def classify_conveyor_infrastructure_fault(exc: BaseException) -> str:
    if not isinstance(exc, OSError):
        return ""
    errno_value = getattr(exc, "errno", None)
    message = " ".join(str(part) for part in getattr(exc, "args", ()) if part is not None).lower()
    filename = str(getattr(exc, "filename", "") or "").replace("\\", "/").lower()
    combined = f"{message} {filename}"
    if errno_value == 5 and (
        "input/output error" in combined
        or "operator_state" in combined
        or "/run/desktop/mnt/host" in combined
    ):
        return INFRASTRUCTURE_FAULT_KIND_DOCKER_BIND_MOUNT_IO
    if errno_value == 17 and "/run/desktop/mnt/host" in combined and "file exists" in combined:
        return INFRASTRUCTURE_FAULT_KIND_DOCKER_BIND_MOUNT_IO
    if "/run/desktop/mnt/host" in combined and "mkdir" in combined and "file exists" in combined:
        return INFRASTRUCTURE_FAULT_KIND_DOCKER_BIND_MOUNT_IO
    return ""


def conveyor_infrastructure_fault_payload(
    exc: BaseException,
    *,
    route: str,
    stale_payload: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    fault_kind = classify_conveyor_infrastructure_fault(exc)
    if not fault_kind:
        raise exc
    payload: dict[str, Any] = {
        "ok": False,
        "schema_name": "NovaliInfrastructureFault",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "route": str(route or ""),
        "infrastructure_fault": True,
        "fault_kind": fault_kind,
        "fault_message": str(exc),
        "recovery_guidance": [
            "Restart Docker Desktop or the Docker Desktop service.",
            "If bind mounts remain unhealthy, run wsl --shutdown and reopen Docker Desktop.",
            "After Docker recovers, restart the novali service with docker compose -f docker-compose.llm.yml up -d novali.",
        ],
        "stale_payload_available": bool(stale_payload),
    }
    if stale_payload:
        payload["stale_payload"] = dict(stale_payload)
    if "overnight-readiness" in str(route or ""):
        payload.update(
            {
                "ready": False,
                "blockers": [fault_kind],
                "warnings": [],
                "directive_statuses": [],
                "recommended_actions": list(payload["recovery_guidance"]),
            }
        )
    return payload
