class ConveyorValidationError(ValueError):
    pass


def _utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def _parse_utc_time(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _safe_slug(value: str, *, fallback: str) -> str:
    slug = re.sub(r"[^a-zA-Z0-9_-]+", "-", str(value or "").strip().lower()).strip("-")
    return (slug or fallback)[:60]


def _record_id(prefix: str, *parts: str) -> str:
    seed = "::".join(str(part or "") for part in parts if str(part or ""))
    if seed:
        digest = uuid.uuid5(uuid.NAMESPACE_URL, seed).hex[:12]
    else:
        digest = uuid.uuid4().hex[:12]
    return f"{prefix}-{digest}"


