def _acquire_directive_spawn_lock(
    operator_root: str | Path,
    directive_id: str,
    *,
    owner: str,
) -> tuple[bool, Path, str]:
    lock_path = _directive_spawn_lock_path(operator_root, directive_id)
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    now_dt = datetime.now(timezone.utc)
    if lock_path.exists():
        lock_payload = _read_json(lock_path / "owner.json")
        stamp = _parse_utc_time(
            str(lock_payload.get("created_at", "") or lock_payload.get("updated_at", "") or "")
        )
        if stamp is not None and (now_dt - stamp).total_seconds() >= SPAWN_RESERVATION_STALE_SECONDS:
            try:
                shutil.rmtree(lock_path)
            except OSError:
                return False, lock_path, "directive_spawn_lock_active"
        else:
            return False, lock_path, "directive_spawn_lock_active"
    try:
        lock_path.mkdir()
    except FileExistsError:
        return False, lock_path, "directive_spawn_lock_active"
    except OSError:
        return False, lock_path, "directive_spawn_lock_unavailable"
    _write_json(
        lock_path / "owner.json",
        {
            "directive_id": str(directive_id or ""),
            "owner": str(owner or ""),
            "created_at": _utc_now(),
            "grants_execution_authority": False,
        },
    )
    return True, lock_path, ""


def _release_directive_spawn_lock(lock_path: Path) -> None:
    try:
        if lock_path.exists():
            shutil.rmtree(lock_path)
    except OSError:
        pass


def _read_json(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _write_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    body = json.dumps(dict(payload), indent=2, sort_keys=True) + "\n"
    last_error: OSError | None = None
    try:
        retry_count = max(4, int(os.environ.get("NOVALI_JSON_WRITE_REPLACE_RETRY_COUNT", "12") or "12"))
    except (TypeError, ValueError):
        retry_count = 12
    for attempt in range(retry_count):
        temp_path = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
        try:
            with temp_path.open("w", encoding="utf-8", newline="\n") as handle:
                handle.write(body)
                handle.flush()
                os.fsync(handle.fileno())
            temp_path.replace(path)
            return
        except PermissionError as exc:
            last_error = exc
            if attempt >= retry_count - 1:
                raise
            time.sleep(min(0.5, 0.05 * (attempt + 1)))
        finally:
            try:
                if temp_path.exists():
                    temp_path.unlink()
            except OSError:
                pass
    if last_error is not None:
        raise last_error


def _append_ledger(operator_root: str | Path, name: str, payload: Mapping[str, Any]) -> None:
    path = _ledgers_root(operator_root) / f"{name}.jsonl"
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(dict(payload), sort_keys=True) + "\n")


def _latest_return_decision(operator_root: str | Path, return_packet_id: str) -> dict[str, Any]:
    packet_id = str(return_packet_id or "").strip()
    if not packet_id:
        return {}
    path = _ledgers_root(operator_root) / "return_decisions.jsonl"
    if not path.exists():
        return {}
    latest: dict[str, Any] = {}
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return {}
    for line in lines:
        if not line.strip():
            continue
        try:
            row = json.loads(line)
        except json.JSONDecodeError:
            continue
        if str(dict(row).get("return_packet_id", "") or "") == packet_id:
            latest = dict(row)
    return latest


def _load_items(root: Path) -> list[dict[str, Any]]:
    if not root.exists():
        return []
    rows: list[dict[str, Any]] = []
    for path in sorted(root.glob("*.json")):
        payload = _read_json(path)
        if payload:
            rows.append(payload)
    return rows


