def _count_by_state(rows: Iterable[Mapping[str, Any]], field: str = "state") -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        state = str(row.get(field, "") or "unknown")
        counts[state] = counts.get(state, 0) + 1
    return counts


def _read_file_manifest(path: Path) -> dict[str, Any]:
    if not path.exists() or not path.is_file():
        return {}
    data = path.read_bytes()
    manifest = {
        "artifact_name": path.name,
        "source_path": str(path),
        "size_bytes": len(data),
        "modified_at_epoch": round(path.stat().st_mtime, 6),
        "sha256": hashlib.sha256(data).hexdigest(),
    }
    manifest["hash"] = manifest["sha256"]
    if path.suffix == ".json":
        try:
            payload = json.loads(data.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            payload = {}
        if isinstance(payload, Mapping):
            gates = {
                str(value)
                for value in _walk_json_values(payload)
                if str(value) == "execution_gated_by_operator_approval"
            }
            if gates:
                manifest["execution_gate"] = "execution_gated_by_operator_approval"
    return manifest


def _walk_json_values(payload: Any) -> Iterable[Any]:
    if isinstance(payload, Mapping):
        for value in payload.values():
            yield from _walk_json_values(value)
    elif isinstance(payload, list):
        for item in payload:
            yield from _walk_json_values(item)
    else:
        yield payload


def _quality_rows(payload: Mapping[str, Any], keys: Iterable[str]) -> list[dict[str, Any]]:
    for key in keys:
        value = payload.get(key)
        if isinstance(value, list):
            return [dict(item) for item in value if isinstance(item, Mapping)]
    return []


THRESHOLD_FIELD_NAMES = {
    "acceptance_threshold",
    "acceptance_thresholds",
    "pass_fail_threshold",
    "pass_fail_thresholds",
    "threshold",
    "latency_budget",
    "latency_budget_ms",
    "fixture_pass_rate",
    "confidence_range",
    "unsafe_rejection_count",
}


def _json_contains_threshold(payload: Any) -> bool:
    if isinstance(payload, Mapping):
        for key, value in payload.items():
            key_text = str(key or "").lower()
            if key_text in THRESHOLD_FIELD_NAMES and str(value or "").strip():
                return True
            if key_text.endswith("threshold") and str(value or "").strip():
                return True
            if _json_contains_threshold(value):
                return True
    elif isinstance(payload, list):
        return any(_json_contains_threshold(item) for item in payload)
    return False


def _row_has_expected_files(row: Mapping[str, Any]) -> bool:
    return bool(
        list(row.get("expected_files", []) or [])
        or str(row.get("expected_file", "") or "").strip()
        or list(row.get("fixture_files", []) or [])
    )


def _row_has_expected_outputs(row: Mapping[str, Any]) -> bool:
    return bool(
        list(row.get("expected_outputs", []) or [])
        or str(row.get("expected_output", "") or "").strip()
        or list(row.get("named_outputs", []) or [])
        or list(row.get("outputs", []) or [])
        or str(row.get("module_output", "") or "").strip()
    )


def _fixture_name_is_generic(name: str) -> bool:
    normalized = str(name or "").strip().lower()
    return bool(re.fullmatch(r"(?:fixture|test_fixture|validation_fixture)[_-]?\d+", normalized))


def _artifact_quality_payload(path: Path) -> tuple[str, dict[str, Any]]:
    if not path.exists() or not path.is_file():
        return "", {}
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return "", {}
    payload: dict[str, Any] = {}
    if path.suffix == ".json":
        try:
            parsed = json.loads(text)
        except json.JSONDecodeError:
            parsed = {}
        if isinstance(parsed, Mapping):
            payload = dict(parsed)
    return text, payload


def _schema_followup_skeleton_value(field: str) -> Any:
    normalized = str(field or "").strip()
    if normalized == "acceptance_thresholds":
        return [
            {
                "metric": "operator_review_acceptance",
                "threshold": "defined before prototype execution",
                "evidence_required": True,
            }
        ]
    if normalized == "go_no_go":
        return {
            "go": ["operator approves review-only prototype package"],
            "no_go": ["unsupported claim or unsafe execution request remains"],
        }
    if normalized == "expected_files":
        return ["operator_review_artifact_to_be_supplied_by_child"]
    if normalized == "expected_outputs":
        return ["reviewable prototype evidence package"]
    if normalized == "non_clinical":
        return True
    if normalized == "unsafe_rejection_count":
        return {
            "threshold": 0,
            "scope": "unsafe or non-review-only execution requests",
        }
    if normalized == "execution_gated_by_operator_approval":
        return True
    if normalized == "robotics_interaction_flow":
        return [
            {
                "step": "operator_review",
                "boundary": "non-clinical, simulation-only, deny-all network child workspace",
            }
        ]
    if normalized == "hardware_abstraction_layer_id":
        return "operator_review_hal_id_required"
    if normalized == "device_capability_manifest_ref":
        return "operator_review_device_manifest_required"
    if normalized == "non_invasive_boundary":
        return "non-invasive review boundary required before prototype execution"
    return "operator_review_required"


def _schema_followup_skeleton(fields: Iterable[Any]) -> dict[str, Any]:
    skeleton: dict[str, Any] = {}
    for field in fields:
        key = str(field or "").strip()
        if key and key not in skeleton:
            skeleton[key] = _schema_followup_skeleton_value(key)
    if "execution_gated_by_operator_approval" in skeleton:
        skeleton["execution_gated_by_operator_approval"] = True
    return skeleton


def _manifest_schema_resonance_followup_record(
    child: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    active_target = _active_child_target_artifact(child, manifest)
    schema_resonance = dict(manifest.get("schema_resonance", {}) or {})
    schema_target = str(schema_resonance.get("target_artifact", "") or active_target)
    missing_fields = [
        str(item).strip()
        for item in list(schema_resonance.get("required_fields_missing", []) or [])
        if str(item).strip()
    ]
    required_fields = [
        str(item).strip()
        for item in list(schema_resonance.get("required_fields", []) or missing_fields)
        if str(item).strip()
    ]
    try:
        score = float(schema_resonance.get("score", 1.0) or 0.0)
    except (TypeError, ValueError):
        score = 0.0
    target_matches = bool(active_target and (not schema_target or schema_target == active_target))
    followup_required = bool(target_matches and score < 1.0 and missing_fields)
    return {
        "child_run_id": str(child.get("child_run_id", "") or ""),
        "directive_id": str(child.get("directive_id", "") or ""),
        "target_artifact": active_target,
        "progress_target_artifact": "",
        "schema_resonance_followup_required": followup_required,
        "schema_resonance_score": score,
        "required_top_level_fields": required_fields,
        "missing_top_level_fields": missing_fields,
        "artifact_top_level_schema_skeleton": _schema_followup_skeleton(required_fields),
        "progress_closed_failed_gates": [],
        "progress_remaining_failed_gates": [],
        "followup_source": "manifest_active_target_schema_resonance",
    }


def _schema_resonance_score_for_target(manifest: Mapping[str, Any], target_artifact: str) -> float:
    schema_resonance = dict(manifest.get("schema_resonance", {}) or {})
    schema_target = str(schema_resonance.get("target_artifact", "") or target_artifact)
    if target_artifact and schema_target and schema_target != target_artifact:
        return 1.0
    try:
        return float(schema_resonance.get("score", 1.0) or 0.0)
    except (TypeError, ValueError):
        return 0.0


def _schema_resonance_missing_fields_for_target(
    manifest: Mapping[str, Any],
    target_artifact: str,
) -> list[str]:
    schema_resonance = dict(manifest.get("schema_resonance", {}) or {})
    schema_target = str(schema_resonance.get("target_artifact", "") or target_artifact)
    if target_artifact and schema_target and schema_target != target_artifact:
        return []
    return [
        str(item).strip()
        for item in list(schema_resonance.get("required_fields_missing", []) or [])
        if str(item).strip()
    ]


def _strip_context_only_artifact_fields(value: Any) -> Any:
    if isinstance(value, Mapping):
        cleaned: dict[str, Any] = {}
        for key, nested in value.items():
            normalized = str(key or "").strip().lower()
            if normalized in ARTIFACT_CONTEXT_ONLY_KEYS:
                continue
            cleaned[str(key)] = _strip_context_only_artifact_fields(nested)
        return cleaned
    if isinstance(value, list):
        return [_strip_context_only_artifact_fields(item) for item in value]
    return value


def _campaign_artifact_body_text(operator_root: str | Path, directive_id: str, artifact_name: str) -> str:
    if not directive_id or not artifact_name:
        return ""
    chunks: list[str] = []
    for root in (
        _campaign_drafts_root(operator_root, directive_id),
        _campaign_canonical_root(operator_root, directive_id),
    ):
        path = root / artifact_name
        if not path.exists() or not path.is_file():
            continue
        try:
            raw = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        if path.suffix.lower() == ".json":
            try:
                parsed = json.loads(raw)
            except json.JSONDecodeError:
                chunks.append(raw)
                continue
            chunks.append(json.dumps(_strip_context_only_artifact_fields(parsed), sort_keys=True))
        else:
            chunks.append(raw)
    return "\n".join(chunks).lower()


def _operator_intent_text(directive: Mapping[str, Any], packet: Mapping[str, Any]) -> str:
    metadata = dict(directive.get("metadata", {}) or {})
    parts = [
        str(directive.get("directive_text", "") or ""),
        str(directive.get("title", "") or ""),
        str(directive.get("directive_title", "") or ""),
    ]
    for source in (directive, metadata, packet):
        for field in OPERATOR_INTENT_FIELDS:
            value = source.get(field, "") if isinstance(source, Mapping) else ""
            if value:
                parts.append(str(value))
    return " ".join(parts).lower()


def _has_genetics_intent(text: str) -> bool:
    lowered = str(text or "").lower()
    return any(term in lowered for term in ("genetic", "genetics", "genomic", "genome"))


def _has_nanotechnology_intent(text: str) -> bool:
    lowered = str(text or "").lower()
    return any(term in lowered for term in ("nanotechnology", "nanotech", "nano-technology", "nano"))


def _operator_intent_materialization_micro_adjustment(
    operator_root: str | Path,
    directive: Mapping[str, Any],
    packet: Mapping[str, Any],
) -> dict[str, Any]:
    directive_id = str(directive.get("directive_id", "") or packet.get("directive_id", "") or "")
    intent_text = _operator_intent_text(directive, packet)
    if not (_has_genetics_intent(intent_text) and _has_nanotechnology_intent(intent_text)):
        return {"required": False}
    required_artifacts = [
        "subsystem_matrix.json",
        "claim_evidence_register.json",
        "dependency_matrix.json",
        "interface_specifications.json",
        "validation_fixtures.json",
        "risk_controls.json",
        "technical_documentation.md",
    ]
    missing = [
        artifact
        for artifact in required_artifacts
        if not (
            _has_genetics_intent(_campaign_artifact_body_text(operator_root, directive_id, artifact))
            and _has_nanotechnology_intent(_campaign_artifact_body_text(operator_root, directive_id, artifact))
        )
    ]
    if not missing:
        return {"required": False}
    target = "subsystem_matrix.json" if "subsystem_matrix.json" in missing else missing[0]
    return {
        "required": True,
        "kind": "operator_intent_not_materialized",
        "target_artifact": target,
        "reasons": ["operator_intent_not_materialized"],
        "missing_artifact_body_updates": missing,
        "feedback": (
            "Operator intent was echoed in context but not materialized in artifact bodies. Continue the campaign "
            "until subsystem_matrix.json, claim_evidence_register.json, dependency_matrix.json, "
            "interface_specifications.json, validation_fixtures.json, risk_controls.json, and "
            "technical_documentation.md contain concrete genetics and nanotechnology rows, claims, dependencies, "
            "interfaces, fixtures, and risk controls."
        ),
    }


def _canonical_promotion_micro_adjustment(campaign_manifest: Mapping[str, Any]) -> dict[str, Any]:
    manifest = dict(campaign_manifest or {})
    promotion = dict(manifest.get("promotion_mismatch", {}) or {})
    promotion_state = str(promotion.get("state", "") or "").strip()
    schema_resonance = dict(manifest.get("schema_resonance", {}) or {})
    target = str(
        promotion.get("target_artifact", "")
        or schema_resonance.get("target_artifact", "")
        or dict(manifest.get("draft_delta_quality", {}) or {}).get("target_artifact", "")
        or manifest.get("next_unresolved_gate_artifact", "")
        or manifest.get("weakest_failed_artifact", "")
        or ""
    ).strip()
    if target not in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER:
        return {"required": False}
    missing_fields = _schema_resonance_missing_fields_for_target(manifest, target)
    canonical_artifact = dict(dict(manifest.get("canonical_artifacts", {}) or {}).get(target, {}) or {})
    canonical_failed_gates = [
        str(item).strip()
        for item in list(
            promotion.get("canonical_failed_gates", [])
            or canonical_artifact.get("failed_quality_gates", [])
            or manifest.get("failed_quality_gates", [])
            or []
        )
        if str(item).strip()
    ]
    gate_field_map = {
        "missing_hardware_abstraction_layer_id": "hardware_abstraction_layer_id",
        "missing_device_capability_manifest": "device_capability_manifest_ref",
        "missing_non_invasive_boundary": "non_invasive_boundary",
        "missing_acceptance_thresholds": "acceptance_thresholds",
    }
    for gate in canonical_failed_gates:
        mapped = gate_field_map.get(gate)
        if mapped:
            _append_unique(missing_fields, mapped)
    manifest_text = json.dumps(manifest, sort_keys=True, default=str).lower()
    if target == "interface_specifications.json" and any(
        marker in manifest_text for marker in ("hardware", "hal", "non-invasive", "non_invasive")
    ):
        for field in (
            "hardware_abstraction_layer_id",
            "device_capability_manifest_ref",
            "non_invasive_boundary",
        ):
            _append_unique(missing_fields, field)
    try:
        resonance_score = float(schema_resonance.get("score", 1.0) or 0.0)
    except (TypeError, ValueError):
        resonance_score = 0.0
    blocked_state = promotion_state in {"draft_ready_canonical_blocked", "schema_resonance_gap"}
    blocked_by_schema = bool(missing_fields and resonance_score < 1.0)
    if not (blocked_state or blocked_by_schema):
        return {"required": False}
    return {
        "required": True,
        "kind": "canonical_promotion_blocked",
        "target_artifact": target,
        "reasons": ["canonical_promotion_blocked"],
        "missing_top_level_fields": missing_fields,
        "canonical_failed_gates": canonical_failed_gates,
        "schema_resonance_score": resonance_score,
        "promotion_mismatch_state": promotion_state,
        "feedback": (
            f"Draft depth exists for {target}, but canonical/schema placement still blocks promotion. Continue with "
            "a focused canonicalization pass: echo the missing evaluator keys as top-level artifact fields, preserve "
            "the row-level detail, and clear the canonical failed gates before returning for operator review."
        ),
    }


