def _hardware_prototype_requested(text: str) -> bool:
    lowered = str(text or "").lower()
    return bool(
        ("hardware" in lowered and "prototype" in lowered)
        or ("hardware" in lowered and "packet" in lowered)
        or ("hardware" in lowered and "interface" in lowered)
        or ("hardware" in lowered and "readiness" in lowered)
        or "real-world prototype" in lowered
        or "real world prototype" in lowered
        or "bench prototype" in lowered
        or "magnetic forge" in lowered
        or "forge bench" in lowered
        or "external hardware" in lowered
        or "hardware interface" in lowered
        or "hardware packet" in lowered
        or "hardware build-ready" in lowered
        or "hardware build ready" in lowered
        or "hardware build packet" in lowered
    )


def _hardware_artifact_text(
    operator_root: str | Path,
    directive_id: str,
    packet: Mapping[str, Any],
    artifact_name: str,
) -> str:
    packet_payload = _read_packet_artifact_json(packet, artifact_name)
    if packet_payload:
        return json.dumps(packet_payload, sort_keys=True, default=str)
    return _campaign_artifact_body_text(operator_root, directive_id, artifact_name)


def _hardware_json_rows(
    operator_root: str | Path,
    directive_id: str,
    packet: Mapping[str, Any],
    artifact_name: str,
    keys: Iterable[str],
) -> list[dict[str, Any]]:
    payload = _read_packet_artifact_json(packet, artifact_name)
    if not payload:
        payload = _campaign_artifact_json_payload(operator_root, directive_id, artifact_name)
    return _quality_rows(payload, keys)


def _hardware_text_has_any(text: str, terms: Iterable[str]) -> bool:
    lowered = str(text or "").lower()
    return any(str(term).lower() in lowered for term in terms)


def _campaign_artifact_json_payload(
    operator_root: str | Path,
    directive_id: str,
    artifact_name: str,
) -> dict[str, Any]:
    for root in (
        _campaign_drafts_root(operator_root, directive_id),
        _campaign_canonical_root(operator_root, directive_id),
    ):
        payload = _read_json(root / artifact_name)
        if payload:
            return payload
    return {}


def _campaign_materialized_file_exists(
    operator_root: str | Path,
    directive_id: str,
    relative_path: str,
) -> bool:
    rel = str(relative_path or "").strip().replace("\\", "/")
    if not rel or rel.startswith("/") or ".." in Path(rel).parts:
        return False
    roots: list[Path] = [
        _campaign_canonical_root(operator_root, directive_id),
        _campaign_drafts_root(operator_root, directive_id),
    ]
    for child in _load_items(_children_root(operator_root)):
        if str(child.get("directive_id", "") or "") != str(directive_id or ""):
            continue
        roots.extend(_child_workspace_candidates(child))
    for root in roots:
        candidate = root / rel
        try:
            candidate.resolve().relative_to(root.resolve())
        except (OSError, ValueError):
            continue
        if candidate.is_file():
            return True
    return False


