def _directive_family_from_text(text: Any) -> str:
    lowered = str(text or "").lower()
    if "full dive" in lowered or "full_dive" in lowered or "neural" in lowered or "bci" in lowered:
        return "full_dive"
    if "magnetic forge" in lowered or "magnetic_forge" in lowered or "forge" in lowered:
        return "magnetic_forge"
    return "build_grade_directive"


