def _append_unique_text(values: list[str], candidate: Any) -> None:
    text = str(candidate or "").strip()
    if not text:
        return
    lowered = {str(item).strip().lower() for item in values}
    if text.lower() not in lowered:
        values.append(text)


def _support_contract_required_fields(
    directive_family: str,
    target_artifact: str,
) -> list[str]:
    family = str(directive_family or "build_grade_directive")
    target = str(target_artifact or "")
    fields: list[str] = []
    for candidate_family in (family, "build_grade_directive"):
        for item in SUPPORT_OBLIGATION_FIELD_CONTRACTS.get(candidate_family, {}).get(target, ()):
            _append_unique_text(fields, item)
    return fields


