def _source_backed_support_rows_for_requested_coverage(
    support: Mapping[str, Any],
    provider_request: Mapping[str, Any] | None = None,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()

    def _add_row(raw_row: Any) -> None:
        if not isinstance(raw_row, Mapping):
            return
        row = dict(raw_row)
        if bool(row.get("grants_execution_authority", False)):
            return
        requested_row_id = str(row.get("requested_row_id", "") or "").strip()
        if not requested_row_id:
            return
        evidence_ref = str(row.get("evidence_ref", "") or "").strip()
        source_ref = str(
            row.get("source_url", "")
            or row.get("datasheet_url", "")
            or row.get("citation_ref", "")
            or row.get("source_hint", "")
            or row.get("source_path", "")
            or row.get("design_reduction_provenance", "")
            or ""
        ).strip()
        if not evidence_ref or not source_ref:
            return
        row_id = str(
            row.get("row_id", "")
            or row.get("support_row_id", "")
            or row.get("engineering_evidence_row_id", "")
            or requested_row_id
        ).strip()
        key = f"{requested_row_id}:{row_id}:{evidence_ref}"
        if key in seen:
            return
        seen.add(key)
        rows.append(row)

    for source in (support, provider_request or {}):
        if not isinstance(source, Mapping):
            continue
        for key in (
            "accepted_field_lane_rows",
            "child_support_rows",
            "support_rows",
            "rows",
        ):
            for raw_row in list(source.get(key, []) or []):
                _add_row(raw_row)
    for pack_key in ("satisfied_pack", "satisfied_support_pack", "support_pack"):
        pack = support.get(pack_key)
        if not isinstance(pack, Mapping):
            continue
        for key in ("child_support_rows", "rows", "support_rows"):
            for raw_row in list(pack.get(key, []) or []):
                _add_row(raw_row)
    return rows


def _source_backed_requested_row_coverage_for_support(
    support: Mapping[str, Any],
    *,
    provider_request: Mapping[str, Any],
    requested_rows: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    target_artifact = str(
        support.get("target_artifact", "") or provider_request.get("target_artifact", "") or ""
    )
    support_rows = _source_backed_support_rows_for_requested_coverage(
        support,
        provider_request,
    )
    coverage = assess_requested_row_coverage(
        support_rows,
        requested_rows=requested_rows,
        target_artifact=target_artifact,
    )
    coverage["source_backed_support_row_count"] = len(support_rows)
    coverage["source_backed_requested_row_coverage_enforced"] = True
    return coverage


def _copy_provider_quality_fields_to_support(
    support: Mapping[str, Any],
    digest: Mapping[str, Any],
    *,
    failed: bool,
    operator_root: str | Path | None = None,
    context: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    updated = dict(support)
    for key in (
        "provider_output_quality_state",
        "provider_output_quality_assessment_id",
        "source_plan_id",
        "source_candidate_count",
        "accepted_child_support_row_count",
        "rejected_child_support_row_count",
        "provider_rejected_row_reasons",
        "row_acceptance_ratio",
        "field_coverage_ratio",
        "source_grounding_state",
        "domain_match_state",
        "placeholder_rejection_count",
        "wrong_target_rejection_count",
        "provider_field_lane_request",
        "provider_field_lane_request_id",
        "requested_rows",
        "requested_row_count",
        "accepted_requested_row_ids",
        "rejected_requested_rows",
        "uncovered_requested_row_ids",
        "source_acquisition_from_design_row_ids",
        "accepted_field_lane_rows",
        "rejected_field_lane_rows",
        "field_lane_uncovered_fields",
        "field_lane_uncovered_roles",
        "field_lane_workbench_state",
    ):
        if key in digest:
            value = digest.get(key)
            updated[key] = list(value) if isinstance(value, list) else value
    source_plan = digest.get("source_plan")
    if isinstance(source_plan, Mapping):
        updated["source_plan"] = {
            "schema_name": str(source_plan.get("schema_name", "") or ""),
            "source_plan_id": str(source_plan.get("source_plan_id", "") or ""),
            "status": str(source_plan.get("status", "") or ""),
            "target_artifact": str(source_plan.get("target_artifact", "") or ""),
            "source_candidate_count": int(source_plan.get("source_candidate_count", 0) or 0),
            "grants_execution_authority": False,
        }
    if failed and str(digest.get("provider_output_quality_state", "") or "") == "rejected":
        failure_count = int(updated.get("provider_output_quality_failure_count", 0) or 0) + 1
        updated["provider_output_quality_failure_count"] = failure_count
        if failure_count >= 2:
            updated["support_provider_quality_blocker"] = "repeated_provider_quality_failure"
            updated["next_support_recovery_action"] = "narrow_research_source_lanes"
            if operator_root is not None and context is not None:
                frame = _record_research_problem_frame(
                    operator_root,
                    support=updated,
                    context=context,
                    digest=digest,
                )
                updated["research_problem_frame_id"] = str(frame.get("research_problem_frame_id", "") or "")
                updated["source_obligation_count"] = int(frame.get("source_obligation_count", 0) or 0)
                updated["blocked_source_lanes"] = list(frame.get("blocked_source_lanes", []) or [])
                _record_support_research_quality_assessment(
                    operator_root,
                    support=updated,
                    context=context,
                    digest=digest,
                    frame=frame,
                )
    elif not failed and str(digest.get("provider_output_quality_state", "") or "") == "accepted":
        updated["provider_output_quality_failure_count"] = 0
        updated["support_provider_quality_blocker"] = ""
        updated["next_support_recovery_action"] = "materialize_consumable_support_rows"
    return updated


def _support_row_spec_value_map(row: Mapping[str, Any]) -> dict[str, str]:
    values: dict[str, str] = {}
    raw_spec_values = row.get("spec_values") or row.get("concrete_spec_values") or {}
    if isinstance(raw_spec_values, Mapping):
        for key, value in raw_spec_values.items():
            text = str(value or "").strip()
            if text:
                values[str(key or "").strip()] = text
    elif isinstance(raw_spec_values, (list, tuple, set)):
        for item in raw_spec_values:
            text = str(item or "").strip()
            if not text:
                continue
            if "=" in text:
                key, value = text.split("=", 1)
            elif ":" in text:
                key, value = text.split(":", 1)
            else:
                continue
            if str(key or "").strip() and str(value or "").strip():
                values[str(key or "").strip()] = str(value or "").strip()
    for key, value in row.items():
        text = str(value or "").strip()
        if text and key not in values:
            values[str(key)] = text
    return values


def _linked_risk_refs_from_support_rows(rows: Iterable[Mapping[str, Any]]) -> list[str]:
    refs: list[str] = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        values = _support_row_spec_value_map(row)
        for key, value in values.items():
            normalized = normalize_support_field_name(key)
            if normalized != "linked_risk_control_ref":
                continue
            for part in re.split(r"[,;|]+", str(value or "")):
                ref = part.strip()
                if ref and ref not in refs:
                    refs.append(ref)
    return refs


def _support_request_state_value(support: Mapping[str, Any]) -> str:
    state = str(support.get("state", "") or "").strip()
    support_state = str(support.get("support_state", "") or "").strip()
    terminal_states = {"failed", "rejected", "superseded", "cancelled"}
    if support_state in terminal_states:
        return support_state
    if state in terminal_states:
        return state
    if state in {
        "commercial_source_acquisition_required",
        "source_backed_rows_required",
        "pending_operator_review",
        "blocked_for_support",
    }:
        return state
    return support_state or state


def _set_support_request_state(support: dict[str, Any], state: str) -> None:
    support["support_state"] = state
    support["state"] = state


