def _technical_documentation_depth_requested_rows(
    *,
    directive_id: str,
    failed_gates: Iterable[Any],
) -> list[dict[str, Any]]:
    gate_rows = {
        "missing_named_modules": {
            "requested_row_id": "technical_documentation_named_modules",
            "target_row_id": "technical_documentation.md#named_modules",
            "required_fields": [
                "named_modules",
                "module_responsibilities",
                "artifact_handoffs",
                "source_evidence_refs",
            ],
            "source_query_hint": (
                "directive-specific named modules, responsibilities, handoff files, "
                "and evidence refs for technical documentation"
            ),
            "source_acceptance_contract": (
                "Return one review-only technical-documentation support row naming concrete modules, "
                "their responsibilities, artifact handoffs, and evidence refs."
            ),
        },
        "missing_handoff_acceptance_thresholds": {
            "requested_row_id": "technical_documentation_handoff_acceptance_thresholds",
            "target_row_id": "technical_documentation.md#handoff_acceptance_thresholds",
            "required_fields": [
                "handoff_acceptance_thresholds",
                "expected_files",
                "expected_outputs",
                "validation_fixture_refs",
                "go_no_go_trace",
            ],
            "source_query_hint": (
                "acceptance thresholds, expected files and outputs, validation fixtures, "
                "and go/no-go trace for implementation handoff documentation"
            ),
            "source_acceptance_contract": (
                "Return one review-only technical-documentation support row with measurable "
                "handoff acceptance thresholds, expected files, expected outputs, fixture refs, "
                "and go/no-go trace."
            ),
        },
        "no_buildable_delta": {
            "requested_row_id": "technical_documentation_buildable_delta",
            "target_row_id": "technical_documentation.md#buildable_delta",
            "required_fields": [
                "buildable_delta_summary",
                "artifact_handoffs",
                "risk_control_refs",
                "validation_fixture_refs",
                "source_evidence_refs",
                "go_no_go_trace",
            ],
            "source_query_hint": (
                "buildable delta summary linking BOM, risk controls, validation fixtures, "
                "documentation handoffs, and evidence refs"
            ),
            "source_acceptance_contract": (
                "Return one review-only technical-documentation support row explaining the concrete "
                "dossier delta and linking BOM, risk-control, fixture, and source evidence refs."
            ),
        },
    }
    normalized_gates = [
        str(item or "").strip()
        for item in list(failed_gates or [])
        if str(item or "").strip()
    ]
    if not normalized_gates:
        normalized_gates = [
            "missing_named_modules",
            "missing_handoff_acceptance_thresholds",
            "no_buildable_delta",
        ]
    requested: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    for gate in normalized_gates:
        template = gate_rows.get(gate)
        if template is None:
            slug = _safe_slug(gate, fallback="technical-documentation-depth-gap")
            template = {
                "requested_row_id": f"technical_documentation_{slug.replace('-', '_')}",
                "target_row_id": f"technical_documentation.md#{slug}",
                "required_fields": _technical_documentation_depth_required_fields(),
                "source_query_hint": f"{gate} technical documentation depth evidence",
                "source_acceptance_contract": (
                    "Return one review-only technical-documentation support row that closes the named "
                    "quality gate with concrete handoffs, thresholds, evidence refs, and go/no-go trace."
                ),
            }
        requested_id = str(template.get("requested_row_id", "") or "").strip()
        if not requested_id or requested_id in seen_ids:
            continue
        seen_ids.add(requested_id)
        row = dict(template)
        row.update(
            {
                "target_artifact": "technical_documentation.md",
                "required_gate": gate,
                "directive_id": directive_id,
                "commercial_component_source_required": False,
                "technical_documentation_depth_support_required": True,
                "grants_execution_authority": False,
            }
        )
        requested.append(row)
    return requested


def _ensure_current_technical_documentation_depth_support_request(
    operator_root: str | Path,
    *,
    directive: Mapping[str, Any],
    stale_support: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    directive_id = str(directive.get("directive_id", "") or "").strip()
    if not directive_id:
        return {"ok": False, "reason": "missing_directive_id", "support_request": {}}
    metadata = dict(directive.get("metadata", {}) or {})
    target_artifact = str(
        metadata.get("support_blocker_target_artifact", "")
        or metadata.get("continuous_campaign_latest_target_artifact", "")
        or metadata.get("initial_work_order_target_artifact", "")
        or ""
    ).strip()
    if (
        bool(metadata.get("technical_documentation_depth_plateau_finalized", False))
        or str(directive.get("blocked_reason", "") or "").strip()
        == "technical_documentation_depth_support_required"
        or str(metadata.get("support_blocker_reason", "") or "").strip()
        == "technical_documentation_depth_support_required"
        or str(metadata.get("support_admission_state", "") or "").strip()
        == "technical_documentation_depth_support_required"
    ):
        target_artifact = "technical_documentation.md"
    if target_artifact != "technical_documentation.md":
        return {"ok": False, "reason": "not_technical_documentation_target", "support_request": {}}
    if not (
        bool(metadata.get("technical_documentation_depth_plateau_finalized", False))
        or str(directive.get("blocked_reason", "") or "").strip()
        == "technical_documentation_depth_support_required"
        or str(metadata.get("support_blocker_reason", "") or "").strip()
        == "technical_documentation_depth_support_required"
    ):
        return {"ok": False, "reason": "technical_documentation_depth_not_required", "support_request": {}}
    current_support_id = str(metadata.get("support_request_id", "") or "").strip()
    current_support = _read_json(_support_request_path(operator_root, current_support_id)) if current_support_id else {}
    if (
        current_support
        and str(current_support.get("directive_id", "") or "") == directive_id
        and str(current_support.get("target_artifact", "") or "") == "technical_documentation.md"
        and _support_request_state_value(current_support) not in {"failed", "rejected", "superseded", "cancelled"}
    ):
        return {"ok": False, "reason": "technical_documentation_support_already_current", "support_request": current_support}

    failed_gates = [
        str(item or "").strip()
        for item in list(metadata.get("technical_documentation_depth_plateau_failed_gates", []) or [])
        if str(item or "").strip()
    ]
    requested_rows = _technical_documentation_depth_requested_rows(
        directive_id=directive_id,
        failed_gates=failed_gates,
    )
    requested_row_ids = [
        str(row.get("requested_row_id", "") or "")
        for row in requested_rows
        if str(row.get("requested_row_id", "") or "")
    ]
    support_request_id = str(
        metadata.get("technical_documentation_depth_support_request_id", "") or ""
    ).strip()
    if not support_request_id:
        support_request_id = _record_id(
            "support",
            directive_id,
            "technical_documentation.md",
            "technical-documentation-depth",
        )
    support = _read_json(_support_request_path(operator_root, support_request_id))
    now = _utc_now()
    source_support_id = str(
        current_support_id
        or (stale_support or {}).get("support_request_id", "")
        or ""
    ).strip()
    if support:
        support = dict(support)
    else:
        support = {
            "schema_name": "ConveyorSupportRequest",
            "schema_version": SUPPORT_REQUEST_SCHEMA_VERSION,
            "support_request_id": support_request_id,
            "created_at": now,
        }
    accepted_ids = [
        str(item or "").strip()
        for item in list(support.get("accepted_requested_row_ids", []) or [])
        if str(item or "").strip() in set(requested_row_ids)
    ]
    uncovered_ids = [
        requested_id for requested_id in requested_row_ids if requested_id not in set(accepted_ids)
    ]
    support.update(
        {
            "directive_id": directive_id,
            "target_artifact": "technical_documentation.md",
            "capability": str(
                support.get("capability", "")
                or (stale_support or {}).get("capability", "")
                or "directive_build_grade_synthesis_pack"
            ),
            "requested_pack_family": str(
                support.get("requested_pack_family", "")
                or _support_pack_family(directive_id, "directive_build_grade_synthesis_pack")
            ),
            "requested_tags": list(
                support.get("requested_tags", [])
                or _support_request_tags("directive_build_grade_synthesis_pack")
            ),
            "state": "technical_documentation_depth_support_required",
            "support_state": "technical_documentation_depth_support_required",
            "operator_review_required": True,
            "candidate_ingestion_state": "technical_documentation_depth_support_required",
            "support_recovery_state": "technical_documentation_depth_support_required",
            "support_materialization_state": "waiting_for_technical_documentation_depth_support",
            "support_blocker_reason": "technical_documentation_depth_support_required",
            "technical_documentation_depth_support_required": True,
            "technical_documentation_depth_failed_gates": failed_gates,
            "missing_field_coverage": _technical_documentation_depth_required_fields(),
            "missing_fields": _technical_documentation_depth_required_fields(),
            "requested_rows": requested_rows,
            "requested_row_count": len(requested_rows),
            "accepted_requested_row_ids": accepted_ids,
            "uncovered_requested_row_ids": uncovered_ids,
            "source_support_request_id": source_support_id,
            "support_replaced_by_support_request_id": support_request_id
            if source_support_id and source_support_id != support_request_id
            else "",
            "next_support_recovery_action": "conveyor_support_synthesis_job",
            "current_provider_support_request_id": support_request_id,
            "provider_latest_freshness_state": "current_support_request",
            "grants_execution_authority": False,
            "updated_at": now,
        }
    )
    _write_json(_support_request_path(operator_root, support_request_id), support)

    directive_path = _directive_path(operator_root, directive_id)
    directive_payload = _read_json(directive_path) or dict(directive)
    directive_metadata = dict(directive_payload.get("metadata", {}) or metadata)
    directive_metadata.update(
        {
            "support_request_id": support_request_id,
            "technical_documentation_depth_support_request_id": support_request_id,
            "technical_documentation_depth_support_required": True,
            "technical_documentation_depth_failed_gates": failed_gates,
            "support_blocker_target_artifact": "technical_documentation.md",
            "support_blocker_reason": "technical_documentation_depth_support_required",
            "support_admission_state": "technical_documentation_depth_support_required",
            "support_admission_blocker_reason": "technical_documentation_depth_support_required",
            "initial_work_order_target_artifact": "technical_documentation.md",
            "continuous_campaign_latest_target_artifact": "technical_documentation.md",
            "support_recovery_target_artifact": "technical_documentation.md",
            "support_recovery_state": "technical_documentation_depth_support_required",
            "uncovered_requested_row_ids": uncovered_ids,
            "accepted_requested_row_ids": accepted_ids,
            "support_pointer_role": "technical_documentation_depth_support_request_id",
            "support_pointer_repaired_from_support_request_id": source_support_id
            if source_support_id and source_support_id != support_request_id
            else "",
            "current_provider_support_request_id": support_request_id,
            "provider_latest_freshness_state": "current_support_request",
            "next_support_recovery_action": "conveyor_support_synthesis_job",
        }
    )
    directive_payload["state"] = "blocked_for_support"
    directive_payload["blocked_reason"] = "technical_documentation_depth_support_required"
    directive_payload["metadata"] = directive_metadata
    directive_payload["updated_at"] = now
    _write_json(directive_path, directive_payload)
    provider_request = _provider_field_lane_request_for_support(
        operator_root,
        support=support,
        context=_support_request_directive_context(operator_root, support),
    )
    _persist_current_provider_acquisition_latest(
        operator_root,
        support=support,
        provider_request=provider_request,
        reason="technical_documentation_depth_support_request_repaired",
    )
    _append_ledger(
        operator_root,
        "support_request_events",
        {
            "event": "technical_documentation_depth_support_request_repaired",
            "generated_at": now,
            "support_request_id": support_request_id,
            "source_support_request_id": source_support_id,
            "directive_id": directive_id,
            "target_artifact": "technical_documentation.md",
            "technical_documentation_depth_failed_gates": failed_gates,
            "uncovered_requested_row_ids": uncovered_ids,
            "grants_execution_authority": False,
        },
    )
    return {
        "ok": True,
        "support_request": support,
        "directive": directive_payload,
        "provider_field_lane_request": provider_request,
        "repaired_from_support_request_id": source_support_id,
        "uncovered_requested_row_ids": uncovered_ids,
    }


def _artifact_ref_tail(ref: Any) -> str:
    text = str(ref or "").strip()
    if not text:
        return ""
    text = text.split("#")[-1].strip()
    text = text.split(":")[-1].strip()
    return text


def _validation_fixture_ref(ref: Any) -> str:
    tail = _artifact_ref_tail(ref)
    return f"validation_fixtures.json#{tail}" if tail else ""


def _risk_control_ref(ref: Any) -> str:
    tail = _artifact_ref_tail(ref)
    return f"risk_controls.json#{tail}" if tail else ""


def _fixture_row_identity(row: Mapping[str, Any]) -> str:
    for key in ("fixture_id", "row_id", "id", "name", "target_row_id"):
        tail = _artifact_ref_tail(row.get(key))
        if tail:
            return tail
    return ""


def _row_field_value_present(row: Mapping[str, Any], field: str) -> bool:
    value = row.get(field)
    if isinstance(value, Mapping):
        return any(str(item or "").strip() for item in value.values())
    if isinstance(value, (list, tuple, set)):
        return any(str(item or "").strip() for item in value)
    return bool(str(value or "").strip())


def _risk_control_rows_for_fixture_handoff(
    operator_root: str | Path,
    *,
    directive_id: str,
    support_rows: Iterable[Mapping[str, Any]] = (),
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    campaign_root = _campaign_root(operator_root, directive_id)
    for relative in (
        Path("drafts") / "risk_controls.json",
        Path("canonical") / "risk_controls.json",
        Path("risk_controls.json"),
    ):
        payload = _read_json(campaign_root / relative)
        if not payload:
            continue
        for key in ("controls", "rows", "risks", "items", "artifact_rows"):
            value = payload.get(key)
            if isinstance(value, list):
                rows.extend(dict(item) for item in value if isinstance(item, Mapping))
        if rows:
            break
    for row in support_rows:
        if not isinstance(row, Mapping):
            continue
        if str(row.get("target_artifact", "") or "").strip() != "risk_controls.json":
            continue
        values = _support_row_spec_value_map(row)
        merged = {**values, **dict(row)}
        rows.append(merged)
    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, row in enumerate(rows):
        fixture_ref = (
            row.get("verification_fixture_ref")
            or row.get("validation_fixture_ref")
            or row.get("fixture_ref")
            or row.get("verification_method")
            or ""
        )
        fixture_tail = _artifact_ref_tail(fixture_ref)
        risk_tail = _artifact_ref_tail(
            row.get("control_id")
            or row.get("hazard_id")
            or row.get("target_row_id")
            or row.get("row_id")
            or f"risk_row_{index + 1}"
        )
        key = f"{risk_tail}|{fixture_tail}"
        if fixture_tail and key not in seen:
            seen.add(key)
            deduped.append(row)
    return deduped


def _validation_fixture_rows_by_id(
    operator_root: str | Path,
    *,
    directive_id: str,
) -> dict[str, dict[str, Any]]:
    campaign_root = _campaign_root(operator_root, directive_id)
    for relative in (
        Path("drafts") / "validation_fixtures.json",
        Path("canonical") / "validation_fixtures.json",
        Path("validation_fixtures.json"),
    ):
        payload = _read_json(campaign_root / relative)
        if not payload:
            continue
        rows: list[dict[str, Any]] = []
        for key in ("fixtures", "validation_fixtures", "rows", "items", "artifact_rows"):
            value = payload.get(key)
            if isinstance(value, list):
                rows.extend(dict(item) for item in value if isinstance(item, Mapping))
        if rows:
            return {
                identity: row
                for row in rows
                for identity in [_fixture_row_identity(row)]
                if identity
            }
    return {}


def _fixture_refs_requiring_support(
    operator_root: str | Path,
    *,
    directive_id: str,
    required_fields: Iterable[str],
    risk_rows: Iterable[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    fixture_rows = _validation_fixture_rows_by_id(operator_root, directive_id=directive_id)
    requested: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in risk_rows:
        fixture_ref = (
            row.get("verification_fixture_ref")
            or row.get("validation_fixture_ref")
            or row.get("fixture_ref")
            or row.get("verification_method")
            or ""
        )
        fixture_tail = _artifact_ref_tail(fixture_ref)
        if not fixture_tail or fixture_tail in seen:
            continue
        fixture_row = fixture_rows.get(fixture_tail, {})
        missing_fields = [
            field
            for field in list(required_fields or [])
            if not _row_field_value_present(fixture_row, field)
        ]
        if not missing_fields:
            continue
        seen.add(fixture_tail)
        risk_ref = _risk_control_ref(
            row.get("control_id")
            or row.get("hazard_id")
            or row.get("target_row_id")
            or row.get("row_id")
            or ""
        )
        bom_ref = str(row.get("linked_bom_ref", "") or row.get("bom_ref", "") or "").strip()
        requested.append(
            {
                "fixture_ref": fixture_tail,
                "target_row_id": _validation_fixture_ref(fixture_tail),
                "missing_fields": missing_fields,
                "linked_risk_control_ref": risk_ref,
                "linked_bom_ref": bom_ref,
            }
        )
    return requested


def _prepare_validation_fixture_support_chain_from_risk_controls(
    operator_root: str | Path,
    *,
    support: Mapping[str, Any],
    support_rows: Iterable[Mapping[str, Any]] = (),
) -> tuple[dict[str, Any], dict[str, Any]]:
    updated = dict(support)
    if str(updated.get("target_artifact", "") or "") != "risk_controls.json":
        return updated, {}
    if _support_request_state_value(updated) not in {"satisfied", "accepted", "design_only_reduction"}:
        return updated, {}
    directive_id = str(updated.get("directive_id", "") or "").strip()
    if not directive_id:
        return updated, {}
    directive = _read_json(_directive_path(operator_root, directive_id))
    directive_text = str(
        directive.get("directive_text", "")
        or directive.get("text", "")
        or directive.get("title", "")
        or str(updated.get("directive_family", "") or "")
        or ""
    )
    directive_family = _directive_family_from_text(directive_text)
    fixture_fields = _validation_fixture_support_required_fields(directive_family)
    risk_rows = _risk_control_rows_for_fixture_handoff(
        operator_root,
        directive_id=directive_id,
        support_rows=support_rows,
    )
    missing_fixtures = _fixture_refs_requiring_support(
        operator_root,
        directive_id=directive_id,
        required_fields=fixture_fields,
        risk_rows=risk_rows,
    )
    if not missing_fixtures:
        updated["validation_fixture_support_state"] = "not_required"
        return updated, {}
    capability = str(updated.get("capability", "") or "directive_build_grade_synthesis_pack")
    fixture_support_id = str(
        updated.get("validation_fixture_support_request_id", "")
        or updated.get("current_validation_fixture_support_request_id", "")
        or ""
    ).strip()
    if not fixture_support_id:
        fixture_support_id = _record_id(
            "support",
            directive_id,
            "validation_fixtures.json",
            capability,
            "risk-validation-fixture-chain",
        )
    now = _utc_now()
    requested_rows = [
        {
            "requested_row_id": _record_id(
                "requested-row",
                directive_id,
                "validation_fixtures.json",
                item["target_row_id"],
            ),
            "target_artifact": "validation_fixtures.json",
            "target_row_id": item["target_row_id"],
            "target_fixture_ref": item["fixture_ref"],
            "required_fields": fixture_fields,
            "linked_bom_refs": [item["linked_bom_ref"]] if item["linked_bom_ref"] else [],
            "linked_risk_control_refs": [item["linked_risk_control_ref"]] if item["linked_risk_control_ref"] else [],
            "source_query_hint": (
                f"{item['fixture_ref']} validation fixture equipment wiring calibration "
                "measurement method pass fail thresholds linked BOM risk controls"
            )[:420],
            "source_acceptance_contract": (
                "Return one review-only validation fixture row with equipment, fixture wiring, "
                "calibration steps, measurement method, pass/fail thresholds, linked BOM refs, "
                "linked risk-control refs, and execution gate."
            ),
            "commercial_component_source_required": False,
            "source_backed_fixture_required": True,
            "grants_execution_authority": False,
        }
        for item in missing_fixtures
    ]
    requested_row_ids = [
        str(row.get("requested_row_id", "") or "")
        for row in requested_rows
        if str(row.get("requested_row_id", "") or "")
    ]
    fixture_refs = [item["fixture_ref"] for item in missing_fixtures]
    fixture_support = _read_json(_support_request_path(operator_root, fixture_support_id))
    if fixture_support:
        fixture_support = dict(fixture_support)
        if _support_request_state_value(fixture_support) == "superseded":
            _set_support_request_state(fixture_support, "pending_operator_review")
            fixture_support["operator_review_required"] = True
            fixture_support["candidate_ingestion_state"] = "pending_support"
            fixture_support["support_materialization_state"] = "waiting_for_consumable_support"
            fixture_support["validation_fixture_support_refresh_state"] = "revived_from_superseded_risk_chain"
            for stale_key in ("superseded_at", "superseded_by_support_request_id", "superseded_reason"):
                fixture_support.pop(stale_key, None)
        elif _support_request_state_value(fixture_support):
            _set_support_request_state(fixture_support, _support_request_state_value(fixture_support))
    else:
        fixture_support = {
            "schema_name": "ConveyorSupportRequest",
            "schema_version": SUPPORT_REQUEST_SCHEMA_VERSION,
            "support_request_id": fixture_support_id,
            "state": "pending_operator_review",
            "support_state": "pending_operator_review",
            "operator_review_required": True,
            "directive_id": directive_id,
            "return_packet_id": str(updated.get("return_packet_id", "") or f"support-chain-{directive_id}"),
            "capability": capability,
            "requested_pack_family": _support_pack_family(directive_id, capability),
            "requested_tags": _support_request_tags(capability),
            "target_artifact": "validation_fixtures.json",
            "created_at": now,
            "grants_execution_authority": False,
        }
    fixture_support.update(
        {
            "target_artifact": "validation_fixtures.json",
            "missing_field_coverage": fixture_fields,
            "missing_fields": fixture_fields,
            "required_gates": [
                "validation_fixtures_have_equipment",
                "validation_fixtures_have_wiring_and_calibration",
                "validation_fixtures_link_bom_and_risk_controls",
                "validation_fixtures_have_pass_fail_thresholds",
            ],
            "source_support_request_id": str(updated.get("support_request_id", "") or ""),
            "source_risk_support_request_id": str(updated.get("support_request_id", "") or ""),
            "missing_validation_fixture_refs": fixture_refs,
            "requested_rows": requested_rows,
            "requested_row_count": len(requested_rows),
            "accepted_requested_row_ids": [
                item
                for item in list(fixture_support.get("accepted_requested_row_ids", []) or [])
                if str(item or "").strip() in set(requested_row_ids)
            ],
            "validation_fixture_support_acquisition_state": "incomplete",
            "fixture_support_current_state": _support_request_state_value(fixture_support)
            or "pending_operator_review",
            "candidate_ingestion_state": str(
                fixture_support.get("candidate_ingestion_state", "") or "pending_support"
            ),
            "support_materialization_state": str(
                fixture_support.get("support_materialization_state", "")
                or "waiting_for_consumable_support"
            ),
            "support_blocker_reason": "validation_fixture_source_rows_required",
            "updated_at": now,
            "grants_execution_authority": False,
        }
    )
    accepted_ids = {
        str(item or "").strip()
        for item in list(fixture_support.get("accepted_requested_row_ids", []) or [])
        if str(item or "").strip()
    }
    fixture_support["uncovered_requested_row_ids"] = [
        requested_id for requested_id in requested_row_ids if requested_id not in accepted_ids
    ]
    _write_json(_support_request_path(operator_root, fixture_support_id), fixture_support)
    directive_path = _directive_path(operator_root, directive_id)
    directive_payload = _read_json(directive_path)
    if directive_payload:
        metadata = dict(directive_payload.get("metadata", {}) or {})
        metadata.update(
            {
                "support_request_id": fixture_support_id,
                "current_validation_fixture_support_request_id": fixture_support_id,
                "current_risk_control_support_request_id": str(updated.get("support_request_id", "") or ""),
                "support_blocker_target_artifact": "validation_fixtures.json",
                "support_blocker_reason": "validation_fixture_source_rows_required",
                "initial_work_order_target_artifact": "validation_fixtures.json",
                "continuous_campaign_latest_target_artifact": "validation_fixtures.json",
                "next_linked_artifact_target": "validation_fixtures.json",
                "missing_validation_fixture_refs": fixture_refs,
                "fixture_support_current_state": _support_request_state_value(fixture_support)
                or "pending_operator_review",
            }
        )
        directive_payload["metadata"] = metadata
        directive_payload["state"] = "blocked_for_support"
        directive_payload["updated_at"] = now
        _write_json(directive_path, directive_payload)
    _append_ledger(
        operator_root,
        "support_request_events",
        {
            "event": "validation_fixture_support_requested_from_risk_controls",
            "generated_at": now,
            "support_request_id": fixture_support_id,
            "source_risk_support_request_id": str(updated.get("support_request_id", "") or ""),
            "directive_id": directive_id,
            "target_artifact": "validation_fixtures.json",
            "missing_validation_fixture_refs": fixture_refs,
            "grants_execution_authority": False,
        },
    )
    updated["validation_fixture_support_state"] = "validation_fixture_support_requested"
    updated["validation_fixture_support_request_id"] = fixture_support_id
    updated["current_validation_fixture_support_request_id"] = fixture_support_id
    updated["missing_validation_fixture_refs"] = fixture_refs
    updated["next_linked_artifact_target"] = "validation_fixtures.json"
    return updated, fixture_support


def _prepare_risk_control_support_chain_from_bom_support(
    operator_root: str | Path,
    *,
    support: Mapping[str, Any],
    support_rows: Iterable[Mapping[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    updated = dict(support)
    if str(updated.get("target_artifact", "") or "") != "bill_of_materials.json":
        return updated, {}
    directive_id = str(updated.get("directive_id", "") or "")
    risk_refs = _linked_risk_refs_from_support_rows(support_rows)
    if not directive_id or not risk_refs:
        return updated, {}
    directive = _read_json(_directive_path(operator_root, directive_id))
    directive_text = str(
        directive.get("directive_text", "")
        or directive.get("text", "")
        or directive.get("title", "")
        or ""
    )
    directive_family = _directive_family_from_text(
        directive_text
        or str(updated.get("directive_family", "") or "")
        or str(updated.get("reason", "") or "")
    )
    capability = str(updated.get("capability", "") or "directive_build_grade_synthesis_pack")
    risk_support_id = str(updated.get("risk_control_support_request_id", "") or "").strip()
    if not risk_support_id:
        risk_support_id = _record_id(
            "support",
            directive_id,
            "risk_controls.json",
            capability,
            "bom-risk-control-chain",
        )
    risk_fields = _risk_control_support_required_fields(directive_family)
    now = _utc_now()
    risk_support = _read_json(_support_request_path(operator_root, risk_support_id))
    requested_rows = [
        {
            "requested_row_id": _record_id(
                "requested-row",
                directive_id,
                "risk_controls.json",
                ref,
            ),
            "target_artifact": "risk_controls.json",
            "target_row_id": ref,
            "required_fields": risk_fields,
            "source_query_hint": (
                f"{ref} FMEA hazard failure mode effect severity occurrence detectability "
                "mitigation verification fixture go/no-go criteria"
            )[:420],
            "source_acceptance_contract": (
                "Return one linked FMEA-like risk-control row with hazard ID, failure mode, effect, "
                "severity, occurrence, detectability, mitigation, linked BOM ref, verification fixture "
                "ref, and go/no-go criteria."
            ),
            "commercial_component_source_required": False,
            "grants_execution_authority": False,
        }
        for ref in risk_refs
    ]
    requested_row_ids = [
        str(row.get("requested_row_id", "") or "")
        for row in requested_rows
        if str(row.get("requested_row_id", "") or "")
    ]
    if not risk_support:
        risk_support = {
            "schema_name": "ConveyorSupportRequest",
            "schema_version": SUPPORT_REQUEST_SCHEMA_VERSION,
            "support_request_id": risk_support_id,
            "state": "pending_operator_review",
            "support_state": "pending_operator_review",
            "operator_review_required": True,
            "directive_id": directive_id,
            "return_packet_id": str(updated.get("return_packet_id", "") or f"support-chain-{directive_id}"),
            "capability": capability,
            "requested_pack_family": _support_pack_family(directive_id, capability),
            "requested_tags": _support_request_tags(capability),
            "target_artifact": "risk_controls.json",
            "missing_field_coverage": risk_fields,
            "missing_fields": risk_fields,
            "required_gates": [
                "hardware_fmea_controls",
                "fmea_links_to_bom",
                "fmea_links_to_validation_fixtures",
                "risk_controls_have_go_no_go_criteria",
            ],
            "source_support_request_id": str(updated.get("support_request_id", "") or ""),
            "source_bom_support_request_id": str(updated.get("support_request_id", "") or ""),
            "missing_fmea_row_refs": risk_refs,
            "requested_rows": requested_rows,
            "requested_row_count": len(requested_rows),
            "accepted_requested_row_ids": [],
            "uncovered_requested_row_ids": requested_row_ids,
            "reason": "Accepted BOM support references risk controls that need FMEA-like support rows.",
            "candidate_ingestion_state": "pending_support",
            "support_materialization_state": "waiting_for_consumable_support",
            "risk_support_current_state": "pending_operator_review",
            "created_at": now,
            "grants_execution_authority": False,
        }
    else:
        risk_support = dict(risk_support)
        if _support_request_state_value(risk_support) == "superseded":
            _set_support_request_state(risk_support, "pending_operator_review")
            risk_support["operator_review_required"] = True
            risk_support["candidate_ingestion_state"] = "pending_support"
            risk_support["support_materialization_state"] = "waiting_for_consumable_support"
            risk_support["support_blocker_reason"] = "risk_control_source_rows_required"
            risk_support["risk_control_support_refresh_state"] = "revived_from_superseded_bom_chain"
            risk_support["risk_support_repaired_from_support_request_id"] = str(
                updated.get("support_request_id", "") or ""
            )
            risk_support["risk_support_current_state"] = "pending_operator_review"
            for stale_key in (
                "superseded_at",
                "superseded_by_support_request_id",
                "superseded_reason",
            ):
                risk_support.pop(stale_key, None)
        elif _support_request_state_value(risk_support):
            _set_support_request_state(risk_support, _support_request_state_value(risk_support))
        risk_support["missing_field_coverage"] = _support_field_coverage_list(
            risk_support.get("missing_field_coverage"),
            risk_fields,
        )
        risk_support["missing_fields"] = _support_field_coverage_list(
            risk_support.get("missing_fields"),
            risk_fields,
        )
        risk_support["missing_fmea_row_refs"] = list(
            dict.fromkeys(list(risk_support.get("missing_fmea_row_refs", []) or []) + risk_refs)
        )
        existing_requested = [
            dict(item)
            for item in list(risk_support.get("requested_rows", []) or [])
            if isinstance(item, Mapping)
        ]
        existing_requested_ids = {
            str(item.get("requested_row_id", "") or "")
            for item in existing_requested
            if str(item.get("requested_row_id", "") or "")
        }
        for row in requested_rows:
            row_id = str(row.get("requested_row_id", "") or "")
            if row_id and row_id not in existing_requested_ids:
                existing_requested.append(row)
                existing_requested_ids.add(row_id)
        risk_support["requested_rows"] = existing_requested
        risk_support["requested_row_count"] = len(existing_requested)
        accepted_ids = {
            str(item or "").strip()
            for item in list(risk_support.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        }
        risk_support["uncovered_requested_row_ids"] = [
            str(item.get("requested_row_id", "") or "")
            for item in existing_requested
            if str(item.get("requested_row_id", "") or "") and str(item.get("requested_row_id", "") or "") not in accepted_ids
        ]
        risk_support["source_bom_support_request_id"] = str(updated.get("support_request_id", "") or "")
    risk_support["updated_at"] = now
    _write_json(_support_request_path(operator_root, risk_support_id), risk_support)
    directive_path = _directive_path(operator_root, directive_id)
    directive_payload = _read_json(directive_path)
    if directive_payload:
        metadata = dict(directive_payload.get("metadata", {}) or {})
        metadata.update(
            {
                "support_request_id": risk_support_id,
                "current_risk_control_support_request_id": risk_support_id,
                "support_blocker_target_artifact": "risk_controls.json",
                "initial_work_order_target_artifact": "risk_controls.json",
                "continuous_campaign_latest_target_artifact": "risk_controls.json",
                "next_linked_artifact_target": "risk_controls.json",
                "missing_fmea_row_refs": risk_refs,
                "risk_support_current_state": _support_request_state_value(risk_support)
                or "pending_operator_review",
            }
        )
        directive_payload["metadata"] = metadata
        _write_json(directive_path, directive_payload)
    _append_ledger(
        operator_root,
        "support_request_events",
        {
            "event": "risk_control_support_requested_from_bom_support",
            "generated_at": now,
            "support_request_id": risk_support_id,
            "source_bom_support_request_id": str(updated.get("support_request_id", "") or ""),
            "directive_id": directive_id,
            "target_artifact": "risk_controls.json",
            "missing_fmea_row_refs": risk_refs,
            "grants_execution_authority": False,
        },
    )
    updated["risk_control_materialization_state"] = "risk_control_support_requested"
    updated["bom_to_risk_control_chain_state"] = "risk_support_requested"
    updated["risk_control_support_request_id"] = risk_support_id
    updated["current_risk_control_support_request_id"] = risk_support_id
    updated["risk_support_current_state"] = _support_request_state_value(risk_support)
    if str(risk_support.get("risk_support_repaired_from_support_request_id", "") or ""):
        updated["risk_support_repaired_from_support_request_id"] = str(
            risk_support.get("risk_support_repaired_from_support_request_id", "")
        )
    updated["missing_fmea_row_refs"] = risk_refs
    updated["risk_control_go_no_go_gap_count"] = len(risk_refs)
    updated["next_linked_artifact_target"] = "risk_controls.json"
    updated["remaining_linked_artifact_gaps"] = list(
        dict.fromkeys(list(updated.get("remaining_linked_artifact_gaps", []) or []) + ["risk_controls.json"])
    )
    return updated, risk_support


