def _risk_control_row_from_support(
    support_row: Mapping[str, Any],
    requested_row: Mapping[str, Any],
) -> dict[str, Any]:
    requested_id = str(
        support_row.get("requested_row_id", "") or requested_row.get("requested_row_id", "") or ""
    ).strip()
    target_row_id = str(
        support_row.get("target_row_id", "") or requested_row.get("target_row_id", "") or ""
    ).strip()
    hazard_id = (
        _support_text_value(support_row, "hazard_id")
        or _artifact_ref_tail(target_row_id)
        or _safe_slug(requested_id, fallback="risk_control")
    )
    support_row_id = str(
        support_row.get("row_id", "") or support_row.get("support_row_id", "") or ""
    ).strip()
    evidence_ref = str(support_row.get("evidence_ref", "") or "").strip()
    row = {
        "control_id": hazard_id,
        "hazard_id": hazard_id,
        "requested_row_id": requested_id,
        "target_row_id": target_row_id,
        "closes_requested_row_id": requested_id,
        "closes_target_row_id": target_row_id,
        "failure_mode": _support_text_value(support_row, "failure_mode"),
        "effect": _support_text_value(support_row, "effect"),
        "severity": _support_text_value(support_row, "severity"),
        "occurrence": _support_text_value(support_row, "occurrence"),
        "detectability": _support_text_value(support_row, "detectability", "detection"),
        "mitigation": _support_text_value(support_row, "mitigation"),
        "linked_bom_ref": _support_text_value(support_row, "linked_bom_ref", "bom_ref"),
        "verification_fixture_ref": _support_text_value(
            support_row,
            "verification_fixture_ref",
            "validation_fixture_ref",
            "fixture_ref",
        ),
        "go_no_go_criteria": _support_text_value(support_row, "go_no_go_criteria", "go_no_go_trace"),
        "source_url": _support_text_value(support_row, "source_url", "datasheet_url"),
        "citation_ref": _support_text_value(support_row, "citation_ref", "citation"),
        "evidence_refs": [item for item in [evidence_ref] if item],
        "support_row_ids": list(
            dict.fromkeys(
                item
                for item in [support_row_id, requested_id, target_row_id]
                if item
            )
        ),
        "execution_gate": _support_text_value(support_row, "execution_gate")
        or "operator_review_required_before_real_world_use",
        "grants_execution_authority": False,
    }
    linked_fixture_refs = _support_list_value(
        support_row,
        "verification_fixture_refs",
        "validation_fixture_refs",
        "fixture_refs",
    )
    if linked_fixture_refs:
        row["verification_fixture_refs"] = linked_fixture_refs
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def materialize_current_bom_support(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    directive_id: str = "",
    support_request_id: str = "",
    persist_snapshot: bool = False,
) -> dict[str, Any]:
    started = time.perf_counter()
    initialize_conveyor_state(operator_root)
    materialized_ids: list[str] = []
    unmaterialized_ids: list[str] = []
    processed_support_ids: list[str] = []
    unblocked_directive_ids: list[str] = []
    changed_count = 0
    support_rows_used = 0
    misassignment_count = 0
    if state_root is None:
        return {
            "ok": False,
            "schema_name": "BOMVisibleMaterialization",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "bom_materialization_state": "state_root_required",
            "bom_materialized_requested_row_ids": [],
            "bom_unmaterialized_requested_row_ids": [],
            "grants_execution_authority": False,
        }
    for support in _load_items(_support_requests_root(operator_root)):
        current_support_id = str(support.get("support_request_id", "") or "")
        if support_request_id and current_support_id != support_request_id:
            continue
        current_directive_id = str(support.get("directive_id", "") or "")
        if directive_id and current_directive_id != directive_id:
            continue
        if str(support.get("target_artifact", "") or "") != "bill_of_materials.json":
            continue
        if _support_request_state_value(support) != "satisfied":
            continue
        requested_rows = [
            dict(row)
            for row in list(support.get("requested_rows", []) or [])
            if isinstance(row, Mapping)
            and str(row.get("requested_row_id", "") or "").strip()
        ]
        accepted_ids = [
            str(item or "").strip()
            for item in list(
                support.get("accepted_enriched_role_lane_row_ids", [])
                or support.get("accepted_commercial_requested_row_ids", [])
                or support.get("accepted_requested_row_ids", [])
                or []
            )
            if str(item or "").strip()
        ]
        if not requested_rows or not accepted_ids:
            continue
        directive = _read_json(_directive_path(operator_root, current_directive_id))
        metadata = dict(directive.get("metadata", {}) or {}) if directive else {}
        pointer_candidates = {
            str(metadata.get("support_request_id", "") or "").strip(),
            str(metadata.get("source_support_request_id", "") or "").strip(),
            str(metadata.get("current_linked_artifact_support_request_id", "") or "").strip(),
            current_support_id,
        }
        if current_support_id not in pointer_candidates:
            continue
        pack_ref = _support_pack_ref_from_support_request(operator_root, support)
        if not pack_ref:
            unmaterialized_ids.extend(accepted_ids)
            continue
        _source_path, _payload, evidence = _support_pack_evidence_for_ref(
            state_root,
            pack_ref,
            target_artifact="bill_of_materials.json",
        )
        evidence_rows = [dict(row) for row in list(evidence.get("rows", []) or []) if isinstance(row, Mapping)]
        candidate_rows = _raw_support_rows_from_pack_payload(_payload) or evidence_rows
        candidate_rows = [
            row
            for row in candidate_rows
            if str(row.get("target_artifact", "") or "").strip() in {"", "bill_of_materials.json"}
            and not bool(row.get("grants_execution_authority", False))
        ]
        accepted_id_by_alias: dict[str, str] = {}
        for accepted_id in accepted_ids:
            for alias in _requested_row_id_aliases(accepted_id):
                accepted_id_by_alias[alias] = accepted_id
        canonical_candidate_rows: list[dict[str, Any]] = []
        for row in candidate_rows:
            canonical = dict(row)
            row_requested_id = str(canonical.get("requested_row_id", "") or "").strip()
            canonical_requested_id = ""
            for alias in _requested_row_id_aliases(row_requested_id):
                if alias in accepted_id_by_alias:
                    canonical_requested_id = accepted_id_by_alias[alias]
                    break
            if canonical_requested_id:
                canonical["requested_row_id"] = canonical_requested_id
            canonical_candidate_rows.append(canonical)
        candidate_rows = canonical_candidate_rows
        support_rows_used += len(candidate_rows)
        coverage = assess_requested_row_coverage(
            candidate_rows,
            requested_rows=requested_rows,
            target_artifact="bill_of_materials.json",
        )
        covered_ids = {
            str(item or "").strip()
            for item in list(coverage.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        }.intersection(set(accepted_ids))
        requested_by_id = {
            str(row.get("requested_row_id", "") or "").strip(): row
            for row in requested_rows
            if str(row.get("requested_row_id", "") or "").strip()
        }
        incoming: list[dict[str, Any]] = []
        for requested_id in accepted_ids:
            if not any(_requested_row_ids_intersect(requested_id, covered) for covered in covered_ids):
                unmaterialized_ids.append(requested_id)
                continue
            requested = requested_by_id.get(requested_id, {})
            requested_role = normalize_support_role_lane(requested.get("target_role") or requested.get("role"))
            source_row = next(
                (
                    row
                    for row in candidate_rows
                    if _requested_row_ids_intersect(row.get("requested_row_id"), requested_id)
                    and (
                        not requested_role
                        or normalize_support_role_lane(row.get("target_role") or row.get("role")) == requested_role
                    )
                ),
                {},
            )
            if not source_row:
                unmaterialized_ids.append(requested_id)
                misassignment_count += 1 if requested_role else 0
                continue
            canonical_source_row = dict(source_row)
            canonical_source_row["requested_row_id"] = requested_id
            incoming.append(_bom_row_from_support(canonical_source_row, requested))
        if not incoming:
            continue
        incoming_materialized_ids = [
            str(row.get("closes_requested_row_id", "") or "")
            for row in incoming
            if str(row.get("closes_requested_row_id", "") or "").strip()
        ]
        campaign_root = _campaign_root(operator_root, current_directive_id)
        draft_path = campaign_root / "drafts" / "bill_of_materials.json"
        payload = _read_json(draft_path) or {
            "schema_name": "ConveyorBillOfMaterials",
            "items": [],
            "grants_execution_authority": False,
        }
        row_key = "items" if isinstance(payload.get("items"), list) else "components" if isinstance(payload.get("components"), list) else "rows" if isinstance(payload.get("rows"), list) else "items"
        existing_rows = [dict(row) for row in list(payload.get(row_key, []) or []) if isinstance(row, Mapping)]
        merged_rows, changed, merge_misassignments = _merge_bom_rows(existing_rows, incoming)
        misassignment_count += merge_misassignments
        payload[row_key] = merged_rows
        visible_materialized_ids = [
            str(row.get("closes_requested_row_id", "") or "")
            for row in merged_rows
            if str(row.get("closes_requested_row_id", "") or "").strip()
        ]
        payload["bom_materialization_state"] = "materialized"
        payload["bom_materialized_requested_row_ids"] = list(dict.fromkeys(visible_materialized_ids))
        payload["bom_unmaterialized_requested_row_ids"] = []
        payload["role_lane_closure_state"] = "closed"
        payload["role_lane_misassignment_count"] = misassignment_count
        payload["role_lane_closed_requested_row_ids"] = list(dict.fromkeys(visible_materialized_ids))
        payload["role_lane_unclosed_requested_row_ids"] = []
        payload["grants_execution_authority"] = False
        if changed:
            _write_json(draft_path, payload)
            changed_count += 1
        materialized_ids.extend(incoming_materialized_ids)
        processed_support_ids.append(current_support_id)
        updated_support = dict(support)
        updated_support["bom_materialization_state"] = "materialized"
        updated_support["bom_materialized_requested_row_ids"] = list(dict.fromkeys(incoming_materialized_ids))
        updated_support["bom_unmaterialized_requested_row_ids"] = [
            item
            for item in accepted_ids
            if not any(
                _requested_row_ids_intersect(item, materialized_id)
                for materialized_id in incoming_materialized_ids
            )
        ]
        updated_support["role_lane_closure_state"] = "closed" if not updated_support["bom_unmaterialized_requested_row_ids"] else "partial"
        updated_support["role_lane_misassignment_count"] = misassignment_count
        updated_support["accepted_enriched_role_lane_row_ids"] = list(dict.fromkeys(incoming_materialized_ids))
        updated_support["uncovered_enriched_role_lane_row_ids"] = list(updated_support["bom_unmaterialized_requested_row_ids"])
        updated_support["support_materialization_state"] = (
            "visible_bom_rows_materialized"
            if not updated_support["bom_unmaterialized_requested_row_ids"]
            else "visible_bom_rows_partial"
        )
        updated_support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, current_support_id), updated_support)
        if not updated_support["bom_unmaterialized_requested_row_ids"]:
            latest_directive = _read_json(_directive_path(operator_root, current_directive_id))
            latest_metadata = dict(latest_directive.get("metadata", {}) or {}) if latest_directive else {}
            target_names = {
                str(value or "")
                for value in (
                    latest_metadata.get("support_blocker_target_artifact", ""),
                    latest_metadata.get("initial_work_order_target_artifact", ""),
                    latest_metadata.get("continuous_campaign_latest_target_artifact", ""),
                    latest_directive.get("support_blocker_target_artifact", ""),
                    latest_directive.get("initial_work_order_target_artifact", ""),
                    latest_directive.get("continuous_campaign_latest_target_artifact", ""),
                )
                if str(value or "")
            }
            if (
                latest_directive
                and str(latest_directive.get("state", "") or "") in {"blocked_for_support", "support_synthesis_in_progress"}
                and (
                    "bill_of_materials.json" in target_names
                    or bool(latest_metadata.get("resident_support_handoff_finalized", False))
                    or str(latest_directive.get("blocked_reason", "") or "")
                    == "resident_support_handoff_missing"
                )
            ):
                repaired_directive = dict(latest_directive)
                repaired_metadata = dict(latest_metadata)
                repaired_metadata["support_materialization_state"] = "visible_bom_rows_materialized"
                repaired_metadata["bom_materialization_state"] = "materialized"
                repaired_metadata["bom_materialized_requested_row_ids"] = list(
                    dict.fromkeys(incoming_materialized_ids)
                )
                repaired_metadata["bom_unmaterialized_requested_row_ids"] = []
                repaired_metadata["role_lane_closure_state"] = updated_support["role_lane_closure_state"]
                repaired_metadata["accepted_enriched_role_lane_row_ids"] = list(
                    dict.fromkeys(incoming_materialized_ids)
                )
                repaired_metadata["uncovered_enriched_role_lane_row_ids"] = []
                repaired_metadata["support_blocker_target_artifact"] = "bill_of_materials.json"
                repaired_metadata["initial_work_order_target_artifact"] = "bill_of_materials.json"
                repaired_metadata["continuous_campaign_latest_target_artifact"] = "bill_of_materials.json"
                repaired_metadata["support_request_id"] = current_support_id
                repaired_metadata["source_support_request_id"] = current_support_id
                repaired_metadata["support_materialization_unblocked_by_support_request_id"] = current_support_id
                repaired_metadata["commercial_source_acquisition_required"] = False
                repaired_metadata["source_backed_rows_required"] = False
                repaired_metadata["uncovered_requested_row_ids"] = []
                repaired_metadata["support_admission_state"] = "adequate"
                repaired_metadata["support_admission_blocker_reason"] = ""
                repaired_metadata["resident_support_handoff_finalized"] = False
                repaired_metadata["resident_support_handoff_state"] = "cleared_after_visible_bom_materialization"
                repaired_metadata["resident_support_handoff_blockers"] = []
                repaired_metadata["support_blocker_reason"] = ""
                repaired_metadata["next_support_recovery_action"] = "bounded_scheduler_admission"
                repaired_directive["metadata"] = repaired_metadata
                repaired_directive["state"] = "requeued"
                repaired_directive["blocked_reason"] = "visible_bom_support_materialized"
                repaired_directive["updated_at"] = _utc_now()
                _write_json(_directive_path(operator_root, current_directive_id), repaired_directive)
                unblocked_directive_ids.append(current_directive_id)
    materialized_ids = list(dict.fromkeys(item for item in materialized_ids if item))
    unmaterialized_ids = [
        item for item in list(dict.fromkeys(item for item in unmaterialized_ids if item))
        if item not in set(materialized_ids)
    ]
    state = (
        "materialized"
        if materialized_ids and not unmaterialized_ids
        else "partial"
        if materialized_ids
        else "no_current_accepted_bom_support"
    )
    result = {
        "ok": True,
        "schema_name": "BOMVisibleMaterialization",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "bom_materialization_state": state,
        "bom_materialized_requested_row_ids": materialized_ids,
        "bom_unmaterialized_requested_row_ids": unmaterialized_ids,
        "bom_materialized_count": len(materialized_ids),
        "bom_changed_artifact_count": changed_count,
        "bom_materialization_unblocked_directive_ids": list(dict.fromkeys(unblocked_directive_ids)),
        "bom_materialization_unblocked_count": len(list(dict.fromkeys(unblocked_directive_ids))),
        "bom_support_rows_used_count": support_rows_used,
        "bom_support_requests_processed": processed_support_ids,
        "role_lane_misassignment_count": misassignment_count,
        "support_materialization_state": (
            "visible_bom_rows_materialized" if state == "materialized" else state
        ),
        "support_tick_duration_ms": round((time.perf_counter() - started) * 1000, 3),
        "grants_execution_authority": False,
    }
    _append_ledger(operator_root, "bom_visible_materialization_events", result)
    if persist_snapshot:
        snapshot = build_task_manager_snapshot(operator_root, persist=True)
        persist_bounded_status_snapshot(
            operator_root,
            task_manager_snapshot=snapshot,
            refreshed_by="bom_visible_materialization",
        )
    return result


def materialize_current_risk_control_support(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    directive_id: str = "",
    support_request_id: str = "",
    persist_snapshot: bool = False,
) -> dict[str, Any]:
    started = time.perf_counter()
    initialize_conveyor_state(operator_root)
    materialized_ids: list[str] = []
    unmaterialized_ids: list[str] = []
    processed_support_ids: list[str] = []
    unblocked_directive_ids: list[str] = []
    changed_count = 0
    support_rows_used = 0
    if state_root is None:
        return {
            "ok": False,
            "schema_name": "RiskControlVisibleMaterialization",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "risk_control_materialization_state": "state_root_required",
            "risk_control_materialized_requested_row_ids": [],
            "risk_control_unmaterialized_requested_row_ids": [],
            "grants_execution_authority": False,
        }
    for support in _load_items(_support_requests_root(operator_root)):
        current_support_id = str(support.get("support_request_id", "") or "")
        if support_request_id and current_support_id != support_request_id:
            continue
        current_directive_id = str(support.get("directive_id", "") or "")
        if directive_id and current_directive_id != directive_id:
            continue
        if str(support.get("target_artifact", "") or "") != "risk_controls.json":
            continue
        if _support_request_state_value(support) != "satisfied":
            continue
        requested_rows = [
            dict(row)
            for row in list(support.get("requested_rows", []) or [])
            if isinstance(row, Mapping)
            and str(row.get("requested_row_id", "") or "").strip()
        ]
        accepted_ids = [
            str(item or "").strip()
            for item in list(
                support.get("accepted_fmea_requested_row_ids", [])
                or support.get("accepted_requested_row_ids", [])
                or []
            )
            if str(item or "").strip()
        ]
        if not requested_rows or not accepted_ids:
            continue
        directive = _read_json(_directive_path(operator_root, current_directive_id))
        metadata = dict(directive.get("metadata", {}) or {}) if directive else {}
        current_pointer = str(
            metadata.get("current_risk_control_support_request_id", "")
            or metadata.get("support_request_id", "")
            or ""
        )
        if current_pointer and current_pointer != current_support_id:
            continue
        pack_ref = _support_pack_ref_from_support_request(operator_root, support)
        if not pack_ref:
            unmaterialized_ids.extend(accepted_ids)
            continue
        _source_path, _payload, evidence = _support_pack_evidence_for_ref(
            state_root,
            pack_ref,
            target_artifact="risk_controls.json",
        )
        evidence_rows = [dict(row) for row in list(evidence.get("rows", []) or []) if isinstance(row, Mapping)]
        candidate_rows = _raw_support_rows_from_pack_payload(_payload) or evidence_rows
        candidate_rows = [
            row
            for row in candidate_rows
            if str(row.get("target_artifact", "") or "").strip() in {"", "risk_controls.json"}
            and not bool(row.get("grants_execution_authority", False))
        ]
        accepted_id_by_alias: dict[str, str] = {}
        for accepted_id in accepted_ids:
            for alias in _requested_row_id_aliases(accepted_id):
                accepted_id_by_alias[alias] = accepted_id
        canonical_candidate_rows: list[dict[str, Any]] = []
        for row in candidate_rows:
            canonical = dict(row)
            row_requested_id = str(canonical.get("requested_row_id", "") or "").strip()
            canonical_requested_id = ""
            for alias in _requested_row_id_aliases(row_requested_id):
                if alias in accepted_id_by_alias:
                    canonical_requested_id = accepted_id_by_alias[alias]
                    break
            if canonical_requested_id:
                canonical["requested_row_id"] = canonical_requested_id
            canonical_candidate_rows.append(canonical)
        candidate_rows = canonical_candidate_rows
        support_rows_used += len(candidate_rows)
        coverage = assess_requested_row_coverage(
            candidate_rows,
            requested_rows=requested_rows,
            target_artifact="risk_controls.json",
        )
        covered_ids = {
            str(item or "").strip()
            for item in list(coverage.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        }.intersection(set(accepted_ids))
        requested_by_id = {
            str(row.get("requested_row_id", "") or "").strip(): row
            for row in requested_rows
            if str(row.get("requested_row_id", "") or "").strip()
        }
        incoming: list[dict[str, Any]] = []
        for requested_id in accepted_ids:
            if not any(_requested_row_ids_intersect(requested_id, covered) for covered in covered_ids):
                unmaterialized_ids.append(requested_id)
                continue
            source_row = next(
                (
                    row
                    for row in candidate_rows
                    if _requested_row_ids_intersect(row.get("requested_row_id"), requested_id)
                ),
                {},
            )
            if not source_row:
                unmaterialized_ids.append(requested_id)
                continue
            canonical_source_row = dict(source_row)
            canonical_source_row["requested_row_id"] = requested_id
            incoming.append(
                _risk_control_row_from_support(
                    canonical_source_row,
                    requested_by_id.get(requested_id, {}),
                )
            )
        if not incoming:
            continue
        incoming_materialized_ids = [
            str(row.get("closes_requested_row_id", "") or "")
            for row in incoming
            if str(row.get("closes_requested_row_id", "") or "").strip()
        ]
        campaign_root = _campaign_root(operator_root, current_directive_id)
        draft_path = campaign_root / "drafts" / "risk_controls.json"
        payload = _read_json(draft_path) or {
            "schema_name": "ConveyorRiskControls",
            "controls": [],
            "grants_execution_authority": False,
        }
        row_key = "controls" if isinstance(payload.get("controls"), list) else "risk_controls" if isinstance(payload.get("risk_controls"), list) else "rows" if isinstance(payload.get("rows"), list) else "controls"
        existing_rows = [dict(row) for row in list(payload.get(row_key, []) or []) if isinstance(row, Mapping)]
        merged_rows, changed = _merge_risk_control_rows(existing_rows, incoming)
        payload[row_key] = merged_rows
        visible_materialized_ids = [
            str(row.get("closes_requested_row_id", "") or "")
            for row in merged_rows
            if str(row.get("closes_requested_row_id", "") or "").strip()
        ]
        payload["risk_control_materialization_state"] = "materialized"
        payload["risk_control_materialized_requested_row_ids"] = list(dict.fromkeys(visible_materialized_ids))
        payload["risk_control_unmaterialized_requested_row_ids"] = []
        payload["grants_execution_authority"] = False
        if changed:
            _write_json(draft_path, payload)
            changed_count += 1
        materialized_ids.extend(incoming_materialized_ids)
        processed_support_ids.append(current_support_id)
        updated_support = dict(support)
        updated_support["risk_control_materialization_state"] = "materialized"
        updated_support["risk_control_materialized_requested_row_ids"] = list(
            dict.fromkeys(incoming_materialized_ids)
        )
        updated_support["risk_control_unmaterialized_requested_row_ids"] = [
            item
            for item in accepted_ids
            if not any(
                _requested_row_ids_intersect(item, materialized_id)
                for materialized_id in incoming_materialized_ids
            )
        ]
        updated_support["support_materialization_state"] = (
            "visible_risk_control_rows_materialized"
            if not updated_support["risk_control_unmaterialized_requested_row_ids"]
            else "visible_risk_control_rows_partial"
        )
        updated_support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, current_support_id), updated_support)
        if not updated_support["risk_control_unmaterialized_requested_row_ids"]:
            latest_directive = _read_json(_directive_path(operator_root, current_directive_id))
            latest_metadata = dict(latest_directive.get("metadata", {}) or {}) if latest_directive else {}
            latest_pointer = str(
                latest_metadata.get("current_risk_control_support_request_id", "")
                or latest_metadata.get("support_request_id", "")
                or latest_directive.get("current_risk_control_support_request_id", "")
                or latest_directive.get("support_request_id", "")
                or ""
            )
            target_names = {
                str(value or "")
                for value in (
                    latest_metadata.get("support_blocker_target_artifact", ""),
                    latest_metadata.get("initial_work_order_target_artifact", ""),
                    latest_metadata.get("continuous_campaign_latest_target_artifact", ""),
                    latest_directive.get("support_blocker_target_artifact", ""),
                    latest_directive.get("initial_work_order_target_artifact", ""),
                    latest_directive.get("continuous_campaign_latest_target_artifact", ""),
                )
                if str(value or "")
            }
            if (
                latest_directive
                and str(latest_directive.get("state", "") or "") in {"blocked_for_support", "support_synthesis_in_progress"}
                and latest_pointer == current_support_id
                and "risk_controls.json" in target_names
            ):
                repaired_directive = dict(latest_directive)
                repaired_metadata = dict(latest_metadata)
                repaired_metadata["support_materialization_state"] = "visible_risk_control_rows_materialized"
                repaired_metadata["risk_control_materialization_state"] = "materialized"
                repaired_metadata["risk_control_materialized_requested_row_ids"] = list(
                    dict.fromkeys(incoming_materialized_ids)
                )
                repaired_metadata["risk_control_unmaterialized_requested_row_ids"] = []
                repaired_metadata["support_blocker_target_artifact"] = "risk_controls.json"
                repaired_metadata["initial_work_order_target_artifact"] = "risk_controls.json"
                repaired_metadata["continuous_campaign_latest_target_artifact"] = "risk_controls.json"
                repaired_metadata["support_request_id"] = current_support_id
                repaired_metadata["current_risk_control_support_request_id"] = current_support_id
                repaired_metadata["risk_control_support_request_id"] = current_support_id
                repaired_metadata["support_pointer_role"] = "current_risk_control_support_request_id"
                repaired_metadata["support_materialization_unblocked_by_support_request_id"] = current_support_id
                repaired_directive["metadata"] = repaired_metadata
                repaired_directive["state"] = "requeued"
                repaired_directive["blocked_reason"] = "visible_risk_control_support_materialized"
                repaired_directive["updated_at"] = _utc_now()
                _write_json(_directive_path(operator_root, current_directive_id), repaired_directive)
                unblocked_directive_ids.append(current_directive_id)
    materialized_ids = list(dict.fromkeys(item for item in materialized_ids if item))
    unmaterialized_ids = [
        item for item in list(dict.fromkeys(item for item in unmaterialized_ids if item))
        if item not in set(materialized_ids)
    ]
    state = (
        "materialized"
        if materialized_ids and not unmaterialized_ids
        else "partial"
        if materialized_ids
        else "no_current_accepted_risk_control_support"
    )
    result = {
        "ok": True,
        "schema_name": "RiskControlVisibleMaterialization",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "risk_control_materialization_state": state,
        "risk_control_materialized_requested_row_ids": materialized_ids,
        "risk_control_unmaterialized_requested_row_ids": unmaterialized_ids,
        "risk_control_materialized_count": len(materialized_ids),
        "risk_control_changed_artifact_count": changed_count,
        "risk_control_materialization_unblocked_directive_ids": list(dict.fromkeys(unblocked_directive_ids)),
        "risk_control_materialization_unblocked_count": len(list(dict.fromkeys(unblocked_directive_ids))),
        "risk_control_support_rows_used_count": support_rows_used,
        "risk_control_support_requests_processed": processed_support_ids,
        "support_tick_duration_ms": round((time.perf_counter() - started) * 1000, 3),
        "grants_execution_authority": False,
    }
    _append_ledger(
        operator_root,
        "risk_control_visible_materialization_events",
        result,
    )
    if persist_snapshot:
        snapshot = build_task_manager_snapshot(operator_root, persist=True)
        persist_bounded_status_snapshot(
            operator_root,
            task_manager_snapshot=snapshot,
            refreshed_by="risk_control_visible_materialization",
        )
    return result


def materialize_current_validation_fixture_support(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    directive_id: str = "",
    support_request_id: str = "",
    persist_snapshot: bool = False,
) -> dict[str, Any]:
    started = time.perf_counter()
    initialize_conveyor_state(operator_root)
    materialized_ids: list[str] = []
    unmaterialized_ids: list[str] = []
    processed_support_ids: list[str] = []
    unblocked_directive_ids: list[str] = []
    changed_count = 0
    support_rows_used = 0
    if state_root is None:
        return {
            "ok": False,
            "schema_name": "ValidationFixtureVisibleMaterialization",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "visible_fixture_materialization_state": "state_root_required",
            "visible_fixture_materialized_requested_row_ids": [],
            "visible_fixture_unmaterialized_requested_row_ids": [],
            "grants_execution_authority": False,
        }
    for support in _load_items(_support_requests_root(operator_root)):
        current_support_id = str(support.get("support_request_id", "") or "")
        if support_request_id and current_support_id != support_request_id:
            continue
        current_directive_id = str(support.get("directive_id", "") or "")
        if directive_id and current_directive_id != directive_id:
            continue
        if str(support.get("target_artifact", "") or "") != "validation_fixtures.json":
            continue
        if _support_request_state_value(support) != "satisfied":
            continue
        requested_rows = [
            dict(row)
            for row in list(support.get("requested_rows", []) or [])
            if isinstance(row, Mapping)
            and str(row.get("requested_row_id", "") or "").strip()
        ]
        accepted_ids = [
            str(item or "").strip()
            for item in list(
                support.get("accepted_validation_fixture_requested_row_ids", [])
                or support.get("accepted_requested_row_ids", [])
                or []
            )
            if str(item or "").strip()
        ]
        if not requested_rows or not accepted_ids:
            continue
        directive = _read_json(_directive_path(operator_root, current_directive_id))
        metadata = dict(directive.get("metadata", {}) or {}) if directive else {}
        current_pointer = str(
            metadata.get("current_validation_fixture_support_request_id", "")
            or metadata.get("support_request_id", "")
            or ""
        )
        if current_pointer and current_pointer != current_support_id:
            continue
        pack_ref = _support_pack_ref_from_support_request(operator_root, support)
        if not pack_ref:
            unmaterialized_ids.extend(accepted_ids)
            continue
        _source_path, _payload, evidence = _support_pack_evidence_for_ref(
            state_root,
            pack_ref,
            target_artifact="validation_fixtures.json",
        )
        evidence_rows = [dict(row) for row in list(evidence.get("rows", []) or []) if isinstance(row, Mapping)]
        candidate_rows = _raw_support_rows_from_pack_payload(_payload) or evidence_rows
        candidate_rows = [
            row
            for row in candidate_rows
            if str(row.get("target_artifact", "") or "").strip() in {"", "validation_fixtures.json"}
            and not bool(row.get("grants_execution_authority", False))
        ]
        accepted_id_by_alias: dict[str, str] = {}
        for accepted_id in accepted_ids:
            for alias in _requested_row_id_aliases(accepted_id):
                accepted_id_by_alias[alias] = accepted_id
        canonical_candidate_rows: list[dict[str, Any]] = []
        for row in candidate_rows:
            canonical = dict(row)
            row_requested_id = str(canonical.get("requested_row_id", "") or "").strip()
            canonical_requested_id = ""
            for alias in _requested_row_id_aliases(row_requested_id):
                if alias in accepted_id_by_alias:
                    canonical_requested_id = accepted_id_by_alias[alias]
                    break
            if canonical_requested_id:
                canonical["requested_row_id"] = canonical_requested_id
            canonical_candidate_rows.append(canonical)
        candidate_rows = canonical_candidate_rows
        support_rows_used += len(candidate_rows)
        coverage = assess_requested_row_coverage(
            candidate_rows,
            requested_rows=requested_rows,
            target_artifact="validation_fixtures.json",
        )
        covered_ids = {
            str(item or "").strip()
            for item in list(coverage.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        }.intersection(set(accepted_ids))
        requested_by_id = {
            str(row.get("requested_row_id", "") or "").strip(): row
            for row in requested_rows
            if str(row.get("requested_row_id", "") or "").strip()
        }
        incoming: list[dict[str, Any]] = []
        for requested_id in accepted_ids:
            if not any(_requested_row_ids_intersect(requested_id, covered) for covered in covered_ids):
                unmaterialized_ids.append(requested_id)
                continue
            source_row = next(
                (
                    row
                    for row in candidate_rows
                    if _requested_row_ids_intersect(row.get("requested_row_id"), requested_id)
                ),
                {},
            )
            if not source_row:
                unmaterialized_ids.append(requested_id)
                continue
            canonical_source_row = dict(source_row)
            canonical_source_row["requested_row_id"] = requested_id
            incoming.append(
                _validation_fixture_row_from_support(
                    canonical_source_row,
                    requested_by_id.get(requested_id, {}),
                )
            )
        if not incoming:
            continue
        incoming_materialized_ids = [
            str(row.get("closes_requested_row_id", "") or "")
            for row in incoming
            if str(row.get("closes_requested_row_id", "") or "").strip()
        ]
        campaign_root = _campaign_root(operator_root, current_directive_id)
        draft_path = campaign_root / "drafts" / "validation_fixtures.json"
        payload = _read_json(draft_path) or {
            "schema_name": "ConveyorValidationFixtures",
            "fixtures": [],
            "grants_execution_authority": False,
        }
        row_key = "fixtures" if isinstance(payload.get("fixtures"), list) else "rows" if isinstance(payload.get("rows"), list) else "fixtures"
        existing_rows = [dict(row) for row in list(payload.get(row_key, []) or []) if isinstance(row, Mapping)]
        merged_rows, changed = _merge_validation_fixture_rows(existing_rows, incoming)
        payload[row_key] = merged_rows
        visible_materialized_ids = [
            str(row.get("closes_requested_row_id", "") or "")
            for row in merged_rows
            if str(row.get("closes_requested_row_id", "") or "").strip()
        ]
        payload["visible_fixture_materialization_state"] = "materialized"
        payload["visible_fixture_materialized_requested_row_ids"] = list(dict.fromkeys(visible_materialized_ids))
        payload["visible_fixture_unmaterialized_requested_row_ids"] = []
        payload["grants_execution_authority"] = False
        if changed:
            _write_json(draft_path, payload)
            changed_count += 1
        materialized_ids.extend(incoming_materialized_ids)
        processed_support_ids.append(current_support_id)
        updated_support = dict(support)
        updated_support["visible_fixture_materialization_state"] = "materialized"
        updated_support["visible_fixture_materialized_requested_row_ids"] = list(
            dict.fromkeys(incoming_materialized_ids)
        )
        updated_support["visible_fixture_unmaterialized_requested_row_ids"] = [
            item
            for item in accepted_ids
            if not any(
                _requested_row_ids_intersect(item, materialized_id)
                for materialized_id in incoming_materialized_ids
            )
        ]
        updated_support["support_materialization_state"] = (
            "visible_fixture_rows_materialized"
            if not updated_support["visible_fixture_unmaterialized_requested_row_ids"]
            else "visible_fixture_rows_partial"
        )
        updated_support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, current_support_id), updated_support)
        if not updated_support["visible_fixture_unmaterialized_requested_row_ids"]:
            latest_directive = _read_json(_directive_path(operator_root, current_directive_id))
            latest_metadata = dict(latest_directive.get("metadata", {}) or {}) if latest_directive else {}
            latest_pointer = str(
                latest_metadata.get("current_validation_fixture_support_request_id", "")
                or latest_metadata.get("support_request_id", "")
                or latest_directive.get("current_validation_fixture_support_request_id", "")
                or latest_directive.get("support_request_id", "")
                or ""
            )
            metadata_target = str(
                latest_metadata.get("support_blocker_target_artifact", "")
                or latest_metadata.get("initial_work_order_target_artifact", "")
                or latest_metadata.get("continuous_campaign_latest_target_artifact", "")
                or latest_directive.get("support_blocker_target_artifact", "")
                or latest_directive.get("initial_work_order_target_artifact", "")
                or latest_directive.get("continuous_campaign_latest_target_artifact", "")
                or ""
            )
            target_names = {
                str(value or "")
                for value in (
                    latest_metadata.get("support_blocker_target_artifact", ""),
                    latest_metadata.get("initial_work_order_target_artifact", ""),
                    latest_metadata.get("continuous_campaign_latest_target_artifact", ""),
                    latest_directive.get("support_blocker_target_artifact", ""),
                    latest_directive.get("initial_work_order_target_artifact", ""),
                    latest_directive.get("continuous_campaign_latest_target_artifact", ""),
                )
                if str(value or "")
            }
            if (
                latest_directive
                and str(latest_directive.get("state", "") or "") in {"blocked_for_support", "support_synthesis_in_progress"}
                and latest_pointer == current_support_id
                and (metadata_target == "validation_fixtures.json" or "validation_fixtures.json" in target_names)
            ):
                repaired_directive = dict(latest_directive)
                repaired_metadata = dict(latest_metadata)
                repaired_metadata["support_materialization_state"] = "visible_fixture_rows_materialized"
                repaired_metadata["visible_fixture_materialization_state"] = "materialized"
                repaired_metadata["visible_fixture_materialized_requested_row_ids"] = list(
                    dict.fromkeys(incoming_materialized_ids)
                )
                repaired_metadata["visible_fixture_unmaterialized_requested_row_ids"] = []
                repaired_metadata["support_blocker_target_artifact"] = "validation_fixtures.json"
                repaired_metadata["initial_work_order_target_artifact"] = "validation_fixtures.json"
                repaired_metadata["continuous_campaign_latest_target_artifact"] = "validation_fixtures.json"
                repaired_metadata["support_materialization_unblocked_by_support_request_id"] = current_support_id
                repaired_directive["metadata"] = repaired_metadata
                repaired_directive["state"] = "requeued"
                repaired_directive["blocked_reason"] = "visible_fixture_support_materialized"
                repaired_directive["updated_at"] = _utc_now()
                _write_json(_directive_path(operator_root, current_directive_id), repaired_directive)
                unblocked_directive_ids.append(current_directive_id)
    materialized_ids = list(dict.fromkeys(item for item in materialized_ids if item))
    unmaterialized_ids = [
        item for item in list(dict.fromkeys(item for item in unmaterialized_ids if item))
        if item not in set(materialized_ids)
    ]
    state = (
        "materialized"
        if materialized_ids and not unmaterialized_ids
        else "partial"
        if materialized_ids
        else "no_current_accepted_fixture_support"
    )
    result = {
        "ok": True,
        "schema_name": "ValidationFixtureVisibleMaterialization",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "visible_fixture_materialization_state": state,
        "visible_fixture_materialized_requested_row_ids": materialized_ids,
        "visible_fixture_unmaterialized_requested_row_ids": unmaterialized_ids,
        "visible_fixture_materialized_count": len(materialized_ids),
        "visible_fixture_changed_artifact_count": changed_count,
        "support_materialization_unblocked_directive_ids": list(dict.fromkeys(unblocked_directive_ids)),
        "support_materialization_unblocked_count": len(list(dict.fromkeys(unblocked_directive_ids))),
        "support_rows_used_count": support_rows_used,
        "support_requests_processed": processed_support_ids,
        "support_materialization_state": (
            "visible_fixture_rows_materialized" if state == "materialized" else state
        ),
        "support_tick_duration_ms": round((time.perf_counter() - started) * 1000, 3),
        "grants_execution_authority": False,
    }
    _append_ledger(
        operator_root,
        "validation_fixture_visible_materialization_events",
        result,
    )
    if persist_snapshot:
        snapshot = build_task_manager_snapshot(operator_root, persist=True)
        persist_bounded_status_snapshot(
            operator_root,
            task_manager_snapshot=snapshot,
            refreshed_by="validation_fixture_visible_materialization",
        )
    return result


def _refresh_cached_task_manager_snapshot_after_fixture_materialization(
    operator_root: str | Path,
    materialization: Mapping[str, Any],
) -> dict[str, Any]:
    cached = load_task_manager_snapshot(operator_root)
    if not cached:
        return {
            "snapshot_refresh_state": "missing_cached_snapshot",
            "snapshot_refreshed_by": "",
            "snapshot_refreshed_directive_ids": [],
        }
    support_ids = [
        str(item or "").strip()
        for item in list(materialization.get("support_requests_processed", []) or [])
        if str(item or "").strip()
    ]
    support_ids_by_directive: dict[str, dict[str, Any]] = {}
    for support_id in support_ids:
        support = _read_json(_support_request_path(operator_root, support_id))
        directive_id = str(support.get("directive_id", "") or "").strip()
        if not directive_id:
            continue
        if str(support.get("target_artifact", "") or "") != "validation_fixtures.json":
            continue
        unmaterialized = [
            str(item or "").strip()
            for item in list(support.get("visible_fixture_unmaterialized_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        if _support_request_state_value(support) != "satisfied" or unmaterialized:
            continue
        support_ids_by_directive[directive_id] = support
    if not support_ids_by_directive:
        return {
            "snapshot_refresh_state": "not_required",
            "snapshot_refreshed_by": "",
            "snapshot_refreshed_directive_ids": [],
        }

    now = _utc_now()
    refreshed = dict(cached)
    refreshed["generated_at"] = now
    refreshed["snapshot_refreshed_by"] = "bounded_support_tick_fixture_materialization_cached_refresh"
    refreshed["snapshot_freshness_state"] = "cached_fixture_materialization_refresh"
    refreshed["grants_execution_authority"] = False
    refreshed_directive_ids: list[str] = []
    directive_tasks: list[dict[str, Any]] = []
    for task in list(cached.get("directive_tasks", []) or []):
        if not isinstance(task, Mapping):
            continue
        row = dict(task)
        directive_id = str(row.get("directive_id", "") or "").strip()
        support = support_ids_by_directive.get(directive_id)
        if support:
            directive = _read_json(_directive_path(operator_root, directive_id))
            metadata = dict(directive.get("metadata", {}) or {}) if directive else {}
            existing_target = str(row.get("target_artifact", "") or "").strip()
            existing_support_state = str(row.get("support_admission_state", "") or "").strip()
            metadata_uncovered_requested_ids = [
                str(item or "").strip()
                for item in list(metadata.get("uncovered_requested_row_ids", []) or [])
                if str(item or "").strip()
            ]
            metadata_provider_field_lane_request_id = str(
                metadata.get("provider_field_lane_request_id", "")
                or row.get("provider_field_lane_request_id", "")
                or row.get("support_admission_provider_field_lane_request_id", "")
                or ""
            ).strip()
            preserved_support_request_id = str(row.get("support_admission_request_id", "") or "").strip()
            if (
                preserved_support_request_id.startswith("provider-field-lane")
                and str(metadata.get("support_request_id", "") or "").strip()
            ):
                metadata_provider_field_lane_request_id = (
                    metadata_provider_field_lane_request_id or preserved_support_request_id
                )
                preserved_support_request_id = str(metadata.get("support_request_id", "") or "").strip()
            active_child_id = str(directive.get("active_child_run_id", "") or "").strip()
            directive_state = str(directive.get("state", "") or "requeued")
            if directive_state not in {"queued", "requeued"}:
                preserved_state = str(row.get("task_state", "") or "").strip()
                if directive_state == "blocked_for_support" or preserved_state == "eligible":
                    preserved_state = "blocked_for_support"
                preserved_support_state = str(row.get("support_admission_state", "") or "").strip()
                preserved_support_reason = str(row.get("support_admission_blocker_reason", "") or "").strip()
                preserved_uncovered = list(row.get("support_admission_uncovered_fields", []) or [])
                if preserved_support_state == "adequate" and directive_state == "blocked_for_support":
                    preserved_support_state = (
                        "commercial_source_acquisition_required"
                        if metadata_uncovered_requested_ids
                        else "blocked_for_support"
                    )
                    preserved_support_reason = (
                        "source_backed_rows_required"
                        if metadata_uncovered_requested_ids
                        else "directive_not_requeued_after_fixture_materialization"
                    )
                    preserved_uncovered = metadata_uncovered_requested_ids
                row.update(
                    {
                        "directive_state": directive_state,
                        "task_state": preserved_state,
                        "active_child_run_id": active_child_id,
                        "active_child_run_ids": [active_child_id] if active_child_id else [],
                        "support_admission_state": preserved_support_state,
                        "support_admission_blocker_reason": preserved_support_reason,
                        "support_admission_request_id": preserved_support_request_id,
                        "provider_field_lane_request_id": metadata_provider_field_lane_request_id,
                        "support_admission_provider_field_lane_request_id": metadata_provider_field_lane_request_id,
                        "support_admission_uncovered_fields": preserved_uncovered,
                        "visible_fixture_materialization_state": "materialized",
                        "visible_fixture_materialized_requested_row_ids": list(
                            support.get("visible_fixture_materialized_requested_row_ids", []) or []
                        ),
                        "visible_fixture_unmaterialized_requested_row_ids": [],
                        "fixture_support_materialized_but_admission_blocked": True,
                        "fixture_support_admission_blocker_reason": (
                            "directive_not_requeued_after_fixture_materialization"
                        ),
                        "updated_at": now,
                        "snapshot_row_refreshed_by": "bounded_support_tick_fixture_materialization_cached_refresh",
                    }
                )
                directive_tasks.append(row)
                refreshed_directive_ids.append(directive_id)
                continue
            commercial_blocker_still_active = (
                bool(metadata.get("commercial_source_acquisition_required", False))
                or bool(metadata.get("source_backed_rows_required", False))
                or existing_support_state in {
                    "commercial_source_acquisition_required",
                    "source_backed_rows_required",
                    "insufficient_role_lane_coverage",
                    "insufficient_requested_row_coverage",
                }
            ) and bool(metadata_uncovered_requested_ids or row.get("support_admission_uncovered_fields", []))
            if commercial_blocker_still_active and existing_target != "validation_fixtures.json":
                row.update(
                    {
                        "visible_fixture_materialization_state": "materialized",
                        "visible_fixture_materialized_requested_row_ids": list(
                            support.get("visible_fixture_materialized_requested_row_ids", []) or []
                        ),
                        "visible_fixture_unmaterialized_requested_row_ids": [],
                        "support_admission_request_id": preserved_support_request_id,
                        "provider_field_lane_request_id": metadata_provider_field_lane_request_id,
                        "support_admission_provider_field_lane_request_id": metadata_provider_field_lane_request_id,
                        "fixture_support_materialized_but_admission_blocked": True,
                        "fixture_support_admission_blocker_reason": "commercial_source_rows_still_required",
                        "updated_at": now,
                        "snapshot_row_refreshed_by": "bounded_support_tick_fixture_materialization_cached_refresh",
                    }
                )
                directive_tasks.append(row)
                refreshed_directive_ids.append(directive_id)
                continue
            row.update(
                {
                    "directive_state": directive_state,
                    "task_state": "running" if active_child_id else "eligible",
                    "active_child_run_id": active_child_id,
                    "active_child_run_ids": [active_child_id] if active_child_id else [],
                    "pending_support": False,
                    "support_admission_state": "adequate",
                    "support_admission_blocker_reason": "",
                    "support_admission_uncovered_fields": [],
                    "support_admission_request_id": str(support.get("support_request_id", "") or ""),
                    "support_materialization_pending_reason": "",
                    "support_materialization_pending_requested_row_ids": [],
                    "support_materialization_closure_state": "closed",
                    "target_artifact": "validation_fixtures.json",
                    "support_materialization_state": "visible_fixture_rows_materialized",
                    "visible_fixture_materialization_state": "materialized",
                    "visible_fixture_materialized_requested_row_ids": list(
                        support.get("visible_fixture_materialized_requested_row_ids", []) or []
                    ),
                    "visible_fixture_unmaterialized_requested_row_ids": [],
                    "updated_at": now,
                    "snapshot_row_refreshed_by": "bounded_support_tick_fixture_materialization_cached_refresh",
                    "initial_work_order_target_artifact": str(
                        metadata.get("initial_work_order_target_artifact", "")
                        or "validation_fixtures.json"
                    ),
                }
            )
            refreshed_directive_ids.append(directive_id)
        directive_tasks.append(row)
    if not refreshed_directive_ids:
        return {
            "snapshot_refresh_state": "not_required",
            "snapshot_refreshed_by": "",
            "snapshot_refreshed_directive_ids": [],
        }
    refreshed["directive_tasks"] = directive_tasks
    refreshed["active_child_count"] = len(
        [
            task
            for task in directive_tasks
            if str(task.get("task_state", "") or "") in {"running", "leased"}
        ]
    )
    refreshed["admissible_directives"] = [
        dict(task)
        for task in directive_tasks
        if str(task.get("task_state", "") or "") == "eligible"
    ]
    refreshed["admissible_directive_count"] = len(refreshed["admissible_directives"])
    refreshed["support_blocked_directive_count"] = len(
        [
            task
            for task in directive_tasks
            if str(task.get("task_state", "") or "") == "blocked_for_support"
        ]
    )
    _write_json(_conveyor_root(operator_root) / "task_manager" / "snapshot_latest.json", refreshed)
    persist_bounded_status_snapshot(
        operator_root,
        task_manager_snapshot=refreshed,
        refreshed_by="bounded_support_tick_fixture_materialization_cached_refresh",
    )
    return {
        "snapshot_refresh_state": "completed",
        "snapshot_refreshed_by": "bounded_support_tick_fixture_materialization_cached_refresh",
        "snapshot_refreshed_directive_ids": list(dict.fromkeys(refreshed_directive_ids)),
    }


def _latest_terminal_child_for_directive(
    operator_root: str | Path,
    directive_id: str,
) -> dict[str, Any]:
    latest_child: dict[str, Any] = {}
    latest_mtime = -1.0
    for path in _children_root(operator_root).glob("*.json"):
        child = _read_json(path)
        if str(child.get("directive_id", "") or "") != str(directive_id or ""):
            continue
        if str(child.get("state", "") or "") not in {"failed", "stopped"}:
            continue
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0.0
        if mtime > latest_mtime:
            latest_mtime = mtime
            latest_child = child
    return latest_child


def _append_resident_no_delta_followup_closure_evidence(
    operator_root: str | Path,
    *,
    directive_id: str,
    latest_progress: Mapping[str, Any],
    followup_target_artifact: str,
) -> dict[str, Any]:
    target_artifact = _resident_target_artifact_from_progress(latest_progress)
    if not directive_id or not target_artifact or not followup_target_artifact:
        return {}
    closed_rows = [
        str(item or "").strip()
        for item in list(
            latest_progress.get("validation_fixture_closed_requested_row_ids", [])
            or latest_progress.get("visible_fixture_materialized_requested_row_ids", [])
            or []
        )
        if str(item or "").strip()
    ]
    closure_evidence = {
        "schema_name": "TargetArtifactClosureEvidence",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "directive_id": directive_id,
        "target_artifact": target_artifact,
        "target_artifact_closure_state": "partial_closed_linked_artifacts_remaining",
        "closed_target_artifact": target_artifact,
        "closed_fields": [
            "equipment",
            "fixture_wiring",
            "calibration_steps",
            "measurement_method",
            "pass_fail_thresholds",
            "linked_bom_refs",
            "linked_risk_control_refs",
            "execution_gate",
        ],
        "closed_requested_row_ids": closed_rows,
        "remaining_linked_artifact_gaps": [followup_target_artifact],
        "remaining_artifacts": [followup_target_artifact],
        "next_linked_artifact_target": followup_target_artifact,
        "partial_target_correct_closure": True,
        "hardware_build_packet_ready": False,
        "resident_support_backed_no_delta_finalized": True,
        "grants_execution_authority": False,
    }
    closure_evidence["target_artifact_closure_evidence_id"] = _record_id(
        "target-artifact-closure",
        directive_id,
        target_artifact,
        ",".join(closed_rows),
        followup_target_artifact,
    )
    latest_path = _conveyor_root(operator_root) / "target_artifact_closure_evidence_latest.json"
    latest = _read_json(latest_path)
    if str(latest.get("target_artifact_closure_evidence_id", "") or "") != str(
        closure_evidence["target_artifact_closure_evidence_id"]
    ):
        _append_ledger(operator_root, "target_artifact_closure_evidence", closure_evidence)
        _write_json(latest_path, closure_evidence)
    return closure_evidence


def repair_resident_no_delta_followup_targets(operator_root: str | Path) -> dict[str, Any]:
    repaired_directive_ids: list[str] = []
    for directive_path in _directives_root(operator_root).glob("*.json"):
        directive = _read_json(directive_path)
        directive_id = str(directive.get("directive_id", "") or directive_path.stem or "").strip()
        if not directive_id:
            continue
        metadata = dict(directive.get("metadata", {}) or {})
        if not bool(metadata.get("resident_support_backed_no_delta_finalized", False)):
            continue
        if bool(metadata.get("resident_no_delta_followup_ready", False)):
            continue
        latest_child = _latest_terminal_child_for_directive(operator_root, directive_id)
        latest_progress = dict(latest_child.get("latest_progress", {}) or {})
        if not latest_progress:
            latest_progress = _latest_child_progress(latest_child)
        followup_target = _resident_no_delta_followup_target(latest_progress)
        followup_repair_reason = "linked_hardware_dossier_not_complete"
        if not followup_target:
            support_followup = _resident_no_delta_followup_from_visible_fixture_support(
                operator_root,
                directive=directive,
                metadata=metadata,
            )
            followup_target = str(support_followup.get("followup_target_artifact", "") or "").strip()
            if followup_target:
                followup_repair_reason = str(
                    support_followup.get("resident_no_delta_followup_repair_reason", "")
                    or "visible_fixture_support_already_materialized"
                )
                latest_progress = {
                    **dict(latest_progress or {}),
                    "target_artifact": str(support_followup.get("target_artifact", "") or "validation_fixtures.json"),
                    "validation_fixture_materialization_state": "materialized",
                    "visible_fixture_materialization_state": "materialized",
                    "support_materialization_state": "visible_fixture_rows_materialized",
                    "validation_fixture_closed_requested_row_ids": list(
                        support_followup.get("visible_fixture_materialized_requested_row_ids", []) or []
                    ),
                    "visible_fixture_materialized_requested_row_ids": list(
                        support_followup.get("visible_fixture_materialized_requested_row_ids", []) or []
                    ),
                    "validation_fixture_unclosed_requested_row_ids": [],
                    "visible_fixture_unmaterialized_requested_row_ids": [],
                    "remaining_failed_gates": ["linked_hardware_dossier_not_complete"],
                    "hardware_build_packet_ready_candidate": False,
                    "grants_execution_authority": False,
                }
        if not followup_target:
            continue
        metadata["resident_no_delta_followup_ready"] = True
        metadata["resident_no_delta_followup_target_artifact"] = followup_target
        metadata["resident_no_delta_followup_reason"] = "linked_hardware_dossier_not_complete"
        metadata["resident_no_delta_followup_repair_reason"] = followup_repair_reason
        metadata["next_unresolved_artifact"] = followup_target
        metadata["initial_work_order_target_artifact"] = followup_target
        metadata["continuous_campaign_latest_target_artifact"] = followup_target
        metadata["support_blocker_target_artifact"] = followup_target
        metadata["support_blocker_reason"] = ""
        metadata["support_admission_state"] = "not_required"
        metadata["next_support_recovery_action"] = "bounded_scheduler_dossier_synthesis"
        directive["metadata"] = metadata
        directive["state"] = "requeued"
        directive["blocked_reason"] = ""
        directive["active_child_run_id"] = ""
        directive["updated_at"] = _utc_now()
        _write_json(directive_path, directive)
        _append_resident_no_delta_followup_closure_evidence(
            operator_root,
            directive_id=directive_id,
            latest_progress=latest_progress,
            followup_target_artifact=followup_target,
        )
        repaired_directive_ids.append(directive_id)
    return {
        "schema_name": "ResidentNoDeltaFollowupRepair",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "resident_no_delta_followup_repaired_count": len(repaired_directive_ids),
        "resident_no_delta_followup_repaired_directive_ids": repaired_directive_ids,
        "grants_execution_authority": False,
    }


def _current_reviewable_return_exists_for_directive(
    operator_root: str | Path,
    directive_id: str,
) -> bool:
    if not directive_id:
        return False
    for path in _returns_root(operator_root).glob("*.json"):
        packet = _read_json(path)
        if str(packet.get("directive_id", "") or "") != directive_id:
            continue
        if str(packet.get("review_state", "") or "") != "pending_operator_review":
            continue
        if bool(packet.get("non_reviewable_pass_result", False)):
            continue
        if bool(packet.get("non_reviewable_malformed_return", False)):
            continue
        if bool(packet.get("superseded_by_current_directive_state", False)):
            continue
        return True
    return False


def _repair_active_resident_no_delta_followup_work_order(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    if not child_id or not directive_id:
        return {"ok": False, "repair_state": "missing_child_or_directive"}
    if str(child.get("state", "") or "") != "running":
        return {"ok": False, "repair_state": "child_not_running"}
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        return {"ok": False, "repair_state": "not_resident_campaign_child"}
    directive_path = _directive_path(operator_root, directive_id)
    directive = _read_json(directive_path)
    metadata = dict(directive.get("metadata", {}) or {})
    if not bool(metadata.get("resident_no_delta_followup_ready", False)):
        return {"ok": False, "repair_state": "followup_not_ready"}
    followup_target = str(metadata.get("resident_no_delta_followup_target_artifact", "") or "").strip()
    if not followup_target:
        return {"ok": False, "repair_state": "followup_target_missing"}
    content_depth_target = str(metadata.get("implementation_readiness_content_depth_target_artifact", "") or "").strip()
    if (
        bool(metadata.get("implementation_readiness_content_depth_repaired", False))
        and content_depth_target
        and followup_target == "implementation_readiness_review.json"
    ):
        return {
            "ok": False,
            "repair_state": "content_depth_repair_already_active",
            "content_depth_target_artifact": content_depth_target,
        }
    progress_target = _resident_target_artifact_from_progress(latest_progress)
    current_target = (
        progress_target
        or str(child.get("latest_work_order_target_artifact", "") or child.get("latest_target_artifact", "") or "").strip()
    )
    inbox_payload = _read_json(_child_inbox_path(child))
    inbox_work_order = _latest_inbox_work_order(inbox_payload)
    inbox_target = str(inbox_work_order.get("target_artifact", "") or "").strip()
    if current_target == followup_target and (not inbox_target or inbox_target == followup_target):
        return {"ok": False, "repair_state": "followup_work_order_already_current"}
    if _current_reviewable_return_exists_for_directive(operator_root, directive_id):
        return {"ok": False, "repair_state": "current_reviewable_return_present"}
    no_delta_signals = {
        str(latest_progress.get("blocked_reason", "") or "").strip(),
        str(latest_progress.get("cycle_outcome", "") or "").strip(),
        str(latest_progress.get("progress_state", "") or "").strip(),
    }
    if (
        "no_artifact_delta" not in no_delta_signals
        and str(latest_progress.get("blocked_reason", "") or "").strip() != "no_artifact_delta"
        and not list(latest_progress.get("resident_self_final_return_blockers", []) or [])
    ):
        return {"ok": False, "repair_state": "no_followup_trigger_progress"}
    reason = str(metadata.get("resident_no_delta_followup_reason", "") or "linked_hardware_dossier_not_complete")
    work_order = _append_resident_work_order(
        operator_root,
        state_root=state_root or operator_root,
        child=child,
        latest_progress=latest_progress,
        target_artifact=followup_target,
        reason=(
            f"Resident no-delta follow-up is ready after {current_target or 'the previous artifact'}; "
            f"continue with {followup_target} for {reason}."
        ),
        target_delta_required=True,
    )
    now = _utc_now()
    updated_child = dict(_read_json(_child_path(operator_root, child_id)) or child)
    updated_child["resident_no_delta_followup_work_order_repaired"] = True
    updated_child["resident_no_delta_followup_work_order_repair_state"] = "completed"
    updated_child["resident_no_delta_followup_work_order_repaired_at"] = now
    updated_child["resident_no_delta_followup_work_order_id"] = str(work_order.get("work_order_id", "") or "")
    updated_child["resident_no_delta_followup_target_artifact"] = followup_target
    updated_child["resident_no_delta_followup_previous_target_artifact"] = current_target
    updated_child["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
    updated_child["latest_work_order_target_artifact"] = followup_target
    updated_child["latest_work_order_at"] = str(work_order.get("generated_at", "") or now)
    updated_child["latest_work_order"] = dict(work_order)
    updated_child["resident_worker_state"] = "resident_no_delta_followup_work_order_repaired"
    updated_child["updated_at"] = now
    _write_json(_child_path(operator_root, child_id), updated_child)
    if directive:
        metadata["resident_no_delta_followup_work_order_repaired"] = True
        metadata["resident_no_delta_followup_work_order_id"] = str(work_order.get("work_order_id", "") or "")
        metadata["resident_no_delta_followup_target_artifact"] = followup_target
        metadata["initial_work_order_target_artifact"] = followup_target
        metadata["continuous_campaign_latest_target_artifact"] = followup_target
        metadata["support_blocker_target_artifact"] = followup_target
        metadata["support_admission_state"] = "not_required"
        metadata["support_blocker_reason"] = ""
        metadata["next_support_recovery_action"] = "bounded_scheduler_dossier_synthesis"
        directive["metadata"] = metadata
        directive["updated_at"] = now
        _write_json(directive_path, directive)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_no_delta_followup_work_order_repaired",
            "generated_at": now,
            "child_run_id": child_id,
            "directive_id": directive_id,
            "previous_target_artifact": current_target,
            "target_artifact": followup_target,
            "work_order_id": str(work_order.get("work_order_id", "") or ""),
            "pending_return_created": False,
            "grants_execution_authority": False,
        },
    )
    return {
        "ok": True,
        "repair_state": "completed",
        "child_run_id": child_id,
        "directive_id": directive_id,
        "previous_target_artifact": current_target,
        "target_artifact": followup_target,
        "work_order_id": str(work_order.get("work_order_id", "") or ""),
    }


def _repair_implementation_readiness_content_depth_work_order(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    if not child_id or not directive_id:
        return {"ok": False, "repair_state": "missing_child_or_directive"}
    if str(child.get("state", "") or "") != "running":
        return {"ok": False, "repair_state": "child_not_running"}
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        return {"ok": False, "repair_state": "not_resident_campaign_child"}
    target_artifact = _resident_target_artifact_from_progress(latest_progress)
    if target_artifact != "implementation_readiness_review.json":
        return {"ok": False, "repair_state": "not_implementation_readiness_review"}
    if str(latest_progress.get("visible_dossier_closure_state", "") or "") != "visible_closure_reviewable":
        return {"ok": False, "repair_state": "visible_dossier_not_reviewable"}
    if bool(latest_progress.get("grants_execution_authority", False)):
        return {"ok": False, "repair_state": "execution_authority_granted"}
    current_child_target = str(
        child.get("latest_work_order_target_artifact", "") or child.get("latest_target_artifact", "") or ""
    ).strip()
    if current_child_target and current_child_target != "implementation_readiness_review.json":
        return {"ok": False, "repair_state": "child_already_retargeted"}
    blockers = {
        str(item or "").strip()
        for item in list(latest_progress.get("resident_self_final_return_blockers", []) or [])
        if str(item or "").strip()
    }
    support_candidate = latest_progress.get("support_request_candidate", {})
    support_candidate_reason = (
        str(support_candidate.get("reason", "") or "") if isinstance(support_candidate, Mapping) else ""
    )
    generic_support_blocked = (
        str(latest_progress.get("sleep_reason", "") or "") == "waiting_for_support_pack_evidence"
        and str(latest_progress.get("blocked_reason", "") or "") == "no_artifact_delta"
        and "no consumable source-backed support rows for implementation_readiness_review.json"
        in support_candidate_reason
    )
    depth_placeholder_blocked = bool(
        blockers.intersection(
            {
                "technical_depth_contract_generic_placeholders",
                "depth_obligation_requires_post_obligation_target_delta",
                "no_artifact_delta",
            }
        )
    )
    if not (generic_support_blocked or depth_placeholder_blocked):
        return {"ok": False, "repair_state": "no_content_depth_repair_signal"}
    directive_path = _directive_path(operator_root, directive_id)
    directive = _read_json(directive_path)
    manifest = _read_json(_campaign_manifest_path(operator_root, directive_id))
    content_target = _preferred_content_depth_target(manifest) or "technical_documentation.md"
    if content_target == "implementation_readiness_review.json":
        content_target = "technical_documentation.md"
    reason = (
        "Implementation-readiness review has visible dossier closure but remains blocked by generic "
        "technical-depth placeholders or non-consumable implementation-readiness support. Retarget the "
        f"resident child to {content_target} so it can deepen the dossier from visible BOM/risk/fixture evidence."
    )
    work_order = _append_resident_work_order(
        operator_root,
        state_root=state_root or operator_root,
        child=child,
        latest_progress=latest_progress,
        target_artifact=content_target,
        reason=reason,
        target_delta_required=True,
    )
    now = _utc_now()
    updated_child = dict(_read_json(_child_path(operator_root, child_id)) or child)
    updated_child["implementation_readiness_content_depth_repaired"] = True
    updated_child["implementation_readiness_content_depth_repair_state"] = "completed"
    updated_child["implementation_readiness_content_depth_repaired_at"] = now
    updated_child["implementation_readiness_content_depth_repair_reason"] = (
        "visible_dossier_reviewable_but_generic_depth_or_support_blocked"
    )
    updated_child["implementation_readiness_content_depth_target_artifact"] = content_target
    updated_child["implementation_readiness_content_depth_work_order_id"] = str(
        work_order.get("work_order_id", "") or ""
    )
    updated_child["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
    updated_child["latest_work_order_target_artifact"] = content_target
    updated_child["latest_work_order_at"] = str(work_order.get("generated_at", "") or now)
    updated_child["latest_work_order"] = dict(work_order)
    updated_child["resident_worker_state"] = "implementation_readiness_content_depth_repaired"
    updated_child["updated_at"] = now
    _write_json(_child_path(operator_root, child_id), updated_child)
    if directive:
        metadata = dict(directive.get("metadata", {}) or {})
        metadata["implementation_readiness_content_depth_repaired"] = True
        metadata["implementation_readiness_content_depth_target_artifact"] = content_target
        metadata["implementation_readiness_content_depth_work_order_id"] = str(
            work_order.get("work_order_id", "") or ""
        )
        metadata["implementation_readiness_content_depth_repair_reason"] = (
            "visible_dossier_reviewable_but_generic_depth_or_support_blocked"
        )
        metadata["initial_work_order_target_artifact"] = content_target
        metadata["continuous_campaign_latest_target_artifact"] = content_target
        metadata["support_blocker_target_artifact"] = content_target
        metadata["support_admission_state"] = "not_required"
        metadata["support_blocker_reason"] = ""
        metadata["next_support_recovery_action"] = "resident_content_depth_retarget"
        directive["metadata"] = metadata
        directive["updated_at"] = now
        _write_json(directive_path, directive)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "implementation_readiness_content_depth_repaired",
            "generated_at": now,
            "child_run_id": child_id,
            "directive_id": directive_id,
            "previous_target_artifact": "implementation_readiness_review.json",
            "target_artifact": content_target,
            "work_order_id": str(work_order.get("work_order_id", "") or ""),
            "repair_reason": "visible_dossier_reviewable_but_generic_depth_or_support_blocked",
            "pending_return_created": False,
            "grants_execution_authority": False,
        },
    )
    return {
        "ok": True,
        "repair_state": "completed",
        "child_run_id": child_id,
        "directive_id": directive_id,
        "target_artifact": content_target,
        "work_order_id": str(work_order.get("work_order_id", "") or ""),
    }


def _technical_documentation_depth_quality(
    operator_root: str | Path,
    directive_id: str,
    directive: Mapping[str, Any],
) -> dict[str, Any]:
    draft_path = _campaign_drafts_root(operator_root, directive_id) / "technical_documentation.md"
    if not draft_path.exists():
        return {"ok": False, "quality_state": "missing_draft", "failed_gates": []}
    assessment = assess_conveyor_artifact_quality(
        "technical_documentation.md",
        draft_path,
        directive_title=_directive_display_title(directive) if directive else "",
    )
    failed_gates = [
        str(item).strip()
        for item in list(assessment.get("failed_gates", []) or [])
        if str(item).strip()
    ]
    return {
        "ok": bool(failed_gates),
        "quality_state": str(assessment.get("quality_state", "") or ""),
        "quality_depth_score": float(assessment.get("quality_depth_score", 0.0) or 0.0),
        "failed_gates": failed_gates,
        "passed_gates": list(assessment.get("passed_gates", []) or []),
        "metrics": dict(assessment.get("metrics", {}) or {}),
    }


def _refresh_technical_documentation_quality_manifest(
    operator_root: str | Path,
    directive_id: str,
    quality: Mapping[str, Any],
) -> None:
    manifest_path = _campaign_manifest_path(operator_root, directive_id)
    manifest = _read_json(manifest_path)
    if not manifest:
        manifest = {
            "schema_name": "ConveyorCampaignManifest",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "directive_id": directive_id,
            "generated_at": _utc_now(),
        }
    canonical = dict(manifest.get("canonical_artifacts", {}) or {})
    existing = dict(canonical.get("technical_documentation.md", {}) or {})
    existing.update(
        {
            "artifact_name": "technical_documentation.md",
            "quality_state": str(quality.get("quality_state", "") or ""),
            "quality_depth_score": float(quality.get("quality_depth_score", 0.0) or 0.0),
            "failed_quality_gates": list(quality.get("failed_gates", []) or []),
            "passed_quality_gates": list(quality.get("passed_gates", []) or []),
            "quality_metrics": dict(quality.get("metrics", {}) or {}),
            "quality_refreshed_by": "bounded_technical_documentation_depth_repair",
            "quality_refreshed_at": _utc_now(),
        }
    )
    canonical["technical_documentation.md"] = existing
    manifest["canonical_artifacts"] = canonical
    manifest["updated_at"] = _utc_now()
    _write_json(manifest_path, manifest)


def _repair_technical_documentation_depth_work_order(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    if not child_id or not directive_id:
        return {"ok": False, "repair_state": "missing_child_or_directive"}
    if str(child.get("state", "") or "") != "running":
        return {"ok": False, "repair_state": "child_not_running"}
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        return {"ok": False, "repair_state": "not_resident_campaign_child"}
    target_artifact = _resident_target_artifact_from_progress(latest_progress)
    if target_artifact != "technical_documentation.md":
        return {"ok": False, "repair_state": "not_technical_documentation"}
    no_delta_signals = {
        str(latest_progress.get("blocked_reason", "") or "").strip(),
        str(latest_progress.get("cycle_outcome", "") or "").strip(),
        str(latest_progress.get("progress_state", "") or "").strip(),
        *[
            str(item or "").strip()
            for item in list(latest_progress.get("resident_self_final_return_blockers", []) or [])
            if str(item or "").strip()
        ],
    }
    if "no_artifact_delta" not in no_delta_signals and "technical_depth_contract_generic_placeholders" not in no_delta_signals:
        return {"ok": False, "repair_state": "no_technical_depth_plateau_signal"}
    directive_path = _directive_path(operator_root, directive_id)
    directive = _read_json(directive_path)
    quality = _technical_documentation_depth_quality(operator_root, directive_id, directive)
    failed_gates = [
        str(item).strip()
        for item in list(quality.get("failed_gates", []) or [])
        if str(item).strip()
    ]
    if not failed_gates:
        return {"ok": False, "repair_state": "technical_documentation_quality_clean_or_unknown"}
    gate_signature = ",".join(sorted(dict.fromkeys(failed_gates)))
    inbox_payload = _read_json(_child_inbox_path(child))
    latest_work_order = _latest_inbox_work_order(inbox_payload)
    latest_gates = {
        str(item).strip()
        for item in list(latest_work_order.get("required_gate_closures", []) or [])
        if str(item).strip()
    }
    if (
        str(latest_work_order.get("target_artifact", "") or "") == "technical_documentation.md"
        and set(failed_gates).issubset(latest_gates)
        and str(child.get("technical_documentation_depth_gate_signature", "") or "") == gate_signature
    ):
        return {"ok": False, "repair_state": "technical_documentation_depth_work_order_already_current"}
    _refresh_technical_documentation_quality_manifest(operator_root, directive_id, quality)
    reason = (
        "Technical documentation plateaued without a new artifact delta. Close the current evaluator gates "
        f"{failed_gates} by adding directive-specific named modules, expected files, fixture references, "
        "handoff thresholds, go/no-go criteria, and evidence-backed build-depth details."
    )
    work_order = _append_resident_work_order(
        operator_root,
        state_root=state_root or operator_root,
        child=child,
        latest_progress=latest_progress,
        target_artifact="technical_documentation.md",
        reason=reason,
        target_delta_required=True,
    )
    work_order = dict(work_order)
    merged_gates = list(
        dict.fromkeys(
            [
                *[
                    str(item).strip()
                    for item in list(work_order.get("required_gate_closures", []) or [])
                    if str(item).strip()
                ],
                *failed_gates,
            ]
        )
    )
    work_order["required_gate_closures"] = merged_gates
    work_order["quality_failed_gates"] = merged_gates
    work_order["source_failed_quality_gates"] = merged_gates
    work_order["quality_state"] = str(quality.get("quality_state", "") or "")
    work_order["quality_depth_score"] = float(quality.get("quality_depth_score", 0.0) or 0.0)
    gate_guidance = _quality_gate_guidance(merged_gates)
    if gate_guidance and gate_guidance not in str(work_order.get("next_step_context", "") or ""):
        work_order["next_step_context"] = (
            f"{work_order.get('next_step_context', '')} {gate_guidance}"
        ).strip()
    work_order["technical_documentation_depth_followup_required"] = True
    work_order["technical_documentation_depth_failed_gates"] = merged_gates
    work_order["work_order_signature"] = _resident_work_order_signature(work_order)
    inbox_path = _child_inbox_path(child)
    inbox_payload = _read_json(inbox_path)
    messages: list[dict[str, Any]] = []
    replaced = False
    for message in list(inbox_payload.get("messages", []) or []):
        if (
            isinstance(message, Mapping)
            and str(message.get("kind", "") or "") == "kernel_work_order"
            and str(message.get("work_order_id", "") or "") == str(work_order.get("work_order_id", "") or "")
        ):
            messages.append(dict(work_order))
            replaced = True
        elif isinstance(message, Mapping):
            messages.append(dict(message))
    if not replaced:
        messages.append(dict(work_order))
    inbox_payload["messages"] = messages
    inbox_payload["updated_at"] = _utc_now()
    inbox_payload = _compact_resident_inbox_work_orders(inbox_payload)
    _request_resident_child_wake(
        operator_root,
        child=child,
        inbox_payload=inbox_payload,
        inbox_path=inbox_path,
        work_order=work_order,
        wake_reason="quality_support_injected",
        force=True,
    )
    now = _utc_now()
    updated_child = dict(_read_json(_child_path(operator_root, child_id)) or child)
    updated_child["technical_documentation_depth_repaired"] = True
    updated_child["technical_documentation_depth_repair_state"] = "completed"
    updated_child["technical_documentation_depth_repaired_at"] = now
    updated_child["technical_documentation_depth_gate_signature"] = gate_signature
    updated_child["technical_documentation_depth_failed_gates"] = failed_gates
    updated_child["technical_documentation_depth_work_order_id"] = str(work_order.get("work_order_id", "") or "")
    updated_child["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
    updated_child["latest_work_order_target_artifact"] = "technical_documentation.md"
    updated_child["latest_work_order_at"] = str(work_order.get("generated_at", "") or now)
    updated_child["latest_work_order"] = dict(work_order)
    updated_child["resident_worker_state"] = "technical_documentation_depth_repaired"
    updated_child["updated_at"] = now
    _write_json(_child_path(operator_root, child_id), updated_child)
    if directive:
        metadata = dict(directive.get("metadata", {}) or {})
        metadata["technical_documentation_depth_repaired"] = True
        metadata["technical_documentation_depth_work_order_id"] = str(work_order.get("work_order_id", "") or "")
        metadata["technical_documentation_depth_gate_signature"] = gate_signature
        metadata["technical_documentation_depth_failed_gates"] = failed_gates
        metadata["initial_work_order_target_artifact"] = "technical_documentation.md"
        metadata["continuous_campaign_latest_target_artifact"] = "technical_documentation.md"
        metadata["support_blocker_target_artifact"] = "technical_documentation.md"
        metadata["support_admission_state"] = "not_required"
        metadata["support_blocker_reason"] = ""
        metadata["next_support_recovery_action"] = "resident_technical_documentation_depth_followup"
        directive["metadata"] = metadata
        directive["updated_at"] = now
        _write_json(directive_path, directive)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "technical_documentation_depth_repaired",
            "generated_at": now,
            "child_run_id": child_id,
            "directive_id": directive_id,
            "target_artifact": "technical_documentation.md",
            "failed_gates": failed_gates,
            "work_order_id": str(work_order.get("work_order_id", "") or ""),
            "pending_return_created": False,
            "grants_execution_authority": False,
        },
    )
    return {
        "ok": True,
        "repair_state": "completed",
        "child_run_id": child_id,
        "directive_id": directive_id,
        "target_artifact": "technical_documentation.md",
        "failed_gates": failed_gates,
        "work_order_id": str(work_order.get("work_order_id", "") or ""),
    }


def _technical_documentation_depth_plateau_finalizer_eligible(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> tuple[bool, list[str], list[str]]:
    blockers: list[str] = []
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        blockers.append("not_resident_campaign_child")
    if str(child.get("state", "") or "") != "running":
        blockers.append("child_not_running")
    if _resident_target_artifact_from_progress(latest_progress) != "technical_documentation.md":
        blockers.append("not_technical_documentation")
    if not bool(child.get("technical_documentation_depth_repaired", False)):
        blockers.append("technical_documentation_depth_followup_not_attempted")
    inbox_payload = _read_json(_child_inbox_path(child))
    latest_work_order = _latest_inbox_work_order(inbox_payload)
    work_order_gates = [
        str(item).strip()
        for item in list(latest_work_order.get("required_gate_closures", []) or [])
        if str(item).strip()
    ]
    if str(latest_work_order.get("target_artifact", "") or "") != "technical_documentation.md":
        blockers.append("latest_work_order_not_technical_documentation")
    if not bool(latest_work_order.get("technical_documentation_depth_followup_required", False)):
        blockers.append("technical_documentation_depth_work_order_not_focused")
    changed_this_cycle = bool(
        latest_progress.get("meaningful_delta", False)
        or latest_progress.get("support_to_artifact_delta", False)
        or latest_progress.get("support_to_artifact_required_field_delta", False)
    )
    try:
        artifact_delta_count = int(latest_progress.get("artifact_delta_count", 0) or 0)
    except (TypeError, ValueError):
        artifact_delta_count = 0
    if changed_this_cycle or artifact_delta_count > 0:
        blockers.append("meaningful_delta_present")
    blocked_reason = str(latest_progress.get("blocked_reason", "") or "").strip()
    cycle_outcome = str(latest_progress.get("cycle_outcome", "") or "").strip()
    if blocked_reason != "no_artifact_delta" and cycle_outcome not in {"blocked", "no_artifact_delta"}:
        blockers.append("latest_progress_not_no_delta_blocked")
    if bool(latest_progress.get("hardware_build_packet_ready_candidate", False)):
        blockers.append("review_ready_checkpoint_should_return")
    outbox_packet = _child_outbox_return_packet_path(child)
    if outbox_packet is not None and outbox_packet.exists():
        blockers.append("return_packet_present")
    if _resident_progress_indicates_mount_fault(latest_progress):
        blockers.append("mount_or_runtime_fault_detected")
    directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    quality = _technical_documentation_depth_quality(operator_root, directive_id, directive)
    failed_gates = [
        str(item).strip()
        for item in list(quality.get("failed_gates", []) or [])
        if str(item).strip()
    ]
    if not failed_gates:
        blockers.append("technical_documentation_quality_clean_or_unknown")
    prior_signature = str(child.get("technical_documentation_depth_gate_signature", "") or "").strip()
    current_signature = ",".join(sorted(dict.fromkeys(failed_gates)))
    if prior_signature and current_signature != prior_signature:
        blockers.append("technical_documentation_gate_signature_changed")
    if work_order_gates and not set(work_order_gates).issubset(set(failed_gates)):
        blockers.append("focused_gate_closure_partially_changed")
    if not child_id or not directive_id:
        blockers.append("missing_child_or_directive")
    return not blockers, blockers, failed_gates


def _finalize_technical_documentation_depth_plateau(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    runner: ConveyorChildRunner,
) -> dict[str, Any] | None:
    eligible, blockers, failed_gates = _technical_documentation_depth_plateau_finalizer_eligible(
        operator_root,
        child=child,
        latest_progress=latest_progress,
    )
    updated = dict(child)
    updated["technical_documentation_depth_plateau_finalizer_blockers"] = blockers
    updated["technical_documentation_depth_plateau_finalizer_eligible"] = eligible
    child_id = str(updated.get("child_run_id", "") or "").strip()
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated)
    if not eligible:
        return None
    checkpoint_path = _child_progress_checkpoint_path(updated)
    before_mtime = 0.0
    if checkpoint_path is not None and checkpoint_path.exists():
        try:
            before_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            before_mtime = 0.0
    before_hash = _progress_checkpoint_hash(latest_progress) if latest_progress else ""
    fresh_progress = _latest_child_progress(updated)
    fresh_hash = _progress_checkpoint_hash(fresh_progress) if fresh_progress else ""
    after_mtime = before_mtime
    if checkpoint_path is not None and checkpoint_path.exists():
        try:
            after_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            after_mtime = before_mtime
    fresh_eligible, fresh_blockers, fresh_failed_gates = _technical_documentation_depth_plateau_finalizer_eligible(
        operator_root,
        child=updated,
        latest_progress=fresh_progress,
    )
    if fresh_hash != before_hash or after_mtime != before_mtime or not fresh_eligible:
        updated["technical_documentation_depth_plateau_finalizer_suppressed"] = True
        updated["technical_documentation_depth_plateau_finalizer_suppressed_reason"] = "fresh_progress_checkpoint_observed"
        updated["technical_documentation_depth_plateau_finalizer_blockers"] = fresh_blockers
        updated["updated_at"] = _utc_now()
        if child_id:
            _write_json(_child_path(operator_root, child_id), updated)
        return None
    try:
        stop_result = dict(runner.stop_child_container(dict(updated)) or {})
    except Exception as exc:
        stop_result = {"ok": False, "state": "stop_failed", "error_class": type(exc).__name__, "error": str(exc)}
    directive_id = str(updated.get("directive_id", "") or "").strip()
    work_order_id = str(fresh_progress.get("work_order_id", "") or updated.get("latest_work_order_id", "") or "")
    lifecycle = {
        "schema_name": "ChildLifecycleAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "child_run_id": child_id,
        "directive_id": directive_id,
        "child_lifecycle_classification": "blocked_pass_completed_not_review_ready",
        "container_exit_code": "",
        "productive_pass_delta_observed": False,
        "productive_pass_completed_not_review_ready": False,
        "blocked_pass_completed_not_review_ready": True,
        "productive_pass_target_artifact": "technical_documentation.md",
        "next_unresolved_artifact": "technical_documentation.md",
        "remaining_failed_gates": fresh_failed_gates,
        "support_request_candidate": {
            "reason": "technical_documentation_depth_support_required",
            "target_artifact": "technical_documentation.md",
            "failed_gates": fresh_failed_gates,
            "support_adequacy_state": "not_required",
            "work_order_id": work_order_id,
            "grants_execution_authority": False,
        },
        "technical_documentation_depth_plateau_finalized": True,
        "grants_execution_authority": False,
    }
    recovery = {
        "target_artifact": "technical_documentation.md",
        "work_order_id": work_order_id,
        "progress_has_delta": False,
        "workspace_has_artifacts": False,
        "artifact_delta_count": 0,
        "blockers": ["technical_documentation_depth_plateau"],
        "recoverable": True,
    }
    finalized = _record_terminal_child_without_review_return(
        operator_root,
        child={**updated, "stop_result": stop_result},
        lifecycle=lifecycle,
        recovery=recovery,
        inspect_state={
            "state": "running",
            "technical_documentation_depth_plateau_stop_result": stop_result,
        },
    )
    now = _utc_now()
    finalized.update(
        {
            "technical_documentation_depth_plateau_finalized": True,
            "technical_documentation_depth_plateau_failed_gates": fresh_failed_gates,
            "technical_documentation_depth_plateau_work_order_id": work_order_id,
            "resident_worker_state": "technical_documentation_depth_plateau_finalized",
            "stop_requested": True,
            "stop_result": stop_result,
            "latest_progress": dict(fresh_progress),
            "updated_at": now,
        }
    )
    if child_id:
        _write_json(_child_path(operator_root, child_id), finalized)
    directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    if directive:
        metadata = dict(directive.get("metadata", {}) or {})
        metadata["technical_documentation_depth_plateau_finalized"] = True
        metadata["technical_documentation_depth_plateau_failed_gates"] = fresh_failed_gates
        metadata["technical_documentation_depth_plateau_work_order_id"] = work_order_id
        metadata["child_lifecycle_classification"] = "blocked_pass_completed_not_review_ready"
        metadata["support_blocker_reason"] = "technical_documentation_depth_support_required"
        metadata["support_blocker_target_artifact"] = "technical_documentation.md"
        metadata["support_admission_state"] = "technical_documentation_depth_support_required"
        metadata["support_admission_blocker_reason"] = "technical_documentation_depth_support_required"
        metadata["next_support_recovery_action"] = "conveyor_support_synthesis_job"
        metadata["continuous_campaign_latest_target_artifact"] = "technical_documentation.md"
        metadata["initial_work_order_target_artifact"] = "technical_documentation.md"
        directive["state"] = "blocked_for_support"
        directive["active_child_run_id"] = ""
        directive["blocked_reason"] = "technical_documentation_depth_support_required"
        directive["metadata"] = metadata
        directive["updated_at"] = now
        _write_json(_directive_path(operator_root, directive_id), directive)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "technical_documentation_depth_plateau_finalized",
            "generated_at": now,
            "child_run_id": child_id,
            "directive_id": directive_id,
            "target_artifact": "technical_documentation.md",
            "failed_gates": fresh_failed_gates,
            "work_order_id": work_order_id,
            "pending_return_created": False,
            "grants_execution_authority": False,
        },
    )
    return finalized


def repair_support_requested_row_coverage_overlap(operator_root: str | Path) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    repaired: list[dict[str, Any]] = []
    for path in sorted(_support_requests_root(operator_root).glob("*.json")):
        support = _read_json(path)
        if not support or bool(support.get("grants_execution_authority", False)):
            continue
        accepted_ids = [
            str(item or "").strip()
            for item in list(support.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        uncovered_ids = [
            str(item or "").strip()
            for item in list(support.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        if not accepted_ids or not uncovered_ids:
            continue
        accepted_set = set(accepted_ids)
        overlap = [item for item in list(dict.fromkeys(uncovered_ids)) if item in accepted_set]
        if not overlap:
            continue
        remaining_uncovered = [
            item for item in list(dict.fromkeys(uncovered_ids)) if item not in accepted_set
        ]
        requested_ids = [
            str(row.get("requested_row_id", "") or "").strip()
            for row in list(support.get("requested_rows", []) or [])
            if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
        ]
        support["accepted_requested_row_ids"] = list(dict.fromkeys(accepted_ids))
        support["uncovered_requested_row_ids"] = remaining_uncovered
        provider_request = support.get("provider_field_lane_request", {})
        if isinstance(provider_request, Mapping):
            provider_request = dict(provider_request)
            provider_request["accepted_requested_row_ids"] = list(dict.fromkeys(accepted_ids))
            provider_request["uncovered_requested_row_ids"] = remaining_uncovered
            support["provider_field_lane_request"] = provider_request
        support["accepted_uncovered_overlap_repaired"] = True
        support["accepted_uncovered_overlap_repaired_requested_row_ids"] = overlap
        support["accepted_uncovered_overlap_repaired_at"] = _utc_now()
        support["requested_row_coverage_state"] = (
            "accepted"
            if requested_ids and set(support["accepted_requested_row_ids"]) >= set(requested_ids)
            else ("accepted" if not remaining_uncovered else "incomplete")
        )
        support["updated_at"] = support["accepted_uncovered_overlap_repaired_at"]
        _write_json(path, support)
        repaired.append(
            {
                "support_request_id": str(support.get("support_request_id", "") or path.stem),
                "target_artifact": str(support.get("target_artifact", "") or ""),
                "accepted_uncovered_overlap_repaired_requested_row_ids": overlap,
                "requested_row_coverage_state": str(
                    support.get("requested_row_coverage_state", "") or ""
                ),
                "grants_execution_authority": False,
            }
        )
    if repaired:
        _append_ledger(
            operator_root,
            "support_request_events",
            {
                "event": "support_requested_row_coverage_overlap_repaired",
                "generated_at": _utc_now(),
                "support_requested_row_coverage_repaired_count": len(repaired),
                "records": repaired,
                "grants_execution_authority": False,
            },
        )
    return {
        "ok": True,
        "schema_name": "SupportRequestedRowCoverageOverlapRepair",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "support_requested_row_coverage_repaired_count": len(repaired),
        "support_requested_row_coverage_repaired_support_request_ids": [
            str(item.get("support_request_id", "") or "") for item in repaired
        ],
        "support_requested_row_coverage_repair_records": repaired,
        "grants_execution_authority": False,
    }


def promote_accepted_ledger_evidence_support_packs(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    promoted: list[dict[str, Any]] = []
    blocked: list[dict[str, Any]] = []
    downgraded: list[dict[str, Any]] = []
    ledger_path = _ledgers_root(operator_root) / "engineering_evidence_rows.jsonl"
    evidence_by_support: dict[str, list[dict[str, Any]]] = {}
    if ledger_path.exists():
        try:
            lines = ledger_path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            lines = []
        for line in lines:
            if not line.strip():
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(row, Mapping) or bool(row.get("grants_execution_authority", False)):
                continue
            support_id = str(row.get("support_request_id", "") or "").strip()
            if not support_id:
                continue
            evidence_by_support.setdefault(support_id, []).append(dict(row))
    for path in sorted(_support_requests_root(operator_root).glob("*.json")):
        support = _read_json(path)
        if not support or bool(support.get("grants_execution_authority", False)):
            continue
        support_request_id = str(support.get("support_request_id", "") or path.stem).strip()
        if _support_request_has_consumable_satisfied_pack(support):
            continue
        support_state = str(support.get("support_state", "") or support.get("state", "") or "").strip()
        materialization_state = str(support.get("support_materialization_state", "") or "").strip()
        stale_acquisition_state = (
            support_state in {
                "pending_operator_review",
                "commercial_source_acquisition_required",
                "source_backed_rows_required",
            }
            or materialization_state
            in {
                "parked_waiting_for_consumable_support",
                "waiting_for_source_backed_rows",
                "async_synthesis_failed",
            }
            or bool(support.get("support_provider_quality_blocker", False))
        )
        already_materialized = materialization_state in {
            "visible_bom_rows_materialized",
            "visible_risk_control_rows_materialized",
            "visible_fixture_rows_materialized",
            "support_ready_for_next_spawn",
        }
        if already_materialized or not stale_acquisition_state:
            continue
        requested_rows = [
            dict(row)
            for row in list(support.get("requested_rows", []) or [])
            if isinstance(row, Mapping)
            and str(row.get("requested_row_id", "") or "").strip()
        ]
        if not requested_rows:
            continue
        accepted_ids = [
            str(item or "").strip()
            for item in list(support.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        uncovered_ids = [
            str(item or "").strip()
            for item in list(support.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        if (
            str(support.get("requested_row_coverage_state", "") or "") != "accepted"
            or uncovered_ids
            or not accepted_ids
        ):
            continue
        target_artifact = str(support.get("target_artifact", "") or "").strip()
        rows = [
            dict(row)
            for row in list(evidence_by_support.get(support_request_id, []) or [])
            if str(row.get("target_artifact", "") or target_artifact).strip() in {"", target_artifact}
            and not bool(row.get("grants_execution_authority", False))
        ]
        if not rows:
            requested_ids = [
                str(row.get("requested_row_id", "") or "").strip()
                for row in requested_rows
                if str(row.get("requested_row_id", "") or "").strip()
            ]
            updated = dict(support)
            updated["requested_row_coverage_state"] = "incomplete"
            updated["accepted_requested_row_ids"] = []
            updated["uncovered_requested_row_ids"] = requested_ids
            updated["rejected_requested_rows"] = [
                {
                    "requested_row_id": requested_id,
                    "row_id": "",
                    "rejected_reasons": ["no_ledger_engineering_evidence_rows"],
                }
                for requested_id in requested_ids
            ]
            updated["support_state"] = "commercial_source_acquisition_required"
            updated["state"] = "commercial_source_acquisition_required"
            updated["candidate_ingestion_state"] = "commercial_source_acquisition_required"
            updated["support_recovery_state"] = "commercial_source_acquisition_required"
            updated["commercial_source_acquisition_required"] = True
            updated["source_backed_rows_required"] = True
            updated["support_provider_quality_blocker"] = "source_backed_rows_required"
            updated["support_materialization_state"] = "waiting_for_source_backed_rows"
            updated["next_support_recovery_action"] = "narrow_research_source_lanes"
            updated["ledger_backed_support_pack_promotion_state"] = "downgraded_no_ledger_rows"
            updated["updated_at"] = _utc_now()
            _write_json(path, updated)
            _persist_current_provider_acquisition_latest(
                operator_root,
                support=updated,
                provider_request=_provider_field_lane_request_for_support(
                    operator_root,
                    support=updated,
                    context=_support_request_directive_context(operator_root, updated),
                ),
                reason="ledger_backed_support_pack_downgraded_no_ledger_rows",
            )
            record = (
                {
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "promotion_blocker": "no_ledger_engineering_evidence_rows",
                    "uncovered_requested_row_ids": requested_ids,
                    "grants_execution_authority": False,
                }
            )
            blocked.append(record)
            downgraded.append(record)
            continue
        requested_id_set = {
            str(row.get("requested_row_id", "") or "").strip()
            for row in requested_rows
            if str(row.get("requested_row_id", "") or "").strip()
        }
        candidate_rows = []
        for row in rows:
            requested_row_id = str(row.get("requested_row_id", "") or "").strip()
            if requested_row_id not in requested_id_set:
                continue
            normalized_row = dict(row)
            if not str(normalized_row.get("row_id", "") or "").strip():
                normalized_row["row_id"] = str(
                    normalized_row.get("support_row_id", "")
                    or normalized_row.get("engineering_evidence_row_id", "")
                    or _record_id("ledger-row", support_request_id, requested_row_id)
                )
            if not str(normalized_row.get("claim", "") or "").strip():
                normalized_row["claim"] = (
                    f"Ledger-backed support evidence for requested row {requested_row_id}."
                )
            candidate_rows.append(normalized_row)
        coverage = assess_requested_row_coverage(
            candidate_rows,
            requested_rows=requested_rows,
            target_artifact=target_artifact,
        )
        if (
            str(coverage.get("requested_row_coverage_state", "") or "") != "accepted"
            or list(coverage.get("uncovered_requested_row_ids", []) or [])
        ):
            updated = dict(support)
            updated["requested_row_coverage_state"] = "incomplete"
            updated["accepted_requested_row_ids"] = list(
                coverage.get("accepted_requested_row_ids", []) or []
            )
            updated["uncovered_requested_row_ids"] = list(
                coverage.get("uncovered_requested_row_ids", []) or []
            )
            updated["rejected_requested_rows"] = list(
                coverage.get("rejected_requested_rows", []) or []
            )
            updated["support_state"] = "commercial_source_acquisition_required"
            updated["state"] = "commercial_source_acquisition_required"
            updated["candidate_ingestion_state"] = "commercial_source_acquisition_required"
            updated["support_recovery_state"] = "commercial_source_acquisition_required"
            updated["commercial_source_acquisition_required"] = True
            updated["source_backed_rows_required"] = True
            updated["support_provider_quality_blocker"] = "source_backed_rows_required"
            updated["support_materialization_state"] = "waiting_for_source_backed_rows"
            updated["next_support_recovery_action"] = "narrow_research_source_lanes"
            updated["ledger_backed_support_pack_promotion_state"] = "downgraded_incomplete_ledger_coverage"
            updated["updated_at"] = _utc_now()
            _write_json(path, updated)
            _persist_current_provider_acquisition_latest(
                operator_root,
                support=updated,
                provider_request=_provider_field_lane_request_for_support(
                    operator_root,
                    support=updated,
                    context=_support_request_directive_context(operator_root, updated),
                ),
                reason="ledger_backed_support_pack_downgraded_incomplete_ledger_coverage",
            )
            record = (
                {
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "promotion_blocker": "ledger_rows_do_not_cover_requested_rows",
                    "uncovered_requested_row_ids": list(
                        coverage.get("uncovered_requested_row_ids", []) or []
                    ),
                    "rejected_requested_rows": list(
                        coverage.get("rejected_requested_rows", []) or []
                    ),
                    "grants_execution_authority": False,
                }
            )
            blocked.append(record)
            downgraded.append(record)
            continue
        capability = str(support.get("capability", "") or "directive_build_grade_synthesis_pack")
        directive_id = str(support.get("directive_id", "") or "")
        required_fields = _support_request_required_fields(support)
        payload = {
            "schema_name": "LedgerBackedSupportPack",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "support_request_id": support_request_id,
            "directive_id": directive_id,
            "target_artifact": target_artifact,
            "capability": capability,
            "requested_pack_family": str(
                support.get("requested_pack_family", "") or _support_pack_family(directive_id, capability)
            ),
            "requested_rows": requested_rows,
            "child_support_rows": candidate_rows,
            "payload_summary": {"child_support_rows": candidate_rows},
            "ledger_backed_support_pack": True,
            "grants_execution_authority": False,
        }
        evidence = extract_consumable_support_evidence(
            payload,
            target_artifact=target_artifact,
            required_fields=required_fields,
            row_limit=CHILD_SUPPORT_PACK_EXCERPT_ROW_LIMIT,
        )
        if int(evidence.get("consumable_support_row_count", 0) or 0) <= 0 or not bool(
            evidence.get("support_evidence_contract_passed", False)
        ):
            requested_ids = [
                str(row.get("requested_row_id", "") or "").strip()
                for row in requested_rows
                if str(row.get("requested_row_id", "") or "").strip()
            ]
            updated = dict(support)
            updated["requested_row_coverage_state"] = "incomplete"
            updated["accepted_requested_row_ids"] = []
            updated["uncovered_requested_row_ids"] = requested_ids
            updated["rejected_requested_rows"] = [
                {
                    "requested_row_id": requested_id,
                    "row_id": "",
                    "rejected_reasons": list(
                        evidence.get("support_evidence_rejected_reasons", []) or []
                    )
                    or ["ledger_rows_not_consumable"],
                }
                for requested_id in requested_ids
            ]
            updated["support_state"] = "commercial_source_acquisition_required"
            updated["state"] = "commercial_source_acquisition_required"
            updated["candidate_ingestion_state"] = "commercial_source_acquisition_required"
            updated["support_recovery_state"] = "commercial_source_acquisition_required"
            updated["commercial_source_acquisition_required"] = True
            updated["source_backed_rows_required"] = True
            updated["support_provider_quality_blocker"] = "source_backed_rows_required"
            updated["support_materialization_state"] = "waiting_for_source_backed_rows"
            updated["next_support_recovery_action"] = "narrow_research_source_lanes"
            updated["support_evidence_rejected_reasons"] = list(
                evidence.get("support_evidence_rejected_reasons", []) or []
            )
            updated["ledger_backed_support_pack_promotion_state"] = "downgraded_non_consumable_ledger_rows"
            updated["updated_at"] = _utc_now()
            _write_json(path, updated)
            _persist_current_provider_acquisition_latest(
                operator_root,
                support=updated,
                provider_request=_provider_field_lane_request_for_support(
                    operator_root,
                    support=updated,
                    context=_support_request_directive_context(operator_root, updated),
                ),
                reason="ledger_backed_support_pack_downgraded_non_consumable_ledger_rows",
            )
            record = (
                {
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "promotion_blocker": "ledger_rows_not_consumable",
                    "uncovered_requested_row_ids": requested_ids,
                    "support_evidence_rejected_reasons": list(
                        evidence.get("support_evidence_rejected_reasons", []) or []
                    ),
                    "grants_execution_authority": False,
                }
            )
            blocked.append(record)
            downgraded.append(record)
            continue
        support_context = _support_request_directive_context(operator_root, support)
        required_roles = _support_required_role_lanes_from_context(support, support_context)
        role_lane_result = _support_role_lane_coverage_result(
            required_roles,
            evidence.get("support_role_lane_covered_roles", []),
        )
        if role_lane_result["support_role_lane_uncovered_roles"]:
            blocked.append(
                {
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "promotion_blocker": "ledger_rows_missing_required_role_lanes",
                    "support_role_lane_uncovered_roles": role_lane_result[
                        "support_role_lane_uncovered_roles"
                    ],
                    "grants_execution_authority": False,
                }
            )
            continue
        component_selection = _component_selection_result_for_evidence(
            support,
            support_context,
            evidence,
        )
        if required_roles and str(component_selection.get("component_selection_workbench_state", "") or "") != "accepted":
            blocked.append(
                {
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "promotion_blocker": "ledger_rows_component_selection_rejected",
                    "component_selection_rejected_row_reasons": list(
                        component_selection.get("component_selection_rejected_row_reasons", []) or []
                    ),
                    "grants_execution_authority": False,
                }
            )
            continue
        pack_ref = _archive_satisfied_support_pack(
            operator_root,
            state_root=state_root or operator_root,
            support_request_id=support_request_id,
            pack_ref={
                "pack_id": _record_id(
                    "ledger-support-pack",
                    support_request_id,
                    target_artifact,
                    ",".join(sorted(set(accepted_ids))),
                ),
                "pack_kind": "knowledge_pack",
                "pack_family": str(payload.get("requested_pack_family", "") or ""),
                "target_artifact": target_artifact,
                "capability": capability,
                "source_kind": "engineering_evidence_ledger",
                "quality_state": "validated",
                "reuse_state": "current_request",
                "grants_execution_authority": False,
            },
            payload=payload,
        )
        pack_ref = _enrich_support_pack_ref_with_evidence(pack_ref, evidence)
        updated = _apply_satisfied_support_pack(support, pack_ref)
        updated["requested_row_coverage_state"] = "accepted"
        updated["accepted_requested_row_ids"] = list(coverage.get("accepted_requested_row_ids", []) or [])
        updated["uncovered_requested_row_ids"] = []
        updated["rejected_requested_rows"] = []
        updated["ledger_backed_support_pack_promoted"] = True
        updated["ledger_backed_support_pack_promoted_at"] = _utc_now()
        updated["ledger_backed_support_pack_row_count"] = len(candidate_rows)
        updated["support_materialization_state"] = "waiting_for_materialization"
        updated["next_support_recovery_action"] = "materialize_consumable_support_rows"
        updated["commercial_source_acquisition_required"] = False
        updated["source_backed_rows_required"] = False
        updated["support_provider_quality_blocker"] = ""
        updated["updated_at"] = updated["ledger_backed_support_pack_promoted_at"]
        _write_json(path, updated)
        directive_id = str(updated.get("directive_id", "") or "")
        if directive_id:
            directive_path = _directive_path(operator_root, directive_id)
            directive = _read_json(directive_path)
            if directive:
                metadata = dict(directive.get("metadata", {}) or {})
                metadata["support_request_id"] = support_request_id
                metadata["support_recovery_state"] = "satisfied"
                metadata["support_recovery_target_artifact"] = target_artifact
                metadata["support_materialization_state"] = "waiting_for_materialization"
                metadata["accepted_requested_row_ids"] = list(
                    updated.get("accepted_requested_row_ids", []) or []
                )
                metadata["uncovered_requested_row_ids"] = []
                metadata["commercial_source_acquisition_required"] = False
                metadata["source_backed_rows_required"] = False
                metadata["support_provider_quality_blocker"] = ""
                directive["metadata"] = metadata
                directive["updated_at"] = updated["updated_at"]
                _write_json(directive_path, directive)
        promoted.append(
            {
                "support_request_id": support_request_id,
                "directive_id": directive_id,
                "target_artifact": target_artifact,
                "ledger_backed_support_pack_row_count": len(candidate_rows),
                "accepted_requested_row_ids": list(
                    updated.get("accepted_requested_row_ids", []) or []
                ),
                "satisfied_pack_ref": str(updated.get("satisfied_pack_ref", "") or ""),
                "grants_execution_authority": False,
            }
        )
    if promoted or blocked or downgraded:
        _append_ledger(
            operator_root,
            "support_request_events",
            {
                "event": "ledger_backed_support_pack_promotion",
                "generated_at": _utc_now(),
                "ledger_backed_support_pack_promoted_count": len(promoted),
                "ledger_backed_support_pack_blocked_count": len(blocked),
                "ledger_backed_support_pack_downgraded_count": len(downgraded),
                "promoted": promoted,
                "blocked": blocked,
                "downgraded": downgraded,
                "grants_execution_authority": False,
            },
        )
    return {
        "ok": True,
        "schema_name": "LedgerBackedSupportPackPromotion",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "ledger_backed_support_pack_promoted_count": len(promoted),
        "ledger_backed_support_pack_promoted_support_request_ids": [
            str(item.get("support_request_id", "") or "") for item in promoted
        ],
        "ledger_backed_support_pack_blocked_count": len(blocked),
        "ledger_backed_support_pack_downgraded_count": len(downgraded),
        "ledger_backed_support_pack_blockers": blocked,
        "grants_execution_authority": False,
    }


def refresh_current_support_acquisition_latest(
    operator_root: str | Path,
    *,
    promote_completed_digest_only: bool = False,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    refreshed: list[dict[str, Any]] = []
    auto_root = autonomy_root(operator_root)
    latest_provider = _read_json(auto_root / "provider_field_lane_request_latest.json")
    latest_source_plan = _read_json(auto_root / "directive_support_source_plan_latest.json")
    latest_digest = _read_json(auto_root / "directive_build_grade_support_digest_latest.json")
    latest_proof = _read_json(auto_root / "capability_consumption_proof_latest.json")
    support_paths_by_id: dict[str, Path] = {}
    for support_path in sorted(_support_requests_root(operator_root).glob("*.json")):
        support_id = support_path.stem
        support = _read_json(support_path)
        if isinstance(support, Mapping):
            support_id = str(support.get("support_request_id", "") or support_id).strip()
        if support_id:
            support_paths_by_id[support_id] = support_path
    preferred_support_ids: list[str] = []
    for payload in (latest_proof, latest_digest, latest_source_plan, latest_provider):
        if not isinstance(payload, Mapping):
            continue
        for key in (
            "proof_target_support_request_id",
            "target_support_request_id",
            "selected_support_request_id",
            "current_provider_support_request_id",
            "support_request_id",
        ):
            value = str(payload.get(key, "") or "").strip()
            if value and value not in preferred_support_ids:
                preferred_support_ids.append(value)
    candidate_paths = [
        support_paths_by_id[support_id]
        for support_id in preferred_support_ids
        if support_id in support_paths_by_id
    ]
    if not candidate_paths:
        candidate_paths = list(support_paths_by_id.values())[:1]
    for path in candidate_paths:
        support = _read_json(path)
        if not support or bool(support.get("grants_execution_authority", False)):
            continue
        support_request_id = str(support.get("support_request_id", "") or path.stem).strip()
        target_artifact = str(support.get("target_artifact", "") or "").strip()
        if not support_request_id or not target_artifact:
            continue
        requested_rows = [
            dict(row)
            for row in list(support.get("requested_rows", []) or [])
            if isinstance(row, Mapping)
            and str(row.get("requested_row_id", "") or "").strip()
        ]
        uncovered_ids = [
            str(item or "").strip()
            for item in list(support.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        support_state = str(support.get("support_state", "") or support.get("state", "") or "").strip()
        refresh_required = bool(
            requested_rows
            and (
                uncovered_ids
                or support_state
                in {
                    "commercial_source_acquisition_required",
                    "source_backed_rows_required",
                    "validation_fixture_source_acquisition_required",
                    "pending_operator_review",
                }
                or bool(support.get("commercial_source_acquisition_required", False))
                or bool(support.get("source_backed_rows_required", False))
                or bool(support.get("support_provider_quality_blocker", False))
            )
        )
        if not refresh_required:
            continue
        provider_request = _provider_field_lane_request_for_support(
            operator_root,
            support=support,
            context=_support_request_directive_context(operator_root, support),
        )
        requested_ids = [
            str(row.get("requested_row_id", "") or "").strip()
            for row in list(provider_request.get("requested_rows", []) or requested_rows)
            if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
        ]
        accepted_ids = [
            str(item or "").strip()
            for item in list(support.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        latest_digest_matches_support = bool(
            latest_digest
            and str(latest_digest.get("support_request_id", "") or "") == support_request_id
            and str(latest_digest.get("target_artifact", "") or "") == target_artifact
            and not bool(latest_digest.get("grants_execution_authority", False))
        )
        latest_digest_accepted_ids = [
            str(item or "").strip()
            for item in list(latest_digest.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ] if latest_digest_matches_support else []
        latest_digest_uncovered_ids = [
            str(item or "").strip()
            for item in list(latest_digest.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ] if latest_digest_matches_support else []
        digest_promoted_to_support = False
        if (
            latest_digest_matches_support
            and str(latest_digest.get("status", "") or "") == "completed"
            and requested_ids
            and set(latest_digest_accepted_ids) >= set(requested_ids)
            and not latest_digest_uncovered_ids
        ):
            repaired_support = dict(support)
            repaired_support["accepted_requested_row_ids"] = list(dict.fromkeys(latest_digest_accepted_ids))
            repaired_support["uncovered_requested_row_ids"] = []
            repaired_support["requested_row_coverage_state"] = "accepted"
            repaired_support["support_state"] = "satisfied"
            repaired_support["state"] = "satisfied"
            repaired_support["candidate_ingestion_state"] = "satisfied"
            repaired_support["support_recovery_state"] = "satisfied"
            repaired_support["commercial_source_acquisition_required"] = False
            repaired_support["source_backed_rows_required"] = False
            repaired_support["support_provider_quality_blocker"] = ""
            repaired_support["support_materialization_state"] = "accepted_source_backed_rows_ready"
            repaired_support["support_evidence_contract_passed"] = True
            repaired_support["accepted_field_lane_rows"] = list(
                latest_digest.get("accepted_field_lane_rows", []) or []
            )
            repaired_support["operator_seed_pack_used"] = bool(
                latest_digest.get("operator_seed_pack_used", False)
            )
            if str(latest_digest.get("operator_seed_pack_id", "") or ""):
                repaired_support["operator_seed_pack_id"] = str(
                    latest_digest.get("operator_seed_pack_id", "") or ""
                )
            repaired_support["provider_latest_freshness_state"] = (
                "current_support_request_promoted_from_completed_digest"
            )
            repaired_support["provider_latest_repaired_from_support_request_id"] = support_request_id
            repaired_support["updated_at"] = _utc_now()
            _write_json(path, repaired_support)
            support = repaired_support
            accepted_ids = list(repaired_support["accepted_requested_row_ids"])
            uncovered_ids = []
            digest_promoted_to_support = True
        if promote_completed_digest_only and not digest_promoted_to_support:
            continue
        source_backed_coverage = _source_backed_requested_row_coverage_for_support(
            support,
            provider_request=provider_request,
            requested_rows=requested_rows,
        )
        coverage_accepted_ids = [
            str(item or "").strip()
            for item in list(source_backed_coverage.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        coverage_uncovered_ids = [
            str(item or "").strip()
            for item in list(source_backed_coverage.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        context = _support_request_directive_context(operator_root, support)
        requires_source_rows = _support_request_requires_commercial_source_rows(
            support,
            context,
        )
        coverage_repaired = False
        if not digest_promoted_to_support and requires_source_rows and requested_ids and (
            set(coverage_accepted_ids) != set(accepted_ids)
            or set(coverage_uncovered_ids) != set(uncovered_ids)
            or str(support.get("requested_row_coverage_state", "") or "") == "accepted"
            and coverage_uncovered_ids
            or (
                not coverage_uncovered_ids
                and set(coverage_accepted_ids) >= set(requested_ids)
                and str(support.get("support_state", "") or "").strip() != "satisfied"
            )
        ):
            repaired_support = dict(support)
            repaired_support["requested_row_coverage_state"] = str(
                source_backed_coverage.get("requested_row_coverage_state", "")
                or ("accepted" if not coverage_uncovered_ids else "incomplete")
            )
            repaired_support["accepted_requested_row_ids"] = coverage_accepted_ids
            repaired_support["uncovered_requested_row_ids"] = coverage_uncovered_ids
            repaired_support["rejected_requested_rows"] = list(
                source_backed_coverage.get("rejected_requested_rows", []) or []
            )
            if coverage_uncovered_ids:
                repaired_support["support_state"] = "commercial_source_acquisition_required"
                repaired_support["state"] = "commercial_source_acquisition_required"
                repaired_support["commercial_source_acquisition_required"] = True
                repaired_support["source_backed_rows_required"] = True
                repaired_support["support_provider_quality_blocker"] = str(
                    repaired_support.get("support_provider_quality_blocker", "")
                    or "source_backed_rows_required"
                )
                repaired_support["support_materialization_state"] = "waiting_for_source_backed_rows"
                repaired_support["next_support_recovery_action"] = "conveyor_support_synthesis_job"
            elif set(coverage_accepted_ids) >= set(requested_ids):
                repaired_support["support_state"] = "satisfied"
                repaired_support["state"] = "satisfied"
                repaired_support["candidate_ingestion_state"] = "satisfied"
                repaired_support["support_recovery_state"] = "satisfied"
                repaired_support["commercial_source_acquisition_required"] = False
                repaired_support["source_backed_rows_required"] = False
                repaired_support["support_provider_quality_blocker"] = ""
                repaired_support["support_materialization_state"] = (
                    "accepted_source_backed_rows_ready"
                )
                repaired_support["next_support_recovery_action"] = (
                    "materialize_consumable_support_rows"
                )
                repaired_support["support_evidence_contract_passed"] = True
            repaired_support["source_backed_requested_row_coverage_repaired"] = True
            repaired_support["source_backed_requested_row_coverage_repaired_at"] = _utc_now()
            repaired_support["source_backed_support_row_count"] = int(
                source_backed_coverage.get("source_backed_support_row_count", 0) or 0
            )
            repaired_support["updated_at"] = repaired_support[
                "source_backed_requested_row_coverage_repaired_at"
            ]
            _write_json(path, repaired_support)
            support = repaired_support
            accepted_ids = coverage_accepted_ids
            uncovered_ids = coverage_uncovered_ids
            coverage_repaired = True
        effective_uncovered_ids = uncovered_ids or [
            requested_id for requested_id in requested_ids if requested_id not in set(accepted_ids)
        ]
        expected_source_query_requested_ids = [
            str(item or "").strip()
            for item in list(provider_request.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ] or effective_uncovered_ids
        latest_current = bool(
            latest_provider
            and latest_source_plan
            and latest_digest
            and str(latest_provider.get("current_provider_support_request_id", "") or "") == support_request_id
            and str(latest_source_plan.get("current_provider_support_request_id", "") or "") == support_request_id
            and str(latest_digest.get("current_provider_support_request_id", "") or "") == support_request_id
            and list(latest_provider.get("accepted_requested_row_ids", []) or []) == accepted_ids
            and list(latest_provider.get("uncovered_requested_row_ids", []) or []) == effective_uncovered_ids
            and (
                list(latest_source_plan.get("source_query_requested_row_ids", []) or [])
                == expected_source_query_requested_ids
                if expected_source_query_requested_ids
                else bool(list(latest_source_plan.get("source_query_requested_row_ids", []) or []))
            )
            and (
                not expected_source_query_requested_ids
                or str(latest_source_plan.get("source_query_generation_state", "") or "") != "provider_supplied"
            )
            and list(latest_digest.get("uncovered_requested_row_ids", []) or []) == effective_uncovered_ids
        )
        if latest_current:
            continue
        _persist_current_provider_acquisition_latest(
            operator_root,
            support=support,
            provider_request=provider_request,
            reason="bounded_support_tick_current_support_acquisition_latest_refresh",
        )
        refreshed.append(
            {
                "support_request_id": support_request_id,
                "target_artifact": target_artifact,
                "uncovered_requested_row_ids": uncovered_ids,
                "source_backed_requested_row_coverage_repaired": coverage_repaired,
                "provider_field_lane_request_id": str(
                    provider_request.get("provider_field_lane_request_id", "") or ""
                ),
                "grants_execution_authority": False,
            }
        )
    if refreshed:
        _append_ledger(
            operator_root,
            "support_request_events",
            {
                "event": "current_support_acquisition_latest_refreshed",
                "generated_at": _utc_now(),
                "current_support_acquisition_latest_refreshed_count": len(refreshed),
                "records": refreshed,
                "grants_execution_authority": False,
            },
        )
    return {
        "ok": True,
        "schema_name": "CurrentSupportAcquisitionLatestRefresh",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "current_support_acquisition_latest_refreshed_count": len(refreshed),
        "current_support_acquisition_latest_refreshed_support_request_ids": [
            str(item.get("support_request_id", "") or "") for item in refreshed
        ],
        "grants_execution_authority": False,
    }


def _support_tick_input_signature(operator_root: str | Path) -> str:
    snapshot = _read_json(_conveyor_root(operator_root) / "bounded_status_snapshot_latest.json")
    if not snapshot or snapshot.get("active_child_count", 0) or _active_children(operator_root):
        return ""
    blockers = snapshot.get("support_blockers", []) or []
    if not blockers:
        return ""
    inputs: dict[str, Any] = {}
    for blocker in blockers:
        support_id = str(blocker.get("support_admission_request_id", "") or "")
        support = _read_json(_support_request_path(operator_root, support_id)) if support_id else {}
        if not support:
            return ""
        inputs[support_id] = {
            "fingerprint": _support_synthesis_input_fingerprint(operator_root, support),
            "support_state": support.get("support_state", ""),
            "operator_review_required": support.get("operator_review_required"),
        }
    # Bounded evidence inputs: changed accepted support can wake materialization
    # even before the support request itself has been updated.
    artifacts = sorted(_support_artifacts_root(operator_root).glob("*.json"))
    if len(artifacts) > 100 or any(path.stat().st_size > 1_000_000 for path in artifacts):
        return ""  # Do not park when a bounded read cannot see all evidence.
    inputs["support_artifacts"] = {path.name: _read_json(path) for path in artifacts}
    # The tick also consumes requests beyond the snapshot's current blocker,
    # and can promote newly appended engineering evidence into a support pack.
    requests = sorted(_support_requests_root(operator_root).glob("*.json"))
    if len(requests) > 1000 or any(path.stat().st_size > 1_000_000 for path in requests):
        return ""
    inputs["support_requests"] = {}
    for path in requests:
        support = _read_json(path)
        inputs["support_requests"][path.name] = {
            "fingerprint": support_input_fingerprint(support, source_plan={}, adapters={}),
            "state": _support_request_state_value(support),
            "review_required": support.get("operator_review_required"),
            "coverage": support.get("requested_row_coverage_state"),
            "materialization": support.get("support_materialization_state"),
            "job_state": support.get("support_synthesis_job_state"),
        }
    ledger = _ledgers_root(operator_root) / "engineering_evidence_rows.jsonl"
    inputs["engineering_evidence_revision"] = (
        [ledger.stat().st_size, ledger.stat().st_mtime_ns] if ledger.exists() else None
    )
    digest = _read_json(autonomy_root(operator_root) / "directive_build_grade_support_digest_latest.json")
    inputs["build_grade_digest"] = {
        key: digest.get(key) for key in (
            "support_request_id", "target_artifact", "digest_state", "support_digest_state",
            "requested_row_coverage_state", "accepted_requested_row_ids", "source_candidates",
            "status", "uncovered_requested_row_ids", "accepted_field_lane_rows",
            "support_evidence_contract_passed", "provider_blocker",
        )
    }
    inputs["snapshot_blockers"] = [
        {key: row.get(key) for key in ("directive_id", "target_artifact", "support_admission_request_id",
                                     "support_admission_state", "support_admission_uncovered_fields")}
        for row in blockers
    ]
    return support_input_fingerprint({}, source_plan={}, adapters=inputs)


def bounded_conveyor_support_tick(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    refresh_task_manager_snapshot: bool = False,
) -> dict[str, Any]:
    from .research_runtime import schedule_research_tick
    research = schedule_research_tick(operator_root)
    with _SUPPORT_TICK_RETRY_LOCK:
        fingerprint = _support_tick_input_signature(operator_root)
        retry_path = _conveyor_root(operator_root) / "support_tick_retry_latest.json"
        prior = _read_json(retry_path)
        attempts = int(prior.get("no_delta_attempt_count", 0)) if fingerprint and prior.get("input_fingerprint") == fingerprint else 0
        if fingerprint and attempts >= RETRY_LIMIT:
            return {
                "ok": True,
                "support_tick_deferred": True,
                "support_tick_deferred_count": 1,
                "support_tick_state": "waiting_for_changed_support_input",
                "input_fingerprint": fingerprint,
                "no_delta_attempt_count": attempts,
                "research_tick": research,
                "grants_execution_authority": False,
            }
        result = _bounded_conveyor_support_tick_impl(
            operator_root, state_root=state_root,
            refresh_task_manager_snapshot=refresh_task_manager_snapshot,
        )
        if research.get("state") != "disabled":
            result["research_tick"] = research
        after = _support_tick_input_signature(operator_root)
        if fingerprint and after == fingerprint:
            _write_json(retry_path, {
                "schema_name": "SupportTickRetryState", "schema_version": 1,
                "input_fingerprint": fingerprint, "no_delta_attempt_count": attempts + 1,
                "generated_at": _utc_now(), "grants_execution_authority": False,
            })
        elif prior:
            _write_json(retry_path, {
                "schema_name": "SupportTickRetryState", "schema_version": 1,
                "input_fingerprint": after, "no_delta_attempt_count": 0,
                "generated_at": _utc_now(), "grants_execution_authority": False,
            })
        return result


def _bounded_conveyor_support_tick_impl(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    refresh_task_manager_snapshot: bool = False,
) -> dict[str, Any]:
    started = time.perf_counter()
    initialize_conveyor_state(operator_root)
    initial_acquisition_latest_refresh = refresh_current_support_acquisition_latest(
        operator_root,
        promote_completed_digest_only=True,
    )
    bom_materialization = materialize_current_bom_support(
        operator_root,
        state_root=state_root,
        persist_snapshot=False,
    )
    risk_materialization = materialize_current_risk_control_support(
        operator_root,
        state_root=state_root,
        persist_snapshot=False,
    )
    fixture_materialization = materialize_current_validation_fixture_support(
        operator_root,
        state_root=state_root,
        persist_snapshot=False,
    )
    support_coverage_repair = repair_support_requested_row_coverage_overlap(operator_root)
    ledger_pack_promotion = promote_accepted_ledger_evidence_support_packs(
        operator_root,
        state_root=state_root,
    )
    post_repair_acquisition_latest_refresh = refresh_current_support_acquisition_latest(operator_root)
    acquisition_latest_refresh = (
        post_repair_acquisition_latest_refresh
        if int(post_repair_acquisition_latest_refresh.get("current_support_acquisition_latest_refreshed_count", 0) or 0)
        else initial_acquisition_latest_refresh
    )
    resident_followup_repair = repair_resident_no_delta_followup_targets(operator_root)
    materialization_fields = dict(fixture_materialization)
    for key in (
        "ok",
        "schema_name",
        "schema_version",
        "generated_at",
            "support_tick_duration_ms",
            "grants_execution_authority",
        ):
            materialization_fields.pop(key, None)
    bom_materialization_fields = dict(bom_materialization)
    for key in (
        "ok",
        "schema_name",
        "schema_version",
        "generated_at",
        "support_tick_duration_ms",
        "grants_execution_authority",
    ):
        bom_materialization_fields.pop(key, None)
    risk_materialization_fields = dict(risk_materialization)
    for key in (
        "ok",
        "schema_name",
        "schema_version",
        "generated_at",
        "support_tick_duration_ms",
        "grants_execution_authority",
    ):
        risk_materialization_fields.pop(key, None)
    result = {
        "ok": True,
        "schema_name": "ConveyorBoundedSupportTick",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "support_tick_phase_policy": "bounded_support_tick",
        "support_tick_state": "completed",
        "support_tick_deferred": False,
        "support_tick_deferred_count": 0,
        "support_pointer_repair_state": "deferred",
        "support_pointer_repair_reason": "bounded_support_tick_skips_broad_freshness_repair",
        "support_pointer_repaired_count": 0,
        **bom_materialization_fields,
        **risk_materialization_fields,
        **materialization_fields,
        "visible_bom_materialization": bom_materialization,
        "risk_control_materialization": risk_materialization,
        "visible_fixture_materialization": fixture_materialization,
        "support_requested_row_coverage_overlap_repair": support_coverage_repair,
        "support_requested_row_coverage_repaired_count": int(
            support_coverage_repair.get("support_requested_row_coverage_repaired_count", 0) or 0
        ),
        "ledger_backed_support_pack_promotion": ledger_pack_promotion,
        "ledger_backed_support_pack_promoted_count": int(
            ledger_pack_promotion.get("ledger_backed_support_pack_promoted_count", 0) or 0
        ),
        "ledger_backed_support_pack_downgraded_count": int(
            ledger_pack_promotion.get("ledger_backed_support_pack_downgraded_count", 0) or 0
        ),
        "current_support_acquisition_latest_refresh": acquisition_latest_refresh,
        "current_support_acquisition_latest_refreshed_count": int(
            acquisition_latest_refresh.get("current_support_acquisition_latest_refreshed_count", 0) or 0
        ),
        "resident_no_delta_followup_repair": resident_followup_repair,
        "resident_no_delta_followup_repaired_count": int(
            resident_followup_repair.get("resident_no_delta_followup_repaired_count", 0) or 0
        ),
    }
    if refresh_task_manager_snapshot:
        try:
            snapshot = build_task_manager_snapshot(operator_root, persist=True)
            persist_bounded_status_snapshot(
                operator_root,
                task_manager_snapshot=snapshot,
                refreshed_by="bounded_support_tick",
            )
            result["bounded_status_snapshot_persisted_at"] = _utc_now()
            result["bounded_status_snapshot_refreshed_by"] = "bounded_support_tick"
            result["task_manager_snapshot_refresh_state"] = "completed"
        except Exception as exc:
            result["support_tick_deferred"] = True
            result["support_tick_deferred_count"] = 1
            result["task_manager_snapshot_refresh_state"] = "deferred"
            result["task_manager_snapshot_refresh_error_class"] = type(exc).__name__
            result["task_manager_snapshot_refresh_error"] = str(exc)
    else:
        cached_refresh = _refresh_cached_task_manager_snapshot_after_fixture_materialization(
            operator_root,
            fixture_materialization,
        )
        result["task_manager_snapshot_cached_refresh_state"] = str(
            cached_refresh.get("snapshot_refresh_state", "") or ""
        )
        result["task_manager_snapshot_cached_refresh_by"] = str(
            cached_refresh.get("snapshot_refreshed_by", "") or ""
        )
        result["task_manager_snapshot_cached_refresh_directive_ids"] = list(
            cached_refresh.get("snapshot_refreshed_directive_ids", []) or []
        )
        risk_changed = int(risk_materialization.get("risk_control_changed_artifact_count", 0) or 0) > 0
        bom_changed = int(bom_materialization.get("bom_changed_artifact_count", 0) or 0) > 0
        fixture_changed = int(fixture_materialization.get("visible_fixture_changed_artifact_count", 0) or 0) > 0
        resident_followup_repaired = int(
            resident_followup_repair.get("resident_no_delta_followup_repaired_count", 0) or 0
        ) > 0
        support_coverage_repaired = int(
            support_coverage_repair.get("support_requested_row_coverage_repaired_count", 0) or 0
        ) > 0
        ledger_pack_promoted = int(
            ledger_pack_promotion.get("ledger_backed_support_pack_promoted_count", 0) or 0
        ) > 0
        ledger_pack_downgraded = int(
            ledger_pack_promotion.get("ledger_backed_support_pack_downgraded_count", 0) or 0
        ) > 0
        if (
            resident_followup_repaired
            or support_coverage_repaired
            or ledger_pack_promoted
            or ledger_pack_downgraded
            or bom_changed
            or (risk_changed and result["task_manager_snapshot_cached_refresh_state"] != "completed")
        ):
            try:
                snapshot = build_task_manager_snapshot(operator_root, persist=True)
                refresh_reason = (
                    "bounded_support_tick_resident_no_delta_followup_repair"
                    if resident_followup_repaired
                    else "bounded_support_tick_requested_row_coverage_repair"
                    if support_coverage_repaired
                    else "bounded_support_tick_ledger_backed_support_pack_promotion"
                    if ledger_pack_promoted
                    else "bounded_support_tick_ledger_backed_support_pack_downgrade"
                    if ledger_pack_downgraded
                    else "bounded_support_tick_bom_materialization"
                    if bom_changed
                    else "bounded_support_tick_risk_materialization"
                )
                persist_bounded_status_snapshot(
                    operator_root,
                    task_manager_snapshot=snapshot,
                    refreshed_by=refresh_reason,
                )
                result["task_manager_snapshot_cached_refresh_state"] = "completed"
                result["task_manager_snapshot_cached_refresh_by"] = refresh_reason
                result["task_manager_snapshot_cached_refresh_directive_ids"] = list(
                    dict.fromkeys(
                        list(
                            resident_followup_repair.get(
                                "resident_no_delta_followup_repaired_directive_ids", []
                            )
                            or []
                        )
                        + list(
                            bom_materialization.get(
                                "bom_materialization_unblocked_directive_ids", []
                            )
                            or []
                        )
                        + [
                            str(item or "")
                            for item in support_coverage_repair.get(
                                "support_requested_row_coverage_repaired_support_request_ids", []
                            )
                            or []
                        ]
                        + list(
                            risk_materialization.get(
                                "risk_control_materialization_unblocked_directive_ids", []
                            )
                            or []
                        )
                    )
                )
                result["bounded_status_snapshot_persisted_at"] = _utc_now()
                result["bounded_status_snapshot_refreshed_by"] = refresh_reason
            except Exception as exc:
                result["support_tick_deferred"] = True
                result["support_tick_deferred_count"] = int(result.get("support_tick_deferred_count", 0) or 0) + 1
                result["task_manager_snapshot_cached_refresh_state"] = "deferred"
                result["task_manager_snapshot_cached_refresh_error_class"] = type(exc).__name__
                result["task_manager_snapshot_cached_refresh_error"] = str(exc)
        cached_snapshot = _read_json(_conveyor_root(operator_root) / "task_manager" / "snapshot_latest.json")
        if cached_snapshot:
            persist_bounded_status_snapshot(
                operator_root,
                task_manager_snapshot=cached_snapshot,
                refreshed_by=(
                    str(result.get("bounded_status_snapshot_refreshed_by", "") or "")
                    or "bounded_support_tick_cached_snapshot"
                ),
            )
            result["bounded_status_snapshot_persisted_at"] = _utc_now()
            result["bounded_status_snapshot_refreshed_by"] = (
                str(result.get("bounded_status_snapshot_refreshed_by", "") or "")
                or "bounded_support_tick_cached_snapshot"
            )
        result["task_manager_snapshot_refresh_state"] = "deferred"
        result["task_manager_snapshot_refresh_reason"] = (
            "bounded_support_tick_refreshed_after_bom_materialization"
            if bom_changed
            else (
            "bounded_support_tick_refreshed_after_risk_materialization"
            if risk_changed and not fixture_changed
            else "bounded_support_tick_skips_full_task_manager_refresh"
            )
        )
    should_refresh_proof = bool(refresh_task_manager_snapshot) or int(
        result.get("resident_no_delta_followup_repaired_count", 0) or 0
    ) > 0
    if should_refresh_proof:
        try:
            proof = _capability_consumption_proof(
                operator_root,
                capability_kind="conveyor_self_structuring_receipts_v1",
                persist=True,
            )
            proof_obligation = _capability_proof_obligation(operator_root, persist=True)
            work_item_summary = _self_structuring_work_item_summary(
                operator_root,
                proof_obligation=proof_obligation,
            )
            result["proof_refresh_state"] = "completed"
            result["proof_phase_work_item_action"] = str(
                proof.get("proof_phase_work_item_action", "")
                or proof_obligation.get("recommended_action", "")
                or ""
            )
            result["active_self_structuring_work_item_id"] = str(
                work_item_summary.get("active_self_structuring_work_item_id", "") or ""
            )
        except Exception as exc:
            result["proof_refresh_state"] = "deferred"
            result["proof_refresh_error_class"] = type(exc).__name__
            result["proof_refresh_error"] = str(exc)
    result["support_tick_duration_ms"] = round((time.perf_counter() - started) * 1000, 3)
    return result


def _mirror_resident_child_progress_checkpoint(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> dict[str, Any]:
    updated = dict(child)
    updated["latest_progress"] = dict(latest_progress)
    receipt = latest_progress.get('reviewed_child_revision_consumed')
    if isinstance(receipt, dict):
        from .child_delivery import reconcile_use
        updated['reviewed_child_artifact_use'] = reconcile_use(Path(operator_root), dict(child), receipt)
    updated["progress_state"] = str(latest_progress.get("progress_state", "") or "")
    updated["latest_progress_at"] = str(latest_progress.get("generated_at", "") or "")
    heartbeat = _resident_progress_heartbeat(updated, latest_progress)
    updated["last_progress_at"] = str(heartbeat.get("last_progress_at", "") or updated["latest_progress_at"])
    updated["last_heartbeat_at"] = str(heartbeat.get("last_heartbeat_at", "") or updated["last_progress_at"])
    updated["last_progress_checkpoint_hash"] = str(heartbeat.get("last_progress_checkpoint_hash", "") or "")
    updated["progress_checkpoint_age_seconds"] = float(heartbeat.get("progress_checkpoint_age_seconds", 0.0) or 0.0)
    updated["progress_heartbeat_source"] = str(heartbeat.get("progress_heartbeat_source", "") or "")
    updated["latest_target_artifact"] = _resident_target_artifact_from_progress(latest_progress)
    updated["latest_artifact_delta_count"] = int(latest_progress.get("artifact_delta_count", 0) or 0)
    updated["bounded_reconcile_progress_state"] = "mirrored"
    updated["bounded_reconcile_progress_mirrored_at"] = _utc_now()
    updated.update(_child_compute_status_fields(updated, latest_progress))
    child_id = str(updated.get("child_run_id", "") or "").strip()
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated)
    return updated


def _resident_support_backed_no_delta_finalizer_eligible(
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> tuple[bool, list[str]]:
    blockers: list[str] = []
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        blockers.append("not_resident_campaign_child")
    try:
        cycle_index = int(latest_progress.get("cycle_index", 0) or 0)
    except (TypeError, ValueError):
        cycle_index = 0
    if cycle_index < RESIDENT_NO_DELTA_BLOCKER_THRESHOLD:
        blockers.append("below_no_delta_cycle_threshold")
    try:
        support_rows_read = int(latest_progress.get("support_pack_rows_read", 0) or 0)
    except (TypeError, ValueError):
        support_rows_read = 0
    try:
        support_consumable = int(latest_progress.get("support_pack_consumable_count", 0) or 0)
    except (TypeError, ValueError):
        support_consumable = 0
    support_state = str(latest_progress.get("support_adequacy_state", "") or "").strip()
    if support_state in {"", "insufficient_field_coverage", "missing_support_rows", "wrong_target", "non_consumable"}:
        blockers.append("support_not_adequate")
    if support_rows_read <= 0 and support_consumable <= 0:
        blockers.append("support_rows_not_consumed")
    changed_this_cycle = bool(
        latest_progress.get("meaningful_delta", False)
        or latest_progress.get("support_to_artifact_delta", False)
        or latest_progress.get("support_to_artifact_required_field_delta", False)
        or latest_progress.get("source_bom_required_field_delta", False)
        or latest_progress.get("risk_control_required_field_delta", False)
        or latest_progress.get("validation_fixture_required_field_delta", False)
    )
    for delta in [item for item in list(latest_progress.get("artifact_deltas", []) or []) if isinstance(item, Mapping)]:
        kind = str(delta.get("delta_kind", "") or "").strip()
        if kind not in {"created", "revised"}:
            continue
        before_hash = str(delta.get("before_hash", "") or delta.get("previous_hash", "") or "").strip()
        after_hash = str(delta.get("after_hash", "") or delta.get("new_hash", "") or "").strip()
        if before_hash and after_hash and before_hash == after_hash:
            continue
        changed_this_cycle = True
        break
    if changed_this_cycle:
        blockers.append("meaningful_delta_present")
    try:
        artifact_delta_count = int(latest_progress.get("artifact_delta_count", 0) or 0)
    except (TypeError, ValueError):
        artifact_delta_count = 0
    if artifact_delta_count > 0:
        blockers.append("artifact_delta_present")
    blocked_reason = str(latest_progress.get("blocked_reason", "") or "").strip()
    cycle_outcome = str(latest_progress.get("cycle_outcome", "") or "").strip()
    if blocked_reason != "no_artifact_delta" and cycle_outcome not in {"blocked", "no_artifact_delta"}:
        blockers.append("latest_progress_not_no_delta_blocked")
    if bool(latest_progress.get("hardware_build_packet_ready_candidate", False)):
        blockers.append("review_ready_checkpoint_should_return")
    outbox_packet = _child_outbox_return_packet_path(child)
    if outbox_packet is not None and outbox_packet.exists():
        blockers.append("return_packet_present")
    if _resident_progress_indicates_mount_fault(latest_progress):
        blockers.append("mount_or_runtime_fault_detected")
    return not blockers, blockers


def _resident_no_delta_followup_target(latest_progress: Mapping[str, Any]) -> str:
    target_artifact = _resident_target_artifact_from_progress(latest_progress)
    if target_artifact != "validation_fixtures.json":
        return ""
    failed_gates = {
        str(item or "").strip()
        for item in list(latest_progress.get("remaining_failed_gates", []) or [])
        if str(item or "").strip()
    }
    if "linked_hardware_dossier_not_complete" not in failed_gates:
        return ""
    materialized_state = str(
        latest_progress.get("validation_fixture_materialization_state", "")
        or latest_progress.get("visible_fixture_materialization_state", "")
        or latest_progress.get("support_materialization_state", "")
        or ""
    ).strip()
    if materialized_state not in {
        "materialized",
        "visible_fixture_rows_materialized",
        "validation_fixture_rows_materialized",
    }:
        return ""
    unclosed = [
        str(item or "").strip()
        for item in list(
            latest_progress.get("validation_fixture_unclosed_requested_row_ids", [])
            or latest_progress.get("visible_fixture_unmaterialized_requested_row_ids", [])
            or latest_progress.get("support_materialization_pending_requested_row_ids", [])
            or []
        )
        if str(item or "").strip()
    ]
    if unclosed:
        return ""
    return "implementation_readiness_review.json"


def _resident_no_delta_followup_from_visible_fixture_support(
    operator_root: str | Path,
    *,
    directive: Mapping[str, Any],
    metadata: Mapping[str, Any],
) -> dict[str, Any]:
    directive_id = str(directive.get("directive_id", "") or "").strip()
    if not directive_id:
        return {}
    support_ids = [
        str(metadata.get("current_validation_fixture_support_request_id", "") or "").strip(),
        str(metadata.get("validation_fixture_support_request_id", "") or "").strip(),
        str(metadata.get("support_request_id", "") or "").strip(),
    ]
    required_fields = [
        "equipment",
        "fixture_wiring",
        "calibration_steps",
        "measurement_method",
        "pass_fail_thresholds",
        "linked_bom_refs",
        "linked_risk_control_refs",
        "execution_gate",
    ]
    for support_id in list(dict.fromkeys(item for item in support_ids if item)):
        support = _read_json(_support_request_path(operator_root, support_id))
        if not support:
            continue
        if str(support.get("directive_id", "") or "") != directive_id:
            continue
        if str(support.get("target_artifact", "") or "") != "validation_fixtures.json":
            continue
        if _support_request_state_value(support) != "satisfied":
            continue
        accepted_ids = [
            str(item or "").strip()
            for item in list(
                support.get("accepted_validation_fixture_requested_row_ids", [])
                or support.get("accepted_requested_row_ids", [])
                or metadata.get("visible_fixture_materialized_requested_row_ids", [])
                or []
            )
            if str(item or "").strip()
        ]
        accepted_ids = list(dict.fromkeys(accepted_ids))
        if not accepted_ids:
            continue
        support_uncovered_ids = {
            str(item or "").strip()
            for item in list(
                support.get("visible_fixture_unmaterialized_requested_row_ids", [])
                or support.get("uncovered_requested_row_ids", [])
                or metadata.get("visible_fixture_unmaterialized_requested_row_ids", [])
                or []
            )
            if str(item or "").strip()
        }
        if support_uncovered_ids.intersection(set(accepted_ids)):
            continue
        draft = _read_json(_campaign_root(operator_root, directive_id) / "drafts" / "validation_fixtures.json")
        fixture_rows: list[dict[str, Any]] = []
        if draft:
            for key in ("fixtures", "rows", "artifact_rows"):
                value = draft.get(key)
                if isinstance(value, list):
                    fixture_rows.extend(dict(item) for item in value if isinstance(item, Mapping))
        visible_by_requested_id: dict[str, dict[str, Any]] = {}
        for row in fixture_rows:
            for key in ("closes_requested_row_id", "requested_row_id"):
                row_requested_id = str(row.get(key, "") or "").strip()
                if not row_requested_id:
                    continue
                for accepted_id in accepted_ids:
                    if _requested_row_ids_intersect(row_requested_id, accepted_id):
                        visible_by_requested_id[accepted_id] = row
        missing_visible_ids: list[str] = []
        for accepted_id in accepted_ids:
            row = visible_by_requested_id.get(accepted_id, {})
            if not row:
                missing_visible_ids.append(accepted_id)
                continue
            if any(
                not _row_field_value_present(row, field)
                or _technical_depth_value_is_placeholder(row.get(field))
                for field in required_fields
            ):
                missing_visible_ids.append(accepted_id)
        if missing_visible_ids:
            continue
        return {
            "followup_target_artifact": "implementation_readiness_review.json",
            "target_artifact": "validation_fixtures.json",
            "support_request_id": support_id,
            "visible_fixture_materialized_requested_row_ids": accepted_ids,
            "resident_no_delta_followup_repair_reason": "visible_fixture_support_already_materialized",
        }
    return {}


def _finalize_support_backed_no_delta_resident_pass(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    runner: ConveyorChildRunner,
) -> dict[str, Any] | None:
    eligible, blockers = _resident_support_backed_no_delta_finalizer_eligible(child, latest_progress)
    updated = dict(child)
    updated["resident_support_backed_no_delta_finalizer_blockers"] = blockers
    updated["resident_support_backed_no_delta_finalizer_eligible"] = eligible
    child_id = str(updated.get("child_run_id", "") or "").strip()
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated)
    if not eligible:
        return None
    checkpoint_path = _child_progress_checkpoint_path(updated)
    before_mtime = 0.0
    if checkpoint_path is not None and checkpoint_path.exists():
        try:
            before_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            before_mtime = 0.0
    before_hash = _progress_checkpoint_hash(latest_progress) if latest_progress else ""
    fresh_progress = _latest_child_progress(updated)
    fresh_hash = _progress_checkpoint_hash(fresh_progress) if fresh_progress else ""
    after_mtime = before_mtime
    if checkpoint_path is not None and checkpoint_path.exists():
        try:
            after_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            after_mtime = before_mtime
    fresh_eligible, fresh_blockers = _resident_support_backed_no_delta_finalizer_eligible(
        updated,
        fresh_progress,
    )
    if fresh_hash != before_hash or after_mtime != before_mtime or not fresh_eligible:
        updated["resident_support_backed_no_delta_finalizer_suppressed"] = True
        updated["resident_support_backed_no_delta_finalizer_suppressed_reason"] = "fresh_progress_checkpoint_observed"
        updated["resident_support_backed_no_delta_finalizer_blockers"] = fresh_blockers
        updated["updated_at"] = _utc_now()
        if child_id:
            _write_json(_child_path(operator_root, child_id), updated)
        return None
    try:
        stop_result = dict(runner.stop_child_container(dict(updated)) or {})
    except Exception as exc:
        stop_result = {"ok": False, "state": "stop_failed", "error_class": type(exc).__name__, "error": str(exc)}
    target_artifact = _resident_target_artifact_from_progress(fresh_progress)
    followup_target_artifact = _resident_no_delta_followup_target(fresh_progress)
    next_unresolved_artifact = followup_target_artifact or target_artifact
    lifecycle = {
        "schema_name": "ChildLifecycleAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "child_run_id": child_id,
        "directive_id": str(updated.get("directive_id", "") or ""),
        "child_lifecycle_classification": "blocked_pass_completed_not_review_ready",
        "container_exit_code": "",
        "productive_pass_delta_observed": False,
        "productive_pass_completed_not_review_ready": False,
        "blocked_pass_completed_not_review_ready": True,
        "productive_pass_target_artifact": target_artifact,
        "next_unresolved_artifact": next_unresolved_artifact,
        "resident_no_delta_followup_target_artifact": followup_target_artifact,
        "resident_no_delta_followup_reason": "linked_hardware_dossier_not_complete"
        if followup_target_artifact
        else "",
        "remaining_failed_gates": [
            str(item)
            for item in list(fresh_progress.get("remaining_failed_gates", []) or [])
            if str(item).strip()
        ],
        "support_request_candidate": {
            "reason": "resident_support_backed_no_delta_finalized",
            "target_artifact": next_unresolved_artifact,
            "support_adequacy_state": str(fresh_progress.get("support_adequacy_state", "") or ""),
            "resident_no_delta_followup_target_artifact": followup_target_artifact,
        },
        "resident_support_backed_no_delta_finalized": True,
        "resident_support_backed_no_delta_finalizer_blockers": [],
        "grants_execution_authority": False,
    }
    recovery = {
        "target_artifact": target_artifact,
        "work_order_id": str(fresh_progress.get("work_order_id", "") or updated.get("latest_work_order_id", "") or ""),
        "progress_has_delta": False,
        "workspace_has_artifacts": False,
        "artifact_delta_count": 0,
        "blockers": ["support_backed_no_artifact_delta"],
        "recoverable": True,
    }
    finalized = _record_terminal_child_without_review_return(
        operator_root,
        child={**updated, "stop_result": stop_result},
        lifecycle=lifecycle,
        recovery=recovery,
        inspect_state={
            "state": "running",
            "resident_support_backed_no_delta_stop_result": stop_result,
        },
    )
    finalized.update(
        {
            "resident_support_backed_no_delta_finalized": True,
            "resident_worker_state": "support_backed_no_delta_finalized",
            "stop_requested": True,
            "stop_result": stop_result,
            "latest_progress": dict(fresh_progress),
            "updated_at": _utc_now(),
        }
    )
    if child_id:
        _write_json(_child_path(operator_root, child_id), finalized)
    directive_id = str(finalized.get("directive_id", "") or "")
    if directive_id:
        directive_path = _directive_path(operator_root, directive_id)
        directive = _read_json(directive_path)
        if directive:
            metadata = dict(directive.get("metadata", {}) or {})
            metadata["resident_support_backed_no_delta_finalized"] = True
            metadata["child_lifecycle_classification"] = "blocked_pass_completed_not_review_ready"
            metadata["resident_no_delta_followup_target_artifact"] = followup_target_artifact
            metadata["resident_no_delta_followup_reason"] = "linked_hardware_dossier_not_complete" if followup_target_artifact else ""
            metadata["next_unresolved_artifact"] = next_unresolved_artifact
            if followup_target_artifact:
                metadata["resident_no_delta_followup_ready"] = True
                metadata["support_blocker_reason"] = ""
                metadata["support_blocker_target_artifact"] = followup_target_artifact
                metadata["support_admission_state"] = "not_required"
                metadata["initial_work_order_target_artifact"] = followup_target_artifact
                metadata["continuous_campaign_latest_target_artifact"] = followup_target_artifact
                metadata["next_support_recovery_action"] = "bounded_scheduler_dossier_synthesis"
                directive["state"] = "requeued"
                directive["blocked_reason"] = ""
            else:
                metadata["resident_no_delta_followup_ready"] = False
                metadata["support_blocker_reason"] = "resident_support_backed_no_delta_finalized"
                metadata["support_blocker_target_artifact"] = target_artifact
                metadata["support_admission_state"] = "resident_support_backed_no_delta_finalized"
                metadata["next_support_recovery_action"] = "operator_review_or_support_refresh"
                directive["state"] = "blocked_for_support"
                directive["blocked_reason"] = "resident_support_backed_no_delta_finalized"
            directive["metadata"] = metadata
            directive["active_child_run_id"] = ""
            directive["updated_at"] = _utc_now()
            _write_json(directive_path, directive)
    if directive_id and followup_target_artifact:
        closed_rows = [
            str(item or "").strip()
            for item in list(
                fresh_progress.get("validation_fixture_closed_requested_row_ids", [])
                or fresh_progress.get("visible_fixture_materialized_requested_row_ids", [])
                or []
            )
            if str(item or "").strip()
        ]
        closure_evidence = {
            "schema_name": "TargetArtifactClosureEvidence",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "generated_at": _utc_now(),
            "directive_id": directive_id,
            "target_artifact": target_artifact,
            "target_artifact_closure_state": "partial_closed_linked_artifacts_remaining",
            "closed_target_artifact": target_artifact,
            "closed_fields": [
                "equipment",
                "fixture_wiring",
                "calibration_steps",
                "measurement_method",
                "pass_fail_thresholds",
                "linked_bom_refs",
                "linked_risk_control_refs",
                "execution_gate",
            ],
            "closed_requested_row_ids": closed_rows,
            "remaining_linked_artifact_gaps": [followup_target_artifact],
            "remaining_artifacts": [followup_target_artifact],
            "next_linked_artifact_target": followup_target_artifact,
            "partial_target_correct_closure": True,
            "hardware_build_packet_ready": False,
            "resident_support_backed_no_delta_finalized": True,
            "grants_execution_authority": False,
        }
        closure_evidence["target_artifact_closure_evidence_id"] = _record_id(
            "target-artifact-closure",
            directive_id,
            target_artifact,
            ",".join(closed_rows),
            followup_target_artifact,
        )
        latest_path = _conveyor_root(operator_root) / "target_artifact_closure_evidence_latest.json"
        latest = _read_json(latest_path)
        if str(latest.get("target_artifact_closure_evidence_id", "") or "") != str(
            closure_evidence["target_artifact_closure_evidence_id"]
        ):
            _append_ledger(operator_root, "target_artifact_closure_evidence", closure_evidence)
            _write_json(latest_path, closure_evidence)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_support_backed_no_delta_finalized",
            "generated_at": _utc_now(),
            "child_run_id": child_id,
            "directive_id": directive_id,
            "target_artifact": target_artifact,
            "resident_no_delta_followup_target_artifact": followup_target_artifact,
            "stop_result": stop_result,
            "grants_execution_authority": False,
        },
    )
    return finalized


def _implementation_readiness_review_finalizer_eligible(
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> tuple[bool, list[str]]:
    blockers: list[str] = []
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        blockers.append("not_resident_campaign_child")
    target_artifact = _resident_target_artifact_from_progress(latest_progress)
    if target_artifact != "implementation_readiness_review.json":
        blockers.append("not_implementation_readiness_review_target")
    closure_state = str(latest_progress.get("visible_dossier_closure_state", "") or "").strip()
    if closure_state != "visible_closure_reviewable":
        blockers.append("visible_dossier_not_reviewable")
    if bool(latest_progress.get("grants_execution_authority", False)):
        blockers.append("execution_authority_granted")
    failed_gates = {
        str(item or "").strip()
        for item in list(latest_progress.get("remaining_failed_gates", []) or [])
        if str(item or "").strip()
    }
    review_only_gates = {
        "operator_review_required",
        "implementation_readiness_review_only",
        "review_only",
        "operator_review_gate",
    }
    unexpected_gates = sorted(failed_gates.difference(review_only_gates))
    if unexpected_gates:
        blockers.append("non_review_only_gates_remaining")
    missing_artifacts = [
        str(item or "").strip()
        for item in list(latest_progress.get("visible_dossier_missing_artifacts", []) or [])
        if str(item or "").strip()
    ]
    incomplete_artifacts = [
        str(item or "").strip()
        for item in list(latest_progress.get("visible_dossier_incomplete_artifacts", []) or [])
        if str(item or "").strip()
    ]
    if missing_artifacts:
        blockers.append("visible_dossier_missing_artifacts")
    if incomplete_artifacts:
        blockers.append("visible_dossier_incomplete_artifacts")
    outbox_packet = _child_outbox_return_packet_path(child)
    if outbox_packet is not None and outbox_packet.exists():
        blockers.append("return_packet_present")
    if _resident_progress_indicates_mount_fault(latest_progress):
        blockers.append("mount_or_runtime_fault_detected")
    return not blockers, blockers


def _finalize_implementation_readiness_review_pass(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    runner: ConveyorChildRunner,
) -> dict[str, Any] | None:
    eligible, blockers = _implementation_readiness_review_finalizer_eligible(child, latest_progress)
    updated = dict(child)
    updated["implementation_readiness_review_finalizer_eligible"] = eligible
    updated["implementation_readiness_review_finalizer_blockers"] = blockers
    child_id = str(updated.get("child_run_id", "") or "").strip()
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated)
    if not eligible:
        return None
    checkpoint_path = _child_progress_checkpoint_path(updated)
    before_mtime = 0.0
    if checkpoint_path is not None and checkpoint_path.exists():
        try:
            before_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            before_mtime = 0.0
    before_hash = _progress_checkpoint_hash(latest_progress) if latest_progress else ""
    fresh_progress = _latest_child_progress(updated)
    fresh_hash = _progress_checkpoint_hash(fresh_progress) if fresh_progress else ""
    after_mtime = before_mtime
    if checkpoint_path is not None and checkpoint_path.exists():
        try:
            after_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            after_mtime = before_mtime
    fresh_eligible, fresh_blockers = _implementation_readiness_review_finalizer_eligible(
        updated,
        fresh_progress,
    )
    if fresh_hash != before_hash or after_mtime != before_mtime or not fresh_eligible:
        updated["implementation_readiness_review_finalizer_suppressed"] = True
        updated["implementation_readiness_review_finalizer_suppressed_reason"] = "fresh_progress_checkpoint_observed"
        updated["implementation_readiness_review_finalizer_blockers"] = fresh_blockers
        updated["updated_at"] = _utc_now()
        if child_id:
            _write_json(_child_path(operator_root, child_id), updated)
        return None
    try:
        stop_result = dict(runner.stop_child_container(dict(updated)) or {})
    except Exception as exc:
        stop_result = {"ok": False, "state": "stop_failed", "error_class": type(exc).__name__, "error": str(exc)}
    failed_gates = [
        str(item)
        for item in list(fresh_progress.get("remaining_failed_gates", []) or [])
        if str(item).strip()
    ]
    packet = record_child_return_packet(
        operator_root,
        child_run_id=child_id,
        outcome_summary=(
            "Resident child completed a review-only implementation readiness dossier; only operator-review "
            "gates remain and no execution authority is granted."
        ),
        artifacts=["implementation_readiness_review.json"],
        verification_evidence=[
            "visible_dossier_closure_reviewable",
            "implementation_readiness_review_only",
            "no_execution_authority_granted",
        ],
        risks=["operator_review_required"],
        requested_follow_up="operator_review_implementation_readiness_dossier",
        result_state="completed",
        extra_fields={
            "target_artifact": "implementation_readiness_review.json",
            "implementation_readiness_review_finalized": True,
            "implementation_readiness_review_finalizer_state": "review_packet_created",
            "visible_dossier_closure_state": str(
                fresh_progress.get("visible_dossier_closure_state", "") or ""
            ),
            "visible_dossier_missing_artifacts": list(
                fresh_progress.get("visible_dossier_missing_artifacts", []) or []
            ),
            "visible_dossier_incomplete_artifacts": list(
                fresh_progress.get("visible_dossier_incomplete_artifacts", []) or []
            ),
            "remaining_failed_gates": failed_gates,
            "hardware_build_packet_ready_candidate": bool(
                fresh_progress.get("hardware_build_packet_ready_candidate", False)
            ),
            "grants_execution_authority": False,
            "stop_result": stop_result,
        },
    )
    finalized = _read_json(_child_path(operator_root, child_id)) or dict(updated)
    finalized.update(
        {
            "implementation_readiness_review_finalized": True,
            "implementation_readiness_review_finalizer_state": "review_packet_created",
            "implementation_readiness_review_finalizer_blockers": [],
            "implementation_readiness_review_visible_closure_state": str(
                fresh_progress.get("visible_dossier_closure_state", "") or ""
            ),
            "stop_requested": True,
            "stop_result": stop_result,
            "latest_progress": dict(fresh_progress),
            "updated_at": _utc_now(),
        }
    )
    if child_id:
        _write_json(_child_path(operator_root, child_id), finalized)
    directive_id = str(finalized.get("directive_id", "") or "")
    if directive_id:
        directive_path = _directive_path(operator_root, directive_id)
        directive = _read_json(directive_path)
        if directive:
            metadata = dict(directive.get("metadata", {}) or {})
            metadata["implementation_readiness_review_finalized"] = True
            metadata["implementation_readiness_review_return_packet_id"] = str(
                packet.get("return_packet_id", "") or ""
            )
            metadata["visible_dossier_closure_state"] = str(
                fresh_progress.get("visible_dossier_closure_state", "") or ""
            )
            metadata["support_admission_state"] = "operator_review_required"
            metadata["support_blocker_reason"] = "operator_review_required"
            metadata["next_support_recovery_action"] = "operator_review_implementation_readiness_dossier"
            directive["metadata"] = metadata
            directive["active_child_run_id"] = ""
            directive["updated_at"] = _utc_now()
            _write_json(directive_path, directive)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "implementation_readiness_review_finalized",
            "generated_at": _utc_now(),
            "child_run_id": child_id,
            "directive_id": directive_id,
            "return_packet_id": str(packet.get("return_packet_id", "") or ""),
            "visible_dossier_closure_state": str(fresh_progress.get("visible_dossier_closure_state", "") or ""),
            "pending_return_created": True,
            "grants_execution_authority": False,
        },
    )
    return finalized


def _resident_support_handoff_stale_seconds() -> float:
    try:
        return max(0.0, float(os.environ.get("NOVALI_RESIDENT_SUPPORT_HANDOFF_STALE_SECONDS", "300")))
    except (TypeError, ValueError):
        return 300.0


def _support_checkout_row_count(child: Mapping[str, Any]) -> int:
    manifest = dict(child.get("support_pack_manifest", {}) or {})
    try:
        row_count = int(manifest.get("total_row_count", 0) or 0)
    except (TypeError, ValueError):
        row_count = 0
    if row_count > 0:
        return row_count
    raw_checkout_path = str(child.get("support_pack_checkout_path", "") or "").strip()
    checkout_path = Path(raw_checkout_path) if raw_checkout_path else Path()
    if raw_checkout_path:
        checkout_manifest = _read_json(checkout_path / "manifest.json")
        try:
            return int(checkout_manifest.get("total_row_count", 0) or 0)
        except (TypeError, ValueError):
            return 0
    return 0


def _current_satisfied_support_request_for_directive(
    operator_root: str | Path,
    *,
    directive: Mapping[str, Any],
    target_artifact: str,
) -> dict[str, Any]:
    directive_id = str(directive.get("directive_id", "") or "").strip()
    metadata = dict(directive.get("metadata", {}) or {})
    candidate_ids = [
        str(metadata.get("support_request_id", "") or "").strip(),
        str(metadata.get("current_linked_artifact_support_request_id", "") or "").strip(),
    ]
    for support_id in [item for item in dict.fromkeys(candidate_ids) if item]:
        support = _read_json(_support_request_path(operator_root, support_id))
        if not support:
            continue
        if str(support.get("directive_id", "") or "") not in {"", directive_id, "[REDACTED]"}:
            continue
        if _support_request_state_value(support) != "satisfied":
            continue
        support_target = str(support.get("target_artifact", "") or "").strip()
        if target_artifact != "implementation_readiness_review.json" and support_target != target_artifact:
            continue
        return support
    newest: dict[str, Any] = {}
    newest_mtime = -1.0
    for support_path in _support_requests_root(operator_root).glob("*.json"):
        support = _read_json(support_path)
        if str(support.get("directive_id", "") or "") not in {"", directive_id, "[REDACTED]"}:
            continue
        if _support_request_state_value(support) != "satisfied":
            continue
        support_target = str(support.get("target_artifact", "") or "").strip()
        if target_artifact != "implementation_readiness_review.json" and support_target != target_artifact:
            continue
        try:
            mtime = support_path.stat().st_mtime
        except OSError:
            mtime = 0.0
        if mtime > newest_mtime:
            newest = support
            newest_mtime = mtime
    return newest


def _resident_child_handoff_assessment(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    target_artifact = (
        _resident_target_artifact_from_progress(latest_progress)
        or str(child.get("latest_work_order_target_artifact", "") or child.get("latest_target_artifact", "") or "").strip()
    )
    inbox_payload = _read_json(_child_inbox_path(child))
    inbox_work_order = _latest_inbox_work_order(inbox_payload)
    inbox_work_order_id = str(inbox_work_order.get("work_order_id", "") or "").strip()
    inbox_target = str(inbox_work_order.get("target_artifact", "") or "").strip()
    wake_work_order_id = str(inbox_payload.get("wake_work_order_id", "") or "").strip()
    checkout_rows = _support_checkout_row_count(child)
    progress_sleep_reason = str(latest_progress.get("sleep_reason", "") or "").strip()
    try:
        progress_rows_read = int(latest_progress.get("support_pack_rows_read", 0) or 0)
    except (TypeError, ValueError):
        progress_rows_read = 0
    try:
        progress_consumable_count = int(latest_progress.get("support_pack_consumable_count", 0) or 0)
    except (TypeError, ValueError):
        progress_consumable_count = 0
    support_adequacy_state = str(latest_progress.get("support_adequacy_state", "") or "").strip()
    work_order_support_state = str(inbox_work_order.get("support_state", "") or "").strip()
    work_order_support_not_required_reason = str(
        inbox_work_order.get("support_not_required_reason", "") or ""
    ).strip()
    support_not_required_for_target = bool(
        work_order_support_not_required_reason
        or work_order_support_state == "not_required"
        or (
            support_adequacy_state == "not_required"
            and target_artifact != "implementation_readiness_review.json"
        )
    )
    heartbeat = _resident_progress_heartbeat(child, latest_progress)
    try:
        age_seconds = float(heartbeat.get("progress_checkpoint_age_seconds", 0.0) or 0.0)
    except (TypeError, ValueError):
        age_seconds = 0.0
    blockers: list[str] = []
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        blockers.append("not_resident_campaign_child")
    if not inbox_work_order_id:
        blockers.append("inbox_work_order_missing")
    if inbox_work_order_id and wake_work_order_id != inbox_work_order_id:
        blockers.append("inbox_wake_token_missing")
    if target_artifact and inbox_target and inbox_target != target_artifact:
        blockers.append("handoff_target_mismatch")
    if (
        progress_sleep_reason == "waiting_for_support_pack_evidence"
        and progress_rows_read <= 0
        and progress_consumable_count <= 0
        and checkout_rows <= 0
        and not support_not_required_for_target
    ):
        blockers.append("support_pack_evidence_missing")
    stale_threshold = _resident_support_handoff_stale_seconds()
    state = "valid" if not blockers else "missing_or_incomplete"
    return {
        "schema_name": "ResidentChildHandoffAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "child_run_id": child_id,
        "directive_id": directive_id,
        "target_artifact": target_artifact,
        "resident_support_handoff_state": state,
        "resident_support_handoff_blockers": blockers,
        "resident_support_handoff_stale_seconds": round(age_seconds, 3),
        "resident_support_handoff_stale_threshold_seconds": stale_threshold,
        "resident_support_handoff_stale": bool(blockers and age_seconds >= stale_threshold),
        "inbox_work_order_present": bool(inbox_work_order_id),
        "inbox_wake_token_present": bool(inbox_work_order_id and wake_work_order_id == inbox_work_order_id),
        "support_checkout_rows_available": checkout_rows,
        "support_handoff_target_match": bool(not target_artifact or not inbox_target or inbox_target == target_artifact),
        "latest_inbox_work_order_id": inbox_work_order_id,
        "latest_inbox_work_order_target_artifact": inbox_target,
        "wake_work_order_id": wake_work_order_id,
        "grants_execution_authority": False,
    }


def _resident_handoff_repair_required(
    assessment: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> bool:
    blockers = {
        str(item or "").strip()
        for item in list(assessment.get("resident_support_handoff_blockers", []) or [])
        if str(item or "").strip()
    }
    if str(latest_progress.get("cycle_outcome", "") or "").strip() == "synthesis_in_progress":
        return False
    sleep_reason = str(latest_progress.get("sleep_reason", "") or "").strip()
    if sleep_reason == "waiting_for_support_pack_evidence":
        return True
    if (
        "inbox_wake_token_missing" in blockers
        and str(latest_progress.get("cycle_outcome", "") or "").strip() == "artifact_delta"
    ):
        return True
    return bool(blockers.intersection({"support_pack_evidence_missing", "handoff_target_mismatch"}))


def _repair_resident_support_handoff(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    target_artifact: str,
) -> dict[str, Any]:
    directive_id = str(child.get("directive_id", "") or "").strip()
    directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    support = _current_satisfied_support_request_for_directive(
        operator_root,
        directive=directive,
        target_artifact=target_artifact,
    )
    if not support:
        return {
            "ok": False,
            "support_handoff_repair_state": "no_satisfied_current_support",
            "support_handoff_repaired_work_order_id": "",
        }
    repaired = _materialize_support_for_running_resident_child(
        operator_root,
        state_root=state_root,
        child=child,
        latest_progress=latest_progress,
        target_artifact=target_artifact,
        support_request=support,
    )
    child_id = str(child.get("child_run_id", "") or "").strip()
    child_after = _read_json(_child_path(operator_root, child_id)) if child_id else {}
    state = "repaired" if bool(repaired.get("ok", False)) else str(
        repaired.get("support_materialization_state", "") or "repair_failed"
    )
    if child_after:
        child_after["resident_support_handoff_state"] = state
        child_after["support_handoff_repair_state"] = str(
            repaired.get("support_materialization_state", "") or state
        )
        child_after["support_handoff_repaired_work_order_id"] = str(repaired.get("work_order_id", "") or "")
        child_after["support_checkout_rows_available"] = int(repaired.get("support_pack_rows_available", 0) or 0)
        child_after["updated_at"] = _utc_now()
        _write_json(_child_path(operator_root, child_id), child_after)
    return {
        **dict(repaired),
        "support_handoff_repair_state": str(repaired.get("support_materialization_state", "") or state),
        "support_handoff_repaired_work_order_id": str(repaired.get("work_order_id", "") or ""),
    }


def _finalize_resident_missing_support_handoff(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    assessment: Mapping[str, Any],
    runner: ConveyorChildRunner,
) -> dict[str, Any] | None:
    if not bool(assessment.get("resident_support_handoff_stale", False)):
        return None
    fresh_progress = _latest_child_progress(child)
    fresh_assessment = _resident_child_handoff_assessment(
        operator_root,
        child=child,
        latest_progress=fresh_progress,
    )
    if not bool(fresh_assessment.get("resident_support_handoff_stale", False)):
        return None
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    try:
        stop_result = dict(runner.stop_child_container(dict(child)) or {})
    except Exception as exc:
        stop_result = {"ok": False, "state": "stop_failed", "error_class": type(exc).__name__, "error": str(exc)}
    now = _utc_now()
    finalized = dict(child)
    finalized.update(
        {
            "state": "stopped" if bool(stop_result.get("ok", False)) else "blocked",
            "stop_requested": True,
            "stop_result": stop_result,
            "child_lifecycle_classification": "blocked_pass_completed_not_review_ready",
            "blocked_pass_completed_not_review_ready": True,
            "non_reviewable_pass_result": True,
            "resident_support_handoff_finalized": True,
            "resident_support_handoff_state": "finalized_missing_handoff",
            "resident_support_handoff_blockers": list(
                fresh_assessment.get("resident_support_handoff_blockers", []) or []
            ),
            "resident_support_handoff_stale_seconds": float(
                fresh_assessment.get("resident_support_handoff_stale_seconds", 0.0) or 0.0
            ),
            "latest_progress": dict(fresh_progress),
            "updated_at": now,
        }
    )
    if child_id:
        _write_json(_child_path(operator_root, child_id), finalized)
    if directive_id:
        directive = _read_json(_directive_path(operator_root, directive_id))
        if directive:
            directive["state"] = "blocked_for_support"
            directive["active_child_run_id"] = ""
            directive["blocked_reason"] = "resident_support_handoff_missing"
            metadata = dict(directive.get("metadata", {}) or {})
            metadata["child_lifecycle_classification"] = "blocked_pass_completed_not_review_ready"
            metadata["resident_support_handoff_finalized"] = True
            metadata["resident_support_handoff_state"] = "finalized_missing_handoff"
            metadata["resident_support_handoff_blockers"] = list(
                fresh_assessment.get("resident_support_handoff_blockers", []) or []
            )
            metadata["resident_support_handoff_stale_seconds"] = float(
                fresh_assessment.get("resident_support_handoff_stale_seconds", 0.0) or 0.0
            )
            metadata["support_blocker_reason"] = "resident_support_handoff_missing"
            metadata["support_admission_state"] = "support_handoff_missing"
            directive["metadata"] = metadata
            directive["updated_at"] = now
            _write_json(_directive_path(operator_root, directive_id), directive)
        release_task_manager_lease(
            operator_root,
            directive_id=directive_id,
            child_run_id=child_id,
            reason="resident_support_handoff_missing",
        )
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_support_handoff_finalized",
            "generated_at": now,
            "child_run_id": child_id,
            "directive_id": directive_id,
            "target_artifact": str(fresh_assessment.get("target_artifact", "") or ""),
            "resident_support_handoff_blockers": list(
                fresh_assessment.get("resident_support_handoff_blockers", []) or []
            ),
            "pending_return_created": False,
            "grants_execution_authority": False,
        },
    )
    return finalized


def bounded_reconcile_child_progress(
    operator_root: str | Path,
    *,
    state_root: str | Path | None = None,
    runner: ConveyorChildRunner | None = None,
    directive_id: str = "",
    child_run_id: str = "",
    finalize_no_delta: bool = True,
    persist_snapshot: bool = False,
) -> dict[str, Any]:
    started = time.perf_counter()
    initialize_conveyor_state(operator_root)
    target_directive_id = str(directive_id or "").strip()
    target_child_id = str(child_run_id or "").strip()
    mirrored = 0
    finalized_count = 0
    finalized_child_ids: list[str] = []
    no_first_checkpoint_finalized_count = 0
    no_first_checkpoint_finalized_child_ids: list[str] = []
    synthesis_stalled_finalized_count = 0
    synthesis_stalled_finalized_child_ids: list[str] = []
    implementation_readiness_review_finalized_count = 0
    implementation_readiness_review_finalized_child_ids: list[str] = []
    support_handoff_repaired_count = 0
    support_handoff_repaired_child_ids: list[str] = []
    support_handoff_finalized_count = 0
    support_handoff_finalized_child_ids: list[str] = []
    no_delta_followup_work_order_repaired_count = 0
    no_delta_followup_work_order_repaired_child_ids: list[str] = []
    implementation_readiness_content_depth_repaired_count = 0
    implementation_readiness_content_depth_repaired_child_ids: list[str] = []
    technical_documentation_depth_repaired_count = 0
    technical_documentation_depth_repaired_child_ids: list[str] = []
    technical_documentation_depth_plateau_finalized_count = 0
    technical_documentation_depth_plateau_finalized_child_ids: list[str] = []
    records: list[dict[str, Any]] = []
    effective_runner = runner
    for child in _active_children(operator_root):
        current_child_id = str(child.get("child_run_id", "") or "").strip()
        current_directive_id = str(child.get("directive_id", "") or "").strip()
        if target_child_id and current_child_id != target_child_id:
            continue
        if target_directive_id and current_directive_id != target_directive_id:
            continue
        if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
            continue
        latest_progress = _latest_child_progress(child)
        if not latest_progress:
            inspect_state = {"state": "running", "bounded_reconcile_assumed_running": True}
            assessment = _resident_no_first_checkpoint_assessment(child, inspect_state=inspect_state)
            updated = dict(child)
            updated.update(
                {
                    "child_runtime_no_first_checkpoint": bool(
                        assessment.get("child_runtime_no_first_checkpoint", False)
                    ),
                    "first_checkpoint_age_seconds": float(
                        assessment.get("first_checkpoint_age_seconds", 0.0) or 0.0
                    ),
                    "last_compute_phase": str(assessment.get("last_compute_phase", "") or ""),
                    "last_heartbeat_at": str(assessment.get("last_heartbeat_at", "") or ""),
                    "resident_no_first_checkpoint_finalizer_eligible": bool(
                        assessment.get("resident_no_first_checkpoint_finalizer_eligible", False)
                    ),
                    "resident_no_first_checkpoint_blockers": list(
                        assessment.get("resident_no_first_checkpoint_blockers", []) or []
                    ),
                    "bounded_reconcile_progress_state": "phase_heartbeat_mirrored_no_first_checkpoint",
                    "bounded_reconcile_progress_mirrored_at": _utc_now(),
                }
            )
            if current_child_id:
                _write_json(_child_path(operator_root, current_child_id), updated)
            mirrored += 1
            if bool(assessment.get("resident_no_first_checkpoint_finalizer_eligible", False)):
                if effective_runner is None:
                    effective_runner = runner_from_scheduler(_load_scheduler(operator_root))
                finalized = _finalize_resident_no_first_checkpoint(
                    operator_root,
                    child=updated,
                    inspect_state=inspect_state,
                    runner=effective_runner,
                )
                if finalized is not None:
                    no_first_checkpoint_finalized_count += 1
                    no_first_checkpoint_finalized_child_ids.append(
                        str(finalized.get("child_run_id", "") or current_child_id)
                    )
                    records.append(finalized)
                    continue
            records.append(updated)
            continue
        updated = _mirror_resident_child_progress_checkpoint(
            operator_root,
            child=child,
            latest_progress=latest_progress,
        )
        mirrored += 1
        handoff_assessment = _resident_child_handoff_assessment(
            operator_root,
            child=updated,
            latest_progress=latest_progress,
        )
        updated.update(
            {
                "resident_support_handoff_state": str(
                    handoff_assessment.get("resident_support_handoff_state", "") or ""
                ),
                "resident_support_handoff_blockers": list(
                    handoff_assessment.get("resident_support_handoff_blockers", []) or []
                ),
                "resident_support_handoff_stale_seconds": float(
                    handoff_assessment.get("resident_support_handoff_stale_seconds", 0.0) or 0.0
                ),
                "inbox_work_order_present": bool(handoff_assessment.get("inbox_work_order_present", False)),
                "inbox_wake_token_present": bool(handoff_assessment.get("inbox_wake_token_present", False)),
                "support_checkout_rows_available": int(
                    handoff_assessment.get("support_checkout_rows_available", 0) or 0
                ),
                "support_handoff_target_match": bool(
                    handoff_assessment.get("support_handoff_target_match", False)
                ),
            }
        )
        if current_child_id:
            _write_json(_child_path(operator_root, current_child_id), updated)
        followup_repair = _repair_active_resident_no_delta_followup_work_order(
            operator_root,
            state_root=state_root or operator_root,
            child=updated,
            latest_progress=latest_progress,
        )
        if bool(followup_repair.get("ok", False)):
            repaired_child = _read_json(_child_path(operator_root, current_child_id)) if current_child_id else updated
            no_delta_followup_work_order_repaired_count += 1
            no_delta_followup_work_order_repaired_child_ids.append(current_child_id)
            records.append(repaired_child or updated)
            continue
        content_depth_repair = _repair_implementation_readiness_content_depth_work_order(
            operator_root,
            state_root=state_root or operator_root,
            child=updated,
            latest_progress=latest_progress,
        )
        if bool(content_depth_repair.get("ok", False)):
            repaired_child = _read_json(_child_path(operator_root, current_child_id)) if current_child_id else updated
            implementation_readiness_content_depth_repaired_count += 1
            implementation_readiness_content_depth_repaired_child_ids.append(current_child_id)
            records.append(repaired_child or updated)
            continue
        technical_doc_repair = _repair_technical_documentation_depth_work_order(
            operator_root,
            state_root=state_root or operator_root,
            child=updated,
            latest_progress=latest_progress,
        )
        if bool(technical_doc_repair.get("ok", False)):
            repaired_child = _read_json(_child_path(operator_root, current_child_id)) if current_child_id else updated
            technical_documentation_depth_repaired_count += 1
            technical_documentation_depth_repaired_child_ids.append(current_child_id)
            records.append(repaired_child or updated)
            continue
        if finalize_no_delta:
            if effective_runner is None:
                effective_runner = runner_from_scheduler(_load_scheduler(operator_root))
            technical_doc_finalized = _finalize_technical_documentation_depth_plateau(
                operator_root,
                child=updated,
                latest_progress=latest_progress,
                runner=effective_runner,
            )
            if technical_doc_finalized is not None:
                technical_documentation_depth_plateau_finalized_count += 1
                technical_documentation_depth_plateau_finalized_child_ids.append(
                    str(technical_doc_finalized.get("child_run_id", "") or current_child_id)
                )
                records.append(technical_doc_finalized)
                continue
        if (
            str(handoff_assessment.get("resident_support_handoff_state", "") or "") != "valid"
            and _resident_handoff_repair_required(handoff_assessment, latest_progress)
        ):
            target_artifact = str(handoff_assessment.get("target_artifact", "") or "")
            repair = _repair_resident_support_handoff(
                operator_root,
                state_root=state_root or operator_root,
                child=updated,
                latest_progress=latest_progress,
                target_artifact=target_artifact,
            )
            if bool(repair.get("ok", False)):
                repaired_child = _read_json(_child_path(operator_root, current_child_id)) if current_child_id else updated
                support_handoff_repaired_count += 1
                support_handoff_repaired_child_ids.append(current_child_id)
                records.append(repaired_child or updated)
                continue
            if bool(handoff_assessment.get("resident_support_handoff_stale", False)):
                if effective_runner is None:
                    effective_runner = runner_from_scheduler(_load_scheduler(operator_root))
                finalized = _finalize_resident_missing_support_handoff(
                    operator_root,
                    child=updated,
                    latest_progress=latest_progress,
                    assessment=handoff_assessment,
                    runner=effective_runner,
                )
                if finalized is not None:
                    support_handoff_finalized_count += 1
                    support_handoff_finalized_child_ids.append(
                        str(finalized.get("child_run_id", "") or current_child_id)
                    )
                    records.append(finalized)
                    continue
        review_finalized = _finalize_implementation_readiness_review_pass(
            operator_root,
            child=updated,
            latest_progress=latest_progress,
            runner=effective_runner or runner_from_scheduler(_load_scheduler(operator_root)),
        )
        if review_finalized is not None:
            implementation_readiness_review_finalized_count += 1
            implementation_readiness_review_finalized_child_ids.append(
                str(review_finalized.get("child_run_id", "") or current_child_id)
            )
            records.append(review_finalized)
            continue
        synthesis_assessment = _resident_synthesis_stalled_assessment(
            updated,
            latest_progress,
            inspect_state={"state": "running", "bounded_reconcile_assumed_running": True},
        )
        updated.update(
            {
                "resident_synthesis_stalled_finalizer_eligible": bool(
                    synthesis_assessment.get("resident_synthesis_stalled_finalizer_eligible", False)
                ),
                "resident_synthesis_checkpoint_age_seconds": float(
                    synthesis_assessment.get("resident_synthesis_checkpoint_age_seconds", 0.0) or 0.0
                ),
                "resident_synthesis_stalled_blockers": list(
                    synthesis_assessment.get("resident_synthesis_stalled_blockers", []) or []
                ),
            }
        )
        if current_child_id:
            _write_json(_child_path(operator_root, current_child_id), updated)
        if bool(synthesis_assessment.get("resident_synthesis_stalled_finalizer_eligible", False)):
            if effective_runner is None:
                effective_runner = runner_from_scheduler(_load_scheduler(operator_root))
            finalized = _finalize_resident_synthesis_stalled(
                operator_root,
                child=updated,
                latest_progress=latest_progress,
                inspect_state={"state": "running", "bounded_reconcile_assumed_running": True},
                runner=effective_runner,
            )
            if finalized is not None:
                synthesis_stalled_finalized_count += 1
                synthesis_stalled_finalized_child_ids.append(
                    str(finalized.get("child_run_id", "") or current_child_id)
                )
                records.append(finalized)
                continue
        if finalize_no_delta:
            eligible, _blockers = _resident_support_backed_no_delta_finalizer_eligible(
                updated,
                latest_progress,
            )
            if eligible:
                if effective_runner is None:
                    effective_runner = runner_from_scheduler(_load_scheduler(operator_root))
                finalized = _finalize_support_backed_no_delta_resident_pass(
                    operator_root,
                    child=updated,
                    latest_progress=latest_progress,
                    runner=effective_runner,
                )
                if finalized is not None:
                    finalized_count += 1
                    finalized_child_ids.append(str(finalized.get("child_run_id", "") or current_child_id))
                    records.append(finalized)
                    continue
        records.append(updated)
    snapshot_state = "deferred"
    snapshot_error = ""
    if persist_snapshot:
        try:
            snapshot = build_task_manager_snapshot(operator_root, persist=True)
            persist_bounded_status_snapshot(
                operator_root,
                task_manager_snapshot=snapshot,
                refreshed_by="bounded_resident_child_progress_reconcile",
            )
            snapshot_state = "completed"
        except Exception as exc:
            snapshot_state = "deferred"
            snapshot_error = f"{type(exc).__name__}: {exc}"
    return {
        "ok": True,
        "schema_name": "BoundedResidentChildProgressReconciliation",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "bounded_reconcile_state": "completed",
        "phase_policy": "bounded_resident_child_progress",
        "mirrored_child_count": mirrored,
        "resident_no_delta_finalized_count": finalized_count,
        "resident_no_delta_finalized_child_ids": finalized_child_ids,
        "resident_no_first_checkpoint_finalized_count": no_first_checkpoint_finalized_count,
        "resident_no_first_checkpoint_finalized_child_ids": no_first_checkpoint_finalized_child_ids,
        "resident_synthesis_stalled_finalized_count": synthesis_stalled_finalized_count,
        "resident_synthesis_stalled_finalized_child_ids": synthesis_stalled_finalized_child_ids,
        "implementation_readiness_review_finalized_count": implementation_readiness_review_finalized_count,
        "implementation_readiness_review_finalized_child_ids": implementation_readiness_review_finalized_child_ids,
        "resident_support_handoff_repaired_count": support_handoff_repaired_count,
        "resident_support_handoff_repaired_child_ids": support_handoff_repaired_child_ids,
        "resident_support_handoff_finalized_count": support_handoff_finalized_count,
        "resident_support_handoff_finalized_child_ids": support_handoff_finalized_child_ids,
        "resident_no_delta_followup_work_order_repaired_count": no_delta_followup_work_order_repaired_count,
        "resident_no_delta_followup_work_order_repaired_child_ids": no_delta_followup_work_order_repaired_child_ids,
        "implementation_readiness_content_depth_repaired_count": implementation_readiness_content_depth_repaired_count,
        "implementation_readiness_content_depth_repaired_child_ids": implementation_readiness_content_depth_repaired_child_ids,
        "technical_documentation_depth_repaired_count": technical_documentation_depth_repaired_count,
        "technical_documentation_depth_repaired_child_ids": technical_documentation_depth_repaired_child_ids,
        "technical_documentation_depth_plateau_finalized_count": technical_documentation_depth_plateau_finalized_count,
        "technical_documentation_depth_plateau_finalized_child_ids": technical_documentation_depth_plateau_finalized_child_ids,
        "pending_return_count_created": implementation_readiness_review_finalized_count,
        "reconcile_heavy_phases_skipped": True,
        "skipped_phases": [
            "docker_inspect",
            "return_collection",
            "draft_quality_assessment",
            "campaign_manifest_refresh",
            "provider_support_acquisition",
            "scheduler_admission",
            "terminal_container_cleanup",
        ],
        "task_manager_snapshot_refresh_state": snapshot_state,
        "task_manager_snapshot_refresh_error": snapshot_error,
        "duration_ms": round((time.perf_counter() - started) * 1000, 3),
        "records": records,
        "grants_execution_authority": False,
    }


def _refresh_stale_risk_control_support_from_satisfied_bom_supports(
    operator_root: str | Path,
) -> dict[str, Any]:
    refreshed: list[dict[str, Any]] = []
    for risk_support in _load_items(_support_requests_root(operator_root)):
        if str(risk_support.get("target_artifact", "") or "") != "risk_controls.json":
            continue
        if _support_request_state_value(risk_support) != "satisfied":
            continue
        requested_ids = _risk_control_requested_row_ids(risk_support)
        if not requested_ids:
            continue
        accepted_ids = {
            str(item or "").strip()
            for item in list(risk_support.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        }
        uncovered_ids = [
            str(item or "").strip()
            for item in list(risk_support.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ] or [requested_id for requested_id in requested_ids if requested_id not in accepted_ids]
        design_only = bool(
            risk_support.get("risk_control_design_reduction_only", False)
            or str(risk_support.get("child_work_mode", "") or "") == "design_only_reduction"
        )
        if not uncovered_ids:
            continue
        repaired = dict(risk_support)
        _set_support_request_state(
            repaired,
            "commercial_source_acquisition_required" if design_only else "pending_operator_review",
        )
        repaired["operator_review_required"] = True
        repaired["support_blocker_reason"] = "risk_control_requested_rows_uncovered"
        repaired["support_pack_consumability_state"] = "diagnostic_requested_row_incomplete"
        repaired["support_materialization_state"] = "waiting_for_consumable_support"
        repaired["risk_support_current_state"] = _support_request_state_value(repaired)
        repaired["risk_control_support_refresh_state"] = (
            "repaired_design_only_fmea_to_source_acquisition"
            if design_only
            else "repaired_satisfied_without_fmea_row_coverage"
        )
        repaired["risk_control_support_provider_quality_blocker"] = "risk_control_requested_rows_uncovered"
        if design_only:
            repaired["commercial_source_acquisition_required"] = True
            repaired["source_backed_rows_required"] = True
            repaired["design_brief_diagnostic_only"] = True
            repaired["r_and_d_design_brief_ready"] = False
            repaired["child_work_mode"] = ""
            repaired["candidate_ingestion_state"] = "commercial_source_acquisition_required"
            repaired["support_recovery_state"] = "commercial_source_acquisition_required"
            repaired["next_support_recovery_action"] = "run_provider_field_lane_source_acquisition"
        repaired["uncovered_requested_row_ids"] = uncovered_ids
        repaired = _apply_risk_control_support_acquisition_fields(repaired, state="incomplete")
        repaired["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, str(repaired.get("support_request_id", "") or "")), repaired)
        directive_id = str(repaired.get("directive_id", "") or "").strip()
        if directive_id:
            directive_path = _directive_path(operator_root, directive_id)
            directive = _read_json(directive_path)
            if directive:
                metadata = dict(directive.get("metadata", {}) or {})
                metadata.update(
                    {
                        "support_request_id": str(repaired.get("support_request_id", "") or ""),
                        "current_risk_control_support_request_id": str(repaired.get("support_request_id", "") or ""),
                        "support_blocker_target_artifact": "risk_controls.json",
                        "support_blocker_reason": "risk_control_requested_rows_uncovered",
                        "risk_support_current_state": _support_request_state_value(repaired),
                        "uncovered_fmea_requested_row_ids": list(
                            repaired.get("uncovered_fmea_requested_row_ids", []) or []
                        ),
                        "commercial_source_acquisition_required": bool(
                            repaired.get("commercial_source_acquisition_required", False)
                        ),
                        "source_backed_rows_required": bool(
                            repaired.get("source_backed_rows_required", False)
                        ),
                        "design_brief_diagnostic_only": bool(
                            repaired.get("design_brief_diagnostic_only", False)
                        ),
                        "r_and_d_design_brief_ready": bool(
                            repaired.get("r_and_d_design_brief_ready", False)
                        ),
                        "child_work_mode": str(repaired.get("child_work_mode", "") or ""),
                    }
                )
                directive["metadata"] = metadata
                directive["state"] = "blocked_for_support"
                directive["updated_at"] = repaired["updated_at"]
                _write_json(directive_path, directive)
        _append_ledger(
            operator_root,
            "support_request_events",
            {
                "event": "risk_control_support_repaired_missing_requested_row_coverage",
                "generated_at": repaired["updated_at"],
                "support_request_id": str(repaired.get("support_request_id", "") or ""),
                "directive_id": directive_id,
                "target_artifact": "risk_controls.json",
                "uncovered_fmea_requested_row_ids": list(
                    repaired.get("uncovered_fmea_requested_row_ids", []) or []
                ),
                "grants_execution_authority": False,
            },
        )
        _record_risk_control_support_acquisition_evidence(
            operator_root,
            support=repaired,
            support_rows=[],
        )
        refreshed.append(
            {
                "support_request_id": str(repaired.get("support_request_id", "") or ""),
                "directive_id": directive_id,
                "target_artifact": "risk_controls.json",
                "missing_fmea_row_refs": list(repaired.get("missing_fmea_row_refs", []) or []),
                "refresh_state": str(
                    repaired.get("risk_control_support_refresh_state", "")
                    or "repaired_satisfied_without_fmea_row_coverage"
                ),
            }
        )
    for support in _load_items(_support_requests_root(operator_root)):
        if str(support.get("target_artifact", "") or "") != "bill_of_materials.json":
            continue
        if _support_request_state_value(support) != "satisfied":
            continue
        risk_support_id = str(support.get("risk_control_support_request_id", "") or "").strip()
        if not risk_support_id:
            continue
        risk_support = _read_json(_support_request_path(operator_root, risk_support_id))
        if _support_request_state_value(risk_support) != "superseded":
            continue
        risk_refs = [
            str(item).strip()
            for item in list(
                support.get("missing_fmea_row_refs", [])
                or risk_support.get("missing_fmea_row_refs", [])
                or []
            )
            if str(item).strip()
        ]
        if not risk_refs:
            continue
        synthetic_bom_rows = [
            {
                "target_artifact": "bill_of_materials.json",
                "linked_risk_control_ref": ref,
                "spec_values": {"linked_risk_control_ref": ref},
                "grants_execution_authority": False,
            }
            for ref in risk_refs
        ]
        _updated_support, refreshed_risk = _prepare_risk_control_support_chain_from_bom_support(
            operator_root,
            support=support,
            support_rows=synthetic_bom_rows,
        )
        if refreshed_risk:
            refreshed.append(
                {
                    "support_request_id": risk_support_id,
                    "source_bom_support_request_id": str(support.get("support_request_id", "") or ""),
                    "directive_id": str(support.get("directive_id", "") or ""),
                    "target_artifact": "risk_controls.json",
                    "missing_fmea_row_refs": list(refreshed_risk.get("missing_fmea_row_refs", []) or []),
                    "refresh_state": str(
                        refreshed_risk.get("risk_control_support_refresh_state", "")
                        or "risk_control_support_refreshed"
                    ),
                }
            )
    return {
        "risk_control_support_refresh_count": len(refreshed),
        "risk_control_support_refreshes": refreshed,
    }


def _refresh_validation_fixture_support_from_satisfied_risk_controls(
    operator_root: str | Path,
) -> dict[str, Any]:
    refreshed: list[dict[str, Any]] = []
    for support in _load_items(_support_requests_root(operator_root)):
        if str(support.get("target_artifact", "") or "") != "risk_controls.json":
            continue
        if _support_request_state_value(support) != "satisfied":
            continue
        requested_ids = _risk_control_requested_row_ids(support)
        accepted_ids = {
            str(item or "").strip()
            for item in list(
                support.get("accepted_requested_row_ids", [])
                or support.get("accepted_fmea_requested_row_ids", [])
                or []
            )
            if str(item or "").strip()
        }
        uncovered_ids = [
            str(item or "").strip()
            for item in list(
                support.get("uncovered_requested_row_ids", [])
                or support.get("uncovered_fmea_requested_row_ids", [])
                or []
            )
            if str(item or "").strip()
        ]
        if requested_ids and (uncovered_ids or not set(requested_ids).issubset(accepted_ids)):
            continue
        updated_support, fixture_support = _prepare_validation_fixture_support_chain_from_risk_controls(
            operator_root,
            support=support,
        )
        if fixture_support:
            _write_json(
                _support_request_path(
                    operator_root,
                    str(updated_support.get("support_request_id", "") or support.get("support_request_id", "") or ""),
                ),
                updated_support,
            )
            refreshed.append(
                {
                    "support_request_id": str(fixture_support.get("support_request_id", "") or ""),
                    "source_risk_support_request_id": str(support.get("support_request_id", "") or ""),
                    "directive_id": str(fixture_support.get("directive_id", "") or ""),
                    "target_artifact": "validation_fixtures.json",
                    "missing_validation_fixture_refs": list(
                        fixture_support.get("missing_validation_fixture_refs", []) or []
                    ),
                    "refresh_state": str(
                        fixture_support.get("validation_fixture_support_refresh_state", "")
                        or "validation_fixture_support_requested"
                    ),
                }
            )
    return {
        "validation_fixture_support_refresh_count": len(refreshed),
        "validation_fixture_support_refreshes": refreshed,
    }


def _clear_directive_design_only_support_metadata(
    operator_root: str | Path,
    *,
    support: Mapping[str, Any],
) -> None:
    directive_id = str(support.get("directive_id", "") or "").strip()
    support_id = str(support.get("support_request_id", "") or "").strip()
    if not directive_id or not support_id:
        return
    directive_path = _directive_path(operator_root, directive_id)
    directive = _read_json(directive_path)
    if not directive:
        return
    metadata = dict(directive.get("metadata", {}) or {})
    metadata_points_elsewhere = str(metadata.get("support_request_id", "") or "") != support_id
    metadata_hard_commercial_blocker = bool(
        metadata.get("commercial_source_acquisition_required", False)
        or metadata.get("source_backed_rows_required", False)
        or list(metadata.get("uncovered_requested_row_ids", []) or [])
        or str(metadata.get("provider_field_lane_request_id", "") or "").startswith("provider-field-lane")
    )
    metadata_stale_commercial_recovery = str(metadata.get("support_recovery_state", "") or "") in {
        "commercial_source_acquisition_required",
        "source_backed_rows_required",
    }
    stale_commercial_blocked_reasons = {
        "source_backed_rows_required",
        "source_backed_magnetic_bom_lane_rows_required",
        "commercial_source_acquisition_required",
    }
    blocked_reason = str(directive.get("blocked_reason", "") or "")
    directive_stale_commercial_blocker = blocked_reason in stale_commercial_blocked_reasons
    if (
        metadata_points_elsewhere
        and not metadata_hard_commercial_blocker
        and not metadata_stale_commercial_recovery
        and not directive_stale_commercial_blocker
    ):
        return
    changed = False
    for key, value in (
        ("child_work_mode", ""),
        ("r_and_d_design_brief_ready", False),
        ("commercial_source_acquisition_required", False),
        ("source_backed_rows_required", False),
        ("support_admission_state", "adequate"),
        ("support_blocker_reason", ""),
        ("support_recovery_state", "satisfied"),
    ):
        if metadata.get(key) != value:
            metadata[key] = value
            changed = True
    accepted_ids = [
        str(item or "").strip()
        for item in list(support.get("accepted_requested_row_ids", []) or [])
        if str(item or "").strip()
    ]
    if accepted_ids and metadata.get("accepted_requested_row_ids") != accepted_ids:
        metadata["accepted_requested_row_ids"] = accepted_ids
        changed = True
    if metadata.get("uncovered_requested_row_ids") != []:
        metadata["uncovered_requested_row_ids"] = []
        changed = True
    if (
        not str(metadata.get("support_request_id", "") or "").strip()
        or (metadata_points_elsewhere and metadata_hard_commercial_blocker)
    ):
        metadata["support_request_id"] = support_id
        changed = True
    if str(metadata.get("provider_field_lane_request_id", "") or "").startswith("provider-field-lane"):
        metadata["previous_provider_field_lane_request_id"] = str(
            metadata.get("provider_field_lane_request_id", "") or ""
        )
        metadata["provider_field_lane_request_id"] = ""
        changed = True
    directive_changed = False
    if directive_stale_commercial_blocker:
        directive["blocked_reason"] = ""
        directive_changed = True
    if changed:
        metadata["source_backed_support_metadata_repaired"] = True
        metadata["source_backed_support_metadata_repaired_at"] = _utc_now()
        directive["metadata"] = metadata
        directive_changed = True
    if directive_changed:
        _write_json(directive_path, directive)


def _support_request_is_current_pointer_candidate(
    support: Mapping[str, Any],
    *,
    directive_id: str,
    target_artifact: str,
) -> bool:
    if str(support.get("directive_id", "") or "") != directive_id:
        return False
    if target_artifact and str(support.get("target_artifact", "") or "") != target_artifact:
        return False
    return _support_request_state_value(support) not in {
        "failed",
        "rejected",
        "superseded",
        "cancelled",
    }


def _repair_stale_satisfied_commercial_bom_support(
    operator_root: str | Path,
    *,
    support: Mapping[str, Any],
    metadata_uncovered_requested_ids: Iterable[Any] = (),
) -> tuple[dict[str, Any], bool]:
    current = dict(support)
    support_request_id = str(current.get("support_request_id", "") or "").strip()
    if not support_request_id:
        return current, False
    if str(current.get("target_artifact", "") or "") != "bill_of_materials.json":
        return current, False
    requested_rows = [
        dict(row)
        for row in list(current.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
    ]
    if not requested_rows:
        return current, False
    commercial_requested = any(
        bool(row.get("commercial_component_source_required", False))
        for row in requested_rows
    ) or bool(current.get("support_role_lane_required_roles"))
    if not commercial_requested:
        return current, False
    metadata_uncovered_values = [
        str(item or "").strip()
        for item in list(metadata_uncovered_requested_ids or [])
        if str(item or "").strip()
    ]
    metadata_uncovered: set[str] = set()
    for item in metadata_uncovered_values:
        if not item:
            continue
        metadata_uncovered.add(item)
        normalized_item = normalize_support_role_lane(item)
        if normalized_item:
            metadata_uncovered.add(normalized_item)
    if metadata_uncovered_values:
        default_required_fields = _support_field_coverage_list(
            requested_rows,
            _support_request_required_fields(current),
            [
                "manufacturer",
                "mpn",
                "datasheet_url",
                "electrical_rating",
                "quantity",
                "unit_cost",
                "alternatives",
                "measurable_spec",
                "substitution_allowed",
                "test_equipment",
                "risk_if_missing",
                "validation_fixture_ref",
                "linked_risk_control_ref",
                "standards_assumption",
                "go_no_go_trace",
            ],
        )
        active_rows: list[dict[str, Any]] = []
        matched_metadata: set[str] = set()
        for row in requested_rows:
            identity_values = {
                str(row.get("requested_row_id", "") or "").strip(),
                str(row.get("target_row_id", "") or "").strip(),
                str(row.get("design_artifact_row_id", "") or "").strip(),
                normalize_support_role_lane(row.get("target_role") or row.get("role")),
            }
            matched = {
                item
                for item in metadata_uncovered_values
                if item in identity_values or (normalize_support_role_lane(item) or item) in identity_values
            }
            if matched:
                active_rows.append(row)
                matched_metadata.update(matched)
        for item in metadata_uncovered_values:
            if item in matched_metadata:
                continue
            normalized_role = normalize_support_role_lane(item)
            new_row = {
                "requested_row_id": item,
                "target_artifact": "bill_of_materials.json",
                "target_row_id": item,
                "required_fields": default_required_fields,
                "commercial_component_source_required": True,
                "grants_execution_authority": False,
            }
            if normalized_role:
                new_row["target_role"] = normalized_role
            active_rows.append(new_row)
        if active_rows:
            requested_rows = active_rows

    pack_ref = _support_pack_ref_from_support_request(operator_root, current)
    evidence_rows: list[dict[str, Any]] = []
    if pack_ref:
        try:
            _source_path, _payload, evidence = _support_pack_evidence_for_ref(
                operator_root,
                pack_ref,
                target_artifact="bill_of_materials.json",
            )
            raw_payload_rows: list[dict[str, Any]] = []
            if isinstance(_payload, Mapping):
                for key in ("child_support_rows", "rows"):
                    raw_payload_rows.extend(
                        [
                            dict(row)
                            for row in list(_payload.get(key, []) or [])
                            if isinstance(row, Mapping)
                        ]
                    )
                summary = _payload.get("payload_summary", {})
                if isinstance(summary, Mapping):
                    raw_payload_rows.extend(
                        [
                            dict(row)
                            for row in list(summary.get("child_support_rows", []) or [])
                            if isinstance(row, Mapping)
                        ]
                    )
            evidence_rows = raw_payload_rows or [
                dict(row)
                for row in list(evidence.get("rows", []) or [])
                if isinstance(row, Mapping)
            ]
        except Exception:
            evidence_rows = []
    if not evidence_rows:
        evidence_rows = [
            dict(row)
            for row in list(
                current.get("accepted_field_lane_rows", [])
                or current.get("child_support_rows", [])
                or []
            )
            if isinstance(row, Mapping)
        ]

    coverage = assess_requested_row_coverage(
        evidence_rows,
        requested_rows=requested_rows,
        target_artifact="bill_of_materials.json",
    )
    forced_uncovered_ids: list[str] = []
    if metadata_uncovered:
        for row in requested_rows:
            requested_id = str(row.get("requested_row_id", "") or "").strip()
            identity_values = {
                requested_id,
                str(row.get("target_row_id", "") or "").strip(),
                str(row.get("design_artifact_row_id", "") or "").strip(),
                normalize_support_role_lane(row.get("target_role") or row.get("role")),
            }
            if any(value and value in metadata_uncovered for value in identity_values):
                forced_uncovered_ids.append(requested_id)
    accepted_ids = [
        str(item or "").strip()
        for item in list(coverage.get("accepted_requested_row_ids", []) or [])
        if str(item or "").strip()
    ]
    if forced_uncovered_ids:
        forced = set(forced_uncovered_ids)
        accepted_ids = [requested_id for requested_id in accepted_ids if requested_id not in forced]
    requested_ids = [
        str(row.get("requested_row_id", "") or "").strip()
        for row in requested_rows
        if str(row.get("requested_row_id", "") or "").strip()
    ]
    uncovered_ids = [
        requested_id
        for requested_id in requested_ids
        if requested_id and requested_id not in set(accepted_ids)
    ]
    split_blocking_state = (
        str(current.get("state", "") or "").strip()
        in {"commercial_source_acquisition_required", "source_backed_rows_required"}
        and str(current.get("support_state", "") or "").strip()
        != str(current.get("state", "") or "").strip()
    )
    if (
        not split_blocking_state
        and not uncovered_ids
        and str(coverage.get("requested_row_coverage_state", "") or "") == "accepted"
    ):
        return current, False

    provider_request = _provider_field_lane_request_for_support(
        operator_root,
        support={**current, "requested_rows": requested_rows},
    )
    rejected_rows = [
        dict(row)
        for row in list(coverage.get("rejected_requested_rows", []) or [])
        if isinstance(row, Mapping)
    ]
    for requested_id in forced_uncovered_ids:
        if not requested_id:
            continue
        if any(str(row.get("requested_row_id", "") or "") == requested_id for row in rejected_rows):
            continue
        rejected_rows.append(
            {
                "requested_row_id": requested_id,
                "row_id": "",
                "rejected_reasons": ["current_operator_feedback_marks_row_uncovered"],
            }
        )

    now = _utc_now()
    updated = dict(current)
    updated["support_state"] = "commercial_source_acquisition_required"
    updated["state"] = "commercial_source_acquisition_required"
    updated["candidate_ingestion_state"] = "commercial_source_acquisition_required"
    updated["operator_review_required"] = True
    updated["commercial_source_acquisition_required"] = True
    updated["source_backed_rows_required"] = True
    updated["support_recovery_state"] = "commercial_source_acquisition_required"
    updated["next_support_recovery_action"] = "run_provider_field_lane_source_acquisition"
    updated["support_provider_quality_blocker"] = "source_backed_rows_required"
    updated["support_blocker_reason"] = "support_request_missing_requested_rows"
    updated["requested_rows"] = requested_rows
    updated["requested_row_count"] = len(requested_rows)
    updated["accepted_requested_row_ids"] = accepted_ids
    updated["uncovered_requested_row_ids"] = uncovered_ids
    updated["rejected_requested_rows"] = rejected_rows
    updated["requested_row_coverage_state"] = "incomplete"
    updated["provider_field_lane_request"] = provider_request
    updated["provider_field_lane_request_id"] = str(
        provider_request.get("provider_field_lane_request_id", "") or ""
    )
    updated["current_provider_support_request_id"] = support_request_id
    updated["provider_latest_freshness_state"] = "current_support_request"
    updated["provider_latest_repair_reason"] = "stale_satisfied_bom_rows_missing_current_requested_fields"
    updated["support_materialization_state"] = "waiting_for_source_backed_rows"
    updated["post_materialization_support_adequacy_state"] = "insufficient_requested_row_coverage"
    updated["post_materialization_uncovered_fields"] = uncovered_ids
    updated["consumable_support_row_count"] = 0
    updated["build_depth_consumable_support_row_count"] = 0
    updated["updated_at"] = now
    _write_json(_support_request_path(operator_root, support_request_id), updated)
    _persist_current_provider_acquisition_latest(
        operator_root,
        support=updated,
        provider_request=provider_request,
        reason="stale_satisfied_bom_rows_missing_current_requested_fields",
    )
    _append_ledger(
        operator_root,
        "support_request_events",
        {
            "event": "stale_satisfied_commercial_bom_support_rebuilt",
            "generated_at": now,
            "support_request_id": support_request_id,
            "directive_id": str(updated.get("directive_id", "") or ""),
            "target_artifact": "bill_of_materials.json",
            "accepted_requested_row_ids": accepted_ids,
            "uncovered_requested_row_ids": uncovered_ids,
            "grants_execution_authority": False,
        },
    )
    return updated, True


def _support_requested_rows_are_accepted(support: Mapping[str, Any]) -> bool:
    requested_ids = [
        str(row.get("requested_row_id", "") or "").strip()
        for row in list(support.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
    ]
    accepted_ids = {
        str(item or "").strip()
        for item in list(
            support.get("accepted_requested_row_ids", [])
            or support.get("accepted_fmea_requested_row_ids", [])
            or support.get("accepted_validation_fixture_requested_row_ids", [])
            or []
        )
        if str(item or "").strip()
    }
    uncovered_ids = [
        str(item or "").strip()
        for item in list(
            support.get("uncovered_requested_row_ids", [])
            or support.get("uncovered_fmea_requested_row_ids", [])
            or support.get("uncovered_validation_fixture_requested_row_ids", [])
            or []
        )
        if str(item or "").strip()
    ]
    if uncovered_ids:
        return False
    return bool(_support_request_state_value(support) == "satisfied" and (not requested_ids or set(requested_ids).issubset(accepted_ids)))


def _linked_artifact_support_handoff_candidate(
    operator_root: str | Path,
    *,
    directive: Mapping[str, Any],
    current_support: Mapping[str, Any],
) -> dict[str, Any]:
    metadata = dict(directive.get("metadata", {}) or {})
    directive_id = str(directive.get("directive_id", "") or current_support.get("directive_id", "") or "").strip()
    current_target = str(current_support.get("target_artifact", "") or "").strip()
    if not directive_id:
        return {}
    metadata_commercial_bom_blocker = bool(
        (
            metadata.get("commercial_source_acquisition_required", False)
            or metadata.get("source_backed_rows_required", False)
            or str(metadata.get("provider_field_lane_request_id", "") or "").startswith("provider-field-lane")
        )
        and (
            list(metadata.get("uncovered_requested_row_ids", []) or [])
            or str(metadata.get("support_blocker_target_artifact", "") or "") == "bill_of_materials.json"
        )
    )
    if current_target != "bill_of_materials.json" and not metadata_commercial_bom_blocker:
        for linked_id, linked_target, linked_role in (
            (
                str(
                    metadata.get("current_validation_fixture_support_request_id", "")
                    or metadata.get("current_linked_artifact_support_request_id", "")
                    or ""
                ).strip(),
                "validation_fixtures.json",
                "validation_fixture_support",
            ),
            (
                str(metadata.get("current_risk_control_support_request_id", "") or "").strip(),
                "risk_controls.json",
                "risk_control_support",
            ),
        ):
            linked_support = _read_json(_support_request_path(operator_root, linked_id)) if linked_id else {}
            current_risk_id = str(metadata.get("current_risk_control_support_request_id", "") or "").strip()
            current_risk = _read_json(_support_request_path(operator_root, current_risk_id)) if current_risk_id else {}
            if linked_target == "validation_fixtures.json" and not (
                _support_request_is_current_pointer_candidate(
                    current_risk,
                    directive_id=directive_id,
                    target_artifact="risk_controls.json",
                )
                and _support_requested_rows_are_accepted(current_risk)
            ):
                continue
            if _support_request_is_current_pointer_candidate(
                linked_support,
                directive_id=directive_id,
                target_artifact=linked_target,
            ) and _support_requested_rows_are_accepted(linked_support):
                return {
                    "support_request": dict(linked_support),
                    "support_request_id": linked_id,
                    "target_artifact": linked_target,
                    "support_pointer_role": linked_role,
                    "current_risk_control_support_request_id": str(
                        metadata.get("current_risk_control_support_request_id", "") or ""
                    ),
                    "source_bom_support_request_id": "",
                }
    bom_support: dict[str, Any] = {}
    if current_target == "bill_of_materials.json" and _support_request_state_value(current_support) == "satisfied":
        bom_support = dict(current_support)
    else:
        bom_candidates = [
            dict(row)
            for row in _load_items(_support_requests_root(operator_root))
            if _support_request_is_current_pointer_candidate(
                row,
                directive_id=directive_id,
                target_artifact="bill_of_materials.json",
            )
            and _support_request_state_value(row) == "satisfied"
            and _support_requested_rows_are_accepted(row)
        ]
        if bom_candidates:
            bom_support = sorted(
                bom_candidates,
                key=lambda item: str(item.get("updated_at", "") or item.get("created_at", "") or ""),
            )[-1]
    if not bom_support or not _support_requested_rows_are_accepted(bom_support):
        return {}
    risk_support_id = str(
        bom_support.get("risk_control_support_request_id", "")
        or bom_support.get("current_risk_control_support_request_id", "")
        or metadata.get("current_risk_control_support_request_id", "")
        or ""
    ).strip()
    risk_support = _read_json(_support_request_path(operator_root, risk_support_id)) if risk_support_id else {}
    if not _support_request_is_current_pointer_candidate(
        risk_support,
        directive_id=directive_id,
        target_artifact="risk_controls.json",
    ):
        return {}
    selected = dict(risk_support)
    selected_role = "risk_control_support"
    next_target = "risk_controls.json"
    if _support_requested_rows_are_accepted(risk_support):
        fixture_support_id = str(
            risk_support.get("validation_fixture_support_request_id", "")
            or risk_support.get("current_validation_fixture_support_request_id", "")
            or metadata.get("current_validation_fixture_support_request_id", "")
            or ""
        ).strip()
        fixture_support = _read_json(_support_request_path(operator_root, fixture_support_id)) if fixture_support_id else {}
        if _support_request_is_current_pointer_candidate(
            fixture_support,
            directive_id=directive_id,
            target_artifact="validation_fixtures.json",
        ):
            selected = dict(fixture_support)
            selected_role = "validation_fixture_support"
            next_target = "validation_fixtures.json"
    return {
        "support_request": selected,
        "support_request_id": str(selected.get("support_request_id", "") or ""),
        "target_artifact": next_target,
        "support_pointer_role": selected_role,
        "current_risk_control_support_request_id": risk_support_id,
        "source_bom_support_request_id": str(bom_support.get("support_request_id", "") or ""),
    }


def repair_directive_support_request_freshness(
    operator_root: str | Path,
    *,
    directive_id: str | None = None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    repaired_count = 0
    created_count = 0
    technical_documentation_depth_support_repaired_count = 0
    inspected_count = 0
    records: list[dict[str, Any]] = []
    directives = _load_items(_directives_root(operator_root))
    if directive_id:
        directives = [
            row
            for row in directives
            if str(row.get("directive_id", "") or "") == str(directive_id)
        ]
    support_rows_cache: list[dict[str, Any]] | None = None

    def support_rows() -> list[dict[str, Any]]:
        nonlocal support_rows_cache
        if support_rows_cache is None:
            support_rows_cache = _load_items(_support_requests_root(operator_root))
        return support_rows_cache

    for directive in directives:
        state = str(directive.get("state", "") or "")
        if state not in {"requeued", "running", "blocked_for_support", "support_synthesis_in_progress"}:
            continue
        inspected_count += 1
        current_directive_id = str(directive.get("directive_id", "") or "")
        metadata = dict(directive.get("metadata", {}) or {})
        current_support_id = str(metadata.get("support_request_id", "") or "")
        current_support = _read_json(_support_request_path(operator_root, current_support_id)) if current_support_id else {}
        current_support_bom_uncovered = bool(
            str(current_support.get("target_artifact", "") or "") == "bill_of_materials.json"
            and list(current_support.get("uncovered_requested_row_ids", []) or [])
        )
        hard_commercial_bom_blocker = bool(
            (
                metadata.get("commercial_source_acquisition_required", False)
                or metadata.get("source_backed_rows_required", False)
                or current_support_bom_uncovered
            )
            and (
                list(metadata.get("uncovered_requested_row_ids", []) or [])
                or current_support_bom_uncovered
            )
            and (
                str(metadata.get("continuous_campaign_latest_target_artifact", "") or "") == "bill_of_materials.json"
                or str(metadata.get("support_blocker_target_artifact", "") or "") == "bill_of_materials.json"
                or str(metadata.get("provider_field_lane_request_id", "") or "").startswith("provider-field-lane")
                or current_support_bom_uncovered
            )
        )
        technical_documentation_depth_blocker = bool(
            metadata.get("technical_documentation_depth_plateau_finalized", False)
            or str(directive.get("blocked_reason", "") or "").strip()
            == "technical_documentation_depth_support_required"
            or str(metadata.get("support_blocker_reason", "") or "").strip()
            == "technical_documentation_depth_support_required"
            or str(metadata.get("support_admission_state", "") or "").strip()
            == "technical_documentation_depth_support_required"
        )
        target_override = (
            "bill_of_materials.json"
            if hard_commercial_bom_blocker
            else ("technical_documentation.md" if technical_documentation_depth_blocker else "")
        )
        retarget_candidate = str(
            target_override
            or metadata.get("initial_work_order_target_artifact", "")
            or metadata.get("continuous_campaign_latest_target_artifact", "")
            or current_support.get("target_artifact", "")
            or ""
        ).strip()
        if retarget_candidate == "interface_specifications.json":
            retargeted_directive, retargeted_target, retarget_closure = _retarget_initial_work_order_after_partial_closure(
                operator_root,
                directive=directive,
                target_artifact=retarget_candidate,
            )
            if retarget_closure and retargeted_target and retargeted_target != retarget_candidate:
                directive = retargeted_directive
                metadata = dict(directive.get("metadata", {}) or {})
                current_support_id = str(metadata.get("support_request_id", "") or "")
                current_support = (
                    _read_json(_support_request_path(operator_root, current_support_id))
                    if current_support_id
                    else {}
                )
        if hard_commercial_bom_blocker:
            bom_candidates = [
                dict(row)
                for row in support_rows()
                if _support_request_is_current_pointer_candidate(
                    row,
                    directive_id=current_directive_id,
                    target_artifact="bill_of_materials.json",
                )
            ]
            if bom_candidates:
                def bom_candidate_key(item: Mapping[str, Any]) -> tuple[int, str]:
                    state_text = str(item.get("support_state", "") or item.get("state", "") or "")
                    requested_count = len(
                        [
                            row
                            for row in list(item.get("requested_rows", []) or [])
                            if isinstance(row, Mapping)
                            and str(row.get("requested_row_id", "") or "").strip()
                        ]
                    )
                    role_count = len(list(item.get("support_role_lane_required_roles", []) or []))
                    if str(item.get("support_request_id", "") or "") == current_support_id:
                        priority = 6
                    elif state_text == "commercial_source_acquisition_required":
                        priority = 5
                    elif requested_count and role_count:
                        priority = 4
                    elif requested_count:
                        priority = 3
                    elif state_text == "satisfied":
                        priority = 2
                    else:
                        priority = 1
                    return (
                        priority,
                        str(item.get("updated_at", "") or item.get("created_at", "") or ""),
                    )

                bom_support = sorted(bom_candidates, key=bom_candidate_key)[-1]
                repaired_bom_support, rebuilt_bom_support = _repair_stale_satisfied_commercial_bom_support(
                    operator_root,
                    support=bom_support,
                    metadata_uncovered_requested_ids=metadata.get("uncovered_requested_row_ids", []),
                )
                best_id = str(repaired_bom_support.get("support_request_id", "") or "")
                if best_id and (
                    rebuilt_bom_support
                    or best_id != current_support_id
                    or str(metadata.get("support_blocker_target_artifact", "") or "") != "bill_of_materials.json"
                    or list(repaired_bom_support.get("uncovered_requested_row_ids", []) or [])
                    or str(repaired_bom_support.get("support_state", "") or "")
                    == "commercial_source_acquisition_required"
                ):
                    now = _utc_now()
                    updated = dict(directive)
                    updated_metadata = dict(metadata)
                    uncovered_ids = [
                        str(item or "").strip()
                        for item in list(
                            repaired_bom_support.get("uncovered_requested_row_ids", [])
                            or metadata.get("uncovered_requested_row_ids", [])
                            or []
                        )
                        if str(item or "").strip()
                    ]
                    updated_metadata.update(
                        {
                            "support_request_id": best_id,
                            "support_blocker_target_artifact": "bill_of_materials.json",
                            "initial_work_order_target_artifact": "bill_of_materials.json",
                            "continuous_campaign_latest_target_artifact": "bill_of_materials.json",
                            "next_unresolved_artifact": "bill_of_materials.json",
                            "support_blocker_reason": "source_backed_rows_required",
                            "support_recovery_state": "commercial_source_acquisition_required",
                            "commercial_source_acquisition_required": True,
                            "source_backed_rows_required": True,
                            "uncovered_requested_row_ids": uncovered_ids,
                            "provider_field_lane_request_id": str(
                                repaired_bom_support.get("provider_field_lane_request_id", "")
                                or updated_metadata.get("provider_field_lane_request_id", "")
                                or ""
                            ),
                            "support_pointer_repaired": True,
                            "support_pointer_repair_reason": (
                                "rebuilt_stale_satisfied_bom_support_for_current_enriched_contract"
                                if rebuilt_bom_support
                                else "promoted_current_bom_source_acquisition_support"
                            ),
                            "support_pointer_previous_request_id": current_support_id,
                            "support_pointer_repaired_at": now,
                        }
                    )
                    updated["state"] = "blocked_for_support"
                    updated["metadata"] = updated_metadata
                    updated["updated_at"] = now
                    _write_json(_directive_path(operator_root, current_directive_id), updated)
                    repaired_count += 1
                    records.append(
                        {
                            "directive_id": current_directive_id,
                            "previous_support_request_id": current_support_id,
                            "support_request_id": best_id,
                            "target_artifact": "bill_of_materials.json",
                            "support_pointer_repair_reason": updated_metadata["support_pointer_repair_reason"],
                            "uncovered_requested_row_ids": uncovered_ids,
                            "grants_execution_authority": False,
                        }
                    )
                    continue
        linked_handoff = _linked_artifact_support_handoff_candidate(
            operator_root,
            directive=directive,
            current_support=current_support,
        )
        if linked_handoff:
            best = dict(linked_handoff.get("support_request", {}) or {})
            best_id = str(linked_handoff.get("support_request_id", "") or "")
            best_target = str(linked_handoff.get("target_artifact", "") or best.get("target_artifact", "") or "")
            if best_id and best_target and best_id != current_support_id:
                now = _utc_now()
                updated = dict(directive)
                updated_metadata = dict(metadata)
                updated_metadata.update(
                    {
                        "support_request_id": best_id,
                        "current_linked_artifact_support_request_id": best_id,
                        "support_pointer_role": str(linked_handoff.get("support_pointer_role", "") or ""),
                        "artifact_handoff_parity_state": "linked_artifact_support_pointer_repaired",
                        "support_blocker_target_artifact": best_target,
                        "initial_work_order_target_artifact": best_target,
                        "continuous_campaign_latest_target_artifact": best_target,
                        "next_unresolved_artifact": best_target,
                        "support_pointer_repaired": True,
                        "support_pointer_repair_reason": "linked_artifact_handoff_after_bom_closure",
                        "support_pointer_previous_request_id": current_support_id,
                        "support_pointer_repaired_at": now,
                        "current_support_request_repaired": True,
                        "support_retargeted_from_artifact": str(current_support.get("target_artifact", "") or ""),
                        "support_retargeted_to_artifact": best_target,
                        "support_retarget_reason": "bom_field_lane_closure_handoff",
                    }
                )
                risk_id = str(linked_handoff.get("current_risk_control_support_request_id", "") or "")
                if risk_id:
                    updated_metadata["current_risk_control_support_request_id"] = risk_id
                if best_target == "validation_fixtures.json":
                    updated_metadata["current_validation_fixture_support_request_id"] = best_id
                    updated_metadata["uncovered_fmea_requested_row_ids"] = []
                    updated_metadata["missing_fmea_row_refs"] = []
                    if _support_requested_rows_are_accepted(best):
                        updated_metadata["uncovered_validation_fixture_requested_row_ids"] = []
                elif best_target == "risk_controls.json":
                    updated_metadata["current_risk_control_support_request_id"] = best_id
                    if _support_requested_rows_are_accepted(best):
                        updated_metadata["uncovered_fmea_requested_row_ids"] = []
                if str(best.get("support_blocker_reason", "") or ""):
                    updated_metadata["support_blocker_reason"] = str(best.get("support_blocker_reason", "") or "")
                elif _support_requested_rows_are_accepted(best):
                    updated_metadata["support_blocker_reason"] = ""
                if _support_requested_rows_are_accepted(best) and state == "blocked_for_support":
                    updated["state"] = "requeued"
                updated["metadata"] = updated_metadata
                updated["updated_at"] = now
                _write_json(_directive_path(operator_root, current_directive_id), updated)
                repaired_count += 1
                records.append(
                    {
                        "directive_id": current_directive_id,
                        "previous_support_request_id": current_support_id,
                        "support_request_id": best_id,
                        "target_artifact": best_target,
                        "support_pointer_repair_reason": "linked_artifact_handoff_after_bom_closure",
                        "artifact_handoff_parity_state": "linked_artifact_support_pointer_repaired",
                        "support_pointer_role": str(linked_handoff.get("support_pointer_role", "") or ""),
                        "grants_execution_authority": False,
                    }
                )
                continue
        target_artifact = str(
            target_override
            or metadata.get("support_blocker_target_artifact", "")
            or metadata.get("initial_work_order_target_artifact", "")
            or metadata.get("continuous_campaign_latest_target_artifact", "")
            or current_support.get("target_artifact", "")
            or ""
        )
        if (
            hard_commercial_bom_blocker
            and current_support_bom_uncovered
            and _support_request_is_current_pointer_candidate(
                current_support,
                directive_id=current_directive_id,
                target_artifact="bill_of_materials.json",
            )
        ):
            now = _utc_now()
            updated = dict(directive)
            updated_metadata = dict(metadata)
            updated_metadata["support_request_id"] = current_support_id
            updated_metadata["support_blocker_target_artifact"] = "bill_of_materials.json"
            updated_metadata["initial_work_order_target_artifact"] = "bill_of_materials.json"
            updated_metadata["continuous_campaign_latest_target_artifact"] = "bill_of_materials.json"
            updated_metadata["next_unresolved_artifact"] = "bill_of_materials.json"
            updated_metadata["support_blocker_reason"] = "source_backed_rows_required"
            updated_metadata["support_recovery_state"] = "commercial_source_acquisition_required"
            updated_metadata["commercial_source_acquisition_required"] = True
            updated_metadata["source_backed_rows_required"] = True
            updated_metadata["uncovered_requested_row_ids"] = [
                str(item).strip()
                for item in list(current_support.get("uncovered_requested_row_ids", []) or [])
                if str(item).strip()
            ]
            updated_metadata["support_pointer_repaired"] = True
            updated_metadata["support_pointer_repair_reason"] = "preserved_current_bom_requested_row_blocker"
            updated_metadata["support_pointer_repaired_at"] = now
            updated["state"] = "blocked_for_support"
            updated["metadata"] = updated_metadata
            updated["updated_at"] = now
            _write_json(_directive_path(operator_root, current_directive_id), updated)
            repaired_count += 1
            records.append(
                {
                    "directive_id": current_directive_id,
                    "support_request_id": current_support_id,
                    "target_artifact": "bill_of_materials.json",
                    "support_pointer_repair_reason": "preserved_current_bom_requested_row_blocker",
                    "uncovered_requested_row_ids": updated_metadata["uncovered_requested_row_ids"],
                    "grants_execution_authority": False,
                }
            )
            continue
        candidates = [
            dict(row)
            for row in support_rows()
            if _support_request_is_current_pointer_candidate(
                row,
                directive_id=current_directive_id,
                target_artifact=target_artifact,
            )
        ]
        if not candidates:
            if target_artifact == "technical_documentation.md":
                technical_doc_repair = _ensure_current_technical_documentation_depth_support_request(
                    operator_root,
                    directive=directive,
                    stale_support=current_support,
                )
                if bool(technical_doc_repair.get("ok", False)):
                    repaired = dict(technical_doc_repair.get("support_request", {}) or {})
                    repaired_id = str(repaired.get("support_request_id", "") or "")
                    repaired_count += 1
                    created_count += 1
                    technical_documentation_depth_support_repaired_count += 1
                    support_rows().append(repaired)
                    records.append(
                        {
                            "directive_id": current_directive_id,
                            "previous_support_request_id": current_support_id,
                            "support_request_id": repaired_id,
                            "target_artifact": "technical_documentation.md",
                            "support_pointer_repair_reason": "technical_documentation_depth_support_request_repaired",
                            "uncovered_requested_row_ids": list(
                                repaired.get("uncovered_requested_row_ids", []) or []
                            ),
                            "grants_execution_authority": False,
                        }
                    )
                    continue
            can_create_from_metadata = bool(
                target_artifact
                and (
                    current_support_id
                    or state == "blocked_for_support"
                    or str(metadata.get("support_blocker_reason", "") or "")
                )
            )
            if not can_create_from_metadata:
                continue
            capability = str(
                metadata.get("initial_work_order_capability", "")
                or current_support.get("capability", "")
                or "directive_build_grade_synthesis_pack"
            )
            support_id = _record_id(
                "support",
                current_directive_id,
                target_artifact,
                capability,
                "metadata-support-blocker",
            )
            existing_support = _read_json(_support_request_path(operator_root, support_id))
            now = _utc_now()
            if existing_support:
                best = dict(existing_support)
            else:
                directive_text = str(
                    directive.get("directive_text", "")
                    or directive.get("text", "")
                    or directive.get("title", "")
                    or directive.get("operator_feedback", "")
                    or ""
                )
                required_fields = _support_contract_required_fields(
                    _directive_family_from_text(directive_text or str(metadata.get("initial_work_order_context", "") or "")),
                    target_artifact,
                )
                best = {
                    "schema_name": "ConveyorSupportRequest",
                    "schema_version": SUPPORT_REQUEST_SCHEMA_VERSION,
                    "support_request_id": support_id,
                    "support_state": "pending_operator_review",
                    "operator_review_required": True,
                    "directive_id": current_directive_id,
                    "return_packet_id": str(
                        metadata.get("initial_work_order_source_return_packet_id", "")
                        or current_support.get("return_packet_id", "")
                        or f"directive-metadata-{current_directive_id}"
                    ),
                    "capability": capability,
                    "requested_pack_family": _support_pack_family(current_directive_id, capability),
                    "requested_tags": _support_request_tags(capability),
                    "target_artifact": target_artifact,
                    "missing_field_coverage": required_fields,
                    "missing_fields": required_fields,
                    "reason": str(
                        metadata.get("support_blocker_reason", "")
                        or "Current directive is support-blocked without a nonterminal support request."
                    ),
                    "candidate_ingestion_state": "pending_support",
                    "support_materialization_state": "waiting_for_consumable_support",
                    "created_at": now,
                    "updated_at": now,
                    "grants_execution_authority": False,
                }
                _write_json(_support_request_path(operator_root, support_id), best)
                support_rows().append(best)
                created_count += 1
            best_id = str(best.get("support_request_id", "") or support_id)
            repair_reason = "created_current_support_request_from_directive_metadata"
        else:
            repair_reason = "stale_support_request_pointer"

        def candidate_key(item: Mapping[str, Any]) -> tuple[int, str]:
            state_text = str(item.get("support_state", "") or "")
            row_count = int(item.get("consumable_support_row_count", 0) or 0)
            has_current_field_obligations = bool(_support_request_explicit_required_fields(item))
            technology_design_active = bool(item.get("technology_design_obligation_active", False))
            if state_text == "satisfied" and row_count > 0 and technology_design_active:
                priority = 5
            elif state_text == "satisfied" and row_count > 0 and has_current_field_obligations:
                priority = 4
            elif state_text == "pending_operator_review" and has_current_field_obligations:
                priority = 3
            elif state_text == "satisfied" and row_count > 0:
                priority = 2
            elif state_text == "pending_operator_review":
                priority = 1
            else:
                priority = 0
            return (
                priority,
                str(item.get("updated_at", "") or item.get("created_at", "") or ""),
            )

        if candidates:
            best = sorted(candidates, key=candidate_key)[-1]
            best_id = str(best.get("support_request_id", "") or "")
        current_ok = bool(current_support) and _support_request_is_current_pointer_candidate(
            current_support,
            directive_id=current_directive_id,
            target_artifact=target_artifact,
        )
        current_has_rows = int(current_support.get("consumable_support_row_count", 0) or 0) > 0
        best_has_rows = int(best.get("consumable_support_row_count", 0) or 0) > 0
        best_has_current_field_obligations = bool(_support_request_explicit_required_fields(best))
        if current_ok and current_has_rows:
            support_context = _support_request_directive_context(operator_root, current_support)
            required_role_lanes = _support_required_role_lanes_from_context(
                current_support,
                support_context,
            )
            role_lane_result = _support_role_lane_coverage_result(
                required_role_lanes,
                current_support.get("support_role_lane_covered_roles", []),
            )
            if (
                required_role_lanes
                and role_lane_result["support_role_lane_uncovered_roles"]
            ):
                capability = str(
                    current_support.get("capability", "")
                    or metadata.get("initial_work_order_capability", "")
                    or "directive_build_grade_synthesis_pack"
                )
                replacement_id = _record_id(
                    "support",
                    current_directive_id,
                    target_artifact,
                    capability,
                    "role-lane-support",
                    ",".join(required_role_lanes),
                )
                replacement = _read_json(_support_request_path(operator_root, replacement_id))
                now = _utc_now()
                required_fields = (
                    _support_request_explicit_required_fields(current_support)
                    or _support_contract_required_fields(
                        _directive_family_from_text(
                            str(directive.get("directive_text", "") or directive.get("operator_feedback", "") or "")
                        ),
                        target_artifact,
                    )
                )
                if not replacement:
                    replacement = {
                        "schema_name": "ConveyorSupportRequest",
                        "schema_version": SUPPORT_REQUEST_SCHEMA_VERSION,
                        "support_request_id": replacement_id,
                        "support_state": "pending_operator_review",
                        "operator_review_required": True,
                        "directive_id": current_directive_id,
                        "return_packet_id": str(
                            current_support.get("return_packet_id", "")
                            or f"directive-role-lane-{current_directive_id}"
                        ),
                        "capability": capability,
                        "requested_pack_family": _support_pack_family(current_directive_id, capability),
                        "requested_tags": _support_request_tags(capability),
                        "target_artifact": target_artifact,
                        "missing_field_coverage": required_fields,
                        "missing_fields": required_fields,
                        "support_role_lane_required_roles": required_role_lanes,
                        "support_role_lane_uncovered_roles": list(
                            role_lane_result.get("support_role_lane_uncovered_roles", []) or []
                        ),
                        "source_support_request_id": current_support_id,
                        "reason": "Current satisfied support lacks required role-lane coverage.",
                        "candidate_ingestion_state": "pending_support",
                        "support_materialization_state": "waiting_for_role_lane_consumable_support",
                        "support_blocker_reason": "support_request_missing_required_role_lanes",
                        "created_at": now,
                        "updated_at": now,
                        "grants_execution_authority": False,
                    }
                    _write_json(_support_request_path(operator_root, replacement_id), replacement)
                    support_rows().append(replacement)
                    created_count += 1
                original = dict(current_support)
                original["support_replaced_by_support_request_id"] = replacement_id
                original["support_role_lane_coverage_state"] = role_lane_result[
                    "support_role_lane_coverage_state"
                ]
                original["support_role_lane_required_roles"] = required_role_lanes
                original["support_role_lane_uncovered_roles"] = list(
                    role_lane_result.get("support_role_lane_uncovered_roles", []) or []
                )
                original["support_blocker_reason"] = "support_request_missing_required_role_lanes"
                original["updated_at"] = now
                _write_json(_support_request_path(operator_root, current_support_id), original)
                updated = dict(directive)
                updated_metadata = dict(metadata)
                updated_metadata["support_request_id"] = replacement_id
                updated_metadata["support_blocker_target_artifact"] = target_artifact
                updated_metadata["support_pointer_repaired"] = True
                updated_metadata[
                    "support_pointer_repair_reason"
                ] = "created_role_lane_support_request_from_inadequate_satisfied_support"
                updated_metadata["support_pointer_previous_request_id"] = current_support_id
                updated_metadata["support_pointer_repaired_at"] = now
                updated_metadata["support_role_lane_required_roles"] = required_role_lanes
                updated["metadata"] = updated_metadata
                updated["updated_at"] = now
                _write_json(_directive_path(operator_root, current_directive_id), updated)
                repaired_count += 1
                records.append(
                    {
                        "directive_id": current_directive_id,
                        "previous_support_request_id": current_support_id,
                        "support_request_id": replacement_id,
                        "target_artifact": target_artifact,
                        "support_pointer_repair_reason": "created_role_lane_support_request_from_inadequate_satisfied_support",
                        "support_role_lane_required_roles": required_role_lanes,
                        "grants_execution_authority": False,
                    }
                )
                continue
        if current_ok and current_support_id == best_id:
            if current_has_rows and str(metadata.get("support_blocker_reason", "") or ""):
                updated = dict(directive)
                updated_metadata = dict(metadata)
                updated_metadata["support_blocker_reason"] = ""
                updated_metadata["support_pointer_repaired"] = True
                updated_metadata["support_pointer_repair_reason"] = "cleared_satisfied_support_blocker"
                updated_metadata["support_pointer_previous_request_id"] = current_support_id
                updated_metadata["support_pointer_repaired_at"] = _utc_now()
                if _support_requested_rows_are_accepted(current_support) and state == "blocked_for_support":
                    updated["state"] = "requeued"
                updated["metadata"] = updated_metadata
                updated["updated_at"] = updated_metadata["support_pointer_repaired_at"]
                _write_json(_directive_path(operator_root, current_directive_id), updated)
                repaired_count += 1
                records.append(
                    {
                        "directive_id": current_directive_id,
                        "previous_support_request_id": current_support_id,
                        "current_support_request_id": current_support_id,
                        "repair_reason": "cleared_satisfied_support_blocker",
                    }
                )
            continue
        if current_ok and current_has_rows and not best_has_rows and not best_has_current_field_obligations:
            continue
        updated = dict(directive)
        updated_metadata = dict(metadata)
        updated_metadata["support_request_id"] = best_id
        updated_metadata["support_blocker_target_artifact"] = str(best.get("target_artifact", "") or target_artifact)
        if hard_commercial_bom_blocker:
            updated_metadata["initial_work_order_target_artifact"] = "bill_of_materials.json"
            updated_metadata["continuous_campaign_latest_target_artifact"] = "bill_of_materials.json"
            updated_metadata["support_recovery_target_artifact"] = "bill_of_materials.json"
            updated_metadata["support_blocker_reason"] = "source_backed_rows_required"
            updated_metadata["support_recovery_state"] = "commercial_source_acquisition_required"
        updated_metadata["support_pointer_repaired"] = True
        updated_metadata["support_pointer_repair_reason"] = repair_reason
        updated_metadata["support_pointer_previous_request_id"] = current_support_id
        updated_metadata["support_pointer_repaired_at"] = _utc_now()
        if str(best.get("target_artifact", "") or target_artifact) != str(current_support.get("target_artifact", "") or ""):
            updated_metadata["current_support_request_repaired"] = True
            updated_metadata["support_retargeted_from_artifact"] = str(current_support.get("target_artifact", "") or "")
            updated_metadata["support_retargeted_to_artifact"] = str(best.get("target_artifact", "") or target_artifact)
            updated_metadata["support_retarget_reason"] = "partial_target_correct_closure"
        updated["metadata"] = updated_metadata
        updated["updated_at"] = updated_metadata["support_pointer_repaired_at"]
        _write_json(_directive_path(operator_root, current_directive_id), updated)
        repaired_count += 1
        records.append(
            {
                "directive_id": current_directive_id,
                "previous_support_request_id": current_support_id,
                "support_request_id": best_id,
                "target_artifact": str(best.get("target_artifact", "") or target_artifact),
                "support_pointer_repair_reason": repair_reason,
                "grants_execution_authority": False,
            }
        )
    if records:
        _append_ledger(
            operator_root,
            "support_request_events",
            {
                "event": "support_pointer_freshness_repaired",
                "generated_at": _utc_now(),
                "support_pointer_repaired_count": repaired_count,
                "support_request_created_count": created_count,
                "records": records,
                "grants_execution_authority": False,
            },
        )
    return {
        "ok": True,
        "schema_name": "ConveyorSupportRequestFreshnessRepair",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "inspected_directive_count": inspected_count,
        "support_pointer_repaired_count": repaired_count,
        "support_request_created_count": created_count,
        "technical_documentation_depth_support_repaired_count": technical_documentation_depth_support_repaired_count,
        "records": records,
        "grants_execution_authority": False,
    }


def approve_conveyor_support_request(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    support_request_id: str,
    trusted_source_digest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    support_request_id = str(support_request_id or "").strip()
    support = _read_json(_support_request_path(operator_root, support_request_id))
    if not support:
        return {"ok": False, "message": f"Support request not found: {support_request_id}"}
    if str(support.get("support_state", "") or "") == "rejected":
        return {"ok": False, "message": "Rejected support requests cannot be approved."}
    now = _utc_now()
    support["support_state"] = "approved"
    support["updated_at"] = now
    support["operator_review_required"] = False
    _write_json(_support_request_path(operator_root, support_request_id), support)
    support_context = _support_request_directive_context(operator_root, support)
    if trusted_source_digest is None:
        try:
            if _support_request_requires_build_grade_support(support):
                digest = _directive_build_grade_support_digest(
                    operator_root,
                    support_context,
                )
                digest_path = (
                    _support_artifacts_root(operator_root)
                    / f"{support_request_id}-directive-build-grade-support-digest.json"
                )
            else:
                from .autonomy import _trusted_source_literature_triage_digest, autonomy_root

                digest = _trusted_source_literature_triage_digest(
                    operator_root,
                    {
                        "operation_id": support_request_id,
                        "action": "trusted_source_literature_triage_digest",
                        "librarian_gap_request_id": support_request_id,
                        "librarian_gap_signature": support_request_id,
                        "requested_pack_family": str(support.get("requested_pack_family", "") or ""),
                        "requested_tags": list(support.get("requested_tags", []) or []),
                        "source_dossier_ref": str(support.get("return_packet_id", "") or ""),
                        "source_coverage_state": "conveyor_child_support_request",
                    },
                )
                digest_path = autonomy_root(operator_root) / "trusted_source_literature_triage_digest_latest.json"
        except Exception as exc:
            support["support_state"] = "pending_operator_review"
            support["operator_review_required"] = True
            support["trusted_source_blocker"] = type(exc).__name__
            support["updated_at"] = _utc_now()
            _write_json(_support_request_path(operator_root, support_request_id), support)
            return {"ok": False, "message": "Trusted-source request failed.", "details": [type(exc).__name__]}
    else:
        digest = _redact_trusted_source_digest(trusted_source_digest)
        digest.update(
            {
                "schema_name": str(digest.get("schema_name", "") or "TrustedSourceLiteratureTriageDigest"),
                "schema_version": str(digest.get("schema_version", "") or CONVEYOR_SCHEMA_VERSION),
                "status": str(digest.get("status", "") or "completed"),
                "requested_pack_family": str(support.get("requested_pack_family", "") or ""),
                "requested_tags": list(support.get("requested_tags", []) or []),
                "directive_id": str(support.get("directive_id", "") or ""),
                "librarian_gap_request_id": support_request_id,
            }
        )
        digest_path = _support_artifacts_root(operator_root) / f"{support_request_id}-trusted-source-digest.json"
    requires_build_grade = _support_request_requires_build_grade_support(support)
    if requires_build_grade and str(digest.get("schema_name", "") or "") != "DirectiveBuildGradeSupportDigest":
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["satisfied_pack_ref"] = ""
        support["satisfied_pack"] = {}
        support["consumable_support_row_count"] = 0
        support["build_depth_consumable_support_row_count"] = 0
        support["support_pack_consumability_state"] = "non_consumable"
        support["non_consumable_support_reasons"] = [
            "build_grade_digest_required",
            "zero_consumable_support_rows",
        ]
        support["support_blocker_reason"] = "build_grade_digest_required"
        support["trusted_source_rejection_reason"] = "build_grade_digest_required"
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        return {
            "ok": False,
            "message": "Build-depth support requires a DirectiveBuildGradeSupportDigest with child_support_rows.",
            "support_request": support,
            "trusted_source_digest": _redact_trusted_source_digest(digest),
        }
    if not requires_build_grade:
        digest = _trusted_source_digest_with_child_support_rows(digest, support)
    digest["requested_pack_family"] = str(support.get("requested_pack_family", "") or digest.get("requested_pack_family", "") or "")
    digest["requested_tags"] = list(support.get("requested_tags", []) or digest.get("requested_tags", []) or [])[:16]
    digest["target_artifact"] = str(support.get("target_artifact", "") or digest.get("target_artifact", "") or "")
    digest["directive_id"] = str(support.get("directive_id", "") or digest.get("directive_id", "") or "")
    accepted_engineering_rows: list[dict[str, Any]] = []
    accepted_engineering_row_ids: list[str] = []
    if requires_build_grade and list(digest.get("child_support_rows", []) or []):
        accepted_engineering_rows, accepted_engineering_row_ids = _record_engineering_evidence_rows(
            operator_root,
            support=support,
            context=support_context,
            digest=digest,
        )
        if accepted_engineering_rows:
            digest["child_support_rows"] = accepted_engineering_rows
            digest["accepted_engineering_evidence_row_count"] = len(accepted_engineering_rows)
            digest["engineering_evidence_row_ids"] = accepted_engineering_row_ids
            if not str(digest.get("provider_output_quality_state", "") or ""):
                digest["provider_output_quality_state"] = "accepted"
            if not int(digest.get("accepted_child_support_row_count", 0) or 0):
                digest["accepted_child_support_row_count"] = len(accepted_engineering_rows)
    _write_json(digest_path, digest)
    try:
        from .librarian import stage_librarian_pack

        staged = stage_librarian_pack(
            state_root=state_root,
            source_path=digest_path,
            workspace_root=None,
            source_kind="conveyor_support_request",
        )
    except Exception as exc:
        return {"ok": False, "message": "Librarian staging failed.", "details": [type(exc).__name__]}
    if str(staged.get("stage_result", "") or "") not in {"staged", "duplicate_existing_version"}:
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["librarian_stage"] = staged
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        return {
            "ok": False,
            "message": "Trusted-source digest was not staged as a reusable pack.",
            "librarian_stage": staged,
        }
    pack_ref = _pack_ref_from_librarian_reuse(
        {
            "pack_id": staged.get("pack_id", ""),
            "pack_kind": staged.get("pack_kind", ""),
            "pack_family": staged.get("pack_family", ""),
            "pack_path": staged.get("pack_path", ""),
            "version_ref": staged.get("version_ref", ""),
            "source_kind": staged.get("source_kind", ""),
            "quality_state": staged.get("quality_state", ""),
            "reuse_state": staged.get("reuse_state", ""),
        }
    )
    digest_rows = list(digest.get("child_support_rows", []) or [])
    try:
        _source_path, _payload, evidence = _support_pack_evidence_for_ref(
            state_root,
            pack_ref,
            target_artifact=str(support.get("target_artifact", "") or ""),
        )
    except Exception:
        _source_path = Path()
        _payload = {}
        evidence = _support_pack_missing_evidence()
    if (
        int(evidence.get("consumable_support_row_count", 0) or 0) <= 0
        and digest_rows
    ):
        _payload = {
            "schema_name": "DirectiveBuildGradeSupportPack",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "support_request_id": support_request_id,
            "directive_id": str(support.get("directive_id", "") or ""),
            "target_artifact": str(support.get("target_artifact", "") or ""),
            "capability": str(support.get("capability", "") or ""),
            "pack_kind": "directive_build_grade_synthesis_pack",
            "child_support_rows": digest_rows,
            "payload_summary": {"child_support_rows": digest_rows},
            "grants_execution_authority": False,
        }
        evidence = extract_consumable_support_evidence(
            _payload,
            target_artifact=str(support.get("target_artifact", "") or ""),
        )
    pack_ref = _enrich_support_pack_ref_with_evidence(pack_ref, evidence)
    if int(evidence.get("consumable_support_row_count", 0) or 0) <= 0:
        support = _copy_provider_quality_fields_to_support(
            support,
            digest,
            failed=True,
            operator_root=operator_root,
            context=support_context,
        )
        if not str(support.get("research_problem_frame_id", "") or ""):
            assessment = _record_support_research_quality_assessment(
                operator_root,
                support=support,
                context=support_context,
                digest=digest,
            )
            support["support_research_quality_assessment_id"] = str(
                assessment.get("support_research_quality_assessment_id", "") or ""
            )
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["satisfied_pack_ref"] = ""
        support["satisfied_pack"] = {}
        support["librarian_stage"] = {
            "stage_result": str(staged.get("stage_result", "") or ""),
            "pack_kind": str(staged.get("pack_kind", "") or ""),
            "pack_id": str(staged.get("pack_id", "") or ""),
            "version_ref": str(staged.get("version_ref", "") or ""),
            "quality_state": str(staged.get("quality_state", "") or ""),
            "reuse_state": str(staged.get("reuse_state", "") or ""),
        }
        support["consumable_support_row_count"] = 0
        support["support_pack_consumability_state"] = str(
            evidence.get("support_pack_consumability_state", "") or "metadata_only"
        )
        support["non_consumable_support_reasons"] = list(
            evidence.get("non_consumable_support_reasons", []) or ["zero_consumable_support_rows"]
        )
        support["support_pack_source_missing"] = bool(evidence.get("support_pack_source_missing", False))
        failure_class = str(digest.get("trusted_source_failure_class", "") or "")
        rejection_reason = str(
            digest.get("trusted_source_rejection_reason", "")
            or digest.get("provider_blocker", "")
            or ""
        )
        if failure_class:
            support["trusted_source_failure_class"] = failure_class
        if rejection_reason:
            support["trusted_source_rejection_reason"] = rejection_reason
            support["support_blocker_reason"] = rejection_reason
        support = _apply_risk_control_support_acquisition_fields(
            support,
            state="incomplete",
        )
        support = _apply_validation_fixture_support_acquisition_fields(
            support,
            state="incomplete",
        )
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        _append_ledger(operator_root, "support_request_events", {"event": "approved_pack_non_consumable", **support})
        return {
            "ok": False,
            "message": "Trusted-source digest did not contain consumable support rows.",
            "support_request": support,
            "librarian_stage": support["librarian_stage"],
            "trusted_source_digest": _redact_trusted_source_digest(digest),
        }
    requested_row_coverage = assess_requested_row_coverage(
        list(evidence.get("rows", []) or []) or digest_rows,
        requested_rows=list(support.get("requested_rows", []) or []),
        target_artifact=str(support.get("target_artifact", "") or ""),
    )
    if (
        str(requested_row_coverage.get("requested_row_coverage_state", "") or "")
        == "incomplete"
    ):
        support = _copy_provider_quality_fields_to_support(
            support,
            digest,
            failed=True,
            operator_root=operator_root,
            context=support_context,
        )
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["satisfied_pack_ref"] = ""
        support["satisfied_pack"] = {}
        support["requested_row_coverage_state"] = "incomplete"
        support["accepted_requested_row_ids"] = list(
            requested_row_coverage.get("accepted_requested_row_ids", []) or []
        )
        support["uncovered_requested_row_ids"] = list(
            requested_row_coverage.get("uncovered_requested_row_ids", []) or []
        )
        support["rejected_requested_rows"] = list(
            requested_row_coverage.get("rejected_requested_rows", []) or []
        )
        support["support_blocker_reason"] = "support_request_missing_requested_rows"
        support["support_pack_consumability_state"] = "diagnostic_requested_row_incomplete"
        support["non_consumable_support_reasons"] = list(
            dict.fromkeys(
                list(evidence.get("non_consumable_support_reasons", []) or [])
                + ["support_request_missing_requested_rows"]
            )
        )
        support = _apply_risk_control_support_acquisition_fields(
            support,
            state="incomplete",
        )
        support = _apply_validation_fixture_support_acquisition_fields(
            support,
            state="incomplete",
        )
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        _append_ledger(
            operator_root,
            "support_request_events",
            {"event": "approved_pack_missing_requested_rows", **support},
        )
        return {
            "ok": False,
            "message": "Build-depth support is missing requested-row bindings.",
            "support_request": support,
            "librarian_stage": {
                "stage_result": str(staged.get("stage_result", "") or ""),
                "pack_kind": str(staged.get("pack_kind", "") or ""),
                "pack_id": str(staged.get("pack_id", "") or ""),
                "version_ref": str(staged.get("version_ref", "") or ""),
            },
            "trusted_source_digest": _redact_trusted_source_digest(digest),
        }
    role_lane_result = _support_role_lane_coverage_result(
        _support_required_role_lanes_from_context(support, support_context),
        evidence.get("support_role_lane_covered_roles", []),
    )
    component_selection = _component_selection_result_for_evidence(
        support,
        support_context,
        evidence,
    )
    if (
        _support_request_requires_build_grade_support(support)
        and role_lane_result["support_role_lane_required_roles"]
        and not role_lane_result["support_role_lane_uncovered_roles"]
        and str(component_selection.get("component_selection_workbench_state", "") or "") == "rejected"
    ):
        support = _copy_provider_quality_fields_to_support(
            support,
            digest,
            failed=True,
            operator_root=operator_root,
            context=support_context,
        )
        support = _copy_component_selection_result_to_support(
            support,
            component_selection,
            blocker_reason="support_request_component_selection_incomplete",
        )
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["satisfied_pack_ref"] = ""
        support["satisfied_pack"] = {}
        support["support_pack_consumability_state"] = "diagnostic_component_selection_incomplete"
        support["support_role_lane_coverage_state"] = role_lane_result["support_role_lane_coverage_state"]
        support["support_role_lane_covered_roles"] = role_lane_result["support_role_lane_covered_roles"]
        support["non_consumable_support_reasons"] = list(
            dict.fromkeys(
                list(evidence.get("non_consumable_support_reasons", []) or [])
                + ["support_request_component_selection_incomplete"]
            )
        )
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        _append_ledger(
            operator_root,
            "component_selection_assessments",
            {"event": "approved_pack_component_selection_incomplete", **component_selection, **support},
        )
        return {
            "ok": False,
            "message": "Build-depth support is missing role-lane component selection fields.",
            "support_request": support,
            "librarian_stage": {
                "stage_result": str(staged.get("stage_result", "") or ""),
                "pack_kind": str(staged.get("pack_kind", "") or ""),
                "pack_id": str(staged.get("pack_id", "") or ""),
                "version_ref": str(staged.get("version_ref", "") or ""),
            },
            "trusted_source_digest": _redact_trusted_source_digest(digest),
        }
    if (
        _support_request_requires_build_grade_support(support)
        and role_lane_result["support_role_lane_required_roles"]
        and role_lane_result["support_role_lane_uncovered_roles"]
    ):
        support = _copy_provider_quality_fields_to_support(
            support,
            digest,
            failed=True,
            operator_root=operator_root,
            context=support_context,
        )
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["satisfied_pack_ref"] = ""
        support["satisfied_pack"] = {}
        support["support_pack_consumability_state"] = "diagnostic_role_lane_incomplete"
        support["support_role_lane_coverage_state"] = role_lane_result["support_role_lane_coverage_state"]
        support["support_role_lane_required_roles"] = role_lane_result["support_role_lane_required_roles"]
        support["support_role_lane_covered_roles"] = role_lane_result["support_role_lane_covered_roles"]
        support["support_role_lane_uncovered_roles"] = role_lane_result["support_role_lane_uncovered_roles"]
        support["support_role_lane_accepted_rows"] = role_lane_result["support_role_lane_accepted_rows"]
        support["support_blocker_reason"] = "support_request_missing_required_role_lanes"
        support["non_consumable_support_reasons"] = list(
            dict.fromkeys(
                list(evidence.get("non_consumable_support_reasons", []) or [])
                + ["support_request_missing_required_role_lanes"]
            )
        )
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        _append_ledger(
            operator_root,
            "support_request_events",
            {"event": "approved_pack_missing_required_role_lanes", **support},
        )
        return {
            "ok": False,
            "message": "Build-depth support is missing required role-lane rows.",
            "support_request": support,
            "librarian_stage": {
                "stage_result": str(staged.get("stage_result", "") or ""),
                "pack_kind": str(staged.get("pack_kind", "") or ""),
                "pack_id": str(staged.get("pack_id", "") or ""),
                "version_ref": str(staged.get("version_ref", "") or ""),
            },
            "trusted_source_digest": _redact_trusted_source_digest(digest),
        }
    pack_ref = _archive_satisfied_support_pack(
        operator_root,
        state_root=state_root,
        support_request_id=support_request_id,
        pack_ref=pack_ref,
        payload=_payload,
        source_path=_source_path,
    )
    support = _copy_provider_quality_fields_to_support(support, digest, failed=False)
    if accepted_engineering_rows:
        support["accepted_engineering_evidence_row_count"] = len(accepted_engineering_rows)
        support["engineering_evidence_row_ids"] = accepted_engineering_row_ids
    assessment = _record_support_research_quality_assessment(
        operator_root,
        support=support,
        context=support_context,
        digest=digest,
        accepted_rows=accepted_engineering_rows,
    )
    support["support_research_quality_assessment_id"] = str(
        assessment.get("support_research_quality_assessment_id", "") or ""
    )
    support["support_state"] = "satisfied"
    support["operator_review_required"] = False
    support["satisfied_pack_ref"] = str(staged.get("pack_id", "") or "")
    support["satisfied_pack"] = pack_ref
    consumable_count = int(evidence.get("consumable_support_row_count", 0) or 0)
    build_depth_count = int(evidence.get("build_depth_consumable_support_row_count", 0) or 0)
    if (
        build_depth_count <= 0
        and consumable_count > 0
        and requires_build_grade
        and bool(evidence.get("support_evidence_contract_passed", False))
    ):
        build_depth_count = consumable_count
    support["consumable_support_row_count"] = consumable_count
    support["build_depth_consumable_support_row_count"] = build_depth_count
    support["support_pack_consumability_state"] = str(evidence.get("support_pack_consumability_state", "") or "")
    support["non_consumable_support_reasons"] = list(evidence.get("non_consumable_support_reasons", []) or [])
    support["support_pack_source_missing"] = bool(evidence.get("support_pack_source_missing", False))
    support["support_evidence_contract_passed"] = bool(
        evidence.get("support_evidence_contract_passed", False)
    )
    support["support_evidence_field_coverage"] = list(
        evidence.get("support_evidence_field_coverage", []) or []
    )
    support["support_evidence_source_quality"] = str(
        evidence.get("support_evidence_source_quality", "") or ""
    )
    support["support_evidence_domain_match"] = bool(
        evidence.get("support_evidence_domain_match", False)
    )
    support["support_evidence_rejected_reasons"] = list(
        evidence.get("support_evidence_rejected_reasons", []) or []
    )
    support["requested_row_coverage_state"] = str(
        requested_row_coverage.get("requested_row_coverage_state", "") or "not_required"
    )
    support["accepted_requested_row_ids"] = list(
        requested_row_coverage.get("accepted_requested_row_ids", []) or []
    )
    support["uncovered_requested_row_ids"] = list(
        requested_row_coverage.get("uncovered_requested_row_ids", []) or []
    )
    support["rejected_requested_rows"] = list(
        requested_row_coverage.get("rejected_requested_rows", []) or []
    )
    if (
        str(support.get("requested_row_coverage_state", "") or "") == "accepted"
        and not support["uncovered_requested_row_ids"]
    ):
        support["post_materialization_support_adequacy_state"] = "adequate"
        support["post_materialization_uncovered_fields"] = []
        support["support_wake_suppressed_reason"] = ""
        support["commercial_source_acquisition_required"] = False
        support["source_backed_rows_required"] = False
        support["support_provider_quality_blocker"] = ""
        support["provider_output_quality_state"] = "accepted"
        support["next_support_recovery_action"] = "materialize_consumable_support_rows"
        if str(support.get("r_and_d_design_brief_id", "") or "").strip():
            support["design_brief_diagnostic_only"] = True
        support["technology_design_obligation_active"] = False
        support["r_and_d_design_brief_ready"] = False
        support["hardware_build_ready_blocked_by_design_obligation"] = False
        support["child_work_mode"] = ""
        if str(support.get("support_satisfaction_mode", "") or "") == "technology_design_obligation":
            support["support_satisfaction_mode"] = "source_backed_field_lane_acquisition"
    support["support_role_lane_coverage_state"] = role_lane_result["support_role_lane_coverage_state"]
    support["support_role_lane_required_roles"] = role_lane_result["support_role_lane_required_roles"]
    support["support_role_lane_covered_roles"] = role_lane_result["support_role_lane_covered_roles"]
    support["support_role_lane_uncovered_roles"] = role_lane_result["support_role_lane_uncovered_roles"]
    support["support_role_lane_accepted_rows"] = list(
        component_selection.get("support_role_lane_accepted_rows", [])
        or role_lane_result["support_role_lane_accepted_rows"]
    )
    support["component_selection_workbench_state"] = str(
        component_selection.get("component_selection_workbench_state", "not_required") or "not_required"
    )
    support["component_selection_rejected_row_reasons"] = list(
        component_selection.get("component_selection_rejected_row_reasons", []) or []
    )
    support = _apply_risk_control_support_acquisition_fields(
        support,
        state="accepted"
        if (
            str(support.get("target_artifact", "") or "") == "risk_controls.json"
            and str(support.get("requested_row_coverage_state", "") or "") == "accepted"
            and not list(support.get("uncovered_requested_row_ids", []) or [])
        )
        else None,
    )
    support = _apply_validation_fixture_support_acquisition_fields(
        support,
        state="accepted"
        if (
            str(support.get("target_artifact", "") or "") == "validation_fixtures.json"
            and str(support.get("requested_row_coverage_state", "") or "") == "accepted"
            and not list(support.get("uncovered_requested_row_ids", []) or [])
        )
        else None,
    )
    support, risk_support = _prepare_risk_control_support_chain_from_bom_support(
        operator_root,
        support=support,
        support_rows=list(digest.get("child_support_rows", []) or []) + list(evidence.get("rows", []) or []),
    )
    evidence_coverage = _support_field_coverage_list(support.get("support_evidence_field_coverage"))
    stale_uncovered = _support_field_coverage_list(support.get("post_materialization_uncovered_fields"))
    if stale_uncovered and all(field in set(evidence_coverage) for field in stale_uncovered):
        support["post_materialization_support_adequacy_state"] = "adequate"
        support["post_materialization_uncovered_fields"] = []
        support["support_wake_suppressed_reason"] = ""
    for key in (
        "original_support_pack_path",
        "durable_support_pack_path",
        "support_pack_archive_path",
        "durable_support_pack_ref",
        "support_pack_archive_state",
        "support_pack_repair_state",
    ):
        if str(pack_ref.get(key, "") or ""):
            support[key] = str(pack_ref.get(key, "") or "")
    if str(support.get("candidate_idempotency_key", "") or ""):
        support["candidate_ingestion_state"] = "satisfied_from_consumable_pack"
    if str(support.get("support_materialization_state", "") or "") == "async_synthesis_failed":
        support["support_materialization_state"] = "waiting_for_materialization"
    support.pop("trusted_source_error_class", None)
    support["librarian_stage"] = {
        "stage_result": str(staged.get("stage_result", "") or ""),
        "pack_kind": str(staged.get("pack_kind", "") or ""),
        "pack_id": str(staged.get("pack_id", "") or ""),
        "version_ref": str(staged.get("version_ref", "") or ""),
        "quality_state": str(staged.get("quality_state", "") or ""),
        "reuse_state": str(staged.get("reuse_state", "") or ""),
    }
    support["updated_at"] = _utc_now()
    _write_json(_support_request_path(operator_root, support_request_id), support)
    _append_ledger(operator_root, "support_request_events", {"event": "approved_and_satisfied", **support})
    _record_support_field_lane_acquisition_evidence(
        operator_root,
        support=support,
        support_rows=list(digest.get("child_support_rows", []) or []) + list(evidence.get("rows", []) or []),
    )
    _record_risk_control_support_acquisition_evidence(
        operator_root,
        support=support,
        support_rows=list(digest.get("child_support_rows", []) or []) + list(evidence.get("rows", []) or []),
    )
    _record_validation_fixture_support_acquisition_evidence(
        operator_root,
        support=support,
        support_rows=list(digest.get("child_support_rows", []) or []) + list(evidence.get("rows", []) or []),
    )
    if risk_support:
        risk_chain_evidence = {
            "schema_name": "RiskControlChainClosureEvidence",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "generated_at": _utc_now(),
            "support_request_id": support_request_id,
            "risk_control_support_request_id": str(risk_support.get("support_request_id", "") or ""),
            "directive_id": str(support.get("directive_id", "") or ""),
            "target_artifact": "bill_of_materials.json",
            "closed_target_artifact": "bill_of_materials.json",
            "next_linked_artifact_target": "risk_controls.json",
            "missing_fmea_row_refs": list(support.get("missing_fmea_row_refs", []) or []),
            "partial_target_correct_closure": True,
            "grants_execution_authority": False,
        }
        _append_ledger(
            operator_root,
            "risk_control_chain_closure_evidence",
            risk_chain_evidence,
        )
        _write_json(_conveyor_root(operator_root) / "risk_control_chain_closure_evidence_latest.json", risk_chain_evidence)
    repair_directive_support_request_freshness(
        operator_root,
        directive_id=str(support.get("directive_id", "") or ""),
    )
    _reset_continuous_campaign_context(
        operator_root,
        str(support.get("directive_id", "") or ""),
        reason="support_approved_and_satisfied",
        action="support_request_approved",
        support_request_id=support_request_id,
        return_packet_id=str(support.get("return_packet_id", "") or ""),
        target_artifact=str(support.get("target_artifact", "") or ""),
    )
    return {
        "ok": True,
        "message": "Support request satisfied.",
        "support_request": support,
        "librarian_stage": support["librarian_stage"],
        "trusted_source_digest": _redact_trusted_source_digest(digest),
    }


def satisfy_conveyor_support_request(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    support_request_id: str,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    support_request_id = str(support_request_id or "").strip()
    support = _read_json(_support_request_path(operator_root, support_request_id))
    if not support:
        return {"ok": False, "message": f"Support request not found: {support_request_id}"}
    if str(support.get("support_state", "") or "") == "rejected":
        return {"ok": False, "message": "Rejected support requests cannot be marked satisfied."}
    pack_ref: dict[str, Any] = {}
    if list(support.get("requested_rows", []) or []):
        pack_ref = _operator_seed_pack_ref(
            operator_root,
            state_root=state_root,
            support=support,
            required_fields=_support_request_required_fields(support),
        )
    if not pack_ref:
        pack_ref = _existing_support_pack_ref(
            state_root=state_root,
            directive_id=str(support.get("directive_id", "") or ""),
            capability=str(support.get("capability", "") or ""),
            target_artifact=str(support.get("target_artifact", "") or ""),
        )
    if not pack_ref:
        pack_ref = _operator_seed_pack_ref(
            operator_root,
            state_root=state_root,
            support=support,
            required_fields=_support_request_required_fields(support),
        )
    if not pack_ref:
        evidence = _support_pack_rejection_diagnostics(
            state_root=state_root,
            directive_id=str(support.get("directive_id", "") or ""),
            capability=str(support.get("capability", "") or ""),
        )
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["consumable_support_row_count"] = 0
        support["support_pack_consumability_state"] = str(
            evidence.get("support_pack_consumability_state", "") or "metadata_only"
        )
        reasons = list(
            evidence.get("non_consumable_support_reasons", [])
            or support.get("non_consumable_support_reasons", [])
            or []
        )
        for reason in ("zero_consumable_support_rows",):
            if reason not in reasons:
                reasons.append(reason)
        support["non_consumable_support_reasons"] = reasons
        support["support_pack_source_missing"] = bool(
            evidence.get("support_pack_source_missing", support.get("support_pack_source_missing", False))
        )
        support["build_depth_consumable_support_row_count"] = int(
            evidence.get("build_depth_consumable_support_row_count", 0) or 0
        )
        support["support_evidence_contract_passed"] = bool(
            evidence.get("support_evidence_contract_passed", False)
        )
        support["support_evidence_field_coverage"] = list(
            evidence.get("support_evidence_field_coverage", []) or []
        )
        support["support_evidence_source_quality"] = str(
            evidence.get("support_evidence_source_quality", "") or ""
        )
        support["support_evidence_domain_match"] = bool(
            evidence.get("support_evidence_domain_match", False)
        )
        support["support_evidence_rejected_reasons"] = list(
            evidence.get("support_evidence_rejected_reasons", []) or reasons
        )
        support = _apply_risk_control_support_acquisition_fields(
            support,
            state="incomplete",
        )
        support = _apply_validation_fixture_support_acquisition_fields(
            support,
            state="incomplete",
        )
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        return {
            "ok": False,
            "message": "No reusable Librarian support pack is staged for this directive and capability.",
            "support_request": support,
        }
    try:
        _source_path, _payload, evidence = _support_pack_evidence_for_ref(
            state_root,
            pack_ref,
            target_artifact=str(support.get("target_artifact", "") or ""),
        )
    except Exception:
        _source_path = Path()
        _payload = {}
        evidence = _support_pack_missing_evidence()
    requested_row_coverage = assess_requested_row_coverage(
        evidence.get("rows", []),
        requested_rows=list(support.get("requested_rows", []) or []),
        target_artifact=str(support.get("target_artifact", "") or ""),
    )
    if (
        str(requested_row_coverage.get("requested_row_coverage_state", "") or "")
        == "incomplete"
    ):
        pack_ref = _enrich_support_pack_ref_with_evidence(pack_ref, evidence)
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["requested_row_coverage_state"] = "incomplete"
        support["accepted_requested_row_ids"] = list(
            requested_row_coverage.get("accepted_requested_row_ids", []) or []
        )
        support["uncovered_requested_row_ids"] = list(
            requested_row_coverage.get("uncovered_requested_row_ids", []) or []
        )
        support["rejected_requested_rows"] = list(
            requested_row_coverage.get("rejected_requested_rows", []) or []
        )
        support["support_blocker_reason"] = "support_request_missing_requested_rows"
        support["support_pack_consumability_state"] = "diagnostic_requested_row_incomplete"
        support["operator_seed_pack_used"] = bool(pack_ref.get("operator_seed_pack_used", False))
        if str(pack_ref.get("operator_seed_pack_id", "") or ""):
            support["operator_seed_pack_id"] = str(pack_ref.get("operator_seed_pack_id", "") or "")
        support["operator_seed_pack_template_bound"] = bool(
            pack_ref.get("operator_seed_pack_template_bound", False)
        )
        support["operator_seed_pack_template_bound_row_count"] = int(
            pack_ref.get("operator_seed_pack_template_bound_row_count", 0) or 0
        )
        support["operator_seed_pack_template_ids"] = list(
            pack_ref.get("operator_seed_pack_template_ids", []) or []
        )
        support["consumable_support_row_count"] = int(
            pack_ref.get("consumable_support_row_count", 0) or 0
        )
        support["build_depth_consumable_support_row_count"] = int(
            pack_ref.get("build_depth_consumable_support_row_count", 0) or 0
        )
        support["support_evidence_field_coverage"] = list(
            pack_ref.get("support_evidence_field_coverage", []) or []
        )
        support["support_evidence_source_quality"] = str(
            pack_ref.get("support_evidence_source_quality", "") or ""
        )
        support["support_provider_quality_blocker"] = "source_backed_rows_required"
        support["next_support_recovery_action"] = "narrow_research_source_lanes"
        support["commercial_source_acquisition_required"] = bool(
            _support_request_requires_commercial_source_rows(
                support,
                _support_request_directive_context(operator_root, support),
            )
        )
        support["source_backed_rows_required"] = bool(
            support["commercial_source_acquisition_required"]
        )
        support = _apply_risk_control_support_acquisition_fields(
            support,
            state="incomplete",
        )
        support = _apply_validation_fixture_support_acquisition_fields(
            support,
            state="incomplete",
        )
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        _append_ledger(
            operator_root,
            "support_request_events",
            {"event": "marked_satisfied_pack_missing_requested_rows", **support},
        )
        _record_support_field_lane_acquisition_evidence(
            operator_root,
            support=support,
            support_rows=list(evidence.get("rows", []) or []),
        )
        return {
            "ok": False,
            "message": "Reusable support pack is missing requested-row bindings.",
            "support_request": support,
        }
    pack_ref = _archive_satisfied_support_pack(
        operator_root,
        state_root=state_root,
        support_request_id=support_request_id,
        pack_ref=pack_ref,
        payload=_payload,
        source_path=_source_path,
    )
    pack_ref = _enrich_support_pack_ref_with_evidence(pack_ref, evidence)
    role_lane_result = _support_role_lane_coverage_result(
        _support_required_role_lanes_from_context(
            support,
            _support_request_directive_context(operator_root, support),
        ),
        pack_ref.get("support_role_lane_covered_roles", []),
    )
    support_context = _support_request_directive_context(operator_root, support)
    component_selection = _component_selection_result_for_evidence(
        support,
        support_context,
        evidence,
    )
    if (
        _support_request_requires_build_grade_support(support)
        and role_lane_result["support_role_lane_required_roles"]
        and not role_lane_result["support_role_lane_uncovered_roles"]
        and str(component_selection.get("component_selection_workbench_state", "") or "") == "rejected"
    ):
        support = _copy_component_selection_result_to_support(
            support,
            component_selection,
            blocker_reason="support_request_component_selection_incomplete",
        )
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["support_pack_consumability_state"] = "diagnostic_component_selection_incomplete"
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        _append_ledger(
            operator_root,
            "component_selection_assessments",
            {"event": "marked_satisfied_component_selection_incomplete", **component_selection, **support},
        )
        return {
            "ok": False,
            "message": "Reusable support pack is missing role-lane component selection fields.",
            "support_request": support,
        }
    if str(component_selection.get("component_selection_workbench_state", "") or "") in {"accepted", "not_required"}:
        pack_ref["component_selection_workbench_state"] = str(
            component_selection.get("component_selection_workbench_state", "") or "not_required"
        )
        pack_ref["component_selection_rejected_row_reasons"] = list(
            component_selection.get("component_selection_rejected_row_reasons", []) or []
        )
        if component_selection.get("support_role_lane_accepted_rows"):
            pack_ref["support_role_lane_accepted_rows"] = list(
                component_selection.get("support_role_lane_accepted_rows", []) or []
            )
    if (
        _support_request_requires_build_grade_support(support)
        and role_lane_result["support_role_lane_required_roles"]
        and role_lane_result["support_role_lane_uncovered_roles"]
    ):
        support["support_state"] = "pending_operator_review"
        support["operator_review_required"] = True
        support["support_role_lane_coverage_state"] = role_lane_result["support_role_lane_coverage_state"]
        support["support_role_lane_required_roles"] = role_lane_result["support_role_lane_required_roles"]
        support["support_role_lane_covered_roles"] = role_lane_result["support_role_lane_covered_roles"]
        support["support_role_lane_uncovered_roles"] = role_lane_result["support_role_lane_uncovered_roles"]
        support["support_role_lane_accepted_rows"] = role_lane_result["support_role_lane_accepted_rows"]
        support["support_blocker_reason"] = "support_request_missing_required_role_lanes"
        support["support_pack_consumability_state"] = "diagnostic_role_lane_incomplete"
        support["updated_at"] = _utc_now()
        _write_json(_support_request_path(operator_root, support_request_id), support)
        _append_ledger(
            operator_root,
            "support_request_events",
            {"event": "marked_satisfied_pack_missing_required_role_lanes", **support},
        )
        return {
            "ok": False,
            "message": "Reusable support pack is missing required role-lane rows.",
            "support_request": support,
        }
    support = _apply_satisfied_support_pack(support, pack_ref)
    support["requested_row_coverage_state"] = str(
        requested_row_coverage.get("requested_row_coverage_state", "") or "not_required"
    )
    support["accepted_requested_row_ids"] = list(
        requested_row_coverage.get("accepted_requested_row_ids", []) or []
    )
    support["uncovered_requested_row_ids"] = list(
        requested_row_coverage.get("uncovered_requested_row_ids", []) or []
    )
    support["rejected_requested_rows"] = list(
        requested_row_coverage.get("rejected_requested_rows", []) or []
    )
    if (
        str(support.get("requested_row_coverage_state", "") or "") == "accepted"
        and not support["uncovered_requested_row_ids"]
    ):
        support["post_materialization_support_adequacy_state"] = "adequate"
        support["post_materialization_uncovered_fields"] = []
        support["support_wake_suppressed_reason"] = ""
        support["commercial_source_acquisition_required"] = False
        support["source_backed_rows_required"] = False
        support["support_provider_quality_blocker"] = ""
        support["provider_output_quality_state"] = "accepted"
        support["next_support_recovery_action"] = "materialize_consumable_support_rows"
        if str(support.get("r_and_d_design_brief_id", "") or "").strip():
            support["design_brief_diagnostic_only"] = True
        support["technology_design_obligation_active"] = False
        support["r_and_d_design_brief_ready"] = False
        support["hardware_build_ready_blocked_by_design_obligation"] = False
        support["child_work_mode"] = ""
        if str(support.get("support_satisfaction_mode", "") or "") == "technology_design_obligation":
            support["support_satisfaction_mode"] = "source_backed_field_lane_acquisition"
    support["support_role_lane_coverage_state"] = role_lane_result["support_role_lane_coverage_state"]
    support["support_role_lane_required_roles"] = role_lane_result["support_role_lane_required_roles"]
    support["support_role_lane_covered_roles"] = role_lane_result["support_role_lane_covered_roles"]
    support["support_role_lane_uncovered_roles"] = role_lane_result["support_role_lane_uncovered_roles"]
    support["support_role_lane_accepted_rows"] = list(
        pack_ref.get("support_role_lane_accepted_rows", [])
        or role_lane_result["support_role_lane_accepted_rows"]
    )
    support["component_selection_workbench_state"] = str(
        pack_ref.get("component_selection_workbench_state", "") or ""
    )
    support["component_selection_rejected_row_reasons"] = list(
        pack_ref.get("component_selection_rejected_row_reasons", []) or []
    )
    support["operator_seed_pack_used"] = bool(pack_ref.get("operator_seed_pack_used", False))
    if str(pack_ref.get("operator_seed_pack_id", "") or ""):
        support["operator_seed_pack_id"] = str(pack_ref.get("operator_seed_pack_id", "") or "")
    support["operator_seed_pack_template_bound"] = bool(
        pack_ref.get("operator_seed_pack_template_bound", False)
    )
    support["operator_seed_pack_template_bound_row_count"] = int(
        pack_ref.get("operator_seed_pack_template_bound_row_count", 0) or 0
    )
    support["operator_seed_pack_template_ids"] = list(
        pack_ref.get("operator_seed_pack_template_ids", []) or []
    )
    support = _apply_risk_control_support_acquisition_fields(
        support,
        state="accepted"
        if (
            str(support.get("target_artifact", "") or "") == "risk_controls.json"
            and str(support.get("requested_row_coverage_state", "") or "") == "accepted"
            and not list(support.get("uncovered_requested_row_ids", []) or [])
        )
        else None,
    )
    support = _apply_validation_fixture_support_acquisition_fields(
        support,
        state="accepted"
        if (
            str(support.get("target_artifact", "") or "") == "validation_fixtures.json"
            and str(support.get("requested_row_coverage_state", "") or "") == "accepted"
            and not list(support.get("uncovered_requested_row_ids", []) or [])
        )
        else None,
    )
    support, risk_support = _prepare_risk_control_support_chain_from_bom_support(
        operator_root,
        support=support,
        support_rows=list(evidence.get("rows", []) or []),
    )
    support["updated_at"] = _utc_now()
    _write_json(_support_request_path(operator_root, support_request_id), support)
    if (
        str(support.get("requested_row_coverage_state", "") or "") == "accepted"
        and not list(support.get("uncovered_requested_row_ids", []) or [])
    ):
        _clear_directive_design_only_support_metadata(operator_root, support=support)
    _append_ledger(operator_root, "support_request_events", {"event": "marked_satisfied", **support})
    _record_support_field_lane_acquisition_evidence(
        operator_root,
        support=support,
        support_rows=list(evidence.get("rows", []) or []),
    )
    _record_risk_control_support_acquisition_evidence(
        operator_root,
        support=support,
        support_rows=list(evidence.get("rows", []) or []),
    )
    _record_validation_fixture_support_acquisition_evidence(
        operator_root,
        support=support,
        support_rows=list(evidence.get("rows", []) or []),
    )
    if risk_support:
        risk_chain_evidence = {
            "schema_name": "RiskControlChainClosureEvidence",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "generated_at": _utc_now(),
            "support_request_id": support_request_id,
            "risk_control_support_request_id": str(risk_support.get("support_request_id", "") or ""),
            "directive_id": str(support.get("directive_id", "") or ""),
            "target_artifact": "bill_of_materials.json",
            "closed_target_artifact": "bill_of_materials.json",
            "next_linked_artifact_target": "risk_controls.json",
            "missing_fmea_row_refs": list(support.get("missing_fmea_row_refs", []) or []),
            "partial_target_correct_closure": True,
            "grants_execution_authority": False,
        }
        _append_ledger(
            operator_root,
            "risk_control_chain_closure_evidence",
            risk_chain_evidence,
        )
        _write_json(_conveyor_root(operator_root) / "risk_control_chain_closure_evidence_latest.json", risk_chain_evidence)
    _reset_continuous_campaign_context(
        operator_root,
        str(support.get("directive_id", "") or ""),
        reason="support_request_satisfied",
        action="support_request_satisfied",
        support_request_id=support_request_id,
        return_packet_id=str(support.get("return_packet_id", "") or ""),
        target_artifact=str(support.get("target_artifact", "") or ""),
    )
    return {"ok": True, "message": "Support request marked satisfied.", "support_request": support}


def reject_conveyor_support_request(
    operator_root: str | Path,
    *,
    support_request_id: str,
    operator_note: str = "",
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    support_request_id = str(support_request_id or "").strip()
    support = _read_json(_support_request_path(operator_root, support_request_id))
    if not support:
        return {"ok": False, "message": f"Support request not found: {support_request_id}"}
    support["support_state"] = "rejected"
    support["operator_note"] = str(operator_note or "")
    support["operator_review_required"] = False
    support["updated_at"] = _utc_now()
    _write_json(_support_request_path(operator_root, support_request_id), support)
    _append_ledger(operator_root, "support_request_events", {"event": "rejected", **support})
    return {"ok": True, "message": "Support request rejected.", "support_request": support}


def configure_conveyor_scheduler(
    operator_root: str | Path,
    *,
    updates: Mapping[str, Any],
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    scheduler = _load_scheduler(operator_root)
    payload = dict(scheduler)
    allowed_runner_modes = {"simulated", "docker", "auto"}
    if "runner_mode" in updates:
        runner_mode = str(updates.get("runner_mode", "") or "").strip().lower()
        if runner_mode not in allowed_runner_modes:
            raise ConveyorValidationError("runner_mode must be simulated, docker, or auto")
        payload["runner_mode"] = runner_mode
    if "child_execution_mode" in updates:
        child_execution_mode = str(updates.get("child_execution_mode", "") or "").strip().lower()
        if child_execution_mode not in {"oneshot_return", "resident_campaign"}:
            raise ConveyorValidationError("child_execution_mode must be oneshot_return or resident_campaign")
        payload["child_execution_mode"] = child_execution_mode
    if "continuous_campaign_mode" in updates:
        payload["continuous_campaign_mode"] = bool(updates.get("continuous_campaign_mode", False))
    if "task_manager_mode" in updates:
        mode = str(updates.get("task_manager_mode", "") or "").strip().lower()
        if mode not in {"shadow", "cutover"}:
            raise ConveyorValidationError("task_manager_mode must be shadow or cutover")
        payload["task_manager_mode"] = mode
    if "task_manager_cutover_enabled" in updates:
        payload["task_manager_cutover_enabled"] = bool(updates.get("task_manager_cutover_enabled", False))
    if "task_manager_max_active_children" in updates:
        try:
            payload["task_manager_max_active_children"] = max(
                1,
                int(updates.get("task_manager_max_active_children", 1) or 1),
            )
        except (TypeError, ValueError) as exc:
            raise ConveyorValidationError("task_manager_max_active_children must be a positive integer") from exc
    if "continuous_campaign_policy" in updates:
        policy_updates = dict(updates.get("continuous_campaign_policy", {}) or {})
        policy = {**DEFAULT_CONTINUOUS_CAMPAIGN_POLICY, **dict(payload.get("continuous_campaign_policy", {}) or {})}
        if "scope" in policy_updates:
            scope = str(policy_updates.get("scope", "") or "").strip()
            if scope not in {"build_grade_directives"}:
                raise ConveyorValidationError("continuous campaign policy scope must be build_grade_directives")
            policy["scope"] = scope
        if "trusted_source_mode" in policy_updates:
            mode = str(policy_updates.get("trusted_source_mode", "") or "").strip()
            if mode not in {"reuse_existing_only", "reuse_existing_then_capped_auto_approve"}:
                raise ConveyorValidationError(
                    "continuous campaign trusted_source_mode must be reuse_existing_only or reuse_existing_then_capped_auto_approve"
                )
            policy["trusted_source_mode"] = mode
        for key in (
            "auto_continue_depth_pass_cap",
            "auto_support_approval_cap",
            "no_progress_escalation_attempts",
            "resident_cycle_sleep_seconds",
        ):
            if key in policy_updates:
                try:
                    policy[key] = max(0, int(policy_updates.get(key, 0) or 0))
                except (TypeError, ValueError) as exc:
                    raise ConveyorValidationError(f"continuous campaign policy {key} must be a non-negative integer") from exc
        payload["continuous_campaign_policy"] = policy
    for key in (
        "docker_image",
        "docker_cli",
        "child_memory_limit",
        "child_cpu_limit",
        "host_bind_root",
        "container_bind_root",
    ):
        if key in updates:
            value = str(updates.get(key, "") or "").strip()
            payload[key] = value
    for key in ("min_concurrency", "max_concurrency", "target_concurrency"):
        if key in updates:
            try:
                payload[key] = max(1, int(updates.get(key, 1) or 1))
            except (TypeError, ValueError) as exc:
                raise ConveyorValidationError(f"{key} must be a positive integer") from exc
    min_concurrency = max(1, int(payload.get("min_concurrency", 1) or 1))
    max_concurrency = max(min_concurrency, int(payload.get("max_concurrency", min_concurrency) or min_concurrency))
    target_concurrency = min(
        max(int(payload.get("target_concurrency", min_concurrency) or min_concurrency), min_concurrency),
        max_concurrency,
    )
    payload["min_concurrency"] = min_concurrency
    payload["max_concurrency"] = max_concurrency
    payload["target_concurrency"] = target_concurrency
    payload["spawn_mode"] = "conveyor_child_runner"
    payload["last_adjustment_reason"] = "operator_configured_scheduler"
    saved = _save_scheduler(operator_root, payload)
    _append_ledger(
        operator_root,
        "scheduler_events",
        {
            "event": "configured",
            "generated_at": saved["generated_at"],
            "runner_mode": saved.get("runner_mode", ""),
            "child_execution_mode": saved.get("child_execution_mode", ""),
            "continuous_campaign_mode": bool(saved.get("continuous_campaign_mode", False)),
            "continuous_campaign_policy": dict(saved.get("continuous_campaign_policy", {}) or {}),
            "target_concurrency": saved.get("target_concurrency", 0),
            "max_concurrency": saved.get("max_concurrency", 0),
        },
    )
    return saved


def _active_children(operator_root: str | Path) -> list[dict[str, Any]]:
    children = _load_items(_children_root(operator_root))
    return [
        child
        for child in children
        if str(child.get("child_run_id", "") or "").strip()
        and not bool(child.get("spawn_suppressed", False))
        and str(child.get("state", "") or "") not in TERMINAL_CHILD_STATES
    ]


def _active_child_ids_by_directive(children: Iterable[Mapping[str, Any]]) -> dict[str, set[str]]:
    active: dict[str, set[str]] = {}
    for child in children:
        if bool(child.get("spawn_suppressed", False)):
            continue
        if str(child.get("state", "") or "") in TERMINAL_CHILD_STATES:
            continue
        directive_id = str(child.get("directive_id", "") or "")
        child_id = str(child.get("child_run_id", "") or "")
        if not directive_id or not child_id:
            continue
        active.setdefault(directive_id, set()).add(child_id)
    return active


def _active_children_for_directive(
    operator_root: str | Path,
    directive_id: str,
) -> list[dict[str, Any]]:
    directive_key = str(directive_id or "").strip()
    if not directive_key:
        return []
    return [
        dict(child)
        for child in _active_children(operator_root)
        if str(child.get("directive_id", "") or "").strip() == directive_key
    ]


def _cleanup_stale_spawn_reservations(
    operator_root: str | Path,
    *,
    runner: ConveyorChildRunner | None = None,
    scheduler: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    scheduler_payload = dict(scheduler or _load_scheduler(operator_root))
    effective_runner = runner or runner_from_scheduler(scheduler_payload)
    now = _utc_now()
    now_dt = datetime.now(timezone.utc)
    cleaned: list[dict[str, Any]] = []
    for child in _load_items(_children_root(operator_root)):
        if str(child.get("state", "") or "").strip() != "spawning":
            continue
        child_id = str(child.get("child_run_id", "") or "").strip()
        directive_id = str(child.get("directive_id", "") or "").strip()
        if not child_id or not directive_id:
            continue
        stamp = _parse_utc_time(
            str(
                child.get("spawn_reserved_at", "")
                or child.get("created_at", "")
                or child.get("updated_at", "")
                or ""
            )
        )
        if stamp is None:
            continue
        age_seconds = (now_dt - stamp).total_seconds()
        if age_seconds < SPAWN_RESERVATION_STALE_SECONDS:
            continue
        inspect_state: dict[str, Any] = {}
        has_container_ref = bool(str(child.get("container_id", "") or child.get("container_name", "")).strip())
        missing_live_container = not has_container_ref
        if has_container_ref:
            try:
                inspect_state = dict(effective_runner.inspect_child_container(child))
            except Exception as exc:  # pragma: no cover - defensive scheduler hygiene.
                inspect_state = {"ok": False, "state": "unknown", "error": str(exc)}
            state_name = str(inspect_state.get("state", "") or "").strip().lower()
            missing_live_container = (
                _child_inspect_indicates_missing_container(inspect_state)
                or state_name in {"unknown", "missing", "not_found", "not-found"}
            )
        if not missing_live_container:
            continue
        updated = dict(child)
        updated["state"] = "failed"
        updated["spawn_reservation_state"] = "stale"
        updated["spawn_failure_kind"] = "spawn_reservation_stale"
        updated["failed_reason"] = "spawn_reservation_stale"
        updated["spawn_reservation_stale_at"] = now
        updated["spawn_reservation_age_seconds"] = round(max(0.0, age_seconds), 3)
        if inspect_state:
            updated["last_inspect_result"] = inspect_state
        updated["updated_at"] = now
        _write_json(_child_path(operator_root, child_id), updated)

        directive = _read_json(_directive_path(operator_root, directive_id))
        if directive and str(directive.get("active_child_run_id", "") or "").strip() == child_id:
            directive_update = dict(directive)
            directive_update["state"] = "requeued"
            directive_update["active_child_run_id"] = ""
            directive_update["updated_at"] = now
            metadata = dict(directive_update.get("metadata", {}) or {})
            metadata["latest_spawn_reservation_stale_child_run_id"] = child_id
            metadata["latest_spawn_reservation_stale_at"] = now
            metadata["latest_spawn_reservation_recovery_action"] = "scheduler_tick"
            directive_update["metadata"] = metadata
            _write_json(_directive_path(operator_root, directive_id), directive_update)

        _append_ledger(
            operator_root,
            "child_events",
            {
                "event": "spawn_reservation_stale",
                "generated_at": now,
                **updated,
            },
        )
        cleaned.append(
            {
                "child_run_id": child_id,
                "directive_id": directive_id,
                "spawn_reservation_state": "stale",
                "spawn_failure_kind": "spawn_reservation_stale",
            }
        )
    return {
        "ok": True,
        "schema_name": "ConveyorSpawnReservationCleanup",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": now,
        "stale_spawn_reservation_count": len(cleaned),
        "records": cleaned,
    }


def _clear_stale_active_child_ids_for_inactive_directives(operator_root: str | Path) -> int:
    inactive_states = {"returned_for_review", "accepted", "requeued", "rejected", "split"}
    now = _utc_now()
    cleared = 0
    for directive in _load_items(_directives_root(operator_root)):
        directive_id = str(directive.get("directive_id", "") or "").strip()
        if not directive_id:
            continue
        if str(directive.get("state", "") or "") not in inactive_states:
            continue
        if not str(directive.get("active_child_run_id", "") or "").strip():
            continue
        updated = dict(directive)
        cleared_child_id = str(updated.get("active_child_run_id", "") or "")
        updated["active_child_run_id"] = ""
        updated["updated_at"] = now
        _write_json(_directive_path(operator_root, directive_id), updated)
        _append_ledger(
            operator_root,
            "directive_events",
            {
                "event": "stale_active_child_id_cleared",
                "directive_id": directive_id,
                "cleared_child_run_id": cleared_child_id,
                "state": str(updated.get("state", "") or ""),
                "generated_at": now,
            },
        )
        cleared += 1
    return cleared


def _repair_requeued_directives_with_active_children(operator_root: str | Path) -> int:
    active_children = _active_children(operator_root)
    if not active_children:
        return 0
    active_by_directive: dict[str, dict[str, Any]] = {}
    for child in active_children:
        directive_id = str(child.get("directive_id", "") or "").strip()
        child_id = str(child.get("child_run_id", "") or "").strip()
        if not directive_id or not child_id:
            continue
        existing = active_by_directive.get(directive_id)
        child_stamp = str(child.get("updated_at", "") or child.get("created_at", ""))
        existing_stamp = str((existing or {}).get("updated_at", "") or (existing or {}).get("created_at", ""))
        if existing is None or child_stamp >= existing_stamp:
            active_by_directive[directive_id] = dict(child)
    if not active_by_directive:
        return 0
    now = _utc_now()
    repaired = 0
    for directive in _load_items(_directives_root(operator_root)):
        directive_id = str(directive.get("directive_id", "") or "").strip()
        active_child = active_by_directive.get(directive_id)
        if not directive_id or not active_child:
            continue
        if str(directive.get("state", "") or "") not in {"queued", "requeued"}:
            continue
        child_id = str(active_child.get("child_run_id", "") or "").strip()
        if not child_id:
            continue
        updated = dict(directive)
        updated["state"] = "running"
        updated["active_child_run_id"] = child_id
        updated["updated_at"] = now
        metadata = dict(updated.get("metadata", {}) or {})
        metadata["active_child_repaired_from_live_child"] = child_id
        metadata["active_child_repair_reason"] = "queued_or_requeued_directive_had_active_child_record"
        metadata["active_child_repair_at"] = now
        updated["metadata"] = metadata
        _write_json(_directive_path(operator_root, directive_id), updated)
        _append_ledger(
            operator_root,
            "directive_events",
            {
                "event": "active_child_directive_link_repaired",
                "generated_at": now,
                "directive_id": directive_id,
                "active_child_run_id": child_id,
                "previous_state": str(directive.get("state", "") or ""),
            },
        )
        repaired += 1
    return repaired


def _reset_active_resident_quality_context(
    operator_root: str | Path,
    directive_id: str,
    *,
    reason: str,
    target_artifact: str = "",
) -> int:
    reset_count = 0
    for child in _load_items(_children_root(operator_root)):
        child_id = str(child.get("child_run_id", "") or "")
        if not child_id or str(child.get("directive_id", "") or "") != str(directive_id or ""):
            continue
        if str(child.get("state", "") or "") in TERMINAL_CHILD_STATES:
            continue
        updated = dict(child)
        updated["consecutive_no_delta_cycles"] = 0
        updated["quality_no_progress_count"] = 0
        updated["latest_quality_retarget_reason"] = str(reason or "context_reset")
        if target_artifact:
            updated["latest_quality_target"] = target_artifact
        updated["updated_at"] = _utc_now()
        _write_json(_child_path(operator_root, child_id), updated)
        _append_ledger(
            operator_root,
            "child_events",
            {
                "event": "resident_quality_context_reset",
                "generated_at": updated["updated_at"],
                "directive_id": str(directive_id or ""),
                "child_run_id": child_id,
                "reason": str(reason or ""),
                "target_artifact": str(target_artifact or ""),
            },
        )
        reset_count += 1
    return reset_count


def _queued_directives(operator_root: str | Path) -> list[dict[str, Any]]:
    active_by_directive = _active_child_ids_by_directive(_load_items(_children_root(operator_root)))
    pending_review_directives = {
        str(row.get("directive_id", "") or "")
        for row in _load_items(_returns_root(operator_root))
        if str(row.get("review_state", "") or "") == "pending_operator_review"
        and str(row.get("directive_id", "") or "")
    }
    directives = [
        row
        for row in _load_items(_directives_root(operator_root))
        if str(row.get("state", "") or "") in {"queued", "requeued"}
        and str(row.get("directive_id", "") or "") not in active_by_directive
        and not (
            str(row.get("state", "") or "") == "queued"
            and str(row.get("directive_id", "") or "") in pending_review_directives
        )
    ]
    directives.sort(key=lambda row: (-int(row.get("priority", 0) or 0), str(row.get("created_at", ""))))
    return directives


def _directive_display_title(directive: Mapping[str, Any]) -> str:
    for key in ("directive_title", "title", "name"):
        value = str(directive.get(key, "") or "").strip()
        if value:
            return value
    directive_text = str(directive.get("directive_text", "") or "")
    patterns = [
        r"\*\*\s*DIRECTIVE\s*:\s*([^*\n]+?)\s*\*\*",
        r"^\s*DIRECTIVE\s*:\s*([^\n]+)",
        r"\bDIRECTIVE\s*:\s*([^\n]+)",
    ]
    for pattern in patterns:
        match = re.search(pattern, directive_text, flags=re.IGNORECASE | re.MULTILINE)
        if match:
            return str(match.group(1) or "").strip().strip("*: ")
    first_line = next((line.strip() for line in directive_text.splitlines() if line.strip()), "")
    return first_line[:120]


def _directive_title_map(directives: Iterable[Mapping[str, Any]]) -> dict[str, str]:
    return {
        str(directive.get("directive_id", "") or ""): _directive_display_title(directive)
        for directive in directives
        if str(directive.get("directive_id", "") or "")
    }


def _supersede_stale_pending_blockers_for_active_directives(
    operator_root: str | Path,
    *,
    returns: list[dict[str, Any]],
    support_requests: list[dict[str, Any]],
    active_by_directive: Mapping[str, set[str]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    if not active_by_directive:
        return returns, support_requests
    now = _utc_now()
    active_choice = {
        directive_id: sorted(child_ids)[-1]
        for directive_id, child_ids in active_by_directive.items()
        if child_ids
    }
    updated_returns: list[dict[str, Any]] = []
    for packet in returns:
        row = dict(packet)
        directive_id = str(row.get("directive_id", "") or "")
        child_id = str(row.get("child_run_id", "") or "")
        active_child_ids = set(active_by_directive.get(directive_id, set()))
        review_state = str(row.get("review_state", "") or "")
        stalled_or_support_blocker = bool(row.get("support_required_before_continue", False)) or (
            "resident_worker_stalled" in {str(item) for item in list(row.get("risks", []) or [])}
        )
        unattributed_requeued_blocker = (
            review_state == "requeued"
            and stalled_or_support_blocker
            and not str(row.get("superseded_by_active_child_run_id", "") or "").strip()
            and not str(row.get("superseded_by_return_packet_id", "") or "").strip()
        )
        if (
            review_state in {"pending_operator_review", "requeued"}
            and active_child_ids
            and child_id not in active_child_ids
            and (review_state == "pending_operator_review" or unattributed_requeued_blocker)
        ):
            row["review_state"] = "requeued"
            row["superseded_by_active_child_run_id"] = active_choice.get(directive_id, "")
            row["superseded_reason"] = "active_resident_worker_continuation"
            row["reviewed_at"] = now
            row["updated_at"] = now
            _write_json(_return_path(operator_root, str(row.get("return_packet_id", "") or "")), row)
        updated_returns.append(row)
    updated_support: list[dict[str, Any]] = []
    for support in support_requests:
        row = dict(support)
        directive_id = str(row.get("directive_id", "") or "")
        child_id = str(row.get("child_run_id", "") or "")
        active_child_ids = set(active_by_directive.get(directive_id, set()))
        if (
            str(row.get("support_state", "") or "") == "pending_operator_review"
            and active_child_ids
            and child_id not in active_child_ids
        ):
            row["support_state"] = "superseded"
            row["operator_review_required"] = False
            row["superseded_by_active_child_run_id"] = active_choice.get(directive_id, "")
            row["superseded_reason"] = "active_resident_worker_continuation"
            row["updated_at"] = now
            _write_json(_support_request_path(operator_root, str(row.get("support_request_id", "") or "")), row)
            _append_ledger(operator_root, "support_request_events", {"event": "superseded", **row})
        updated_support.append(row)
    return updated_returns, updated_support


def _return_blocker_target(packet: Mapping[str, Any]) -> str:
    target = str(packet.get("target_artifact", "") or "").strip()
    if target:
        return target
    for clarification in list(packet.get("requested_operator_clarifications", []) or []):
        if not isinstance(clarification, Mapping):
            continue
        target = str(clarification.get("target_artifact", "") or "").strip()
        if target:
            return target
    return "general"


def _support_request_target(request: Mapping[str, Any]) -> str:
    target = str(request.get("target_artifact", "") or "").strip()
    if target:
        return target
    reason = str(request.get("reason", "") or request.get("request_reason", "") or "")
    match = re.search(r"targeting\s+([a-zA-Z0-9_.-]+\.json)", reason)
    if match:
        return str(match.group(1) or "").strip()
    return "general"


def _record_sort_time(row: Mapping[str, Any]) -> str:
    return str(
        row.get("generated_at", "")
        or row.get("updated_at", "")
        or row.get("reviewed_at", "")
        or row.get("support_request_id", "")
        or row.get("return_packet_id", "")
        or ""
    )


def _record_sort_key(row: Mapping[str, Any], *, path_field: str, id_field: str) -> tuple[str, float, str]:
    mtime = 0.0
    path_text = str(row.get(path_field, "") or "").strip()
    if path_text:
        try:
            mtime = Path(path_text).stat().st_mtime
        except OSError:
            mtime = 0.0
    return (_record_sort_time(row), mtime, str(row.get(id_field, "") or ""))


def _supersede_duplicate_pending_blockers(
    operator_root: str | Path,
    *,
    returns: list[dict[str, Any]],
    support_requests: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    now = _utc_now()
    return_groups: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for packet in returns:
        review_state = str(packet.get("review_state", "") or "")
        stalled_or_support_blocker = bool(packet.get("support_required_before_continue")) or (
            "resident_worker_stalled" in {str(item) for item in list(packet.get("risks", []) or [])}
        )
        unattributed_requeued_blocker = (
            review_state == "requeued"
            and stalled_or_support_blocker
            and not str(packet.get("superseded_by_active_child_run_id", "") or "").strip()
            and not str(packet.get("superseded_by_return_packet_id", "") or "").strip()
        )
        if review_state != "pending_operator_review" and not unattributed_requeued_blocker:
            continue
        if not bool(packet.get("support_required_before_continue")) and "resident_worker_stalled" not in {
            str(item) for item in list(packet.get("risks", []) or [])
        }:
            continue
        directive_id = str(packet.get("directive_id", "") or "")
        if not directive_id:
            continue
        return_groups.setdefault((directive_id, _return_blocker_target(packet)), []).append(packet)
    keep_return_ids: set[str] = set()
    superseded_return_by_id: dict[str, str] = {}
    superseded_return_reason_by_id: dict[str, str] = {}
    for packets in return_groups.values():
        directive_id = str(packets[0].get("directive_id", "") or "") if packets else ""
        directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
        latest_return_packet_id = str(directive.get("latest_return_packet_id", "") or "")
        preferred = [
            packet
            for packet in packets
            if str(packet.get("return_packet_id", "") or "") == latest_return_packet_id
        ]
        ordered = sorted(
            packets,
            key=lambda packet: _record_sort_key(
                packet,
                path_field="return_packet_path",
                id_field="return_packet_id",
            ),
        )
        keeper = preferred[0] if preferred else ordered[-1]
        keeper_id = str(keeper.get("return_packet_id", "") or "")
        if keeper_id:
            keep_return_ids.add(keeper_id)
        for packet in ordered:
            packet_id = str(packet.get("return_packet_id", "") or "")
            if packet_id and packet_id != keeper_id:
                superseded_return_by_id[packet_id] = keeper_id
                superseded_return_reason_by_id[packet_id] = "duplicate_pending_blocker_replaced"
    child_return_groups: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for packet in returns:
        if str(packet.get("review_state", "") or "") != "pending_operator_review":
            continue
        directive_id = str(packet.get("directive_id", "") or "")
        child_id = str(packet.get("child_run_id", "") or "")
        if not directive_id or not child_id:
            continue
        child_return_groups.setdefault((directive_id, child_id), []).append(packet)
    for packets in child_return_groups.values():
        if len(packets) < 2:
            continue
        directive_id = str(packets[0].get("directive_id", "") or "") if packets else ""
        directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
        latest_return_packet_id = str(directive.get("latest_return_packet_id", "") or "")
        preferred = [
            packet
            for packet in packets
            if str(packet.get("return_packet_id", "") or "") == latest_return_packet_id
        ]
        ordered = sorted(
            packets,
            key=lambda packet: _record_sort_key(
                packet,
                path_field="return_packet_path",
                id_field="return_packet_id",
            ),
        )
        keeper = preferred[0] if preferred else ordered[-1]
        keeper_id = str(keeper.get("return_packet_id", "") or "")
        if keeper_id:
            keep_return_ids.add(keeper_id)
        for packet in ordered:
            packet_id = str(packet.get("return_packet_id", "") or "")
            if packet_id and packet_id != keeper_id and packet_id not in keep_return_ids:
                superseded_return_by_id[packet_id] = keeper_id
                superseded_return_reason_by_id.setdefault(packet_id, "duplicate_pending_return_replaced")
    updated_returns: list[dict[str, Any]] = []
    for packet in returns:
        row = dict(packet)
        packet_id = str(row.get("return_packet_id", "") or "")
        if packet_id in superseded_return_by_id:
            row["review_state"] = "requeued"
            row["reviewed_at"] = now
            row["updated_at"] = now
            row["superseded_by_return_packet_id"] = superseded_return_by_id[packet_id]
            row["superseded_reason"] = superseded_return_reason_by_id.get(
                packet_id,
                "duplicate_pending_blocker_replaced",
            )
            _write_json(_return_path(operator_root, packet_id), row)
            try:
                _append_self_healing_evidence(
                    operator_root,
                    healing_kind="duplicate_pending_return_suppression",
                    directive_id=str(row.get("directive_id", "") or ""),
                    return_packet_id=packet_id,
                    child_run_id=str(row.get("child_run_id", "") or ""),
                    reason=str(row.get("superseded_reason", "") or "duplicate_pending_return_replaced"),
                    evidence_refs=[
                        packet_id,
                        str(row.get("superseded_by_return_packet_id", "") or ""),
                    ],
                )
            except Exception:
                pass
        updated_returns.append(row)

    support_groups: dict[tuple[str, str, str], list[dict[str, Any]]] = {}
    support_by_return: dict[str, str] = {}
    for packet in returns:
        packet_id = str(packet.get("return_packet_id", "") or "")
        for support_id in list(packet.get("support_request_ids", []) or []):
            support_by_return[str(support_id)] = packet_id
    for request in support_requests:
        if str(request.get("support_state", "") or "") != "pending_operator_review":
            continue
        directive_id = str(request.get("directive_id", "") or "")
        capability = str(request.get("capability", "") or "")
        if not directive_id or not capability:
            continue
        support_groups.setdefault((directive_id, capability, _support_request_target(request)), []).append(request)
    superseded_support_by_id: dict[str, str] = {}
    for requests in support_groups.values():
        ordered = sorted(
            requests,
            key=lambda request: _record_sort_key(
                request,
                path_field="support_request_path",
                id_field="support_request_id",
            ),
        )
        keeper = ordered[-1]
        keeper_id = str(keeper.get("support_request_id", "") or "")
        for request in ordered[:-1]:
            support_id = str(request.get("support_request_id", "") or "")
            if support_id:
                superseded_support_by_id[support_id] = keeper_id
    updated_support: list[dict[str, Any]] = []
    for request in support_requests:
        row = dict(request)
        support_id = str(row.get("support_request_id", "") or "")
        if support_id in superseded_support_by_id:
            row["support_state"] = "superseded"
            row["operator_review_required"] = False
            row["superseded_by_support_request_id"] = superseded_support_by_id[support_id]
            row["superseded_reason"] = "duplicate_pending_blocker_replaced"
            row["updated_at"] = now
            _write_json(_support_request_path(operator_root, support_id), row)
            _append_ledger(operator_root, "support_request_events", {"event": "superseded", **row})
        updated_support.append(row)
    return updated_returns, updated_support


def _append_self_healing_evidence(
    operator_root: str | Path,
    *,
    healing_kind: str,
    directive_id: str = "",
    return_packet_id: str = "",
    child_run_id: str = "",
    reason: str = "",
    evidence_refs: Iterable[str] = (),
) -> dict[str, Any]:
    now = _utc_now()
    evidence = {
        "schema_name": "SelfHealingEvidence",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "self_healing_evidence_id": _record_id(
            "self-healing",
            healing_kind,
            directive_id,
            return_packet_id,
            child_run_id,
            reason,
        ),
        "created_at": now,
        "source": "conveyor_control_plane",
        "healing_kind": str(healing_kind or ""),
        "healing_action": str(healing_kind or ""),
        "directive_id": str(directive_id or ""),
        "return_packet_id": str(return_packet_id or ""),
        "child_run_id": str(child_run_id or ""),
        "reason": str(reason or ""),
        "failure_prevented": str(reason or ""),
        "evidence_refs": [str(item) for item in evidence_refs if str(item).strip()],
        "repeat_failure_prevented": True,
        "operator_intervention_reduced": True,
        "directive_progress_delta": 1.0,
        "repeat_intervention_reduced": False,
        "grants_execution_authority": False,
    }
    record = _append_autonomy_ledger(operator_root, "self_healing_evidence", evidence)
    _write_json(autonomy_root(operator_root) / "self_healing_evidence_latest.json", record)
    _persist_capability_consumption_event(
        operator_root,
        {
            "consumed_capability_kinds": ["control_plane_self_healing_v1"],
            "planner_hook_references": ["conveyor.control_plane_self_healing"],
            "runtime_hook_references": [
                str(record.get("self_healing_evidence_id", "") or ""),
                str(return_packet_id or ""),
            ],
            "baseline_action": "operator_manual_cleanup_required",
            "final_action": str(healing_kind or "control_plane_self_healing"),
            "decision_changed_by_capability": True,
            "repeat_failure_prevented": True,
            "operator_intervention_reduced": True,
            "directive_progress_delta": 1.0,
            "target_correct_gate_closure": True,
            "hook_reason": str(reason or ""),
            "safety_gates_preserved": [
                "operator_review_state_only",
                "no_execution_authority",
            ],
        },
        operation_id=str(record.get("self_healing_evidence_id", "") or ""),
    )
    return record


def _directive_expects_build_grade_documentation(directive: Mapping[str, Any]) -> bool:
    text = str(directive.get("directive_text", "") or "").lower()
    metadata = dict(directive.get("metadata", {}) or {})
    return (
        "deliverables" in text
        or "technical documentation" in text
        or "build-grade" in text
        or bool(metadata.get("requires_build_grade_documentation", False))
    )


def _packet_workspace_root(packet: Mapping[str, Any]) -> Path | None:
    summary = dict(packet.get("resource_runtime_summary", {}) or {})
    workspace = str(summary.get("workspace_root", "") or "").strip()
    if not workspace:
        return None
    for path in _host_visible_path_candidates(workspace):
        if path.exists() and path.is_dir():
            return path.resolve()
    return None


def _packet_artifact_manifest(packet: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    manifest = packet.get("artifact_manifest", {})
    if not isinstance(manifest, Mapping):
        return {}
    return {
        str(name): dict(payload)
        for name, payload in manifest.items()
        if str(name).strip() and isinstance(payload, Mapping)
    }


def _packet_artifact_path(packet: Mapping[str, Any], artifact_name: str) -> Path | None:
    artifact = str(artifact_name or "").strip()
    if not artifact:
        return None
    manifest = _packet_artifact_manifest(packet)
    row = manifest.get(artifact, {})
    for key in ("source_path", "path", "canonical_path"):
        source = str(row.get(key, "") or "").strip()
        if not source:
            continue
        candidates = [Path(source).resolve()]
        if "\\" in source:
            candidates.append(Path(source.replace("\\", "/")).resolve())
        for candidate in candidates:
            if candidate.name != artifact:
                continue
            if candidate.exists() and candidate.is_file():
                return candidate
    workspace = _packet_workspace_root(packet)
    if workspace is not None:
        candidate = (workspace / artifact).resolve()
        try:
            candidate.relative_to(workspace.resolve())
        except ValueError:
            candidate = None
        if candidate and candidate.exists() and candidate.is_file():
            return candidate
    return None


def _packet_materialized_file_exists(packet: Mapping[str, Any], relative_path: str) -> bool:
    rel = str(relative_path or "").strip().replace("\\", "/")
    if not rel or rel.startswith("/") or ".." in Path(rel).parts:
        return False
    roots: list[Path] = []
    workspace = _packet_workspace_root(packet)
    if workspace is not None:
        roots.append(workspace)
    for row in _packet_artifact_manifest(packet).values():
        for key in ("source_path", "path", "canonical_path"):
            source = str(row.get(key, "") or "").strip()
            if not source:
                continue
            source_path = Path(source)
            roots.append(source_path.parent)
            if "\\" in source:
                roots.append(Path(source.replace("\\", "/")).parent)
    seen: set[str] = set()
    for root in roots:
        root_key = str(root)
        if root_key in seen:
            continue
        seen.add(root_key)
        for candidate_root in _host_visible_path_candidates(root):
            candidate = (candidate_root / rel).resolve()
            try:
                candidate.relative_to(candidate_root.resolve())
            except ValueError:
                continue
            if candidate.exists() and candidate.is_file():
                return True
    return False


def _read_packet_artifact_text(packet: Mapping[str, Any], *, max_chars: int = 20000) -> str:
    chunks: list[str] = []
    for artifact in list(packet.get("artifacts", []) or []):
        artifact_name = str(artifact or "").strip()
        if not artifact_name:
            continue
        candidate = _packet_artifact_path(packet, artifact_name)
        if candidate is None:
            continue
        try:
            text = candidate.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if text.strip():
            chunks.append(text[:max_chars])
    return "\n\n".join(chunks)[: max_chars * 2]


def _read_packet_artifact_json(packet: Mapping[str, Any], artifact_name: str) -> dict[str, Any]:
    candidate = _packet_artifact_path(packet, artifact_name)
    if candidate is None:
        return {}
    try:
        payload = json.loads(candidate.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _related_support_requests_for_packet(
    operator_root: str | Path,
    packet: Mapping[str, Any],
    *,
    capability: str = "",
) -> list[dict[str, Any]]:
    directive_id = str(packet.get("directive_id", "") or "").strip()
    child_run_id = str(packet.get("child_run_id", "") or "").strip()
    return_packet_id = str(packet.get("return_packet_id", "") or "").strip()
    resident_progress_id = f"resident-progress-{child_run_id}" if child_run_id else ""
    rows: list[dict[str, Any]] = []
    for support in _load_items(_support_requests_root(operator_root)):
        support_capability = str(support.get("capability", "") or "").strip()
        if capability and support_capability != capability:
            continue
        if directive_id and str(support.get("directive_id", "") or "").strip() != directive_id:
            continue
        support_return = str(support.get("return_packet_id", "") or "").strip()
        support_child = str(support.get("child_run_id", "") or "").strip()
        if support_return in {return_packet_id, resident_progress_id} or (
            child_run_id and support_child == child_run_id
        ):
            rows.append(dict(support))
    return rows


def _resolve_return_operator_feedback(
    operator_root: str | Path,
    *,
    packet: Mapping[str, Any],
    feedback: str,
    clarifications: Iterable[Mapping[str, Any]] | None = None,
    operator_note: str = "",
    resolution_source: str = "operator_deeper_pass_direction",
) -> list[dict[str, Any]]:
    feedback_text = str(feedback or operator_note or "").strip()
    if not feedback_text:
        return []
    return_packet_id = str(packet.get("return_packet_id", "") or "")
    if not return_packet_id:
        return []
    directive_id = str(packet.get("directive_id", "") or "")
    directive = _load_directive(operator_root, directive_id)
    if not directive:
        return []
    requested = [
        dict(item)
        for item in list(packet.get("requested_operator_clarifications", []) or [])
        if isinstance(item, Mapping) and not bool(item.get("resolved", False))
    ]
    requested_by_id = {
        str(item.get("clarification_id", "") or ""): item
        for item in requested
        if str(item.get("clarification_id", "") or "")
    }
    answer_payloads = [
        dict(item)
        for item in list(clarifications or [] or [])
        if isinstance(item, Mapping)
    ]
    if not answer_payloads:
        answer_payloads = [
            {
                "clarification_id": str(
                    source.get("clarification_id", "") or f"clarification-{uuid.uuid4().hex[:10]}"
                ),
                "answer": feedback_text,
            }
            for source in requested
        ]
    if not answer_payloads:
        return []
    now = _utc_now()
    resolved_records: list[dict[str, Any]] = []
    for index, answer in enumerate(answer_payloads):
        clarification_id = str(answer.get("clarification_id", "") or "").strip()
        source = requested_by_id.get(clarification_id)
        if source is None and index < len(requested):
            source = requested[index]
            clarification_id = clarification_id or str(source.get("clarification_id", "") or "")
        if not clarification_id:
            clarification_id = f"clarification-{uuid.uuid4().hex[:10]}"
        source = dict(source or {})
        resolved_records.append(
            {
                "clarification_id": clarification_id,
                "question": str(answer.get("question", "") or source.get("question", "") or ""),
                "answer": str(
                    answer.get("answer", "")
                    or answer.get("operator_answer", "")
                    or feedback_text
                ).strip(),
                "blocked_gate": str(
                    answer.get("blocked_gate", "")
                    or source.get("blocked_gate", "")
                    or source.get("blocked_requirement", "")
                    or "operator_clarification_required"
                ),
                "target_artifact": str(
                    answer.get("target_artifact", "") or source.get("target_artifact", "") or ""
                ),
                "proposed_options": [
                    dict(item) if isinstance(item, Mapping) else str(item)
                    for item in list(answer.get("proposed_options", source.get("proposed_options", [])) or [])
                ],
                "resolved": True,
                "resolution_source": resolution_source,
                "return_packet_id": return_packet_id,
                "operator_feedback": feedback_text,
                "answered_at": now,
            }
        )
    existing = [
        dict(item)
        for item in list(directive.get("operator_clarifications", []) or [])
        if isinstance(item, Mapping)
    ]
    by_id = {
        str(item.get("clarification_id", "") or f"clarification-{uuid.uuid4().hex[:10]}"): item
        for item in existing
    }
    for record in resolved_records:
        by_id[str(record["clarification_id"])] = record
    directive["operator_clarifications"] = list(by_id.values())
    directive["operator_feedback"] = feedback_text
    directive["updated_at"] = now
    _write_json(_directive_path(operator_root, directive_id), directive)
    packet_payload = dict(_read_json(_return_path(operator_root, return_packet_id)) or packet)
    resolved_by_id = {str(item.get("clarification_id", "") or ""): item for item in resolved_records}
    updated_requested = []
    for item in list(packet_payload.get("requested_operator_clarifications", []) or []):
        if not isinstance(item, Mapping):
            continue
        updated = dict(item)
        resolved = resolved_by_id.get(str(updated.get("clarification_id", "") or ""))
        if resolved:
            updated.update(
                {
                    "resolved": True,
                    "answer": resolved["answer"],
                    "answered_at": resolved["answered_at"],
                    "resolution_source": resolution_source,
                }
            )
        updated_requested.append(updated)
    packet_payload["requested_operator_clarifications"] = updated_requested
    packet_payload["operator_clarifications_resolved"] = resolved_records
    packet_payload["operator_feedback"] = feedback_text
    packet_payload["updated_at"] = now
    _write_json(_return_path(operator_root, return_packet_id), packet_payload)
    _append_ledger(
        operator_root,
        "directive_events",
        {
            "event": "operator_feedback_resolved_clarifications",
            "generated_at": now,
            "directive_id": directive_id,
            "return_packet_id": return_packet_id,
            "resolution_source": resolution_source,
            "clarification_count": len(resolved_records),
        },
    )
    return resolved_records


def _cleanup_related_support_requests_for_requeue(
    operator_root: str | Path,
    *,
    packet: Mapping[str, Any],
    state_root: str | Path | None,
    feedback: str,
    operator_note: str = "",
) -> list[dict[str, Any]]:
    feedback_text = str(feedback or operator_note or "").strip()
    return_packet_id = str(packet.get("return_packet_id", "") or "")
    cleaned: list[dict[str, Any]] = []
    related_support = _related_support_requests_for_packet(operator_root, packet)
    cleanup_capabilities = {
        str(item.get("capability", "") or "")
        for item in related_support
        if str(item.get("capability", "") or "")
    }
    directive_id = str(packet.get("directive_id", "") or "")
    seen_support_ids = {
        str(item.get("support_request_id", "") or "")
        for item in related_support
        if str(item.get("support_request_id", "") or "")
    }
    if cleanup_capabilities and directive_id:
        for support in _load_items(_support_requests_root(operator_root)):
            support_request_id = str(support.get("support_request_id", "") or "")
            if not support_request_id or support_request_id in seen_support_ids:
                continue
            if str(support.get("support_state", "") or "") != "pending_operator_review":
                continue
            if str(support.get("directive_id", "") or "") != directive_id:
                continue
            if str(support.get("capability", "") or "") not in cleanup_capabilities:
                continue
            if not str(support.get("return_packet_id", "") or "").startswith("resident-progress-"):
                continue
            related_support.append(dict(support))
            seen_support_ids.add(support_request_id)
    for support in related_support:
        if str(support.get("support_state", "") or "") != "pending_operator_review":
            continue
        support_request_id = str(support.get("support_request_id", "") or "")
        if not support_request_id:
            continue
        capability = str(support.get("capability", "") or "")
        pack_ref = _existing_support_pack_ref(
            state_root=state_root,
            directive_id=str(support.get("directive_id", "") or ""),
            capability=capability,
        )
        now = _utc_now()
        updated = dict(support)
        if pack_ref:
            updated["support_state"] = "satisfied"
            updated["satisfied_pack_ref"] = str(pack_ref.get("pack_id", "") or "")
            updated["satisfied_pack"] = pack_ref
            event = "satisfied_by_operator_deeper_pass_existing_pack"
        else:
            updated["support_state"] = "superseded"
            updated["satisfied_pack_ref"] = ""
            updated["satisfied_pack"] = dict(updated.get("satisfied_pack", {}) or {})
            updated["superseded_by_return_packet_id"] = return_packet_id
            updated["superseded_reason"] = "operator_deeper_pass_direction"
            updated["operator_feedback"] = feedback_text
            event = "superseded_by_operator_deeper_pass"
        updated["operator_review_required"] = False
        updated["grants_execution_authority"] = False
        updated["updated_at"] = now
        _write_json(_support_request_path(operator_root, support_request_id), updated)
        _append_ledger(operator_root, "support_request_events", {"event": event, **updated})
        cleaned.append(updated)
    return cleaned


def _supersede_sibling_pending_returns_for_requeue(
    operator_root: str | Path,
    *,
    packet: Mapping[str, Any],
    feedback: str,
) -> list[dict[str, Any]]:
    return_packet_id = str(packet.get("return_packet_id", "") or "")
    directive_id = str(packet.get("directive_id", "") or "")
    child_run_id = str(packet.get("child_run_id", "") or "")
    if not directive_id or not return_packet_id:
        return []
    now = _utc_now()
    superseded: list[dict[str, Any]] = []
    for candidate in _load_items(_returns_root(operator_root)):
        candidate_id = str(candidate.get("return_packet_id", "") or "")
        if not candidate_id or candidate_id == return_packet_id:
            continue
        if str(candidate.get("directive_id", "") or "") != directive_id:
            continue
        if child_run_id and str(candidate.get("child_run_id", "") or "") != child_run_id:
            continue
        if str(candidate.get("review_state", "") or "") != "pending_operator_review":
            continue
        updated = dict(candidate)
        updated["review_state"] = "requeued"
        updated["reviewed_at"] = now
        updated["updated_at"] = now
        updated["operator_feedback"] = str(feedback or "")
        updated["superseded_by_return_packet_id"] = return_packet_id
        updated["superseded_reason"] = "operator_requeue_sibling_return_replaced"
        updated["grants_execution_authority"] = False
        _write_json(_return_path(operator_root, candidate_id), updated)
        try:
            _append_self_healing_evidence(
                operator_root,
                healing_kind="duplicate_pending_return_suppression",
                directive_id=directive_id,
                return_packet_id=candidate_id,
                child_run_id=str(updated.get("child_run_id", "") or ""),
                reason="operator_requeue_sibling_return_replaced",
                evidence_refs=[candidate_id, return_packet_id],
            )
        except Exception:
            pass
        superseded.append(updated)
    return superseded


def _support_blocker_target_artifact(packet: Mapping[str, Any], support_requests: Iterable[Mapping[str, Any]]) -> str:
    direct = str(packet.get("target_artifact", "") or "").strip()
    if direct:
        return direct
    for item in list(packet.get("requested_operator_clarifications", []) or []):
        if not isinstance(item, Mapping):
            continue
        target = str(item.get("target_artifact", "") or "").strip()
        if target:
            return target
    for support in support_requests:
        target = str(support.get("target_artifact", "") or "").strip()
        if target:
            return target
        reason = str(support.get("reason", support.get("request_reason", "")) or "")
        match = re.search(r"targeting\s+([A-Za-z0-9_.-]+\.json)", reason)
        if match:
            return match.group(1)
    return "interface_specifications.json"


def _support_blocker_packet_fields(
    operator_root: str | Path,
    packet: Mapping[str, Any],
    evaluation: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    evaluation_payload = dict(evaluation or {})
    related = _related_support_requests_for_packet(
        operator_root,
        packet,
        capability="directive_build_grade_synthesis_pack",
    )
    support_by_id: dict[str, dict[str, Any]] = {}
    for support in related:
        support_id = str(support.get("support_request_id", "") or "").strip()
        if support_id:
            support_by_id[support_id] = dict(support)
    for support_id in list(evaluation_payload.get("support_request_ids", []) or []):
        support_id_text = str(support_id or "").strip()
        if not support_id_text or support_id_text in support_by_id:
            continue
        support = _read_json(_support_request_path(operator_root, support_id_text))
        if support:
            support_by_id[support_id_text] = support
    support_requests = list(support_by_id.values())
    pending = [
        support
        for support in support_requests
        if str(support.get("support_state", "") or "") == "pending_operator_review"
    ]
    if not pending:
        return {}
    target_artifact = _support_blocker_target_artifact(packet, pending)
    failed_gates = [
        str(item)
        for item in list(packet.get("failed_gates", []) or [])
        if str(item or "").strip()
    ]
    for item in list(packet.get("requested_operator_clarifications", []) or []):
        if isinstance(item, Mapping):
            gate = str(item.get("blocked_gate", item.get("blocked_requirement", "")) or "").strip()
            if gate and gate not in failed_gates:
                failed_gates.append(gate)
    if "resident_worker_stalled" in {str(item) for item in list(packet.get("risks", []) or [])}:
        if "resident_artifact_delta_after_support" not in failed_gates:
            failed_gates.append("resident_artifact_delta_after_support")
    blocked_requirements = [
        str(item)
        for item in list(packet.get("blocked_requirements", []) or [])
        if str(item or "").strip()
    ]
    for reason in list(evaluation_payload.get("reasons", []) or []):
        reason_text = str(reason or "").strip()
        if reason_text and reason_text not in blocked_requirements:
            blocked_requirements.append(reason_text)
    if "kernel_support_request_pending" not in blocked_requirements:
        blocked_requirements.append("kernel_support_request_pending")
    return {
        "failed_gates": failed_gates,
        "blocked_requirements": blocked_requirements,
        "support_required_before_continue": True,
        "support_blocker_state": "pending_operator_review",
        "support_request_ids": [str(item.get("support_request_id", "") or "") for item in pending],
        "target_artifact": target_artifact,
        "next_required_operator_action": "approve_support_and_continue_deeper",
    }


def _clear_stale_support_blocker_packet_fields(packet: Mapping[str, Any]) -> tuple[dict[str, Any], bool]:
    row = dict(packet)
    stale_keys = (
        "support_required_before_continue",
        "support_blocker_state",
        "support_request_ids",
        "next_required_operator_action",
    )
    changed = False
    if bool(row.get("support_required_before_continue", False)) or str(row.get("support_blocker_state", "") or ""):
        support_ids = [str(item) for item in list(row.get("support_request_ids", []) or []) if str(item or "")]
        blocker_state = str(row.get("support_blocker_state", "") or "")
        if not support_ids and blocker_state in {"", "pending_operator_review"}:
            return row, False
        for key in stale_keys:
            if key in row:
                row.pop(key, None)
                changed = True
        row["support_blocker_state"] = "resolved"
        row["support_required_before_continue"] = False
        row["updated_at"] = _utc_now()
        changed = True
    return row, changed


def _approve_related_support_requests_before_requeue(
    operator_root: str | Path,
    *,
    packet: Mapping[str, Any],
    state_root: str | Path | None,
) -> tuple[bool, list[dict[str, Any]], str]:
    if state_root is None:
        return False, [], "state_root is required to approve support before requeue."
    related = _related_support_requests_for_packet(operator_root, packet)
    pending = [
        dict(item)
        for item in related
        if str(item.get("support_state", "") or "") == "pending_operator_review"
    ]
    results: list[dict[str, Any]] = []
    for support in pending:
        support_request_id = str(support.get("support_request_id", "") or "").strip()
        if not support_request_id:
            continue
        pack_ref = _existing_support_pack_ref(
            state_root=state_root,
            directive_id=str(support.get("directive_id", "") or ""),
            capability=str(support.get("capability", "") or ""),
        )
        if pack_ref:
            result = satisfy_conveyor_support_request(
                operator_root,
                state_root=state_root,
                support_request_id=support_request_id,
            )
        else:
            result = approve_conveyor_support_request(
                operator_root,
                state_root=state_root,
                support_request_id=support_request_id,
            )
        result_payload = dict(result)
        result_payload["support_request_id"] = support_request_id
        results.append(result_payload)
        if not bool(result_payload.get("ok", False)):
            return False, results, str(result_payload.get("message", "") or "Support approval failed.")
    return True, results, ""


def _continuous_campaign_policy(scheduler: Mapping[str, Any]) -> dict[str, Any]:
    policy = {**DEFAULT_CONTINUOUS_CAMPAIGN_POLICY, **dict(scheduler.get("continuous_campaign_policy", {}) or {})}
    for key in (
        "auto_continue_depth_pass_cap",
        "auto_support_approval_cap",
        "no_progress_escalation_attempts",
        "resident_cycle_sleep_seconds",
    ):
        try:
            policy[key] = max(0, int(policy.get(key, 0) or 0))
        except (TypeError, ValueError):
            policy[key] = int(DEFAULT_CONTINUOUS_CAMPAIGN_POLICY[key])
    return policy


def _continuous_campaign_no_progress(packet: Mapping[str, Any]) -> bool:
    return (
        "resident_worker_stalled" in {str(item) for item in list(packet.get("risks", []) or [])}
        and int(packet.get("novelty_count", 0) or 0) <= 0
        and int(packet.get("claim_count", 0) or 0) <= 0
    )


def _continuous_campaign_clarifications_require_operator(
    clarifications: Iterable[Mapping[str, Any]],
) -> bool:
    routine_support_gates = {"resident_artifact_delta_after_support"}
    for clarification in clarifications:
        if not isinstance(clarification, Mapping):
            return True
        if bool(clarification.get("resolved", False)):
            continue
        blocked_gate = str(
            clarification.get("blocked_gate", "")
            or clarification.get("blocked_requirement", "")
            or ""
        )
        if blocked_gate not in routine_support_gates:
            return True
    return False


def _continuous_campaign_state(
    *,
    scheduler: Mapping[str, Any],
    directive: Mapping[str, Any],
) -> dict[str, Any]:
    policy = _continuous_campaign_policy(scheduler)
    metadata = dict(directive.get("metadata", {}) or {})
    auto_continue_cap = int(policy.get("auto_continue_depth_pass_cap", 0) or 0)
    auto_support_cap = int(policy.get("auto_support_approval_cap", 0) or 0)
    auto_continue_used = int(metadata.get("continuous_campaign_auto_continue_count", 0) or 0)
    auto_support_used = int(metadata.get("continuous_campaign_auto_support_approval_count", 0) or 0)
    return {
        "enabled": bool(scheduler.get("continuous_campaign_mode", False)),
        "scope": str(policy.get("scope", "")),
        "trusted_source_mode": str(policy.get("trusted_source_mode", "")),
        "auto_continue_depth_pass_cap": auto_continue_cap,
        "auto_continue_depth_pass_used": auto_continue_used,
        "auto_continue_depth_pass_remaining": max(0, auto_continue_cap - auto_continue_used),
        "auto_support_approval_cap": auto_support_cap,
        "auto_support_approval_used": auto_support_used,
        "auto_support_approval_remaining": max(0, auto_support_cap - auto_support_used),
        "no_progress_escalation_attempts": int(policy.get("no_progress_escalation_attempts", 0) or 0),
        "consecutive_no_progress_count": int(metadata.get("continuous_campaign_consecutive_no_progress_count", 0) or 0),
        "latest_state": str(metadata.get("continuous_campaign_latest_state", "") or ""),
        "latest_action": str(metadata.get("continuous_campaign_latest_action", "") or ""),
        "latest_reason": str(metadata.get("continuous_campaign_latest_reason", "") or ""),
        "latest_return_packet_id": str(metadata.get("continuous_campaign_latest_return_packet_id", "") or ""),
        "latest_support_request_id": str(metadata.get("continuous_campaign_latest_support_request_id", "") or ""),
        "latest_target_artifact": str(metadata.get("continuous_campaign_latest_target_artifact", "") or ""),
        "latest_updated_at": str(metadata.get("continuous_campaign_latest_updated_at", "") or ""),
    }


def _set_continuous_campaign_metadata(
    operator_root: str | Path,
    directive: Mapping[str, Any],
    *,
    state: str,
    action: str = "",
    reason: str = "",
    return_packet_id: str = "",
    support_request_id: str = "",
    auto_continue_increment: bool = False,
    auto_support_increment: bool | int = False,
    no_progress_count: int | None = None,
    target_artifact: str = "",
    feedback: str = "",
) -> dict[str, Any]:
    directive_id = str(directive.get("directive_id", "") or "").strip()
    latest = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    updated = dict(latest or directive)
    metadata = dict(updated.get("metadata", {}) or {})
    if auto_continue_increment:
        metadata["continuous_campaign_auto_continue_count"] = (
            int(metadata.get("continuous_campaign_auto_continue_count", 0) or 0) + 1
        )
    if auto_support_increment:
        support_increment = (
            1
            if isinstance(auto_support_increment, bool)
            else max(0, int(auto_support_increment or 0))
        )
        metadata["continuous_campaign_auto_support_approval_count"] = (
            int(metadata.get("continuous_campaign_auto_support_approval_count", 0) or 0)
            + support_increment
        )
    if no_progress_count is not None:
        metadata["continuous_campaign_consecutive_no_progress_count"] = max(0, int(no_progress_count))
    now = _utc_now()
    metadata["continuous_campaign_latest_state"] = state
    metadata["continuous_campaign_latest_action"] = action
    metadata["continuous_campaign_latest_reason"] = reason
    metadata["continuous_campaign_latest_return_packet_id"] = return_packet_id
    metadata["continuous_campaign_latest_support_request_id"] = support_request_id
    metadata["continuous_campaign_latest_target_artifact"] = target_artifact
    metadata["continuous_campaign_latest_updated_at"] = now
    if target_artifact:
        metadata["initial_work_order_target_artifact"] = target_artifact
        metadata["initial_work_order_context"] = feedback
        metadata["initial_work_order_source_return_packet_id"] = return_packet_id
        metadata["initial_work_order_capability"] = "directive_build_grade_synthesis_pack"
    updated["metadata"] = metadata
    updated["updated_at"] = now
    _write_json(_directive_path(operator_root, str(updated.get("directive_id", "") or "")), updated)
    _append_ledger(
        operator_root,
        "continuous_campaign_events",
        {
            "event": state,
            "generated_at": now,
            "directive_id": str(updated.get("directive_id", "") or ""),
            "return_packet_id": return_packet_id,
            "support_request_id": support_request_id,
            "action": action,
            "reason": reason,
            "target_artifact": target_artifact,
        },
    )
    return updated


def _auto_reengagement_target_artifact(
    operator_root: str | Path,
    *,
    directive: Mapping[str, Any],
    packet: Mapping[str, Any],
    evaluation: Mapping[str, Any],
) -> str:
    failed_return_recovery = dict(evaluation.get("failed_return_recovery", {}) or {})
    failed_return_target = str(failed_return_recovery.get("target_artifact", "") or "").strip()
    if (
        bool(failed_return_recovery.get("eligible", False))
        and failed_return_target in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER
        and failed_return_target != "technical_documentation.md"
    ):
        return failed_return_target
    micro_adjustment = dict(evaluation.get("micro_adjustment", {}) or {})
    micro_target = str(micro_adjustment.get("target_artifact", "") or "").strip()
    if micro_target in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER and micro_target != "technical_documentation.md":
        return micro_target
    campaign_state = dict(evaluation.get("campaign_state", {}) or {})
    next_unresolved = str(
        evaluation.get("next_unresolved_gate_artifact", "")
        or campaign_state.get("next_unresolved_gate_artifact", "")
        or ""
    ).strip()
    if next_unresolved in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER and next_unresolved != "technical_documentation.md":
        return next_unresolved
    draft_delta = dict(campaign_state.get("draft_delta_quality", {}) or {})
    draft_target = str(draft_delta.get("target_artifact", "") or "").strip()
    if draft_target in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER and draft_target != "technical_documentation.md":
        return draft_target
    metadata = dict(directive.get("metadata", {}) or {})
    previous_target = str(metadata.get("continuous_campaign_latest_target_artifact", "") or "").strip()
    selected = _select_next_campaign_target_artifact(
        directive,
        previous_target=previous_target or "technical_documentation.md",
        missing_artifacts=list(evaluation.get("missing_artifacts", []) or []),
        campaign_state=campaign_state,
    )
    if selected and selected != "technical_documentation.md":
        return selected
    return _operator_requeue_target_artifact(
        operator_root,
        directive=directive,
        packet=packet,
        feedback="",
        previous_target=previous_target,
    )


def _reset_continuous_campaign_context(
    operator_root: str | Path,
    directive_or_id: Mapping[str, Any] | str,
    *,
    reason: str,
    action: str,
    return_packet_id: str = "",
    support_request_id: str = "",
    feedback: str = "",
    target_artifact: str = "",
) -> dict[str, Any]:
    try:
        directive = (
            _load_directive(operator_root, str(directive_or_id))
            if isinstance(directive_or_id, str)
            else dict(directive_or_id)
        )
    except ConveyorValidationError:
        return {}
    directive_id = str(directive.get("directive_id", "") or "")
    if not directive_id:
        return {}
    metadata = dict(directive.get("metadata", {}) or {})
    had_continuous_state = any(str(key).startswith("continuous_campaign_") for key in metadata)
    metadata["continuous_campaign_consecutive_no_progress_count"] = 0
    metadata["continuous_campaign_latest_state"] = "context_reset"
    metadata["continuous_campaign_latest_action"] = action
    metadata["continuous_campaign_latest_reason"] = reason
    metadata["continuous_campaign_latest_return_packet_id"] = return_packet_id
    metadata["continuous_campaign_latest_support_request_id"] = support_request_id
    if target_artifact:
        metadata["continuous_campaign_latest_target_artifact"] = target_artifact
        metadata["initial_work_order_target_artifact"] = target_artifact
        metadata["initial_work_order_context"] = feedback
        metadata["initial_work_order_source_return_packet_id"] = return_packet_id
        metadata["initial_work_order_capability"] = "directive_build_grade_synthesis_pack"
        satisfied_support = (
            _read_json(_support_request_path(operator_root, support_request_id))
            if support_request_id
            else {}
        )
        if (
            reason == "support_request_satisfied"
            and target_artifact == "bill_of_materials.json"
            and _support_requested_rows_are_accepted(satisfied_support)
        ):
            metadata["support_request_id"] = support_request_id
            metadata["source_support_request_id"] = support_request_id
            metadata["commercial_source_acquisition_required"] = False
            metadata["source_backed_rows_required"] = False
            metadata["support_recovery_state"] = "satisfied"
            metadata["support_blocker_reason"] = ""
            metadata["support_provider_quality_blocker"] = False
            metadata["uncovered_requested_row_ids"] = []
            metadata["uncovered_commercial_requested_row_ids"] = []
            metadata["support_admission_state"] = "support_materialization_pending"
            metadata["support_admission_blocker_reason"] = "support_materialization_pending"
            metadata["next_support_recovery_action"] = "materialize_consumable_support_rows"
            metadata["support_satisfied_without_requeue_blocker"] = True
        else:
            metadata = _mark_commercial_bom_requeue_blocker(
                operator_root,
                directive=directive,
                metadata=metadata,
                target_artifact=target_artifact,
            )
    metadata["continuous_campaign_latest_updated_at"] = _utc_now()
    active_child_reset_count = _reset_active_resident_quality_context(
        operator_root,
        directive_id,
        reason=reason,
        target_artifact=target_artifact,
    )
    directive["metadata"] = metadata
    directive["updated_at"] = metadata["continuous_campaign_latest_updated_at"]
    _write_json(_directive_path(operator_root, directive_id), directive)
    if had_continuous_state or reason or feedback or support_request_id:
        _append_ledger(
            operator_root,
            "continuous_campaign_events",
            {
                "event": "context_reset",
                "generated_at": metadata["continuous_campaign_latest_updated_at"],
                "directive_id": directive_id,
                "return_packet_id": return_packet_id,
                "support_request_id": support_request_id,
                "action": action,
                "reason": reason,
                "target_artifact": target_artifact,
                "feedback": str(feedback or "")[:1000],
                "active_child_quality_context_reset_count": active_child_reset_count,
            },
        )
    return directive


def _campaign_artifact_attempts(metadata: Mapping[str, Any]) -> dict[str, int]:
    attempts: dict[str, int] = {}
    for artifact, count in dict(metadata.get("continuous_campaign_artifact_attempts", {}) or {}).items():
        artifact_name = str(artifact or "")
        if artifact_name not in BUILD_GRADE_ARTIFACT_ROTATION_ORDER:
            continue
        try:
            attempts[artifact_name] = max(0, int(count or 0))
        except (TypeError, ValueError):
            attempts[artifact_name] = 0
    return attempts


CONTENT_DEPTH_FRONTIER_ARTIFACTS = (
    "technical_documentation.md",
    "prototype_assembly_plan.json",
    "claim_evidence_register.json",
)
PROTOTYPE_DELTA_TARGET_ARTIFACTS = (
    "prototype_assembly_plan.json",
    "implementation_readiness_review.json",
    "claim_evidence_register.json",
)
FULL_DIVE_OPERATOR_REQUEUE_TARGETS = (
    "interface_specifications.json",
    "dependency_matrix.json",
    "bill_of_materials.json",
    "risk_controls.json",
    "prototype_assembly_plan.json",
)
GRIN_OPERATOR_REQUEUE_TARGETS = (
    "prototype_assembly_plan.json",
    "interface_specifications.json",
    "validation_fixtures.json",
    "claim_evidence_register.json",
    "risk_controls.json",
)


def _preferred_content_depth_target(campaign_state: Mapping[str, Any] | None) -> str:
    state = dict(campaign_state or {})
    manifest = dict(state.get("campaign_manifest", {}) or state)
    artifacts = dict(manifest.get("canonical_artifacts", {}) or {})
    candidates: list[tuple[int, float, str]] = []
    for artifact_name in CONTENT_DEPTH_FRONTIER_ARTIFACTS:
        payload = dict(artifacts.get(artifact_name, {}) or {})
        if not payload:
            candidates.append((QUALITY_ARTIFACT_PRIORITY.get(artifact_name, 0), 0.0, artifact_name))
            continue
        gates = [str(item) for item in list(payload.get("failed_quality_gates", []) or []) if str(item)]
        try:
            score = float(payload.get("quality_depth_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            score = 0.0
        if gates or score < 0.75:
            candidates.append(
                (
                    QUALITY_ARTIFACT_PRIORITY.get(artifact_name, 0) + _quality_gate_severity(gates),
                    -score,
                    artifact_name,
                )
            )
    if candidates:
        return max(candidates)[2]
    return ""


def _artifact_quality_payloads(campaign_state: Mapping[str, Any] | None) -> dict[str, dict[str, Any]]:
    state = dict(campaign_state or {})
    manifest = dict(state.get("campaign_manifest", {}) or state)
    return {
        str(name): dict(payload or {})
        for name, payload in dict(manifest.get("canonical_artifacts", {}) or {}).items()
        if str(name)
    }


def _artifact_is_quality_clean(payload: Mapping[str, Any]) -> bool:
    gates = [str(item) for item in list(payload.get("failed_quality_gates", []) or []) if str(item)]
    try:
        score = float(payload.get("quality_depth_score", 0.0) or 0.0)
    except (TypeError, ValueError):
        score = 0.0
    return not gates and score >= QUALITY_CLEAN_TARGET_THRESHOLD


def _clean_quality_artifacts(campaign_state: Mapping[str, Any] | None) -> list[str]:
    artifacts = _artifact_quality_payloads(campaign_state)
    return [name for name, payload in artifacts.items() if _artifact_is_quality_clean(payload)]


def _campaign_has_handoff_or_seed_delta(campaign_state: Mapping[str, Any] | None) -> bool:
    state = dict(campaign_state or {})
    manifest = dict(state.get("campaign_manifest", {}) or state)
    handoff = manifest.get("implementation_handoff") or manifest.get("implementation_handoff_summary")
    if isinstance(handoff, Mapping) and handoff:
        return True
    for artifact_name in PROTOTYPE_DELTA_TARGET_ARTIFACTS:
        payload = dict(_artifact_quality_payloads(manifest).get(artifact_name, {}) or {})
        if payload:
            return True
    return False


def _prototype_delta_target_for_directive(directive: Mapping[str, Any] | None) -> dict[str, Any]:
    text = " ".join(
        [
            str((directive or {}).get("directive_text", "") or ""),
            str((directive or {}).get("title", "") or ""),
            str((directive or {}).get("directive_title", "") or ""),
        ]
    ).lower()
    if "grin" in text or "human advancement" in text:
        return {
            "repo_path": "prototypes/grin_signal_model",
            "prototype_family": "grin_signal_model",
            "execution_boundary": "non_invasive_synthetic_signal_model_only",
            "protected_root_write_allowed": False,
        }
    if "full dive" in text or "virtual simulation" in text:
        return {
            "repo_path": "prototypes/full_dive_runtime_core",
            "prototype_family": "full_dive_runtime_core",
            "execution_boundary": "simulation_only_runtime_core",
            "protected_root_write_allowed": False,
        }
    return {
        "repo_path": "prototypes/review_gated_seed_delta",
        "prototype_family": "review_gated_seed_delta",
        "execution_boundary": "offline_review_artifact_only",
        "protected_root_write_allowed": False,
    }


def _prototype_delta_artifact_target(
    directive: Mapping[str, Any],
    campaign_state: Mapping[str, Any] | None,
    *,
    previous: str = "",
) -> str:
    if not _campaign_has_handoff_or_seed_delta(campaign_state):
        return ""
    attempts = _campaign_artifact_attempts(dict(directive.get("metadata", {}) or {}))
    candidates = [item for item in PROTOTYPE_DELTA_TARGET_ARTIFACTS if item != previous]
    if not candidates:
        candidates = list(PROTOTYPE_DELTA_TARGET_ARTIFACTS)
    return min(candidates, key=lambda item: attempts.get(item, 0))


def _campaign_artifact_quality_clean(campaign_state: Mapping[str, Any] | None, artifact_name: str) -> bool:
    name = str(artifact_name or "").strip()
    if not name:
        return False
    state = dict(campaign_state or {})
    if name in {str(item) for item in list(state.get("quality_failed_artifacts", []) or [])}:
        return False
    artifact = dict(dict(state.get("canonical_artifacts", {}) or {}).get(name, {}) or {})
    failed_gates = [str(item) for item in list(artifact.get("failed_quality_gates", []) or []) if str(item).strip()]
    if failed_gates:
        return False
    try:
        score = float(artifact.get("quality_depth_score", 0.0) or 0.0)
    except (TypeError, ValueError):
        score = 0.0
    return score >= 0.99


def _operator_feedback_explicit_artifact(feedback: str) -> str:
    text = str(feedback or "").lower()
    artifact_names = {str(item).lower(): str(item) for item in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER}
    for pattern in (
        r"primary\s+failed\s+artifact\s*(?:is|:|-)\s*([a-z0-9_.-]+)",
        r"primary\s+failed\s+artifact\s+([a-z0-9_.-]+)",
        r"(?:continue|requeue|focus|work|stay)\s+(?:on|with)\s+([a-z0-9_.-]+\.json)\s+only",
        r"(?:target|target artifact)\s*(?:is|:|-)?\s*([a-z0-9_.-]+\.json)",
        r"(?:continue|requeue|focus|work|stay)\b.{0,80}?\b([a-z0-9_.-]+\.json)\s+(?:only|first)",
        r"([a-z0-9_.-]+\.json)\s+only",
    ):
        match = re.search(pattern, text)
        if match:
            candidate = match.group(1).strip().strip(".,;:")
            if candidate in artifact_names:
                return artifact_names[candidate]
    candidates: list[tuple[int, int, str]] = []
    for artifact_name in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER:
        lowered = artifact_name.lower()
        for match in re.finditer(re.escape(lowered), text):
            start, end = match.span()
            window_start = max(0, start - 48)
            window_end = min(len(text), end + 48)
            window = text[window_start:window_end]
            score = 1
            if re.search(r"\bonly\b", window):
                score += 100
            if re.search(r"\bfirst\b", window):
                score += 80
            if re.search(r"\btarget(?:\s+artifact)?\b", window):
                score += 70
            if re.search(r"\bcontinue\s+(?:on|with)\b|\brequeue\s+(?:on|with)\b|\bfocus\s+(?:on|with)\b", window):
                score += 60
            candidates.append((-score, start, artifact_name))
        if artifact_name == "technical_documentation.md" and (
            "technical documentation" in text or "technical doc" in text
        ):
            phrase_pos = min(
                [pos for pos in (text.find("technical documentation"), text.find("technical doc")) if pos >= 0],
                default=0,
            )
            candidates.append((-1, phrase_pos, artifact_name))
    if candidates:
        candidates.sort()
        return candidates[0][2]
    return ""


def _operator_requeue_target_priority(directive: Mapping[str, Any], feedback: str) -> tuple[str, ...]:
    source = " ".join(
        [
            str(directive.get("directive_text", "") or ""),
            str(directive.get("title", "") or ""),
            str(directive.get("directive_title", "") or ""),
            str(feedback or ""),
        ]
    ).lower()
    if "grin" in source or "human advancement" in source or "robot" in source:
        return GRIN_OPERATOR_REQUEUE_TARGETS
    if "full dive" in source or "virtual simulation" in source or "hardware" in source or "bci" in source:
        return FULL_DIVE_OPERATOR_REQUEUE_TARGETS
    return (
        "prototype_assembly_plan.json",
        "interface_specifications.json",
        "claim_evidence_register.json",
        "risk_controls.json",
    )


def _operator_requeue_target_artifact(
    operator_root: str | Path,
    *,
    directive: Mapping[str, Any],
    packet: Mapping[str, Any] | None = None,
    feedback: str = "",
    previous_target: str = "",
) -> str:
    explicit = _operator_feedback_explicit_artifact(feedback)
    if explicit:
        return explicit
    directive_id = str(directive.get("directive_id", "") or (packet or {}).get("directive_id", "") or "")
    campaign_state = _read_json(_campaign_manifest_path(operator_root, directive_id)) if directive_id else {}
    if not _campaign_artifact_quality_clean(campaign_state, "technical_documentation.md"):
        return "technical_documentation.md"
    requested_targets = [
        str(item.get("target_artifact", "") or "")
        for item in list((packet or {}).get("requested_operator_clarifications", []) or [])
        if isinstance(item, Mapping)
    ]
    previous = str(previous_target or "").strip()
    priority = list(_operator_requeue_target_priority(directive, feedback))
    for candidate in [*priority, previous, *requested_targets]:
        artifact_name = str(candidate or "").strip()
        if artifact_name and artifact_name != "technical_documentation.md" and artifact_name in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER:
            return artifact_name
    return _select_next_campaign_target_artifact(
        directive,
        previous_target=previous or "technical_documentation.md",
        campaign_state=campaign_state,
    )


def _select_next_campaign_target_artifact(
    directive: Mapping[str, Any],
    *,
    previous_target: str = "",
    missing_artifacts: Iterable[str] | None = None,
    campaign_state: Mapping[str, Any] | None = None,
) -> str:
    metadata = dict(directive.get("metadata", {}) or {})
    attempts = _campaign_artifact_attempts(metadata)
    previous = str(previous_target or metadata.get("continuous_campaign_latest_target_artifact", "") or "").strip()
    campaign_payload = dict(campaign_state or directive.get("campaign_state", {}) or {})
    artifact_gate_candidates = _artifact_level_failed_gate_candidates(
        directive,
        campaign_payload,
        exclude=[previous] if previous else [],
    )
    if artifact_gate_candidates:
        return str(artifact_gate_candidates[0].get("artifact_name", "") or "")
    content_target = _preferred_content_depth_target(campaign_state or directive.get("campaign_state", {}))
    if content_target and (previous == "implementation_readiness_review.json" or previous not in CONTENT_DEPTH_FRONTIER_ARTIFACTS):
        return content_target
    clean_artifacts = set(_clean_quality_artifacts(campaign_payload))
    if not content_target and previous in clean_artifacts:
        delta_target = _prototype_delta_artifact_target(directive, campaign_payload, previous=previous)
        if delta_target:
            return delta_target
    missing = [str(item) for item in list(missing_artifacts or []) if str(item) in BUILD_GRADE_ARTIFACT_ROTATION_ORDER]
    if not missing:
        state = dict(campaign_state or directive.get("campaign_state", {}) or {})
        quality_failed = [
            str(item)
            for item in list(state.get("quality_failed_artifacts", []) or [])
            if str(item) in BUILD_GRADE_ARTIFACT_ROTATION_ORDER
        ]
        if quality_failed:
            missing.extend(quality_failed)
        assessment = dict(state.get("build_grade_artifact_assessment", {}) or {})
        for artifact in BUILD_GRADE_ARTIFACT_ROTATION_ORDER:
            artifact_state = dict(assessment.get(artifact, {}) or {})
            if artifact_state and not bool(artifact_state.get("present", True)):
                missing.append(artifact)
    candidates = missing or list(BUILD_GRADE_ARTIFACT_ROTATION_ORDER)
    if clean_artifacts:
        filtered_candidates = [
            item
            for item in candidates
            if item not in clean_artifacts or item in PROTOTYPE_DELTA_TARGET_ARTIFACTS
        ]
        if filtered_candidates:
            candidates = filtered_candidates
    fresh_candidates = [item for item in candidates if item != previous]
    if fresh_candidates:
        candidates = fresh_candidates
    order = list(BUILD_GRADE_ARTIFACT_ROTATION_ORDER)
    if previous in order:
        start = (order.index(previous) + 1) % len(order)
        rotated_order = order[start:] + order[:start]
    else:
        rotated_order = order
    ordered_candidates = [item for item in rotated_order if item in candidates]
    if ordered_candidates:
        never_attempted = [item for item in ordered_candidates if attempts.get(item, 0) <= 0]
        if never_attempted:
            return never_attempted[0]
        return min(ordered_candidates, key=lambda item: attempts.get(item, 0))
    return candidates[0]


def _mark_campaign_artifact_attempt(
    operator_root: str | Path,
    directive: Mapping[str, Any],
    *,
    artifact: str,
    return_packet_id: str = "",
    reason: str = "",
) -> dict[str, Any]:
    artifact_name = str(artifact or "").strip()
    if artifact_name not in BUILD_GRADE_ARTIFACT_ROTATION_ORDER:
        return dict(directive)
    updated = dict(directive)
    metadata = dict(updated.get("metadata", {}) or {})
    attempts = _campaign_artifact_attempts(metadata)
    attempts[artifact_name] = attempts.get(artifact_name, 0) + 1
    metadata["continuous_campaign_artifact_attempts"] = attempts
    metadata["continuous_campaign_last_attempted_artifact"] = artifact_name
    metadata["continuous_campaign_last_attempted_return_packet_id"] = return_packet_id
    metadata["continuous_campaign_last_attempt_reason"] = reason
    updated["metadata"] = metadata
    updated["updated_at"] = _utc_now()
    _write_json(_directive_path(operator_root, str(updated.get("directive_id", "") or "")), updated)
    return updated


def _domain_quality_profile_guidance(directive: Mapping[str, Any] | None) -> str:
    title = _directive_display_title(directive or {}).lower()
    if "full dive" in title:
        return (
            "Domain profile: Full Dive should progress as a non-invasive hardware plus software interface "
            "bench-prototype dossier. Include interface architecture, sensor/actuator boundaries, signal chain, "
            "electronics BOM, electrical interface spec, simulation/HAL software, latency and sampling budgets, "
            "bench fixtures, safety case, risk controls, research evidence, and regulatory assumptions. Keep "
            "human-subject use, invasive interfaces, clinical claims, unsafe stimulation, and ungated actuation blocked."
        )
    if "virtual simulation" in title:
        return (
            "Domain profile: virtual simulation work should progress as a software/simulation prototype package. "
            "Include runtime modules, simulation architecture, data model, input/control loop, rendering or physics "
            "assumptions, evaluation fixtures, and prototype integration plan."
        )
    if "grin" in title or "human advancement" in title:
        return (
            "Domain profile: GRIN should progress as detailed architecture and non-invasive/non-clinical prototype "
            "planning. Tag invasive, clinical, human-subject, or deployment-sensitive steps as "
            "execution_gated_by_operator_approval."
        )
    return (
        "Domain profile: produce prototype-evaluable technical content with named dependencies, typed interfaces, "
        "validation fixtures, acceptance thresholds, and evidence refs."
    )


def _quality_gate_guidance(failed_gates: Iterable[str]) -> str:
    guidance = {
        "generic_bom": "Replace generic BOM placeholders with named software, hardware, fixture, data, or service dependencies.",
        "review_interface_only": "Replace review interfaces with system interfaces that define producer, consumer, typed inputs, typed outputs, failure modes, and validation hooks.",
        "non_domain_validation_fixture": "Replace generic validation assertions with concrete fixture setup, test data shape, pass/fail criteria, instrumentation, and stop conditions.",
        "unsupported_claims": "Tie material claims to checked-out support pack refs or mark them explicitly unsupported for operator review.",
        "generic_claims": "Replace category-level claims with directive-specific material claims that affect concrete prototype decisions.",
        "missing_claim_impact": "For each claim, name the artifact, subsystem, build step, or validation decision it changes.",
        "generic_assembly_plan": "Replace generic integration rows with concrete build sequence rows for named prototype modules and outputs.",
        "missing_concrete_build_sequence": "Add build order, integration dependencies, environment assumptions, validation handoffs, go/no-go criteria, and stop conditions.",
        "scaffold_technical_documentation": "Replace scaffold prose with directive-specific subsystem behavior, design choices, build steps, risks, and evidence references.",
        "missing_concrete_build_steps": "Add concrete build steps, acceptance thresholds, test environment assumptions, failure modes, and evidence references.",
        "missing_typed_contracts": "Add typed contracts, boundary conditions, input/output schemas, error handling, and validation hooks.",
        "missing_real_dependencies": "Name concrete dependencies, source constraints, substitutes, version/compatibility assumptions, and risk if missing.",
        "missing_named_modules": "Name the concrete modules, controllers, sensors, fixtures, data paths, and expected files that make the handoff inspectable.",
        "missing_handoff_acceptance_thresholds": "Add explicit handoff acceptance thresholds, pass/fail limits, measurable review criteria, and stop conditions.",
        "no_buildable_delta": "Add materially buildable technical detail rather than restating planning scaffolds.",
    }
    selected = [guidance[str(gate)] for gate in failed_gates if str(gate) in guidance]
    return " ".join(dict.fromkeys(selected))


def _campaign_artifact_guidance(
    artifact: str,
    *,
    fallback: str = "",
    directive: Mapping[str, Any] | None = None,
    failed_gates: Iterable[str] | None = None,
) -> str:
    artifact_name = str(artifact or "").strip()
    guidance = BUILD_GRADE_ARTIFACT_GUIDANCE.get(artifact_name, "")
    quality_guidance = _quality_gate_guidance(list(failed_gates or []))
    domain_guidance = _domain_quality_profile_guidance(directive)
    parts = [str(fallback or "").strip(), guidance, quality_guidance, domain_guidance]
    combined: list[str] = []
    for part in parts:
        text = str(part or "").strip()
        if text and text.lower() not in " ".join(combined).lower():
            combined.append(text)
    return " ".join(combined)


def _attempt_continuous_campaign_continuation(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    packet: Mapping[str, Any],
    evaluation: Mapping[str, Any],
) -> dict[str, Any]:
    scheduler = _load_scheduler(operator_root)
    directive = _load_directive(operator_root, str(packet.get("directive_id", "") or ""))
    policy = _continuous_campaign_policy(scheduler)
    return_packet_id = str(packet.get("return_packet_id", "") or "")
    target_artifact = _support_blocker_target_artifact(
        packet,
        _related_support_requests_for_packet(
            operator_root,
            packet,
            capability="directive_build_grade_synthesis_pack",
        ),
    )
    result_base = {
        "attempted": False,
        "state": "not_attempted",
        "action": "",
        "reason": "",
        "support_results": [],
        "auto_support_approved_count": 0,
        "auto_requeued": False,
        "target_artifact": target_artifact,
    }
    if not bool(scheduler.get("continuous_campaign_mode", False)):
        result_base["reason"] = "continuous_campaign_mode_disabled"
        return result_base
    if _autonomy_emergency_stop_active(operator_root):
        result_base["state"] = "blocked"
        result_base["reason"] = "emergency_stop"
        _set_continuous_campaign_metadata(
            operator_root,
            directive,
            state="blocked",
            reason="emergency_stop",
            return_packet_id=return_packet_id,
            target_artifact=target_artifact,
        )
        return result_base
    if policy.get("scope") == "build_grade_directives" and not _directive_expects_build_grade_documentation(directive):
        result_base["reason"] = "directive_out_of_scope"
        return result_base
    reasons = {str(item) for item in list(evaluation.get("reasons", []) or [])}
    routine_continuation_reasons = {
        "kernel_support_request_pending",
        "resident_worker_stalled",
        "operator_clarification_required",
    }
    if reasons - routine_continuation_reasons:
        result_base["state"] = "operator_review_required"
        result_base["reason"] = "non_support_blocker"
        return result_base
    if _continuous_campaign_clarifications_require_operator(
        [
            dict(item)
            for item in list(evaluation.get("requested_operator_clarifications", []) or [])
            if isinstance(item, Mapping)
        ]
    ):
        result_base["state"] = "operator_review_required"
        result_base["reason"] = "operator_clarification_required"
        return result_base
    if state_root is None:
        result_base["state"] = "operator_review_required"
        result_base["reason"] = "state_root_required"
        return result_base
    metadata = dict(directive.get("metadata", {}) or {})
    previous_no_progress_count = int(metadata.get("continuous_campaign_consecutive_no_progress_count", 0) or 0)
    no_progress_count = previous_no_progress_count + 1 if _continuous_campaign_no_progress(packet) else 0
    auto_continue_used = int(metadata.get("continuous_campaign_auto_continue_count", 0) or 0)
    if auto_continue_used >= int(policy.get("auto_continue_depth_pass_cap", 0) or 0):
        result_base.update(
            {
                "attempted": True,
                "state": "cap_exhausted",
                "reason": "continuous_campaign_depth_pass_cap_exhausted",
            }
        )
        _set_continuous_campaign_metadata(
            operator_root,
            directive,
            state="cap_exhausted",
            reason=str(result_base["reason"]),
            return_packet_id=return_packet_id,
            no_progress_count=no_progress_count,
            target_artifact=target_artifact,
        )
        return result_base
    all_related_support = [
        dict(item)
        for item in _related_support_requests_for_packet(
            operator_root,
            packet,
            capability="directive_build_grade_synthesis_pack",
        )
    ]
    related = [
        dict(item)
        for item in all_related_support
        if str(item.get("support_state", "") or "") == "pending_operator_review"
    ]
    satisfied_related = [
        dict(item)
        for item in all_related_support
        if str(item.get("support_state", "") or "") == "satisfied"
    ]
    if not related:
        if satisfied_related:
            support_results = []
            auto_support_approved = 0
        elif no_progress_count >= int(policy.get("no_progress_escalation_attempts", 0) or 0):
            result_base.update(
                {
                    "attempted": True,
                    "state": "no_progress_escalated",
                    "reason": "continuous_campaign_no_progress_cap_reached",
                }
            )
            _set_continuous_campaign_metadata(
                operator_root,
                directive,
                state="no_progress_escalated",
                reason=str(result_base["reason"]),
                return_packet_id=return_packet_id,
                no_progress_count=no_progress_count,
                target_artifact=target_artifact,
            )
            return result_base
        else:
            result_base["reason"] = "no_pending_build_grade_support"
            return result_base
    else:
        support_results = []
        auto_support_approved = 0
    for support in related:
        support_request_id = str(support.get("support_request_id", "") or "")
        pack_ref = _existing_support_pack_ref(
            state_root=state_root,
            directive_id=str(support.get("directive_id", "") or ""),
            capability=str(support.get("capability", "") or ""),
        )
        if pack_ref:
            result = satisfy_conveyor_support_request(
                operator_root,
                state_root=state_root,
                support_request_id=support_request_id,
            )
            action = "satisfied_from_existing_pack"
        else:
            auto_support_used = int(metadata.get("continuous_campaign_auto_support_approval_count", 0) or 0)
            if auto_support_used + auto_support_approved >= int(policy.get("auto_support_approval_cap", 0) or 0):
                result_base.update(
                    {
                        "attempted": True,
                        "state": "cap_exhausted",
                        "reason": "continuous_campaign_auto_support_cap_exhausted",
                        "support_results": support_results,
                    }
                )
                _set_continuous_campaign_metadata(
                    operator_root,
                    directive,
                    state="cap_exhausted",
                    reason=str(result_base["reason"]),
                    return_packet_id=return_packet_id,
                    support_request_id=support_request_id,
                    no_progress_count=no_progress_count,
                    target_artifact=target_artifact,
                )
                return result_base
            if str(policy.get("trusted_source_mode", "")) != "reuse_existing_then_capped_auto_approve":
                result_base.update(
                    {
                        "attempted": True,
                        "state": "operator_review_required",
                        "reason": "trusted_source_auto_approval_disabled",
                        "support_results": support_results,
                    }
                )
                return result_base
            result = approve_conveyor_support_request(
                operator_root,
                state_root=state_root,
                support_request_id=support_request_id,
            )
            action = "auto_approved_trusted_source"
            if bool(result.get("ok", False)):
                auto_support_approved += 1
        result_payload = dict(result)
        result_payload["continuous_campaign_action"] = action
        support_results.append(result_payload)
        if not bool(result.get("ok", False)):
            result_base.update(
                {
                    "attempted": True,
                    "state": "support_failed",
                    "reason": str(result.get("message", "") or "support_satisfaction_failed"),
                    "support_results": support_results,
                }
            )
            _set_continuous_campaign_metadata(
                operator_root,
                directive,
                state="support_failed",
                reason=str(result_base["reason"]),
                return_packet_id=return_packet_id,
                support_request_id=support_request_id,
                no_progress_count=no_progress_count,
                target_artifact=target_artifact,
            )
            return result_base
    previous_target_artifact = target_artifact
    directive_after_support = _load_directive(operator_root, str(directive.get("directive_id", "") or ""))
    directive_after_support = _mark_campaign_artifact_attempt(
        operator_root,
        directive_after_support,
        artifact=previous_target_artifact,
        return_packet_id=return_packet_id,
        reason="support_satisfied_after_blocked_pass",
    )
    target_artifact = _select_next_campaign_target_artifact(
        directive_after_support,
        previous_target=previous_target_artifact,
        missing_artifacts=list(evaluation.get("missing_artifacts", []) or []),
        campaign_state=dict(evaluation.get("campaign_state", {}) or {}),
    )
    campaign_state = dict(evaluation.get("campaign_state", {}) or {})
    failed_gates = [
        str(gate)
        for artifact in list(campaign_state.get("quality_failed_artifacts", []) or [])
        if str(artifact) == target_artifact
        for gate in list(
            dict(
                dict(campaign_state.get("campaign_manifest", {}) or {})
                .get("canonical_artifacts", {})
                .get(target_artifact, {})
            ).get("failed_quality_gates", [])
            or []
        )
    ] or list(campaign_state.get("failed_quality_gates", []) or [])
    feedback = _campaign_artifact_guidance(
        target_artifact,
        fallback=str(evaluation.get("feedback", "") or ""),
        directive=directive_after_support,
        failed_gates=failed_gates,
    )
    decision = _decide_return(
        operator_root,
        return_packet_id=return_packet_id,
        decision_state="requeued",
        operator_note="continuous_campaign_auto_continue",
        feedback=feedback,
    )
    directive_after_decision = _load_directive(operator_root, str(directive.get("directive_id", "") or ""))
    _set_continuous_campaign_metadata(
        operator_root,
        directive_after_decision,
        state="auto_requeued",
        action="continuous_campaign_auto_continue",
        reason="support_satisfied",
        return_packet_id=return_packet_id,
        support_request_id=str((related or satisfied_related or [{}])[-1].get("support_request_id", "") or ""),
        auto_continue_increment=True,
        auto_support_increment=auto_support_approved,
        no_progress_count=0,
        target_artifact=target_artifact,
        feedback=feedback,
    )
    return {
        "attempted": True,
        "state": "auto_requeued",
        "action": "continuous_campaign_auto_continue",
        "reason": "support_satisfied",
        "support_results": support_results,
        "auto_support_approved_count": auto_support_approved,
        "auto_requeued": True,
        "decision": decision,
        "target_artifact": target_artifact,
    }


def _attempt_active_resident_support_continuation(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    scheduler = _load_scheduler(operator_root)
    result: dict[str, Any] = {
        "attempted": False,
        "auto_supported_count": 0,
        "auto_support_approved_count": 0,
        "work_order_injected_count": 0,
        "blocked_count": 0,
        "results": [],
    }
    if state_root is None:
        result["reason"] = "state_root_required"
        return result
    if not bool(scheduler.get("continuous_campaign_mode", False)):
        result["reason"] = "continuous_campaign_mode_disabled"
        return result
    if _autonomy_emergency_stop_active(operator_root):
        result["reason"] = "emergency_stop"
        result["blocked_count"] = 1
        return result
    policy = _continuous_campaign_policy(scheduler)
    active_children = {
        str(child.get("child_run_id", "") or ""): dict(child)
        for child in _active_children(operator_root)
        if str(child.get("child_run_id", "") or "")
    }
    if not active_children:
        result["reason"] = "no_active_resident_children"
        return result
    pending_support = [
        dict(support)
        for support in _load_items(_support_requests_root(operator_root))
        if str(support.get("support_state", "") or "") == "pending_operator_review"
        and str(support.get("capability", "") or "") == "directive_build_grade_synthesis_pack"
        and str(support.get("child_run_id", "") or "") in active_children
        and str(support.get("return_packet_id", "") or "").startswith("resident-progress-")
    ]
    if not pending_support:
        result["reason"] = "no_active_resident_support_requests"
        return result
    result["attempted"] = True
    for support in pending_support:
        support_request_id = str(support.get("support_request_id", "") or "")
        child = dict(active_children.get(str(support.get("child_run_id", "") or ""), {}) or {})
        directive_id = str(support.get("directive_id", "") or child.get("directive_id", "") or "")
        try:
            directive = _load_directive(operator_root, directive_id)
        except ConveyorValidationError as exc:
            result["blocked_count"] += 1
            result["results"].append(
                {
                    "support_request_id": support_request_id,
                    "state": "blocked",
                    "reason": "stale_directive_reference",
                    "message": str(exc),
                }
            )
            continue
        if policy.get("scope") == "build_grade_directives" and not _directive_expects_build_grade_documentation(directive):
            result["results"].append(
                {
                    "support_request_id": support_request_id,
                    "state": "skipped",
                    "reason": "directive_out_of_scope",
                }
            )
            continue
        metadata = dict(directive.get("metadata", {}) or {})
        auto_support_used = int(metadata.get("continuous_campaign_auto_support_approval_count", 0) or 0)
        support_action = "satisfied_from_existing_pack"
        pack_ref = _existing_support_pack_ref(
            state_root=state_root,
            directive_id=directive_id,
            capability=str(support.get("capability", "") or ""),
        )
        if pack_ref:
            support_result = satisfy_conveyor_support_request(
                operator_root,
                state_root=state_root,
                support_request_id=support_request_id,
            )
            auto_support_increment = 0
        else:
            if auto_support_used >= int(policy.get("auto_support_approval_cap", 0) or 0):
                result["blocked_count"] += 1
                _set_continuous_campaign_metadata(
                    operator_root,
                    directive,
                    state="cap_exhausted",
                    reason="continuous_campaign_auto_support_cap_exhausted",
                    support_request_id=support_request_id,
                    target_artifact=str(support.get("target_artifact", "") or ""),
                )
                result["results"].append(
                    {
                        "support_request_id": support_request_id,
                        "state": "cap_exhausted",
                        "reason": "continuous_campaign_auto_support_cap_exhausted",
                    }
                )
                continue
            if str(policy.get("trusted_source_mode", "")) != "reuse_existing_then_capped_auto_approve":
                result["blocked_count"] += 1
                result["results"].append(
                    {
                        "support_request_id": support_request_id,
                        "state": "blocked",
                        "reason": "trusted_source_auto_approval_disabled",
                    }
                )
                continue
            support_result = approve_conveyor_support_request(
                operator_root,
                state_root=state_root,
                support_request_id=support_request_id,
            )
            support_action = "auto_approved_trusted_source"
            auto_support_increment = 1 if bool(support_result.get("ok", False)) else 0
        if not bool(support_result.get("ok", False)):
            result["blocked_count"] += 1
            result["results"].append(
                {
                    "support_request_id": support_request_id,
                    "state": "support_failed",
                    "reason": str(support_result.get("message", "") or "support_satisfaction_failed"),
                    "support_result": support_result,
                }
            )
            continue
        manifest = _write_campaign_manifest(operator_root, directive_id, active_child=child)
        support_target = str(support.get("target_artifact", "") or "").strip()
        target_artifact = _preferred_content_depth_target(manifest)
        if not target_artifact:
            target_artifact = _weakest_failed_artifact_from_manifest(manifest) or support_target
        if target_artifact == "implementation_readiness_review.json":
            target_artifact = _preferred_content_depth_target(manifest) or "technical_documentation.md"
        target_artifact = target_artifact or "technical_documentation.md"
        latest_progress = _latest_child_progress(child)
        work_order = _append_resident_work_order(
            operator_root,
            state_root=state_root,
            child=child,
            latest_progress=latest_progress,
            target_artifact=target_artifact,
            reason=(
                f"Continuous campaign satisfied {support_request_id}; continue with the weakest content "
                f"artifact {target_artifact} using concrete prototype-depth fields."
            ),
        )
        support_payload = dict(support_result.get("support_request", {}) or {})
        satisfied_pack = dict(support_payload.get("satisfied_pack", {}) or {})
        satisfied_pack_ref = str(
            support_payload.get("satisfied_pack_ref", "")
            or satisfied_pack.get("pack_id", "")
            or ""
        )
        for related_support in _related_support_requests_for_packet(
            operator_root,
            {
                "directive_id": directive_id,
                "child_run_id": str(child.get("child_run_id", "") or ""),
                "return_packet_id": f"resident-progress-{child.get('child_run_id', '')}",
            },
            capability="directive_build_grade_synthesis_pack",
        ):
            related_support_id = str(related_support.get("support_request_id", "") or "")
            if related_support_id == support_request_id:
                continue
            if str(related_support.get("support_state", "") or "") != "pending_operator_review":
                continue
            updated_support = dict(related_support)
            updated_support["support_state"] = "satisfied"
            updated_support["operator_review_required"] = False
            updated_support["satisfied_pack"] = satisfied_pack or dict(updated_support.get("satisfied_pack", {}) or {})
            updated_support["satisfied_pack_ref"] = str(
                satisfied_pack_ref
                or updated_support.get("satisfied_pack_ref", "")
                or dict(updated_support.get("satisfied_pack", {}) or {}).get("pack_id", "")
                or ""
            )
            updated_support["satisfied_by_support_request_id"] = support_request_id
            updated_support["updated_at"] = _utc_now()
            _write_json(_support_request_path(operator_root, related_support_id), updated_support)
            _append_ledger(
                operator_root,
                "support_request_events",
                {"event": "satisfied_by_active_resident_continuation", **updated_support},
            )
        child_payload = dict(_read_json(_child_path(operator_root, str(child.get("child_run_id", "") or ""))) or child)
        child_payload["resident_worker_state"] = "quality_support_auto_continued"
        child_payload["latest_quality_target"] = target_artifact
        child_payload["latest_quality_retarget_reason"] = "active_resident_support_auto_satisfied"
        child_payload["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
        child_payload["latest_work_order_target_artifact"] = target_artifact
        child_payload["latest_work_order_at"] = str(work_order.get("generated_at", "") or "")
        child_payload["latest_work_order"] = dict(work_order)
        child_payload["updated_at"] = _utc_now()
        _write_json(_child_path(operator_root, str(child_payload.get("child_run_id", "") or "")), child_payload)
        directive_after_support = _load_directive(operator_root, directive_id)
        _set_continuous_campaign_metadata(
            operator_root,
            directive_after_support,
            state="auto_supported_active_resident",
            action=support_action,
            reason="active_resident_support_satisfied",
            support_request_id=support_request_id,
            auto_support_increment=auto_support_increment,
            no_progress_count=0,
            target_artifact=target_artifact,
            feedback=str(work_order.get("next_step_context", "") or ""),
        )
        result["auto_supported_count"] += 1
        result["auto_support_approved_count"] += auto_support_increment
        result["work_order_injected_count"] += 1
        result["results"].append(
            {
                "support_request_id": support_request_id,
                "state": "auto_supported",
                "action": support_action,
                "target_artifact": target_artifact,
                "work_order_id": str(work_order.get("work_order_id", "") or ""),
                "support_result": support_result,
            }
        )
    return result


def _host_visible_path_candidates(recorded_path: str | Path) -> list[Path]:
    raw = str(recorded_path or "").strip()
    if not raw:
        return []
    candidates = [Path(raw)]
    normalized = raw.replace("\\", "/")
    marker = "/operator_state/"
    if marker in normalized:
        suffix = normalized.split(marker, 1)[1]
        candidates.append(Path.cwd() / "operator_state" / suffix)
    elif normalized.startswith("operator_state/"):
        candidates.append(Path.cwd() / normalized)
    return candidates


def _child_workspace_candidates(child: Mapping[str, Any]) -> list[Path]:
    candidates: list[Path] = []
    for key in ("workspace_root", "workspace_path"):
        for candidate in _host_visible_path_candidates(str(child.get(key, "") or "")):
            if candidate not in candidates:
                candidates.append(candidate)
    return candidates


def _latest_child_workspace_artifacts(child: Mapping[str, Any]) -> tuple[list[str], dict[str, Any]]:
    workspace: Path | None = None
    for candidate in _child_workspace_candidates(child):
        if candidate.exists() and candidate.is_dir():
            workspace = candidate.resolve()
            break
    if workspace is None:
        return [], {}
    artifacts: list[str] = []
    manifest: dict[str, Any] = {}
    for artifact_name in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER:
        artifact_path = (workspace / artifact_name).resolve()
        try:
            artifact_path.relative_to(workspace)
        except ValueError:
            continue
        if not artifact_path.exists() or not artifact_path.is_file():
            continue
        try:
            data = artifact_path.read_bytes()
        except OSError:
            continue
        artifacts.append(artifact_name)
        manifest[artifact_name] = {
            "artifact_name": artifact_name,
            "source_path": str(artifact_path),
            "size_bytes": len(data),
            "modified_at_epoch": round(artifact_path.stat().st_mtime, 6),
            "sha256": hashlib.sha256(data).hexdigest(),
            "hash": hashlib.sha256(data).hexdigest(),
        }
    return artifacts, manifest


def _return_manifest_entry(artifact_name: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    row = dict(payload)
    failed_gates = [str(item) for item in list(row.get("failed_quality_gates", []) or []) if str(item)]
    try:
        quality_score = float(row.get("quality_depth_score", 0.0) or 0.0)
    except (TypeError, ValueError):
        quality_score = 0.0
    evidence_refs = [
        str(item)
        for item in list(row.get("evidence_refs", row.get("verification_evidence", [])) or [])
        if str(item or "").strip()
    ]
    if not evidence_refs:
        evidence_refs = [f"artifact:{artifact_name}"]
    entry = {
        "artifact_name": artifact_name,
        "source_path": str(row.get("source_path", row.get("path", "")) or ""),
        "sha256": str(row.get("sha256", row.get("hash", "")) or ""),
        "hash": str(row.get("hash", row.get("sha256", "")) or ""),
        "size_bytes": int(row.get("size_bytes", 0) or 0),
        "modified_at_epoch": row.get("modified_at_epoch", 0),
        "evidence_refs": evidence_refs,
        "quality_depth_score": quality_score,
        "quality_state": str(row.get("quality_state", "") or ""),
        "failed_quality_gates": failed_gates,
        "gate_status": "failed" if failed_gates or (quality_score and quality_score < 0.75) else "passed",
        "execution_gated_by_operator_approval": bool(
            row.get("execution_gated_by_operator_approval", False)
        )
        or str(row.get("execution_gate", "") or "") == "execution_gated_by_operator_approval",
    }
    if isinstance(row.get("compiled_documentation"), Mapping):
        entry["compiled_documentation"] = dict(row.get("compiled_documentation", {}) or {})
    return entry


def _append_unique(values: list[str], *items: str) -> list[str]:
    for item in items:
        text = str(item or "").strip()
        if text and text not in values:
            values.append(text)
    return values


def _return_evidence_for_artifacts(artifact_names: Iterable[str], existing: Iterable[str]) -> list[str]:
    names = {str(item) for item in artifact_names if str(item)}
    evidence = [str(item) for item in existing if str(item or "").strip()]
    if "directive_deliverables.json" in names:
        _append_unique(evidence, "conveyor_child_deliverables_built")
    if "technical_documentation.md" in names:
        _append_unique(evidence, "conveyor_child_technical_documentation_built")
    if BUILD_PACKAGE_QUALITY_REQUIRED_ARTIFACTS <= names:
        _append_unique(evidence, BUILD_GRADE_STRUCTURED_EVIDENCE)
    return evidence


def _string_list(value: Any, *, limit: int = 12) -> list[str]:
    if isinstance(value, str):
        return [value] if value.strip() else []
    if not isinstance(value, list):
        return []
    result: list[str] = []
    for item in value[:limit]:
        if isinstance(item, str):
            text = item.strip()
        elif isinstance(item, Mapping):
            text = str(
                item.get("name")
                or item.get("step")
                or item.get("gate")
                or item.get("metric")
                or item.get("expected_file")
                or item.get("fixture_id")
                or ""
            ).strip()
        else:
            text = str(item or "").strip()
        if text and text not in result:
            result.append(text)
    return result


def _derive_prototype_implementation_handoff(packet: Mapping[str, Any]) -> dict[str, Any]:
    artifacts = set(str(item) for item in list(packet.get("artifacts", []) or []) if str(item))
    if "prototype_assembly_plan.json" not in artifacts or "implementation_readiness_review.json" not in artifacts:
        return {}
    assembly = _read_packet_artifact_json(packet, "prototype_assembly_plan.json")
    readiness = _read_packet_artifact_json(packet, "implementation_readiness_review.json")
    fixtures_payload = _read_packet_artifact_json(packet, "validation_fixtures.json")
    interfaces_payload = _read_packet_artifact_json(packet, "interface_specifications.json")
    risk_payload = _read_packet_artifact_json(packet, "risk_controls.json")
    claims_payload = _read_packet_artifact_json(packet, "claim_evidence_register.json")
    assembly_steps = _artifact_rows(assembly, ("assembly_steps", "steps", "rows", "items"))
    if not assembly_steps:
        return {}
    chosen = dict(assembly_steps[0])
    chosen_name = str(chosen.get("name", chosen.get("step_id", "prototype slice")) or "prototype slice")
    build_steps = _string_list(chosen.get("build_sequence"))
    build_steps.extend(item for item in _string_list(readiness.get("build_steps")) if item not in build_steps)
    expected_files = _string_list(chosen.get("named_outputs")) or _string_list(chosen.get("outputs"))
    for row in _artifact_rows(readiness, ("build_steps", "prototype_build_steps", "assembly_steps")):
        expected = str(row.get("expected_file", "") or "").strip()
        if expected and expected not in expected_files:
            expected_files.append(expected)
    for row in _artifact_rows(_read_packet_artifact_json(packet, "bill_of_materials.json"), ("items", "components", "rows")):
        name = str(row.get("name", "") or "").strip()
        if (name.startswith("src/") or name.startswith("tests/") or name.startswith("fixtures/")) and name not in expected_files:
            expected_files.append(name)
    fixtures = [
        {
            "fixture_id": str(row.get("fixture_id", row.get("name", "")) or ""),
            "setup": str(row.get("setup", row.get("purpose", "")) or ""),
            "pass_fail_criteria": str(row.get("pass_fail_criteria", row.get("acceptance_thresholds", "")) or ""),
        }
        for row in _artifact_rows(fixtures_payload, ("fixtures", "validation_fixtures", "rows", "items"))
    ]
    acceptance_tests = _string_list(chosen.get("validation_handoff"))
    for row in _artifact_rows(readiness, ("acceptance_thresholds", "pass_fail_thresholds")):
        metric = str(row.get("metric", row.get("gate", "")) or "").strip()
        threshold = str(row.get("threshold", "") or "").strip()
        label = f"{metric}: {threshold}".strip(": ")
        if label and label not in acceptance_tests:
            acceptance_tests.append(label)
    safety_gates = _artifact_rows(risk_payload, ("controls", "risk_controls", "rows", "items"))
    safety_gates.extend(_artifact_rows(readiness, ("prototype_execution_gates", "execution_gates", "operator_gates")))
    evidence_refs: list[str] = []
    for claim in _artifact_rows(claims_payload, ("claims", "claim_evidence", "rows", "items")):
        for ref in list(claim.get("evidence_refs", []) or []):
            _append_unique(evidence_refs, str(ref))
    interface_names = [
        str(row.get("name", "") or "")
        for row in _artifact_rows(interfaces_payload, ("interfaces", "rows", "items"))
        if str(row.get("name", "") or "").strip()
    ]
    manifest_rows = [
        {
            "artifact_name": name,
            "hash": str(row.get("hash", row.get("sha256", "")) or ""),
            "quality_depth_score": row.get("quality_depth_score", 0),
            "gate_status": str(row.get("gate_status", "") or ""),
            "evidence_refs": list(row.get("evidence_refs", []) or []),
        }
        for name, row in _packet_artifact_manifest(packet).items()
    ]
    return {
        "schema_name": "ConveyorPrototypeImplementationHandoff",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "directive_id": str(packet.get("directive_id", "") or ""),
        "directive_title": str(packet.get("directive_title", "") or ""),
        "chosen_prototype_slice": {
            "name": chosen_name,
            "step_id": str(chosen.get("step_id", "") or ""),
            "module_output": str(chosen.get("module_output", "") or ""),
            "interfaces": interface_names[:8],
        },
        "build_steps": build_steps[:12],
        "fixtures": fixtures[:12],
        "expected_files": expected_files[:16],
        "acceptance_tests": acceptance_tests[:16],
        "safety_gates": safety_gates[:12],
        "evidence_refs": evidence_refs[:16],
        "source_artifact_manifest": manifest_rows,
        "authority_boundary": "review_only_execution_gated_by_operator_approval",
    }


def _title_case_identifier(value: str, fallback: str = "PrototypeRuntime") -> str:
    parts = re.findall(r"[A-Za-z0-9]+", str(value or ""))
    if not parts:
        return fallback
    result = "".join(part[:1].upper() + part[1:] for part in parts)
    return result if result else fallback


def _snake_identifier(value: str, fallback: str = "prototype_runtime") -> str:
    parts = re.findall(r"[A-Za-z0-9]+", str(value or "").lower())
    return "_".join(parts) if parts else fallback


def _handoff_module_names(handoff: Mapping[str, Any]) -> list[str]:
    chosen = dict(handoff.get("chosen_prototype_slice", {}) or {})
    candidates = [
        str(chosen.get("module_output", "") or ""),
        str(chosen.get("name", "") or ""),
        str(handoff.get("directive_title", "") or ""),
    ]
    for interface in list(chosen.get("interfaces", []) or [])[:4]:
        candidates.append(str(interface or ""))
    names: list[str] = []
    for candidate in candidates:
        name = _title_case_identifier(candidate)
        if not name.endswith(("Runtime", "Evaluator", "Writer", "Spec", "Harness", "Adapter", "Manifest")):
            name = f"{name}Runtime"
        if name not in names:
            names.append(name)
    while len(names) < 3:
        fallback = ["PrototypeRuntime", "SafetyGateEvaluator", "EvidenceManifestWriter"][len(names)]
        if fallback not in names:
            names.append(fallback)
    return names[:5]


def _handoff_expected_files(handoff: Mapping[str, Any]) -> list[str]:
    chosen = dict(handoff.get("chosen_prototype_slice", {}) or {})
    module = _snake_identifier(str(chosen.get("module_output", "") or chosen.get("name", "")), "prototype_runtime")
    files = [
        str(item)
        for item in list(handoff.get("expected_files", []) or [])
        if str(item or "").strip()
    ]
    normalized: list[str] = []
    for item in files:
        if item.startswith(("src/", "tests/", "fixtures/")):
            _append_unique(normalized, item)
    _append_unique(normalized, f"src/{module}.py")
    _append_unique(normalized, f"tests/test_{module}.py")
    for fixture in list(handoff.get("fixtures", []) or [])[:3]:
        fixture_id = ""
        if isinstance(fixture, Mapping):
            fixture_id = str(fixture.get("fixture_id", fixture.get("name", "")) or "")
        fixture_name = _snake_identifier(fixture_id, "validation_fixture")
        _append_unique(normalized, f"fixtures/{fixture_name}.json")
    return normalized[:12]


def _compile_handoff_technical_documentation(
    handoff: Mapping[str, Any],
) -> str:
    chosen = dict(handoff.get("chosen_prototype_slice", {}) or {})
    title = str(handoff.get("directive_title", "") or "Conveyor prototype handoff").strip()
    slice_name = str(chosen.get("name", "") or "prototype slice").strip()
    module_names = _handoff_module_names(handoff)
    expected_files = _handoff_expected_files(handoff)
    interfaces = [
        str(item)
        for item in list(chosen.get("interfaces", []) or [])
        if str(item or "").strip()
    ] or ["PrototypeInputSpec", "PrototypeOutputManifest"]
    build_steps = [
        str(item)
        for item in list(handoff.get("build_steps", []) or [])
        if str(item or "").strip()
    ] or ["Prepare the local-only prototype harness", "Run validation fixtures", "Write evidence manifest"]
    fixtures = [
        dict(item)
        for item in list(handoff.get("fixtures", []) or [])
        if isinstance(item, Mapping)
    ]
    acceptance_tests = [
        str(item)
        for item in list(handoff.get("acceptance_tests", []) or [])
        if str(item or "").strip()
    ] or ["python -m unittest discovers the prototype acceptance tests"]
    safety_gates = [
        dict(item) if isinstance(item, Mapping) else {"gate": str(item)}
        for item in list(handoff.get("safety_gates", []) or [])
    ]
    evidence_refs = [
        str(item)
        for item in list(handoff.get("evidence_refs", []) or [])
        if str(item or "").strip()
    ] or ["handoff:source_artifact_manifest"]
    fixture_lines = []
    for fixture in fixtures:
        fixture_id = str(fixture.get("fixture_id", fixture.get("name", "validation-fixture")) or "validation-fixture")
        setup = str(fixture.get("setup", fixture.get("purpose", "")) or "local validation setup")
        criteria = str(
            fixture.get("pass_fail_criteria", fixture.get("acceptance_thresholds", "")) or "fixture must pass"
        )
        fixture_lines.append(f"- fixture-{_snake_identifier(fixture_id)}: {setup}; acceptance threshold: {criteria}.")
    if not fixture_lines:
        fixture_lines = ["- fixture-validation-fixture: local validation setup; acceptance threshold: fixture must pass."]
    gate_lines = []
    for gate in safety_gates:
        gate_text = json.dumps(gate, sort_keys=True)
        gate_lines.append(f"- Go/no-go safety governance gate: {gate_text}.")
    if not gate_lines:
        gate_lines = ["- Go/no-go safety governance gate: execution remains blocked until operator approval."]
    file_lines = [f"- `{path}`" for path in expected_files]
    build_lines = [f"{index}. Build step: {step}." for index, step in enumerate(build_steps, start=1)]
    acceptance_lines = [f"- Acceptance threshold: {test}." for test in acceptance_tests]
    evidence_lines = [f"- Evidence ref: {ref}." for ref in evidence_refs]
    repeated_detail = "\n".join(
        [
            "This implementation sequence is intentionally local-only and review-gated. "
            f"{module_names[0]} owns the prototype assembly path, {module_names[1]} evaluates no-go states, "
            f"and {module_names[2]} writes the evidence manifest before any operator review decision.",
            "The validation strategy ties every build step to validation fixtures, typed interface contracts, "
            "expected files, failure mode reporting, and explicit go/no-go thresholds.",
            "Knowledge gaps remain tracked as source coverage gaps and follow-up experiments; unsupported claims "
            "do not become executable requirements.",
        ]
        * 3
    )
    return "\n\n".join(
        [
            f"# Technical Documentation: {title}",
            f"## Prototype Slice\n{slice_name} is the chosen prototype assembly slice. Named modules: {', '.join(module_names)}.",
            "## Architecture\nSubsystem decomposition assigns responsibility across "
            + ", ".join(module_names)
            + ". The architecture is offline, simulation-only, and operator-review gated.",
            "## Typed Interface Contracts\n"
            + "\n".join(f"- Interface contract `{name}` defines input_schema, output_schema, failure modes, and validation hooks." for name in interfaces),
            "## Dependency Map\nDependencies are limited to local runtime libraries, sealed fixtures, test environment files, and evidence manifests. No network, credential, actuator, clinical, or real-world dependency is granted.",
            "## Expected Files\n" + "\n".join(file_lines),
            "## Prototype Build Sequence\n" + "\n".join(build_lines),
            "## Validation Strategy\n" + "\n".join(fixture_lines),
            "## Acceptance Tests And Thresholds\n" + "\n".join(acceptance_lines),
            "## Safety Governance Gates\n" + "\n".join(gate_lines),
            "## Evidence References\n" + "\n".join(evidence_lines),
            "## Knowledge Gaps\nOpen research questions, source coverage gaps, fixture coverage gaps, and follow-up experiments must stay visible before broadening scope.",
            "## Buildable Delta\n" + repeated_detail,
        ]
    )


def _compile_handoff_documentation_if_needed(
    operator_root: str | Path,
    packet: Mapping[str, Any],
) -> tuple[dict[str, Any], bool]:
    updated = dict(packet)
    handoff = dict(updated.get("implementation_handoff", {}) or {})
    directive_id = str(updated.get("directive_id", "") or "").strip()
    if not handoff or not directive_id:
        return updated, False
    manifest = _write_campaign_manifest(operator_root, directive_id)
    technical = dict(dict(manifest.get("canonical_artifacts", {}) or {}).get("technical_documentation.md", {}) or {})
    failed = {str(item) for item in list(technical.get("failed_quality_gates", []) or [])}
    if not failed.intersection(
        {
            "scaffold_technical_documentation",
            "missing_named_modules",
            "missing_validation_fixtures",
            "missing_handoff_acceptance_thresholds",
            "missing_concrete_build_steps",
            "no_buildable_delta",
        }
    ):
        return updated, False
    canonical_path = _campaign_canonical_root(operator_root, directive_id) / "technical_documentation.md"
    original_manifest = _read_file_manifest(canonical_path)
    compiled_text = _compile_handoff_technical_documentation(handoff)
    draft_path = _campaign_drafts_root(operator_root, directive_id) / "technical_documentation.md"
    draft_path.parent.mkdir(parents=True, exist_ok=True)
    draft_path.write_text(compiled_text, encoding="utf-8")
    compiled_sha = hashlib.sha256(compiled_text.encode("utf-8")).hexdigest()
    metadata = {
        "artifact_name": "technical_documentation.md",
        "source_artifact": "implementation_handoff",
        "return_packet_id": str(updated.get("return_packet_id", "") or ""),
        "original_sha256": str(original_manifest.get("sha256", "") or ""),
        "compiled_sha256": compiled_sha,
        "compiled_at": _utc_now(),
        "authority_boundary": "campaign_canonical_review_artifact_only",
    }
    _append_campaign_ledger(
        operator_root,
        directive_id,
        {
            "event": "technical_documentation_compiled_from_handoff",
            "generated_at": metadata["compiled_at"],
            "directive_id": directive_id,
            "return_packet_id": metadata["return_packet_id"],
            "compiled_documentation": metadata,
        },
    )
    promotion = promote_conveyor_campaign_drafts(operator_root, directive_id=directive_id)
    manifest = dict(promotion.get("manifest", {}) or _write_campaign_manifest(operator_root, directive_id))
    technical = dict(dict(manifest.get("canonical_artifacts", {}) or {}).get("technical_documentation.md", {}) or {})
    if "technical_documentation.md" not in list(promotion.get("promoted_artifacts", []) or []) and not technical:
        return updated, False
    updated["compiled_documentation"] = metadata
    updated["campaign_manifest_ref"] = str(_campaign_manifest_path(operator_root, directive_id))
    updated["artifact_manifest"] = {
        name: _return_manifest_entry(name, dict(row or {}))
        for name, row in dict(manifest.get("canonical_artifacts", {}) or {}).items()
        if name in set(updated.get("artifacts", []) or []) or name in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER
    }
    updated["quality_depth_score"] = float(manifest.get("quality_depth_score", 0.0) or 0.0)
    return updated, True


def _attach_latest_child_workspace_artifacts(
    operator_root: str | Path,
    packet: Mapping[str, Any],
    *,
    child: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], bool]:
    updated = dict(packet)
    existing_artifacts = [
        str(item)
        for item in list(updated.get("artifacts", []) or [])
        if str(item or "").strip()
    ]
    child_record = dict(child or {})
    if not child_record:
        child_id = str(updated.get("child_run_id", "") or "").strip()
        child_record = _read_json(_child_path(operator_root, child_id)) if child_id else {}
    artifact_names, manifest = _latest_child_workspace_artifacts(child_record)
    if not artifact_names:
        return updated, False
    merged = [
        artifact_name
        for artifact_name in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER
        if artifact_name in set(existing_artifacts) or artifact_name in set(artifact_names)
    ]
    if not merged:
        return updated, False
    evidence = [
        str(item)
        for item in list(updated.get("verification_evidence", []) or [])
        if str(item or "").strip()
    ]
    if "conveyor_child_workspace_artifacts_attached" not in evidence:
        evidence.append("conveyor_child_workspace_artifacts_attached")
    updated["artifacts"] = merged
    updated["artifact_manifest"] = {
        name: _return_manifest_entry(name, row)
        for name, row in manifest.items()
    }
    updated["artifact_source"] = "child_workspace_latest"
    updated["workspace_artifact_attached"] = True
    updated["verification_evidence"] = _return_evidence_for_artifacts(merged, evidence)
    handoff = _derive_prototype_implementation_handoff(updated)
    if handoff:
        updated["implementation_handoff"] = handoff
    return updated, True


def _attach_latest_campaign_canonical_artifacts(
    operator_root: str | Path,
    packet: Mapping[str, Any],
) -> tuple[dict[str, Any], bool]:
    updated = dict(packet)
    directive_id = str(updated.get("directive_id", "") or "").strip()
    if not directive_id:
        return updated, False
    manifest_path = _campaign_manifest_path(operator_root, directive_id)
    canonical_root = _campaign_canonical_root(operator_root, directive_id)
    if not manifest_path.exists() and not canonical_root.exists():
        return updated, False
    campaign_manifest = _write_campaign_manifest(operator_root, directive_id)
    canonical_artifacts = dict(campaign_manifest.get("canonical_artifacts", {}) or {})
    artifact_names = [
        artifact
        for artifact in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER
        if artifact in canonical_artifacts
    ]
    if not artifact_names:
        return updated, False
    updated["artifacts"] = artifact_names
    updated["artifact_manifest"] = {
        name: _return_manifest_entry(name, dict(canonical_artifacts.get(name, {}) or {}))
        for name in artifact_names
    }
    updated["artifact_source"] = "campaign_canonical_latest"
    updated["workspace_artifact_attached"] = False
    updated["campaign_manifest_ref"] = str(manifest_path)
    updated["artifact_presence_score"] = float(campaign_manifest.get("artifact_presence_score", 0.0) or 0.0)
    updated["quality_depth_score"] = float(campaign_manifest.get("quality_depth_score", 0.0) or 0.0)
    evidence = [
        str(item)
        for item in list(updated.get("verification_evidence", []) or [])
        if str(item or "").strip()
    ]
    _append_unique(evidence, "conveyor_child_campaign_artifacts_attached")
    updated["verification_evidence"] = _return_evidence_for_artifacts(artifact_names, evidence)
    handoff = _derive_prototype_implementation_handoff(updated)
    if handoff:
        updated["implementation_handoff"] = handoff
    return updated, True


def _attach_latest_campaign_draft_artifacts(
    operator_root: str | Path,
    packet: Mapping[str, Any],
) -> tuple[dict[str, Any], bool]:
    updated = dict(packet)
    directive_id = str(updated.get("directive_id", "") or "").strip()
    if not directive_id:
        return updated, False
    draft_root = _campaign_drafts_root(operator_root, directive_id)
    if not draft_root.exists():
        return updated, False
    artifact_order = list(BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER) + ["device_capability_manifest.json"]
    artifact_manifest = {
        artifact: _read_file_manifest(draft_root / artifact)
        for artifact in artifact_order
        if (draft_root / artifact).exists() and (draft_root / artifact).is_file()
    }
    artifact_names = [artifact for artifact in artifact_order if artifact in artifact_manifest]
    if not artifact_names:
        return updated, False
    updated["artifacts"] = artifact_names
    updated["artifact_manifest"] = {
        name: _return_manifest_entry(name, dict(artifact_manifest.get(name, {}) or {}))
        for name in artifact_names
    }
    updated["artifact_source"] = "campaign_draft_latest"
    updated["workspace_artifact_attached"] = False
    updated["campaign_draft_ref"] = str(draft_root)
    evidence = [
        str(item)
        for item in list(updated.get("verification_evidence", []) or [])
        if str(item or "").strip()
    ]
    _append_unique(evidence, "conveyor_child_campaign_draft_artifacts_attached")
    updated["verification_evidence"] = _return_evidence_for_artifacts(artifact_names, evidence)
    handoff = _derive_prototype_implementation_handoff(updated)
    if handoff:
        updated["implementation_handoff"] = handoff
    return updated, True


def _return_hydration_candidate_score(
    operator_root: str | Path,
    packet: Mapping[str, Any],
    *,
    directive: Mapping[str, Any],
    source_rank: int,
) -> tuple[int, int, float, int, int]:
    directive_id = str(packet.get("directive_id", "") or directive.get("directive_id", "") or "")
    artifacts = {str(item) for item in list(packet.get("artifacts", []) or []) if str(item).strip()}
    required_count = len(set(BUILD_PACKAGE_QUALITY_REQUIRED_ARTIFACTS) & artifacts)
    manifest = _packet_artifact_manifest(packet)
    quality_scores = []
    for row in manifest.values():
        try:
            quality_scores.append(float(row.get("quality_depth_score", 0.0) or 0.0))
        except (TypeError, ValueError):
            continue
    quality_score = sum(quality_scores) / max(1, len(quality_scores))
    hardware = _assess_hardware_build_packet(
        operator_root,
        directive_id,
        directive=directive,
        packet=packet,
    )
    hardware_required = bool(hardware.get("required", False))
    hardware_ready = not hardware_required or bool(hardware.get("hardware_build_packet_ready", False))
    field_gap_count = sum(
        len(list(rows or []))
        for rows in dict(hardware.get("field_gaps_by_artifact", {}) or {}).values()
    )
    return (
        1 if hardware_ready else 0,
        0 if field_gap_count else 1,
        quality_score,
        required_count,
        source_rank,
    )


def _hydrate_pending_return_workspace_artifacts(
    operator_root: str | Path,
    packet: Mapping[str, Any],
) -> tuple[dict[str, Any], bool]:
    if str(packet.get("review_state", "") or "") != "pending_operator_review":
        return dict(packet), False
    directive_id = str(packet.get("directive_id", "") or "").strip()
    directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    if not directive:
        return dict(packet), False
    candidates: list[tuple[int, dict[str, Any]]] = [(0, dict(packet))]
    workspace_packet, workspace_hydrated = _attach_latest_child_workspace_artifacts(operator_root, packet)
    if workspace_hydrated:
        candidates.append((1, workspace_packet))
    canonical_packet, canonical_hydrated = _attach_latest_campaign_canonical_artifacts(operator_root, packet)
    if canonical_hydrated:
        candidates.append((2, canonical_packet))
    draft_packet, draft_hydrated = _attach_latest_campaign_draft_artifacts(operator_root, packet)
    if draft_hydrated:
        candidates.append((3, draft_packet))
    candidates = [
        (rank, candidate)
        for rank, candidate in candidates
        if list(candidate.get("artifacts", []) or [])
    ]
    if candidates:
        selected_rank, selected = max(
            candidates,
            key=lambda item: _return_hydration_candidate_score(
                operator_root,
                item[1],
                directive=directive,
                source_rank=item[0],
            ),
        )
        if selected != dict(packet):
            return selected, True
        if selected_rank != 0:
            return selected, True
        return dict(packet), False
    risks = {str(item) for item in list(packet.get("risks", []) or [])}
    summary = str(packet.get("outcome_summary", "") or "").lower()
    if "resident_worker_stalled" not in risks and "resident directive worker stalled" not in summary:
        return dict(packet), False
    updated, hydrated = _attach_latest_child_workspace_artifacts(operator_root, packet)
    if hydrated:
        return updated, True
    return _attach_latest_campaign_canonical_artifacts(operator_root, packet)


def _artifact_rows(payload: Mapping[str, Any], keys: Iterable[str]) -> list[dict[str, Any]]:
    for key in keys:
        value = payload.get(key)
        if isinstance(value, list):
            return [dict(item) for item in value if isinstance(item, Mapping)]
    return []


def _build_grade_structured_assessment(
    packet: Mapping[str, Any],
    *,
    artifact_text: str,
) -> dict[str, Any]:
    subsystem_rows = _artifact_rows(
        _read_packet_artifact_json(packet, "subsystem_matrix.json"),
        ("subsystems", "rows"),
    )
    interface_rows = _artifact_rows(
        _read_packet_artifact_json(packet, "interface_specifications.json"),
        ("interfaces", "rows"),
    )
    dependency_rows = _artifact_rows(
        _read_packet_artifact_json(packet, "dependency_matrix.json"),
        ("dependencies", "rows"),
    )
    validation_rows = _artifact_rows(
        _read_packet_artifact_json(packet, "validation_protocols.json"),
        ("protocols", "validations", "rows"),
    )
    milestone_rows = _artifact_rows(
        _read_packet_artifact_json(packet, "prototype_milestones.json"),
        ("milestones", "rows"),
    )
    claims = _artifact_rows(
        _read_packet_artifact_json(packet, "claim_evidence_register.json"),
        ("claims", "rows"),
    )
    novelty_items = _artifact_rows(
        _read_packet_artifact_json(packet, "novelty_delta.json"),
        ("novel_items", "novelty_items", "rows"),
    )
    if not novelty_items:
        novelty_payload = _read_packet_artifact_json(packet, "novelty_delta.json")
        raw_items = novelty_payload.get("novel_items") or novelty_payload.get("novelty_items") or []
        novelty_items = [{"item": str(item)} for item in raw_items if str(item).strip()] if isinstance(raw_items, list) else []
    directive_specific_row_count = sum(
        len(rows)
        for rows in (subsystem_rows, interface_rows, dependency_rows, validation_rows, milestone_rows)
    )
    supported_claim_count = 0
    unsupported_claim_count = 0
    high_risk_claim_count = 0
    for claim in claims:
        evidence_refs = [str(item).strip() for item in list(claim.get("evidence_refs", []) or []) if str(item).strip()]
        confidence = str(claim.get("confidence", "") or "").strip().lower()
        risk = str(claim.get("risk_level", "") or claim.get("risk", "") or "").strip().lower()
        if evidence_refs and confidence not in {"unsupported", "missing"}:
            supported_claim_count += 1
        else:
            unsupported_claim_count += 1
        if risk in {"high", "critical", "clinical", "invasive"}:
            high_risk_claim_count += 1
    generic_markers = [
        "break the directive into bounded subsystems",
        "keep kernel state, child workspace, checkout bundle",
        "sequence 1: produce non-executing architecture",
        "domain research packs are required before treating",
    ]
    lowered = artifact_text.lower()
    generic_template_content = sum(1 for marker in generic_markers if marker in lowered) >= 2
    return {
        "schema_name": "ConveyorBuildGradeArtifactAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "subsystem_row_count": len(subsystem_rows),
        "interface_row_count": len(interface_rows),
        "dependency_row_count": len(dependency_rows),
        "validation_row_count": len(validation_rows),
        "milestone_row_count": len(milestone_rows),
        "directive_specific_row_count": directive_specific_row_count,
        "claim_count": len(claims),
        "supported_claim_count": supported_claim_count,
        "unsupported_claim_count": unsupported_claim_count,
        "high_risk_claim_count": high_risk_claim_count,
        "novelty_count": len(novelty_items),
        "generic_template_content": generic_template_content,
        "structured_artifact_ready": (
            len(subsystem_rows) >= 3
            and len(interface_rows) >= 2
            and len(dependency_rows) >= 2
            and len(validation_rows) >= 2
            and len(milestone_rows) >= 2
            and len(claims) >= 2
            and supported_claim_count >= 2
            and len(novelty_items) >= 2
            and not generic_template_content
            and unsupported_claim_count == 0
        ),
    }


def _build_grade_handoff_assessment(packet: Mapping[str, Any]) -> dict[str, Any]:
    handoff = dict(packet.get("implementation_handoff", {}) or {})
    chosen = dict(handoff.get("chosen_prototype_slice", {}) or {})
    build_steps = _string_list(handoff.get("build_steps"), limit=20)
    expected_files = _handoff_expected_files(handoff) if handoff else []
    fixtures = [
        dict(item)
        for item in list(handoff.get("fixtures", []) or [])
        if isinstance(item, Mapping)
        and str(item.get("fixture_id", item.get("name", "")) or "").strip()
    ]
    acceptance_tests = _string_list(handoff.get("acceptance_tests"), limit=20)
    evidence_refs = _string_list(handoff.get("evidence_refs"), limit=20)
    safety_gates = [
        dict(item) if isinstance(item, Mapping) else {"gate": str(item)}
        for item in list(handoff.get("safety_gates", []) or [])
        if str(item or "").strip()
    ]
    interface_names = [
        str(item)
        for item in list(chosen.get("interfaces", []) or [])
        if str(item or "").strip()
    ]
    safety_gate_present = any(
        "execution_gated_by_operator_approval" in json.dumps(row, sort_keys=True)
        or "operator_approval" in json.dumps(row, sort_keys=True).lower()
        or "no-go" in json.dumps(row, sort_keys=True).lower()
        for row in safety_gates
    )
    gate_results = {
        "subsystem_decomposition": bool(str(chosen.get("name", "") or "").strip() and str(chosen.get("module_output", "") or "").strip()),
        "interface_contracts": len(interface_names) >= 1,
        "dependency_map": bool(expected_files),
        "prototype_build_sequence": len(build_steps) >= 2,
        "validation_strategy": bool(fixtures) and bool(acceptance_tests),
        "safety_governance_gates": safety_gate_present,
        "knowledge_gap_register": bool(evidence_refs),
    }
    satisfied = sorted(gate for gate, passed in gate_results.items() if passed)
    missing = sorted(gate for gate, passed in gate_results.items() if not passed)
    return {
        "schema_name": "ConveyorBuildGradeHandoffAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "handoff_present": bool(handoff),
        "handoff_ready": bool(handoff) and not missing,
        "satisfied_handoff_gates": satisfied,
        "missing_handoff_gates": missing,
        "handoff_gate_results": gate_results,
        "build_step_count": len(build_steps),
        "fixture_count": len(fixtures),
        "expected_file_count": len(expected_files),
        "acceptance_test_count": len(acceptance_tests),
        "evidence_ref_count": len(evidence_refs),
        "safety_gate_count": len(safety_gates),
    }


def _campaign_depth_assessment(
    packet: Mapping[str, Any],
    *,
    missing_artifacts: list[str],
    missing_evidence: list[str],
) -> dict[str, Any]:
    artifact_text = _read_packet_artifact_text(packet)
    combined = "\n".join(
        [
            str(packet.get("outcome_summary", "") or ""),
            str(packet.get("requested_follow_up", "") or ""),
            artifact_text,
        ]
    ).lower()
    gate_results: dict[str, bool] = {}
    for gate, phrases in BUILD_READINESS_GATES.items():
        gate_results[gate] = any(phrase in combined for phrase in phrases)
    build_grade_assessment = _build_grade_structured_assessment(packet, artifact_text=artifact_text)
    handoff_assessment = _build_grade_handoff_assessment(packet)
    for gate, passed in dict(handoff_assessment.get("handoff_gate_results", {}) or {}).items():
        if passed:
            gate_results[gate] = True
    satisfied = sorted(gate for gate, passed in gate_results.items() if passed)
    missing_gates = sorted(gate for gate, passed in gate_results.items() if not passed)
    satisfied_count = len(satisfied)
    handoff_present = bool(handoff_assessment.get("handoff_present", False))
    handoff_ready = bool(handoff_assessment.get("handoff_ready", False))
    structured_ready = bool(build_grade_assessment.get("structured_artifact_ready", False))
    if (
        missing_artifacts
        or missing_evidence
        or satisfied_count <= 1
        or bool(build_grade_assessment.get("generic_template_content", False))
    ):
        readiness_level = "scaffold"
    elif satisfied_count <= 3:
        readiness_level = "architecture_draft"
    elif satisfied_count <= 5:
        readiness_level = "technical_spec"
    elif missing_gates or not structured_ready or (handoff_present and not handoff_ready):
        readiness_level = "prototype_plan"
    else:
        readiness_level = "build_ready_review"
    return {
        "schema_name": "ConveyorDirectiveCampaignState",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "readiness_level": readiness_level,
        "readiness_levels": list(CAMPAIGN_READINESS_LEVELS),
        "satisfied_build_readiness_gates": satisfied,
        "missing_build_readiness_gates": missing_gates,
        "build_readiness_gate_results": gate_results,
        "artifact_content_available": bool(artifact_text.strip()),
        "artifact_content_sample_chars": min(len(artifact_text), 1200),
        "build_grade_artifact_assessment": build_grade_assessment,
        "build_grade_handoff_assessment": handoff_assessment,
        "prototype_ready": (
            readiness_level == "build_ready_review"
            and not missing_artifacts
            and not missing_evidence
            and structured_ready
            and (handoff_ready if handoff_present else True)
        ),
    }


def _trusted_source_refs_for_directive(
    operator_root: str | Path,
    directive: Mapping[str, Any],
) -> list[dict[str, Any]]:
    metadata = dict(directive.get("metadata", {}) or {})
    directive_queue_id = str(metadata.get("directive_queue_id", "") or "").strip()
    allowed_source_ids = {
        str(item).strip()
        for item in list(metadata.get("allowed_source_ids", []) or [])
        if str(item).strip()
    }
    required_tags = {
        str(item).strip()
        for item in list(metadata.get("required_capability_tags", []) or [])
        if str(item).strip()
    }
    bindings = load_trusted_source_bindings_or_default(root=operator_root)
    secrets = load_trusted_source_secrets_or_default(operator_root)
    _, _, availability = validate_trusted_source_bindings(bindings, secrets_payload=secrets)
    refs: list[dict[str, Any]] = []
    for row in list(availability.get("sources", []) or []):
        source_id = str(row.get("source_id", "") or "").strip()
        if not source_id or not bool(row.get("enabled", False)):
            continue
        row_queue_ids = {
            str(item).strip()
            for item in list(row.get("allowed_directive_queue_ids", []) or [])
            if str(item).strip()
        }
        row_tags = {
            str(item).strip()
            for item in list(row.get("capability_tags", []) or [])
            if str(item).strip()
        }
        if allowed_source_ids and source_id not in allowed_source_ids:
            continue
        if directive_queue_id and row_queue_ids and directive_queue_id not in row_queue_ids:
            continue
        if required_tags and not required_tags.issubset(row_tags):
            continue
        refs.append(
            {
                "source_id": source_id,
                "source_kind": str(row.get("source_kind", "") or ""),
                "ready_for_launch": bool(row.get("ready_for_launch", False)),
                "availability_class": str(row.get("availability_class", "") or ""),
                "availability_reason": str(row.get("availability_reason", "") or ""),
                "endpoint_base": str(row.get("endpoint_base", "") or ""),
                "path_hint": str(row.get("path_hint", "") or ""),
                "capability_tags": sorted(row_tags),
                "allowed_directive_queue_ids": sorted(row_queue_ids),
                "max_requests_per_directive": int(row.get("max_requests_per_directive", 0) or 0),
                "requires_operator_review": bool(row.get("requires_operator_review", False)),
                "grants_execution_authority": False,
                "kernel_mediated_only": True,
            }
        )
    refs.sort(key=lambda item: str(item.get("source_id", "")))
    return refs


def _autonomy_emergency_stop_active(operator_root: str | Path) -> bool:
    try:
        return bool(autonomy_status(operator_root).get("emergency_stop", False))
    except Exception:
        return False


def _latest_unseen_failed_child(operator_root: str | Path, scheduler: Mapping[str, Any]) -> dict[str, Any]:
    seen_ids = {
        str(item).strip()
        for item in list(scheduler.get("latest_failure_child_ids", []) or [])
        if str(item).strip()
    }
    latest_seen = str(scheduler.get("latest_failure_child_id", "") or "").strip()
    if latest_seen:
        seen_ids.add(latest_seen)
    failed = [
        child
        for child in _load_items(_children_root(operator_root))
        if str(child.get("state", "") or "") == "failed"
        and str(child.get("child_run_id", "") or "") not in seen_ids
    ]
    failed.sort(key=lambda row: str(row.get("updated_at", "")), reverse=True)
    return failed[0] if failed else {}


def _submitted_directive_count_for_concurrency(operator_root: str | Path) -> int:
    terminal_states = {"accepted", "rejected", "split"}
    return len(
        {
            str(row.get("directive_id", "") or "").strip()
            for row in _load_items(_directives_root(operator_root))
            if str(row.get("directive_id", "") or "").strip()
            and str(row.get("state", "") or "").strip() not in terminal_states
        }
    )


def _task_manager_max_active_cap(scheduler: Mapping[str, Any], *, max_concurrency: int) -> int:
    try:
        configured = int(scheduler.get("task_manager_max_active_children", max_concurrency) or max_concurrency)
    except (TypeError, ValueError):
        configured = max_concurrency
    try:
        env_cap = int(os.environ.get("NOVALI_TASK_MANAGER_MAX_ACTIVE_CHILDREN", str(configured)) or configured)
    except ValueError:
        env_cap = configured
    return max(1, min(max_concurrency, max(1, configured), max(1, env_cap)))


def _dynamic_scheduler_target_for_submitted_directives(
    operator_root: str | Path,
    scheduler: Mapping[str, Any],
    *,
    min_concurrency: int,
    max_concurrency: int,
) -> tuple[int, dict[str, Any]]:
    submitted_count = _submitted_directive_count_for_concurrency(operator_root)
    task_manager_cap = _task_manager_max_active_cap(scheduler, max_concurrency=max_concurrency)
    effective_cap = max(1, min(max_concurrency, task_manager_cap))
    desired = submitted_count if submitted_count > 0 else min_concurrency
    effective_target = min(effective_cap, max(min_concurrency, desired))
    return effective_target, {
        "dynamic_concurrency_policy": "submitted_directive_count",
        "dynamic_concurrency_submitted_directive_count": submitted_count,
        "dynamic_concurrency_effective_target": effective_target,
        "dynamic_concurrency_max_cap": effective_cap,
        "dynamic_concurrency_task_manager_max_active_children": task_manager_cap,
    }


def _adapt_scheduler(operator_root: str | Path, scheduler: Mapping[str, Any]) -> dict[str, Any]:
    payload = dict(scheduler)
    min_concurrency = max(1, int(payload.get("min_concurrency", 1) or 1))
    max_concurrency = max(min_concurrency, int(payload.get("max_concurrency", min_concurrency) or min_concurrency))
    target = min(max(int(payload.get("target_concurrency", min_concurrency) or min_concurrency), min_concurrency), max_concurrency)
    dynamic_target, dynamic_diagnostics = _dynamic_scheduler_target_for_submitted_directives(
        operator_root,
        payload,
        min_concurrency=min_concurrency,
        max_concurrency=max_concurrency,
    )
    failure = _latest_unseen_failed_child(operator_root, payload)
    if failure:
        child_id = str(failure.get("child_run_id", "") or "")
        failed_ids = [
            str(child.get("child_run_id", "") or "")
            for child in _load_items(_children_root(operator_root))
            if str(child.get("state", "") or "") == "failed"
            and str(child.get("child_run_id", "") or "")
        ]
        failure_floor = max(min_concurrency, target - 1)
        payload["target_concurrency"] = max(failure_floor, dynamic_target)
        payload["latest_failure_child_id"] = child_id
        payload["latest_failure_child_ids"] = sorted(set(failed_ids))[-50:]
        payload.update(dynamic_diagnostics)
        payload["last_adjustment_reason"] = (
            "submitted_directive_count"
            if payload["target_concurrency"] != failure_floor
            else "recent_child_failure"
        )
        _append_ledger(
            operator_root,
            "scheduler_events",
            {
                "event": "target_concurrency_adapted",
                "generated_at": _utc_now(),
                "child_run_id": child_id,
                "previous_target_concurrency": target,
                "target_concurrency": payload["target_concurrency"],
                "reason": payload["last_adjustment_reason"],
                **dynamic_diagnostics,
            },
        )
        return _save_scheduler(operator_root, payload)
    if target != dynamic_target:
        payload["target_concurrency"] = dynamic_target
        payload.update(dynamic_diagnostics)
        payload["last_adjustment_reason"] = "submitted_directive_count"
        _append_ledger(
            operator_root,
            "scheduler_events",
            {
                "event": "target_concurrency_adapted",
                "generated_at": _utc_now(),
                "previous_target_concurrency": target,
                "target_concurrency": payload["target_concurrency"],
                "reason": "submitted_directive_count",
                **dynamic_diagnostics,
            },
        )
        return _save_scheduler(operator_root, payload)
    payload["target_concurrency"] = dynamic_target
    payload.update(dynamic_diagnostics)
    payload.setdefault("last_adjustment_reason", "steady")
    return _save_scheduler(operator_root, payload)


def _build_checkout_bundle(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    directive: Mapping[str, Any],
    child_run_id: str,
    child_execution_mode: str = "oneshot_return",
    inbox_path: str | Path = "",
    progress_path: str | Path = "",
    scheduler: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    checkout_id = _record_id("checkout", child_run_id, str(directive.get("directive_id", "")))
    reusable_refs: list[dict[str, Any]] = []
    try:
        from .librarian import latest_reusable_librarian_pack

        reusable = latest_reusable_librarian_pack(
            state_root,
            directive_ref=str(directive.get("directive_id", "") or ""),
        )
        if bool(reusable.get("reusable", False)):
            reusable_refs.append(
                {
                    "pack_id": str(reusable.get("pack_id", "") or ""),
                    "pack_kind": str(reusable.get("pack_kind", "") or ""),
                    "pack_path": str(reusable.get("pack_path", "") or ""),
                    "grants_execution_authority": False,
                }
            )
    except Exception as exc:
        reusable_refs.append(
            {
                "pack_id": "",
                "pack_kind": "",
                "pack_path": "",
                "grants_execution_authority": False,
                "checkout_note": f"librarian_lookup_failed:{type(exc).__name__}",
            }
        )
    metadata = dict(directive.get("metadata", {}) or {})
    support_request_refs = _support_request_refs_for_directive(
        operator_root,
        str(directive.get("directive_id", "") or ""),
    )
    directive_id = str(directive.get("directive_id", "") or "")
    campaign_manifest = _ensure_campaign_workspace(operator_root, directive_id)
    campaign_workspace = {
        "directive_id": directive_id,
        "draft_path": "/novali/campaign_drafts",
        "canonical_path": "/novali/campaign_canonical",
        "host_draft_path": str(_campaign_drafts_root(operator_root, directive_id)),
        "host_canonical_path": str(_campaign_canonical_root(operator_root, directive_id)),
        "manifest_path": str(_campaign_manifest_path(operator_root, directive_id)),
        "draft_mount_mode": "read_write",
        "canonical_mount_mode": "read_only",
        "canonical_artifacts": dict(campaign_manifest.get("canonical_artifacts", {}) or {}),
        "prototype_target": str(campaign_manifest.get("prototype_target", "") or "build_package"),
        "safety_boundary": str(
            campaign_manifest.get("safety_boundary", "")
            or "full_specs_allowed_execution_gated_by_operator_approval"
        ),
    }
    seen_pack_ids = {str(item.get("pack_id", "") or "") for item in reusable_refs if item.get("pack_id")}
    for support_ref in support_request_refs:
        pack_id = str(support_ref.get("pack_id", "") or "")
        if not pack_id or pack_id in seen_pack_ids:
            continue
        reusable_refs.append(
            {
                "pack_id": pack_id,
                "pack_kind": str(support_ref.get("pack_kind", "") or "knowledge_pack"),
                "pack_family": str(support_ref.get("pack_family", "") or ""),
                "pack_path": str(support_ref.get("pack_path", "") or ""),
                "version_ref": str(support_ref.get("version_ref", "") or ""),
                "source_kind": str(support_ref.get("source_kind", "") or "conveyor_support_request"),
                "support_request_id": str(support_ref.get("support_request_id", "") or ""),
                "capability": str(support_ref.get("capability", "") or ""),
                "support_capability": str(support_ref.get("capability", "") or ""),
                "requested_pack_family": str(support_ref.get("requested_pack_family", "") or ""),
                "requested_tags": list(support_ref.get("requested_tags", []) or []),
                "original_support_pack_path": str(support_ref.get("original_support_pack_path", "") or ""),
                "durable_support_pack_path": str(support_ref.get("durable_support_pack_path", "") or ""),
                "support_pack_archive_path": str(support_ref.get("support_pack_archive_path", "") or ""),
                "durable_support_pack_ref": str(support_ref.get("durable_support_pack_ref", "") or ""),
                "support_pack_archive_state": str(support_ref.get("support_pack_archive_state", "") or ""),
                "support_pack_repair_state": str(support_ref.get("support_pack_repair_state", "") or ""),
                "grants_execution_authority": False,
            }
        )
        seen_pack_ids.add(pack_id)
    role_adapter = _latest_role_specific_research_adapter(operator_root)
    checkout_target_artifact = str(
        metadata.get("initial_work_order_target_artifact", "")
        or metadata.get("continuous_campaign_latest_target_artifact", "")
        or ""
    )
    checkout_initial_recovered = bool(
        checkout_target_artifact
        and not str(metadata.get("initial_work_order_target_artifact", "") or "").strip()
        and str(metadata.get("continuous_campaign_latest_target_artifact", "") or "").strip()
    )
    reusable_refs, support_rank_summary, available_support_pack_ids = _rank_and_cap_support_refs(
        reusable_refs,
        state_root=state_root,
        directive_id=directive_id,
        target_artifact=checkout_target_artifact,
        adapter=role_adapter,
    )
    support_checkout = _materialize_child_support_pack_checkout(
        operator_root,
        state_root=state_root,
        child_run_id=child_run_id,
        pack_refs=reusable_refs,
        target_artifact=checkout_target_artifact,
    )
    skipped_non_consumable = [
        {
            "pack_id": str(item.get("pack_id", "") or ""),
            "support_pack_consumability_state": str(item.get("support_pack_consumability_state", "") or ""),
            "non_consumable_support_reasons": list(item.get("non_consumable_support_reasons", []) or []),
            "source": "support_rank_summary",
            "grants_execution_authority": False,
        }
        for item in support_rank_summary
        if str(item.get("pack_id", "") or "")
        and int(item.get("consumable_support_row_count", 0) or 0) <= 0
    ]
    if skipped_non_consumable:
        manifest = dict(support_checkout.get("support_pack_manifest", {}) or {})
        existing_non_consumable = list(manifest.get("non_consumable_packs", []) or [])
        seen_non_consumable = {str(item.get("pack_id", "") or "") for item in existing_non_consumable if isinstance(item, Mapping)}
        for item in skipped_non_consumable:
            if str(item.get("pack_id", "") or "") not in seen_non_consumable:
                existing_non_consumable.append(item)
        manifest["non_consumable_packs"] = existing_non_consumable
        manifest["support_pack_non_consumable_count"] = len(existing_non_consumable)
        manifest["support_pack_consumable_count"] = int(manifest.get("pack_count", 0) or 0)
        support_checkout["support_pack_manifest"] = manifest
        manifest_path = Path(str(support_checkout.get("host_support_pack_checkout_path", "") or "")) / "manifest.json"
        if str(support_checkout.get("host_support_pack_checkout_path", "") or ""):
            _write_json(manifest_path, manifest)
    smoke_sleep_seconds = 0.0
    try:
        smoke_sleep_seconds = max(0.0, min(float(metadata.get("smoke_sleep_seconds", 0) or 0), 900.0))
    except (TypeError, ValueError):
        smoke_sleep_seconds = 0.0
    resident_cycle_sleep_seconds = 30
    if str(child_execution_mode or "") == "resident_campaign":
        campaign_policy = _continuous_campaign_policy(dict(scheduler or _load_scheduler(operator_root)))
        try:
            resident_cycle_sleep_seconds = max(
                30,
                min(int(campaign_policy.get("resident_cycle_sleep_seconds", 600) or 600), 1800),
            )
        except (TypeError, ValueError):
            resident_cycle_sleep_seconds = int(DEFAULT_CONTINUOUS_CAMPAIGN_POLICY["resident_cycle_sleep_seconds"])
    resident_first_cycle_sleep_seconds = resident_cycle_sleep_seconds
    latest_action = str(metadata.get("continuous_campaign_latest_action", "") or "").strip()
    latest_state = str(metadata.get("continuous_campaign_latest_state", "") or "").strip()
    if str(child_execution_mode or "") == "resident_campaign" and (
        latest_action == "operator_requeue" or latest_state == "context_reset"
    ):
        resident_first_cycle_sleep_seconds = 60
    previous_return_packet_id = str(directive.get("latest_return_packet_id", "") or "")
    previous_artifacts: list[str] = []
    if previous_return_packet_id:
        previous_packet = _read_json(_return_path(operator_root, previous_return_packet_id))
        previous_artifacts = [str(item) for item in list(previous_packet.get("artifacts", []) or [])]
    from .directive_candidates import delivery as child_revision_delivery
    reviewed_child_revisions = child_revision_delivery(Path(operator_root), str(directive.get('directive_id', '')))
    payload = {
        "schema_name": CHECKOUT_SCHEMA_NAME,
        "schema_version": CHECKOUT_SCHEMA_VERSION,
        "checkout_id": checkout_id,
        "child_run_id": child_run_id,
        "directive_id": str(directive.get("directive_id", "") or ""),
        "directive_text": str(directive.get("directive_text", "") or ""),
        "child_execution_mode": str(child_execution_mode or "oneshot_return"),
        "inbox_path": str(inbox_path or ""),
        "progress_path": str(progress_path or ""),
        "return_policy": {
            "operator_review_gate": (
                "review_worthy_milestone"
                if str(child_execution_mode or "") == "resident_campaign"
                else "child_exit_return_packet"
            ),
            "progress_channel": "progress_latest.json",
            "final_return_trigger": "kernel_inbox_request_or_review_worthy_blocker",
        },
        "operator_feedback": str(directive.get("operator_feedback", "") or ""),
        "operator_clarifications": [
            dict(item)
            for item in list(directive.get("operator_clarifications", []) or [])
            if isinstance(item, Mapping)
        ],
        "build_grade_contract": {
            "required_artifacts": sorted(BUILD_GRADE_ALL_REQUIRED_ARTIFACTS),
            "required_evidence": sorted(BUILD_GRADE_REQUIRED_EVIDENCE | {BUILD_GRADE_STRUCTURED_EVIDENCE}),
            "minimum_directive_specific_rows": 11,
            "minimum_supported_claims": 2,
            "minimum_novelty_items": 2,
            "requires_operator_clarification_resolution": True,
        },
        "requeue_count": int(directive.get("requeue_count", 0) or 0),
        "previous_return_packet_id": previous_return_packet_id,
        "previous_artifacts": previous_artifacts,
        "reviewed_child_artifact_revisions": reviewed_child_revisions,
        "generated_at": _utc_now(),
        "immutable": True,
        "network_policy": "deny_all",
        "write_authority": "isolated_workspace_only",
        "smoke_sleep_seconds": smoke_sleep_seconds,
        "librarian_pack_refs": reusable_refs,
        "support_pack_rank_summary": support_rank_summary,
        "omitted_support_pack_ref_count": max(0, len(available_support_pack_ids) - len(reusable_refs)),
        "available_support_pack_ids": available_support_pack_ids,
        "support_request_refs": support_request_refs,
        "trusted_source_refs": _trusted_source_refs_for_directive(operator_root, directive),
        "child_compute_mode": CHILD_COMPUTE_DEFAULT_MODE
        if str(child_execution_mode or "") == "resident_campaign"
        else "single_pass",
        "child_compute_budget_seconds": CHILD_COMPUTE_DEFAULT_BUDGET_SECONDS,
        "child_compute_max_passes": CHILD_COMPUTE_DEFAULT_MAX_PASSES,
        "child_compute_sleep_when_blocked": True,
        "support_pack_mount_path": "/novali/support_packs",
        "host_support_pack_checkout_path": str(support_checkout.get("host_support_pack_checkout_path", "") or ""),
        "support_pack_manifest": dict(support_checkout.get("support_pack_manifest", {}) or {}),
        "support_pack_bytes": int(support_checkout.get("support_pack_bytes", 0) or 0),
        "campaign_workspace": campaign_workspace,
        "missing_capability_request_channel": "child_return_packet.missing_capability_requests",
        "resident_cycle_sleep_seconds": resident_cycle_sleep_seconds,
        "resident_first_cycle_sleep_seconds": resident_first_cycle_sleep_seconds,
        "resident_wake_poll_seconds": 5,
        "initial_work_order_target_artifact": checkout_target_artifact,
        "initial_work_order_context": str(metadata.get("initial_work_order_context", "") or ""),
        "initial_work_order_source_return_packet_id": str(
            metadata.get("initial_work_order_source_return_packet_id", "")
            or metadata.get("continuous_campaign_latest_return_packet_id", "")
            or ""
        ),
        "initial_work_order_capability": str(
            metadata.get("initial_work_order_capability", "")
            or "directive_build_grade_synthesis_pack"
        ),
        "initial_work_order_recovered_from_campaign_metadata": checkout_initial_recovered,
        "provenance": {
            "source": "kernel_librarian_checkout",
            "state_root": str(state_root),
        },
    }
    _write_json(_checkout_path(operator_root, checkout_id), payload)
    _append_ledger(operator_root, "checkout_events", {"event": "created", **payload})
    return payload


def _prepare_child_write_dir(path: Path) -> str:
    path.mkdir(parents=True, exist_ok=True)
    try:
        path.chmod(0o777)
    except OSError:
        pass
    try:
        return oct(path.stat().st_mode & 0o777)
    except OSError:
        return "unknown"


def _prepare_child_writable_tree(path: Path) -> dict[str, Any]:
    """Make an existing bind-mounted tree writable by the non-root child user."""

    directory_mode = _prepare_child_write_dir(path)
    file_modes: dict[str, str] = {}
    failed_paths: list[str] = []
    for file_path in sorted(p for p in path.rglob("*") if p.is_file()):
        try:
            current_mode = file_path.stat().st_mode & 0o777
            file_path.chmod(current_mode | 0o666)
            file_modes[str(file_path.relative_to(path))] = oct(file_path.stat().st_mode & 0o777)
        except OSError:
            failed_paths.append(str(file_path.relative_to(path)))
    return {
        "directory_mode": directory_mode,
        "file_modes": file_modes,
        "failed_paths": failed_paths,
        "prepared_file_count": len(file_modes),
        "prepare_failed_count": len(failed_paths),
    }


def _child_progress_path_candidates(child: Mapping[str, Any]) -> list[Path]:
    progress_path = str(child.get("progress_path", "") or "").strip()
    if not progress_path:
        return []
    candidates = [Path(progress_path)]
    normalized = progress_path.replace("\\", "/")
    if normalized != progress_path:
        normalized_candidate = Path(normalized)
        candidates.append(normalized_candidate)
        if not normalized_candidate.is_absolute():
            candidates.append(Path.cwd() / normalized_candidate)
    marker = "/operator_state/"
    if marker in normalized:
        suffix = normalized.split(marker, 1)[1]
        candidates.append(Path.cwd() / "operator_state" / suffix)
    return candidates


def _latest_child_progress(child: Mapping[str, Any]) -> dict[str, Any]:
    candidates = _child_progress_path_candidates(child)
    seen: set[str] = set()
    for candidate in candidates:
        candidate_key = str(candidate)
        if candidate_key in seen:
            continue
        seen.add(candidate_key)
        payload = _read_json(candidate / "progress_latest.json")
        if payload:
            return payload
    return {}


def _child_progress_checkpoint_path(child: Mapping[str, Any]) -> Path | None:
    seen: set[str] = set()
    fallback: Path | None = None
    for candidate in _child_progress_path_candidates(child):
        candidate_key = str(candidate)
        if candidate_key in seen:
            continue
        seen.add(candidate_key)
        latest_path = candidate / "progress_latest.json"
        if fallback is None:
            fallback = latest_path
        if latest_path.exists():
            return latest_path
    return fallback


def _progress_checkpoint_hash(payload: Mapping[str, Any]) -> str:
    body = json.dumps(dict(payload), sort_keys=True, separators=(",", ":"), default=str)
    return hashlib.sha256(body.encode("utf-8")).hexdigest()


def _resident_progress_heartbeat(child: Mapping[str, Any], latest_progress: Mapping[str, Any]) -> dict[str, Any]:
    checkpoint_path = _child_progress_checkpoint_path(child)
    heartbeat_payload: dict[str, Any] = {}
    if checkpoint_path is not None:
        heartbeat_payload = _read_json(checkpoint_path.with_name("progress_heartbeat.json"))
    generated_at = str(latest_progress.get("generated_at", "") or "")
    checkpoint_hash = _progress_checkpoint_hash(latest_progress) if latest_progress else ""
    now_dt = datetime.now(timezone.utc)
    checkpoint_mtime_at = ""
    checkpoint_age_seconds = 0.0
    if checkpoint_path is not None and checkpoint_path.exists():
        try:
            mtime_dt = datetime.fromtimestamp(checkpoint_path.stat().st_mtime, tz=timezone.utc)
            checkpoint_mtime_at = mtime_dt.replace(microsecond=0).isoformat()
            checkpoint_age_seconds = max(0.0, (now_dt - mtime_dt).total_seconds())
        except OSError:
            checkpoint_mtime_at = ""
            checkpoint_age_seconds = 0.0
    last_progress_at = str(
        heartbeat_payload.get("last_progress_at", "")
        or heartbeat_payload.get("generated_at", "")
        or generated_at
        or checkpoint_mtime_at
        or ""
    )
    last_heartbeat_at = str(
        heartbeat_payload.get("last_heartbeat_at", "")
        or heartbeat_payload.get("generated_at", "")
        or generated_at
        or checkpoint_mtime_at
        or ""
    )
    return {
        "last_progress_at": last_progress_at,
        "last_heartbeat_at": last_heartbeat_at,
        "last_progress_checkpoint_hash": str(
            heartbeat_payload.get("progress_checkpoint_hash", "") or checkpoint_hash
        ),
        "progress_checkpoint_hash": checkpoint_hash,
        "progress_checkpoint_path": str(checkpoint_path or ""),
        "progress_checkpoint_mtime_at": checkpoint_mtime_at,
        "progress_checkpoint_age_seconds": round(checkpoint_age_seconds, 3),
        "progress_heartbeat_source": "progress_heartbeat_json" if heartbeat_payload else "progress_latest_json",
    }


def _resident_productive_stale_seconds() -> float:
    try:
        return max(60.0, min(float(os.environ.get("NOVALI_RESIDENT_PRODUCTIVE_STALE_SECONDS", "900") or "900"), 86400.0))
    except (TypeError, ValueError):
        return 900.0


def _child_first_checkpoint_stale_seconds() -> float:
    try:
        return max(
            30.0,
            min(float(os.environ.get("NOVALI_CHILD_FIRST_CHECKPOINT_STALE_SECONDS", "180") or "180"), 86400.0),
        )
    except (TypeError, ValueError):
        return 180.0


def _resident_phase_heartbeat(child: Mapping[str, Any]) -> dict[str, Any]:
    now_dt = datetime.now(timezone.utc)
    for candidate in _child_progress_path_candidates(child):
        heartbeat_path = candidate / "progress_phase_heartbeat.json"
        if not heartbeat_path.exists():
            continue
        payload = _read_json(heartbeat_path)
        if not payload:
            continue
        try:
            mtime_dt = datetime.fromtimestamp(heartbeat_path.stat().st_mtime, tz=timezone.utc)
            age_seconds = max(0.0, (now_dt - mtime_dt).total_seconds())
            mtime_at = mtime_dt.replace(microsecond=0).isoformat()
        except OSError:
            age_seconds = 0.0
            mtime_at = ""
        return {
            **dict(payload),
            "phase_heartbeat_path": str(heartbeat_path),
            "phase_heartbeat_mtime_at": mtime_at,
            "phase_heartbeat_age_seconds": round(age_seconds, 3),
        }
    return {}


def _child_outbox_return_packet_path(child: Mapping[str, Any]) -> Path | None:
    raw_outbox_path = str(child.get("outbox_path", "") or "").strip()
    return Path(raw_outbox_path) / "return_packet.json" if raw_outbox_path else None


def _resident_productive_finalizer_assessment(
    child: Mapping[str, Any],
    *,
    latest_progress: Mapping[str, Any],
    inspect_state: Mapping[str, Any],
) -> dict[str, Any]:
    threshold_seconds = _resident_productive_stale_seconds()
    heartbeat = _resident_progress_heartbeat(child, latest_progress)
    try:
        age_seconds = float(heartbeat.get("progress_checkpoint_age_seconds", 0.0) or 0.0)
    except (TypeError, ValueError):
        age_seconds = 0.0
    try:
        artifact_delta_count = int(latest_progress.get("artifact_delta_count", 0) or 0)
    except (TypeError, ValueError):
        artifact_delta_count = 0
    progress_has_delta = bool(
        latest_progress
        and (
            _resident_progress_has_meaningful_delta(latest_progress)
            or bool(latest_progress.get("meaningful_delta", False))
            or artifact_delta_count > 0
        )
    )
    outbox_packet = _child_outbox_return_packet_path(child)
    return_packet_present = bool(outbox_packet is not None and outbox_packet.exists())
    checkpoint_path = Path(str(heartbeat.get("progress_checkpoint_path", "") or ""))
    checkpoint_mtime = 0.0
    if checkpoint_path.exists():
        try:
            checkpoint_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            checkpoint_mtime = 0.0
    newer_return_packet = False
    if return_packet_present and checkpoint_mtime and outbox_packet is not None:
        try:
            newer_return_packet = outbox_packet.stat().st_mtime >= checkpoint_mtime
        except OSError:
            newer_return_packet = False
    state_name = str(inspect_state.get("state", "") or "").strip().lower()
    blocked_reasons: list[str] = []
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        blocked_reasons.append("not_resident_campaign_child")
    if state_name in {"exited"} or _child_inspect_indicates_missing_container(inspect_state):
        blocked_reasons.append("not_running_resident_child")
    if _child_inspect_indicates_mount_fault(inspect_state, child):
        blocked_reasons.append("mount_or_runtime_fault_detected")
    if not bool(latest_progress.get("compute_budget_exhausted", False)):
        blocked_reasons.append("compute_budget_not_exhausted")
    if not progress_has_delta:
        blocked_reasons.append("no_meaningful_artifact_delta")
    if age_seconds < threshold_seconds:
        blocked_reasons.append("progress_checkpoint_not_stale")
    if newer_return_packet:
        blocked_reasons.append("newer_return_packet_present")
    if bool(latest_progress.get("resident_self_final_return_eligible", False)) and bool(
        latest_progress.get("hardware_build_packet_ready_candidate", False)
    ):
        blocked_reasons.append("review_ready_checkpoint_should_return")
    return {
        "schema_name": "ResidentProductiveFinalizerAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "child_run_id": str(child.get("child_run_id", "") or ""),
        "directive_id": str(child.get("directive_id", "") or ""),
        "resident_productive_finalizer_eligible": not blocked_reasons,
        "resident_productive_finalizer_blockers": blocked_reasons,
        "resident_productive_stale_threshold_seconds": threshold_seconds,
        "resident_productive_progress_age_seconds": round(age_seconds, 3),
        "resident_productive_delta_observed": progress_has_delta,
        "resident_productive_return_packet_present": return_packet_present,
        "resident_productive_newer_return_packet_present": newer_return_packet,
        **heartbeat,
    }


def _finalize_stale_resident_productive_pass(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    inspect_state: Mapping[str, Any],
    runner: ConveyorChildRunner,
) -> dict[str, Any] | None:
    assessment = _resident_productive_finalizer_assessment(
        child,
        latest_progress=latest_progress,
        inspect_state=inspect_state,
    )
    updated_child = dict(child)
    updated_child.update(
        {
            "last_progress_at": str(assessment.get("last_progress_at", "") or ""),
            "last_heartbeat_at": str(assessment.get("last_heartbeat_at", "") or ""),
            "last_progress_checkpoint_hash": str(assessment.get("last_progress_checkpoint_hash", "") or ""),
            "progress_checkpoint_age_seconds": float(assessment.get("progress_checkpoint_age_seconds", 0.0) or 0.0),
            "resident_stale_after_productive_delta": bool(assessment.get("resident_productive_delta_observed", False)),
            "resident_productive_finalizer_eligible": bool(
                assessment.get("resident_productive_finalizer_eligible", False)
            ),
            "resident_productive_stale_threshold_seconds": float(
                assessment.get("resident_productive_stale_threshold_seconds", 0.0) or 0.0
            ),
        }
    )
    child_id = str(updated_child.get("child_run_id", "") or "")
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated_child)
    if not bool(assessment.get("resident_productive_finalizer_eligible", False)):
        return None
    checkpoint_path = Path(str(assessment.get("progress_checkpoint_path", "") or ""))
    before_hash = str(assessment.get("progress_checkpoint_hash", "") or "")
    before_mtime = 0.0
    if checkpoint_path.exists():
        try:
            before_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            before_mtime = 0.0
    fresh_progress = _latest_child_progress(updated_child)
    fresh_assessment = _resident_productive_finalizer_assessment(
        updated_child,
        latest_progress=fresh_progress,
        inspect_state=inspect_state,
    )
    after_mtime = before_mtime
    if checkpoint_path.exists():
        try:
            after_mtime = checkpoint_path.stat().st_mtime
        except OSError:
            after_mtime = before_mtime
    if (
        str(fresh_assessment.get("progress_checkpoint_hash", "") or "") != before_hash
        or after_mtime != before_mtime
        or not bool(fresh_assessment.get("resident_productive_finalizer_eligible", False))
    ):
        updated_child["resident_productive_finalizer_suppressed"] = True
        updated_child["resident_productive_finalizer_suppressed_reason"] = "fresh_progress_checkpoint_observed"
        updated_child["updated_at"] = _utc_now()
        if child_id:
            _write_json(_child_path(operator_root, child_id), updated_child)
        return None
    try:
        stop_result = dict(runner.stop_child_container(dict(updated_child)) or {})
    except Exception as exc:
        stop_result = {"ok": False, "state": "stop_failed", "error_class": type(exc).__name__, "error": str(exc)}
    recovery = _missing_container_recovery_evidence(updated_child, fresh_progress)
    lifecycle = _classify_terminal_child_without_return(
        updated_child,
        inspect_state={
            **dict(inspect_state),
            "state": str(inspect_state.get("state", "") or "running"),
            "resident_productive_finalizer_stop_result": stop_result,
        },
        latest_progress=fresh_progress,
        recovery=recovery,
    )
    if str(lifecycle.get("child_lifecycle_classification", "") or "") != "productive_pass_completed_not_review_ready":
        return None
    lifecycle["resident_productive_stale_finalized"] = True
    lifecycle["resident_productive_finalizer_assessment"] = dict(fresh_assessment)
    finalized = _record_terminal_child_without_review_return(
        operator_root,
        child={**updated_child, "stop_result": stop_result, "stop_requested": True},
        lifecycle=lifecycle,
        recovery=recovery,
        inspect_state={
            **dict(inspect_state),
            "resident_productive_finalizer_stop_result": stop_result,
        },
    )
    finalized["resident_productive_stale_finalized"] = True
    finalized["stop_requested"] = True
    finalized["stop_result"] = stop_result
    finalized["last_progress_at"] = str(fresh_assessment.get("last_progress_at", "") or "")
    finalized["last_heartbeat_at"] = str(fresh_assessment.get("last_heartbeat_at", "") or "")
    finalized["last_progress_checkpoint_hash"] = str(fresh_assessment.get("last_progress_checkpoint_hash", "") or "")
    finalized["progress_checkpoint_age_seconds"] = float(
        fresh_assessment.get("progress_checkpoint_age_seconds", 0.0) or 0.0
    )
    if child_id:
        _write_json(_child_path(operator_root, child_id), finalized)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_productive_stale_finalized",
            "generated_at": _utc_now(),
            "child_run_id": child_id,
            "directive_id": str(finalized.get("directive_id", "") or ""),
            "target_artifact": str(lifecycle.get("productive_pass_target_artifact", "") or ""),
            "stop_result": stop_result,
            "resident_productive_finalizer_assessment": dict(fresh_assessment),
            "grants_execution_authority": False,
        },
    )
    return finalized


def _resident_no_first_checkpoint_assessment(
    child: Mapping[str, Any],
    *,
    inspect_state: Mapping[str, Any],
) -> dict[str, Any]:
    threshold_seconds = _child_first_checkpoint_stale_seconds()
    checkpoint_path = _child_progress_checkpoint_path(child)
    phase_heartbeat = _resident_phase_heartbeat(child)
    now_dt = datetime.now(timezone.utc)
    reference_at = (
        str(phase_heartbeat.get("last_heartbeat_at", "") or phase_heartbeat.get("generated_at", "") or "")
        or str(child.get("spawn_fulfilled_at", "") or "")
        or str(child.get("created_at", "") or "")
        or str(child.get("updated_at", "") or "")
    )
    reference_dt = _parse_utc_time(reference_at)
    age_seconds = 0.0
    if reference_dt is not None:
        age_seconds = max(0.0, (now_dt - reference_dt).total_seconds())
    state_name = str(inspect_state.get("state", "") or "").strip().lower()
    blocked_reasons: list[str] = []
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        blocked_reasons.append("not_resident_campaign_child")
    if state_name not in {"running", "created", "restarting", "unknown"}:
        blocked_reasons.append("not_running_resident_child")
    if _child_inspect_indicates_missing_container(inspect_state):
        blocked_reasons.append("missing_container")
    if _child_inspect_indicates_mount_fault(inspect_state, child):
        blocked_reasons.append("mount_or_runtime_fault_detected")
    if checkpoint_path is not None and checkpoint_path.exists():
        blocked_reasons.append("first_checkpoint_present")
    if phase_heartbeat and age_seconds < threshold_seconds:
        blocked_reasons.append("phase_heartbeat_fresh")
    elif not phase_heartbeat and age_seconds < threshold_seconds:
        blocked_reasons.append("startup_not_stale")
    return {
        "schema_name": "ResidentNoFirstCheckpointAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "child_run_id": str(child.get("child_run_id", "") or ""),
        "directive_id": str(child.get("directive_id", "") or ""),
        "resident_no_first_checkpoint_finalizer_eligible": not blocked_reasons,
        "resident_no_first_checkpoint_blockers": blocked_reasons,
        "child_first_checkpoint_stale_threshold_seconds": threshold_seconds,
        "first_checkpoint_age_seconds": round(age_seconds, 3),
        "child_runtime_no_first_checkpoint": not (checkpoint_path is not None and checkpoint_path.exists()),
        "last_compute_phase": str(phase_heartbeat.get("last_compute_phase", "") or ""),
        "phase_heartbeat_event": str(phase_heartbeat.get("phase_event", "") or ""),
        "phase_heartbeat_age_seconds": float(phase_heartbeat.get("phase_heartbeat_age_seconds", 0.0) or 0.0),
        "last_heartbeat_at": str(
            phase_heartbeat.get("last_heartbeat_at", "")
            or phase_heartbeat.get("generated_at", "")
            or reference_at
            or ""
        ),
    }


def _finalize_resident_no_first_checkpoint(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    inspect_state: Mapping[str, Any],
    runner: ConveyorChildRunner,
) -> dict[str, Any] | None:
    assessment = _resident_no_first_checkpoint_assessment(child, inspect_state=inspect_state)
    updated_child = dict(child)
    updated_child.update(
        {
            "child_runtime_no_first_checkpoint": bool(assessment.get("child_runtime_no_first_checkpoint", False)),
            "first_checkpoint_age_seconds": float(assessment.get("first_checkpoint_age_seconds", 0.0) or 0.0),
            "last_compute_phase": str(assessment.get("last_compute_phase", "") or ""),
            "last_heartbeat_at": str(assessment.get("last_heartbeat_at", "") or ""),
            "resident_no_first_checkpoint_finalizer_eligible": bool(
                assessment.get("resident_no_first_checkpoint_finalizer_eligible", False)
            ),
            "resident_no_first_checkpoint_blockers": list(
                assessment.get("resident_no_first_checkpoint_blockers", []) or []
            ),
        }
    )
    child_id = str(updated_child.get("child_run_id", "") or "")
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated_child)
    if not bool(assessment.get("resident_no_first_checkpoint_finalizer_eligible", False)):
        return None
    fresh_progress = _latest_child_progress(updated_child)
    fresh_assessment = _resident_no_first_checkpoint_assessment(updated_child, inspect_state=inspect_state)
    if fresh_progress or not bool(fresh_assessment.get("resident_no_first_checkpoint_finalizer_eligible", False)):
        updated_child["resident_no_first_checkpoint_finalizer_suppressed"] = True
        updated_child["resident_no_first_checkpoint_finalizer_suppressed_reason"] = (
            "fresh_first_checkpoint_or_heartbeat_observed"
        )
        updated_child["updated_at"] = _utc_now()
        if child_id:
            _write_json(_child_path(operator_root, child_id), updated_child)
        return None
    try:
        stop_result = dict(runner.stop_child_container(dict(updated_child)) or {})
    except Exception as exc:
        stop_result = {"ok": False, "state": "stop_failed", "error_class": type(exc).__name__, "error": str(exc)}
    target = str(
        updated_child.get("latest_work_order_target_artifact", "")
        or updated_child.get("latest_target_artifact", "")
        or ""
    ).strip()
    latest_progress = {
        "schema_name": "ResidentNoFirstCheckpointLifecycleProgress",
        "generated_at": _utc_now(),
        "child_run_id": child_id,
        "directive_id": str(updated_child.get("directive_id", "") or ""),
        "target_artifact": target,
        "progress_state": "blocked",
        "cycle_outcome": "blocked",
        "remaining_failed_gates": ["child_runtime_no_first_checkpoint"],
        "hardware_build_packet_ready_candidate": False,
        "grants_execution_authority": False,
    }
    recovery = {
        "recoverable": True,
        "blockers": [],
        "progress_has_delta": False,
        "workspace_has_artifacts": False,
        "workspace_artifacts": [],
        "artifact_delta_count": 0,
        "materialized_expected_files": [],
        "target_artifact": target,
        "work_order_id": str(updated_child.get("latest_work_order_id", "") or ""),
        "latest_progress_ref": {
            "child_run_id": child_id,
            "directive_id": str(updated_child.get("directive_id", "") or ""),
            "target_artifact": target,
            "work_order_id": str(updated_child.get("latest_work_order_id", "") or ""),
            "generated_at": str(latest_progress.get("generated_at", "") or ""),
        },
    }
    lifecycle = _classify_terminal_child_without_return(
        {**updated_child, "stop_requested": False},
        inspect_state={**dict(inspect_state), "resident_no_first_checkpoint_stop_result": stop_result},
        latest_progress=latest_progress,
        recovery=recovery,
    )
    if str(lifecycle.get("child_lifecycle_classification", "") or "") != "blocked_pass_completed_not_review_ready":
        return None
    lifecycle["child_runtime_no_first_checkpoint"] = True
    lifecycle["resident_no_first_checkpoint_assessment"] = dict(fresh_assessment)
    finalized = _record_terminal_child_without_review_return(
        operator_root,
        child={**updated_child, "stop_result": stop_result, "stop_requested": True},
        lifecycle=lifecycle,
        recovery=recovery,
        inspect_state={**dict(inspect_state), "resident_no_first_checkpoint_stop_result": stop_result},
    )
    finalized["child_runtime_no_first_checkpoint"] = True
    finalized["resident_no_first_checkpoint_finalized"] = True
    finalized["first_checkpoint_age_seconds"] = float(fresh_assessment.get("first_checkpoint_age_seconds", 0.0) or 0.0)
    finalized["last_compute_phase"] = str(fresh_assessment.get("last_compute_phase", "") or "")
    finalized["last_heartbeat_at"] = str(fresh_assessment.get("last_heartbeat_at", "") or "")
    finalized["stop_requested"] = True
    finalized["stop_result"] = stop_result
    if child_id:
        _write_json(_child_path(operator_root, child_id), finalized)
    directive_id = str(finalized.get("directive_id", "") or "")
    if directive_id:
        directive = _read_json(_directive_path(operator_root, directive_id))
        if directive:
            directive["state"] = "blocked"
            directive["active_child_run_id"] = ""
            directive["blocked_reason"] = "child_runtime_no_first_checkpoint"
            metadata = dict(directive.get("metadata", {}) or {})
            metadata["child_lifecycle_classification"] = "blocked_pass_completed_not_review_ready"
            metadata["child_runtime_no_first_checkpoint"] = True
            metadata["next_unresolved_artifact"] = target
            directive["metadata"] = metadata
            directive["updated_at"] = _utc_now()
            _write_json(_directive_path(operator_root, directive_id), directive)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_no_first_checkpoint_finalized",
            "generated_at": _utc_now(),
            "child_run_id": child_id,
            "directive_id": directive_id,
            "target_artifact": target,
            "resident_no_first_checkpoint_assessment": dict(fresh_assessment),
            "grants_execution_authority": False,
        },
    )
    return finalized


def _resident_synthesis_stalled_assessment(
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    *,
    inspect_state: Mapping[str, Any],
) -> dict[str, Any]:
    threshold_seconds = _child_first_checkpoint_stale_seconds()
    heartbeat = _resident_progress_heartbeat(child, latest_progress)
    try:
        age_seconds = float(heartbeat.get("progress_checkpoint_age_seconds", 0.0) or 0.0)
    except (TypeError, ValueError):
        age_seconds = 0.0
    state_name = str(inspect_state.get("state", "") or "").strip().lower()
    cycle_outcome = str(latest_progress.get("cycle_outcome", "") or "").strip()
    last_phase = str(
        latest_progress.get("last_compute_phase", "")
        or child.get("last_compute_phase", "")
        or ""
    ).strip()
    blockers: list[str] = []
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        blockers.append("not_resident_campaign_child")
    if state_name in {"exited"} or _child_inspect_indicates_missing_container(inspect_state):
        blockers.append("not_running_resident_child")
    if _child_inspect_indicates_mount_fault(inspect_state, child):
        blockers.append("mount_or_runtime_fault_detected")
    if cycle_outcome != "synthesis_in_progress":
        blockers.append("not_synthesis_in_progress_checkpoint")
    if last_phase != "synthesize_rows":
        blockers.append("not_synthesize_rows_phase")
    if age_seconds < threshold_seconds:
        blockers.append("synthesis_checkpoint_not_stale")
    if bool(latest_progress.get("meaningful_delta", False)) or int(latest_progress.get("artifact_delta_count", 0) or 0):
        blockers.append("checkpoint_already_has_artifact_delta")
    return {
        "schema_name": "ResidentSynthesisStalledAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "child_run_id": str(child.get("child_run_id", "") or ""),
        "directive_id": str(child.get("directive_id", "") or ""),
        "resident_synthesis_stalled_finalizer_eligible": not blockers,
        "resident_synthesis_stalled_blockers": blockers,
        "resident_synthesis_stalled_threshold_seconds": threshold_seconds,
        "resident_synthesis_checkpoint_age_seconds": round(age_seconds, 3),
        "last_compute_phase": last_phase,
        "cycle_outcome": cycle_outcome,
        "target_artifact": str(latest_progress.get("target_artifact", "") or ""),
        "grants_execution_authority": False,
    }


def _finalize_resident_synthesis_stalled(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    inspect_state: Mapping[str, Any],
    runner: ConveyorChildRunner,
) -> dict[str, Any] | None:
    assessment = _resident_synthesis_stalled_assessment(
        child,
        latest_progress,
        inspect_state=inspect_state,
    )
    updated_child = dict(child)
    updated_child.update(
        {
            "resident_synthesis_stalled_finalizer_eligible": bool(
                assessment.get("resident_synthesis_stalled_finalizer_eligible", False)
            ),
            "resident_synthesis_stalled_blockers": list(
                assessment.get("resident_synthesis_stalled_blockers", []) or []
            ),
            "resident_synthesis_checkpoint_age_seconds": float(
                assessment.get("resident_synthesis_checkpoint_age_seconds", 0.0) or 0.0
            ),
            "last_compute_phase": str(assessment.get("last_compute_phase", "") or ""),
        }
    )
    child_id = str(updated_child.get("child_run_id", "") or "")
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated_child)
    if not bool(assessment.get("resident_synthesis_stalled_finalizer_eligible", False)):
        return None
    fresh_progress = _latest_child_progress(updated_child)
    fresh_assessment = _resident_synthesis_stalled_assessment(
        updated_child,
        fresh_progress,
        inspect_state=inspect_state,
    )
    if not bool(fresh_assessment.get("resident_synthesis_stalled_finalizer_eligible", False)):
        updated_child["resident_synthesis_stalled_finalizer_suppressed"] = True
        updated_child["resident_synthesis_stalled_finalizer_suppressed_reason"] = (
            "fresh_progress_or_non_synthesis_checkpoint_observed"
        )
        updated_child["updated_at"] = _utc_now()
        if child_id:
            _write_json(_child_path(operator_root, child_id), updated_child)
        return None
    try:
        stop_result = dict(runner.stop_child_container(dict(updated_child)) or {})
    except Exception as exc:
        stop_result = {"ok": False, "state": "stop_failed", "error_class": type(exc).__name__, "error": str(exc)}
    target = str(
        fresh_progress.get("target_artifact", "")
        or updated_child.get("latest_work_order_target_artifact", "")
        or updated_child.get("latest_target_artifact", "")
        or ""
    ).strip()
    lifecycle_progress = {
        **dict(fresh_progress),
        "progress_state": "blocked",
        "cycle_outcome": "blocked",
        "target_artifact": target,
        "remaining_failed_gates": ["child_runtime_synthesis_stalled"],
        "hardware_build_packet_ready_candidate": False,
        "grants_execution_authority": False,
    }
    recovery = {
        "recoverable": True,
        "blockers": [],
        "progress_has_delta": False,
        "workspace_has_artifacts": False,
        "workspace_artifacts": [],
        "artifact_delta_count": 0,
        "materialized_expected_files": [],
        "target_artifact": target,
        "work_order_id": str(updated_child.get("latest_work_order_id", "") or ""),
        "latest_progress_ref": {
            "child_run_id": child_id,
            "directive_id": str(updated_child.get("directive_id", "") or ""),
            "target_artifact": target,
            "work_order_id": str(updated_child.get("latest_work_order_id", "") or ""),
            "generated_at": str(lifecycle_progress.get("generated_at", "") or ""),
        },
    }
    lifecycle = _classify_terminal_child_without_return(
        {**updated_child, "stop_requested": False},
        inspect_state={**dict(inspect_state), "resident_synthesis_stalled_stop_result": stop_result},
        latest_progress=lifecycle_progress,
        recovery=recovery,
    )
    if str(lifecycle.get("child_lifecycle_classification", "") or "") != "blocked_pass_completed_not_review_ready":
        return None
    lifecycle["child_runtime_synthesis_stalled"] = True
    lifecycle["resident_synthesis_stalled_assessment"] = dict(fresh_assessment)
    finalized = _record_terminal_child_without_review_return(
        operator_root,
        child={**updated_child, "stop_result": stop_result, "stop_requested": True},
        lifecycle=lifecycle,
        recovery=recovery,
        inspect_state={**dict(inspect_state), "resident_synthesis_stalled_stop_result": stop_result},
    )
    finalized["child_runtime_synthesis_stalled"] = True
    finalized["resident_synthesis_stalled_finalized"] = True
    finalized["resident_synthesis_checkpoint_age_seconds"] = float(
        fresh_assessment.get("resident_synthesis_checkpoint_age_seconds", 0.0) or 0.0
    )
    finalized["last_compute_phase"] = str(fresh_assessment.get("last_compute_phase", "") or "")
    finalized["stop_requested"] = True
    finalized["stop_result"] = stop_result
    if child_id:
        _write_json(_child_path(operator_root, child_id), finalized)
    directive_id = str(finalized.get("directive_id", "") or "")
    if directive_id:
        directive = _read_json(_directive_path(operator_root, directive_id))
        if directive:
            directive["state"] = "blocked"
            directive["active_child_run_id"] = ""
            directive["blocked_reason"] = "child_runtime_synthesis_stalled"
            metadata = dict(directive.get("metadata", {}) or {})
            metadata["child_lifecycle_classification"] = "blocked_pass_completed_not_review_ready"
            metadata["child_runtime_synthesis_stalled"] = True
            metadata["next_unresolved_artifact"] = target
            directive["metadata"] = metadata
            directive["updated_at"] = _utc_now()
            _write_json(_directive_path(operator_root, directive_id), directive)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_synthesis_stalled_finalized",
            "generated_at": _utc_now(),
            "child_run_id": child_id,
            "directive_id": directive_id,
            "target_artifact": target,
            "resident_synthesis_stalled_assessment": dict(fresh_assessment),
            "grants_execution_authority": False,
        },
    )
    return finalized


CHILD_COMPUTE_STATUS_FIELDS = (
    "child_activity_state",
    "child_compute_mode",
    "cycle_process_cpu_seconds",
    "compute_pass_count",
    "sleep_reason",
    "support_pack_rows_read",
    "artifact_rows_generated",
    "artifact_rows_revised",
)


def _child_compute_status_fields(
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    embedded_progress = child.get("latest_progress", {})
    progress = dict(
        latest_progress
        if isinstance(latest_progress, Mapping)
        else embedded_progress
        if isinstance(embedded_progress, Mapping)
        else {}
    )
    fields: dict[str, Any] = {
        "child_activity_state": str(
            progress.get("child_activity_state", "")
            or child.get("child_activity_state", "")
            or ""
        ),
        "child_compute_mode": str(
            progress.get("child_compute_mode", "")
            or child.get("child_compute_mode", "")
            or ""
        ),
        "child_compute_cpu_seconds_latest": float(
            progress.get("cycle_process_cpu_seconds", child.get("child_compute_cpu_seconds_latest", 0.0)) or 0.0
        ),
        "child_compute_pass_count_latest": int(
            progress.get("compute_pass_count", child.get("child_compute_pass_count_latest", 0)) or 0
        ),
        "child_sleep_reason": str(
            progress.get("sleep_reason", "")
            or child.get("child_sleep_reason", "")
            or ""
        ),
    }
    for key in (
        "support_pack_rows_read",
        "artifact_rows_generated",
        "artifact_rows_revised",
    ):
        try:
            fields[key] = int(progress.get(key, child.get(key, 0)) or 0)
        except (TypeError, ValueError):
            fields[key] = 0
    candidate = progress.get("support_request_candidate", child.get("support_request_candidate", {}))
    if isinstance(candidate, Mapping) and candidate:
        fields["support_candidate_pending"] = True
        fields["support_request_id"] = str(child.get("latest_support_request_id", child.get("support_request_id", "")) or "")
        fields["support_candidate_target_artifact"] = str(candidate.get("target_artifact", "") or progress.get("target_artifact", "") or "")
        fields["support_candidate_capability"] = str(candidate.get("capability", "") or "")
        fields["support_tick_needed"] = True
    else:
        fields["support_candidate_pending"] = False
        fields["support_request_id"] = str(child.get("latest_support_request_id", child.get("support_request_id", "")) or "")
        fields["support_candidate_target_artifact"] = ""
        fields["support_candidate_capability"] = ""
        fields["support_tick_needed"] = False
    return fields


def _child_inbox_path(child: Mapping[str, Any]) -> Path:
    raw_inbox_path = str(child.get("inbox_path", "") or "")
    normalized = raw_inbox_path.replace("\\", "/")
    marker = "/operator_state/"
    if normalized.startswith("operator_state/"):
        inbox_path = Path.cwd() / normalized
    elif marker in normalized:
        suffix = normalized.split(marker, 1)[1]
        inbox_path = Path.cwd() / "operator_state" / suffix
    else:
        inbox_path = Path(normalized)
    return inbox_path / "inbox.json" if inbox_path.suffix != ".json" else inbox_path


def _latest_inbox_work_order(inbox_payload: Mapping[str, Any]) -> dict[str, Any]:
    for message in reversed(list(inbox_payload.get("messages", []) or [])):
        if isinstance(message, Mapping) and str(message.get("kind", "") or "") == "kernel_work_order":
            return dict(message)
    return {}


def _compact_hash(payload: Any, *, length: int = 16) -> str:
    body = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str)
    return hashlib.sha256(body.encode("utf-8")).hexdigest()[:length]


def _resident_work_order_signature(work_order: Mapping[str, Any]) -> str:
    role_ref = dict(work_order.get("role_research_adapter_ref", {}) or {})
    signature_payload = {
        "directive_id": str(work_order.get("directive_id", "") or ""),
        "target_artifact": str(work_order.get("target_artifact", "") or ""),
        "target_selection_reason": str(work_order.get("target_selection_reason", "") or ""),
        "schema_skeleton_id": str(work_order.get("schema_skeleton_id", "") or ""),
        "required_gate_closures": sorted(
            str(item) for item in list(work_order.get("required_gate_closures", []) or [])
        ),
        "quality_failed_gates": sorted(
            str(item) for item in list(work_order.get("quality_failed_gates", []) or [])
        ),
        "role_adapter_id": str(role_ref.get("role_specific_research_adapter_id", "") or ""),
        "child_output_contract": work_order.get("child_output_contract", {}),
        "hardware_prototype_readiness_contract": work_order.get("hardware_prototype_readiness_contract", {}),
        "prototype_evidence_fixture": work_order.get("prototype_evidence_fixture", {}),
        "field_level_output_contract": work_order.get("field_level_output_contract", {}),
        "plateau_intervention_stage": str(work_order.get("plateau_intervention_stage", "") or ""),
        "depth_obligation_id": str(work_order.get("depth_obligation_id", "") or ""),
        "depth_target_artifact": str(work_order.get("depth_target_artifact", "") or ""),
        "depth_missing_fields": work_order.get("depth_missing_fields", []),
        "depth_required_evidence_refs": sorted(
            str(item) for item in list(work_order.get("depth_required_evidence_refs", []) or [])
        ),
        "target_delta_required": bool(work_order.get("target_delta_required", False)),
        "schema_resonance_followup_required": bool(work_order.get("schema_resonance_followup_required", False)),
        "persistent_schema_contract_required": bool(work_order.get("persistent_schema_contract_required", False)),
        "schema_resonance_score": work_order.get("schema_resonance_score", ""),
        "required_top_level_fields": sorted(
            str(item) for item in list(work_order.get("required_top_level_fields", []) or [])
        ),
        "missing_top_level_fields": sorted(
            str(item) for item in list(work_order.get("missing_top_level_fields", []) or [])
        ),
        "artifact_top_level_schema_skeleton": work_order.get("artifact_top_level_schema_skeleton", {}),
    }
    return _compact_hash(signature_payload)


def _compact_resident_inbox_work_orders(inbox_payload: dict[str, Any]) -> dict[str, Any]:
    messages = [item for item in list(inbox_payload.get("messages", []) or []) if isinstance(item, Mapping)]
    work_orders = [dict(item) for item in messages if str(item.get("kind", "") or "") == "kernel_work_order"]
    if len(work_orders) <= 1:
        inbox_payload.setdefault(
            "inbox_compaction_summary",
            {
                "compacted": False,
                "active_work_order_count": len(work_orders),
                "omitted_work_order_count": 0,
                "omitted_work_order_ids": [],
            },
        )
        return inbox_payload
    latest_work_order = work_orders[-1]
    non_work_messages = [dict(item) for item in messages if str(item.get("kind", "") or "") != "kernel_work_order"]
    omitted = work_orders[:-1]
    inbox_payload["messages"] = [*non_work_messages[:1], latest_work_order]
    inbox_payload["inbox_compaction_summary"] = {
        "compacted": True,
        "active_work_order_count": 1,
        "omitted_work_order_count": len(omitted),
        "omitted_work_order_ids": [
            str(item.get("work_order_id", "") or "") for item in omitted[-20:]
        ],
        "total_message_count_before": len(messages),
        "total_message_count_after": len(inbox_payload["messages"]),
    }
    return inbox_payload


def _resident_wake_request_from_inbox(inbox_payload: Mapping[str, Any]) -> dict[str, Any]:
    try:
        sequence = max(0, int(inbox_payload.get("wake_sequence", 0) or 0))
    except (TypeError, ValueError):
        sequence = 0
    work_order_id = str(inbox_payload.get("wake_work_order_id", "") or "").strip()
    if sequence <= 0 or not work_order_id:
        return {}
    return {
        "wake_requested_at": str(inbox_payload.get("wake_requested_at", "") or ""),
        "wake_reason": str(inbox_payload.get("wake_reason", "") or ""),
        "wake_work_order_id": work_order_id,
        "wake_priority": str(inbox_payload.get("wake_priority", "") or ""),
        "wake_sequence": sequence,
        "wake_ack_timeout_seconds": int(float(inbox_payload.get("wake_ack_timeout_seconds", 0) or 0)),
    }


def _resident_wake_ack_from_progress(progress: Mapping[str, Any]) -> dict[str, Any]:
    if not bool(progress.get("wake_token_observed", False)):
        return {}
    try:
        latency = float(progress.get("wake_latency_seconds", 0.0) or 0.0)
    except (TypeError, ValueError):
        latency = 0.0
    return {
        "wake_acknowledged_at": str(progress.get("generated_at", "") or ""),
        "wake_work_order_id": str(progress.get("wake_work_order_id", "") or ""),
        "wake_reason": str(progress.get("wake_reason", "") or ""),
        "wake_sequence": int(float(progress.get("wake_sequence", 0) or 0)),
        "wake_latency_seconds": max(0.0, latency),
    }


def _resident_work_order_wake_reason(work_order: Mapping[str, Any], fallback_reason: str = "") -> str:
    fallback = str(fallback_reason or "").lower()
    if "manifest_next_unresolved_gate_drift" in fallback:
        return "manifest_next_unresolved_gate_drift"
    if bool(work_order.get("schema_resonance_followup_required", False)):
        return "schema_resonance_followup_required"
    if "schema_resonance_followup_required" in fallback:
        return "schema_resonance_followup_required"
    reason = str(work_order.get("plateau_recovery_reason", "") or "").strip()
    if reason in RESIDENT_WAKE_HIGH_PRIORITY_REASONS:
        return reason
    if work_order.get("field_level_output_contract"):
        return "field_level_contract_injected"
    if work_order.get("hardware_prototype_readiness_contract"):
        return "hardware_prototype_readiness_contract_required"
    reason = str(work_order.get("target_selection_reason", "") or "").strip()
    if reason in RESIDENT_WAKE_HIGH_PRIORITY_REASONS:
        return reason
    if "operator clarification" in fallback:
        return "operator_clarification_requeue"
    if "operator requeue" in fallback or "operator feedback" in fallback:
        return "operator_requeue"
    if "quality" in fallback or "support" in fallback:
        return "quality_support_injected"
    if "plateau" in fallback:
        return "draft_delta_plateau_recovery"
    return ""


def _request_resident_child_wake(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    inbox_payload: dict[str, Any],
    inbox_path: Path,
    work_order: Mapping[str, Any],
    wake_reason: str,
    force: bool = False,
) -> dict[str, Any]:
    reason = str(wake_reason or "").strip()
    if reason not in RESIDENT_WAKE_HIGH_PRIORITY_REASONS:
        return inbox_payload
    work_order_id = str(work_order.get("work_order_id", "") or "").strip()
    if not work_order_id:
        return inbox_payload
    existing = _resident_wake_request_from_inbox(inbox_payload)
    if (
        not force
        and existing
        and str(existing.get("wake_work_order_id", "") or "") == work_order_id
    ):
        _write_json(inbox_path, inbox_payload)
        return inbox_payload
    try:
        sequence = max(0, int(inbox_payload.get("wake_sequence", 0) or 0)) + 1
    except (TypeError, ValueError):
        sequence = 1
    now = _utc_now()
    inbox_payload["wake_requested_at"] = now
    inbox_payload["wake_reason"] = reason
    inbox_payload["wake_work_order_id"] = work_order_id
    inbox_payload["wake_priority"] = "high"
    inbox_payload["wake_ack_timeout_seconds"] = RESIDENT_WAKE_ACK_TIMEOUT_SECONDS
    inbox_payload["wake_sequence"] = sequence
    _write_json(inbox_path, inbox_payload)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_child_wake_requested",
            "generated_at": now,
            "child_run_id": str(child.get("child_run_id", "") or ""),
            "directive_id": str(child.get("directive_id", "") or ""),
            "work_order_id": work_order_id,
            "wake_reason": reason,
            "wake_priority": "high",
            "wake_sequence": sequence,
            "wake_ack_timeout_seconds": RESIDENT_WAKE_ACK_TIMEOUT_SECONDS,
        },
    )
    return inbox_payload


def _resident_wake_state(child: Mapping[str, Any]) -> dict[str, Any]:
    inbox_payload = _read_json(_child_inbox_path(child))
    request = _resident_wake_request_from_inbox(inbox_payload)
    progress = dict(child.get("latest_progress", {}) or {}) or _latest_child_progress(child)
    ack = dict(child.get("latest_wake_ack", {}) or {}) or _resident_wake_ack_from_progress(progress)
    pending = False
    stale = False
    latency: float | None = None
    if request:
        pending = not ack or (
            str(ack.get("wake_work_order_id", "") or "") != str(request.get("wake_work_order_id", "") or "")
            or int(ack.get("wake_sequence", 0) or 0) < int(request.get("wake_sequence", 0) or 0)
        )
        if pending:
            requested_at = _parse_utc_time(request.get("wake_requested_at", ""))
            if requested_at:
                latency = max(0.0, (datetime.now(timezone.utc) - requested_at).total_seconds())
                timeout = int(request.get("wake_ack_timeout_seconds", RESIDENT_WAKE_ACK_TIMEOUT_SECONDS) or RESIDENT_WAKE_ACK_TIMEOUT_SECONDS)
                stale = latency >= timeout
        else:
            try:
                latency = float(ack.get("wake_latency_seconds", 0.0) or 0.0)
            except (TypeError, ValueError):
                latency = 0.0
    elif ack:
        try:
            latency = float(ack.get("wake_latency_seconds", 0.0) or 0.0)
        except (TypeError, ValueError):
            latency = 0.0
    return {
        "latest_wake_request": request,
        "latest_wake_ack": ack,
        "wake_pending": pending,
        "wake_stale": stale,
        "wake_latency_seconds": latency,
        "wake_fallback_restart_count": int(child.get("wake_fallback_restart_count", 0) or 0),
    }


def _wake_fallback_blockers(operator_root: str | Path, child: Mapping[str, Any], state: Mapping[str, Any]) -> list[str]:
    blockers: list[str] = []
    if _autonomy_emergency_stop_active(operator_root):
        blockers.append("emergency_stop")
    if _child_inspect_indicates_mount_fault(state, child):
        blockers.append("docker_mount_fault")
    directive_id = str(child.get("directive_id", "") or "")
    if directive_id:
        pending_support = [
            item
            for item in _load_items(_support_requests_root(operator_root))
            if str(item.get("directive_id", "") or "") == directive_id
            and str(item.get("support_state", "") or "") == "pending_operator_review"
        ]
        if pending_support:
            blockers.append("pending_support")
        directive = _load_directive(operator_root, directive_id)
        campaign = _continuous_campaign_state(scheduler=_load_scheduler(operator_root), directive=directive)
        if str(campaign.get("latest_state", "") or "") == "cap_exhausted":
            blockers.append("cap_exhausted")
    return blockers


def _fallback_restart_stale_wake_child(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    child: Mapping[str, Any],
    state: Mapping[str, Any],
    wake_state: Mapping[str, Any],
    runner: ConveyorChildRunner,
    scheduler: Mapping[str, Any],
) -> dict[str, Any] | None:
    if not bool(wake_state.get("wake_stale", False)):
        return None
    request = dict(wake_state.get("latest_wake_request", {}) or {})
    work_order_id = str(request.get("wake_work_order_id", "") or "")
    if not work_order_id:
        return None
    restarted_ids = {
        str(item)
        for item in list(child.get("wake_fallback_restarted_work_order_ids", []) or [])
        if str(item)
    }
    if work_order_id in restarted_ids:
        return None
    for existing_child in _load_items(_children_root(operator_root)):
        if str(existing_child.get("child_run_id", "") or "") == str(child.get("child_run_id", "") or ""):
            continue
        if str(existing_child.get("wake_fallback_restart_work_order_id", "") or "") == work_order_id:
            return None
        if work_order_id in {
            str(item)
            for item in list(existing_child.get("wake_fallback_restarted_work_order_ids", []) or [])
            if str(item)
        }:
            return None
    directive_id = str(child.get("directive_id", "") or "")
    overlapping_active_children = [
        dict(existing_child)
        for existing_child in _active_children_for_directive(operator_root, directive_id)
        if str(existing_child.get("child_run_id", "") or "").strip()
        and str(existing_child.get("child_run_id", "") or "").strip()
        != str(child.get("child_run_id", "") or "").strip()
    ]
    if overlapping_active_children:
        now = _utc_now()
        try:
            runner.stop_child_container(dict(child))
        except Exception:
            pass
        stopped_child = dict(child)
        stopped_child.update(dict(wake_state))
        stopped_child["state"] = "stopped"
        stopped_child["resident_worker_state"] = "wake_fallback_superseded_by_active_child"
        stopped_child["wake_fallback_restart_count"] = int(stopped_child.get("wake_fallback_restart_count", 0) or 0) + 1
        stopped_child["wake_fallback_restarted_work_order_ids"] = sorted(restarted_ids | {work_order_id})
        stopped_child["wake_fallback_suppression_reason"] = "active_child_already_exists_for_directive"
        stopped_child["superseded_by_active_child_run_id"] = str(
            overlapping_active_children[0].get("child_run_id", "") or ""
        )
        stopped_child["updated_at"] = now
        _write_json(_child_path(operator_root, str(stopped_child.get("child_run_id", "") or "")), stopped_child)
        directive = _load_directive(operator_root, directive_id)
        if directive:
            directive_update = dict(directive)
            directive_update["state"] = "running"
            directive_update["active_child_run_id"] = str(
                overlapping_active_children[0].get("child_run_id", "") or ""
            )
            directive_update["updated_at"] = now
            metadata = dict(directive_update.get("metadata", {}) or {})
            metadata["wake_fallback_suppressed_by_active_child_run_id"] = directive_update["active_child_run_id"]
            metadata["wake_fallback_suppressed_work_order_id"] = work_order_id
            metadata["wake_fallback_suppressed_at"] = now
            directive_update["metadata"] = metadata
            _write_json(_directive_path(operator_root, directive_id), directive_update)
        _append_ledger(
            operator_root,
            "child_events",
            {
                "event": "resident_child_wake_fallback_spawn_suppressed",
                "generated_at": now,
                "old_child_run_id": str(child.get("child_run_id", "") or ""),
                "child_run_id": "",
                "directive_id": directive_id,
                "work_order_id": work_order_id,
                "spawn_suppression_reason": "active_child_already_exists_for_directive",
                "existing_active_child_run_ids": [
                    str(existing_child.get("child_run_id", "") or "")
                    for existing_child in overlapping_active_children
                    if str(existing_child.get("child_run_id", "") or "")
                ],
            },
        )
        return None
    blockers = _wake_fallback_blockers(operator_root, child, state)
    if blockers:
        updated = dict(child)
        updated.update(dict(wake_state))
        updated["wake_fallback_blockers"] = blockers
        updated["updated_at"] = _utc_now()
        _write_json(_child_path(operator_root, str(updated.get("child_run_id", "") or "")), updated)
        return None
    directive = _load_directive(operator_root, directive_id)
    if not directive:
        return None
    latest_work_order = _latest_inbox_work_order(_read_json(_child_inbox_path(child)))
    if not latest_work_order:
        latest_work_order = dict(child.get("latest_work_order", {}) or {})
    if latest_work_order:
        metadata = dict(directive.get("metadata", {}) or {})
        metadata["initial_work_order_target_artifact"] = str(latest_work_order.get("target_artifact", "") or "")
        metadata["initial_work_order_context"] = str(latest_work_order.get("next_step_context", "") or "")
        metadata["initial_work_order_capability"] = str(
            latest_work_order.get("capability", "") or "directive_build_grade_synthesis_pack"
        )
        metadata["continuous_campaign_latest_target_artifact"] = str(latest_work_order.get("target_artifact", "") or "")
        metadata["continuous_campaign_latest_action"] = "wake_fallback_restart"
        directive["metadata"] = metadata
    directive["active_child_run_id"] = ""
    directive["state"] = "requeued"
    directive["updated_at"] = _utc_now()
    _write_json(_directive_path(operator_root, directive_id), directive)
    try:
        runner.stop_child_container(dict(child))
    except Exception:
        pass
    stopped_child = dict(child)
    stopped_child.update(dict(wake_state))
    stopped_child["state"] = "stopped"
    stopped_child["resident_worker_state"] = "wake_fallback_restarted"
    stopped_child["wake_fallback_restart_count"] = int(stopped_child.get("wake_fallback_restart_count", 0) or 0) + 1
    stopped_child["wake_fallback_restarted_work_order_ids"] = sorted(restarted_ids | {work_order_id})
    stopped_child["updated_at"] = _utc_now()
    _write_json(_child_path(operator_root, str(stopped_child.get("child_run_id", "") or "")), stopped_child)
    new_child = _spawn_child_for_directive(
        operator_root,
        state_root=str(state_root or operator_root),
        directive=directive,
        runner=runner,
        scheduler=scheduler,
    )
    if bool(new_child.get("spawn_suppressed", False)):
        _append_ledger(
            operator_root,
            "child_events",
            {
                "event": "resident_child_wake_fallback_spawn_suppressed",
                "generated_at": _utc_now(),
                "old_child_run_id": str(child.get("child_run_id", "") or ""),
                "child_run_id": "",
                "directive_id": directive_id,
                "work_order_id": work_order_id,
                "spawn_suppression_reason": str(
                    new_child.get("spawn_suppression_reason", "spawn_suppressed_existing_active_child") or ""
                ),
                "existing_active_child_run_ids": list(new_child.get("existing_active_child_run_ids", []) or []),
            },
        )
        return None
    new_child["wake_fallback_restart_from_child_run_id"] = str(child.get("child_run_id", "") or "")
    new_child["wake_fallback_restart_work_order_id"] = work_order_id
    new_child["wake_fallback_restart_count"] = int(stopped_child.get("wake_fallback_restart_count", 0) or 0)
    _write_json(_child_path(operator_root, str(new_child.get("child_run_id", "") or "")), new_child)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_child_wake_fallback_restart",
            "generated_at": _utc_now(),
            "old_child_run_id": str(child.get("child_run_id", "") or ""),
            "child_run_id": str(new_child.get("child_run_id", "") or ""),
            "directive_id": directive_id,
            "work_order_id": work_order_id,
            "wake_sequence": int(request.get("wake_sequence", 0) or 0),
        },
    )
    return new_child


def _resident_target_artifact_from_progress(progress: Mapping[str, Any]) -> str:
    target = str(progress.get("target_artifact", "") or "").strip()
    if target:
        return target
    try:
        cycle_index = max(1, int(progress.get("cycle_index", 1) or 1))
    except (TypeError, ValueError):
        cycle_index = 1
    return RESIDENT_DEFAULT_TARGET_ARTIFACTS[(cycle_index - 1) % len(RESIDENT_DEFAULT_TARGET_ARTIFACTS)]


def _is_explicit_full_dive_context(directive: Mapping[str, Any]) -> bool:
    metadata = dict(directive.get("metadata", {}) or {})
    text = " ".join(
        [
            str(directive.get("directive_text", "") or ""),
            str(directive.get("directive_title", "") or ""),
            str(directive.get("title", "") or ""),
            str(metadata.get("directive_title", "") or ""),
            str(metadata.get("initial_work_order_context", "") or ""),
        ]
    ).lower()
    return "full dive" in text or "full_dive" in text or "full dive virtual simulation program" in text


def _resident_no_delta_support_threshold(
    directive: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    campaign_state: Mapping[str, Any] | None = None,
) -> int:
    target = _resident_target_artifact_from_progress(latest_progress)
    failed: set[str] = set()
    for key in ("remaining_failed_gates", "hardware_readiness_blockers", "failed_gates", "unchanged_failed_gates"):
        failed.update(str(item).strip() for item in list(latest_progress.get(key, []) or []) if str(item).strip())
    campaign = dict(campaign_state or {})
    target_quality = dict(dict(campaign.get("canonical_artifacts", {}) or {}).get(target, {}) or {})
    failed.update(
        str(item).strip()
        for item in list(target_quality.get("failed_quality_gates", []) or [])
        if str(item).strip()
    )
    hardware_assessment = dict(campaign.get("hardware_build_packet_assessment", {}) or {})
    failed.update(
        str(item).strip()
        for item in list(hardware_assessment.get("failed_gates", []) or [])
        if str(item).strip()
    )
    if _hardware_depth_missing_fields(hardware_assessment, target_artifact=target):
        failed.add("missing_full_dive_hardware_depth_fields")
    if (
        _is_explicit_full_dive_context(directive)
        and target == "interface_specifications.json"
        and "missing_full_dive_hardware_depth_fields" in failed
    ):
        return 1
    return RESIDENT_NO_DELTA_SUPPORT_THRESHOLD


def _hardware_depth_missing_fields(
    assessment: Mapping[str, Any],
    *,
    target_artifact: str = "",
) -> list[dict[str, Any]]:
    target = str(target_artifact or "").strip()
    rows: list[dict[str, Any]] = []
    for artifact, artifact_rows in dict(assessment.get("field_gaps_by_artifact", {}) or {}).items():
        artifact_name = str(artifact or "").strip()
        if target and artifact_name and artifact_name != target:
            continue
        for row in list(artifact_rows or []):
            if not isinstance(row, Mapping):
                continue
            missing_fields = [
                str(item).strip()
                for item in list(row.get("missing_fields", []) or [])
                if str(item).strip()
            ]
            if not missing_fields:
                continue
            rows.append(
                {
                    "artifact": artifact_name,
                    "row_id": str(row.get("row_id", "") or row.get("id", "") or "<row>"),
                    "missing_fields": missing_fields,
                }
            )
    if rows or not target:
        return rows
    for artifact, artifact_rows in dict(assessment.get("field_gaps_by_artifact", {}) or {}).items():
        for row in list(artifact_rows or []):
            if not isinstance(row, Mapping):
                continue
            missing_fields = [
                str(item).strip()
                for item in list(row.get("missing_fields", []) or [])
                if str(item).strip()
            ]
            if missing_fields:
                rows.append(
                    {
                        "artifact": str(artifact or "").strip(),
                        "row_id": str(row.get("row_id", "") or row.get("id", "") or "<row>"),
                        "missing_fields": missing_fields,
                    }
                )
    return rows


def _support_coverage_state(
    *,
    pack_refs: Iterable[Mapping[str, Any]],
    support_request: Mapping[str, Any],
    existing_support_refs: Iterable[Mapping[str, Any]],
) -> str:
    if list(pack_refs or []):
        return "librarian_support_refs_available"
    if list(existing_support_refs or []):
        return "support_refs_available_but_not_ranked_for_target"
    support_state = str(support_request.get("support_state", "") or "").strip()
    support_id = str(support_request.get("support_request_id", "") or "").strip()
    if support_state in {"pending_operator_review", "pending", "requested"} or support_id:
        return "directive_build_grade_synthesis_pack_requested"
    return "coverage_missing"


def _plateau_depth_obligation_fields(
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    target_artifact: str,
    campaign_state: Mapping[str, Any],
    reason: str,
) -> dict[str, Any]:
    target = str(target_artifact or "").strip()
    assessment = dict(campaign_state.get("hardware_build_packet_assessment", {}) or {})
    failed_gates = [
        str(item).strip()
        for item in list(
            dict(campaign_state.get("canonical_artifacts", {}) or {})
            .get(target, {})
            .get("failed_quality_gates", [])
            or []
        )
        if str(item).strip()
    ]
    if not failed_gates:
        failed_gates = [
            str(item).strip()
            for item in list(assessment.get("failed_gates", []) or [])
            if str(item).strip()
        ]
    missing_fields = _hardware_depth_missing_fields(assessment, target_artifact=target)
    required_evidence_refs = [
        "campaign_latest_manifest.hardware_build_packet_assessment",
        "resident_progress_latest",
    ]
    if missing_fields:
        required_evidence_refs.append("row_level_hardware_field_gaps")
    return {
        "plateau_intervention_stage": "plateau_depth_recovery",
        "depth_obligation_id": _record_id(
            "depth-obligation",
            str(child.get("directive_id", "") or ""),
            str(child.get("child_run_id", "") or ""),
            target,
            str(latest_progress.get("cycle_index", "") or ""),
            reason,
        ),
        "depth_target_artifact": target,
        "depth_missing_fields": missing_fields,
        "depth_required_evidence_refs": required_evidence_refs,
        "depth_required_gate_closures": failed_gates,
        "target_delta_required": True,
    }


def _copy_depth_obligation_to_child(updated: dict[str, Any], work_order: Mapping[str, Any]) -> None:
    for key in (
        "plateau_intervention_stage",
        "depth_obligation_id",
        "depth_target_artifact",
        "depth_missing_fields",
        "depth_source_coverage_state",
        "depth_required_evidence_refs",
        "target_delta_required",
    ):
        if key in work_order:
            updated[key] = work_order.get(key)
    if list(work_order.get("required_gate_closures", []) or []):
        updated["depth_required_gate_closures"] = list(work_order.get("required_gate_closures", []) or [])


def _append_resident_work_order(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    target_artifact: str = "",
    reason: str = "",
    schema_resonance_followup: Mapping[str, Any] | None = None,
    plateau_intervention_stage: str = "",
    depth_obligation_id: str = "",
    depth_missing_fields: Iterable[Mapping[str, Any]] | None = None,
    depth_required_evidence_refs: Iterable[str] | None = None,
    target_delta_required: bool = False,
    technology_design_mode: str = "",
    technology_design_obligations: Iterable[Mapping[str, Any]] | None = None,
    r_and_d_design_brief: Mapping[str, Any] | None = None,
    support_refs_override: Iterable[Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "")
    directive_id = str(child.get("directive_id", "") or "")
    directive = _load_directive(operator_root, directive_id)
    target_artifact = str(target_artifact or "").strip() or _resident_target_artifact_from_progress(latest_progress)
    reason = str(reason or "").strip() or (
        f"Resident worker reached {RESIDENT_NO_DELTA_SUPPORT_THRESHOLD} cycle(s) without an artifact delta "
        f"while targeting {target_artifact}."
    )
    if support_refs_override is None:
        existing_support_refs = _support_request_refs_for_directive(operator_root, directive_id)
    else:
        existing_support_refs = [
            dict(ref)
            for ref in list(support_refs_override or [])
            if isinstance(ref, Mapping)
        ]
    if existing_support_refs:
        support_request = {
            "support_request_id": "",
            "support_state": "satisfied",
            "capability": "directive_build_grade_synthesis_pack",
            "reason": "reused_satisfied_support_refs",
        }
    else:
        support_request = _support_request_from_child_request(
            operator_root,
            state_root=state_root,
            directive=directive,
            packet={
                "return_packet_id": f"resident-progress-{child_id}",
                "child_run_id": child_id,
            },
            child_request={
                "request_type": "knowledge_checkout",
                "capability": "directive_build_grade_synthesis_pack",
                "reason": reason,
            },
        )
        if support_refs_override is None:
            existing_support_refs = _support_request_refs_for_directive(operator_root, directive_id)
    inbox_path = _child_inbox_path(child)
    inbox_payload = _read_json(inbox_path)
    if not inbox_payload:
        inbox_payload = {
            "schema_name": "ConveyorChildInbox",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "generated_at": _utc_now(),
            "child_run_id": child_id,
            "directive_id": directive_id,
            "request_final_return": False,
            "stop_requested": False,
            "messages": [],
        }
    now = _utc_now()
    work_order_id = _record_id("work-order", child_id, target_artifact, str(latest_progress.get("cycle_index", "") or ""))
    campaign_manifest = _read_json(_campaign_manifest_path(operator_root, directive_id))
    hardware_build_packet_assessment = dict(
        campaign_manifest.get("hardware_build_packet_assessment", {}) or {}
    )
    hardware_fixture_contract = dict(
        hardware_build_packet_assessment.get("prototype_evidence_fixture", {}) or {}
    )
    if hardware_build_packet_assessment:
        base_fixture_contract = _hardware_build_packet_fixture_contract()
        base_fixture_contract.update(hardware_fixture_contract)
        hardware_fixture_contract = base_fixture_contract
        hardware_fixture_contract.setdefault(
            "fixture_id",
            str(hardware_build_packet_assessment.get("fixture_id", "") or "hardware_build_packet_v1"),
        )
        hardware_fixture_contract["target_artifact"] = target_artifact
        artifact_contracts = dict(hardware_fixture_contract.get("artifact_contracts", {}) or {})
        if _is_full_dive_hardware_context(directive):
            for artifact_name, contract in FULL_DIVE_HARDWARE_REQUIRED_FIELDS.items():
                existing_contract = dict(artifact_contracts.get(artifact_name, {}) or {})
                existing_contract["row_keys"] = list(contract.get("row_keys", []) or [])
                existing_contract["id_fields"] = list(contract.get("id_fields", []) or [])
                existing_contract["required_fields"] = list(contract.get("required_fields", []) or [])
                existing_contract["gates"] = list(
                    dict.fromkeys(
                        [
                            *list(existing_contract.get("gates", []) or []),
                            "missing_full_dive_hardware_depth_fields",
                        ]
                    )
                )
                artifact_contracts[artifact_name] = existing_contract
            hardware_fixture_contract["artifact_contracts"] = artifact_contracts
            hardware_fixture_contract["required_artifacts"] = list(
                dict.fromkeys(
                    [
                        *list(hardware_fixture_contract.get("required_artifacts", []) or []),
                        *FULL_DIVE_HARDWARE_DOCUMENTATION_ARTIFACTS,
                    ]
                )
            )
            hardware_fixture_contract["full_dive_required_documentation_artifacts"] = list(
                FULL_DIVE_HARDWARE_DOCUMENTATION_ARTIFACTS
            )
            hardware_fixture_contract["hardware_readiness_tiers"] = [
                "simulation_interface_ready",
                "bench_electronics_ready",
                "non_human_lab_ready",
                "human_subject_blocked",
                "unsupported_claim_blocked",
            ]
        target_contract = dict(artifact_contracts.get(target_artifact, {}) or {})
        hardware_fixture_contract["target_required_fields"] = list(
            target_contract.get("required_fields", []) or []
        )
        hardware_fixture_contract["target_artifact_contract"] = target_contract
        hardware_fixture_contract["field_gaps_by_artifact"] = dict(
            hardware_build_packet_assessment.get("field_gaps_by_artifact", {}) or {}
        )
        hardware_fixture_contract["cross_artifact_link_gaps"] = list(
            hardware_build_packet_assessment.get("cross_artifact_link_gaps", []) or []
        )
        hardware_fixture_contract["next_unresolved_artifact"] = str(
            hardware_build_packet_assessment.get("next_unresolved_artifact", "") or ""
        )
        hardware_fixture_contract["target_gate_closures"] = list(
            dict.fromkeys(
                [
                    *list(target_contract.get("gates", []) or []),
                    *list(hardware_build_packet_assessment.get("failed_gates", []) or []),
                ]
            )
        )
        hardware_fixture_contract["safety_constraints"] = {
            "network_policy": "deny_all",
            "kernel_mediated_only": True,
            "grants_execution_authority": False,
        }
    target_quality = dict(
        dict(campaign_manifest.get("canonical_artifacts", {}) or {}).get(target_artifact, {})
    )
    source_failed_quality_gates = [
        str(gate)
        for gate in list(target_quality.get("failed_quality_gates", []) or [])
        if str(gate).strip()
    ]
    prototype_cluster_closure = _assess_prototype_cluster_closure(directive, campaign_manifest)
    enrichment = _work_order_enrichment(
        operator_root,
        directive=directive,
        target_artifact=target_artifact,
        campaign_state=campaign_manifest,
        active_child=child,
    )
    pack_refs, pack_rank_summary, available_pack_ids = _rank_and_cap_support_refs(
        existing_support_refs,
        state_root=state_root or operator_root,
        directive_id=directive_id,
        target_artifact=target_artifact,
        adapter=_latest_role_specific_research_adapter(operator_root),
    )
    next_step_context = _campaign_artifact_guidance(
        target_artifact,
        fallback=(
            f"Revise {target_artifact} with directive-specific subsystem, interface, dependency, "
            "validation, milestone, claim-evidence, and novelty details. Tie material claims to checked-out "
            "Librarian/support refs where available and mark unsupported claims for operator review."
        ),
        directive=directive,
        failed_gates=list(target_quality.get("failed_quality_gates", []) or []),
    )
    fixture_row_feedback = _prototype_fixture_row_level_feedback(hardware_build_packet_assessment)
    if fixture_row_feedback:
        next_step_context = f"{next_step_context} {fixture_row_feedback}"
    proof_obligation = _active_capability_proof_obligation_for_target(
        operator_root,
        target_artifact,
    )
    proof_required_gate_closures = [
        str(gate).strip()
        for gate in list(proof_obligation.get("proof_required_gate_closures", []) or [])
        if str(gate).strip()
    ]
    if proof_obligation:
        expected_link = str(proof_obligation.get("proof_expected_next_link", "") or "")
        receipt_id = str(proof_obligation.get("proof_target_receipt_id", "") or "")
        next_step_context = (
            f"{next_step_context} This work order is bound to proof obligation "
            f"{proof_obligation.get('capability_proof_obligation_id', '')}: produce a concrete delta for "
            f"{target_artifact}, close required gates {proof_required_gate_closures}, and satisfy "
            f"{expected_link or 'the next proof link'} for receipt {receipt_id or 'unrecorded'}."
        )
    schema_followup = dict(schema_resonance_followup or {})
    missing_top_level_fields = [
        str(item).strip()
        for item in list(schema_followup.get("missing_top_level_fields", []) or [])
        if str(item).strip()
    ]
    required_top_level_fields = [
        str(item).strip()
        for item in list(schema_followup.get("required_top_level_fields", []) or missing_top_level_fields)
        if str(item).strip()
    ]
    raw_schema_skeleton = schema_followup.get("artifact_top_level_schema_skeleton", {})
    if isinstance(raw_schema_skeleton, Mapping):
        artifact_top_level_schema_skeleton = dict(raw_schema_skeleton)
    else:
        artifact_top_level_schema_skeleton = _schema_followup_skeleton(
            raw_schema_skeleton or required_top_level_fields
        )
    if required_top_level_fields:
        artifact_top_level_schema_skeleton = {
            **_schema_followup_skeleton(required_top_level_fields),
            **artifact_top_level_schema_skeleton,
        }
    schema_resonance_followup_required = bool(schema_followup.get("schema_resonance_followup_required", False))
    persistent_schema_contract = _active_schema_contract_for_artifact(
        child,
        campaign_manifest,
        target_artifact,
    )
    persistent_schema_contract_required = bool(
        persistent_schema_contract
        and not schema_resonance_followup_required
    )
    if persistent_schema_contract:
        persistent_required = [
            str(item).strip()
            for item in list(persistent_schema_contract.get("required_top_level_fields", []) or [])
            if str(item).strip()
        ]
        if persistent_required:
            required_top_level_fields = list(dict.fromkeys([*required_top_level_fields, *persistent_required]))
            persistent_skeleton = persistent_schema_contract.get("artifact_top_level_schema_skeleton", {})
            artifact_top_level_schema_skeleton = {
                **_schema_followup_skeleton(required_top_level_fields),
                **artifact_top_level_schema_skeleton,
                **(dict(persistent_skeleton) if isinstance(persistent_skeleton, Mapping) else {}),
            }
    try:
        schema_resonance_score = float(schema_followup.get("schema_resonance_score", 1.0) or 0.0)
    except (TypeError, ValueError):
        schema_resonance_score = 0.0
    required_gate_closures = list(
        dict.fromkeys([*source_failed_quality_gates, *proof_required_gate_closures])
    )
    normalized_depth_missing_fields = [
        dict(item)
        for item in list(depth_missing_fields or [])
        if isinstance(item, Mapping)
    ]
    normalized_depth_evidence_refs = [
        str(item).strip()
        for item in list(depth_required_evidence_refs or [])
        if str(item).strip()
    ]
    normalized_technology_design_obligations = [
        dict(item)
        for item in list(technology_design_obligations or [])
        if isinstance(item, Mapping)
    ]
    normalized_r_and_d_design_brief = (
        dict(r_and_d_design_brief) if isinstance(r_and_d_design_brief, Mapping) else {}
    )
    if target_delta_required:
        next_step_context = (
            f"{next_step_context} Plateau recovery requires a concrete post-obligation delta "
            f"for {target_artifact}; do not return from unchanged artifacts."
        )
    if technology_design_mode:
        next_step_context = (
            f"{next_step_context} This is an R&D design obligation: design the missing technology "
            "or integration boundary, cite the mounted design rows, and keep hardware build-ready false "
            "until the design is reduced to concrete source-backed build evidence."
        )
    depth_source_coverage_state = _support_coverage_state(
        pack_refs=pack_refs,
        support_request=support_request,
        existing_support_refs=existing_support_refs,
    )
    message = {
        "kind": "kernel_work_order",
        "schema_name": "ConveyorChildWorkOrder",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "work_order_id": work_order_id,
        "generated_at": now,
        "child_run_id": child_id,
        "directive_id": directive_id,
        "capability": "directive_build_grade_synthesis_pack",
        "support_request_id": str(support_request.get("support_request_id", "") or ""),
        "support_state": str(support_request.get("support_state", "") or ""),
        "target_artifact": target_artifact,
        "next_step_context": next_step_context,
        "quality_failed_gates": list(target_quality.get("failed_quality_gates", []) or []),
        "quality_state": str(target_quality.get("quality_state", "") or ""),
        "quality_depth_score": float(target_quality.get("quality_depth_score", 0.0) or 0.0),
        "allowed_pack_refs": pack_refs,
        "support_pack_rank_summary": pack_rank_summary,
        "omitted_support_pack_ref_count": max(0, len(available_pack_ids) - len(pack_refs)),
        "available_support_pack_ids": available_pack_ids,
        "plateau_intervention_stage": str(plateau_intervention_stage or ""),
        "depth_obligation_id": str(depth_obligation_id or ""),
        "depth_target_artifact": target_artifact if depth_obligation_id or target_delta_required else "",
        "depth_missing_fields": normalized_depth_missing_fields,
        "depth_source_coverage_state": depth_source_coverage_state,
        "depth_required_evidence_refs": normalized_depth_evidence_refs,
        "target_delta_required": bool(target_delta_required),
        "technology_design_mode": str(technology_design_mode or ""),
        "technology_design_obligations": normalized_technology_design_obligations,
        "r_and_d_design_brief": normalized_r_and_d_design_brief,
        "research_design_readiness_state": (
            "design_work_requested" if technology_design_mode else ""
        ),
        "artifact_level_failed_gate_target": bool(source_failed_quality_gates),
        "source_failed_quality_gates": source_failed_quality_gates,
        "required_gate_closures": required_gate_closures,
        "capability_proof_obligation_id": str(
            proof_obligation.get("capability_proof_obligation_id", "") or ""
        ),
        "proof_target_capability_kind": str(
            proof_obligation.get("proof_target_capability_kind", "") or ""
        ),
        "proof_target_receipt_id": str(
            proof_obligation.get("proof_target_receipt_id", "") or ""
        ),
        "proof_target_artifact": str(
            proof_obligation.get("proof_target_artifact", "") or ""
        ),
        "proof_required_gate_closures": proof_required_gate_closures,
        "proof_expected_next_link": str(
            proof_obligation.get("proof_expected_next_link", "") or ""
        ),
        "prototype_cluster_requirements": {
            "closure_family": str(prototype_cluster_closure.get("cluster_family", "") or ""),
            "cluster_closed": bool(prototype_cluster_closure.get("cluster_closed", False)),
            "missing_cluster_gates": list(prototype_cluster_closure.get("missing_cluster_gates", []) or []),
            "artifact_gate_map": dict(prototype_cluster_closure.get("artifact_gate_map", {}) or {}),
            "next_unresolved_artifact": str(prototype_cluster_closure.get("next_unresolved_artifact", "") or ""),
        },
        "prototype_evidence_fixture": hardware_fixture_contract,
        "schema_resonance_followup_required": schema_resonance_followup_required,
        "persistent_schema_contract_required": persistent_schema_contract_required,
        "schema_resonance_score": schema_resonance_score,
        "required_top_level_fields": required_top_level_fields,
        "missing_top_level_fields": missing_top_level_fields,
        "artifact_top_level_schema_skeleton": artifact_top_level_schema_skeleton,
        **enrichment,
        "grants_execution_authority": False,
        "network_policy": "deny_all",
        "kernel_mediated_only": True,
    }
    if hardware_fixture_contract:
        message["prototype_evidence_fixture"] = hardware_fixture_contract
    message["work_order_signature"] = _resident_work_order_signature(message)
    existing = _latest_inbox_work_order(inbox_payload)
    if str(existing.get("work_order_signature", "") or "") == str(message["work_order_signature"]):
        duplicate_count = int(inbox_payload.get("resident_work_order_duplicate_suppressed_count", 0) or 0) + 1
        inbox_payload["resident_work_order_duplicate_suppressed_count"] = duplicate_count
        inbox_payload["updated_at"] = now
        inbox_payload = _compact_resident_inbox_work_orders(inbox_payload)
        wake_reason = _resident_work_order_wake_reason(existing, reason)
        if wake_reason:
            inbox_payload = _request_resident_child_wake(
                operator_root,
                child=child,
                inbox_payload=inbox_payload,
                inbox_path=inbox_path,
                work_order=existing,
                wake_reason=wake_reason,
            )
        else:
            _write_json(inbox_path, inbox_payload)
        _append_ledger(
            operator_root,
            "child_events",
            {
                "event": "resident_work_order_duplicate_suppressed",
                "generated_at": now,
                "child_run_id": child_id,
                "directive_id": directive_id,
                "work_order_id": str(existing.get("work_order_id", "") or ""),
                "suppressed_work_order_id": work_order_id,
                "work_order_signature": str(message["work_order_signature"]),
                "target_artifact": target_artifact,
                "suppressed_count": duplicate_count,
            },
        )
        existing["work_order_signature"] = str(message["work_order_signature"])
        return existing
    _record_role_research_adapter_consumption(
        operator_root,
        work_order=message,
        baseline_action="inject_quality_gap_work_order",
        final_action="inject_role_adapter_shaped_work_order",
        reason=str(enrichment.get("target_selection_reason", "") or reason),
    )
    messages = list(inbox_payload.get("messages", []) or [])
    messages.append(message)
    inbox_payload["messages"] = messages
    inbox_payload["updated_at"] = now
    inbox_payload["request_final_return"] = False
    inbox_payload["stop_requested"] = False
    wake_reason = _resident_work_order_wake_reason(message, reason)
    if wake_reason:
        inbox_payload = _request_resident_child_wake(
            operator_root,
            child=child,
            inbox_payload=inbox_payload,
            inbox_path=inbox_path,
            work_order=message,
            wake_reason=wake_reason,
        )
    inbox_payload = _compact_resident_inbox_work_orders(inbox_payload)
    _write_json(inbox_path, inbox_payload)
    _append_ledger(operator_root, "child_events", {"event": "resident_work_order_injected", **message})
    return message


def _materialize_support_for_running_resident_child(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    target_artifact: str,
    support_request: Mapping[str, Any],
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "")
    directive_id = str(child.get("directive_id", "") or "")
    support_pack_target_artifact = (
        "" if str(target_artifact or "").strip() == "implementation_readiness_review.json" else target_artifact
    )
    support_request_id = str(support_request.get("support_request_id", "") or "").strip()
    current_ref = _support_pack_ref_from_support_request(operator_root, support_request)
    refs: list[dict[str, Any]] = []
    if current_ref:
        refs.append(current_ref)
    elif support_request_id:
        refs = [
            dict(ref)
            for ref in _support_request_refs_for_directive(operator_root, directive_id)
            if str(ref.get("support_request_id", "") or "").strip() == support_request_id
        ][:3]
    if not refs:
        return {
            "ok": False,
            "support_materialization_state": "current_support_pack_ref_missing",
            "support_pack_rows_available": 0,
        }
    pack_refs, rank_summary, available_pack_ids = _rank_and_cap_support_refs(
        refs,
        state_root=state_root,
        directive_id=directive_id,
        target_artifact=support_pack_target_artifact,
        adapter=_latest_role_specific_research_adapter(operator_root),
    )
    support_checkout = _materialize_child_support_pack_checkout(
        operator_root,
        state_root=state_root,
        child_run_id=child_id,
        pack_refs=pack_refs,
        target_artifact=support_pack_target_artifact,
    )
    manifest = dict(support_checkout.get("support_pack_manifest", {}) or {})
    row_count = int(manifest.get("total_row_count", 0) or 0)
    if row_count <= 0:
        return {
            "ok": False,
            "support_materialization_state": "no_consumable_rows",
            "support_pack_rows_available": 0,
        }
    required_fields = _support_request_required_fields(support_request, latest_progress)
    coverage = _support_pack_coverage_assessment(
        manifest,
        target_artifact=target_artifact,
        required_fields=required_fields,
    )
    directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    role_required = [
        str(role)
        for split in list(
            dict(assess_operator_feedback_obligations(str(directive.get("operator_feedback", "") or "")).get(
                "operator_feedback_obligations", {}
            ) or {}).get("required_role_splits", [])
            or []
        )
        if isinstance(split, Mapping)
        and str(split.get("artifact_name", "") or target_artifact) == target_artifact
        and normalize_support_role_lane(split.get("base_role", "")) == "sensor_array"
        for role in list(split.get("required_roles", []) or [])
    ]
    role_required = list(dict.fromkeys(normalize_support_role_lane(role) for role in role_required if str(role).strip()))
    role_covered = list(
        dict.fromkeys(
            normalize_support_role_lane(role)
            for role in list(manifest.get("support_role_lane_covered_roles", []) or [])
            if normalize_support_role_lane(role)
        )
    )
    role_uncovered = [role for role in role_required if role not in set(role_covered)]
    coverage_state = str(coverage.get("support_adequacy_state", "") or "")
    if coverage_state in {"adequate", "not_required"} and role_uncovered:
        coverage_state = "insufficient_role_lane_coverage"
        coverage = {
            **coverage,
            "support_adequacy_state": coverage_state,
            "support_uncovered_missing_fields": role_uncovered,
            "support_role_lane_required_roles": role_required,
            "support_role_lane_covered_roles": role_covered,
            "support_role_lane_uncovered_roles": role_uncovered,
        }
    if coverage_state not in {"adequate", "not_required"}:
        now = _utc_now()
        support_request_id = str(support_request.get("support_request_id", "") or "")
        if support_request_id:
            support_payload = dict(_read_json(_support_request_path(operator_root, support_request_id)) or support_request)
            support_payload["support_state"] = "pending_operator_review"
            support_payload["operator_review_required"] = True
            support_payload["support_materialization_state"] = "waiting_for_required_field_coverage"
            support_payload["post_materialization_support_adequacy_state"] = coverage_state
            support_payload["post_materialization_uncovered_fields"] = list(
                coverage.get("support_uncovered_missing_fields", []) or []
            )
            support_payload["support_wake_suppressed_reason"] = coverage_state
            support_payload["updated_at"] = now
            _write_json(_support_request_path(operator_root, support_request_id), support_payload)
        _append_ledger(
            operator_root,
            "support_request_events",
            {
                "event": "resident_support_wake_suppressed",
                "generated_at": now,
                "child_run_id": child_id,
                "directive_id": directive_id,
                "support_request_id": support_request_id,
                "target_artifact": target_artifact,
                "support_wake_suppressed_reason": coverage_state,
                "post_materialization_uncovered_fields": list(
                    coverage.get("support_uncovered_missing_fields", []) or []
                ),
                "grants_execution_authority": False,
            },
        )
        return {
            "ok": False,
            "support_materialization_state": "waiting_for_required_field_coverage",
            "support_pack_rows_available": row_count,
            "post_materialization_support_adequacy_state": coverage_state,
            "post_materialization_uncovered_fields": list(
                coverage.get("support_uncovered_missing_fields", []) or []
            ),
            "support_wake_suppressed_reason": coverage_state,
        }
    technology_design_active = bool(support_request.get("technology_design_obligation_active", False))
    technology_design_obligations = [
        dict(item)
        for item in list(support_request.get("technology_design_obligations", []) or [])
        if isinstance(item, Mapping)
    ]
    if not technology_design_obligations:
        for obligation_id in list(support_request.get("technology_design_obligation_ids", []) or []):
            obligation_text = str(obligation_id or "").strip()
            if obligation_text:
                technology_design_obligations.append(
                    {
                        "technology_design_obligation_id": obligation_text,
                        "target_artifact": target_artifact,
                        "gap_kind": "technology_design_needed",
                    }
                )
    r_and_d_design_brief = dict(support_request.get("r_and_d_design_brief", {}) or {})
    brief_id = str(support_request.get("r_and_d_design_brief_id", "") or "")
    if brief_id and not r_and_d_design_brief:
        r_and_d_design_brief = {
            "r_and_d_design_brief_id": brief_id,
            "target_artifact": target_artifact,
            "missing_fields": required_fields,
        }
    work_order = _append_resident_work_order(
        operator_root,
        state_root=state_root,
        child=child,
        latest_progress=latest_progress,
        target_artifact=target_artifact,
        reason=(
            f"Support request {support_request.get('support_request_id', '')} is satisfied with "
            f"{row_count} consumable support row(s); continue {target_artifact} using checked-out evidence."
        ),
        technology_design_mode="r_and_d_design" if technology_design_active else "",
        technology_design_obligations=technology_design_obligations,
        r_and_d_design_brief=r_and_d_design_brief,
        support_refs_override=pack_refs,
    )
    inbox_path = _child_inbox_path(child)
    inbox_payload = _read_json(inbox_path)
    if inbox_payload:
        wake_reason = _resident_work_order_wake_reason(work_order, "quality support injected")
        if wake_reason:
            inbox_payload = _request_resident_child_wake(
                operator_root,
                child=child,
                inbox_payload=inbox_payload,
                inbox_path=inbox_path,
                work_order=work_order,
                wake_reason=wake_reason,
                force=True,
            )
            inbox_payload = _compact_resident_inbox_work_orders(inbox_payload)
            _write_json(inbox_path, inbox_payload)
    now = _utc_now()
    updated_child = dict(_read_json(_child_path(operator_root, child_id)) or child)
    updated_child["support_pack_rank_summary"] = rank_summary
    updated_child["available_support_pack_ids"] = available_pack_ids
    updated_child["omitted_support_pack_ref_count"] = max(0, len(available_pack_ids) - len(pack_refs))
    updated_child["support_pack_checkout_path"] = str(support_checkout.get("host_support_pack_checkout_path", "") or "")
    updated_child["support_pack_manifest"] = manifest
    updated_child["support_pack_bytes"] = int(support_checkout.get("support_pack_bytes", 0) or 0)
    updated_child["support_pack_rows_available"] = row_count
    updated_child["post_materialization_support_adequacy_state"] = coverage_state
    updated_child["post_materialization_uncovered_fields"] = list(
        coverage.get("support_uncovered_missing_fields", []) or []
    )
    updated_child["support_materialization_state"] = "support_checkout_refreshed"
    updated_child["support_checkout_refreshed_at"] = now
    updated_child["wake_work_order_id"] = str(work_order.get("work_order_id", "") or "")
    updated_child["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
    updated_child["latest_work_order_target_artifact"] = str(work_order.get("target_artifact", "") or target_artifact)
    updated_child["latest_work_order_at"] = str(work_order.get("generated_at", "") or now)
    updated_child["latest_work_order"] = dict(work_order)
    updated_child["resident_worker_state"] = "support_checkout_refreshed"
    updated_child["updated_at"] = now
    _write_json(_child_path(operator_root, child_id), updated_child)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_support_checkout_refreshed",
            "generated_at": now,
            "child_run_id": child_id,
            "directive_id": directive_id,
            "support_request_id": str(support_request.get("support_request_id", "") or ""),
            "target_artifact": target_artifact,
            "work_order_id": str(work_order.get("work_order_id", "") or ""),
            "support_pack_rows_available": row_count,
            "grants_execution_authority": False,
        },
    )
    return {
        "ok": True,
        "support_materialization_state": "support_checkout_refreshed",
        "support_pack_rows_available": row_count,
        "work_order_id": str(work_order.get("work_order_id", "") or ""),
        "support_pack_manifest": manifest,
        "post_materialization_support_adequacy_state": coverage_state,
        "post_materialization_uncovered_fields": list(
            coverage.get("support_uncovered_missing_fields", []) or []
        ),
    }


def _park_support_blocked_resident_child(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    directive: Mapping[str, Any],
    support_request: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    runner: ConveyorChildRunner,
    target_artifact: str,
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "")
    directive_id = str(child.get("directive_id", "") or directive.get("directive_id", "") or "")
    support_request_id = str(support_request.get("support_request_id", "") or "")
    idempotency_key = _record_id(
        "support-blocked-park",
        directive_id,
        child_id,
        support_request_id,
        str(latest_progress.get("work_order_id", "") or child.get("latest_work_order_id", "") or ""),
        target_artifact,
    )
    existing_child = _read_json(_child_path(operator_root, child_id)) if child_id else {}
    if str(existing_child.get("support_blocked_park_idempotency_key", "") or "") == idempotency_key:
        return {
            "ok": True,
            "already_applied": True,
            "support_blocked_child_parked": True,
            "support_blocked_park_idempotency_key": idempotency_key,
        }
    stop_result: dict[str, Any] = {}
    try:
        stop_result = dict(runner.stop_child_container(dict(child)) or {})
    except Exception as exc:
        stop_result = {"ok": False, "state": "stop_failed", "error_class": type(exc).__name__}
    now = _utc_now()
    updated_child = dict(existing_child or child)
    updated_child["state"] = "stopped" if bool(stop_result.get("ok", False)) else "blocked"
    updated_child["stop_requested"] = True
    updated_child["stop_result"] = stop_result
    updated_child["resident_worker_state"] = "parked_for_support"
    updated_child["support_materialization_state"] = "parked_waiting_for_consumable_support"
    updated_child["support_blocker_reason"] = "no_consumable_support_rows"
    updated_child["support_blocked_park_idempotency_key"] = idempotency_key
    updated_child["latest_support_request_id"] = support_request_id
    updated_child["support_request_id"] = support_request_id
    updated_child["latest_target_artifact"] = target_artifact
    updated_child["updated_at"] = now
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated_child)
    support = dict(support_request)
    support["support_state"] = "pending_operator_review"
    support["operator_review_required"] = True
    support["candidate_ingestion_state"] = str(support.get("candidate_ingestion_state", "") or "pending_support")
    support["support_materialization_state"] = "parked_waiting_for_consumable_support"
    support["support_blocker_reason"] = "no_consumable_support_rows"
    support["support_blocked_child_run_id"] = child_id
    support["support_blocked_park_idempotency_key"] = idempotency_key
    support["updated_at"] = now
    if support_request_id:
        _write_json(_support_request_path(operator_root, support_request_id), support)
    if directive_id:
        directive_payload = dict(_read_json(_directive_path(operator_root, directive_id)) or directive)
        directive_payload["state"] = "blocked_for_support"
        directive_payload["active_child_run_id"] = ""
        metadata = dict(directive_payload.get("metadata", {}) or {})
        metadata["support_blocker_reason"] = "no_consumable_support_rows"
        metadata["support_request_id"] = support_request_id
        metadata["support_blocker_target_artifact"] = target_artifact
        metadata["support_blocked_child_run_id"] = child_id
        metadata["support_blocked_park_idempotency_key"] = idempotency_key
        metadata["support_blocked_at"] = now
        directive_payload["metadata"] = metadata
        directive_payload["updated_at"] = now
        _write_json(_directive_path(operator_root, directive_id), directive_payload)
        release_task_manager_lease(
            operator_root,
            directive_id=directive_id,
            child_run_id=child_id,
            reason="support_blocked_no_consumable_rows",
        )
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_child_parked_for_support",
            "generated_at": now,
            "child_run_id": child_id,
            "directive_id": directive_id,
            "support_request_id": support_request_id,
            "target_artifact": target_artifact,
            "support_blocker_reason": "no_consumable_support_rows",
            "support_blocked_park_idempotency_key": idempotency_key,
            "grants_execution_authority": False,
        },
    )
    try:
        build_task_manager_snapshot(operator_root, persist=True)
    except Exception:
        pass
    return {
        "ok": bool(stop_result.get("ok", False)),
        "already_applied": False,
        "support_blocked_child_parked": True,
        "support_blocked_park_idempotency_key": idempotency_key,
        "support_request_id": support_request_id,
        "target_artifact": target_artifact,
        "stop_result": stop_result,
    }


def _support_request_auto_approval_worker(
    operator_root: str,
    state_root: str,
    support_request_id: str,
    queue: Any,
) -> None:
    try:
        queue.put(
            {
                "ok": True,
                "result": approve_conveyor_support_request(
                    operator_root,
                    state_root=state_root,
                    support_request_id=support_request_id,
                ),
            }
        )
    except Exception as exc:  # pragma: no cover - child process defensive path.
        queue.put({"ok": False, "error_type": type(exc).__name__, "error": str(exc)})


def _run_conveyor_module_json_worker(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    command: str,
    timeout_seconds: float,
    extra_args: Iterable[str] = (),
) -> dict[str, Any]:
    worker_root = _conveyor_root(operator_root) / "worker_results"
    worker_root.mkdir(parents=True, exist_ok=True)
    result_path = worker_root / f"{command}-{uuid.uuid4().hex}.json"
    package_root = Path(__file__).resolve().parents[1]
    env = dict(os.environ)
    prior_pythonpath = str(env.get("PYTHONPATH", "") or "")
    env["PYTHONPATH"] = (
        str(package_root)
        if not prior_pythonpath
        else str(package_root) + os.pathsep + prior_pythonpath
    )
    argv = [
        sys.executable,
        "-m",
        "operator_shell.conveyor",
        command,
        "--operator-root",
        str(operator_root),
        "--state-root",
        str(state_root),
        "--result-path",
        str(result_path),
        *[str(item) for item in extra_args],
    ]
    process = subprocess.Popen(
        argv,
        cwd=str(package_root),
        env=env,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        start_new_session=True,
    )
    try:
        return_code = process.wait(timeout=timeout_seconds)
    except subprocess.TimeoutExpired:
        process.terminate()
        try:
            process.wait(timeout=1.0)
        except subprocess.TimeoutExpired:
            try:
                process.kill()
            except OSError:
                pass
        return {
            "ok": False,
            "worker_started": True,
            "worker_pid": int(process.pid or 0),
            "worker_timed_out": True,
            "result_path": str(result_path),
        }
    message = _read_json(result_path)
    try:
        result_path.unlink(missing_ok=True)
    except OSError:
        pass
    if not message:
        return {
            "ok": False,
            "worker_started": True,
            "worker_pid": int(process.pid or 0),
            "worker_returncode": int(return_code or 0),
            "error_type": "MissingWorkerResult",
            "error": "worker exited without writing a result file",
        }
    message["worker_started"] = True
    message["worker_pid"] = int(process.pid or 0)
    message["worker_returncode"] = int(return_code or 0)
    return message


def _approve_conveyor_support_request_bounded(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    support_request_id: str,
    timeout_seconds: float | None = None,
) -> dict[str, Any]:
    timeout = max(
        0.0,
        float(
            RESIDENT_SUPPORT_TICK_TRUSTED_SOURCE_TIMEOUT_SECONDS
            if timeout_seconds is None
            else timeout_seconds
        ),
    )
    if timeout <= 0.0:
        return approve_conveyor_support_request(
            operator_root,
            state_root=str(state_root),
            support_request_id=support_request_id,
        )
    if timeout < 0.05:
        return {
            "ok": False,
            "message": "Trusted-source support approval timed out.",
            "details": ["resident_support_trusted_source_timeout"],
            "control_plane_degraded_reason": "resident_support_trusted_source_timeout",
            "timeout_seconds": timeout,
            "trusted_source_worker_started": False,
        }
    try:
        message = _run_conveyor_module_json_worker(
            operator_root,
            state_root=state_root,
            command="support-request-auto-approval",
            timeout_seconds=timeout,
            extra_args=("--support-request-id", support_request_id),
        )
        if bool(message.get("worker_timed_out", False)):
            return {
                "ok": False,
                "message": "Trusted-source support approval timed out.",
                "details": ["resident_support_trusted_source_timeout"],
                "control_plane_degraded_reason": "resident_support_trusted_source_timeout",
                "timeout_seconds": timeout,
                "trusted_source_worker_started": bool(message.get("worker_started", False)),
                "trusted_source_worker_terminated": True,
            }
        if bool(message.get("ok", False)):
            return dict(message.get("result", {}) or {})
        return {
            "ok": False,
            "message": "Trusted-source support approval failed.",
            "details": [str(message.get("error_type", "") or "support_approval_failed")],
            "error": str(message.get("error", "") or ""),
            "control_plane_degraded_reason": "resident_support_trusted_source_failed",
        }
    except Exception as exc:  # pragma: no cover - defensive fail-soft path for live control plane.
        return {
            "ok": False,
            "message": "Trusted-source support approval failed.",
            "details": [type(exc).__name__],
            "error": str(exc),
            "control_plane_degraded_reason": "resident_support_trusted_source_failed",
        }


def _support_synthesis_job_id(
    support_request_id: str,
    *,
    contract_fingerprint: str = "",
) -> str:
    return _record_id(
        "support-synthesis",
        str(support_request_id or ""),
        str(contract_fingerprint or ""),
    )


def _support_synthesis_contract_fingerprint(context: Mapping[str, Any]) -> str:
    rows = []
    for row in list(context.get("requested_rows", []) or []):
        if not isinstance(row, Mapping):
            continue
        rows.append(
            {
                "requested_row_id": str(row.get("requested_row_id", "") or ""),
                "target_artifact": str(row.get("target_artifact", "") or ""),
                "target_row_id": str(row.get("target_row_id", "") or ""),
                "target_role": str(row.get("target_role", "") or ""),
                "decomposed_from_requested_row_id": str(
                    row.get("decomposed_from_requested_row_id", "") or ""
                ),
                "required_fields": [
                    str(item or "")
                    for item in list(row.get("required_fields", []) or [])
                    if str(item or "")
                ],
            }
        )
    payload = {
        "support_request_id": str(context.get("support_request_id", "") or ""),
        "target_artifact": str(context.get("target_artifact", "") or ""),
        "requested_rows": rows,
        "uncovered_requested_row_ids": [
            str(item or "")
            for item in list(context.get("uncovered_requested_row_ids", []) or [])
            if str(item or "")
        ],
        "abstract_lane_promoted_from_metadata_requested_row_ids": [
            str(item or "")
            for item in list(
                context.get("abstract_lane_promoted_from_metadata_requested_row_ids", [])
                or []
            )
            if str(item or "")
        ],
    }
    digest = hashlib.sha256(json.dumps(payload, sort_keys=True).encode("utf-8")).hexdigest()
    return digest[:16]


def _trusted_source_provider_rate_limited(*values: Any) -> bool:
    text = " ".join(str(value or "") for value in values).lower()
    if re.search(r"(?<!\d)429(?!\d)", text):
        return True
    return "rate limit" in text or "rate_limit" in text or "too many requests" in text


def _support_synthesis_rate_limit_retry_after() -> tuple[int, str]:
    raw = str(os.environ.get("NOVALI_SUPPORT_SYNTHESIS_RATE_LIMIT_BACKOFF_SECONDS", "900") or "900")
    try:
        seconds = max(60, int(float(raw)))
    except (TypeError, ValueError):
        seconds = 900
    retry_at = datetime.fromtimestamp(time.time() + seconds, tz=timezone.utc)
    return seconds, retry_at.replace(microsecond=0).isoformat()


def _support_synthesis_external_attempt_cap() -> int:
    raw = str(os.environ.get("NOVALI_SUPPORT_SYNTHESIS_MAX_EXTERNAL_ATTEMPTS_PER_SUPPORT", "2") or "2")
    try:
        return max(1, int(float(raw)))
    except (TypeError, ValueError):
        return 2


def _read_autonomy_ledger_tail_for_support(
    operator_root: str | Path,
    ledger_name: str,
    support_request_id: str,
    *,
    limit: int = 2000,
) -> list[dict[str, Any]]:
    support_id = str(support_request_id or "").strip()
    if not support_id:
        return []
    path = autonomy_root(operator_root) / "ledgers" / f"{ledger_name}.jsonl"
    if not path.exists():
        return []
    rows: deque[dict[str, Any]] = deque(maxlen=max(1, int(limit or 1)))
    try:
        with path.open("r", encoding="utf-8") as handle:
            for line in handle:
                text = line.strip()
                if not text:
                    continue
                try:
                    payload = json.loads(text)
                except json.JSONDecodeError:
                    continue
                if not isinstance(payload, Mapping):
                    continue
                if (
                    str(payload.get("support_request_id", "") or "").strip() == support_id
                    or str(payload.get("current_provider_support_request_id", "") or "").strip()
                    == support_id
                ):
                    rows.append(dict(payload))
    except OSError:
        return []
    return list(rows)


def _support_synthesis_attempt_budget_epoch(
    source_plan_rows: Iterable[Mapping[str, Any]],
) -> tuple[datetime | None, str]:
    epoch_at: datetime | None = None
    epoch_state = ""
    raw_min_age = str(
        os.environ.get("NOVALI_SUPPORT_SYNTHESIS_BUDGET_EPOCH_MIN_AGE_SECONDS", "60")
        or "60"
    )
    try:
        min_age_seconds = max(0, int(float(raw_min_age)))
    except (TypeError, ValueError):
        min_age_seconds = 60
    newest_eligible_at = datetime.now(timezone.utc) - timedelta(seconds=min_age_seconds)
    for row in source_plan_rows:
        has_queries = bool(
            list(row.get("generated_search_queries", []) or [])
            or list(row.get("search_queries", []) or [])
            or list(row.get("source_query_requested_row_ids", []) or [])
        )
        if not has_queries:
            continue
        has_external_result = bool(
            str(row.get("trusted_source_response_status", "") or "").strip()
            or str(row.get("trusted_source_failure_class", "") or "").strip()
            or str(row.get("trusted_source_rejection_reason", "") or "").strip()
        )
        if has_external_result:
            continue
        freshness_state = str(row.get("provider_latest_freshness_state", "") or "").strip()
        query_state = str(row.get("source_query_generation_state", "") or "").strip()
        if freshness_state != "current_support_request" and query_state != "generated":
            continue
        candidate_at = _parse_utc_time(row.get("generated_at", "") or row.get("created_at", ""))
        if candidate_at is None:
            continue
        if candidate_at > newest_eligible_at:
            continue
        if epoch_at is None or candidate_at > epoch_at:
            epoch_at = candidate_at
            epoch_state = "current_source_plan_epoch"
    return epoch_at, epoch_state


def _support_budget_row_after_epoch(
    row: Mapping[str, Any],
    epoch_at: datetime | None,
) -> bool:
    if epoch_at is None:
        return True
    row_at = _parse_utc_time(row.get("generated_at", "") or row.get("created_at", ""))
    if row_at is None:
        return True
    return row_at > epoch_at


def _persisted_support_budget_epoch(
    operator_root: str | Path,
    support_request_id: str,
) -> tuple[datetime | None, str]:
    support_id = str(support_request_id or "").strip()
    if not support_id:
        return None, ""
    support = _read_json(
        _conveyor_root(operator_root)
        / "support_requests"
        / f"{_safe_slug(support_id, fallback='support-request')}.json"
    )
    if str(support.get("support_request_id", "") or "").strip() != support_id:
        return None, ""
    epoch_state = str(
        support.get("support_external_request_budget_epoch_state", "") or ""
    ).strip()
    if epoch_state != "current_source_plan_epoch":
        return None, ""
    epoch_at = _parse_utc_time(support.get("support_external_request_budget_epoch_at", ""))
    if epoch_at is None:
        return None, ""
    return epoch_at, epoch_state


def _rate_limit_retry_budget_epoch(support: Mapping[str, Any]) -> tuple[datetime | None, str]:
    if not bool(support.get("provider_rate_limited", False)) and not bool(
        support.get("support_synthesis_backoff_required", False)
    ):
        return None, ""
    retry_at = _parse_utc_time(support.get("support_synthesis_next_retry_after", ""))
    if retry_at is None:
        started_at = _parse_utc_time(support.get("support_synthesis_backoff_started_at", ""))
        if started_at is None:
            return None, ""
        try:
            retry_after_seconds = int(support.get("support_synthesis_retry_after_seconds", 900) or 900)
        except (TypeError, ValueError):
            retry_after_seconds = 900
        retry_at = started_at + timedelta(seconds=max(60, retry_after_seconds))
    if retry_at > datetime.now(timezone.utc):
        return None, ""
    return retry_at, "rate_limit_retry_window_epoch"


def _support_synthesis_external_attempt_budget(
    operator_root: str | Path,
    support_request_id: str,
) -> dict[str, Any]:
    cap = _support_synthesis_external_attempt_cap()
    support_id = str(support_request_id or "").strip()
    if not support_id:
        return {
            "external_request_budget_state": "unscoped",
            "support_external_request_attempt_count": 0,
            "support_external_request_attempt_cap": cap,
            "support_external_request_budget_exhausted": False,
            "support_external_request_budget_epoch_state": "",
            "support_external_request_budget_epoch_at": "",
        }
    source_plan_rows = _read_autonomy_ledger_tail_for_support(
        operator_root,
        "directive_support_source_plans",
        support_id,
    )
    latest_source_plan = _read_json(
        autonomy_root(operator_root) / "directive_support_source_plan_latest.json"
    )
    if latest_source_plan and (
        str(latest_source_plan.get("support_request_id", "") or "").strip() == support_id
        or str(latest_source_plan.get("current_provider_support_request_id", "") or "").strip()
        == support_id
    ):
        source_plan_rows.append(dict(latest_source_plan))
    epoch_at, epoch_state = _support_synthesis_attempt_budget_epoch(source_plan_rows)
    support = _read_json(
        _conveyor_root(operator_root)
        / "support_requests"
        / f"{_safe_slug(support_id, fallback='support-request')}.json"
    )
    persisted_epoch_at, persisted_epoch_state = _persisted_support_budget_epoch(
        operator_root,
        support_id,
    )
    if persisted_epoch_at is not None and (
        epoch_at is None or persisted_epoch_at > epoch_at
    ):
        epoch_at = persisted_epoch_at
        epoch_state = persisted_epoch_state
    retry_epoch_at, retry_epoch_state = _rate_limit_retry_budget_epoch(support)
    if retry_epoch_at is not None and (epoch_at is None or retry_epoch_at > epoch_at):
        epoch_at = retry_epoch_at
        epoch_state = retry_epoch_state
    source_plan_attempts = 0
    for row in source_plan_rows:
        if not _support_budget_row_after_epoch(row, epoch_at):
            continue
        if (
            str(row.get("trusted_source_response_status", "") or "").strip()
            or str(row.get("trusted_source_failure_class", "") or "").strip()
            or str(row.get("trusted_source_rejection_reason", "") or "").strip()
        ):
            source_plan_attempts += 1
    digest_attempts = 0
    for row in _read_autonomy_ledger_tail_for_support(
        operator_root,
        "directive_build_grade_support_digests",
        support_id,
    ):
        if not _support_budget_row_after_epoch(row, epoch_at):
            continue
        try:
            digest_attempts += int(row.get("trusted_source_attempt_count", 0) or 0)
        except (TypeError, ValueError):
            digest_attempts += 0
    attempt_count = max(source_plan_attempts, digest_attempts)
    exhausted = attempt_count >= cap
    return {
        "external_request_budget_state": "exhausted" if exhausted else "available",
        "support_external_request_attempt_count": int(attempt_count),
        "support_external_request_attempt_cap": int(cap),
        "support_external_request_budget_exhausted": bool(exhausted),
        "support_external_request_budget_epoch_state": epoch_state,
        "support_external_request_budget_epoch_at": (
            epoch_at.isoformat() if epoch_at is not None else ""
        ),
    }


def _mark_support_synthesis_external_budget_exhausted(
    operator_root: str | Path,
    support_request_id: str,
    *,
    budget: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    support_id = str(support_request_id or "").strip()
    support = _read_json(_support_request_path(operator_root, support_id)) if support_id else {}
    if not support:
        return {}
    current_budget = dict(
        budget or _support_synthesis_external_attempt_budget(operator_root, support_id)
    )
    now = _utc_now()
    support["external_request_budget_state"] = "exhausted"
    support["support_external_request_budget_exhausted"] = True
    support["support_external_request_attempt_count"] = int(
        current_budget.get("support_external_request_attempt_count", 0) or 0
    )
    support["support_external_request_attempt_cap"] = int(
        current_budget.get("support_external_request_attempt_cap", 0) or 0
    )
    support["support_synthesis_job_state"] = "blocked_by_external_request_budget"
    support["candidate_ingestion_state"] = "external_request_budget_exhausted"
    support["support_materialization_state"] = "parked_waiting_for_operator_or_seed_pack"
    support["support_provider_quality_blocker"] = "external_request_budget_exhausted"
    support["next_support_recovery_action"] = "operator_review_or_seed_pack_required"
    support["operator_review_required"] = True
    support["updated_at"] = now
    _write_json(_support_request_path(operator_root, support_id), support)
    _append_ledger(
        operator_root,
        "support_request_events",
        {
            "event": "support_synthesis_external_request_budget_exhausted",
            "generated_at": now,
            "support_request_id": support_id,
            "directive_id": str(support.get("directive_id", "") or ""),
            "target_artifact": str(support.get("target_artifact", "") or ""),
            "support_external_request_attempt_count": support[
                "support_external_request_attempt_count"
            ],
            "support_external_request_attempt_cap": support["support_external_request_attempt_cap"],
            "grants_execution_authority": False,
        },
    )
    return support


def _support_synthesis_matching_seed_pack_available(
    operator_root: str | Path,
    support: Mapping[str, Any],
) -> dict[str, Any]:
    seed_dir = _conveyor_root(operator_root) / "operator_support_seed_packs"
    if not seed_dir.exists():
        return {
            "matching_seed_pack_available": False,
            "matching_seed_pack_id": "",
            "matching_seed_requested_row_ids": [],
        }
    target_artifact = str(support.get("target_artifact", "") or "").strip()
    directive_family = str(support.get("directive_family", "") or "").strip()
    requested_ids = {
        str(item or "").strip()
        for item in list(
            support.get("uncovered_requested_row_ids", [])
            or support.get("requested_row_ids", [])
            or []
        )
        if str(item or "").strip()
    }
    for row in list(support.get("requested_rows", []) or []):
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip():
            requested_ids.add(str(row.get("requested_row_id", "") or "").strip())
    if not requested_ids:
        return {
            "matching_seed_pack_available": False,
            "matching_seed_pack_id": "",
            "matching_seed_requested_row_ids": [],
        }
    for path in sorted(seed_dir.glob("*.json")):
        payload = _read_json(path)
        if str(payload.get("schema_name", "") or "") != "OperatorApprovedSupportSeedPack":
            continue
        if bool(payload.get("grants_execution_authority", False)):
            continue
        seed_target = str(payload.get("target_artifact", "") or "").strip()
        if target_artifact and seed_target and seed_target != target_artifact:
            continue
        seed_family = str(payload.get("directive_family", "") or "").strip()
        if directive_family and seed_family and seed_family != directive_family:
            continue
        seed_rows: list[dict[str, Any]] = []
        for key in (
            "child_support_rows",
            "support_row_templates",
            "child_support_row_templates",
            "requested_row_templates",
            "row_templates",
        ):
            seed_rows.extend(
                dict(row)
                for row in list(payload.get(key, []) or [])
                if isinstance(row, Mapping)
            )
        row_ids = {
            str(row.get("requested_row_id", "") or "").strip()
            for row in seed_rows
            if str(row.get("requested_row_id", "") or "").strip()
            and str(row.get("target_artifact", "") or target_artifact).strip() == target_artifact
            and not bool(row.get("grants_execution_authority", False))
        }
        matched = sorted(requested_ids & row_ids)
        if matched:
            return {
                "matching_seed_pack_available": True,
                "matching_seed_pack_id": str(
                    payload.get("operator_seed_pack_id", "")
                    or payload.get("seed_pack_id", "")
                    or path.stem
                ),
                "matching_seed_requested_row_ids": matched,
            }
    return {
        "matching_seed_pack_available": False,
        "matching_seed_pack_id": "",
        "matching_seed_requested_row_ids": [],
    }


def _support_synthesis_cheap_source_validation_pending(
    operator_root: str | Path,
    support_request_id: str,
) -> bool:
    support_id = str(support_request_id or "").strip()
    if not support_id:
        return False
    candidates: list[dict[str, Any]] = []
    latest_source_plan = _read_json(
        Path(operator_root) / "autonomy" / "directive_support_source_plan_latest.json"
    )
    if latest_source_plan:
        candidates.append(dict(latest_source_plan))
    latest_digest = _read_json(
        Path(operator_root) / "autonomy" / "directive_build_grade_support_digest_latest.json"
    )
    if latest_digest:
        candidates.append(dict(latest_digest))
    for row in candidates:
        row_support_id = str(
            row.get("support_request_id", "")
            or row.get("current_provider_support_request_id", "")
            or ""
        ).strip()
        if row_support_id != support_id:
            continue
        if int(row.get("source_candidate_count", 0) or 0) <= 0:
            continue
        if str(row.get("trusted_source_rejection_reason", "") or "").strip() == (
            "source_candidate_field_validation_required"
        ):
            return True
        if str(row.get("provider_blocker", "") or "").strip() == "cheap_source_candidate_validation_required":
            return True
    return False


def _support_synthesis_rate_limit_backoff_expired(support: Mapping[str, Any]) -> bool:
    if not bool(support.get("provider_rate_limited", False)) and not bool(
        support.get("support_synthesis_backoff_required", False)
    ):
        return False
    retry_at = _parse_utc_time(support.get("support_synthesis_next_retry_after", ""))
    if retry_at is None:
        started_at = _parse_utc_time(support.get("support_synthesis_backoff_started_at", ""))
        if started_at is None:
            return False
        try:
            retry_after_seconds = int(support.get("support_synthesis_retry_after_seconds", 900) or 900)
        except (TypeError, ValueError):
            retry_after_seconds = 900
        retry_at = started_at + timedelta(seconds=max(60, retry_after_seconds))
    return datetime.now(timezone.utc) >= retry_at


def _clear_expired_support_synthesis_rate_limit_backoff(support: Mapping[str, Any]) -> dict[str, Any]:
    refreshed = dict(support)
    if not _support_synthesis_rate_limit_backoff_expired(refreshed):
        return refreshed
    refreshed["provider_rate_limited"] = False
    refreshed["support_synthesis_backoff_required"] = False
    refreshed["support_synthesis_backoff_expired_state"] = "retry_window_open"
    refreshed["support_synthesis_backoff_expired_at"] = _utc_now()
    refreshed["next_support_recovery_action"] = "narrow_research_source_lanes"
    refreshed["candidate_ingestion_state"] = "pending_support"
    refreshed["support_materialization_state"] = "parked_waiting_for_consumable_support"
    if str(refreshed.get("support_provider_quality_blocker", "") or "") == "trusted_source_provider_rate_limited":
        refreshed["support_provider_quality_blocker"] = "source_backed_rows_required"
    refreshed["parked_support_recovery_attempted"] = False
    refreshed["core_support_recovery_attempted"] = False
    refreshed["core_support_recovery_reason"] = ""
    refreshed["core_support_recovery_job_id"] = ""
    return refreshed


def _normalize_failed_async_support_request(
    operator_root: str | Path,
    support_request_id: str,
    *,
    error_class: str,
    job_id: str = "",
) -> dict[str, Any]:
    support = _read_json(_support_request_path(operator_root, support_request_id))
    if not support:
        return {}
    parked = bool(str(support.get("support_blocked_park_idempotency_key", "") or ""))
    support["support_state"] = "pending_operator_review"
    support["operator_review_required"] = True
    support["candidate_ingestion_state"] = "trusted_source_requested"
    support["support_materialization_state"] = (
        "parked_waiting_for_consumable_support"
        if parked
        else "async_synthesis_failed"
    )
    if parked:
        support["support_blocker_reason"] = str(
            support.get("support_blocker_reason", "") or "no_consumable_support_rows"
        )
    support["support_synthesis_job_state"] = "failed"
    if job_id and bool(support.get("core_support_recovery_attempted", False)):
        support["core_support_recovery_job_id"] = str(
            support.get("core_support_recovery_job_id", "") or job_id
        )
    latest_digest = _read_json(autonomy_root(operator_root) / "directive_build_grade_support_digest_latest.json")
    latest_digest_matches_support = bool(
        latest_digest
        and str(latest_digest.get("support_request_id", "") or "") == support_request_id
        and str(latest_digest.get("target_artifact", "") or "") == str(support.get("target_artifact", "") or "")
        and not bool(latest_digest.get("grants_execution_authority", False))
    )
    latest_source_plan = _read_json(autonomy_root(operator_root) / "directive_support_source_plan_latest.json")
    latest_source_plan_matches_support = bool(
        latest_source_plan
        and str(latest_source_plan.get("support_request_id", "") or "") == support_request_id
        and str(latest_source_plan.get("target_artifact", "") or "") == str(support.get("target_artifact", "") or "")
        and not bool(latest_source_plan.get("grants_execution_authority", False))
    )
    if (
        latest_digest_matches_support
    ):
        prior_uncovered_ids = [
            str(item or "").strip()
            for item in list(support.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        contract_requested_ids = [
            str(item or "").strip()
            for item in list(support.get("support_synthesis_contract_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        accepted_ids = [
            str(item or "").strip()
            for item in list(latest_digest.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        latest_digest_requires_cheap_source_validation = (
            str(latest_digest.get("trusted_source_failure_class", "") or "").strip()
            == "cheap_source_candidate_validation_required"
            or str(latest_digest.get("provider_blocker", "") or "").strip()
            == "cheap_source_candidate_validation_required"
            or (
                str(latest_digest.get("trusted_source_rejection_reason", "") or "").strip()
                == "source_candidate_field_validation_required"
                and int(latest_digest.get("cheap_source_rows_extracted_count", 0) or 0) == 0
            )
        )
        prior_accepted_ids: list[str] = []
        for source in (
            support.get("accepted_requested_row_ids", []),
            dict(support.get("provider_field_lane_request", {}) or {}).get(
                "accepted_requested_row_ids", []
            ),
        ):
            for item in list(source or []):
                value = str(item or "").strip()
                if value:
                    prior_accepted_ids.append(value)
        if not latest_digest_requires_cheap_source_validation:
            accepted_ids = list(dict.fromkeys(prior_accepted_ids + accepted_ids))
        uncovered_ids = [
            str(item or "").strip()
            for item in list(latest_digest.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        latest_digest_completed = str(latest_digest.get("status", "") or "") == "completed"
        if not uncovered_ids and prior_uncovered_ids and not latest_digest_completed:
            uncovered_ids = prior_uncovered_ids
        latest_provider_request = (
            dict(latest_digest.get("provider_field_lane_request", {}) or {})
            if isinstance(latest_digest.get("provider_field_lane_request", {}), Mapping)
            else {}
        )
        latest_requested_rows = [
            dict(row)
            for row in list(latest_provider_request.get("requested_rows", []) or [])
            if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
        ]
        latest_requested_ids = {
            str(row.get("requested_row_id", "") or "").strip()
            for row in latest_requested_rows
            if str(row.get("requested_row_id", "") or "").strip()
        }
        latest_request_covers_contract = (
            not contract_requested_ids
            or set(contract_requested_ids).issubset(latest_requested_ids)
        )
        if latest_requested_rows and latest_request_covers_contract:
            support["provider_field_lane_request"] = latest_provider_request
            support["requested_rows"] = latest_requested_rows
            support["requested_row_count"] = len(latest_requested_rows)
        elif latest_requested_rows and contract_requested_ids:
            support["provider_latest_freshness_state"] = "stale_provider_request_missing_current_contract_rows"
            support["provider_latest_repaired_from_support_request_id"] = support_request_id
        if contract_requested_ids:
            existing_requested_ids = {
                str(row.get("requested_row_id", "") or "").strip()
                for row in list(support.get("requested_rows", []) or [])
                if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
            }
            target_artifact = str(support.get("target_artifact", "") or "")
            fallback_required_fields = list(
                support.get("required_fields", [])
                or support.get("missing_fields", [])
                or _support_contract_required_fields(
                    _directive_family_from_text(str(support.get("directive_family", "") or "")),
                    target_artifact,
                )
                or []
            )
            reconstructed_rows = [
                dict(row)
                for row in list(support.get("requested_rows", []) or [])
                if isinstance(row, Mapping)
            ]
            for contract_id in contract_requested_ids:
                if contract_id in existing_requested_ids:
                    continue
                base_row_id = str(contract_id).split("__", 1)[0]
                reconstructed_rows.append(
                    {
                        "requested_row_id": contract_id,
                        "target_artifact": target_artifact,
                        "target_row_id": base_row_id,
                        "target_role": base_row_id,
                        "required_fields": fallback_required_fields,
                        "source_query_hint": (
                            f"{contract_id} {target_artifact} source-backed evidence"
                        ),
                        "reconstructed_from_support_synthesis_contract": True,
                        "commercial_component_source_required": bool(
                            support.get("commercial_source_acquisition_required", False)
                            or support.get("source_backed_rows_required", False)
                        ),
                        "grants_execution_authority": False,
                    }
                )
                existing_requested_ids.add(contract_id)
            support["requested_rows"] = reconstructed_rows
            support["requested_row_count"] = len(reconstructed_rows)
        for key in (
            "abstract_lane_decomposition_state",
            "abstract_lane_decomposition_reason",
        ):
            value = latest_digest.get(key, "") or latest_provider_request.get(key, "")
            if str(value or "").strip():
                support[key] = str(value or "")
        for key in (
            "abstract_source_requested_row_ids",
            "abstract_decomposed_requested_row_ids",
            "decomposed_requested_row_ids",
            "decomposed_abstract_requested_rows",
        ):
            value = latest_digest.get(key, []) or latest_provider_request.get(key, []) or []
            if value:
                support[key] = list(value)
        requested_ids = [
            str(row.get("requested_row_id", "") or "").strip()
            for row in list(support.get("requested_rows", []) or [])
            if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
        ]
        if requested_ids:
            requested_set = set(requested_ids)
            uncovered_ids = [item for item in uncovered_ids if item in requested_set]
        if accepted_ids or uncovered_ids:
            accepted_ids = list(dict.fromkeys(accepted_ids))
            accepted_set = set(accepted_ids)
            accepted_uncovered_overlap = [
                item for item in list(dict.fromkeys(uncovered_ids)) if item in accepted_set
            ]
            uncovered_ids = [
                item for item in list(dict.fromkeys(uncovered_ids)) if item not in accepted_set
            ]
            if accepted_uncovered_overlap:
                support["accepted_uncovered_overlap_repaired"] = True
                support["accepted_uncovered_overlap_repaired_requested_row_ids"] = (
                    accepted_uncovered_overlap
                )
            support["accepted_requested_row_ids"] = list(dict.fromkeys(accepted_ids))
            support["uncovered_requested_row_ids"] = list(
                dict.fromkeys(uncovered_ids or [item for item in requested_ids if item not in set(accepted_ids)])
            )
            support["requested_row_coverage_state"] = (
                "accepted"
                if requested_ids and set(support["accepted_requested_row_ids"]) >= set(requested_ids)
                else "incomplete"
            )
            support["accepted_field_lane_rows"] = list(
                latest_digest.get("accepted_field_lane_rows", []) or []
            )
            support["operator_seed_pack_used"] = bool(latest_digest.get("operator_seed_pack_used", False))
            if str(latest_digest.get("operator_seed_pack_id", "") or ""):
                support["operator_seed_pack_id"] = str(latest_digest.get("operator_seed_pack_id", ""))
            support["source_query_generation_state"] = str(
                latest_digest.get("source_query_generation_state", "")
                or dict(latest_digest.get("source_plan", {}) or {}).get("source_query_generation_state", "")
                or ""
            )
            support["generated_search_queries"] = list(
                latest_digest.get("generated_search_queries", [])
                or dict(latest_digest.get("source_plan", {}) or {}).get("generated_search_queries", [])
                or []
            )
            support["source_query_requested_row_ids"] = list(
                latest_digest.get("source_query_requested_row_ids", [])
                or dict(latest_digest.get("source_plan", {}) or {}).get("source_query_requested_row_ids", [])
                or []
            )
            support["support_provider_quality_blocker"] = str(
                latest_digest.get("provider_blocker", "")
                or support.get("support_provider_quality_blocker", "")
                or "source_backed_rows_required"
            )
            if str(latest_digest.get("trusted_source_response_status", "") or ""):
                support["trusted_source_response_status"] = str(
                    latest_digest.get("trusted_source_response_status", "") or ""
                )
            elif latest_source_plan_matches_support and str(
                latest_source_plan.get("trusted_source_response_status", "") or ""
            ):
                support["trusted_source_response_status"] = str(
                    latest_source_plan.get("trusted_source_response_status", "") or ""
                )
            if str(latest_digest.get("trusted_source_failure_class", "") or ""):
                support["trusted_source_failure_class"] = str(
                    latest_digest.get("trusted_source_failure_class", "") or ""
                )
            elif latest_source_plan_matches_support and str(
                latest_source_plan.get("trusted_source_failure_class", "") or ""
            ):
                support["trusted_source_failure_class"] = str(
                    latest_source_plan.get("trusted_source_failure_class", "") or ""
                )
            if str(latest_digest.get("trusted_source_rejection_reason", "") or ""):
                support["trusted_source_rejection_reason"] = str(
                    latest_digest.get("trusted_source_rejection_reason", "") or ""
                )
            elif latest_source_plan_matches_support and str(
                latest_source_plan.get("trusted_source_rejection_reason", "") or ""
            ):
                support["trusted_source_rejection_reason"] = str(
                    latest_source_plan.get("trusted_source_rejection_reason", "") or ""
                )
            support["next_support_recovery_action"] = str(
                "narrow_research_source_lanes"
                if str(latest_digest.get("provider_blocker", "") or "")
                else support.get("next_support_recovery_action", "")
                or "narrow_research_source_lanes"
            )
            if support["uncovered_requested_row_ids"]:
                support["commercial_source_acquisition_required"] = bool(
                    support.get("commercial_source_acquisition_required", True)
                )
                support["source_backed_rows_required"] = bool(
                    support.get("source_backed_rows_required", True)
                )
            current_uncovered_set = {
                str(item or "").strip()
                for item in list(support.get("uncovered_requested_row_ids", []) or [])
                if str(item or "").strip()
            }
            current_query_set = {
                str(item or "").strip()
                for item in list(support.get("source_query_requested_row_ids", []) or [])
                if str(item or "").strip()
            }
            if current_uncovered_set and not current_uncovered_set.issubset(current_query_set):
                current_uncovered_rows = [
                    dict(row)
                    for row in list(support.get("requested_rows", []) or [])
                    if isinstance(row, Mapping)
                    and str(row.get("requested_row_id", "") or "").strip() in current_uncovered_set
                ]
                if current_uncovered_rows:
                    refresh_request = dict(support.get("provider_field_lane_request", {}) or {})
                    refresh_request.update(
                        {
                            "schema_name": str(
                                refresh_request.get("schema_name", "") or "ProviderFieldLaneRequest"
                            ),
                            "support_request_id": support_request_id,
                            "directive_id": str(support.get("directive_id", "") or ""),
                            "target_artifact": str(support.get("target_artifact", "") or ""),
                            "requested_rows": current_uncovered_rows,
                            "requested_row_count": len(current_uncovered_rows),
                            "accepted_requested_row_ids": [],
                            "uncovered_requested_row_ids": sorted(current_uncovered_set),
                            "provider_latest_freshness_state": "current_support_request",
                            "grants_execution_authority": False,
                        }
                    )
                    for stale_query_key in (
                        "search_queries",
                        "generated_search_queries",
                        "source_query_requested_row_ids",
                    ):
                        refresh_request.pop(stale_query_key, None)
                    _persist_current_provider_acquisition_latest(
                        operator_root,
                        support=support,
                        provider_request=refresh_request,
                        reason="failed_synthesis_current_uncovered_contract_refresh",
                    )
                    refreshed_plan = _read_json(
                        autonomy_root(operator_root) / "directive_support_source_plan_latest.json"
                    )
                    if refreshed_plan and str(
                        refreshed_plan.get("support_request_id", "") or ""
                    ) == support_request_id:
                        support["provider_latest_freshness_state"] = str(
                            refreshed_plan.get("provider_latest_freshness_state", "")
                            or "current_support_request"
                        )
                        support["source_query_generation_state"] = str(
                            refreshed_plan.get("source_query_generation_state", "") or ""
                        )
                        support["source_query_generation_reason"] = str(
                            refreshed_plan.get("source_query_generation_reason", "") or ""
                        )
                        support["generated_search_queries"] = list(
                            refreshed_plan.get("generated_search_queries", []) or []
                        )
                        support["search_queries"] = list(
                            refreshed_plan.get("search_queries", []) or []
                        )
                        support["source_query_requested_row_ids"] = list(
                            refreshed_plan.get("source_query_requested_row_ids", []) or []
                        )
                        support["source_candidate_count"] = int(
                            refreshed_plan.get("source_candidate_count", 0) or 0
                        )
                        support["source_candidates"] = list(
                            refreshed_plan.get("source_candidates", []) or []
                        )
                        support["retrieved_knowledge_refs"] = list(
                            refreshed_plan.get("retrieved_knowledge_refs", []) or []
                        )
                        support["provider_latest_repair_reason"] = (
                            "failed_synthesis_current_uncovered_contract_refresh"
                        )
                        support["next_support_recovery_action"] = "narrow_research_source_lanes"
                        support["support_provider_quality_blocker"] = str(
                            support.get("support_provider_quality_blocker", "")
                            or "source_backed_rows_required"
                        )
    latest_digest_rate_limited = bool(
        latest_digest_matches_support
        and _trusted_source_provider_rate_limited(
            latest_digest.get("trusted_source_response_status", ""),
            latest_digest.get("trusted_source_failure_class", ""),
            latest_digest.get("trusted_source_rejection_reason", ""),
            latest_digest.get("provider_blocker", ""),
        )
    )
    request_rate_limited = bool(
        not latest_digest_matches_support
        and _trusted_source_provider_rate_limited(
            error_class,
            support.get("trusted_source_response_status", ""),
            support.get("trusted_source_rejection_reason", ""),
            support.get("support_provider_quality_blocker", ""),
            support.get("provider_blocker", ""),
        )
    )
    if latest_digest_matches_support and not latest_digest_rate_limited:
        support["provider_rate_limited"] = False
        support["support_synthesis_backoff_required"] = False
        if str(support.get("next_support_recovery_action", "") or "") == "provider_rate_limit_backoff":
            support["next_support_recovery_action"] = "narrow_research_source_lanes"
        if str(support.get("support_provider_quality_blocker", "") or "") == "trusted_source_provider_rate_limited":
            support["support_provider_quality_blocker"] = "source_backed_rows_required"
    if latest_digest_rate_limited or request_rate_limited:
        retry_after_seconds, retry_after = _support_synthesis_rate_limit_retry_after()
        support["provider_rate_limited"] = True
        support["support_synthesis_backoff_required"] = True
        support["support_synthesis_backoff_started_at"] = str(
            support.get("support_synthesis_backoff_started_at", "") or _utc_now()
        )
        support["support_synthesis_retry_after_seconds"] = retry_after_seconds
        support["support_synthesis_next_retry_after"] = retry_after
        support["next_support_recovery_action"] = "provider_rate_limit_backoff"
        support["candidate_ingestion_state"] = "trusted_source_rate_limited"
        support["support_materialization_state"] = "parked_waiting_for_provider_rate_limit"
        support["support_provider_quality_blocker"] = "trusted_source_provider_rate_limited"
        support["trusted_source_response_status"] = str(
            support.get("trusted_source_response_status", "")
            or (latest_digest.get("trusted_source_response_status", "") if latest_digest_matches_support else "")
            or "429"
        )
        support["trusted_source_failure_class"] = str(
            support.get("trusted_source_failure_class", "")
            or (latest_digest.get("trusted_source_failure_class", "") if latest_digest_matches_support else "")
            or "http_status"
        )
        support["trusted_source_rejection_reason"] = str(
            support.get("trusted_source_rejection_reason", "")
            or (latest_digest.get("trusted_source_rejection_reason", "") if latest_digest_matches_support else "")
            or (latest_digest.get("provider_blocker", "") if latest_digest_matches_support else "")
            or str(error_class or "")
        )
    support["trusted_source_error_class"] = str(error_class or "trusted_source_synthesis_failed")
    support["updated_at"] = _utc_now()
    _write_json(_support_request_path(operator_root, support_request_id), support)
    return support


def _support_synthesis_worker_alive(pid: Any) -> bool:
    try:
        pid_value = int(pid or 0)
    except (TypeError, ValueError):
        return False
    if pid_value <= 0:
        return False
    if os.name == "nt":
        try:
            from ctypes import byref, c_ulong, windll

            handle = windll.kernel32.OpenProcess(0x1000, False, pid_value)
            if not handle:
                return False
            try:
                exit_code = c_ulong()
                if not windll.kernel32.GetExitCodeProcess(handle, byref(exit_code)):
                    return False
                return exit_code.value == 259
            finally:
                windll.kernel32.CloseHandle(handle)
        except (AttributeError, OSError, ValueError):
            return False
    try:
        os.kill(pid_value, 0)
    except OSError:
        return False
    return True


def _run_resident_support_synthesis_job(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    job_id: str,
) -> None:
    job_path = _support_synthesis_job_path(operator_root, job_id)
    job = _read_json(job_path)
    if not job:
        return
    now = _utc_now()
    job["job_state"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _write_json(job_path, job)
    support_request_id = str(job.get("support_request_id", "") or "")
    error_class = ""
    try:
        approval = approve_conveyor_support_request(
            operator_root,
            state_root=str(state_root),
            support_request_id=support_request_id,
        )
        support = dict(approval.get("support_request", {}) or _read_json(_support_request_path(operator_root, support_request_id)))
        if bool(approval.get("ok", False)) and str(support.get("support_state", "") or "") == "satisfied":
            materialized: dict[str, Any] = {}
            support["support_synthesis_job_state"] = "completed"
            support["support_synthesis_completed_at"] = _utc_now()
            support["support_provider_quality_blocker"] = ""
            support["updated_at"] = support["support_synthesis_completed_at"]
            _write_json(_support_request_path(operator_root, support_request_id), support)
            child_id = str(job.get("child_run_id", "") or support.get("child_run_id", "") or "")
            child = _read_json(_child_path(operator_root, child_id)) if child_id else {}
            if child and str(child.get("state", "") or "") not in TERMINAL_CHILD_STATES:
                latest_progress = _latest_child_progress(child)
                materialized = _materialize_support_for_running_resident_child(
                    operator_root,
                    state_root=state_root,
                    child=child,
                    latest_progress=latest_progress,
                    target_artifact=str(
                        support.get("target_artifact", "")
                        or job.get("target_artifact", "")
                        or latest_progress.get("target_artifact", "")
                        or ""
                    ),
                    support_request=support,
                )
                if bool(materialized.get("ok", False)):
                    support = dict(_read_json(_support_request_path(operator_root, support_request_id)) or support)
                    support["support_materialization_state"] = "support_checkout_refreshed"
                    support["support_checkout_refreshed_at"] = _utc_now()
                    support["wake_work_order_id"] = str(materialized.get("work_order_id", "") or "")
                    support["support_pack_rows_available"] = int(
                        materialized.get("support_pack_rows_available", 0) or 0
                    )
                    support["support_synthesis_job_state"] = "completed"
                    support["updated_at"] = support["support_checkout_refreshed_at"]
                    _write_json(_support_request_path(operator_root, support_request_id), support)
            job["job_state"] = "completed"
            job["support_synthesis_job_state"] = "completed"
            job["approval_ok"] = True
            job["support_state_after"] = str(support.get("support_state", "") or "")
            job["materialization"] = materialized
        else:
            details = approval.get("details", [])
            if isinstance(details, list) and details:
                error_class = str(details[0] or "")
            error_class = error_class or str(approval.get("message", "") or "trusted_source_synthesis_failed")
            support = _normalize_failed_async_support_request(
                operator_root,
                support_request_id,
                error_class=error_class,
                job_id=job_id,
            )
            job["job_state"] = "failed"
            job["support_synthesis_job_state"] = "failed"
            job["approval_ok"] = False
            job["support_state_after"] = str(support.get("support_state", "") or "")
            job["error_class"] = error_class
    except Exception as exc:  # pragma: no cover - defensive background worker path.
        support = _normalize_failed_async_support_request(
            operator_root,
            support_request_id,
            error_class=type(exc).__name__,
            job_id=job_id,
        )
        job["job_state"] = "failed"
        job["support_synthesis_job_state"] = "failed"
        job["approval_ok"] = False
        job["support_state_after"] = str(support.get("support_state", "") or "")
        job["error_class"] = type(exc).__name__
    finally:
        job["completed_at"] = _utc_now()
        job["updated_at"] = job["completed_at"]
        _write_json(job_path, job)


def _start_resident_support_synthesis_job(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    job_id: str,
) -> None:
    worker_code = (
        "from operator_shell.conveyor import _run_resident_support_synthesis_job; "
        "_run_resident_support_synthesis_job(__import__('sys').argv[1], "
        "state_root=__import__('sys').argv[2], job_id=__import__('sys').argv[3])"
    )
    env = dict(os.environ)
    package_root = Path(__file__).resolve().parents[1]
    prior_pythonpath = str(env.get("PYTHONPATH", "") or "")
    env["PYTHONPATH"] = (
        str(package_root)
        if not prior_pythonpath
        else str(package_root) + os.pathsep + prior_pythonpath
    )
    process = subprocess.Popen(
        [
            sys.executable,
            "-c",
            worker_code,
            str(operator_root),
            str(state_root),
            str(job_id),
        ],
        cwd=str(package_root),
        env=env,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        start_new_session=True,
    )
    job_path = _support_synthesis_job_path(operator_root, job_id)
    job = _read_json(job_path)
    if job:
        job["worker_launch_state"] = "detached_process_started"
        job["worker_pid"] = int(process.pid or 0)
        job["worker_launched_at"] = _utc_now()
        job["updated_at"] = job["worker_launched_at"]
        _write_json(job_path, job)


def _support_synthesis_input_fingerprint(operator_root: str | Path, support: Mapping[str, Any]) -> str:
    from .autonomy import _configured_knowledge_source_adapter_candidates

    plan = _read_json(autonomy_root(operator_root) / "directive_support_source_plan_latest.json")
    if str(plan.get("support_request_id", "")) != str(support.get("support_request_id", "")):
        plan = {}
    adapters = _configured_knowledge_source_adapter_candidates(
        operator_root, context=support, provider_field_lane_request=support,
    )
    cache_root = _conveyor_root(operator_root) / "source_evidence_cache"
    adapters["cached_source_revisions"] = [
        {"name": path.name, "size": path.stat().st_size, "mtime_ns": path.stat().st_mtime_ns}
        for path in sorted(cache_root.glob("*.json"))
    ]
    from .research_episodes import load_research_handoff
    try:
        research = load_research_handoff(Path(operator_root), support)
        if research:
            adapters["research_evidence_revision"] = hashlib.sha256(
                json.dumps(research, sort_keys=True).encode()
            ).hexdigest()
    except (ValueError, OSError, KeyError, TypeError):
        pass
    return support_input_fingerprint(support, source_plan=plan, adapters=adapters)


def _support_synthesis_waiting_for_input(operator_root: str | Path, support: Mapping[str, Any]) -> bool:
    if support.get("support_state") in {"satisfied", "rejected", "approved"}:
        return False
    job_id = str(support.get("support_synthesis_job_id", "") or "")
    job = _read_json(_support_synthesis_job_path(operator_root, job_id)) if job_id else {}
    return bool(
        job.get("job_state") in {"failed", "waiting_for_input"}
        and int(job.get("same_input_attempt_count", 0)) >= RETRY_LIMIT
        and job.get("retry_input_fingerprint") == _support_synthesis_input_fingerprint(operator_root, support)
    )


def _enqueue_resident_support_synthesis_job(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    support_request: Mapping[str, Any],
    child: Mapping[str, Any],
    target_artifact: str,
) -> dict[str, Any]:
    with _SUPPORT_SYNTHESIS_ENQUEUE_LOCK:
        return _enqueue_resident_support_synthesis_job_locked(
            operator_root, state_root=state_root, support_request=support_request,
            child=child, target_artifact=target_artifact,
        )


def _enqueue_resident_support_synthesis_job_locked(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    support_request: Mapping[str, Any],
    child: Mapping[str, Any],
    target_artifact: str,
) -> dict[str, Any]:
    support_request_id = str(support_request.get("support_request_id", "") or "")
    contract_fingerprint = str(
        support_request.get("support_synthesis_contract_fingerprint", "") or ""
    )
    job_id = _support_synthesis_job_id(
        support_request_id,
        contract_fingerprint=contract_fingerprint,
    )
    job_path = _support_synthesis_job_path(operator_root, job_id)
    lease_id = f"support-synthesis-lease-{support_request_id}"
    lease_path = _support_synthesis_job_lease_path(operator_root, support_request_id)
    operator_seed_pack_policy = str(
        support_request.get("operator_seed_pack_policy", "")
        or "disabled_by_operator_experiment"
    )
    existing = _read_json(job_path)
    existing_state = str(existing.get("job_state", "") or "")
    if existing and existing_state in {"queued", "running"}:
        worker_pid = int(existing.get("worker_pid", 0) or 0)
        if existing_state == "running" and worker_pid <= 0:
            existing["job_state"] = "failed"
            existing["orphaned_previous_state"] = "running"
            existing["error_class"] = "orphaned_support_synthesis_job"
            existing["support_synthesis_job_repair_state"] = "orphaned_running_without_worker_pid"
            existing["updated_at"] = _utc_now()
            _write_json(job_path, existing)
        elif worker_pid > 0 and not _support_synthesis_worker_alive(worker_pid):
            existing["job_state"] = "failed"
            existing["orphaned_previous_state"] = existing_state
            existing["error_class"] = "orphaned_support_synthesis_worker_not_running"
            existing["support_synthesis_job_repair_state"] = "orphaned_worker_not_running"
            existing["updated_at"] = _utc_now()
            _write_json(job_path, existing)
        else:
            result = dict(existing)
            result["support_synthesis_job_lease_id"] = lease_id
            result["support_synthesis_job_lease_state"] = "active"
            result["operator_seed_pack_policy"] = operator_seed_pack_policy
            _write_json(
                lease_path,
                {
                    "schema_name": "ConveyorSupportSynthesisJobLease",
                    "schema_version": CONVEYOR_SCHEMA_VERSION,
                    "support_synthesis_job_lease_id": lease_id,
                    "support_synthesis_job_lease_state": "active",
                    "support_request_id": support_request_id,
                    "job_id": str(result.get("job_id", "") or job_id),
                    "contract_fingerprint": contract_fingerprint,
                    "operator_seed_pack_policy": operator_seed_pack_policy,
                    "updated_at": _utc_now(),
                    "grants_execution_authority": False,
                },
            )
            result["job_created"] = False
            return result
    existing = _read_json(job_path)
    existing_state = str(existing.get("job_state", "") or "")
    if existing and existing_state in {"queued", "running"}:
        result = dict(existing)
        result["support_synthesis_job_lease_id"] = lease_id
        result["support_synthesis_job_lease_state"] = "active"
        result["operator_seed_pack_policy"] = operator_seed_pack_policy
        result["job_created"] = False
        return result
    fingerprint = _support_synthesis_input_fingerprint(operator_root, support_request)
    same_input = existing.get("retry_input_fingerprint") == fingerprint
    attempt_count = int(existing.get("same_input_attempt_count", 0)) if same_input else 0
    if same_input and (existing_state == "completed" or attempt_count >= RETRY_LIMIT):
        if existing_state != "completed" and existing_state != "waiting_for_input":
            existing["job_state"] = "waiting_for_input"
            existing["retry_blocker"] = "unchanged_support_input"
            existing["updated_at"] = _utc_now()
            _write_json(job_path, existing)
        return {**existing, "job_created": False}
    now = _utc_now()
    job = {
        "schema_name": "ConveyorSupportSynthesisJob",
        "retry_input_fingerprint": fingerprint,
        "same_input_attempt_count": attempt_count + 1,
        "same_input_attempt_limit": RETRY_LIMIT,
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "job_id": job_id,
        "job_state": "queued",
        "support_request_id": support_request_id,
        "directive_id": str(support_request.get("directive_id", "") or child.get("directive_id", "") or ""),
        "child_run_id": str(child.get("child_run_id", "") or support_request.get("child_run_id", "") or ""),
        "target_artifact": str(target_artifact or support_request.get("target_artifact", "") or ""),
        "capability": str(support_request.get("capability", "") or ""),
        "support_synthesis_contract_fingerprint": contract_fingerprint,
        "support_synthesis_contract_requested_row_ids": list(
            support_request.get("support_synthesis_contract_requested_row_ids", []) or []
        ),
        "support_synthesis_contract_uncovered_requested_row_ids": list(
            support_request.get("support_synthesis_contract_uncovered_requested_row_ids", []) or []
        ),
        "support_synthesis_job_lease_id": lease_id,
        "support_synthesis_job_lease_state": "active",
        "operator_seed_pack_policy": operator_seed_pack_policy,
        "created_at": now,
        "updated_at": now,
        "grants_execution_authority": False,
    }
    if existing and str(existing.get("orphaned_previous_state", "") or ""):
        job["orphaned_previous_state"] = str(existing.get("orphaned_previous_state", "") or "")
        job["previous_error_class"] = str(existing.get("error_class", "") or "")
    _write_json(job_path, job)
    support = dict(support_request)
    support["support_state"] = "pending_operator_review"
    support["operator_review_required"] = True
    support["candidate_ingestion_state"] = "trusted_source_synthesis_in_progress"
    support["support_materialization_state"] = "waiting_for_async_synthesis"
    support["support_synthesis_job_id"] = job_id
    support["support_synthesis_job_state"] = "queued"
    support["support_synthesis_job_lease_id"] = lease_id
    support["operator_seed_pack_policy"] = operator_seed_pack_policy
    support["support_synthesis_contract_fingerprint"] = contract_fingerprint
    support["updated_at"] = now
    _write_json(_support_request_path(operator_root, support_request_id), support)
    _write_json(
        lease_path,
        {
            "schema_name": "ConveyorSupportSynthesisJobLease",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "support_synthesis_job_lease_id": lease_id,
            "support_synthesis_job_lease_state": "active",
            "support_request_id": support_request_id,
            "job_id": job_id,
            "contract_fingerprint": contract_fingerprint,
            "operator_seed_pack_policy": operator_seed_pack_policy,
            "created_at": now,
            "updated_at": now,
            "grants_execution_authority": False,
        },
    )
    _append_ledger(
        operator_root,
        "support_request_events",
        {
            "event": "resident_support_synthesis_job_enqueued",
            "generated_at": now,
            "support_request_id": support_request_id,
            "job_id": job_id,
            "directive_id": str(job.get("directive_id", "") or ""),
            "child_run_id": str(job.get("child_run_id", "") or ""),
            "target_artifact": str(job.get("target_artifact", "") or ""),
            "grants_execution_authority": False,
        },
    )
    _start_resident_support_synthesis_job(operator_root, state_root=state_root, job_id=job_id)
    result = dict(job)
    result["job_created"] = True
    return result


def enqueue_conveyor_support_synthesis_job(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    support_request_id: str,
) -> dict[str, Any]:
    support_id = str(support_request_id or "").strip()
    if not support_id:
        return {"ok": False, "message": "support_request_id is required."}
    support = _read_json(_support_request_path(operator_root, support_id))
    if not support:
        return {"ok": False, "message": f"Support request not found: {support_id}"}
    if not _support_request_requires_build_grade_support(support):
        return {
            "ok": False,
            "message": "Support request does not require async build-grade synthesis.",
            "async_synthesis_not_required": True,
            "support_request_id": support_id,
        }
    operator_seed_pack_policy = str(
        support.get("operator_seed_pack_policy", "")
        or os.environ.get("NOVALI_OPERATOR_SEED_PACK_POLICY", "")
        or "disabled_by_operator_experiment"
    ).strip()
    budget = _support_synthesis_external_attempt_budget(operator_root, support_id)
    cheap_source_validation_pending = (
        operator_seed_pack_policy == "disabled_by_operator_experiment"
        and _support_synthesis_cheap_source_validation_pending(operator_root, support_id)
    )
    if cheap_source_validation_pending:
        budget = {
            **dict(budget),
            "support_external_request_budget_exhausted": False,
            "external_request_budget_state": "bypassed_for_cheap_source_validation",
            "support_external_request_budget_bypass_reason": (
                "cheap_source_candidates_require_deterministic_validation"
            ),
            "cheap_source_validation_pending": True,
        }
    seed_availability = (
        {
            "matching_seed_pack_available": False,
            "matching_seed_pack_id": "",
            "matching_seed_requested_row_ids": [],
            "operator_seed_pack_policy": "disabled_by_operator_experiment",
        }
        if operator_seed_pack_policy == "disabled_by_operator_experiment"
        else _support_synthesis_matching_seed_pack_available(operator_root, support)
    )
    if (
        operator_seed_pack_policy != "disabled_by_operator_experiment"
        and bool(seed_availability.get("matching_seed_pack_available", False))
    ):
        budget = {
            **dict(budget),
            "support_external_request_budget_bypassed_by_seed_pack": True,
            "support_external_request_budget_bypass_reason": "matching_operator_seed_pack_available",
            "operator_seed_pack_id": str(seed_availability.get("matching_seed_pack_id", "") or ""),
            "matching_seed_requested_row_ids": list(
                seed_availability.get("matching_seed_requested_row_ids", []) or []
            ),
            "support_external_request_budget_exhausted": False,
            "external_request_budget_state": "bypassed_by_seed_pack",
        }
    if bool(budget.get("support_external_request_budget_exhausted", False)):
        refreshed = _mark_support_synthesis_external_budget_exhausted(
            operator_root,
            support_id,
            budget=budget,
        )
        return {
            "ok": False,
            "message": "External support synthesis request budget exhausted for this support request.",
            "support_request_id": support_id,
            "support_synthesis_job_state": "blocked_by_external_request_budget",
            "post_write_refresh_state": "deferred",
            "post_write_refresh_deferred": True,
            "control_plane_response_mode": "write_ack_lightweight",
            "external_request_budget_state": "exhausted",
            "support_external_request_attempt_count": int(
                budget.get("support_external_request_attempt_count", 0) or 0
            ),
            "support_external_request_attempt_cap": int(
                budget.get("support_external_request_attempt_cap", 0) or 0
            ),
            "support_request": refreshed,
            "grants_execution_authority": False,
        }
    child_id = str(support.get("child_run_id", "") or "")
    child = _read_json(_child_path(operator_root, child_id)) if child_id else {}
    support_context = _support_request_directive_context(operator_root, support)
    contract_fingerprint = _support_synthesis_contract_fingerprint(support_context)
    support = {**dict(support), **dict(budget)}
    support["operator_seed_pack_policy"] = operator_seed_pack_policy
    support["operator_seed_pack_used"] = False if operator_seed_pack_policy == "disabled_by_operator_experiment" else bool(
        support.get("operator_seed_pack_used", False)
    )
    support["operator_seed_pack_id"] = "" if operator_seed_pack_policy == "disabled_by_operator_experiment" else str(
        support.get("operator_seed_pack_id", "") or ""
    )
    support["requested_rows"] = [
        dict(row)
        for row in list(support_context.get("requested_rows", []) or [])
        if isinstance(row, Mapping)
    ]
    support["requested_row_count"] = len(support["requested_rows"])
    support["uncovered_requested_row_ids"] = [
        str(item or "")
        for item in list(support_context.get("uncovered_requested_row_ids", []) or [])
        if str(item or "")
    ]
    support["accepted_requested_row_ids"] = [
        str(item or "")
        for item in list(support_context.get("accepted_requested_row_ids", []) or [])
        if str(item or "")
    ]
    for key in (
        "abstract_lane_decomposition_required",
        "abstract_lane_promoted_from_metadata_requested_row_ids",
    ):
        if key in support_context:
            support[key] = support_context[key]
    support["support_synthesis_contract_fingerprint"] = contract_fingerprint
    support["support_synthesis_contract_requested_row_ids"] = [
        str(row.get("requested_row_id", "") or "")
        for row in list(support_context.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "")
    ]
    support["support_synthesis_contract_uncovered_requested_row_ids"] = [
        str(item or "")
        for item in list(support_context.get("uncovered_requested_row_ids", []) or [])
        if str(item or "")
    ]
    job = _enqueue_resident_support_synthesis_job(
        operator_root,
        state_root=state_root,
        support_request=support,
        child=child,
        target_artifact=str(support.get("target_artifact", "") or ""),
    )
    result = dict(job)
    result["ok"] = True
    result["message"] = (
        "Support synthesis is waiting for changed evidence, contract, or review."
        if job.get("job_state") == "waiting_for_input"
        else "Build-grade support synthesis job acknowledged."
    )
    result["support_request_id"] = support_id
    result["support_synthesis_job_state"] = str(job.get("job_state", "") or "queued")
    result["external_request_budget_state"] = str(
        budget.get("external_request_budget_state", "") or ""
    )
    result["support_external_request_budget_bypass_reason"] = str(
        budget.get("support_external_request_budget_bypass_reason", "") or ""
    )
    result["cheap_source_validation_pending"] = bool(
        budget.get("cheap_source_validation_pending", False)
    )
    result["post_write_refresh_state"] = "deferred"
    result["post_write_refresh_deferred"] = True
    result["control_plane_response_mode"] = "write_ack_lightweight"
    return result


def _recover_parked_support_blocked_directives(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    policy: Mapping[str, Any],
    auto_approve_remaining: int,
) -> dict[str, Any]:
    result: dict[str, Any] = {
        "parked_support_recovery_count": 0,
        "parked_support_satisfied_count": 0,
        "parked_support_deferred_count": 0,
        "auto_support_used_count": 0,
        "core_support_recovery_override_count": 0,
        "r_and_d_design_brief_created_count": 0,
        "commercial_source_acquisition_repaired_count": 0,
        "technical_documentation_depth_support_repaired_count": 0,
        "parked_support_seed_satisfied_count": 0,
        "results": [],
    }
    active_by_directive: dict[str, list[dict[str, Any]]] = {}
    for child in _active_children(operator_root):
        directive_id = str(child.get("directive_id", "") or "")
        if directive_id:
            active_by_directive.setdefault(directive_id, []).append(dict(child))
    remaining = max(0, int(auto_approve_remaining or 0))
    for directive in _load_items(_directives_root(operator_root)):
        directive_id = str(directive.get("directive_id", "") or "")
        if not directive_id:
            continue
        state = str(directive.get("state", "") or "")
        if state not in {"requeued", "blocked_for_support", "support_synthesis_in_progress"}:
            continue
        if str(directive.get("active_child_run_id", "") or "").strip() or active_by_directive.get(directive_id):
            continue
        metadata = dict(directive.get("metadata", {}) or {})
        support_request_id = str(metadata.get("support_request_id", "") or "")
        support = _read_json(_support_request_path(operator_root, support_request_id)) if support_request_id else {}
        if not support:
            continue
        if str(support.get("directive_id", "") or "") != directive_id:
            continue
        target_artifact = str(
            support.get("target_artifact", "")
            or metadata.get("support_blocker_target_artifact", "")
            or metadata.get("initial_work_order_target_artifact", "")
            or metadata.get("continuous_campaign_latest_target_artifact", "")
            or ""
        ).strip()
        if not target_artifact:
            continue
        if _support_synthesis_waiting_for_input(operator_root, support):
            result["parked_support_deferred_count"] += 1
            result["results"].append({
                "directive_id": directive_id,
                "support_request_id": support_request_id,
                "target_artifact": target_artifact,
                "state": "waiting_for_changed_support_input",
                "support_result_ok": False,
                "grants_execution_authority": False,
            })
            continue
        technical_doc_depth_repair = _ensure_current_technical_documentation_depth_support_request(
            operator_root,
            directive=directive,
            stale_support=support,
        )
        if bool(technical_doc_depth_repair.get("ok", False)):
            support = dict(technical_doc_depth_repair.get("support_request", {}) or support)
            directive = dict(technical_doc_depth_repair.get("directive", {}) or directive)
            metadata = dict(directive.get("metadata", {}) or {})
            support_request_id = str(support.get("support_request_id", "") or support_request_id)
            target_artifact = "technical_documentation.md"
            result["technical_documentation_depth_support_repaired_count"] += 1
            result["parked_support_deferred_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "technical_documentation_depth_support_required",
                    "support_state": str(support.get("support_state", "") or ""),
                    "support_result_ok": False,
                    "provider_field_lane_request_id": str(
                        support.get("provider_field_lane_request_id", "")
                        or dict(technical_doc_depth_repair.get("provider_field_lane_request", {}) or {}).get(
                            "provider_field_lane_request_id",
                            "",
                        )
                    ),
                    "uncovered_requested_row_ids": list(
                        support.get("uncovered_requested_row_ids", []) or []
                    ),
                    "materialization": {},
                }
            )
            continue
        if (
            policy.get("scope") == "build_grade_directives"
            and not _directive_expects_build_grade_documentation(directive)
            and not _support_request_requires_build_grade_support(support)
        ):
            continue
        support_context = _support_request_directive_context(operator_root, support)
        requested_row_acquisition_required = bool(
            _support_request_requires_commercial_source_rows(support, support_context)
            and list(support.get("requested_rows", []) or support_context.get("requested_rows", []) or [])
        )
        explicit_source_acquisition_state = (
            str(support.get("support_state", "") or "") == "commercial_source_acquisition_required"
            or bool(support.get("commercial_source_acquisition_required", False))
            or bool(support.get("source_backed_rows_required", False))
        )
        metadata_source_acquisition_state = bool(
            (
                metadata.get("commercial_source_acquisition_required", False)
                or metadata.get("source_backed_rows_required", False)
            )
            and list(metadata.get("uncovered_requested_row_ids", []) or [])
        )
        if requested_row_acquisition_required and (
            explicit_source_acquisition_state
            or metadata_source_acquisition_state
            or str(support.get("target_artifact", "") or target_artifact) == "validation_fixtures.json"
        ):
            provider_request = _provider_field_lane_request_for_support(
                operator_root,
                support=support,
                context=support_context,
            )
            requested_rows = [
                dict(row)
                for row in list(provider_request.get("requested_rows", []) or support.get("requested_rows", []) or [])
                if isinstance(row, Mapping)
            ]
            requested_ids = [
                str(row.get("requested_row_id", "") or "").strip()
                for row in requested_rows
                if str(row.get("requested_row_id", "") or "").strip()
            ]
            refreshed_contract_ids = {
                str(item or "").strip()
                for item in list(provider_request.get("provider_requested_row_contract_refreshed_ids", []) or [])
                if str(item or "").strip()
            }
            accepted_ids = [
                str(item).strip()
                for item in list(support.get("accepted_requested_row_ids", []) or [])
                if str(item).strip()
                and str(item).strip() in set(requested_ids)
                and str(item).strip() not in refreshed_contract_ids
            ]
            uncovered_ids = [requested_id for requested_id in requested_ids if requested_id not in set(accepted_ids)]
            now = _utc_now()
            support = dict(support)
            support["provider_field_lane_request"] = provider_request
            support["provider_field_lane_request_id"] = str(
                provider_request.get("provider_field_lane_request_id", "") or ""
            )
            support["current_provider_support_request_id"] = support_request_id
            support["provider_latest_freshness_state"] = "current_support_request"
            support["requested_rows"] = requested_rows
            support["requested_row_count"] = len(requested_rows)
            support["accepted_requested_row_ids"] = accepted_ids
            support["uncovered_requested_row_ids"] = uncovered_ids
            acquisition_label = (
                "validation_fixture_source_acquisition_required"
                if target_artifact == "validation_fixtures.json"
                else "commercial_source_acquisition_required"
            )
            if uncovered_ids:
                support["support_state"] = acquisition_label
            support["candidate_ingestion_state"] = acquisition_label
            support["support_recovery_state"] = acquisition_label
            if target_artifact == "bill_of_materials.json":
                support["commercial_source_acquisition_required"] = True
                support["source_backed_rows_required"] = True
                support["support_provider_quality_blocker"] = (
                    support.get("support_provider_quality_blocker", "")
                    or "source_backed_requested_rows_uncovered"
                )
            support["next_support_recovery_action"] = "run_provider_field_lane_source_acquisition"
            support = _clear_expired_support_synthesis_rate_limit_backoff(support)
            support = _apply_validation_fixture_support_acquisition_fields(
                support,
                state="accepted" if requested_rows and not uncovered_ids else "incomplete",
            )
            support["updated_at"] = now
            _write_json(_support_request_path(operator_root, support_request_id), support)
            if metadata_source_acquisition_state or str(metadata.get("support_request_id", "") or "") != support_request_id:
                updated_directive = dict(directive)
                updated_metadata = dict(metadata)
                updated_metadata["support_request_id"] = support_request_id
                updated_metadata["support_blocker_target_artifact"] = target_artifact
                updated_metadata["initial_work_order_target_artifact"] = target_artifact
                updated_metadata["continuous_campaign_latest_target_artifact"] = target_artifact
                updated_metadata["support_recovery_target_artifact"] = target_artifact
                updated_metadata["support_recovery_state"] = acquisition_label
                updated_metadata["support_blocker_reason"] = (
                    "source_backed_rows_required"
                    if target_artifact == "bill_of_materials.json"
                    else str(updated_metadata.get("support_blocker_reason", "") or "")
                )
                updated_metadata["provider_field_lane_request_id"] = str(
                    provider_request.get("provider_field_lane_request_id", "") or ""
                )
                updated_metadata["uncovered_requested_row_ids"] = list(uncovered_ids)
                updated_metadata["commercial_source_acquisition_required"] = bool(
                    target_artifact == "bill_of_materials.json" and uncovered_ids
                )
                updated_metadata["source_backed_rows_required"] = bool(
                    target_artifact == "bill_of_materials.json" and uncovered_ids
                )
                updated_metadata["source_backed_support_metadata_repaired"] = True
                updated_metadata["source_backed_support_metadata_repaired_at"] = now
                updated_directive["metadata"] = updated_metadata
                updated_directive["updated_at"] = now
                _write_json(_directive_path(operator_root, directive_id), updated_directive)
                directive = updated_directive
                metadata = updated_metadata
            _persist_current_provider_acquisition_latest(
                operator_root,
                support=support,
                provider_request=provider_request,
                reason=f"current_{target_artifact}_source_acquisition_support_tick",
            )
            result["current_provider_latest_refreshed_count"] = int(
                result.get("current_provider_latest_refreshed_count", 0) or 0
            ) + 1
            seed_pack_ref = _operator_seed_pack_ref(
                operator_root,
                state_root=state_root,
                support=support,
                required_fields=_support_request_required_fields(support),
            )
            if seed_pack_ref:
                seed_satisfaction = satisfy_conveyor_support_request(
                    operator_root,
                    state_root=state_root,
                    support_request_id=support_request_id,
                )
                support = dict(seed_satisfaction.get("support_request", {}) or support)
                if bool(seed_satisfaction.get("ok", False)):
                    result["parked_support_seed_satisfied_count"] = int(
                        result.get("parked_support_seed_satisfied_count", 0) or 0
                    ) + 1
        commercial_design_repair = _repair_design_brief_commercial_support_to_source_acquisition(
            operator_root,
            support=support,
            context=support_context,
        )
        if bool(commercial_design_repair.get("ok", False)):
            support = dict(commercial_design_repair.get("support_request", {}) or support)
            now = _utc_now()
            updated_directive = dict(directive)
            updated_metadata = dict(metadata)
            updated_metadata["support_request_id"] = support_request_id
            updated_metadata["support_blocker_reason"] = "source_backed_rows_required"
            updated_metadata["support_recovery_state"] = "commercial_source_acquisition_required"
            updated_metadata["support_recovery_target_artifact"] = target_artifact
            updated_metadata["initial_work_order_target_artifact"] = target_artifact
            updated_metadata["commercial_source_acquisition_required"] = True
            updated_metadata["source_backed_rows_required"] = True
            updated_metadata["design_brief_diagnostic_only"] = True
            updated_metadata["provider_field_lane_request_id"] = str(
                support.get("provider_field_lane_request_id", "") or ""
            )
            updated_metadata["uncovered_requested_row_ids"] = list(
                support.get("uncovered_requested_row_ids", []) or []
            )
            updated_metadata["support_recovered_at"] = now
            updated_directive["state"] = "blocked_for_support"
            updated_directive["metadata"] = updated_metadata
            updated_directive["updated_at"] = now
            _write_json(_directive_path(operator_root, directive_id), updated_directive)
            result["commercial_source_acquisition_repaired_count"] += 1
            result["parked_support_deferred_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "commercial_source_acquisition_required",
                    "support_state": "commercial_source_acquisition_required",
                    "support_result_ok": False,
                    "provider_field_lane_request_id": str(
                        support.get("provider_field_lane_request_id", "") or ""
                    ),
                    "uncovered_requested_row_ids": list(
                        support.get("uncovered_requested_row_ids", []) or []
                    ),
                    "materialization": {},
                }
            )
            continue
        support_state = str(support.get("support_state", "") or "")
        if _support_request_has_consumable_satisfied_pack(support):
            technology_design_active = bool(support.get("technology_design_obligation_active", False))
            recovery_state = "r_and_d_design_brief_ready" if technology_design_active else "support_ready_for_next_spawn"
            result_state = (
                "r_and_d_design_brief_ready_for_next_spawn"
                if technology_design_active
                else "support_ready_for_next_spawn"
            )
            updated_directive = dict(directive)
            updated_metadata = dict(metadata)
            updated_metadata["support_request_id"] = support_request_id
            updated_metadata["support_blocker_reason"] = ""
            updated_metadata["support_recovery_state"] = recovery_state
            updated_metadata["support_recovery_target_artifact"] = target_artifact
            updated_metadata["initial_work_order_target_artifact"] = target_artifact
            if technology_design_active:
                updated_metadata["child_work_mode"] = "design_only_reduction"
                updated_metadata["r_and_d_design_brief_ready"] = True
                updated_metadata["initial_work_order_context"] = (
                    f"Use R&D design brief {support.get('r_and_d_design_brief_id', '')} to design the "
                    f"missing technology obligations for {target_artifact}. This is design-ready only; "
                    "do not claim hardware build readiness until concrete source-backed components, "
                    "fixtures, risk controls, and acceptance evidence exist."
                )
                updated_metadata["r_and_d_design_brief_id"] = str(support.get("r_and_d_design_brief_id", "") or "")
                updated_metadata["technology_design_obligation_ids"] = list(
                    support.get("technology_design_obligation_ids", []) or []
                )
            updated_metadata["support_recovered_at"] = _utc_now()
            updated_directive["metadata"] = updated_metadata
            if state == "blocked_for_support":
                updated_directive["state"] = "requeued"
            updated_directive["updated_at"] = updated_metadata["support_recovered_at"]
            _write_json(_directive_path(operator_root, directive_id), updated_directive)
            result["parked_support_satisfied_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": result_state,
                    "support_state": support_state,
                    "support_result_ok": True,
                    "r_and_d_design_brief_id": str(support.get("r_and_d_design_brief_id", "") or ""),
                    "materialization": {},
                }
            )
            continue
        job_state = str(
            support.get("support_synthesis_job_state", "")
            or support.get("job_state", "")
            or ""
        )
        recovery_attempted = bool(support.get("parked_support_recovery_attempted", False))
        zero_row_support_blocker = (
            int(support.get("consumable_support_row_count", 0) or 0) <= 0
            and (
                bool(
                    str(support.get("trusted_source_error_class", "") or "")
                    or str(support.get("trusted_source_rejection_reason", "") or "")
                    or str(support.get("non_consumable_support_reasons", "") or "")
                )
                or str(metadata.get("support_blocker_reason", "") or "") == "no_consumable_support_rows"
                or str(support.get("support_blocker_reason", "") or "") == "no_consumable_support_rows"
                or str(support.get("candidate_ingestion_state", "") or "")
                in {"pending_support", "trusted_source_requested", "satisfied_from_consumable_pack"}
                or str(support.get("support_materialization_state", "") or "")
                in {
                    "parked_waiting_for_consumable_support",
                    "waiting_for_materialization",
                    "async_synthesis_failed",
                }
            )
        )
        stranded_core_recovery_marker = (
            bool(support.get("core_support_recovery_attempted", False))
            and not str(support.get("core_support_recovery_job_id", "") or "")
            and zero_row_support_blocker
        )
        if job_state in {"queued", "running", "trusted_source_synthesis_in_progress"}:
            result["parked_support_deferred_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "trusted_source_synthesis_in_progress",
                    "support_state": support_state,
                    "support_result_ok": False,
                    "materialization": {},
                }
            )
            continue
        design_recovery_candidate = _support_request_should_receive_r_and_d_design_brief(
            support,
            support_context,
        )
        if (
            recovery_attempted
            and job_state == "failed"
            and not stranded_core_recovery_marker
            and not design_recovery_candidate
        ):
            result["parked_support_deferred_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "pending_operator_review",
                    "reason": "parked_support_recovery_already_failed",
                    "support_state": support_state,
                    "support_result_ok": False,
                    "materialization": {},
                }
            )
            continue
        pack_ref = _support_pack_ref_for_candidate(
            operator_root,
            state_root=state_root,
            directive_id=directive_id,
            capability=str(support.get("capability", "") or "directive_build_grade_synthesis_pack"),
            target_artifact=target_artifact,
            required_fields=_support_request_required_fields(support),
            current_child_run_id="",
            exclude_support_request_id=support_request_id,
        )
        if pack_ref:
            pack_ref = _archive_satisfied_support_pack(
                operator_root,
                state_root=state_root,
                support_request_id=support_request_id,
                pack_ref=pack_ref,
            )
            support = _apply_satisfied_support_pack(support, pack_ref)
            support["candidate_ingestion_state"] = "satisfied_from_consumable_pack"
            support["support_materialization_state"] = "support_ready_for_next_spawn"
            support["support_recovery_state"] = "support_ready_for_next_spawn"
            support["updated_at"] = _utc_now()
            _write_json(_support_request_path(operator_root, support_request_id), support)
            repair_directive_support_request_freshness(operator_root, directive_id=directive_id)
            result["parked_support_satisfied_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "support_ready_for_next_spawn",
                    "support_state": "satisfied",
                    "support_result_ok": True,
                    "materialization": {},
                }
            )
            continue
        design_result = _satisfy_support_with_r_and_d_design_brief(
            operator_root,
            state_root=state_root,
            support=support,
        )
        if bool(design_result.get("ok", False)):
            support = dict(design_result.get("support_request", {}) or support)
            updated_directive = dict(directive)
            updated_metadata = dict(metadata)
            updated_metadata["support_request_id"] = support_request_id
            updated_metadata["support_blocker_reason"] = ""
            updated_metadata["support_recovery_state"] = "r_and_d_design_brief_ready"
            updated_metadata["support_recovery_target_artifact"] = target_artifact
            updated_metadata["initial_work_order_target_artifact"] = target_artifact
            updated_metadata["initial_work_order_context"] = (
                f"Use R&D design brief {support.get('r_and_d_design_brief_id', '')} to design the "
                f"missing technology obligations for {target_artifact}. This is design-ready only; "
                "do not claim hardware build readiness until concrete source-backed components, "
                "fixtures, risk controls, and acceptance evidence exist."
            )
            updated_metadata["r_and_d_design_brief_id"] = str(support.get("r_and_d_design_brief_id", "") or "")
            updated_metadata["technology_design_obligation_ids"] = list(
                support.get("technology_design_obligation_ids", []) or []
            )
            updated_metadata["child_work_mode"] = "design_only_reduction"
            updated_metadata["r_and_d_design_brief_ready"] = True
            updated_metadata["support_recovered_at"] = _utc_now()
            updated_directive["metadata"] = updated_metadata
            if state in {"blocked_for_support", "support_synthesis_in_progress"}:
                updated_directive["state"] = "requeued"
            updated_directive["updated_at"] = updated_metadata["support_recovered_at"]
            _write_json(_directive_path(operator_root, directive_id), updated_directive)
            repair_directive_support_request_freshness(operator_root, directive_id=directive_id)
            result["parked_support_satisfied_count"] += 1
            result["r_and_d_design_brief_created_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "r_and_d_design_brief_ready_for_next_spawn",
                    "support_state": "satisfied",
                    "support_result_ok": True,
                    "r_and_d_design_brief_id": str(support.get("r_and_d_design_brief_id", "") or ""),
                    "materialization": {},
                }
            )
            continue
        auto_cap = int(policy.get("auto_support_approval_cap", 0) or 0)
        auto_support_used = int(metadata.get("continuous_campaign_auto_support_approval_count", 0) or 0)
        cap_allows_auto_support = (
            remaining > 0
            and auto_support_used < auto_cap
            and str(policy.get("trusted_source_mode", "") or "") == "reuse_existing_then_capped_auto_approve"
        )
        external_budget = _support_synthesis_external_attempt_budget(
            operator_root,
            support_request_id,
        )
        if bool(external_budget.get("support_external_request_budget_exhausted", False)):
            support = _mark_support_synthesis_external_budget_exhausted(
                operator_root,
                support_request_id,
                budget=external_budget,
            )
            result["parked_support_deferred_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "pending_operator_review",
                    "reason": "support_external_request_budget_exhausted",
                    "support_state": str(support.get("support_state", "") or support_state),
                    "support_result_ok": False,
                    "external_request_budget_state": "exhausted",
                    "support_external_request_attempt_count": int(
                        external_budget.get("support_external_request_attempt_count", 0) or 0
                    ),
                    "support_external_request_attempt_cap": int(
                        external_budget.get("support_external_request_attempt_cap", 0) or 0
                    ),
                    "materialization": {},
                }
            )
            continue
        core_recovery_override = (
            not cap_allows_auto_support
            and str(policy.get("trusted_source_mode", "") or "") == "reuse_existing_then_capped_auto_approve"
            and zero_row_support_blocker
            and (
                not bool(support.get("core_support_recovery_attempted", False))
                or stranded_core_recovery_marker
            )
        )
        if cap_allows_auto_support or core_recovery_override:
            support = dict(support)
            now = _utc_now()
            support["parked_support_recovery_obligation_id"] = _record_id(
                "support-recovery",
                directive_id,
                support_request_id,
                target_artifact,
            )
            support["support_recovery_state"] = "trusted_source_synthesis_queued"
            support["support_recovery_target_artifact"] = target_artifact
            support["support_recovery_requested_at"] = now
            support["updated_at"] = now
            _write_json(_support_request_path(operator_root, support_request_id), support)
            job = _enqueue_resident_support_synthesis_job(
                operator_root,
                state_root=state_root,
                support_request=support,
                child={},
                target_artifact=target_artifact,
            )
            job_created = bool(job.get("job_created", False))
            if job_created:
                support = _read_json(_support_request_path(operator_root, support_request_id)) or dict(support)
                support["parked_support_recovery_attempted"] = True
                if core_recovery_override:
                    support["core_support_recovery_attempted"] = True
                    support["core_support_recovery_reason"] = "cap_exhausted_zero_row_support_recovery"
                    support["core_support_recovery_job_id"] = str(job.get("job_id", "") or "")
                    support["core_support_recovery_requested_at"] = now
                support["support_recovery_state"] = "trusted_source_synthesis_queued"
                support["support_recovery_target_artifact"] = target_artifact
                support["support_recovery_requested_at"] = now
                support["updated_at"] = now
                _write_json(_support_request_path(operator_root, support_request_id), support)
                if cap_allows_auto_support:
                    remaining -= 1
                    result["auto_support_used_count"] += 1
                if core_recovery_override:
                    result["core_support_recovery_override_count"] += 1
                result["parked_support_recovery_count"] += 1
                _set_continuous_campaign_metadata(
                    operator_root,
                    directive,
                    state="support_synthesis_in_progress",
                    action="queued_trusted_source_synthesis",
                    reason="parked_support_blocker_async_synthesis_queued",
                    support_request_id=support_request_id,
                    auto_support_increment=bool(cap_allows_auto_support),
                    target_artifact=target_artifact,
                )
            result["parked_support_deferred_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "trusted_source_synthesis_in_progress",
                    "support_state": "pending_operator_review",
                    "support_result_ok": False,
                    "async_job_enqueued": True,
                    "support_synthesis_job_id": str(job.get("job_id", "") or ""),
                    "job_created": job_created,
                    "core_support_recovery_override": core_recovery_override,
                    "materialization": {},
                }
            )
        else:
            result["parked_support_deferred_count"] += 1
            result["results"].append(
                {
                    "child_run_id": "",
                    "directive_id": directive_id,
                    "support_request_id": support_request_id,
                    "target_artifact": target_artifact,
                    "state": "pending_operator_review",
                    "reason": "parked_support_recovery_waiting_for_operator_or_policy_cap",
                    "support_state": support_state,
                    "support_result_ok": False,
                    "materialization": {},
                }
            )
    return result


def ingest_resident_support_request_candidates(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    auto_approve_limit: int = 1,
    runner: ConveyorChildRunner | None = None,
) -> dict[str, Any]:
    started = time.perf_counter()
    initialize_conveyor_state(operator_root)
    result: dict[str, Any] = {
        "ok": True,
        "schema_name": "ConveyorResidentSupportCandidateIngestion",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "attempted": False,
        "support_candidate_seen_count": 0,
        "support_candidate_ingested_count": 0,
        "support_candidate_satisfied_count": 0,
        "support_checkout_refreshed_count": 0,
        "support_tick_deferred_count": 0,
        "support_blocked_child_parked_count": 0,
        "parked_support_recovery_count": 0,
        "parked_support_satisfied_count": 0,
        "auto_support_used_count": 0,
        "core_support_recovery_override_count": 0,
        "r_and_d_design_brief_created_count": 0,
        "commercial_source_acquisition_repaired_count": 0,
        "technical_documentation_depth_support_repaired_count": 0,
        "parked_support_seed_satisfied_count": 0,
        "support_tick_duration_ms": 0.0,
        "results": [],
    }
    if state_root is None:
        result["ok"] = False
        result["reason"] = "state_root_required"
        return result
    support_pack_repair = _repair_satisfied_support_pack_archives(
        operator_root,
        state_root=state_root,
    )
    support_pointer_repair = repair_directive_support_request_freshness(operator_root)
    risk_control_support_refresh = _refresh_stale_risk_control_support_from_satisfied_bom_supports(
        operator_root
    )
    validation_fixture_support_refresh = _refresh_validation_fixture_support_from_satisfied_risk_controls(
        operator_root
    )
    result["support_pack_repair"] = support_pack_repair
    result["support_pointer_repair"] = support_pointer_repair
    result["risk_control_support_refresh"] = risk_control_support_refresh
    result["validation_fixture_support_refresh"] = validation_fixture_support_refresh
    result["support_pack_repaired_count"] = int(support_pack_repair.get("repaired_count", 0) or 0)
    result["support_pack_unrepairable_count"] = int(support_pack_repair.get("unrepairable_count", 0) or 0)
    result["support_pointer_repaired_count"] = int(
        support_pointer_repair.get("support_pointer_repaired_count", 0) or 0
    )
    result["technical_documentation_depth_support_repaired_count"] = int(
        support_pointer_repair.get("technical_documentation_depth_support_repaired_count", 0) or 0
    )
    result["risk_control_support_refresh_count"] = int(
        risk_control_support_refresh.get("risk_control_support_refresh_count", 0) or 0
    )
    result["validation_fixture_support_refresh_count"] = int(
        validation_fixture_support_refresh.get("validation_fixture_support_refresh_count", 0) or 0
    )
    scheduler = _load_scheduler(operator_root)
    if not bool(scheduler.get("continuous_campaign_mode", False)):
        result["reason"] = "continuous_campaign_mode_disabled"
        return result
    if _autonomy_emergency_stop_active(operator_root):
        result["reason"] = "emergency_stop"
        result["support_tick_deferred_count"] = 1
        return result
    policy = _continuous_campaign_policy(scheduler)
    effective_runner = runner or runner_from_scheduler(scheduler)
    auto_approve_remaining = max(0, int(auto_approve_limit or 0))
    parked_recovery = _recover_parked_support_blocked_directives(
        operator_root,
        state_root=Path(state_root),
        policy=policy,
        auto_approve_remaining=auto_approve_remaining,
    )
    result["parked_support_recovery"] = parked_recovery
    result["parked_support_recovery_count"] = int(
        parked_recovery.get("parked_support_recovery_count", 0) or 0
    )
    result["parked_support_satisfied_count"] = int(
        parked_recovery.get("parked_support_satisfied_count", 0) or 0
    )
    result["support_tick_deferred_count"] += int(
        parked_recovery.get("parked_support_deferred_count", 0) or 0
    )
    result["core_support_recovery_override_count"] = int(
        parked_recovery.get("core_support_recovery_override_count", 0) or 0
    )
    result["auto_support_used_count"] = int(
        parked_recovery.get("auto_support_used_count", 0) or 0
    )
    result["r_and_d_design_brief_created_count"] = int(
        parked_recovery.get("r_and_d_design_brief_created_count", 0) or 0
    )
    result["commercial_source_acquisition_repaired_count"] = int(
        parked_recovery.get("commercial_source_acquisition_repaired_count", 0) or 0
    )
    result["technical_documentation_depth_support_repaired_count"] += int(
        parked_recovery.get("technical_documentation_depth_support_repaired_count", 0) or 0
    )
    result["parked_support_seed_satisfied_count"] = int(
        parked_recovery.get("parked_support_seed_satisfied_count", 0) or 0
    )
    result["support_candidate_satisfied_count"] += int(
        parked_recovery.get("parked_support_satisfied_count", 0) or 0
    )
    auto_approve_remaining = max(
        0,
        auto_approve_remaining - int(parked_recovery.get("auto_support_used_count", 0) or 0),
    )
    result["results"].extend(list(parked_recovery.get("results", []) or []))
    for child in _active_children(operator_root):
        if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
            continue
        child_id = str(child.get("child_run_id", "") or "")
        latest_progress = _latest_child_progress(child)
        if not latest_progress:
            continue
        candidate = latest_progress.get("support_request_candidate", {})
        if not isinstance(candidate, Mapping) or not candidate:
            continue
        result["attempted"] = True
        result["support_candidate_seen_count"] += 1
        directive_id = str(child.get("directive_id", "") or latest_progress.get("directive_id", "") or "")
        try:
            directive = _load_directive(operator_root, directive_id)
        except ConveyorValidationError as exc:
            result["support_tick_deferred_count"] += 1
            result["results"].append(
                {
                    "child_run_id": child_id,
                    "directive_id": directive_id,
                    "state": "deferred",
                    "reason": "stale_directive_reference",
                    "message": str(exc),
                }
            )
            continue
        if policy.get("scope") == "build_grade_directives" and not _directive_expects_build_grade_documentation(directive):
            result["results"].append(
                {
                    "child_run_id": child_id,
                    "directive_id": directive_id,
                    "state": "skipped",
                    "reason": "directive_out_of_scope",
                }
            )
            continue
        candidate_key = _resident_support_candidate_idempotency_key(
            child=child,
            latest_progress=latest_progress,
            child_request=candidate,
        )
        existing_candidate_support = _support_request_for_candidate_key(operator_root, candidate_key)
        if (
            existing_candidate_support
            and str(existing_candidate_support.get("candidate_ingestion_state", "") or "") == "trusted_source_requested"
            and str(existing_candidate_support.get("support_materialization_state", "") or "") == "async_synthesis_failed"
            and not _support_request_has_consumable_satisfied_pack(existing_candidate_support)
        ):
            rebound_pack_ref = _satisfied_prior_support_pack_ref(
                operator_root,
                state_root=state_root,
                directive_id=directive_id,
                capability=str(
                    existing_candidate_support.get("capability", "")
                    or candidate.get("capability", "")
                    or ""
                ),
                target_artifact=str(
                    existing_candidate_support.get("target_artifact", "")
                    or candidate.get("target_artifact", "")
                    or ""
                ),
                required_fields=_support_request_required_fields(
                    existing_candidate_support,
                    latest_progress,
                ),
                current_child_run_id=child_id,
                exclude_support_request_id=str(
                    existing_candidate_support.get("support_request_id", "") or ""
                ),
            )
            if not rebound_pack_ref:
                existing_candidate_support["support_state"] = "pending_operator_review"
                existing_candidate_support["operator_review_required"] = True
                existing_candidate_support["updated_at"] = _utc_now()
                _write_json(
                    _support_request_path(
                        operator_root,
                        str(existing_candidate_support.get("support_request_id", "") or ""),
                    ),
                    existing_candidate_support,
                )
                result["support_tick_deferred_count"] += 1
                result["results"].append(
                    {
                        "child_run_id": child_id,
                        "directive_id": directive_id,
                        "support_request_id": str(existing_candidate_support.get("support_request_id", "") or ""),
                        "target_artifact": str(existing_candidate_support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""),
                        "support_state": "pending_operator_review",
                        "state": "trusted_source_requested",
                        "created": False,
                        "support_result_ok": False,
                        "materialization": {},
                    }
                )
                continue
        support, created = _resident_support_request_from_progress_candidate(
            operator_root,
            state_root=state_root,
            directive=directive,
            child=child,
            latest_progress=latest_progress,
            child_request=candidate,
        )
        if created:
            result["support_candidate_ingested_count"] += 1
        support_request_id = str(support.get("support_request_id", "") or "")
        support_result: dict[str, Any] = {}
        prior_candidate_state = str(support.get("candidate_ingestion_state", "") or "")
        prior_materialization_state = str(support.get("support_materialization_state", "") or "")
        if (
            not created
            and prior_candidate_state == "trusted_source_requested"
            and prior_materialization_state == "async_synthesis_failed"
            and not _support_request_has_consumable_satisfied_pack(support)
        ):
            pack_ref = _satisfied_prior_support_pack_ref(
                operator_root,
                state_root=state_root,
                directive_id=directive_id,
                capability=str(support.get("capability", "") or candidate.get("capability", "") or ""),
                target_artifact=str(support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""),
                required_fields=_support_request_required_fields(support, latest_progress),
                current_child_run_id=child_id,
                exclude_support_request_id=support_request_id,
            )
            if pack_ref:
                pack_ref = _archive_satisfied_support_pack(
                    operator_root,
                    state_root=state_root,
                    support_request_id=support_request_id,
                    pack_ref=pack_ref,
                )
                support = _apply_satisfied_support_pack(support, pack_ref)
                support["candidate_ingestion_state"] = "satisfied_from_consumable_pack"
                support["support_materialization_state"] = "waiting_for_materialization"
                support["updated_at"] = _utc_now()
                _write_json(_support_request_path(operator_root, support_request_id), support)
                _append_ledger(
                    operator_root,
                    "support_request_events",
                    {
                        "event": "resident_candidate_satisfied_from_existing_pack",
                        **support,
                    },
                )
                support_result = {"ok": True, "support_request": support}
            else:
                support["support_state"] = "pending_operator_review"
                support["operator_review_required"] = True
                support["updated_at"] = _utc_now()
                _write_json(_support_request_path(operator_root, support_request_id), support)
                materialized = {}
                result["support_tick_deferred_count"] += 1
                result["results"].append(
                    {
                        "child_run_id": child_id,
                        "directive_id": directive_id,
                        "support_request_id": support_request_id,
                        "target_artifact": str(support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""),
                        "support_state": "pending_operator_review",
                        "state": "trusted_source_requested",
                        "created": created,
                        "support_result_ok": False,
                        "materialization": materialized,
                    }
                )
                continue
        if str(support.get("support_state", "") or "") != "satisfied":
            pack_ref = _support_pack_ref_for_candidate(
                operator_root,
                state_root=state_root,
                directive_id=directive_id,
                capability=str(support.get("capability", "") or candidate.get("capability", "") or ""),
                target_artifact=str(support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""),
                required_fields=_support_request_required_fields(support, latest_progress),
                current_child_run_id=child_id,
                exclude_support_request_id=support_request_id,
            )
            if pack_ref:
                pack_ref = _archive_satisfied_support_pack(
                    operator_root,
                    state_root=state_root,
                    support_request_id=support_request_id,
                    pack_ref=pack_ref,
                )
                support = _apply_satisfied_support_pack(support, pack_ref)
                support["candidate_ingestion_state"] = "satisfied_from_consumable_pack"
                if bool(support.get("support_rebound_from_prior_child", False)):
                    support["support_materialization_state"] = "waiting_for_materialization"
                support["updated_at"] = _utc_now()
                _write_json(_support_request_path(operator_root, support_request_id), support)
                _append_ledger(
                    operator_root,
                    "support_request_events",
                    {
                        "event": "resident_candidate_satisfied_from_existing_pack",
                        **support,
                    },
                )
                support_result = {"ok": True, "support_request": support}
            else:
                design_result = _satisfy_support_with_r_and_d_design_brief(
                    operator_root,
                    state_root=state_root,
                    support=support,
                )
                if bool(design_result.get("ok", False)):
                    support = dict(design_result.get("support_request", {}) or support)
                    support_result = {"ok": True, "support_request": support}
                    result["r_and_d_design_brief_created_count"] += 1
                else:
                    metadata = dict(directive.get("metadata", {}) or {})
                    auto_support_used = int(metadata.get("continuous_campaign_auto_support_approval_count", 0) or 0)
                    auto_cap = int(policy.get("auto_support_approval_cap", 0) or 0)
                    if (
                        auto_approve_remaining > 0
                        and auto_support_used < auto_cap
                        and str(policy.get("trusted_source_mode", "") or "") == "reuse_existing_then_capped_auto_approve"
                    ):
                        auto_approve_remaining -= 1
                        job = _enqueue_resident_support_synthesis_job(
                            operator_root,
                            state_root=state_root,
                            support_request=support,
                            child=child,
                            target_artifact=str(support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""),
                        )
                        support = _read_json(_support_request_path(operator_root, support_request_id)) or support
                        support_result = {
                            "ok": False,
                            "async_job_enqueued": True,
                            "support_synthesis_job_id": str(job.get("job_id", "") or ""),
                        }
                        if bool(job.get("job_created", False)):
                            _set_continuous_campaign_metadata(
                                operator_root,
                                directive,
                                state="support_synthesis_in_progress",
                                action="queued_trusted_source_synthesis",
                                reason="resident_support_candidate_async_synthesis_queued",
                                support_request_id=support_request_id,
                                auto_support_increment=True,
                                target_artifact=str(support.get("target_artifact", "") or ""),
                            )
                    else:
                        support["candidate_ingestion_state"] = "pending_support"
                        support["operator_review_required"] = True
                        support["updated_at"] = _utc_now()
                        _write_json(_support_request_path(operator_root, support_request_id), support)
        if str(support.get("support_state", "") or "") == "satisfied":
            result["support_candidate_satisfied_count"] += 1 if created else 0
            materialized = _materialize_support_for_running_resident_child(
                operator_root,
                state_root=Path(state_root),
                child=child,
                latest_progress=latest_progress,
                target_artifact=str(support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""),
                support_request=support,
            )
            if bool(materialized.get("ok", False)):
                result["support_checkout_refreshed_count"] += 1
                state = str(materialized.get("support_materialization_state", "") or "satisfied")
            else:
                support_after_materialization = (
                    _read_json(_support_request_path(operator_root, support_request_id)) or support
                )
                design_result = _satisfy_support_with_r_and_d_design_brief(
                    operator_root,
                    state_root=state_root,
                    support=support_after_materialization,
                )
                if bool(design_result.get("ok", False)):
                    support = dict(design_result.get("support_request", {}) or support_after_materialization)
                    result["r_and_d_design_brief_created_count"] += 1
                    materialized = _materialize_support_for_running_resident_child(
                        operator_root,
                        state_root=Path(state_root),
                        child=child,
                        latest_progress=latest_progress,
                        target_artifact=str(
                            support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""
                        ),
                        support_request=support,
                    )
                    if bool(materialized.get("ok", False)):
                        result["support_checkout_refreshed_count"] += 1
                        state = "r_and_d_design_brief_materialized"
                    else:
                        result["support_tick_deferred_count"] += 1
                        materialized = _park_support_blocked_resident_child(
                            operator_root,
                            child=child,
                            directive=directive,
                            support_request=_read_json(_support_request_path(operator_root, support_request_id)) or support,
                            latest_progress=latest_progress,
                            runner=effective_runner,
                            target_artifact=str(
                                support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""
                            ),
                        )
                        result["support_blocked_child_parked_count"] += 1
                        state = "parked_waiting_for_consumable_support"
                else:
                    result["support_tick_deferred_count"] += 1
                    materialized = _park_support_blocked_resident_child(
                        operator_root,
                        child=child,
                        directive=directive,
                        support_request=support_after_materialization,
                        latest_progress=latest_progress,
                        runner=effective_runner,
                        target_artifact=str(
                            support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""
                        ),
                    )
                    result["support_blocked_child_parked_count"] += 1
                    state = "parked_waiting_for_consumable_support"
        else:
            materialized = {}
            state = str(support.get("candidate_ingestion_state", "") or "pending_support")
            result["support_tick_deferred_count"] += 1
            if state not in {"trusted_source_synthesis_in_progress"}:
                materialized = _park_support_blocked_resident_child(
                    operator_root,
                    child=child,
                    directive=directive,
                    support_request=support,
                    latest_progress=latest_progress,
                    runner=effective_runner,
                    target_artifact=str(
                        support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""
                    ),
                )
                result["support_blocked_child_parked_count"] += 1
                state = "parked_waiting_for_consumable_support"
        result["results"].append(
            {
                "child_run_id": child_id,
                "directive_id": directive_id,
                "support_request_id": support_request_id,
                "target_artifact": str(support.get("target_artifact", "") or candidate.get("target_artifact", "") or ""),
                "support_state": str(support.get("support_state", "") or ""),
                "state": state,
                "created": created,
                "support_result_ok": bool(support_result.get("ok", False)) if support_result else False,
                "materialization": materialized,
            }
        )
    result["support_tick_duration_ms"] = round((time.perf_counter() - started) * 1000, 3)
    try:
        snapshot = build_task_manager_snapshot(operator_root, persist=True)
        persist_bounded_status_snapshot(
            operator_root,
            task_manager_snapshot=snapshot,
            refreshed_by="support_tick",
        )
        result["bounded_status_snapshot_persisted_at"] = _utc_now()
        result["bounded_status_snapshot_refreshed_by"] = "support_tick"
    except Exception as exc:
        result["bounded_status_snapshot_refresh_error_class"] = type(exc).__name__
    return result


def _append_quality_growth_evidence(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    work_order: Mapping[str, Any],
    reason: str,
    record_consumption_event: bool = True,
) -> None:
    directive_id = str(child.get("directive_id", "") or "")
    child_id = str(child.get("child_run_id", "") or "")
    target_artifact = str(work_order.get("target_artifact", "") or "")
    failed_gates = [
        str(gate)
        for gate in list(work_order.get("quality_failed_gates", []) or [])
        if str(gate).strip()
    ]
    required_gate_closures = [
        str(gate)
        for gate in list(work_order.get("required_gate_closures", []) or [])
        if str(gate).strip()
    ]
    closed_failed_gates = [
        str(gate)
        for gate in list(latest_progress.get("closed_failed_gates", []) or [])
        if str(gate).strip()
    ]
    unchanged_failed_gates = [
        str(gate)
        for gate in list(latest_progress.get("remaining_failed_gates", []) or latest_progress.get("unchanged_failed_gates", []) or [])
        if str(gate).strip()
    ]
    target_correct_gate_closure = bool(
        required_gate_closures
        and set(required_gate_closures).issubset(set(closed_failed_gates))
        and not unchanged_failed_gates
    )
    dedupe_key = _record_id(
        "quality-growth-dedupe",
        directive_id,
        target_artifact,
        "|".join(sorted(set(failed_gates))),
        str(work_order.get("quality_state", "") or ""),
    )
    dedupe_signature = "|".join(
        [
            target_artifact,
            str(work_order.get("quality_state", "") or ""),
            ",".join(sorted(set(failed_gates))),
        ]
    )
    ledger_path = autonomy_root(operator_root) / "ledgers" / "conveyor_quality_growth_evidence.jsonl"
    if ledger_path.exists():
        try:
            for line in ledger_path.read_text(encoding="utf-8").splitlines()[-200:]:
                if not line.strip():
                    continue
                row = json.loads(line)
                if str(row.get("dedupe_signature", "") or "") == dedupe_signature:
                    return
        except (OSError, json.JSONDecodeError):
            pass
    now = _utc_now()
    evidence = {
        "schema_name": "ConveyorQualityGrowthEvidence",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "quality_growth_evidence_id": _record_id(
            "quality-growth",
            directive_id,
            child_id,
            target_artifact,
            str(latest_progress.get("cycle_index", "") or ""),
            reason,
        ),
        "created_at": now,
        "source": "conveyor_resident_quality_loop",
        "directive_id": directive_id,
        "child_run_id": child_id,
        "work_order_id": str(work_order.get("work_order_id", "") or ""),
        "target_artifact": target_artifact,
        "failed_quality_gates": failed_gates,
        "required_gate_closures": required_gate_closures,
        "closed_failed_gates": closed_failed_gates,
        "unchanged_failed_gates": unchanged_failed_gates,
        "gate_closure_since_last_cycle": bool(closed_failed_gates),
        "target_correct_gate_closure": target_correct_gate_closure,
        "kernel_consumed_gate_closure": bool(target_correct_gate_closure),
        "next_action_after_closure": (
            "retarget_next_unresolved_artifact" if target_correct_gate_closure else ""
        ),
        "schema_skeleton_id": str(
            work_order.get("schema_skeleton_id", "")
            or latest_progress.get("schema_skeleton_id", "")
            or ""
        ),
        "field_level_contract_applied": bool(
            latest_progress.get("field_level_contract_applied", False)
            or work_order.get("field_level_output_contract")
        ),
        "quality_state": str(work_order.get("quality_state", "") or ""),
        "quality_depth_score": float(work_order.get("quality_depth_score", 0.0) or 0.0),
        "reason": str(reason or ""),
        "dedupe_key": dedupe_key,
        "dedupe_signature": dedupe_signature,
        "proposed_capability_kinds": list(QUALITY_GROWTH_CAPABILITY_KINDS),
        "safety_gates_preserved": [
            "child_network_deny_all",
            "kernel_mediated_support_only",
            "canonical_promotion_kernel_owned",
        ],
    }
    _append_autonomy_ledger(operator_root, "conveyor_quality_growth_evidence", evidence)
    _write_json(autonomy_root(operator_root) / "conveyor_quality_growth_evidence_latest.json", evidence)
    if not record_consumption_event:
        return
    _persist_capability_consumption_event(
        operator_root,
        {
            "consumed_capability_kinds": list(QUALITY_GROWTH_CAPABILITY_KINDS),
            "planner_hook_references": [
                "conveyor.quality_gap_to_work_order_planner",
                "conveyor.promotion_packet_issuance",
            ],
            "runtime_hook_references": [
                str(work_order.get("work_order_id", "") or ""),
                str(evidence.get("quality_growth_evidence_id", "") or ""),
            ],
            "baseline_action": "continue_previous_resident_target",
            "final_action": "inject_quality_gap_work_order",
            "decision_changed_by_capability": True,
            "repeat_failure_prevented": True,
            "operator_intervention_reduced": True,
            "directive_progress_effect": "quality_gap_converted_to_targeted_work_order",
            "hook_reason": str(reason or ""),
            "safety_gates_preserved": list(evidence["safety_gates_preserved"]),
        },
        operation_id=str(work_order.get("work_order_id", "") or ""),
    )


def _append_growth_receipt(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    work_order: Mapping[str, Any],
    trigger_signal: str,
    selected_action: str,
    baseline_action: str,
    final_action: str,
    before_state: Mapping[str, Any],
    after_state: Mapping[str, Any],
    manifest: Mapping[str, Any] | None = None,
    reason: str = "",
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "")
    directive_id = str(child.get("directive_id", "") or "")
    work_order_id = str(work_order.get("work_order_id", "") or "")
    target_artifact = str(work_order.get("target_artifact", "") or "")
    inbox_path = _child_inbox_path(child)
    inbox_payload = _read_json(inbox_path)
    messages = [dict(item) for item in list(inbox_payload.get("messages", []) or []) if isinstance(item, Mapping)]
    inbox_work_order_present = any(
        str(item.get("kind", "") or "") == "kernel_work_order"
        and str(item.get("work_order_id", "") or "") == work_order_id
        for item in messages
    )
    wake_requested = str(inbox_payload.get("wake_work_order_id", "") or "") == work_order_id
    wake_ack = dict(child.get("latest_wake_ack", {}) or {})
    ack_evidence = {
        "acknowledged": bool(
            str(wake_ack.get("wake_work_order_id", "") or "") == work_order_id
            or str(wake_ack.get("work_order_id", "") or "") == work_order_id
        ),
        "wake_ack_at": str(wake_ack.get("acknowledged_at", "") or wake_ack.get("wake_ack_at", "") or ""),
    }
    try:
        repo_local_inbox_path = Path(inbox_path).resolve().is_relative_to(Path(operator_root).resolve())
    except (OSError, ValueError):
        repo_local_inbox_path = False
    delivery_evidence = {
        "repo_local_inbox_path": repo_local_inbox_path,
        "inbox_path": str(inbox_path),
        "inbox_work_order_present": inbox_work_order_present,
        "wake_requested": wake_requested,
        "wake_reason": str(inbox_payload.get("wake_reason", "") or ""),
        "wake_sequence": int(inbox_payload.get("wake_sequence", 0) or 0),
        "network_policy": str(work_order.get("network_policy", "") or ""),
        "kernel_mediated_only": bool(work_order.get("kernel_mediated_only", False)),
        "deny_all_preserved": str(work_order.get("network_policy", "") or "") == "deny_all",
    }
    canonical_effect = {
        "target_artifact": target_artifact,
        "target_delta_applied": bool(
            str(before_state.get("target_artifact", "") or before_state.get("active_target_artifact", "") or "")
            and str(after_state.get("target_artifact", "") or after_state.get("active_target_artifact", "") or "")
            and str(before_state.get("target_artifact", "") or before_state.get("active_target_artifact", "") or "")
            != str(after_state.get("target_artifact", "") or after_state.get("active_target_artifact", "") or "")
        ),
        "manifest_next_unresolved_gate_artifact": str(
            dict(manifest or {}).get("next_unresolved_gate_artifact", "")
            or dict(manifest or {}).get("weakest_failed_artifact", "")
            or ""
        ),
        "canonical_schema_resonance_reached": bool(
            float(dict(dict(manifest or {}).get("schema_resonance", {}) or {}).get("score", 0.0) or 0.0)
            >= 1.0
        ),
    }
    verified_delivery = bool(
        inbox_work_order_present
        and wake_requested
        and repo_local_inbox_path
        and delivery_evidence["deny_all_preserved"]
        and delivery_evidence["kernel_mediated_only"]
    )
    receipt = {
        "schema_name": "CapabilityConsumptionReceipt",
        "schema_version": "novali_autonomy_v1",
        "created_at": _utc_now(),
        "growth_episode_id": _record_id(
            "growth-episode",
            directive_id,
            child_id,
            selected_action,
            target_artifact,
            work_order_id,
        ),
        "receipt_id": _record_id(
            "growth-receipt",
            directive_id,
            child_id,
            selected_action,
            target_artifact,
            work_order_id,
        ),
        "source": "conveyor_resident_quality_loop",
        "capability_kind": "conveyor_self_structuring_receipts_v1",
        "trigger_signal": str(trigger_signal or ""),
        "selected_action": str(selected_action or ""),
        "baseline_action": str(baseline_action or ""),
        "final_action": str(final_action or ""),
        "decision_changed": False,
        "receipt_state": "verified_delivery" if verified_delivery else "diagnostic_evidence_only",
        "directive_id": directive_id,
        "child_run_id": child_id,
        "work_order_id": work_order_id,
        "target_artifact": target_artifact,
        "before_state": dict(before_state),
        "after_state": dict(after_state),
        "delivery_evidence": delivery_evidence,
        "ack_evidence": ack_evidence,
        "canonical_effect": canonical_effect,
        "later_consumption": {
            "later_consumed": False,
            "required_for_strict_usefulness": True,
            "target_artifact": target_artifact,
            "required_gate_closures": [
                str(gate)
                for gate in list(work_order.get("required_gate_closures", []) or [])
                if str(gate).strip()
            ],
            "quality_failed_gates": [
                str(gate)
                for gate in list(work_order.get("quality_failed_gates", []) or [])
                if str(gate).strip()
            ],
        },
        "strict_usefulness_eligible": False,
        "strict_growth_blockers": [
            "later_consumption_not_observed",
            "promotion_and_later_decision_change_required",
        ],
        "reason": str(reason or ""),
        "dedupe_signature": "|".join(
            [directive_id, child_id, selected_action, target_artifact, work_order_id]
        ),
    }
    ledger_path = autonomy_root(operator_root) / "ledgers" / "capability_consumption_receipts.jsonl"
    if ledger_path.exists():
        try:
            for line in ledger_path.read_text(encoding="utf-8").splitlines()[-200:]:
                if not line.strip():
                    continue
                row = json.loads(line)
                if str(row.get("dedupe_signature", "") or "") == str(receipt["dedupe_signature"]):
                    return row
        except (OSError, json.JSONDecodeError):
            pass
    record = _append_autonomy_ledger(operator_root, "capability_consumption_receipts", receipt)
    _append_autonomy_ledger(operator_root, "growth_episodes", record)
    _write_json(autonomy_root(operator_root) / "capability_consumption_receipt_latest.json", record)
    return record


def _read_growth_receipt_ledger(operator_root: str | Path, *, limit: int = 200) -> list[dict[str, Any]]:
    ledger_path = autonomy_root(operator_root) / "ledgers" / "capability_consumption_receipts.jsonl"
    rows: deque[dict[str, Any]] = deque(maxlen=max(1, limit))
    if not ledger_path.exists():
        return []
    try:
        for line in ledger_path.read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            payload = json.loads(line)
            if isinstance(payload, dict):
                rows.append(payload)
    except (OSError, json.JSONDecodeError):
        return []
    return list(rows)


def _progress_artifact_rows(latest_progress: Mapping[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for key in (
        "target_artifact_rows",
        "artifact_rows",
        "bill_of_materials_rows",
        "bom_rows",
    ):
        for row in list(latest_progress.get(key, []) or []):
            if isinstance(row, Mapping):
                rows.append(dict(row))
    return rows


def _magnetic_sensor_split_required(
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    *,
    target_artifact: str,
    required_gates: Iterable[str],
) -> bool:
    if target_artifact != "bill_of_materials.json":
        return False
    latest_work_order = dict(child.get("latest_work_order", {}) or {})
    haystack = " ".join(
        [
            str(child.get("directive_id", "") or ""),
            str(child.get("directive_text", "") or ""),
            str(latest_work_order.get("operator_feedback", "") or ""),
            str(latest_work_order.get("feedback", "") or ""),
            str(latest_work_order.get("target_artifact", "") or ""),
            " ".join(str(gate) for gate in list(required_gates or [])),
            str(latest_progress.get("operator_feedback", "") or ""),
            str(latest_progress.get("proof_target", "") or ""),
        ]
    ).lower()
    return "magnetic" in haystack or "sensor_array" in haystack


def _row_identity_text(row: Mapping[str, Any]) -> str:
    return " ".join(
        str(row.get(key, "") or "")
        for key in (
            "row_id",
            "item_id",
            "component_id",
            "id",
            "name",
            "required_for",
            "category",
            "function",
            "subsystem",
        )
    ).lower()


def _row_has_source_backed_build_specifics(row: Mapping[str, Any]) -> bool:
    return bool(
        str(row.get("manufacturer", "") or "").strip()
        and str(row.get("mpn", row.get("part_number", "")) or "").strip()
        and str(row.get("datasheet_url", row.get("source_url", row.get("citation_ref", ""))) or "").strip()
        and str(row.get("validation_fixture_ref", row.get("fixture_ref", "")) or "").strip()
        and str(row.get("linked_risk_control_ref", row.get("risk_ref", "")) or "").strip()
        and (
            str(row.get("go_no_go_trace", "") or "").strip()
            or bool(row.get("acceptance_thresholds"))
            or bool(row.get("test_equipment"))
        )
    )


def _magnetic_sensor_split_closed(latest_progress: Mapping[str, Any]) -> bool:
    rows = _progress_artifact_rows(latest_progress)
    if not rows:
        return False
    role_terms = {
        "thermal": ("thermal", "temperature", "thermocouple", "rtd"),
        "current": ("current", "amp"),
        "magnetic": ("gauss", "gaussmeter", "magnetic_field", "magnetic field", "hall", "field sensor"),
        "coolant": ("coolant", "cooling", "flow"),
        "daq": ("daq", "logging", "logger", "data acquisition"),
    }
    matched_row_ids: dict[str, str] = {}
    for row in rows:
        identity = _row_identity_text(row)
        if not identity or not _row_has_source_backed_build_specifics(row):
            continue
        row_id = str(
            row.get("row_id")
            or row.get("item_id")
            or row.get("component_id")
            or row.get("id")
            or row.get("name")
            or identity
        )
        for role, terms in role_terms.items():
            if role in matched_row_ids:
                continue
            if any(term in identity for term in terms):
                matched_row_ids[role] = row_id
    return set(matched_row_ids) == set(role_terms) and len(set(matched_row_ids.values())) >= len(role_terms)


def _append_depth_obligation_later_consumption_if_strict_capable(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> dict[str, Any]:
    latest_work_order = dict(child.get("latest_work_order", {}) or {})
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    depth_obligation_id = str(
        child.get("depth_obligation_id", "")
        or latest_work_order.get("depth_obligation_id", "")
        or ""
    ).strip()
    if not child_id or not depth_obligation_id:
        return {}

    depth_target = str(
        child.get("depth_target_artifact", "")
        or latest_work_order.get("depth_target_artifact", "")
        or ""
    ).strip()
    latest_work_order_target = str(
        child.get("latest_work_order_target_artifact", "")
        or latest_work_order.get("target_artifact", "")
        or ""
    ).strip()
    progress_target = str(latest_progress.get("target_artifact", "") or "").strip()
    allowed_targets = {target for target in (depth_target, latest_work_order_target) if target}
    if not progress_target or progress_target not in allowed_targets:
        return {}
    target_artifact = depth_target if depth_target == progress_target else progress_target

    required_gates = [
        str(gate).strip()
        for gate in list(
            child.get("depth_required_gate_closures", [])
            or latest_work_order.get("depth_required_gate_closures", [])
            or latest_work_order.get("required_gate_closures", [])
            or []
        )
        if str(gate).strip()
    ]
    if not required_gates:
        return {}

    def _progress_list(*keys: str) -> list[str]:
        values: list[str] = []
        for key in keys:
            source: Any = latest_progress
            for part in key.split("."):
                if not isinstance(source, Mapping):
                    source = {}
                    break
                source = source.get(part, {})
            values.extend(str(item).strip() for item in list(source or []) if str(item).strip())
        return values

    closed_failed_gates = sorted(
        set(
            _progress_list(
                "closed_failed_gates",
                "closed_gates",
                "gate_closures",
                "gate_closure_summary.closed_failed_gates",
                "latest_gate_closure_summary.closed_failed_gates",
                "target_correct_gate_closure.closed_failed_gates",
            )
        )
    )
    if not set(required_gates).issubset(set(closed_failed_gates)):
        return {}
    still_failed_gates = set(
        _progress_list(
            "remaining_failed_gates",
            "unchanged_failed_gates",
            "gate_closure_summary.remaining_failed_gates",
            "gate_closure_summary.unchanged_failed_gates",
            "latest_gate_closure_summary.remaining_failed_gates",
            "latest_gate_closure_summary.unchanged_failed_gates",
            "target_correct_gate_closure.remaining_failed_gates",
            "target_correct_gate_closure.unchanged_failed_gates",
        )
    )
    if set(required_gates).intersection(still_failed_gates):
        return {}

    artifact_deltas = [
        dict(delta)
        for delta in list(latest_progress.get("artifact_deltas", []) or [])
        if isinstance(delta, Mapping)
    ]
    artifact_delta_targets = {
        str(
            delta.get("artifact_name", "")
            or delta.get("target_artifact", "")
            or delta.get("artifact", "")
            or ""
        ).strip()
        for delta in artifact_deltas
        if str(
            delta.get("artifact_name", "")
            or delta.get("target_artifact", "")
            or delta.get("artifact", "")
            or ""
        ).strip()
    }
    try:
        artifact_delta_count = int(latest_progress.get("artifact_delta_count", 0) or 0)
    except (TypeError, ValueError):
        artifact_delta_count = 0
    draft_changed_this_cycle = bool(latest_progress.get("draft_changed_this_cycle", False))
    artifact_delta_count_targets_depth = bool(
        artifact_delta_count > 0
        and (not artifact_deltas or target_artifact in artifact_delta_targets)
    )
    target_specific_delta_observed = bool(
        latest_progress.get("target_draft_changed_this_cycle", False)
        or latest_progress.get("target_artifact_delta_observed", False)
        or latest_progress.get("target_delta_observed", False)
        or latest_progress.get("target_draft_delta_observed", False)
    )
    draft_delta_observed = bool(
        draft_changed_this_cycle
        or artifact_delta_count_targets_depth
        or target_artifact in artifact_delta_targets
        or target_specific_delta_observed
    )
    if not draft_delta_observed:
        return {}

    def _truthy_value(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return value > 0
        text = str(value or "").strip().lower()
        try:
            return float(text) > 0
        except ValueError:
            pass
        return text in {"1", "true", "yes", "y", "positive", "observed"}

    def _truthy_progress_flag(name: str) -> bool:
        return _truthy_value(latest_progress.get(name, False))

    later_progress = dict(latest_progress.get("later_consumption", {}) or {})
    intervention_or_failure_delta = bool(
        _truthy_progress_flag("operator_intervention_reduced")
        or _truthy_progress_flag("repeat_failure_prevented")
        or _truthy_progress_flag("positive_directive_progress_delta")
        or _truthy_progress_flag("intervention_or_failure_delta")
        or _truthy_progress_flag("failure_prevention_delta")
        or _truthy_progress_flag("directive_progress_delta")
        or _truthy_value(later_progress.get("intervention_or_failure_delta", False))
    )
    if not intervention_or_failure_delta:
        return {}
    if _magnetic_sensor_split_required(
        child,
        latest_progress,
        target_artifact=target_artifact,
        required_gates=required_gates,
    ) and not _magnetic_sensor_split_closed(latest_progress):
        return {}

    try:
        progress_cycle_index = int(float(latest_progress.get("cycle_index", 0) or 0))
    except (TypeError, ValueError):
        progress_cycle_index = 0
    dedupe_signature = "|".join(
        [
            child_id,
            depth_obligation_id,
            target_artifact,
            str(progress_cycle_index),
        ]
    )
    receipt_id = _record_id("growth-receipt", "depth-obligation", dedupe_signature)
    for row in _read_growth_receipt_ledger(operator_root, limit=300):
        if str(row.get("receipt_id", "") or "") == receipt_id:
            return row
        if str(row.get("dedupe_signature", "") or "") == dedupe_signature:
            return row

    work_order_id = str(
        latest_progress.get("work_order_id", "")
        or latest_progress.get("wake_work_order_id", "")
        or child.get("latest_work_order_id", "")
        or latest_work_order.get("work_order_id", "")
        or ""
    ).strip()
    receipt = {
        "schema_name": "CapabilityConsumptionReceipt",
        "schema_version": "novali_autonomy_v1",
        "created_at": _utc_now(),
        "receipt_id": receipt_id,
        "source": "conveyor_resident_quality_loop",
        "capability_kind": "conveyor_self_structuring_receipts_v1",
        "receipt_state": "later_consumed",
        "directive_id": directive_id,
        "child_run_id": child_id,
        "work_order_id": work_order_id,
        "depth_obligation_id": depth_obligation_id,
        "target_artifact": target_artifact,
        "later_consumption": {
            "later_consumed": True,
            "target_artifact": target_artifact,
            "work_order_id": work_order_id,
            "depth_obligation_id": depth_obligation_id,
            "progress_cycle_index": progress_cycle_index,
            "progress_generated_at": str(latest_progress.get("generated_at", "") or ""),
            "target_correct_gate_closure": True,
            "required_gate_closures": required_gates,
            "closed_failed_gates": closed_failed_gates,
            "intervention_or_failure_delta": True,
            "draft_delta_observed": True,
            "draft_changed_this_cycle": draft_changed_this_cycle,
            "artifact_delta_count": artifact_delta_count,
            "artifact_delta_targets": sorted(artifact_delta_targets),
            "artifact_deltas": artifact_deltas,
        },
        "strict_usefulness_eligible": True,
        "strict_growth_blockers": [],
        "grants_execution_authority": False,
        "dedupe_signature": dedupe_signature,
    }
    record = _append_autonomy_ledger(operator_root, "capability_consumption_receipts", receipt)
    _append_autonomy_ledger(operator_root, "growth_episodes", record)
    _write_json(autonomy_root(operator_root) / "capability_consumption_receipt_latest.json", record)
    return record


def _append_later_consumed_growth_receipt_events(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    draft_delta_quality: Mapping[str, Any],
    promotion: Mapping[str, Any] | None = None,
) -> list[dict[str, Any]]:
    directive_id = str(child.get("directive_id", "") or "")
    child_id = str(child.get("child_run_id", "") or "")
    progress_work_order_id = str(
        latest_progress.get("work_order_id", "")
        or latest_progress.get("wake_work_order_id", "")
        or child.get("latest_work_order_id", "")
        or ""
    )
    if not directive_id or not child_id or not progress_work_order_id:
        return []
    rows = _read_growth_receipt_ledger(operator_root, limit=200)
    consumed_ids = {
        str(row.get("receipt_id", "") or "")
        for row in rows
        if bool(dict(row.get("later_consumption", {}) or {}).get("later_consumed", False))
        or str(row.get("receipt_state", "") or "") == "later_consumed"
    }
    progress_target = str(latest_progress.get("target_artifact", "") or draft_delta_quality.get("target_artifact", "") or "")
    artifact_deltas = [dict(item) for item in list(latest_progress.get("artifact_deltas", []) or []) if isinstance(item, Mapping)]
    progress_delta_targets = {
        str(item.get("artifact_name", "") or "").strip()
        for item in artifact_deltas
        if str(item.get("artifact_name", "") or "").strip()
    }
    draft_delta_observed = bool(
        _resident_progress_has_meaningful_delta(latest_progress)
        or draft_delta_quality.get("draft_changed_since_last_review", False)
        or draft_delta_quality.get("draft_changed_from_canonical", False)
        or artifact_deltas
    )
    closed_failed_gates = [
        str(gate)
        for gate in list(latest_progress.get("closed_failed_gates", []) or [])
        if str(gate).strip()
    ]
    remaining_failed_gates = [
        str(gate)
        for gate in list(latest_progress.get("remaining_failed_gates", []) or latest_progress.get("unchanged_failed_gates", []) or [])
        if str(gate).strip()
    ]
    try:
        quality_delta_count = int(dict(promotion or {}).get("quality_delta_count", 0) or 0)
    except (TypeError, ValueError):
        quality_delta_count = 0
    appended: list[dict[str, Any]] = []
    for row in rows:
        receipt_id = str(row.get("receipt_id", "") or "")
        if not receipt_id or receipt_id in consumed_ids:
            continue
        row_directive_id = str(row.get("directive_id", "") or "")
        if row_directive_id and row_directive_id not in {directive_id, "[REDACTED]"}:
            continue
        if str(row.get("child_run_id", "") or "") != child_id:
            continue
        if str(row.get("work_order_id", "") or "") != progress_work_order_id:
            continue
        if str(row.get("receipt_state", "") or "") not in {"verified_delivery", "verified_canonical_effect"}:
            continue
        delivery = dict(row.get("delivery_evidence", {}) or {})
        if not (
            bool(delivery.get("inbox_work_order_present", False))
            and bool(delivery.get("wake_requested", False))
            and bool(delivery.get("repo_local_inbox_path", False))
            and bool(delivery.get("deny_all_preserved", False))
            and bool(delivery.get("kernel_mediated_only", False))
        ):
            continue
        target_artifact = str(row.get("target_artifact", "") or "")
        before = dict(row.get("before_state", {}) or {})
        before_target = str(before.get("target_artifact", "") or before.get("active_target_artifact", "") or "")
        target_behavior_changed = bool(
            target_artifact
            and progress_target == target_artifact
            and (not before_target or before_target != progress_target)
        )
        target_delta_observed = bool(target_artifact and target_artifact in progress_delta_targets)
        canonical_effect_observed = bool(
            quality_delta_count > 0
            or dict(row.get("canonical_effect", {}) or {}).get("target_delta_applied", False)
            and target_behavior_changed
        )
        decision_changed = bool(
            target_behavior_changed
            and (draft_delta_observed or target_delta_observed or canonical_effect_observed)
        )
        if not decision_changed:
            continue
        prior_later = dict(row.get("later_consumption", {}) or {})
        required_gate_closures = [
            str(gate)
            for gate in list(prior_later.get("required_gate_closures", []) or [])
            if str(gate).strip()
        ]
        if not required_gate_closures:
            required_gate_closures = [
                str(gate)
                for gate in list(prior_later.get("quality_failed_gates", []) or [])
                if str(gate).strip()
            ]
        target_correct_gate_closure = bool(
            not remaining_failed_gates
            and (
                bool(required_gate_closures and set(required_gate_closures).issubset(set(closed_failed_gates)))
                or bool(not required_gate_closures and closed_failed_gates)
            )
        )
        intervention_or_failure_delta = bool(
            target_correct_gate_closure
            and (
                canonical_effect_observed
                or draft_delta_observed
                or target_delta_observed
                or quality_delta_count > 0
            )
        )
        strict_growth_blockers = ["promotion_and_later_decision_change_required"]
        if not target_correct_gate_closure:
            strict_growth_blockers.append("target_correct_closure_not_observed")
        if target_correct_gate_closure and not intervention_or_failure_delta:
            strict_growth_blockers.append("intervention_delta_not_observed")
        update = {
            **dict(row),
            "created_at": _utc_now(),
            "receipt_event_type": "later_consumed",
            "receipt_state": "later_consumed",
            "decision_changed": True,
            "ack_evidence": {
                **dict(row.get("ack_evidence", {}) or {}),
                "acknowledged": True,
                "progress_work_order_id": progress_work_order_id,
                "progress_cycle_index": int(float(latest_progress.get("cycle_index", 0) or 0)),
                "progress_generated_at": str(latest_progress.get("generated_at", "") or ""),
            },
            "later_consumption": {
                **prior_later,
                "later_consumed": True,
                "consumed_at": _utc_now(),
                "progress_work_order_id": progress_work_order_id,
                "progress_cycle_index": int(float(latest_progress.get("cycle_index", 0) or 0)),
                "target_behavior_changed": target_behavior_changed,
                "draft_delta_observed": bool(draft_delta_observed or target_delta_observed),
                "canonical_effect_observed": canonical_effect_observed,
                "closed_failed_gates": closed_failed_gates,
                "remaining_failed_gates": remaining_failed_gates,
                "target_correct_gate_closure": target_correct_gate_closure,
                "operator_intervention_reduced": intervention_or_failure_delta,
                "repeat_failure_prevented": intervention_or_failure_delta,
                "directive_progress_delta": 1.0 if intervention_or_failure_delta else 0.0,
            },
            "strict_usefulness_eligible": bool(target_correct_gate_closure and intervention_or_failure_delta),
            "strict_growth_blockers": strict_growth_blockers,
        }
        record = _append_autonomy_ledger(operator_root, "capability_consumption_receipts", update)
        _append_autonomy_ledger(operator_root, "growth_episodes", record)
        _write_json(autonomy_root(operator_root) / "capability_consumption_receipt_latest.json", record)
        appended.append(record)
        consumed_ids.add(receipt_id)
    return appended


def _manifest_next_unresolved_gate_artifact(manifest: Mapping[str, Any]) -> str:
    prototype_cluster = dict(manifest.get("prototype_cluster_closure", {}) or {})
    target = str(manifest.get("next_unresolved_gate_artifact", "") or "").strip()
    if target:
        return target
    target = str(prototype_cluster.get("next_unresolved_artifact", "") or "").strip()
    if target:
        return target
    for key in ("weakest_failed_artifact", "latest_quality_target"):
        fallback = str(manifest.get(key, "") or "").strip()
        if fallback:
            return fallback
    return str(prototype_cluster.get("next_unresolved_artifact", "") or "").strip()


def _active_child_target_artifact(child: Mapping[str, Any], manifest: Mapping[str, Any] | None = None) -> str:
    manifest = manifest or {}
    for value in (
        child.get("latest_work_order_target_artifact", ""),
        child.get("latest_target_artifact", ""),
        manifest.get("active_child_target_artifact", ""),
    ):
        target = str(value or "").strip()
        if target:
            return target
    return ""


def _resident_child_target_drift_record(
    child: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    active_target = _active_child_target_artifact(child, manifest)
    next_target = _manifest_next_unresolved_gate_artifact(manifest)
    return {
        "child_run_id": str(child.get("child_run_id", "") or ""),
        "directive_id": str(child.get("directive_id", "") or ""),
        "active_child_target_artifact": active_target,
        "latest_work_order_target_artifact": active_target,
        "manifest_next_unresolved_gate_artifact": next_target,
        "target_drift_detected": bool(active_target and next_target and active_target != next_target),
    }


def _schema_resonance_followup_record(
    child: Mapping[str, Any],
    manifest: Mapping[str, Any],
    latest_progress: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    progress = dict(latest_progress or {}) or dict(child.get("latest_progress", {}) or {}) or _latest_child_progress(child)
    active_target = _active_child_target_artifact(child, manifest)
    progress_target = str(progress.get("target_artifact", "") or "").strip()
    schema_resonance = dict(manifest.get("schema_resonance", {}) or {})
    schema_target = str(schema_resonance.get("target_artifact", "") or active_target)
    missing_fields = [
        str(item).strip()
        for item in list(schema_resonance.get("required_fields_missing", []) or [])
        if str(item).strip()
    ]
    required_fields = [
        str(item).strip()
        for item in list(schema_resonance.get("required_fields", []) or missing_fields)
        if str(item).strip()
    ]
    try:
        score = float(schema_resonance.get("score", 1.0) or 0.0)
    except (TypeError, ValueError):
        score = 0.0
    closed_gates = [
        str(item).strip()
        for item in list(progress.get("closed_failed_gates", []) or [])
        if str(item).strip()
    ]
    remaining_gates = [
        str(item).strip()
        for item in list(progress.get("remaining_failed_gates", []) or progress.get("unchanged_failed_gates", []) or [])
        if str(item).strip()
    ]
    target_matches = bool(
        active_target
        and progress_target == active_target
        and (not schema_target or schema_target == active_target)
    )
    progress_claimed_closure = bool(closed_gates and not remaining_gates)
    followup_required = bool(target_matches and progress_claimed_closure and score < 1.0 and missing_fields)
    return {
        "child_run_id": str(child.get("child_run_id", "") or ""),
        "directive_id": str(child.get("directive_id", "") or ""),
        "target_artifact": active_target,
        "progress_target_artifact": progress_target,
        "schema_resonance_followup_required": followup_required,
        "schema_resonance_score": score,
        "required_top_level_fields": required_fields,
        "missing_top_level_fields": missing_fields,
        "artifact_top_level_schema_skeleton": _schema_followup_skeleton(required_fields),
        "progress_closed_failed_gates": closed_gates,
        "progress_remaining_failed_gates": remaining_gates,
    }


def _latest_work_order_has_schema_followup(
    child: Mapping[str, Any],
    target_artifact: str,
    missing_fields: Iterable[Any],
) -> bool:
    work_order = dict(child.get("latest_work_order", {}) or {})
    if str(work_order.get("target_artifact", "") or "") != str(target_artifact or ""):
        return False
    if not bool(work_order.get("schema_resonance_followup_required", False)):
        return False
    existing_missing = {
        str(item).strip()
        for item in list(work_order.get("missing_top_level_fields", []) or [])
        if str(item).strip()
    }
    expected_missing = {str(item).strip() for item in list(missing_fields or []) if str(item).strip()}
    skeleton = work_order.get("artifact_top_level_schema_skeleton", {})
    skeleton_keys = set(dict(skeleton).keys()) if isinstance(skeleton, Mapping) else set()
    return bool(expected_missing and existing_missing == expected_missing and expected_missing.issubset(skeleton_keys))


def _active_capability_proof_obligation_for_target(
    operator_root: str | Path,
    target_artifact: str,
) -> dict[str, Any]:
    target = str(target_artifact or "").strip()
    if not target:
        return {}
    latest = _read_json(autonomy_root(operator_root) / "capability_proof_obligation_latest.json")
    candidates: list[dict[str, Any]] = []
    if latest:
        candidates.append(latest)
    ledger = autonomy_root(operator_root) / "ledgers" / "capability_proof_obligations.jsonl"
    if ledger.exists():
        try:
            for line in ledger.read_text(encoding="utf-8").splitlines()[-100:]:
                if not line.strip():
                    continue
                payload = json.loads(line)
                if isinstance(payload, dict):
                    candidates.append(payload)
        except (OSError, json.JSONDecodeError):
            pass
    for item in reversed(candidates):
        if not bool(item.get("active", False)):
            continue
        if str(item.get("proof_target_artifact", "") or "").strip() != target:
            continue
        return item
    return {}


def _inject_schema_resonance_followup_work_order(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    followup: Mapping[str, Any],
    now: str | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    now = now or _utc_now()
    target_artifact = str(followup.get("target_artifact", "") or "")
    reason = (
        "schema_resonance_followup_required: child reported closed gates but manifest schema resonance "
        f"for {target_artifact} is still below 1.0."
    )
    work_order = _append_resident_work_order(
        operator_root,
        state_root=state_root,
        child=child,
        latest_progress=latest_progress,
        target_artifact=target_artifact,
        reason=reason,
        schema_resonance_followup={
            "schema_resonance_followup_required": True,
            "schema_resonance_score": float(followup.get("schema_resonance_score", 0.0) or 0.0),
            "required_top_level_fields": list(followup.get("required_top_level_fields", []) or []),
            "missing_top_level_fields": list(followup.get("missing_top_level_fields", []) or []),
            "artifact_top_level_schema_skeleton": dict(
                followup.get("artifact_top_level_schema_skeleton", {}) or {}
            ),
        },
    )
    updated = dict(child)
    target_correct_state = dict(updated.get("target_correct_gate_closure", {}) or {})
    if target_correct_state:
        target_correct_state["kernel_consumed_gate_closure"] = False
        target_correct_state["next_action_after_closure"] = ""
        updated["target_correct_gate_closure"] = target_correct_state
    updated.update(
        {
            "latest_work_order_id": str(work_order.get("work_order_id", "") or ""),
            "latest_work_order_target_artifact": target_artifact,
            "latest_target_artifact": target_artifact,
            "latest_quality_target": target_artifact,
            "latest_work_order": dict(work_order),
            "latest_work_order_at": str(work_order.get("generated_at", "") or ""),
            "latest_quality_retarget_reason": "schema_resonance_followup_required",
            "resident_worker_state": "schema_resonance_followup_injected",
            "schema_resonance_followup_required": True,
            "schema_resonance_score": float(followup.get("schema_resonance_score", 0.0) or 0.0),
            "missing_top_level_fields": list(followup.get("missing_top_level_fields", []) or []),
            "required_top_level_fields": list(followup.get("required_top_level_fields", []) or []),
            "artifact_top_level_schema_skeleton": dict(
                followup.get("artifact_top_level_schema_skeleton", {}) or {}
            ),
            "schema_resonance_followup": {
                "created_at": now,
                "target_artifact": target_artifact,
                "schema_resonance_score": float(followup.get("schema_resonance_score", 0.0) or 0.0),
                "missing_top_level_fields": list(followup.get("missing_top_level_fields", []) or []),
                "work_order_id": str(work_order.get("work_order_id", "") or ""),
            },
            "updated_at": now,
        }
    )
    growth_receipt = _append_growth_receipt(
        operator_root,
        child=updated,
        work_order=work_order,
        trigger_signal="schema_resonance_followup_required",
        selected_action="repair_active_schema_resonance_followup",
        baseline_action="accept_progress_reported_gate_closure",
        final_action="inject_schema_resonance_followup_work_order",
        before_state={
            "target_artifact": target_artifact,
            "schema_resonance_score": float(followup.get("schema_resonance_score", 0.0) or 0.0),
            "missing_top_level_fields": list(followup.get("missing_top_level_fields", []) or []),
        },
        after_state={
            "target_artifact": target_artifact,
            "schema_resonance_followup_required": True,
            "missing_top_level_fields": list(followup.get("missing_top_level_fields", []) or []),
        },
        manifest={},
        reason=reason,
    )
    updated["growth_receipt_id"] = str(growth_receipt.get("receipt_id", "") or "")
    updated["growth_receipt_state"] = str(growth_receipt.get("receipt_state", "") or "")
    return updated, work_order


def repair_active_schema_resonance_followup(
    operator_root: str | Path,
    *,
    state_root: str | Path | None = None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    now = _utc_now()
    checked_count = 0
    followup_records: list[dict[str, Any]] = []
    repairs: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    children = [
        child
        for child in _load_items(_children_root(operator_root))
        if str(child.get("state", "") or "") not in TERMINAL_CHILD_STATES
        and str(child.get("directive_id", "") or "")
    ]
    for child in children:
        checked_count += 1
        child_id = str(child.get("child_run_id", "") or "")
        directive_id = str(child.get("directive_id", "") or "")
        latest_progress = dict(child.get("latest_progress", {}) or {}) or _latest_child_progress(child)
        try:
            manifest = _write_campaign_manifest(operator_root, directive_id, active_child=child)
        except Exception as exc:
            skipped.append(
                {
                    "child_run_id": child_id,
                    "directive_id": directive_id,
                    "reason": "manifest_refresh_failed",
                    "error": str(exc),
                }
            )
            continue
        followup = _schema_resonance_followup_record(child, manifest, latest_progress)
        if not bool(followup.get("schema_resonance_followup_required", False)):
            manifest_followup = _manifest_schema_resonance_followup_record(child, manifest)
            if bool(manifest_followup.get("schema_resonance_followup_required", False)):
                followup = manifest_followup
        if not bool(followup.get("schema_resonance_followup_required", False)):
            continue
        followup_records.append(followup)
        target_artifact = str(followup.get("target_artifact", "") or "")
        if target_artifact not in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER:
            skipped.append({**followup, "reason": "target_not_reviewable"})
            continue
        if _latest_work_order_has_schema_followup(
            child,
            target_artifact,
            list(followup.get("missing_top_level_fields", []) or []),
        ):
            skipped.append({**followup, "reason": "schema_followup_already_active"})
            continue
        updated, work_order = _inject_schema_resonance_followup_work_order(
            operator_root,
            state_root=state_root,
            child=child,
            latest_progress=latest_progress,
            followup=followup,
            now=now,
        )
        _write_json(_child_path(operator_root, child_id), updated)
        _append_ledger(
            operator_root,
            "child_events",
            {
                "event": "schema_resonance_followup_injected",
                "generated_at": now,
                "child_run_id": child_id,
                "directive_id": directive_id,
                "target_artifact": target_artifact,
                "work_order_id": str(work_order.get("work_order_id", "") or ""),
                "schema_resonance_score": float(followup.get("schema_resonance_score", 0.0) or 0.0),
                "missing_top_level_fields": list(followup.get("missing_top_level_fields", []) or []),
            },
        )
        repairs.append(
            {
                **followup,
                "work_order_id": str(work_order.get("work_order_id", "") or ""),
            }
        )
    return {
        "ok": True,
        "schema_name": "ConveyorSchemaResonanceFollowupRepair",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": now,
        "checked_child_count": checked_count,
        "followup_required": bool(followup_records),
        "followup_required_count": len(followup_records),
        "repaired_count": len(repairs),
        "skipped_count": len(skipped),
        "repairs": repairs,
        "skipped": skipped,
        "followup_records": followup_records,
    }


def repair_active_resident_target_drift(
    operator_root: str | Path,
    *,
    state_root: str | Path | None = None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    now = _utc_now()
    children = [
        child
        for child in _load_items(_children_root(operator_root))
        if str(child.get("state", "") or "") not in TERMINAL_CHILD_STATES
        and str(child.get("directive_id", "") or "")
    ]
    checked_count = 0
    drift_records: list[dict[str, Any]] = []
    repairs: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    for child in children:
        checked_count += 1
        child_id = str(child.get("child_run_id", "") or "")
        directive_id = str(child.get("directive_id", "") or "")
        try:
            manifest = _write_campaign_manifest(operator_root, directive_id, active_child=child)
        except Exception as exc:
            skipped.append(
                {
                    "child_run_id": child_id,
                    "directive_id": directive_id,
                    "reason": "manifest_refresh_failed",
                    "error": str(exc),
                }
            )
            continue
        drift = _resident_child_target_drift_record(child, manifest)
        if not drift["target_drift_detected"]:
            continue
        drift_records.append(drift)
        previous_target = str(drift.get("active_child_target_artifact", "") or "")
        target_artifact = str(drift.get("manifest_next_unresolved_gate_artifact", "") or "")
        if target_artifact not in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER:
            skipped.append({**drift, "reason": "target_not_reviewable"})
            continue
        if bool(child.get("return_requested_after_clean_delta", False)):
            skipped.append({**drift, "reason": "clean_delta_return_already_requested"})
            continue
        latest_progress = dict(child.get("latest_progress", {}) or {}) or _latest_child_progress(child)
        if not latest_progress:
            latest_progress = {
                "cycle_index": int(child.get("cycle_index", 0) or 0),
                "target_artifact": previous_target,
                "closed_failed_gates": [],
                "remaining_failed_gates": list(manifest.get("failed_quality_gates", []) or []),
            }
        reason = (
            "manifest_next_unresolved_gate_drift: active resident target "
            f"{previous_target} differs from manifest next unresolved gate artifact {target_artifact}."
        )
        work_order = _append_resident_work_order(
            operator_root,
            state_root=state_root,
            child=child,
            latest_progress=latest_progress,
            target_artifact=target_artifact,
            reason=reason,
        )
        _append_quality_growth_evidence(
            operator_root,
            child=child,
            latest_progress=latest_progress,
            work_order=work_order,
            reason=reason,
            record_consumption_event=False,
        )
        child_path = _child_path(operator_root, child_id)
        refreshed_child = _read_json(child_path) or dict(child)
        refreshed_child.update(
            {
                "latest_work_order_id": str(work_order.get("work_order_id", "") or ""),
                "latest_work_order_target_artifact": target_artifact,
                "latest_target_artifact": target_artifact,
                "latest_quality_target": target_artifact,
                "latest_work_order": dict(work_order),
                "latest_quality_retarget_reason": "manifest_next_unresolved_gate_drift",
                "resident_worker_state": "manifest_target_retargeted",
                "target_drift_detected": False,
                "previous_work_order_target_artifact": previous_target,
                "manifest_next_unresolved_gate_artifact": target_artifact,
                "manifest_target_drift_repair": {
                    "repaired_at": now,
                    "previous_target_artifact": previous_target,
                    "target_artifact": target_artifact,
                    "reason": "manifest_next_unresolved_gate_drift",
                    "work_order_id": str(work_order.get("work_order_id", "") or ""),
                },
                "updated_at": now,
            }
        )
        _write_json(child_path, refreshed_child)
        growth_receipt = _append_growth_receipt(
            operator_root,
            child=refreshed_child,
            work_order=work_order,
            trigger_signal="manifest_next_unresolved_gate_drift",
            selected_action="repair_active_resident_target_drift",
            baseline_action="continue_previous_resident_target",
            final_action="retarget_to_manifest_next_unresolved_gate_artifact",
            before_state={
                "active_target_artifact": previous_target,
                "target_artifact": previous_target,
            },
            after_state={
                "active_target_artifact": target_artifact,
                "target_artifact": target_artifact,
            },
            manifest=manifest,
            reason=reason,
        )
        _append_ledger(
            operator_root,
            "child_events",
            {
                "event": "active_resident_target_drift_repaired",
                "generated_at": now,
                "child_run_id": child_id,
                "directive_id": directive_id,
                "previous_target_artifact": previous_target,
                "target_artifact": target_artifact,
                "work_order_id": str(work_order.get("work_order_id", "") or ""),
                "growth_receipt_id": str(growth_receipt.get("receipt_id", "") or ""),
                "reason": "manifest_next_unresolved_gate_drift",
            },
        )
        repairs.append(
            {
                **drift,
                "previous_target_artifact": previous_target,
                "target_artifact": target_artifact,
                "work_order_id": str(work_order.get("work_order_id", "") or ""),
                "quality_growth_evidence_recorded": True,
                "growth_receipt_id": str(growth_receipt.get("receipt_id", "") or ""),
                "growth_receipt_state": str(growth_receipt.get("receipt_state", "") or ""),
            }
        )
    return {
        "ok": True,
        "schema_name": "ConveyorActiveResidentTargetDriftRepair",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": now,
        "checked_child_count": checked_count,
        "target_drift_detected": bool(drift_records),
        "target_drift_detected_count": len(drift_records),
        "repaired_count": len(repairs),
        "skipped_count": len(skipped),
        "repairs": repairs,
        "skipped": skipped,
        "drift_records": drift_records,
    }


def _append_prototype_promotion_proof_receipt(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    next_unresolved_artifact: str,
    reason: str,
) -> dict[str, Any]:
    directive_id = str(child.get("directive_id", "") or "")
    child_id = str(child.get("child_run_id", "") or "")
    target_artifact = str(latest_progress.get("target_artifact", "") or "").strip()
    closed_failed_gates = [
        str(gate)
        for gate in list(latest_progress.get("closed_failed_gates", []) or [])
        if str(gate).strip()
    ]
    remaining_failed_gates = [
        str(gate)
        for gate in list(latest_progress.get("remaining_failed_gates", []) or latest_progress.get("unchanged_failed_gates", []) or [])
        if str(gate).strip()
    ]
    if not directive_id or not child_id or not target_artifact or not closed_failed_gates or remaining_failed_gates:
        return {}
    directive = _read_json(_directive_path(operator_root, directive_id))
    if not _hardware_build_packet_required(directive, child):
        return {}
    assessment = _assess_hardware_build_packet(
        operator_root,
        directive_id,
        directive=directive,
        active_child=child,
    )
    fixture = dict(assessment.get("prototype_evidence_fixture", {}) or {})
    if not bool(assessment.get("promotion_proof_eligible", False)):
        return {}
    next_action = "retarget_next_unresolved_artifact" if next_unresolved_artifact else "request_final_return"
    receipt = {
        "schema_name": "PrototypePromotionProofReceipt",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "prototype_promotion_proof_receipt_id": "",
        "created_at": _utc_now(),
        "fixture_id": str(assessment.get("fixture_id", "") or fixture.get("fixture_id", "")),
        "directive_id": directive_id,
        "child_run_id": child_id,
        "requested_target_artifact": target_artifact,
        "closed_gates": closed_failed_gates,
        "remaining_gates": remaining_failed_gates,
        "field_gaps_before": [],
        "field_gaps_after": dict(assessment.get("field_gaps_by_artifact", {}) or {}),
        "cross_artifact_links_verified": bool(fixture.get("cross_artifact_links_verified", False)),
        "safety_gates_preserved": list(fixture.get("safety_gates_preserved", []) or []),
        "kernel_consumed_closure": True,
        "next_action_after_closure": next_action,
        "next_unresolved_gate_artifact": str(next_unresolved_artifact or ""),
        "promotion_proof_eligible": True,
        "reason": str(reason or ""),
    }
    receipt["prototype_promotion_proof_receipt_id"] = _record_id(
        "prototype-proof",
        directive_id,
        child_id,
        target_artifact,
        ",".join(sorted(closed_failed_gates)),
        next_action,
    )
    _append_autonomy_ledger(operator_root, "prototype_promotion_proof_receipts", receipt)
    _write_json(autonomy_root(operator_root) / "prototype_promotion_proof_receipt_latest.json", receipt)
    evidence = {
        "schema_name": "ConveyorQualityGrowthEvidence",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "quality_growth_evidence_id": _record_id(
            "prototype-proof-quality-growth",
            receipt["prototype_promotion_proof_receipt_id"],
        ),
        "created_at": _utc_now(),
        "source": "prototype_promotion_proof_receipt",
        "directive_id": directive_id,
        "child_run_id": child_id,
        "target_artifact": target_artifact,
        "fixture_id": receipt["fixture_id"],
        "prototype_promotion_proof_receipt_id": receipt["prototype_promotion_proof_receipt_id"],
        "promotion_proof_eligible": True,
        "required_gate_closures": closed_failed_gates,
        "closed_failed_gates": closed_failed_gates,
        "unchanged_failed_gates": [],
        "gate_closure_since_last_cycle": True,
        "target_correct_gate_closure": True,
        "kernel_consumed_gate_closure": True,
        "next_action_after_closure": next_action,
        "next_unresolved_gate_artifact": str(next_unresolved_artifact or ""),
        "grants_execution_authority": False,
        "safety_gates_preserved": receipt["safety_gates_preserved"],
        "cross_artifact_links_verified": receipt["cross_artifact_links_verified"],
        "reason": str(reason or ""),
    }
    _append_autonomy_ledger(operator_root, "conveyor_quality_growth_evidence", evidence)
    _write_json(autonomy_root(operator_root) / "conveyor_quality_growth_evidence_latest.json", evidence)
    return receipt


def _append_target_correct_gate_closure_evidence(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    next_unresolved_artifact: str,
    reason: str,
) -> None:
    target_artifact = str(latest_progress.get("target_artifact", "") or "").strip()
    closed_failed_gates = [
        str(gate)
        for gate in list(latest_progress.get("closed_failed_gates", []) or [])
        if str(gate).strip()
    ]
    remaining_failed_gates = [
        str(gate)
        for gate in list(latest_progress.get("remaining_failed_gates", []) or latest_progress.get("unchanged_failed_gates", []) or [])
        if str(gate).strip()
    ]
    if not target_artifact or not closed_failed_gates or remaining_failed_gates:
        return
    directive_id = str(child.get("directive_id", "") or "")
    child_id = str(child.get("child_run_id", "") or "")
    evidence = {
        "schema_name": "ConveyorQualityGrowthEvidence",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "quality_growth_evidence_id": _record_id(
            "target-correct-quality-growth",
            directive_id,
            child_id,
            target_artifact,
            ",".join(sorted(closed_failed_gates)),
            str(next_unresolved_artifact or ""),
        ),
        "created_at": _utc_now(),
        "source": "conveyor_target_correct_gate_closure",
        "directive_id": directive_id,
        "child_run_id": child_id,
        "target_artifact": target_artifact,
        "required_gate_closures": closed_failed_gates,
        "closed_failed_gates": closed_failed_gates,
        "unchanged_failed_gates": [],
        "gate_closure_since_last_cycle": True,
        "target_correct_gate_closure": True,
        "kernel_consumed_gate_closure": True,
        "next_action_after_closure": "retarget_next_unresolved_artifact" if next_unresolved_artifact else "request_final_return",
        "next_unresolved_gate_artifact": str(next_unresolved_artifact or ""),
        "reason": str(reason or ""),
        "safety_gates_preserved": [
            "child_network_deny_all",
            "kernel_mediated_support_only",
            "operator_review_required_before_acceptance",
        ],
    }
    _append_autonomy_ledger(operator_root, "conveyor_quality_growth_evidence", evidence)
    _write_json(autonomy_root(operator_root) / "conveyor_quality_growth_evidence_latest.json", evidence)
    _append_prototype_promotion_proof_receipt(
        operator_root,
        child=child,
        latest_progress=latest_progress,
        next_unresolved_artifact=next_unresolved_artifact,
        reason=reason,
    )
    if target_artifact == "risk_controls.json" and next_unresolved_artifact == "validation_fixtures.json":
        _write_json(_conveyor_root(operator_root) / "risk_control_materialization_evidence_latest.json", {
            **evidence,
            "closed_target_artifact": "risk_controls.json",
            "next_linked_artifact_target": "validation_fixtures.json",
            "partial_target_correct_closure": True,
            "grants_execution_authority": False,
        })


def _resident_progress_has_meaningful_delta(progress: Mapping[str, Any]) -> bool:
    if bool(progress.get("support_to_artifact_required_field_delta", False)) or bool(
        progress.get("support_to_artifact_delta", False)
    ):
        return True
    if str(progress.get("bom_field_closure_state", "") or "") in {"closed", "partial"} and list(
        progress.get("bom_closed_requested_row_ids", []) or []
    ):
        return True
    if str(progress.get("role_lane_closure_state", "") or "") in {"closed", "partial"} and list(
        progress.get("role_lane_closed_requested_row_ids", []) or []
    ):
        return True
    if str(progress.get("risk_control_materialization_state", "") or "") == "materialized" and list(
        progress.get("risk_control_materialized_rows", []) or []
    ):
        return True
    if str(progress.get("validation_fixture_materialization_state", "") or "") == "materialized" and list(
        progress.get("validation_fixture_materialized_rows", []) or []
    ):
        return True
    deltas = [delta for delta in list(progress.get("artifact_deltas", []) or []) if isinstance(delta, Mapping)]
    for delta in deltas:
        if str(delta.get("delta_kind", "") or "") not in {"created", "revised"}:
            continue
        before_hash = str(
            delta.get("before_hash", "")
            or delta.get("previous_hash", "")
            or delta.get("canonical_before_hash", "")
            or ""
        )
        after_hash = str(
            delta.get("after_hash", "")
            or delta.get("new_hash", "")
            or delta.get("draft_after_hash", "")
            or ""
        )
        if before_hash and after_hash and before_hash == after_hash:
            continue
        return True
    return False


def _resident_progress_indicates_mount_fault(progress: Mapping[str, Any] | None) -> bool:
    if not isinstance(progress, Mapping) or not progress:
        return False
    if bool(progress.get("infrastructure_fault", False)) and str(progress.get("blocked_reason", "") or "") == "docker_mount_fault":
        return True
    return "docker_mount_fault" in {
        str(progress.get("blocked_reason", "") or ""),
        str(progress.get("cycle_outcome", "") or ""),
        str(progress.get("progress_state", "") or ""),
    }


def _child_inspect_indicates_mount_fault(state: Mapping[str, Any], child: Mapping[str, Any]) -> bool:
    try:
        exit_code = int(state.get("exit_code", child.get("container_exit_code", -1)) or -1)
    except (TypeError, ValueError):
        exit_code = -1
    if exit_code == MOUNT_FAULT_EXIT_CODE:
        return True
    return _resident_progress_indicates_mount_fault(_latest_child_progress(child))


def _child_inspect_indicates_missing_container(state: Mapping[str, Any]) -> bool:
    state_name = str(state.get("state", "") or "").strip().lower()
    error_text = " ".join(
        [
            str(state.get("error", "") or ""),
            str(state.get("stderr", "") or ""),
            str(state.get("message", "") or ""),
        ]
    ).lower()
    if state_name not in {"unknown", "missing", "not_found", "not-found"}:
        return False
    return bool(
        "no such object" in error_text
        or "no such container" in error_text
        or "container not found" in error_text
        or "not found" in error_text
    )


def _child_requested_final_return(child: Mapping[str, Any]) -> bool:
    if bool(child.get("return_requested_after_clean_delta", False)):
        return True
    inbox_payload = _read_json(_child_inbox_path(child))
    return bool(
        inbox_payload.get("request_final_return", False)
        or inbox_payload.get("return_requested_after_clean_delta", False)
    )


def _missing_container_recovery_evidence(
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> dict[str, Any]:
    directive_id = str(child.get("directive_id", "") or "")
    progress_directive_id = str(latest_progress.get("directive_id", "") or directive_id)
    same_directive_progress = bool(latest_progress) and progress_directive_id == directive_id
    try:
        artifact_delta_count = int(latest_progress.get("artifact_delta_count", 0) or 0)
    except (TypeError, ValueError):
        artifact_delta_count = 0
    materialized_expected_files = [
        str(item)
        for item in list(latest_progress.get("materialized_expected_files", []) or [])
        if str(item).strip()
    ]
    progress_has_delta = bool(
        same_directive_progress
        and (
            bool(latest_progress.get("meaningful_delta", False))
            or artifact_delta_count > 0
            or materialized_expected_files
            or _resident_progress_has_meaningful_delta(latest_progress)
        )
    )
    artifact_names, _manifest = _latest_child_workspace_artifacts(child)
    workspace_has_artifacts = bool(artifact_names)
    target_artifact = str(
        latest_progress.get("target_artifact", "")
        or child.get("latest_work_order_target_artifact", "")
        or child.get("latest_target_artifact", "")
        or ""
    ).strip()
    work_order_id = str(
        latest_progress.get("work_order_id", "")
        or child.get("latest_work_order_id", "")
        or ""
    ).strip()
    blockers: list[str] = []
    if not directive_id:
        blockers.append("missing_directive_id")
    if not same_directive_progress and latest_progress:
        blockers.append("progress_directive_mismatch")
    if not progress_has_delta and not workspace_has_artifacts:
        blockers.append("missing_progress_or_workspace_evidence")
    return {
        "recoverable": bool(directive_id and not blockers),
        "blockers": blockers,
        "progress_has_delta": progress_has_delta,
        "workspace_has_artifacts": workspace_has_artifacts,
        "workspace_artifacts": artifact_names,
        "artifact_delta_count": artifact_delta_count,
        "materialized_expected_files": materialized_expected_files,
        "target_artifact": target_artifact,
        "work_order_id": work_order_id,
        "latest_progress_ref": {
            "child_run_id": str(latest_progress.get("child_run_id", "") or child.get("child_run_id", "") or ""),
            "directive_id": progress_directive_id,
            "cycle_index": latest_progress.get("cycle_index", ""),
            "generated_at": str(latest_progress.get("generated_at", "") or ""),
            "target_artifact": target_artifact,
            "work_order_id": work_order_id,
        },
    }


def _requeue_missing_container_child_without_return(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    recovery: Mapping[str, Any],
    inspect_state: Mapping[str, Any],
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    now = _utc_now()
    updated_child = dict(child)
    updated_child["state"] = "failed"
    updated_child["failed_reason"] = "missing_container_before_final_return"
    updated_child["missing_container_recovery_blocked"] = True
    updated_child["missing_container_recovery_blockers"] = ["final_return_not_requested"]
    updated_child["missing_container_after_return_request"] = False
    updated_child["container_missing_after_return_request"] = False
    updated_child["last_inspect_state"] = str(inspect_state.get("state", "") or "")
    updated_child["last_inspect_result"] = dict(inspect_state)
    updated_child["missing_container_last_seen_at"] = now
    updated_child["updated_at"] = now
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated_child)

    directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    target = str(recovery.get("target_artifact", "") or child.get("latest_work_order_target_artifact", "") or "").strip()
    feedback_parts = [
        str(directive.get("operator_feedback", "") or "").strip(),
        (
            "The prior resident child container disappeared before emitting a final return packet, but it left "
            "usable progress/workspace evidence. Requeue from the latest campaign draft instead of waiting on the "
            "missing child."
        ),
    ]
    if target:
        feedback_parts.append(f"Continue on {target} and preserve the current row-level gate feedback.")
    feedback = " ".join(part for part in feedback_parts if part)
    if directive_id and directive:
        directive["state"] = "requeued"
        directive["active_child_run_id"] = ""
        directive["operator_feedback"] = feedback
        directive["requeue_count"] = int(directive.get("requeue_count", 0) or 0) + 1
        directive["updated_at"] = now
        _write_json(_directive_path(operator_root, directive_id), directive)
    event = {
        "event": "missing_container_child_requeued_without_return",
        "generated_at": now,
        "child_run_id": child_id,
        "directive_id": directive_id,
        "target_artifact": target,
        "workspace_artifacts": list(recovery.get("workspace_artifacts", []) or []),
        "artifact_delta_count": int(recovery.get("artifact_delta_count", 0) or 0),
        "last_inspect_result": dict(inspect_state),
    }
    _append_ledger(operator_root, "child_events", event)
    return updated_child


def _classify_terminal_child_without_return(
    child: Mapping[str, Any],
    *,
    inspect_state: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    recovery: Mapping[str, Any],
) -> dict[str, Any]:
    try:
        exit_code = int(inspect_state.get("exit_code", child.get("container_exit_code", -1)) or -1)
    except (TypeError, ValueError):
        exit_code = -1
    progress_has_delta = bool(recovery.get("progress_has_delta", False))
    workspace_has_artifacts = bool(recovery.get("workspace_has_artifacts", False))
    support_request_candidate = latest_progress.get("support_request_candidate", {})
    has_support_candidate = isinstance(support_request_candidate, Mapping) and bool(support_request_candidate)
    has_blocked_progress = bool(
        has_support_candidate
        or str(latest_progress.get("cycle_outcome", "") or "") in {"blocked", "needs_support"}
        or str(latest_progress.get("progress_state", "") or "") in {"blocked", "needs_support", "needs_operator"}
        or list(latest_progress.get("remaining_failed_gates", []) or [])
    )
    if bool(child.get("stop_requested", False)) or str(child.get("requested_child_control_action", "") or "") == "stop":
        classification = "intentional_stop"
    elif progress_has_delta or workspace_has_artifacts:
        classification = "productive_pass_completed_not_review_ready"
    elif has_blocked_progress:
        classification = "blocked_pass_completed_not_review_ready"
    else:
        classification = "infrastructure_failed"
    return {
        "schema_name": "ChildLifecycleAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "child_run_id": str(child.get("child_run_id", "") or ""),
        "directive_id": str(child.get("directive_id", "") or ""),
        "child_lifecycle_classification": classification,
        "container_exit_code": exit_code,
        "productive_pass_delta_observed": progress_has_delta,
        "productive_pass_completed_not_review_ready": classification == "productive_pass_completed_not_review_ready",
        "blocked_pass_completed_not_review_ready": classification == "blocked_pass_completed_not_review_ready",
        "productive_pass_target_artifact": str(recovery.get("target_artifact", "") or ""),
        "next_unresolved_artifact": str(
            latest_progress.get("next_unresolved_artifact", "")
            or latest_progress.get("target_artifact", "")
            or recovery.get("target_artifact", "")
            or ""
        ),
        "remaining_failed_gates": [
            str(item) for item in list(latest_progress.get("remaining_failed_gates", []) or []) if str(item).strip()
        ],
        "support_request_candidate": dict(support_request_candidate) if has_support_candidate else {},
        "last_inspect_result": dict(inspect_state),
        "grants_execution_authority": False,
    }


def _record_terminal_child_without_review_return(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    lifecycle: Mapping[str, Any],
    recovery: Mapping[str, Any],
    inspect_state: Mapping[str, Any],
) -> dict[str, Any]:
    child_id = str(child.get("child_run_id", "") or "").strip()
    directive_id = str(child.get("directive_id", "") or "").strip()
    now = _utc_now()
    classification = str(lifecycle.get("child_lifecycle_classification", "") or "")
    target = str(
        lifecycle.get("productive_pass_target_artifact", "")
        or recovery.get("target_artifact", "")
        or child.get("latest_work_order_target_artifact", "")
        or ""
    ).strip()
    updated_child = dict(child)
    updated_child["state"] = "stopped" if classification == "intentional_stop" else "failed"
    updated_child["failed_reason"] = classification
    updated_child["child_lifecycle_classification"] = classification
    updated_child["productive_pass_completed_not_review_ready"] = bool(
        lifecycle.get("productive_pass_completed_not_review_ready", False)
    )
    updated_child["blocked_pass_completed_not_review_ready"] = bool(
        lifecycle.get("blocked_pass_completed_not_review_ready", False)
    )
    updated_child["productive_pass_delta_observed"] = bool(lifecycle.get("productive_pass_delta_observed", False))
    updated_child["productive_pass_target_artifact"] = target
    updated_child["non_reviewable_pass_result"] = True
    updated_child["container_exit_code"] = lifecycle.get("container_exit_code", "")
    updated_child["last_inspect_state"] = str(inspect_state.get("state", "") or "")
    updated_child["last_inspect_result"] = dict(inspect_state)
    updated_child["latest_progress"] = dict(_latest_child_progress(child) or {})
    updated_child["updated_at"] = now
    if child_id:
        _write_json(_child_path(operator_root, child_id), updated_child)

    directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    support_candidate = lifecycle.get("support_request_candidate", {})
    support_candidate_map = support_candidate if isinstance(support_candidate, Mapping) else {}
    support_blocked = bool(
        support_candidate_map
        and str(support_candidate_map.get("reason", "") or "")
    )
    if directive_id and directive:
        feedback_parts = [
            str(directive.get("operator_feedback", "") or "").strip(),
            (
                "The prior resident child ended before emitting a valid return packet, but Novali found "
                "target-artifact progress and treated it as a productive non-review-ready pass."
                if classification == "productive_pass_completed_not_review_ready"
                else "The prior resident child ended blocked before emitting a valid return packet."
            ),
        ]
        if target:
            feedback_parts.append(f"Continue on {target}; preserve the newest campaign draft and close the exact remaining gates.")
        state = "blocked_for_support" if support_blocked else "requeued"
        directive["state"] = state
        directive["active_child_run_id"] = ""
        directive["operator_feedback"] = " ".join(part for part in feedback_parts if part)
        directive["requeue_count"] = int(directive.get("requeue_count", 0) or 0) + 1
        metadata = dict(directive.get("metadata", {}) or {})
        metadata["child_lifecycle_classification"] = classification
        metadata["productive_pass_target_artifact"] = target
        metadata["productive_pass_delta_observed"] = bool(lifecycle.get("productive_pass_delta_observed", False))
        metadata["non_reviewable_pass_result"] = True
        metadata["next_unresolved_artifact"] = str(lifecycle.get("next_unresolved_artifact", "") or target)
        metadata["initial_work_order_target_artifact"] = str(lifecycle.get("next_unresolved_artifact", "") or target)
        if support_blocked:
            metadata["support_blocker_reason"] = str(support_candidate_map.get("reason", "") or "child_support_request_candidate")
            metadata["support_blocker_target_artifact"] = str(support_candidate_map.get("target_artifact", "") or target)
            metadata["next_unresolved_artifact"] = str(support_candidate_map.get("target_artifact", "") or metadata["next_unresolved_artifact"])
            if str(support_candidate_map.get("target_artifact", "") or ""):
                metadata["continuous_campaign_latest_target_artifact"] = str(
                    support_candidate_map.get("target_artifact", "")
                )
        directive["metadata"] = metadata
        directive["updated_at"] = now
        _write_json(_directive_path(operator_root, directive_id), directive)
    release_task_manager_lease(
        operator_root,
        directive_id=directive_id,
        reason="terminal_child_without_review_return",
        child_run_id=child_id,
    )
    event = {
        "event": "child_lifecycle_assessed",
        **dict(lifecycle),
        "non_reviewable_pass_result": True,
    }
    _append_ledger(operator_root, "child_lifecycle_assessments", event)
    _write_json(_conveyor_root(operator_root) / "child_lifecycle_assessment_latest.json", event)
    return updated_child


def _backfill_terminal_child_lifecycle_assessments(operator_root: str | Path) -> dict[str, Any]:
    inspected = 0
    backfilled = 0
    rows: list[dict[str, Any]] = []
    directives = _load_items(_directives_root(operator_root))
    children = _load_items(_children_root(operator_root))
    active_terminal_child_ids = {
        str(directive.get("active_child_run_id", "") or "").strip()
        for directive in directives
        if str(directive.get("state", "") or "") not in {"accepted", "rejected", "returned_for_review"}
        and str(directive.get("active_child_run_id", "") or "").strip()
    }
    orphaned_stopped_directive_ids = {
        str(directive.get("directive_id", "") or "").strip()
        for directive in directives
        if str(directive.get("directive_id", "") or "").strip()
        and not str(directive.get("active_child_run_id", "") or "").strip()
        and str(directive.get("state", "") or "").strip() in {"blocked", "blocked_for_support"}
        and str(directive.get("blocked_reason", "") or "").strip() == "active_child_stopped"
    }
    orphaned_latest_children: dict[str, dict[str, Any]] = {}
    for child in children:
        directive_id = str(child.get("directive_id", "") or "").strip()
        if directive_id not in orphaned_stopped_directive_ids:
            continue
        if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
            continue
        if str(child.get("state", "") or "") not in TERMINAL_CHILD_STATES:
            continue
        if bool(child.get("non_reviewable_pass_result", False)):
            continue
        failed_reason = str(child.get("failed_reason", "") or "")
        if failed_reason and failed_reason != "active_child_stopped":
            continue
        current = orphaned_latest_children.get(directive_id, {})
        child_time = _parse_utc_time(child.get("updated_at", "") or child.get("created_at", ""))
        current_time = _parse_utc_time(current.get("updated_at", "") or current.get("created_at", ""))
        if not current or (child_time and (not current_time or child_time >= current_time)):
            orphaned_latest_children[directive_id] = dict(child)
    orphaned_terminal_child_ids = {
        str(child.get("child_run_id", "") or "").strip()
        for child in orphaned_latest_children.values()
        if str(child.get("child_run_id", "") or "").strip()
    }
    generic_failed_reasons = {
        "active_child_stopped",
        "missing_container_before_final_return",
        "missing_child_return_packet",
        "missing_container",
        "no_return_packet",
    }
    for child in children:
        child_id = str(child.get("child_run_id", "") or "").strip()
        if not child_id:
            continue
        if child_id not in active_terminal_child_ids and child_id not in orphaned_terminal_child_ids:
            continue
        if bool(child.get("non_reviewable_pass_result", False)):
            continue
        if str(child.get("child_lifecycle_classification", "") or "") in {
            "intentional_stop",
            "productive_pass_completed_not_review_ready",
            "blocked_pass_completed_not_review_ready",
        }:
            continue
        if str(child.get("state", "") or "") not in TERMINAL_CHILD_STATES:
            continue
        failed_reason = str(child.get("failed_reason", "") or "")
        if failed_reason and failed_reason not in generic_failed_reasons:
            continue
        latest_progress = _latest_child_progress(child)
        if not latest_progress:
            if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
                continue
            inspected += 1
            inspect_state = dict(child.get("last_inspect_result", {}) or {})
            if not inspect_state:
                inspect_state = {
                    "state": str(child.get("last_inspect_state", "") or child.get("state", "") or "stopped"),
                    "exit_code": child.get("container_exit_code", -1),
                    "error": str(child.get("failed_reason", "") or "child_runtime_no_first_checkpoint"),
                }
            target = str(
                child.get("latest_work_order_target_artifact", "")
                or child.get("latest_target_artifact", "")
                or ""
            ).strip()
            lifecycle_progress = {
                "schema_name": "ResidentNoFirstCheckpointLifecycleProgress",
                "generated_at": _utc_now(),
                "child_run_id": child_id,
                "directive_id": str(child.get("directive_id", "") or ""),
                "target_artifact": target,
                "progress_state": "blocked",
                "cycle_outcome": "blocked",
                "remaining_failed_gates": ["child_runtime_no_first_checkpoint"],
                "hardware_build_packet_ready_candidate": False,
                "grants_execution_authority": False,
            }
            recovery = {
                "recoverable": True,
                "blockers": [],
                "progress_has_delta": False,
                "workspace_has_artifacts": False,
                "workspace_artifacts": [],
                "artifact_delta_count": 0,
                "materialized_expected_files": [],
                "target_artifact": target,
                "work_order_id": str(child.get("latest_work_order_id", "") or ""),
                "latest_progress_ref": {
                    "child_run_id": child_id,
                    "directive_id": str(child.get("directive_id", "") or ""),
                    "target_artifact": target,
                    "work_order_id": str(child.get("latest_work_order_id", "") or ""),
                    "generated_at": str(lifecycle_progress.get("generated_at", "") or ""),
                },
            }
            lifecycle = _classify_terminal_child_without_return(
                {**child, "stop_requested": False},
                inspect_state=inspect_state,
                latest_progress=lifecycle_progress,
                recovery=recovery,
            )
            if str(lifecycle.get("child_lifecycle_classification", "") or "") != "blocked_pass_completed_not_review_ready":
                continue
            lifecycle["child_runtime_no_first_checkpoint"] = True
            lifecycle["backfilled_productive_lifecycle_assessment"] = True
            lifecycle["backfill_reason"] = "terminal_child_no_first_checkpoint_reclassified"
            updated_child = _record_terminal_child_without_review_return(
                operator_root,
                child=child,
                lifecycle=lifecycle,
                recovery=recovery,
                inspect_state=inspect_state,
            )
            updated_child["child_runtime_no_first_checkpoint"] = True
            updated_child["first_checkpoint_age_seconds"] = float(
                _resident_no_first_checkpoint_assessment(child, inspect_state=inspect_state).get(
                    "first_checkpoint_age_seconds", 0.0
                )
                or 0.0
            )
            if child_id:
                _write_json(_child_path(operator_root, child_id), updated_child)
            directive_id = str(updated_child.get("directive_id", "") or "")
            if directive_id:
                directive = _read_json(_directive_path(operator_root, directive_id))
                if directive:
                    directive["state"] = "blocked"
                    directive["active_child_run_id"] = ""
                    directive["blocked_reason"] = "child_runtime_no_first_checkpoint"
                    metadata = dict(directive.get("metadata", {}) or {})
                    metadata["child_lifecycle_classification"] = "blocked_pass_completed_not_review_ready"
                    metadata["child_runtime_no_first_checkpoint"] = True
                    metadata["next_unresolved_artifact"] = target
                    directive["metadata"] = metadata
                    directive["updated_at"] = _utc_now()
                    _write_json(_directive_path(operator_root, directive_id), directive)
            rows.append(updated_child)
            backfilled += 1
            continue
        inspected += 1
        inspect_state = dict(child.get("last_inspect_result", {}) or {})
        if not inspect_state:
            inspect_state = {
                "state": str(child.get("last_inspect_state", "") or "unknown"),
                "exit_code": child.get("container_exit_code", -1),
                "error": str(child.get("failed_reason", "") or ""),
            }
        recovery = _missing_container_recovery_evidence(child, latest_progress)
        lifecycle = _classify_terminal_child_without_return(
            child,
            inspect_state=inspect_state,
            latest_progress=latest_progress,
            recovery=recovery,
        )
        classification = str(lifecycle.get("child_lifecycle_classification", "") or "")
        if classification not in {
            "productive_pass_completed_not_review_ready",
            "blocked_pass_completed_not_review_ready",
        }:
            continue
        lifecycle["backfilled_productive_lifecycle_assessment"] = True
        lifecycle["backfill_reason"] = "terminal_child_progress_checkpoint_reclassified"
        updated_child = _record_terminal_child_without_review_return(
            operator_root,
            child=child,
            lifecycle=lifecycle,
            recovery=recovery,
            inspect_state=inspect_state,
        )
        rows.append(updated_child)
        backfilled += 1
    return {
        "inspected_terminal_child_count": inspected,
        "productive_pass_backfill_count": sum(
            1
            for row in rows
            if str(row.get("child_lifecycle_classification", "") or "")
            == "productive_pass_completed_not_review_ready"
        ),
        "blocked_pass_backfill_count": sum(
            1
            for row in rows
            if str(row.get("child_lifecycle_classification", "") or "")
            == "blocked_pass_completed_not_review_ready"
        ),
        "terminal_child_lifecycle_backfill_count": backfilled,
        "records": rows,
    }


def repair_child_runtime_no_first_checkpoint_blockers(
    operator_root: str | Path,
    *,
    repaired_at: str | None = None,
    repair_source: str = "child_runtime_repair_acknowledged",
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    now = _utc_now()
    repair_time_text = str(repaired_at or now)
    repair_time = _parse_utc_time(repair_time_text)
    children_by_directive: dict[str, list[dict[str, Any]]] = {}
    for child in _load_items(_children_root(operator_root)):
        directive_id = str(child.get("directive_id", "") or "").strip()
        if directive_id:
            children_by_directive.setdefault(directive_id, []).append(dict(child))

    cleared = 0
    skipped: list[dict[str, Any]] = []
    repaired_directive_ids: list[str] = []
    repaired_child_ids: list[str] = []
    for directive in _load_items(_directives_root(operator_root)):
        directive_id = str(directive.get("directive_id", "") or "").strip()
        if not directive_id:
            continue
        metadata = dict(directive.get("metadata", {}) or {})
        has_blocker = bool(metadata.get("child_runtime_no_first_checkpoint", False)) or (
            str(directive.get("blocked_reason", "") or "").strip() == "child_runtime_no_first_checkpoint"
        )
        if not has_blocker:
            continue
        if str(directive.get("active_child_run_id", "") or "").strip():
            skipped.append(
                {
                    "directive_id": directive_id,
                    "reason": "active_child_present",
                    "grants_execution_authority": False,
                }
            )
            continue
        candidates = [
            child
            for child in list(children_by_directive.get(directive_id, []) or [])
            if bool(child.get("child_runtime_no_first_checkpoint", False))
            or str(child.get("failed_reason", "") or "").strip() == "blocked_pass_completed_not_review_ready"
        ]
        if not candidates:
            skipped.append(
                {
                    "directive_id": directive_id,
                    "reason": "no_no_first_checkpoint_child",
                    "grants_execution_authority": False,
                }
            )
            continue
        latest_child = max(
            candidates,
            key=lambda child: _parse_utc_time(child.get("updated_at", "") or child.get("created_at", ""))
            or datetime.min.replace(tzinfo=timezone.utc),
        )
        child_runtime_time_text = str(
            latest_child.get("spawn_fulfilled_at", "")
            or latest_child.get("started_at", "")
            or latest_child.get("created_at", "")
            or latest_child.get("updated_at", "")
            or ""
        )
        child_runtime_time = _parse_utc_time(child_runtime_time_text)
        if repair_time and child_runtime_time and repair_time <= child_runtime_time:
            skipped.append(
                {
                    "directive_id": directive_id,
                    "child_run_id": str(latest_child.get("child_run_id", "") or ""),
                    "reason": "repair_not_newer_than_child",
                    "repair_applied_at": repair_time_text,
                    "child_runtime_started_at": child_runtime_time_text,
                    "child_updated_at": str(latest_child.get("updated_at", "") or ""),
                    "grants_execution_authority": False,
                }
            )
            continue

        updated_directive = dict(directive)
        updated_metadata = dict(metadata)
        updated_directive["state"] = "requeued"
        updated_directive["blocked_reason"] = ""
        updated_directive["active_child_run_id"] = ""
        updated_metadata["child_runtime_no_first_checkpoint"] = False
        updated_metadata["child_runtime_no_first_checkpoint_repair_applied"] = True
        updated_metadata["child_runtime_no_first_checkpoint_repaired_at"] = repair_time_text
        updated_metadata["child_runtime_no_first_checkpoint_repair_source"] = str(repair_source or "")
        updated_metadata["child_runtime_no_first_checkpoint_repaired_child_run_id"] = str(
            latest_child.get("child_run_id", "") or ""
        )
        updated_metadata["support_admission_state_before_runtime_repair"] = str(
            metadata.get("support_admission_state", "") or ""
        )
        updated_directive["metadata"] = updated_metadata
        updated_directive["updated_at"] = now
        _write_json(_directive_path(operator_root, directive_id), updated_directive)

        child_id = str(latest_child.get("child_run_id", "") or "").strip()
        if child_id:
            updated_child = dict(latest_child)
            updated_child["child_runtime_no_first_checkpoint_repair_state"] = "repaired_after_child_exit"
            updated_child["child_runtime_no_first_checkpoint_repaired_at"] = repair_time_text
            updated_child["child_runtime_no_first_checkpoint_repair_source"] = str(repair_source or "")
            updated_child["updated_at"] = now
            _write_json(_child_path(operator_root, child_id), updated_child)
            repaired_child_ids.append(child_id)

        release_task_manager_lease(
            operator_root,
            directive_id=directive_id,
            reason="child_runtime_no_first_checkpoint_repaired",
            child_run_id=child_id,
        )
        repaired_directive_ids.append(directive_id)
        cleared += 1

    event = {
        "event": "child_runtime_no_first_checkpoint_repair",
        "generated_at": now,
        "repair_applied_at": repair_time_text,
        "repair_source": str(repair_source or ""),
        "child_runtime_repair_cleared_count": cleared,
        "repaired_directive_ids": repaired_directive_ids,
        "repaired_child_run_ids": repaired_child_ids,
        "skipped": skipped,
        "grants_execution_authority": False,
    }
    _append_ledger(operator_root, "child_lifecycle_assessments", event)
    _write_json(_conveyor_root(operator_root) / "child_runtime_repair_latest.json", event)
    try:
        build_task_manager_snapshot(operator_root, persist=True)
    except Exception:
        pass
    return event


def repair_child_runtime_synthesis_stalled_blockers(
    operator_root: str | Path,
    *,
    repaired_at: str | None = None,
    repair_source: str = "child_runtime_synthesis_stalled_repair_acknowledged",
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    now = _utc_now()
    repair_time_text = str(repaired_at or now)
    repair_time = _parse_utc_time(repair_time_text)
    children_by_directive: dict[str, list[dict[str, Any]]] = {}
    for child in _load_items(_children_root(operator_root)):
        directive_id = str(child.get("directive_id", "") or "").strip()
        if directive_id:
            children_by_directive.setdefault(directive_id, []).append(dict(child))

    cleared = 0
    skipped: list[dict[str, Any]] = []
    repaired_directive_ids: list[str] = []
    repaired_child_ids: list[str] = []
    for directive in _load_items(_directives_root(operator_root)):
        directive_id = str(directive.get("directive_id", "") or "").strip()
        if not directive_id:
            continue
        metadata = dict(directive.get("metadata", {}) or {})
        has_blocker = bool(metadata.get("child_runtime_synthesis_stalled", False)) or (
            str(directive.get("blocked_reason", "") or "").strip() == "child_runtime_synthesis_stalled"
        )
        if not has_blocker:
            continue
        if str(directive.get("active_child_run_id", "") or "").strip():
            skipped.append(
                {
                    "directive_id": directive_id,
                    "reason": "active_child_present",
                    "grants_execution_authority": False,
                }
            )
            continue
        candidates = [
            child
            for child in list(children_by_directive.get(directive_id, []) or [])
            if bool(child.get("resident_synthesis_stalled_finalized", False))
            or bool(child.get("child_runtime_synthesis_stalled", False))
            or str(child.get("failed_reason", "") or "").strip() == "blocked_pass_completed_not_review_ready"
        ]
        if not candidates:
            skipped.append(
                {
                    "directive_id": directive_id,
                    "reason": "no_synthesis_stalled_child",
                    "grants_execution_authority": False,
                }
            )
            continue
        latest_child = max(
            candidates,
            key=lambda child: _parse_utc_time(child.get("updated_at", "") or child.get("created_at", ""))
            or datetime.min.replace(tzinfo=timezone.utc),
        )
        child_runtime_time_text = str(
            latest_child.get("spawn_fulfilled_at", "")
            or latest_child.get("started_at", "")
            or latest_child.get("created_at", "")
            or latest_child.get("updated_at", "")
            or ""
        )
        child_runtime_time = _parse_utc_time(child_runtime_time_text)
        if repair_time and child_runtime_time and repair_time <= child_runtime_time:
            skipped.append(
                {
                    "directive_id": directive_id,
                    "child_run_id": str(latest_child.get("child_run_id", "") or ""),
                    "reason": "repair_not_newer_than_child",
                    "repair_applied_at": repair_time_text,
                    "child_runtime_started_at": child_runtime_time_text,
                    "child_updated_at": str(latest_child.get("updated_at", "") or ""),
                    "grants_execution_authority": False,
                }
            )
            continue

        updated_directive = dict(directive)
        updated_metadata = dict(metadata)
        updated_directive["state"] = "requeued"
        updated_directive["blocked_reason"] = ""
        updated_directive["active_child_run_id"] = ""
        updated_metadata["child_runtime_synthesis_stalled"] = False
        updated_metadata["child_runtime_synthesis_stalled_repair_applied"] = True
        updated_metadata["child_runtime_synthesis_stalled_repaired_at"] = repair_time_text
        updated_metadata["child_runtime_synthesis_stalled_repair_source"] = str(repair_source or "")
        updated_metadata["child_runtime_synthesis_stalled_repaired_child_run_id"] = str(
            latest_child.get("child_run_id", "") or ""
        )
        updated_metadata["support_admission_state_before_runtime_repair"] = str(
            metadata.get("support_admission_state", "") or ""
        )
        updated_directive["metadata"] = updated_metadata
        updated_directive["updated_at"] = now
        _write_json(_directive_path(operator_root, directive_id), updated_directive)

        child_id = str(latest_child.get("child_run_id", "") or "").strip()
        if child_id:
            updated_child = dict(latest_child)
            updated_child["child_runtime_synthesis_stalled_repair_state"] = "repaired_after_child_exit"
            updated_child["child_runtime_synthesis_stalled_repaired_at"] = repair_time_text
            updated_child["child_runtime_synthesis_stalled_repair_source"] = str(repair_source or "")
            updated_child["updated_at"] = now
            _write_json(_child_path(operator_root, child_id), updated_child)
            repaired_child_ids.append(child_id)

        release_task_manager_lease(
            operator_root,
            directive_id=directive_id,
            reason="child_runtime_synthesis_stalled_repaired",
            child_run_id=child_id,
        )
        repaired_directive_ids.append(directive_id)
        cleared += 1

    event = {
        "event": "child_runtime_synthesis_stalled_repair",
        "generated_at": now,
        "repair_applied_at": repair_time_text,
        "repair_source": str(repair_source or ""),
        "child_runtime_repair_cleared_count": cleared,
        "repaired_directive_ids": repaired_directive_ids,
        "repaired_child_run_ids": repaired_child_ids,
        "skipped": skipped,
        "grants_execution_authority": False,
    }
    _append_ledger(operator_root, "child_lifecycle_assessments", event)
    _write_json(_conveyor_root(operator_root) / "child_runtime_repair_latest.json", event)
    try:
        build_task_manager_snapshot(operator_root, persist=True)
    except Exception:
        pass
    return event


def _recover_quiescent_resident_return_from_campaign_draft(
    operator_root: str | Path,
    child: Mapping[str, Any],
) -> dict[str, Any] | None:
    if str(child.get("child_execution_mode", "") or "") != "resident_campaign":
        return None
    latest_progress = _latest_child_progress(child)
    review_ready_checkpoint = bool(
        latest_progress
        and bool(latest_progress.get("hardware_build_packet_ready_candidate", False))
        and not list(latest_progress.get("remaining_failed_gates", []) or [])
        and not str(latest_progress.get("blocked_reason", "") or "").strip()
        and not list(latest_progress.get("resident_self_final_return_blockers", []) or [])
        and str(latest_progress.get("progress_state", "") or "") not in {"blocked", "needs_support", "needs_operator"}
    )
    if not (
        bool(child.get("productive_quiescence_eligible", False))
        or bool(child.get("return_requested_after_clean_delta", False))
        or _child_requested_final_return(child)
        or review_ready_checkpoint
    ):
        return None
    directive_id = str(child.get("directive_id", "") or "").strip()
    child_id = str(child.get("child_run_id", "") or "").strip()
    if not directive_id or not child_id:
        return None
    directive = _read_json(_directive_path(operator_root, directive_id))
    if not directive:
        return None
    candidate_packet = {
        "review_state": "pending_operator_review",
        "directive_id": directive_id,
        "child_run_id": child_id,
        "artifacts": [],
        "verification_evidence": [],
    }
    hydrated, attached = _attach_latest_campaign_draft_artifacts(operator_root, candidate_packet)
    if not attached:
        return None
    hardware = _assess_hardware_build_packet(
        operator_root,
        directive_id,
        directive=directive,
        active_child=child,
        packet=hydrated,
        require_return_packet=False,
    )
    if bool(hardware.get("required", False)) and not bool(hardware.get("hardware_build_packet_ready", False)):
        return None
    packet = record_child_return_packet(
        operator_root,
        child_run_id=child_id,
        outcome_summary=(
            "Resident child reached a review-ready campaign draft checkpoint; "
            "Novali recovered the final return packet from campaign draft artifacts."
        ),
        artifacts=[str(item) for item in list(hydrated.get("artifacts", []) or [])],
        verification_evidence=[
            "resident_productive_quiescence_recovered",
            "conveyor_child_campaign_draft_artifacts_attached",
            "hardware_build_packet_ready_candidate",
        ],
        risks=[],
        requested_follow_up="operator_review_build_grade_documentation",
        result_state="completed",
        extra_fields={
            "recovered_from_productive_quiescence": True,
            "recovered_from_review_ready_checkpoint": review_ready_checkpoint,
            "return_packet_recovered_by_parent": True,
            "recovery_artifact_source": "campaign_draft_latest",
            "recovery_hardware_build_packet_assessment": dict(hardware),
            "recovery_latest_progress_ref": {
                "child_run_id": str(latest_progress.get("child_run_id", "") or child_id),
                "directive_id": str(latest_progress.get("directive_id", "") or directive_id),
                "cycle_index": latest_progress.get("cycle_index", ""),
                "generated_at": str(latest_progress.get("generated_at", "") or ""),
                "target_artifact": str(latest_progress.get("target_artifact", "") or ""),
            },
            "grants_execution_authority": False,
        },
    )
    recovered, recovered_attached = _attach_latest_campaign_draft_artifacts(operator_root, packet)
    if recovered_attached:
        recovered["recovered_from_productive_quiescence"] = True
        recovered["recovered_from_review_ready_checkpoint"] = review_ready_checkpoint
        recovered["return_packet_recovered_by_parent"] = True
        recovered["recovery_artifact_source"] = "campaign_draft_latest"
        recovered["recovery_hardware_build_packet_assessment"] = dict(hardware)
        recovered["recovery_latest_progress_ref"] = {
            "child_run_id": str(latest_progress.get("child_run_id", "") or child_id),
            "directive_id": str(latest_progress.get("directive_id", "") or directive_id),
            "cycle_index": latest_progress.get("cycle_index", ""),
            "generated_at": str(latest_progress.get("generated_at", "") or ""),
            "target_artifact": str(latest_progress.get("target_artifact", "") or ""),
        }
        recovered["grants_execution_authority"] = False
        recovered["updated_at"] = _utc_now()
        _write_json(_return_path(operator_root, str(packet.get("return_packet_id", "") or "")), recovered)
        packet = recovered
    return packet


def _resident_quality_retarget(
    operator_root: str | Path,
    *,
    directive_id: str,
    active_child: Mapping[str, Any],
    previous_target: str,
    stale_weakest_failed_artifact: str = "",
    refreshed_campaign_state: Mapping[str, Any] | None = None,
    prefer_previous_failed_target: bool = False,
) -> str:
    directive = _load_directive(operator_root, directive_id)
    campaign_state = dict(refreshed_campaign_state or {})
    if not campaign_state:
        campaign_state = _write_campaign_manifest(
            operator_root,
            directive_id,
            active_child=active_child,
        )
    clean_artifacts = set(_clean_quality_artifacts(campaign_state))
    previous = str(previous_target or "").strip()
    failed_artifacts = [str(item) for item in list(campaign_state.get("quality_failed_artifacts", []) or [])]
    artifact_gate_candidates = _artifact_level_failed_gate_candidates(
        directive,
        campaign_state,
        exclude=[] if prefer_previous_failed_target else [previous] if previous else [],
    )
    if artifact_gate_candidates:
        first = str(artifact_gate_candidates[0].get("artifact_name", "") or "")
        if first:
            return first
    if (
        prefer_previous_failed_target
        and previous
        and previous in failed_artifacts
        and previous not in clean_artifacts
    ):
        return previous
    quality_failed = [
        str(item)
        for item in failed_artifacts
        if str(item) in BUILD_GRADE_ARTIFACT_ROTATION_ORDER
        and str(item) != previous
        and str(item) not in clean_artifacts
    ]
    if quality_failed:
        return quality_failed[0]
    selected = _select_next_campaign_target_artifact(
        directive,
        previous_target=previous_target,
        campaign_state=campaign_state,
    )
    if selected:
        return selected
    fallback = str(stale_weakest_failed_artifact or "").strip()
    if fallback:
        if fallback not in clean_artifacts:
            return fallback
    return str(previous_target or "").strip()


def _resident_followup_delta_complete(
    *,
    campaign_state: Mapping[str, Any],
    draft_delta_quality: Mapping[str, Any],
    prior_draft_delta_quality: Mapping[str, Any] | None = None,
    latest_progress: Mapping[str, Any] | None = None,
) -> tuple[bool, str]:
    prior = dict(prior_draft_delta_quality or {})
    draft = dict(draft_delta_quality or {})
    progress = dict(latest_progress or {})
    prior_satisfied = bool(prior.get("operator_followup_delta_satisfied", False))
    followup_satisfied = bool(draft.get("operator_followup_delta_satisfied", False)) or prior_satisfied
    gate_source = prior if prior_satisfied else draft
    failed_gates = [
        str(item)
        for item in list(gate_source.get("failed_gates", []) or [])
        if str(item).strip()
    ]
    if not followup_satisfied:
        return False, ""
    if failed_gates:
        return False, ""
    progress_target = str(progress.get("target_artifact", "") or "").strip()
    draft_target = str(draft.get("target_artifact", "") or gate_source.get("target_artifact", "") or "").strip()
    if progress_target and draft_target and progress_target != draft_target:
        return False, ""
    target_artifacts = {item for item in (progress_target, draft_target) if item}
    artifact_deltas = [
        delta
        for delta in list(progress.get("artifact_deltas", []) or [])
        if isinstance(delta, Mapping)
    ]
    fresh_target_delta = bool(
        progress.get("draft_changed_this_cycle", False)
        or progress.get("target_draft_changed_this_cycle", False)
        or progress.get("target_artifact_delta_observed", False)
        or progress.get("target_delta_observed", False)
        or progress.get("target_draft_delta_observed", False)
    )
    if not fresh_target_delta:
        for delta in artifact_deltas:
            artifact_name = str(
                delta.get("artifact_name", "")
                or delta.get("target_artifact", "")
                or delta.get("artifact", "")
                or ""
            ).strip()
            if target_artifacts and artifact_name and artifact_name not in target_artifacts:
                continue
            if str(delta.get("delta_kind", "") or "") not in {"created", "revised"}:
                continue
            before_hash = str(
                delta.get("before_hash", "")
                or delta.get("previous_hash", "")
                or delta.get("canonical_before_hash", "")
                or ""
            )
            after_hash = str(
                delta.get("after_hash", "")
                or delta.get("new_hash", "")
                or delta.get("draft_after_hash", "")
                or ""
            )
            if before_hash and after_hash and before_hash == after_hash:
                continue
            fresh_target_delta = True
            break
    if not fresh_target_delta:
        return False, ""
    progress_unresolved = [
        str(item).strip()
        for key in ("remaining_failed_gates", "unchanged_failed_gates", "self_final_blockers")
        for item in list(progress.get(key, []) or [])
        if str(item).strip()
    ]
    if progress_unresolved:
        return False, ""
    if str(campaign_state.get("readiness_state", "") or "") == "artifact_complete_quality_shallow":
        return False, ""
    remaining_quality_gates = [
        str(item)
        for item in list(campaign_state.get("failed_quality_gates", []) or [])
        if str(item).strip()
    ]
    remaining_quality_artifacts = [
        str(item)
        for item in list(campaign_state.get("quality_failed_artifacts", []) or [])
        if str(item).strip()
    ]
    if remaining_quality_gates or remaining_quality_artifacts:
        return False, ""
    if float(campaign_state.get("artifact_presence_score", 1.0) or 0.0) >= 1.0 and float(
        campaign_state.get("quality_depth_score", 1.0) or 0.0
    ) < 0.75:
        return False, ""
    if [
        str(item).strip()
        for item in list(progress.get("missing_required_return_artifacts_after_write", []) or [])
        if str(item).strip()
    ]:
        return False, ""
    if str(progress.get("blocked_reason", "") or "") in {
        "docker_mount_fault",
        "operator_clarification_required",
        "support_required",
        "safety_review_required",
    }:
        return False, ""
    return True, "operator_followup_delta_satisfied"


def _request_resident_final_return_after_clean_delta(
    operator_root: str | Path,
    *,
    child: Mapping[str, Any],
    reason: str,
) -> dict[str, Any]:
    inbox_path = _child_inbox_path(child)
    inbox_payload = _read_json(inbox_path)
    if not inbox_payload:
        inbox_payload = {
            "schema_name": "ConveyorChildInbox",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "generated_at": _utc_now(),
            "child_run_id": str(child.get("child_run_id", "") or ""),
            "directive_id": str(child.get("directive_id", "") or ""),
            "messages": [],
        }
    now = _utc_now()
    inbox_payload["request_final_return"] = True
    inbox_payload["return_requested_after_clean_delta"] = True
    inbox_payload["final_return_reason"] = str(reason or "operator_followup_delta_satisfied")
    inbox_payload["stop_requested"] = False
    inbox_payload["updated_at"] = now
    inbox_payload = _compact_resident_inbox_work_orders(inbox_payload)
    _write_json(inbox_path, inbox_payload)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "resident_followup_delta_satisfied_return_requested",
            "generated_at": now,
            "child_run_id": str(child.get("child_run_id", "") or ""),
            "directive_id": str(child.get("directive_id", "") or ""),
            "productive_quiescence_eligible": True,
            "return_requested_after_clean_delta": True,
            "followup_completion_reason": str(reason or "operator_followup_delta_satisfied"),
        },
    )
    return inbox_payload


def _sensor_array_split_feedback(directive: Mapping[str, Any], target_artifact: str, depth_missing_fields: Iterable[Mapping[str, Any]]) -> str:
    text = str(directive.get("directive_text", "") or "").lower()
    rows = " ".join(str(dict(item).get("row_id", "") or "") for item in depth_missing_fields if isinstance(item, Mapping)).lower()
    if "magnetic forge" not in text or target_artifact != "bill_of_materials.json" or "sensor_array" not in rows:
        return ""
    return (
        "For Magnetic Forge, split sensor_array into concrete source-backed rows for thermal_sensor_interface, "
        "current_sensor_interface, magnetic_field_sensor_or_gaussmeter, coolant_flow_or_temperature_sensor, "
        "and daq_logger_or_microcontroller_interface. Each replacement row needs manufacturer, MPN, "
        "datasheet/source URL, ratings, cost basis, connector/protocol/signal or measurement details, fixture links, "
        "risk links, and go/no-go trace evidence; if no source-backed part is available, mark that row unresolved "
        "instead of returning as build-ready."
    )


def _post_support_plateau_gate_signature(
    *,
    latest_progress: Mapping[str, Any],
    draft_delta_quality: Mapping[str, Any],
    campaign_state: Mapping[str, Any],
    target_artifact: str,
) -> str:
    gates: set[str] = set()
    for key in (
        "remaining_failed_gates",
        "unchanged_failed_gates",
        "self_final_blockers",
    ):
        gates.update(
            str(item).strip()
            for item in list(latest_progress.get(key, []) or [])
            if str(item).strip()
        )
    gates.update(
        str(item).strip()
        for item in list(draft_delta_quality.get("failed_gates", []) or [])
        if str(item).strip() and str(item).strip() != "draft_delta_plateau"
    )
    for field in list(latest_progress.get("support_uncovered_missing_fields", []) or []):
        text = str(field or "").strip()
        if text:
            gates.add(f"support_field:{text}")
    hardware_assessment = dict(campaign_state.get("hardware_build_packet_assessment", {}) or {})
    for gap in _hardware_depth_missing_fields(hardware_assessment, target_artifact=target_artifact):
        if not isinstance(gap, Mapping):
            continue
        row_id = str(gap.get("row_id", "") or "").strip()
        for field in list(gap.get("missing_fields", []) or []):
            field_text = str(field or "").strip()
            if field_text:
                gates.add(f"{row_id}:{field_text}" if row_id else field_text)
    if not gates:
        return "no_failed_gate_signature"
    return "|".join(sorted(gates))


def _update_post_support_plateau_gate_signature(
    updated: dict[str, Any],
    *,
    latest_progress: Mapping[str, Any],
    draft_delta_quality: Mapping[str, Any],
    campaign_state: Mapping[str, Any],
    target_artifact: str,
    post_support_no_delta: int,
) -> int:
    signature = _post_support_plateau_gate_signature(
        latest_progress=latest_progress,
        draft_delta_quality=draft_delta_quality,
        campaign_state=campaign_state,
        target_artifact=target_artifact,
    )
    previous_signature = str(updated.get("plateau_failed_gate_signature", "") or "")
    try:
        previous_count = int(updated.get("plateau_gate_signature_unchanged_count", 0) or 0)
    except (TypeError, ValueError):
        previous_count = 0
    if previous_signature and previous_signature == signature:
        count = max(1, previous_count) + 1
    elif previous_signature:
        count = 1
    else:
        count = max(1, int(post_support_no_delta or 0))
    updated["plateau_failed_gate_signature"] = signature
    updated["plateau_gate_signature_unchanged_count"] = count
    return count


def _plateau_hard_stop_idempotency_key(
    child_payload: Mapping[str, Any],
    *,
    depth_obligation_id: str,
    target_artifact: str,
) -> str:
    return _record_id(
        "plateau-hard-stop",
        str(child_payload.get("child_run_id", "") or ""),
        str(depth_obligation_id or ""),
        str(target_artifact or ""),
    )


def _find_existing_plateau_hard_stop_return(
    operator_root: str | Path,
    *,
    child_run_id: str,
    idempotency_key: str,
) -> dict[str, Any]:
    matches: list[dict[str, Any]] = []
    for packet in _load_items(_returns_root(operator_root)):
        if str(packet.get("child_run_id", "") or "") != str(child_run_id or ""):
            continue
        if str(packet.get("plateau_hard_stop_idempotency_key", "") or "") != str(idempotency_key or ""):
            continue
        matches.append(dict(packet))
    if not matches:
        return {}
    matches.sort(
        key=lambda packet: _record_sort_key(
            packet,
            path_field="return_packet_path",
            id_field="return_packet_id",
        )
    )
    keeper = dict(matches[-1])
    keeper_id = str(keeper.get("return_packet_id", "") or "")
    now = _utc_now()
    for packet in matches[:-1]:
        packet_id = str(packet.get("return_packet_id", "") or "")
        if not packet_id:
            continue
        packet["review_state"] = "requeued"
        packet["reviewed_at"] = str(packet.get("reviewed_at", "") or now)
        packet["updated_at"] = now
        packet["superseded_by_return_packet_id"] = keeper_id
        packet["superseded_reason"] = "duplicate_plateau_hard_stop_replaced"
        _write_json(_return_path(operator_root, packet_id), packet)
    if keeper_id:
        keeper["return_packet_path"] = str(_return_path(operator_root, keeper_id))
    keeper["plateau_hard_stop_deduplicated"] = True
    keeper["updated_at"] = now
    if keeper_id:
        _write_json(_return_path(operator_root, keeper_id), keeper)
    return keeper


def _hard_stop_resident_plateau_after_support(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    updated: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    runner: ConveyorChildRunner,
    target_artifact: str,
    campaign_for_completion: Mapping[str, Any],
    latest_work_order: Mapping[str, Any],
    post_support_no_delta: int,
) -> tuple[dict[str, Any], dict[str, Any]]:
    child_payload = dict(updated)
    try:
        runner.stop_child_container(child_payload)
    except Exception:
        pass
    latest_depth_obligation_id = str(
        child_payload.get("depth_obligation_id", "")
        or latest_work_order.get("depth_obligation_id", "")
        or ""
    )
    depth_missing_fields = [
        dict(item)
        for item in list(
            child_payload.get("depth_missing_fields", [])
            or latest_work_order.get("depth_missing_fields", [])
            or _hardware_depth_missing_fields(
                dict(campaign_for_completion.get("hardware_build_packet_assessment", {}) or {}),
                target_artifact=target_artifact,
            )
        )
        if isinstance(item, Mapping)
    ]
    row_feedback = _prototype_fixture_row_level_feedback(
        dict(campaign_for_completion.get("hardware_build_packet_assessment", {}) or {})
    )
    directive_id = str(child_payload.get("directive_id", "") or "")
    directive = _load_directive(operator_root, directive_id) if directive_id else {}
    focused_feedback = " ".join(
        item
        for item in [
            (
                f"Resident child plateaued after the {latest_depth_obligation_id} depth obligation."
                if latest_depth_obligation_id
                else "Resident child plateaued after kernel depth support."
            ),
            f"Requeue and continue on {target_artifact}; a concrete target artifact delta is required before returning.",
            (
                f"Missing row-level fields: {json.dumps(depth_missing_fields, sort_keys=True)}."
                if depth_missing_fields
                else ""
            ),
            row_feedback,
            _sensor_array_split_feedback(directive, target_artifact, depth_missing_fields),
            "Use checked-out Librarian/support refs first; request directive_build_grade_synthesis_pack only for concrete uncovered gaps.",
            "No child or return packet grants execution authority.",
        ]
        if item
    )
    plateau_idempotency_key = _plateau_hard_stop_idempotency_key(
        child_payload,
        depth_obligation_id=latest_depth_obligation_id,
        target_artifact=target_artifact,
    )
    packet = _find_existing_plateau_hard_stop_return(
        operator_root,
        child_run_id=str(child_payload.get("child_run_id", "") or ""),
        idempotency_key=plateau_idempotency_key,
    )
    if packet:
        packet["target_artifact"] = target_artifact
        packet["support_backed_no_delta_cycles"] = max(
            int(packet.get("support_backed_no_delta_cycles", 0) or 0),
            int(post_support_no_delta),
        )
        packet["plateau_hard_stop_reused_existing_packet"] = True
        _write_json(_return_path(operator_root, str(packet.get("return_packet_id", "") or "")), packet)
    else:
        packet = record_child_return_packet(
            operator_root,
            child_run_id=str(child_payload.get("child_run_id", "") or ""),
            outcome_summary="Resident directive worker stalled after kernel support without producing artifact deltas.",
            artifacts=[],
            verification_evidence=[
                "resident_progress_checkpoint_inspected",
                "kernel_work_order_previously_injected",
            ],
            risks=["resident_worker_stalled"],
            requested_follow_up="operator_clarification_or_requeue",
            result_state="failed",
            extra_fields={
                "plateau_requeue_reason": "second_no_delta_window_after_depth_support",
                "plateau_hard_stop_applied": True,
                "plateau_hard_stop_idempotency_key": plateau_idempotency_key,
                "target_artifact": target_artifact,
                "support_backed_no_delta_cycles": int(post_support_no_delta),
                "plateau_gate_signature": str(child_payload.get("plateau_failed_gate_signature", "") or ""),
                "plateau_gate_signature_unchanged_count": int(
                    child_payload.get("plateau_gate_signature_unchanged_count", 0) or 0
                ),
                "depth_obligation_result": {
                    "depth_obligation_id": latest_depth_obligation_id,
                    "target_artifact": target_artifact,
                    "target_delta_required": True,
                    "target_delta_observed": False,
                    "depth_missing_fields": depth_missing_fields,
                    "post_support_no_delta_cycles": int(post_support_no_delta),
                    "requeue_recommended": True,
                },
                "suppressed_duplicate_blank_return_count": 0,
            },
            requested_operator_clarifications=[
                {
                    "question": (
                        f"What additional direction, source boundary, or prototype depth should the child use for {target_artifact}?"
                    ),
                    "blocked_gate": "resident_artifact_delta_after_support",
                    "target_artifact": target_artifact,
                }
            ],
        )
    try:
        _decide_return(
            operator_root,
            return_packet_id=str(packet.get("return_packet_id", "") or ""),
            decision_state="requeued",
            operator_note="resident_plateau_depth_recovery",
            feedback=focused_feedback,
        )
        _set_continuous_campaign_metadata(
            operator_root,
            _read_json(_directive_path(operator_root, directive_id)) or {},
            state="auto_requeued",
            action="resident_plateau_depth_recovery",
            reason="second_no_delta_window_after_depth_support",
            return_packet_id=str(packet.get("return_packet_id", "") or ""),
            no_progress_count=0,
            target_artifact=target_artifact,
            feedback=focused_feedback,
        )
        packet = _read_json(_return_path(operator_root, str(packet.get("return_packet_id", "") or ""))) or packet
    except ConveyorValidationError:
        pass
    child_payload["state"] = "failed"
    child_payload["resident_worker_state"] = "plateau_requeued"
    child_payload["active_child_run_id"] = ""
    child_payload["plateau_requeue_reason"] = "second_no_delta_window_after_depth_support"
    child_payload["plateau_hard_stop_applied"] = True
    child_payload["plateau_hard_stop_idempotency_key"] = str(
        packet.get("plateau_hard_stop_idempotency_key", "")
    )
    child_payload["support_backed_no_delta_cycles"] = int(post_support_no_delta)
    child_payload["depth_obligation_result"] = dict(packet.get("depth_obligation_result", {}) or {})
    child_payload["return_packet_id"] = str(packet.get("return_packet_id", "") or "")
    child_payload["updated_at"] = _utc_now()
    child_id_for_update = str(child_payload.get("child_run_id", "") or "")
    if child_id_for_update:
        _write_json(_child_path(operator_root, child_id_for_update), child_payload)
    try:
        build_task_manager_snapshot(operator_root, persist=True)
    except Exception:
        pass
    return child_payload, packet


def _update_resident_child_progress_state(
    operator_root: str | Path,
    *,
    state_root: str | Path | None,
    child: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    runner: ConveyorChildRunner,
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    updated = dict(child)
    updated["latest_progress"] = dict(latest_progress)
    updated["progress_state"] = str(latest_progress.get("progress_state", "") or "")
    updated["latest_progress_at"] = str(latest_progress.get("generated_at", "") or "")
    heartbeat = _resident_progress_heartbeat(updated, latest_progress)
    updated["last_progress_at"] = str(heartbeat.get("last_progress_at", "") or updated["latest_progress_at"])
    updated["last_heartbeat_at"] = str(heartbeat.get("last_heartbeat_at", "") or updated["last_progress_at"])
    updated["last_progress_checkpoint_hash"] = str(heartbeat.get("last_progress_checkpoint_hash", "") or "")
    updated["progress_checkpoint_age_seconds"] = float(heartbeat.get("progress_checkpoint_age_seconds", 0.0) or 0.0)
    updated["progress_heartbeat_source"] = str(heartbeat.get("progress_heartbeat_source", "") or "")
    updated.update(_child_compute_status_fields(updated, latest_progress))
    try:
        cycle_index = max(0, int(latest_progress.get("cycle_index", 0) or 0))
    except (TypeError, ValueError):
        cycle_index = 0
    try:
        previous_cycle_index = max(0, int(updated.get("latest_processed_progress_cycle_index", 0) or 0))
    except (TypeError, ValueError):
        previous_cycle_index = 0
    already_processed_cycle = bool(cycle_index > 0 and previous_cycle_index >= cycle_index)
    new_no_delta_cycles = max(0, cycle_index - previous_cycle_index)
    meaningful_delta = _resident_progress_has_meaningful_delta(latest_progress)
    target_artifact = _resident_target_artifact_from_progress(latest_progress)
    updated["latest_target_artifact"] = target_artifact
    updated["latest_artifact_delta_count"] = len(list(latest_progress.get("artifact_deltas", []) or []))
    updated["latest_processed_progress_cycle_index"] = max(previous_cycle_index, cycle_index)
    updated["support_injection_count"] = int(updated.get("support_injection_count", 0) or 0)
    updated["quality_no_progress_count"] = int(updated.get("quality_no_progress_count", 0) or 0)
    try:
        support_rows_read = int(latest_progress.get("support_pack_rows_read", 0) or 0)
    except (TypeError, ValueError):
        support_rows_read = 0
    support_adequacy_state = str(latest_progress.get("support_adequacy_state", "") or "").strip()
    checkout_support_backed = bool(
        support_rows_read > 0
        and support_adequacy_state not in {
            "insufficient_field_coverage",
            "missing_support_rows",
            "wrong_target",
            "non_consumable",
        }
    )
    if checkout_support_backed:
        updated["checkout_support_rows_consumed"] = support_rows_read
        updated["checkout_support_adequacy_state"] = support_adequacy_state or "rows_available"
        if not updated.get("first_checkout_support_cycle_index"):
            updated["first_checkout_support_cycle_index"] = previous_cycle_index or cycle_index
    wake_ack = _resident_wake_ack_from_progress(latest_progress)
    if wake_ack:
        previous_ack = dict(updated.get("latest_wake_ack", {}) or {})
        updated["latest_wake_ack"] = wake_ack
        updated["wake_latency_seconds"] = float(wake_ack.get("wake_latency_seconds", 0.0) or 0.0)
        if int(previous_ack.get("wake_sequence", 0) or 0) != int(wake_ack.get("wake_sequence", 0) or 0):
            _append_ledger(
                operator_root,
                "child_events",
                {
                    "event": "resident_child_wake_acknowledged",
                    "generated_at": str(wake_ack.get("wake_acknowledged_at", "") or _utc_now()),
                    "child_run_id": str(updated.get("child_run_id", "") or ""),
                    "directive_id": str(updated.get("directive_id", "") or ""),
                    "work_order_id": str(wake_ack.get("wake_work_order_id", "") or ""),
                    "wake_reason": str(wake_ack.get("wake_reason", "") or ""),
                    "wake_sequence": int(wake_ack.get("wake_sequence", 0) or 0),
                    "wake_latency_seconds": float(wake_ack.get("wake_latency_seconds", 0.0) or 0.0),
                },
            )
    updated.update(_resident_wake_state(updated))
    if already_processed_cycle:
        return updated, None
    prior_draft_delta_quality = dict(updated.get("draft_delta_quality", {}) or {})
    draft_delta_quality = _assess_conveyor_campaign_draft_delta_quality(
        operator_root,
        str(updated.get("directive_id", "") or ""),
        active_child=updated,
        target_artifact=target_artifact,
    )
    latest_draft_hash = str(draft_delta_quality.get("draft_hash", "") or "")
    hash_by_artifact = dict(updated.get("last_draft_delta_hash_by_artifact", {}) or {})
    plateau_counts = dict(updated.get("draft_plateau_counts_by_artifact", {}) or {})
    if target_artifact and latest_draft_hash:
        hash_by_artifact[target_artifact] = latest_draft_hash
        plateau_counts[target_artifact] = int(draft_delta_quality.get("draft_plateau_count", 0) or 0)
        updated["last_draft_delta_hash_by_artifact"] = hash_by_artifact
        updated["draft_plateau_counts_by_artifact"] = plateau_counts
        failed_by_artifact = dict(updated.get("last_draft_delta_failed_gates_by_artifact", {}) or {})
        failed_by_artifact[target_artifact] = list(draft_delta_quality.get("failed_gates", []) or [])
        updated["last_draft_delta_failed_gates_by_artifact"] = failed_by_artifact
    updated["draft_delta_quality"] = draft_delta_quality
    updated["draft_plateau_count"] = int(draft_delta_quality.get("draft_plateau_count", 0) or 0)
    updated["latest_draft_delta_gate_failures"] = list(draft_delta_quality.get("failed_gates", []) or [])
    updated["latest_gate_closure_summary"] = {
        "target_artifact": target_artifact,
        "gate_closure_since_last_cycle": bool(draft_delta_quality.get("gate_closure_since_last_cycle", False)),
        "closed_failed_gates": list(draft_delta_quality.get("closed_failed_gates", []) or []),
        "unchanged_failed_gates": list(draft_delta_quality.get("unchanged_failed_gates", []) or []),
        "plateau_recovery_attempt_count": int(draft_delta_quality.get("plateau_recovery_attempt_count", 0) or 0),
    }
    latest_work_order = dict(updated.get("latest_work_order", {}) or {})
    required_gate_closures = [
        str(item)
        for item in list(latest_work_order.get("required_gate_closures", []) or [])
        if str(item).strip()
    ]
    progress_closed_gates = [
        str(item)
        for item in list(latest_progress.get("closed_failed_gates", []) or [])
        if str(item).strip()
    ]
    progress_remaining_gates = [
        str(item)
        for item in list(latest_progress.get("remaining_failed_gates", []) or latest_progress.get("unchanged_failed_gates", []) or [])
        if str(item).strip()
    ]
    target_correct = bool(
        required_gate_closures
        and set(required_gate_closures).issubset(set(progress_closed_gates))
        and not progress_remaining_gates
    )
    updated["target_correct_gate_closure"] = {
        "target_artifact": target_artifact,
        "required_gate_closures": required_gate_closures,
        "closed_failed_gates": progress_closed_gates,
        "remaining_failed_gates": progress_remaining_gates,
        "target_correct": target_correct,
        "kernel_consumed_gate_closure": False,
        "next_action_after_closure": "",
    }
    updated["field_level_contract_applied"] = bool(latest_progress.get("field_level_contract_applied", False))
    directive_id_for_completion = str(updated.get("directive_id", "") or "")
    campaign_for_completion: dict[str, Any] = {}
    if directive_id_for_completion:
        campaign_for_completion = _write_campaign_manifest(
            operator_root,
            directive_id_for_completion,
            active_child=updated,
        )
    no_delta_support_threshold = _resident_no_delta_support_threshold(
        _load_directive(operator_root, directive_id_for_completion),
        latest_progress,
        campaign_for_completion,
    )
    updated = _persist_active_schema_contract(
        updated,
        manifest=campaign_for_completion,
        target_artifact=target_artifact,
        draft_delta_quality=draft_delta_quality,
        latest_work_order=latest_work_order,
    )
    latest_work_order = dict(updated.get("latest_work_order", {}) or latest_work_order)
    consumed_receipts = _append_later_consumed_growth_receipt_events(
        operator_root,
        child=updated,
        latest_progress=latest_progress,
        draft_delta_quality=draft_delta_quality,
    )
    if consumed_receipts:
        updated["latest_growth_receipt_id"] = str(consumed_receipts[-1].get("receipt_id", "") or "")
        updated["latest_growth_receipt_state"] = str(consumed_receipts[-1].get("receipt_state", "") or "")
    later_consumption_receipt = _append_depth_obligation_later_consumption_if_strict_capable(
        operator_root,
        child=updated,
        latest_progress=latest_progress,
    )
    if later_consumption_receipt:
        updated["latest_later_consumption_receipt_id"] = str(
            later_consumption_receipt.get("receipt_id", "") or ""
        )
    schema_support_protection = _schema_followup_generic_support_protection(
        updated,
        draft_delta_quality=draft_delta_quality,
        prior_draft_delta_quality=prior_draft_delta_quality,
        manifest=campaign_for_completion,
        target_artifact=target_artifact,
    )
    if meaningful_delta and campaign_for_completion:
        schema_followup = _schema_resonance_followup_record(
            updated,
            campaign_for_completion,
            latest_progress,
        )
        draft_schema_followup_failed_gates = set(
            str(item)
            for item in list(draft_delta_quality.get("failed_gates", []) or prior_draft_delta_quality.get("failed_gates", []) or [])
            if str(item).strip()
        )
        draft_schema_followup_required = bool(
            draft_delta_quality.get("schema_followup_required", False)
            or prior_draft_delta_quality.get("schema_followup_required", False)
            or "schema_resonance_followup_top_level_fields_missing" in draft_schema_followup_failed_gates
        )
        draft_schema_followup_contract_satisfied = bool(
            draft_delta_quality.get(
                "schema_followup_contract_satisfied",
                prior_draft_delta_quality.get("schema_followup_contract_satisfied", True),
            )
        )
        schema_followup_missing_draft_contract = bool(
            updated.get("schema_resonance_followup_required", False)
            and draft_schema_followup_required
            and not draft_schema_followup_contract_satisfied
        )
        if bool(schema_followup.get("schema_resonance_followup_required", False)) and not _latest_work_order_has_schema_followup(
            updated,
            str(schema_followup.get("target_artifact", "") or ""),
            list(schema_followup.get("missing_top_level_fields", []) or []),
        ) and not schema_followup_missing_draft_contract:
            updated, work_order = _inject_schema_resonance_followup_work_order(
                operator_root,
                state_root=state_root,
                child=updated,
                latest_progress=latest_progress,
                followup=schema_followup,
            )
            _append_ledger(
                operator_root,
                "child_events",
                {
                    "event": "schema_resonance_followup_injected",
                    "generated_at": _utc_now(),
                    "child_run_id": str(updated.get("child_run_id", "") or ""),
                    "directive_id": str(updated.get("directive_id", "") or ""),
                    "target_artifact": str(schema_followup.get("target_artifact", "") or ""),
                    "work_order_id": str(work_order.get("work_order_id", "") or ""),
                    "schema_resonance_score": float(schema_followup.get("schema_resonance_score", 0.0) or 0.0),
                    "missing_top_level_fields": list(schema_followup.get("missing_top_level_fields", []) or []),
                },
            )
            updated["consecutive_no_delta_cycles"] = 0
            updated["quality_no_progress_count"] = 0
            return updated, None
    schema_followup_active = bool(
        latest_work_order.get("schema_resonance_followup_required", False)
        or updated.get("schema_resonance_followup_required", False)
        or draft_delta_quality.get("schema_followup_required", False)
        or prior_draft_delta_quality.get("schema_followup_required", False)
        or "schema_resonance_followup_top_level_fields_missing"
        in set(
            str(item)
            for item in list(draft_delta_quality.get("failed_gates", []) or prior_draft_delta_quality.get("failed_gates", []) or [])
            if str(item).strip()
        )
    )
    schema_followup_contract_satisfied = bool(
        draft_delta_quality.get(
            "schema_followup_contract_satisfied",
            prior_draft_delta_quality.get("schema_followup_contract_satisfied", True),
        )
    )
    if meaningful_delta and schema_followup_active and not schema_followup_contract_satisfied:
        missing_top_level_fields = [
            str(item).strip()
            for item in list(
                draft_delta_quality.get("schema_followup_missing_top_level_fields", [])
                or prior_draft_delta_quality.get("schema_followup_missing_top_level_fields", [])
                or []
            )
            if str(item).strip()
        ]
        missing_signature = ",".join(missing_top_level_fields)
        previous_signature = str(updated.get("schema_followup_last_missing_signature", "") or "")
        previous_stall_count = int(updated.get("schema_followup_stall_count", 0) or 0)
        prior_missing_top_level_fields = [
            str(item).strip()
            for item in list(prior_draft_delta_quality.get("schema_followup_missing_top_level_fields", []) or [])
            if str(item).strip()
        ]
        prior_missing_signature = ",".join(prior_missing_top_level_fields)
        prior_schema_followup_miss = bool(
            prior_missing_signature == missing_signature
            and not bool(prior_draft_delta_quality.get("schema_followup_contract_satisfied", True))
            and "schema_resonance_followup_top_level_fields_missing"
            in list(prior_draft_delta_quality.get("failed_gates", []) or [])
        )
        stall_count = (
            previous_stall_count + 1
            if previous_stall_count > 0 and previous_signature in {"", missing_signature}
            else 2 if prior_schema_followup_miss else 1
        )
        updated["schema_followup_stall_count"] = stall_count
        updated["schema_followup_last_missing_signature"] = missing_signature
        updated["schema_followup_top_level_fields_present"] = False
        updated["schema_followup_contract_satisfied"] = False
        updated["schema_followup_missing_top_level_fields"] = missing_top_level_fields
        updated["schema_resonance_followup_required"] = True
        updated["missing_top_level_fields"] = list(
            latest_work_order.get("missing_top_level_fields", [])
            or updated.get("missing_top_level_fields", [])
            or missing_top_level_fields
        )
        updated["required_top_level_fields"] = list(
            latest_work_order.get("required_top_level_fields", [])
            or updated.get("required_top_level_fields", [])
            or list(draft_delta_quality.get("schema_followup_required_top_level_fields", []) or [])
            or missing_top_level_fields
        )
        updated["resident_worker_state"] = (
            "schema_resonance_followup_stalled"
            if stall_count >= 2
            else "schema_resonance_followup_injected"
        )
        target_correct_state = dict(updated.get("target_correct_gate_closure", {}) or {})
        if target_correct_state:
            target_correct_state["kernel_consumed_gate_closure"] = False
            target_correct_state["next_action_after_closure"] = ""
            updated["target_correct_gate_closure"] = target_correct_state
        updated["quality_no_progress_count"] = int(updated.get("quality_no_progress_count", 0) or 0) + 1
        updated["consecutive_no_delta_cycles"] = int(updated.get("quality_no_progress_count", 0) or 0)
        updated["updated_at"] = _utc_now()
        _append_ledger(
            operator_root,
            "child_events",
            {
                "event": "schema_resonance_followup_top_level_fields_missing",
                "generated_at": updated["updated_at"],
                "child_run_id": str(updated.get("child_run_id", "") or ""),
                "directive_id": str(updated.get("directive_id", "") or ""),
                "target_artifact": target_artifact,
                "work_order_id": str(latest_work_order.get("work_order_id", "") or ""),
                "missing_top_level_fields": missing_top_level_fields,
                "schema_followup_stall_count": stall_count,
                "resident_worker_state": str(updated.get("resident_worker_state", "") or ""),
            },
        )
        child_id_for_update = str(updated.get("child_run_id", "") or "")
        if child_id_for_update:
            _write_json(_child_path(operator_root, child_id_for_update), updated)
        return updated, None
    followup_complete, followup_reason = _resident_followup_delta_complete(
        campaign_state=campaign_for_completion,
        draft_delta_quality=draft_delta_quality,
        prior_draft_delta_quality=prior_draft_delta_quality,
        latest_progress=latest_progress,
    )
    if followup_complete:
        _request_resident_final_return_after_clean_delta(
            operator_root,
            child=updated,
            reason=followup_reason,
        )
        updated["resident_worker_state"] = "followup_delta_satisfied_return_requested"
        updated["productive_quiescence_eligible"] = True
        updated["return_requested_after_clean_delta"] = True
        updated["followup_completion_reason"] = followup_reason
        updated["consecutive_no_delta_cycles"] = 0
        updated["quality_no_progress_count"] = 0
        return updated, None
    if meaningful_delta:
        directive_id = str(updated.get("directive_id", "") or "")
        promotion: dict[str, Any] = {}
        if directive_id:
            promotion = promote_conveyor_campaign_drafts(operator_root, directive_id=directive_id)
            updated["campaign_promotion"] = {
                "promoted_artifacts": list(promotion.get("promoted_artifacts", []) or []),
                "rejected_artifacts": list(promotion.get("rejected_artifacts", []) or []),
                "promoted_quality_artifacts": list(promotion.get("promoted_quality_artifacts", []) or []),
                "quality_rejected_artifacts": list(promotion.get("quality_rejected_artifacts", []) or []),
                "unchanged_artifacts": list(promotion.get("unchanged_artifacts", []) or []),
                "quality_delta_count": int(promotion.get("quality_delta_count", 0) or 0),
                "weakest_failed_artifact": str(promotion.get("weakest_failed_artifact", "") or ""),
                "generated_at": str(promotion.get("generated_at", "") or ""),
            }
        quality_delta_count = int(promotion.get("quality_delta_count", 0) or 0)
        weakest_failed_artifact = str(promotion.get("weakest_failed_artifact", "") or "")
        updated["latest_quality_target"] = weakest_failed_artifact or target_artifact
        if quality_delta_count > 0:
            schema_followup_active = bool(
                latest_work_order.get("schema_resonance_followup_required", False)
                or schema_support_protection.get("active", False)
            )
            promotion_manifest = dict(promotion.get("manifest", {}) or {})
            promotion_schema = dict(promotion_manifest.get("schema_resonance", {}) or {})
            try:
                promotion_schema_score = float(promotion_schema.get("score", 1.0) or 0.0)
            except (TypeError, ValueError):
                promotion_schema_score = 0.0
            schema_followup_closure_allowed = bool(
                not schema_followup_active
                or (
                    bool(draft_delta_quality.get("schema_followup_contract_satisfied", False))
                    and promotion_schema_score >= 1.0
                )
            )
            if schema_followup_active and not schema_followup_closure_allowed:
                updated["resident_worker_state"] = "schema_resonance_followup_injected"
                updated["schema_resonance_followup_required"] = True
                updated["schema_resonance_score"] = promotion_schema_score
                updated["schema_followup_contract_satisfied"] = bool(
                    draft_delta_quality.get("schema_followup_contract_satisfied", False)
                )
                updated["schema_followup_top_level_fields_present"] = bool(
                    draft_delta_quality.get("schema_followup_top_level_fields_present", False)
                )
                updated["schema_followup_missing_top_level_fields"] = list(
                    draft_delta_quality.get("schema_followup_missing_top_level_fields", []) or []
                )
                target_correct_state = dict(updated.get("target_correct_gate_closure", {}) or {})
                if target_correct_state:
                    target_correct_state["kernel_consumed_gate_closure"] = False
                    target_correct_state["next_action_after_closure"] = ""
                    updated["target_correct_gate_closure"] = target_correct_state
                child_id_for_update = str(updated.get("child_run_id", "") or "")
                if child_id_for_update:
                    _write_json(_child_path(operator_root, child_id_for_update), updated)
                return updated, None
            if target_artifact:
                plateau_counts = dict(updated.get("draft_plateau_counts_by_artifact", {}) or {})
                plateau_counts[target_artifact] = 0
                updated["draft_plateau_counts_by_artifact"] = plateau_counts
                updated["draft_plateau_count"] = 0
                draft_delta_quality = dict(updated.get("draft_delta_quality", {}) or {})
                draft_delta_quality["draft_plateau"] = False
                draft_delta_quality["draft_plateau_count"] = 0
                draft_delta_quality["failed_gates"] = [
                    gate for gate in list(draft_delta_quality.get("failed_gates", []) or []) if gate != "draft_delta_plateau"
                ]
                updated["draft_delta_quality"] = draft_delta_quality
                updated["latest_draft_delta_gate_failures"] = list(draft_delta_quality.get("failed_gates", []) or [])
            updated["consecutive_no_delta_cycles"] = 0
            updated["quality_no_progress_count"] = 0
            updated["resident_worker_state"] = "working_with_quality_deltas"
            updated["last_meaningful_delta_at"] = str(latest_progress.get("generated_at", "") or _utc_now())
            updated["last_quality_promotion_at"] = str(promotion.get("generated_at", "") or latest_progress.get("generated_at", "") or _utc_now())
            updated["latest_work_order_id"] = str(latest_progress.get("work_order_id", "") or updated.get("latest_work_order_id", "") or "")
            retarget_artifact = (
                _resident_quality_retarget(
                    operator_root,
                    directive_id=directive_id,
                    active_child=updated,
                    previous_target=target_artifact,
                    stale_weakest_failed_artifact=weakest_failed_artifact,
                )
                if directive_id
                else weakest_failed_artifact
            )
            if retarget_artifact and retarget_artifact != target_artifact:
                retarget_reason = (
                    f"Campaign quality improved for {target_artifact}; retargeting to weakest failed artifact "
                    f"{retarget_artifact}."
                )
                work_order = _append_resident_work_order(
                    operator_root,
                    state_root=state_root,
                    child=updated,
                    latest_progress=latest_progress,
                    target_artifact=retarget_artifact,
                    reason=retarget_reason,
                )
                _append_quality_growth_evidence(
                    operator_root,
                    child=updated,
                    latest_progress=latest_progress,
                    work_order=work_order,
                    reason=retarget_reason,
                )
                _append_target_correct_gate_closure_evidence(
                    operator_root,
                    child=updated,
                    latest_progress=latest_progress,
                    next_unresolved_artifact=retarget_artifact,
                    reason=retarget_reason,
                )
                updated["resident_worker_state"] = "quality_retargeted"
                updated["latest_quality_target"] = retarget_artifact
                updated["latest_quality_retarget_reason"] = "weakest_failed_artifact_after_quality_delta"
                target_correct_state = dict(updated.get("target_correct_gate_closure", {}) or {})
                if bool(target_correct_state.get("target_correct", False)):
                    target_correct_state["kernel_consumed_gate_closure"] = True
                    target_correct_state["next_action_after_closure"] = "retarget_next_unresolved_artifact"
                    target_correct_state["next_unresolved_gate_artifact"] = retarget_artifact
                    updated["target_correct_gate_closure"] = target_correct_state
                updated["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
                updated["latest_work_order_target_artifact"] = str(work_order.get("target_artifact", "") or "")
                updated["latest_work_order_at"] = str(work_order.get("generated_at", "") or "")
                updated["latest_work_order"] = dict(work_order)
            return updated, None
        quality_no_progress = int(updated.get("quality_no_progress_count", 0) or 0) + 1
        updated["quality_no_progress_count"] = quality_no_progress
        updated["consecutive_no_delta_cycles"] = quality_no_progress
        updated["resident_worker_state"] = "working_without_quality_delta"
        updated["last_artifact_activity_at"] = str(latest_progress.get("generated_at", "") or _utc_now())
        support_injection_count = int(updated.get("support_injection_count", 0) or 0)
        support_backed_plateau = support_injection_count > 0 or checkout_support_backed
        support_anchor_cycle = (
            int(updated.get("last_support_injected_cycle_index", 0) or 0)
            if support_injection_count > 0
            else int(updated.get("first_checkout_support_cycle_index", previous_cycle_index or cycle_index) or 0)
        )
        post_support_no_delta = max(0, cycle_index - support_anchor_cycle) if support_backed_plateau else 0
        plateau_signature_unchanged_count = 0
        if support_backed_plateau:
            plateau_signature_unchanged_count = _update_post_support_plateau_gate_signature(
                updated,
                latest_progress=latest_progress,
                draft_delta_quality=draft_delta_quality,
                campaign_state=campaign_for_completion,
                target_artifact=target_artifact,
                post_support_no_delta=post_support_no_delta,
            )
        if (
            support_backed_plateau
            and plateau_signature_unchanged_count >= RESIDENT_NO_DELTA_BLOCKER_THRESHOLD
        ):
            return _hard_stop_resident_plateau_after_support(
                operator_root,
                state_root=state_root,
                updated=updated,
                latest_progress=latest_progress,
                runner=runner,
                target_artifact=target_artifact,
                campaign_for_completion=campaign_for_completion,
                latest_work_order=latest_work_order,
                post_support_no_delta=post_support_no_delta,
            )
        if quality_no_progress >= no_delta_support_threshold:
            if bool(schema_support_protection.get("block_generic_support", False)):
                updated = _preserve_schema_followup_work_order_awaiting_canonicalization(
                    updated,
                    latest_work_order=latest_work_order,
                    protection=schema_support_protection,
                    target_artifact=target_artifact,
                )
                return updated, None
            if bool(schema_support_protection.get("schema_aware_support_required", False)):
                schema_support_reason = (
                    "schema_resonance_followup_stalled_support: preserving the active schema follow-up "
                    f"contract for {target_artifact} until canonical schema resonance reaches 1.0."
                )
                work_order = _append_resident_work_order(
                    operator_root,
                    state_root=state_root,
                    child=updated,
                    latest_progress=latest_progress,
                    target_artifact=target_artifact,
                    reason=schema_support_reason,
                    schema_resonance_followup={
                        "schema_resonance_followup_required": True,
                        "schema_resonance_score": float(
                            schema_support_protection.get("schema_resonance_score", 0.0) or 0.0
                        ),
                        "required_top_level_fields": list(
                            schema_support_protection.get("required_top_level_fields", []) or []
                        ),
                        "missing_top_level_fields": list(
                            schema_support_protection.get("missing_top_level_fields", []) or []
                        ),
                        "artifact_top_level_schema_skeleton": dict(
                            schema_support_protection.get("artifact_top_level_schema_skeleton", {}) or {}
                        ),
                    },
                )
                updated["resident_worker_state"] = "schema_resonance_followup_stalled"
                updated["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
                updated["latest_work_order_target_artifact"] = str(work_order.get("target_artifact", "") or "")
                updated["latest_work_order_at"] = str(work_order.get("generated_at", "") or "")
                updated["latest_work_order"] = dict(work_order)
                updated["schema_resonance_followup_required"] = True
                growth_receipt = _append_growth_receipt(
                    operator_root,
                    child=updated,
                    work_order=work_order,
                    trigger_signal="schema_resonance_followup_stalled",
                    selected_action="schema_resonance_followup_stalled_support",
                    baseline_action="inject_generic_quality_support",
                    final_action="preserve_schema_followup_contract",
                    before_state={
                        "target_artifact": target_artifact,
                        "missing_top_level_fields": list(
                            schema_support_protection.get("missing_top_level_fields", []) or []
                        ),
                    },
                    after_state={
                        "target_artifact": target_artifact,
                        "schema_resonance_followup_required": True,
                        "resident_worker_state": "schema_resonance_followup_stalled",
                    },
                    manifest={},
                    reason=schema_support_reason,
                )
                updated["growth_receipt_id"] = str(growth_receipt.get("receipt_id", "") or "")
                updated["growth_receipt_state"] = str(growth_receipt.get("receipt_state", "") or "")
                return updated, None
            retarget = (
                _resident_quality_retarget(
                    operator_root,
                    directive_id=directive_id,
                    active_child=updated,
                    previous_target=target_artifact,
                    stale_weakest_failed_artifact=weakest_failed_artifact,
                    prefer_previous_failed_target=True,
                )
                if directive_id
                else (weakest_failed_artifact or target_artifact)
            )
            support_reason = (
                f"Resident worker produced {quality_no_progress} artifact activity cycle(s) without canonical "
                f"quality progress; retargeting to {retarget} with explicit quality gates."
            )
            depth_obligation = _plateau_depth_obligation_fields(
                child=updated,
                latest_progress=latest_progress,
                target_artifact=retarget,
                campaign_state=campaign_for_completion,
                reason=support_reason,
            )
            work_order = _append_resident_work_order(
                operator_root,
                state_root=state_root,
                child=updated,
                latest_progress=latest_progress,
                target_artifact=retarget,
                reason=support_reason,
                plateau_intervention_stage=str(depth_obligation.get("plateau_intervention_stage", "") or ""),
                depth_obligation_id=str(depth_obligation.get("depth_obligation_id", "") or ""),
                depth_missing_fields=list(depth_obligation.get("depth_missing_fields", []) or []),
                depth_required_evidence_refs=list(depth_obligation.get("depth_required_evidence_refs", []) or []),
                target_delta_required=True,
            )
            _append_quality_growth_evidence(
                operator_root,
                child=updated,
                latest_progress=latest_progress,
                work_order=work_order,
                reason=support_reason,
            )
            updated["resident_worker_state"] = "quality_support_injected"
            updated["support_injection_count"] = int(updated.get("support_injection_count", 0) or 0) + 1
            updated["last_support_injected_cycle_index"] = cycle_index
            updated["latest_quality_retarget_reason"] = "artifact_activity_without_quality_delta"
            updated["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
            updated["latest_work_order_target_artifact"] = str(work_order.get("target_artifact", "") or "")
            updated["latest_work_order_at"] = str(work_order.get("generated_at", "") or "")
            updated["latest_work_order"] = dict(work_order)
            _copy_depth_obligation_to_child(updated, work_order)
        return updated, None
    consecutive = int(updated.get("consecutive_no_delta_cycles", 0) or 0) + new_no_delta_cycles
    updated["consecutive_no_delta_cycles"] = consecutive
    support_injection_count = int(updated.get("support_injection_count", 0) or 0)
    last_support_cycle = int(updated.get("last_support_injected_cycle_index", 0) or 0)
    if support_injection_count <= 0 and not checkout_support_backed and consecutive >= no_delta_support_threshold:
        if bool(schema_support_protection.get("block_generic_support", False)):
            updated = _preserve_schema_followup_work_order_awaiting_canonicalization(
                updated,
                latest_work_order=latest_work_order,
                protection=schema_support_protection,
                target_artifact=target_artifact,
            )
            return updated, None
        if bool(schema_support_protection.get("schema_aware_support_required", False)):
            schema_support_reason = (
                "schema_resonance_followup_stalled_support: preserving the active schema follow-up "
                f"contract for {target_artifact} until canonical schema resonance reaches 1.0."
            )
            work_order = _append_resident_work_order(
                operator_root,
                state_root=state_root,
                child=updated,
                latest_progress=latest_progress,
                target_artifact=target_artifact,
                reason=schema_support_reason,
                schema_resonance_followup={
                    "schema_resonance_followup_required": True,
                    "schema_resonance_score": float(schema_support_protection.get("schema_resonance_score", 0.0) or 0.0),
                    "required_top_level_fields": list(schema_support_protection.get("required_top_level_fields", []) or []),
                    "missing_top_level_fields": list(schema_support_protection.get("missing_top_level_fields", []) or []),
                    "artifact_top_level_schema_skeleton": dict(
                        schema_support_protection.get("artifact_top_level_schema_skeleton", {}) or {}
                    ),
                },
            )
            updated["resident_worker_state"] = "schema_resonance_followup_stalled"
            updated["support_injection_count"] = support_injection_count + 1
            updated["last_support_injected_cycle_index"] = cycle_index
            updated["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
            updated["latest_work_order_target_artifact"] = str(work_order.get("target_artifact", "") or "")
            updated["latest_work_order_at"] = str(work_order.get("generated_at", "") or "")
            updated["latest_work_order"] = dict(work_order)
            updated["schema_resonance_followup_required"] = True
            growth_receipt = _append_growth_receipt(
                operator_root,
                child=updated,
                work_order=work_order,
                trigger_signal="schema_resonance_followup_stalled",
                selected_action="schema_resonance_followup_stalled_support",
                baseline_action="inject_generic_support",
                final_action="preserve_schema_followup_contract",
                before_state={
                    "target_artifact": target_artifact,
                    "missing_top_level_fields": list(
                        schema_support_protection.get("missing_top_level_fields", []) or []
                    ),
                },
                after_state={
                    "target_artifact": target_artifact,
                    "schema_resonance_followup_required": True,
                    "resident_worker_state": "schema_resonance_followup_stalled",
                },
                manifest={},
                reason=schema_support_reason,
            )
            updated["growth_receipt_id"] = str(growth_receipt.get("receipt_id", "") or "")
            updated["growth_receipt_state"] = str(growth_receipt.get("receipt_state", "") or "")
            return updated, None
        support_reason = (
            f"Resident worker reached {consecutive} no-artifact-delta cycle(s); "
            f"quality support injected for {target_artifact}."
        )
        depth_obligation = _plateau_depth_obligation_fields(
            child=updated,
            latest_progress=latest_progress,
            target_artifact=target_artifact,
            campaign_state=campaign_for_completion,
            reason=support_reason,
        )
        work_order = _append_resident_work_order(
            operator_root,
            state_root=state_root,
            child=updated,
            latest_progress=latest_progress,
            target_artifact=target_artifact,
            reason=support_reason,
            plateau_intervention_stage=str(depth_obligation.get("plateau_intervention_stage", "") or ""),
            depth_obligation_id=str(depth_obligation.get("depth_obligation_id", "") or ""),
            depth_missing_fields=list(depth_obligation.get("depth_missing_fields", []) or []),
            depth_required_evidence_refs=list(depth_obligation.get("depth_required_evidence_refs", []) or []),
            target_delta_required=True,
        )
        updated["resident_worker_state"] = "support_injected"
        updated["support_injection_count"] = 1
        updated["last_support_injected_cycle_index"] = cycle_index
        updated["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
        updated["latest_work_order_target_artifact"] = str(work_order.get("target_artifact", "") or "")
        updated["latest_work_order_at"] = str(work_order.get("generated_at", "") or "")
        updated["latest_work_order"] = dict(work_order)
        _copy_depth_obligation_to_child(updated, work_order)
        return updated, None
    support_backed_plateau = support_injection_count > 0 or checkout_support_backed
    support_anchor_cycle = (
        last_support_cycle
        if support_injection_count > 0
        else int(updated.get("first_checkout_support_cycle_index", previous_cycle_index or cycle_index) or 0)
    )
    post_support_no_delta = max(0, cycle_index - support_anchor_cycle) if support_backed_plateau else 0
    plateau_signature_unchanged_count = 0
    if support_backed_plateau:
        plateau_signature_unchanged_count = _update_post_support_plateau_gate_signature(
            updated,
            latest_progress=latest_progress,
            draft_delta_quality=draft_delta_quality,
            campaign_state=campaign_for_completion,
            target_artifact=target_artifact,
            post_support_no_delta=post_support_no_delta,
        )
    if support_backed_plateau and plateau_signature_unchanged_count >= RESIDENT_NO_DELTA_BLOCKER_THRESHOLD:
        return _hard_stop_resident_plateau_after_support(
            operator_root,
            state_root=state_root,
            updated=updated,
            latest_progress=latest_progress,
            runner=runner,
            target_artifact=target_artifact,
            campaign_for_completion=campaign_for_completion,
            latest_work_order=latest_work_order,
            post_support_no_delta=post_support_no_delta,
        )
    updated["resident_worker_state"] = "working_without_artifact_delta"
    return updated, None


def _spawn_child_for_directive(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    directive: Mapping[str, Any],
    runner: ConveyorChildRunner | None = None,
    scheduler: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    now = _utc_now()
    directive_id = str(directive.get("directive_id", "") or "")
    lock_owner = _record_id("spawn-lock-owner", directive_id, now, uuid.uuid4().hex)
    lock_acquired, lock_path, lock_reason = _acquire_directive_spawn_lock(
        operator_root,
        directive_id,
        owner=lock_owner,
    )
    if not lock_acquired:
        released_lease = release_task_manager_lease(
            operator_root,
            directive_id=directive_id,
            reason=lock_reason or "directive_spawn_lock_active",
        )
        suppression = {
            "schema_name": CHILD_RUN_SCHEMA_NAME,
            "schema_version": CHILD_RUN_SCHEMA_VERSION,
            "child_run_id": "",
            "directive_id": directive_id,
            "state": "spawn_suppressed",
            "spawn_suppressed": True,
            "spawn_suppression_reason": lock_reason or "directive_spawn_lock_active",
            "task_manager_lease_released": bool(
                dict(released_lease or {}).get("lease_state", "") == "released"
            ),
            "task_manager_release_reason": str(
                dict(released_lease or {}).get("repair_reason", "") or ""
            ),
            "generated_at": now,
            "updated_at": now,
        }
        _append_ledger(operator_root, "child_events", {"event": "spawn_suppressed", **suppression})
        return suppression
    try:
        return _spawn_child_for_directive_unlocked(
            operator_root,
            state_root=state_root,
            directive=directive,
            runner=runner,
            scheduler=scheduler,
        )
    finally:
        _release_directive_spawn_lock(lock_path)


def _spawn_child_for_directive_unlocked(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    directive: Mapping[str, Any],
    runner: ConveyorChildRunner | None = None,
    scheduler: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    now = _utc_now()
    scheduler_payload = dict(scheduler or _load_scheduler(operator_root))
    effective_runner = runner or runner_from_scheduler(scheduler_payload)
    directive_id = str(directive.get("directive_id", "") or "")
    latest_directive = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
    if latest_directive:
        directive = latest_directive
    existing_active_children = _active_children_for_directive(operator_root, directive_id)
    if existing_active_children:
        existing_ids = [
            str(child.get("child_run_id", "") or "")
            for child in existing_active_children
            if str(child.get("child_run_id", "") or "")
        ]
        suppression = {
            "schema_name": CHILD_RUN_SCHEMA_NAME,
            "schema_version": CHILD_RUN_SCHEMA_VERSION,
            "child_run_id": "",
            "directive_id": directive_id,
            "state": "spawn_suppressed",
            "spawn_suppressed": True,
            "spawn_suppression_reason": "spawn_suppressed_existing_active_child",
            "existing_active_child_run_ids": existing_ids,
            "existing_active_child_count": len(existing_active_children),
            "generated_at": now,
            "updated_at": now,
        }
        _append_ledger(operator_root, "child_events", {"event": "spawn_suppressed", **suppression})
        release_task_manager_lease(
            operator_root,
            directive_id=directive_id,
            reason="spawn_suppressed_existing_active_child",
        )
        return suppression
    directive_metadata = dict(directive.get("metadata", {}) or {})
    child_execution_mode = str(
        directive_metadata.get("child_execution_mode", scheduler_payload.get("child_execution_mode", "oneshot_return"))
        or "oneshot_return"
    ).strip().lower()
    if child_execution_mode not in {"oneshot_return", "resident_campaign"}:
        child_execution_mode = "oneshot_return"
    pre_spawn_closure: dict[str, Any] = {}
    if child_execution_mode == "resident_campaign":
        candidate_initial_target = str(
            directive_metadata.get("initial_work_order_target_artifact", "")
            or directive_metadata.get("continuous_campaign_latest_target_artifact", "")
            or ""
        ).strip()
        directive, _, pre_spawn_closure = _retarget_initial_work_order_after_partial_closure(
            operator_root,
            directive=directive,
            target_artifact=candidate_initial_target,
        )
        directive_metadata = dict(directive.get("metadata", {}) or {})
    child_run_id = _record_id("child", directive_id, now, uuid.uuid4().hex)
    workspace_root = _workspaces_root(operator_root) / child_run_id
    outbox_path = _outboxes_root(operator_root) / child_run_id
    inbox_path = _inboxes_root(operator_root) / child_run_id
    progress_path = _progress_root(operator_root) / child_run_id
    campaign_draft_path = _campaign_drafts_root(operator_root, directive_id)
    campaign_canonical_path = _campaign_canonical_root(operator_root, directive_id)
    workspace_permission_mode = _prepare_child_write_dir(workspace_root)
    outbox_permission_mode = _prepare_child_write_dir(outbox_path)
    inbox_permission_mode = _prepare_child_write_dir(inbox_path)
    progress_permission_mode = _prepare_child_write_dir(progress_path)
    campaign_draft_write_prep = _prepare_child_writable_tree(campaign_draft_path)
    campaign_draft_permission_mode = str(campaign_draft_write_prep.get("directory_mode", "unknown") or "unknown")
    campaign_canonical_path.mkdir(parents=True, exist_ok=True)
    checkout = _build_checkout_bundle(
        operator_root,
        state_root=state_root,
        directive=directive,
        child_run_id=child_run_id,
        child_execution_mode=child_execution_mode,
        inbox_path=inbox_path,
        progress_path=progress_path,
        scheduler=scheduler_payload,
    )
    inbox_payload = {
        "schema_name": "ConveyorChildInbox",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": now,
        "child_run_id": child_run_id,
        "directive_id": directive_id,
        "request_final_return": False,
        "stop_requested": False,
        "messages": [
            {
                "kind": "kernel_context",
                "generated_at": now,
                "operator_feedback": str(directive.get("operator_feedback", "") or ""),
                "previous_return_packet_id": str(directive.get("latest_return_packet_id", "") or ""),
                "support_request_refs": list(checkout.get("support_request_refs", []) or []),
                "librarian_pack_refs": list(checkout.get("librarian_pack_refs", []) or []),
            }
        ],
    }
    initial_work_order: dict[str, Any] = {}
    explicit_initial_target = str(directive_metadata.get("initial_work_order_target_artifact", "") or "").strip()
    recovered_initial_target = str(directive_metadata.get("continuous_campaign_latest_target_artifact", "") or "").strip()
    initial_target = explicit_initial_target or recovered_initial_target
    initial_recovered_from_campaign_metadata = bool(initial_target and not explicit_initial_target and recovered_initial_target)
    if child_execution_mode == "resident_campaign" and initial_target in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER:
        initial_campaign_state = _read_json(_campaign_manifest_path(operator_root, directive_id))
        enrichment = _work_order_enrichment(
            operator_root,
            directive=directive,
            target_artifact=initial_target,
            campaign_state=initial_campaign_state,
            target_selection_reason=(
                "checkout_structured_target_recovery"
                if initial_recovered_from_campaign_metadata
                else ""
            ),
        )
        initial_context = str(directive_metadata.get("initial_work_order_context", "") or "").strip()
        if not initial_context:
            initial_context = _campaign_artifact_guidance(
                initial_target,
                fallback=(
                    f"Revise {initial_target} with directive-specific typed contracts, boundary conditions, "
                    "inputs/outputs, validation fixtures, failure modes, safety/governance boundaries, "
                    "and prototype integration assumptions."
                ),
                directive=directive,
                failed_gates=list(
                    dict(
                        dict(initial_campaign_state.get("canonical_artifacts", {}) or {}).get(initial_target, {})
                    ).get("failed_quality_gates", [])
                    or []
                ),
            )
        initial_work_order = {
            "kind": "kernel_work_order",
            "schema_name": "ConveyorChildWorkOrder",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "work_order_id": _record_id("work-order", child_run_id, initial_target, "initial"),
            "generated_at": now,
            "child_run_id": child_run_id,
            "directive_id": directive_id,
            "capability": str(
                directive_metadata.get("initial_work_order_capability", "")
                or "directive_build_grade_synthesis_pack"
            ),
            "support_request_id": "",
            "support_state": "satisfied",
            "target_artifact": initial_target,
            "next_step_context": initial_context,
            "allowed_pack_refs": list(checkout.get("librarian_pack_refs", []) or []),
            "support_request_refs": list(checkout.get("support_request_refs", []) or []),
            "previous_return_packet_id": str(
                directive_metadata.get("initial_work_order_source_return_packet_id", "")
                or directive_metadata.get("continuous_campaign_latest_return_packet_id", "")
                or directive.get("latest_return_packet_id", "")
                or ""
            ),
            "partial_target_correct_closure": bool(pre_spawn_closure),
            "closed_target_artifact": str(pre_spawn_closure.get("closed_target_artifact", "") or ""),
            "next_linked_artifact_target": str(pre_spawn_closure.get("next_linked_artifact_target", "") or ""),
            "remaining_linked_artifact_gaps": list(
                pre_spawn_closure.get("remaining_linked_artifact_gaps", []) or []
            ),
            "initial_work_order_recovered_from_campaign_metadata": initial_recovered_from_campaign_metadata,
            **enrichment,
            "grants_execution_authority": False,
            "network_policy": "deny_all",
            "kernel_mediated_only": True,
        }
        _record_role_research_adapter_consumption(
            operator_root,
            work_order=initial_work_order,
            baseline_action="issue_basic_child_work_order",
            final_action="issue_role_adapter_shaped_child_work_order",
            reason=str(enrichment.get("target_selection_reason", "") or "role_adapter_output_contract"),
        )
        inbox_payload["messages"].append(initial_work_order)
    if child_execution_mode == "resident_campaign" and initial_target and not initial_work_order:
        released_lease = release_task_manager_lease(
            operator_root,
            directive_id=directive_id,
            reason="resident_initial_work_order_missing",
        )
        suppression = {
            "schema_name": CHILD_RUN_SCHEMA_NAME,
            "schema_version": CHILD_RUN_SCHEMA_VERSION,
            "child_run_id": "",
            "directive_id": directive_id,
            "state": "spawn_suppressed",
            "spawn_suppressed": True,
            "spawn_suppression_reason": "resident_initial_work_order_missing",
            "resident_support_handoff_state": "spawn_suppressed_missing_work_order",
            "intended_target_artifact": initial_target,
            "task_manager_lease_released": bool(
                dict(released_lease or {}).get("lease_state", "") == "released"
            ),
            "generated_at": now,
            "updated_at": now,
            "grants_execution_authority": False,
        }
        _append_ledger(operator_root, "child_events", {"event": "spawn_suppressed", **suppression})
        return suppression
    _write_json(inbox_path / "inbox.json", inbox_payload)
    child = {
        "schema_name": CHILD_RUN_SCHEMA_NAME,
        "schema_version": CHILD_RUN_SCHEMA_VERSION,
        "child_run_id": child_run_id,
        "directive_id": directive_id,
        "state": "spawning",
        "spawn_state": "planning",
        "spawn_reservation_state": "reserved",
        "spawn_reserved_at": now,
        "spawn_mode": "",
        "network_policy": "deny_all",
        "child_execution_mode": child_execution_mode,
        "write_authority": "isolated_workspace_only",
        "workspace_root": str(workspace_root),
        "outbox_path": str(outbox_path),
        "inbox_path": str(inbox_path),
        "progress_path": str(progress_path),
        "support_pack_checkout_path": str(checkout.get("host_support_pack_checkout_path", "") or ""),
        "support_pack_bytes": int(checkout.get("support_pack_bytes", 0) or 0),
        "support_pack_manifest": dict(checkout.get("support_pack_manifest", {}) or {}),
        "child_compute_mode": str(checkout.get("child_compute_mode", "") or ""),
        "child_compute_budget_seconds": int(checkout.get("child_compute_budget_seconds", 0) or 0),
        "child_compute_max_passes": int(checkout.get("child_compute_max_passes", 0) or 0),
        "campaign_draft_path": str(campaign_draft_path),
        "campaign_canonical_path": str(campaign_canonical_path),
        "campaign_manifest_path": str(_campaign_manifest_path(operator_root, directive_id)),
        "workspace_permission_mode": workspace_permission_mode,
        "outbox_permission_mode": outbox_permission_mode,
        "inbox_permission_mode": inbox_permission_mode,
        "progress_permission_mode": progress_permission_mode,
        "campaign_draft_permission_mode": campaign_draft_permission_mode,
        "campaign_draft_file_permission_modes": dict(
            campaign_draft_write_prep.get("file_modes", {}) or {}
        ),
        "campaign_draft_writable_file_count": int(
            campaign_draft_write_prep.get("prepared_file_count", 0) or 0
        ),
        "campaign_draft_writable_prepare_failed_count": int(
            campaign_draft_write_prep.get("prepare_failed_count", 0) or 0
        ),
        "campaign_draft_writable_prepare_failed_paths": list(
            campaign_draft_write_prep.get("failed_paths", []) or []
        ),
        "checkout_id": str(checkout.get("checkout_id", "")),
        "checkout_path": str(_checkout_path(operator_root, str(checkout.get("checkout_id", "")))),
        "created_at": now,
        "updated_at": now,
        "pause_requested": False,
        "stop_requested": False,
    }
    if initial_work_order:
        child["latest_work_order_id"] = str(initial_work_order.get("work_order_id", "") or "")
        child["latest_work_order_target_artifact"] = str(initial_work_order.get("target_artifact", "") or "")
        child["latest_work_order_at"] = str(initial_work_order.get("generated_at", "") or "")
        child["latest_work_order"] = dict(initial_work_order)
        child["resident_first_cycle_sleep_seconds"] = int(
            checkout.get("resident_first_cycle_sleep_seconds", checkout.get("resident_cycle_sleep_seconds", 0)) or 0
        )
        child["omitted_support_pack_ref_count"] = int(checkout.get("omitted_support_pack_ref_count", 0) or 0)
        child["support_pack_rank_summary"] = list(checkout.get("support_pack_rank_summary", []) or [])
    intended_target = initial_target if initial_target in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER else ""
    spawned_target = str(initial_work_order.get("target_artifact", "") or "")
    intent_continuity = {
        "source_return_packet_id": str(
            directive_metadata.get("initial_work_order_source_return_packet_id", "")
            or directive_metadata.get("continuous_campaign_latest_return_packet_id", "")
            or directive.get("latest_return_packet_id", "")
            or ""
        ),
        "intended_target_artifact": intended_target,
        "spawned_target_artifact": spawned_target,
        "inbox_work_order_present": bool(initial_work_order),
        "role_adapter_ref_present": bool(
            dict(initial_work_order.get("role_research_adapter_ref", {}) or {}).get(
                "role_specific_research_adapter_id", ""
            )
        ),
        "requirement_contract_present": bool(initial_work_order.get("child_output_contract")),
        "recovered_from_campaign_metadata": initial_recovered_from_campaign_metadata,
        "preserved": bool(intended_target and spawned_target == intended_target and initial_work_order),
    }
    failed_intent_gates: list[str] = []
    if intended_target and not intent_continuity["preserved"]:
        failed_intent_gates.append("handoff_intent_not_preserved")
    if intended_target and not bool(initial_work_order):
        failed_intent_gates.append("structured_work_order_missing_after_requeue")
    intent_continuity["failed_gates"] = failed_intent_gates
    if intended_target:
        child["intent_continuity"] = intent_continuity
    _write_json(_child_path(operator_root, child_run_id), child)
    reserved_directive = dict(_read_json(_directive_path(operator_root, directive_id)) or directive)
    reserved_directive["state"] = "running"
    reserved_directive["active_child_run_id"] = child_run_id
    reserved_directive.pop("blocked_reason", None)
    reserved_directive.pop("blocked_at", None)
    reserved_directive["updated_at"] = now
    reserved_metadata = dict(reserved_directive.get("metadata", {}) or {})
    reserved_metadata["spawn_reservation_state"] = "reserved"
    reserved_metadata["spawn_reserved_child_run_id"] = child_run_id
    reserved_metadata["spawn_reserved_at"] = now
    reserved_directive["metadata"] = reserved_metadata
    _write_json(_directive_path(operator_root, directive_id), reserved_directive)
    _append_ledger(
        operator_root,
        "child_events",
        {
            "event": "spawn_reserved",
            "generated_at": now,
            "child_run_id": child_run_id,
            "directive_id": directive_id,
            "spawn_reservation_state": "reserved",
        },
    )
    plan = effective_runner.plan_child_container(child)
    spawn = effective_runner.spawn_child_container(child, plan)
    child["spawn_mode"] = str(plan.get("spawn_mode", "simulated_child_container") or "simulated_child_container")
    child["spawn_state"] = str(spawn.get("spawn_state", "spawned") or "spawned")
    child["container_id"] = str(spawn.get("container_id", "") or "")
    child["container_name"] = str(spawn.get("container_name", plan.get("container_name", "")) or "")
    child["container_image"] = str(plan.get("container_image", "") or "")
    child["docker_command"] = list(plan.get("docker_command", []) or [])
    child["runner_plan"] = {
        key: value
        for key, value in dict(plan).items()
        if key not in {"docker_command"}
    }
    spawn_failed = not bool(spawn.get("ok", False))
    spawn_fault_kind = ""
    if spawn_failed:
        child["state"] = "failed"
        child["spawn_reservation_state"] = "released_failed"
        child["spawn_error"] = str(spawn.get("error", "") or spawn.get("stderr", "") or "child runner spawn failed")
        spawn_fault_kind = classify_conveyor_infrastructure_fault(OSError(5, child["spawn_error"]))
        child["spawn_failure_kind"] = spawn_fault_kind or "spawn_failed"
        if spawn_fault_kind:
            child["infrastructure_fault"] = True
            child["infrastructure_fault_kind"] = spawn_fault_kind
    else:
        child["state"] = "running"
        child["spawn_reservation_state"] = "fulfilled"
        child["spawn_fulfilled_at"] = _utc_now()
    _write_json(_child_path(operator_root, child_run_id), child)
    update_task_manager_lease_after_spawn(
        operator_root,
        directive_id=directive_id,
        child_run_id=child_run_id,
        spawn_failed=spawn_failed,
    )
    if intended_target:
        _append_ledger(
            operator_root,
            "conveyor_intent_continuity_events",
            {
                "schema_name": "ConveyorIntentContinuityEvent",
                "schema_version": CONVEYOR_SCHEMA_VERSION,
                "created_at": now,
                "child_run_id": child_run_id,
                "directive_id": directive_id,
                **intent_continuity,
            },
        )
    updated_directive = dict(_read_json(_directive_path(operator_root, directive_id)) or directive)
    updated_directive["state"] = "requeued" if spawn_failed else "running"
    updated_directive["active_child_run_id"] = "" if spawn_failed else child_run_id
    updated_directive["updated_at"] = now
    updated_metadata = dict(updated_directive.get("metadata", {}) or {})
    if spawn_failed:
        updated_metadata["latest_spawn_failure_kind"] = spawn_fault_kind or "spawn_failed"
        updated_metadata["latest_spawn_failed_child_run_id"] = child_run_id
        updated_metadata["latest_spawn_failed_at"] = now
        updated_metadata["spawn_reservation_state"] = "released_failed"
        if spawn_fault_kind:
            updated_metadata["latest_spawn_infrastructure_fault"] = spawn_fault_kind
            updated_metadata["latest_spawn_fault_at"] = now
        updated_metadata["latest_spawn_fault_recovery_action"] = (
            "recover_docker_mount_and_scheduler_tick"
            if spawn_fault_kind
            else "scheduler_tick"
        )
        updated_directive["metadata"] = updated_metadata
    else:
        updated_directive.pop("blocked_reason", None)
        updated_directive.pop("blocked_at", None)
        updated_metadata["spawn_reservation_state"] = "fulfilled"
        updated_metadata["spawn_fulfilled_child_run_id"] = child_run_id
        updated_metadata["spawn_fulfilled_at"] = child.get("spawn_fulfilled_at", "")
        if initial_work_order:
            updated_metadata["latest_spawned_work_order_target_artifact"] = str(
                initial_work_order.get("target_artifact", "") or ""
            )
            updated_metadata["latest_spawned_work_order_id"] = str(
                initial_work_order.get("work_order_id", "") or ""
            )
        preserve_initial_work_order_context = bool(
            str(updated_metadata.get("support_recovery_state", "") or "")
            or str(updated_metadata.get("support_request_id", "") or "")
            or str(updated_metadata.get("r_and_d_design_brief_id", "") or "")
        )
        if initial_work_order:
            if preserve_initial_work_order_context:
                updated_metadata["initial_work_order_target_artifact"] = str(
                    initial_work_order.get("target_artifact", "")
                    or updated_metadata.get("initial_work_order_target_artifact", "")
                    or ""
                )
                updated_metadata.setdefault(
                    "initial_work_order_capability",
                    str(initial_work_order.get("capability", "") or "directive_build_grade_synthesis_pack"),
                )
            else:
                for key in (
                    "initial_work_order_target_artifact",
                    "initial_work_order_context",
                    "initial_work_order_source_return_packet_id",
                    "initial_work_order_capability",
                ):
                    updated_metadata.pop(key, None)
        updated_directive["metadata"] = updated_metadata
    _write_json(_directive_path(operator_root, directive_id), updated_directive)
    _append_ledger(operator_root, "child_events", {"event": "spawned", **child})
    return child


def _scheduler_pending_return_evaluation_degraded(reason: str) -> dict[str, Any]:
    return {
        "ok": False,
        "schema_name": "ConveyorPendingReturnEvaluation",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "evaluation_deferred": True,
        "control_plane_response_mode": "degraded",
        "control_plane_degraded_reason": reason,
        "requeued_count": 0,
        "held_for_operator_count": 0,
        "evaluated_return_count": 0,
    }


def _scheduler_pending_return_evaluation_worker(
    operator_root: str,
    state_root: str,
    queue: Any,
) -> None:
    try:
        queue.put({"ok": True, "result": evaluate_pending_child_returns(operator_root, state_root=state_root)})
    except Exception as exc:  # pragma: no cover - child process defensive path.
        queue.put({"ok": False, "error_type": type(exc).__name__, "error": str(exc)})


def _evaluate_pending_child_returns_for_scheduler(
    operator_root: str | Path,
    *,
    state_root: str | Path,
) -> dict[str, Any]:
    if not conveyor_pending_return_evaluation_required(operator_root):
        return {
            "ok": True,
            "schema_name": "ConveyorPendingReturnEvaluation",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "generated_at": _utc_now(),
            "evaluation_required": False,
            "requeued_count": 0,
            "held_for_operator_count": 0,
            "evaluated_return_count": 0,
        }
    timeout_seconds = max(0.0, float(SCHEDULER_RETURN_EVALUATION_TIMEOUT_SECONDS or 0.0))
    if timeout_seconds <= 0.0:
        return evaluate_pending_child_returns(operator_root, state_root=state_root)
    if not _SCHEDULER_RETURN_EVALUATION_LOCK.acquire(blocking=False):
        return _scheduler_pending_return_evaluation_degraded("scheduler_return_evaluation_already_in_flight")
    if timeout_seconds < 0.05:
        _SCHEDULER_RETURN_EVALUATION_LOCK.release()
        degraded = _scheduler_pending_return_evaluation_degraded("scheduler_return_evaluation_timeout")
        degraded["timeout_seconds"] = timeout_seconds
        degraded["return_evaluation_background_worker_started"] = False
        return degraded
    try:
        message = _run_conveyor_module_json_worker(
            operator_root,
            state_root=state_root,
            command="scheduler-pending-return-evaluation",
            timeout_seconds=timeout_seconds,
        )
        if bool(message.get("worker_timed_out", False)):
            degraded = _scheduler_pending_return_evaluation_degraded("scheduler_return_evaluation_timeout")
            degraded["timeout_seconds"] = timeout_seconds
            degraded["return_evaluation_background_worker_started"] = bool(message.get("worker_started", False))
            degraded["return_evaluation_worker_terminated"] = True
            return degraded
        if bool(message.get("ok", False)):
            return dict(message.get("result", {}) or {})
        degraded = _scheduler_pending_return_evaluation_degraded("scheduler_return_evaluation_failed")
        degraded["error_type"] = str(message.get("error_type", "") or "")
        degraded["error"] = str(message.get("error", "") or "")
        return degraded
    except Exception as exc:  # pragma: no cover - defensive fail-soft path for live control plane.
        degraded = _scheduler_pending_return_evaluation_degraded("scheduler_return_evaluation_failed")
        degraded["error_type"] = type(exc).__name__
        degraded["error"] = str(exc)
        return degraded
    finally:
        _SCHEDULER_RETURN_EVALUATION_LOCK.release()


def scheduler_tick(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    runner: ConveyorChildRunner | None = None,
    phase_policy: str = "full",
) -> dict[str, Any]:
    with _SCHEDULER_TICK_LOCK:
        return _scheduler_tick_unlocked(
            operator_root,
            state_root=state_root,
            runner=runner,
            phase_policy=phase_policy,
        )


def _scheduler_tick_unlocked(
    operator_root: str | Path,
    *,
    state_root: str | Path,
    runner: ConveyorChildRunner | None = None,
    phase_policy: str = "full",
) -> dict[str, Any]:
    phase_results: list[dict[str, Any]] = []
    phase_timeouts: list[str] = []
    normalized_phase_policy = str(phase_policy or "full").strip().lower() or "full"
    bounded_admission = normalized_phase_policy in {"bounded_admission", "admission_only"}

    def run_phase(name: str, fn: Callable[[], Any]) -> Any:
        started = time.perf_counter()
        try:
            result = fn()
            status = "ok"
            if isinstance(result, Mapping) and bool(result.get("evaluation_deferred", False)):
                status = "deferred"
            if isinstance(result, Mapping) and str(result.get("control_plane_degraded_reason", "") or "").endswith("_timeout"):
                phase_timeouts.append(name)
            return result
        except Exception as exc:
            phase_results.append(
                {
                    "phase": name,
                    "ok": False,
                    "status": "failed",
                    "duration_ms": round((time.perf_counter() - started) * 1000, 3),
                    "error_type": type(exc).__name__,
                    "error": str(exc),
                }
            )
            raise
        finally:
            if not phase_results or phase_results[-1].get("phase") != name:
                phase_results.append(
                    {
                        "phase": name,
                        "ok": True,
                        "status": status if "status" in locals() else "ok",
                        "duration_ms": round((time.perf_counter() - started) * 1000, 3),
                    }
                )

    def deferred_phase(name: str, *, reason: str = "bounded_admission_phase_deferred") -> dict[str, Any]:
        phase_results.append(
            {
                "phase": name,
                "ok": True,
                "status": "deferred",
                "duration_ms": 0.0,
                "reason": reason,
            }
        )
        return {
            "ok": True,
            "phase": name,
            "deferred": True,
            "control_plane_response_mode": "bounded_admission",
            "control_plane_degraded_reason": reason,
            "records": [],
        }

    initialize_conveyor_state(operator_root)
    loaded_scheduler = _load_scheduler(operator_root)
    scheduler_adaptation_state = "ok"
    scheduler_adaptation_error_type = ""
    scheduler_adaptation_error = ""
    try:
        scheduler = _adapt_scheduler(operator_root, loaded_scheduler)
    except (OSError, PermissionError) as exc:
        scheduler = dict(loaded_scheduler)
        scheduler_adaptation_state = "degraded"
        scheduler_adaptation_error_type = type(exc).__name__
        scheduler_adaptation_error = str(exc)
        phase_timeouts.append("scheduler_adaptation_failed")
        phase_results.append(
            {
                "phase": "scheduler_adaptation",
                "ok": False,
                "status": "degraded",
                "duration_ms": 0.0,
                "error_type": scheduler_adaptation_error_type,
                "error": scheduler_adaptation_error,
            }
        )
    effective_runner = runner or runner_from_scheduler(scheduler)
    pre_tick_directives = _load_items(_directives_root(operator_root))
    pre_tick_pending_review_ids = {
        str(packet.get("directive_id", "") or "")
        for packet in _load_items(_returns_root(operator_root))
        if str(packet.get("review_state", "") or "") == "pending_operator_review"
        and str(packet.get("directive_id", "") or "")
    }
    pre_tick_spawn_blocked_by_review_ids = {
        str(directive.get("directive_id", "") or "")
        for directive in pre_tick_directives
        if str(directive.get("state", "") or "") == "queued"
        and str(directive.get("directive_id", "") or "") in pre_tick_pending_review_ids
    }
    blocking_reasons: list[str] = []
    if _autonomy_emergency_stop_active(operator_root):
        blocking_reasons.append("emergency_stop")
        stopped = run_phase("emergency_stop_child_stop", lambda: _stop_active_child_runs(operator_root, runner=runner))
        resident_support_candidate_ingestion: dict[str, Any] = {
            "ok": False,
            "reason": "emergency_stop",
            "support_candidate_ingested_count": 0,
            "support_candidate_satisfied_count": 0,
            "support_checkout_refreshed_count": 0,
            "support_tick_deferred_count": 1,
        }
        reconciliation: dict[str, Any] = {
            "ok": True,
            "inspected_child_count": 0,
            "collected_return_count": 0,
            "failed_return_count": 0,
            "records": [],
        }
    else:
        stopped = []
        if bounded_admission:
            resident_support_candidate_ingestion = deferred_phase(
                "resident_support_candidate_ingestion",
                reason="bounded_admission_support_ingestion_deferred",
            )
            resident_support_candidate_ingestion["support_candidate_ingested_count"] = 0
            resident_support_candidate_ingestion["support_candidate_satisfied_count"] = 0
            resident_support_candidate_ingestion["support_checkout_refreshed_count"] = 0
            resident_support_candidate_ingestion["support_tick_deferred_count"] = 1
        else:
            resident_support_candidate_ingestion = run_phase(
                "resident_support_candidate_ingestion",
                lambda: ingest_resident_support_request_candidates(
                    operator_root,
                    state_root=state_root,
                ),
            )
        if bounded_admission:
            reconciliation = deferred_phase("child_reconciliation")
        else:
            reconciliation = run_phase(
                "child_reconciliation",
                lambda: reconcile_child_runs(operator_root, state_root=state_root, runner=runner),
            )
    if bounded_admission:
        kernel_evaluation = deferred_phase("pending_return_evaluation")
        active_support_continuation = deferred_phase("support_continuation")
    else:
        kernel_evaluation = run_phase(
            "pending_return_evaluation",
            lambda: _evaluate_pending_child_returns_for_scheduler(operator_root, state_root=state_root),
        )
        active_support_continuation = run_phase(
            "support_continuation",
            lambda: _attempt_active_resident_support_continuation(
                operator_root,
                state_root=state_root,
            ),
        )
    if bounded_admission:
        active_child_directive_repair = deferred_phase("active_child_directive_repair")
        active_child_directive_repair_count = 0
        stale_active_child_directive_cleanup = deferred_phase("stale_active_child_id_cleanup")
        stale_active_child_directive_cleanup_count = 0
        stale_spawn_reservation_cleanup = deferred_phase("stale_spawn_reservation_cleanup")
        stale_spawn_reservation_cleanup["stale_spawn_reservation_count"] = 0
        stale_spawn_reservation_cleanup["records"] = []
    else:
        active_child_directive_repair_count = run_phase(
            "active_child_directive_repair",
            lambda: _repair_requeued_directives_with_active_children(operator_root),
        )
        stale_active_child_directive_cleanup_count = run_phase(
            "stale_active_child_id_cleanup",
            lambda: _clear_stale_active_child_ids_for_inactive_directives(operator_root),
        )
        stale_spawn_reservation_cleanup = run_phase(
            "stale_spawn_reservation_cleanup",
            lambda: _cleanup_stale_spawn_reservations(
                operator_root,
                runner=runner,
                scheduler=scheduler,
            ),
        )
    if bounded_admission:
        directive_integrity_repair = deferred_phase("directive_integrity_repair")
        task_manager_snapshot_for_repair = load_task_manager_snapshot(operator_root)
        if not task_manager_snapshot_for_repair:
            task_manager_snapshot_for_repair = {
                "schema_name": "TaskManagerSnapshot",
                "schema_version": CONVEYOR_SCHEMA_VERSION,
                "generated_at": _utc_now(),
                "snapshot_refreshed_by": "bounded_admission_cached_snapshot_missing",
                "snapshot_freshness_state": "missing_cached_snapshot",
                "directive_tasks": [],
                "admissible_directives": [],
                "admissible_directive_count": 0,
                "active_lease_count": 0,
                "active_leases": [],
                "grants_execution_authority": False,
            }
        task_manager_repair = deferred_phase("task_manager_repair")
        task_manager_repair["snapshot"] = task_manager_snapshot_for_repair
        task_manager_repair["task_manager_repair_applied_count"] = 0
        task_manager_repair["task_manager_released_stale_lease_count"] = 0
    else:
        directive_integrity_repair = run_phase(
            "directive_integrity_repair",
            lambda: repair_conveyor_directive_integrity(operator_root, runner=effective_runner),
        )
        task_manager_repair = run_phase(
            "task_manager_repair",
            lambda: apply_task_manager_repairs(
                operator_root,
                scheduler=scheduler,
                inspect_containers=True,
                runner=effective_runner,
            ),
        )
    task_manager_snapshot = dict(task_manager_repair.get("snapshot", {}) or {}) or build_task_manager_snapshot(
        operator_root,
        scheduler=scheduler,
        inspect_containers=True,
        runner=effective_runner,
        persist=True,
    )
    task_manager_admissible_count_before_admission = int(
        task_manager_snapshot.get("admissible_directive_count", 0) or 0
    )
    task_manager_cutover = bool(scheduler.get("task_manager_cutover_enabled", False)) or (
        str(scheduler.get("task_manager_mode", "") or "").strip().lower() == "cutover"
    )
    if blocking_reasons:
        return {
            "ok": False,
            "schema_name": "ConveyorSchedulerTick",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "generated_at": _utc_now(),
            "spawned_count": 0,
            "spawned_children": [],
            "suppressed_spawn_count": 0,
            "spawn_suppression_reasons": [],
            "stopped_children": stopped,
            "reconciliation": reconciliation,
            "kernel_evaluation": kernel_evaluation,
            "resident_support_candidate_ingestion": resident_support_candidate_ingestion,
            "support_candidate_ingested_count": int(
                resident_support_candidate_ingestion.get("support_candidate_ingested_count", 0) or 0
            ),
            "support_candidate_satisfied_count": int(
                resident_support_candidate_ingestion.get("support_candidate_satisfied_count", 0) or 0
            ),
            "support_checkout_refreshed_count": int(
                resident_support_candidate_ingestion.get("support_checkout_refreshed_count", 0) or 0
            ),
            "support_tick_deferred_count": int(
                resident_support_candidate_ingestion.get("support_tick_deferred_count", 0) or 0
            ),
            "active_support_continuation": active_support_continuation,
            "active_child_directive_repair_count": active_child_directive_repair_count,
            "stale_active_child_directive_cleanup_count": stale_active_child_directive_cleanup_count,
            "stale_spawn_reservation_cleanup_count": int(
                stale_spawn_reservation_cleanup.get("stale_spawn_reservation_count", 0) or 0
            ),
            "stale_spawn_reservations": list(stale_spawn_reservation_cleanup.get("records", []) or []),
            "directive_integrity_repair": directive_integrity_repair,
            "malformed_return_repaired_count": int(
                directive_integrity_repair.get("malformed_return_repaired_count", 0) or 0
            ),
            "task_manager_mode": str(task_manager_snapshot.get("task_manager_mode", "") or "shadow"),
            "task_manager_cutover_enabled": task_manager_cutover,
            "task_manager_state": task_manager_snapshot,
            "task_manager_active_lease_count": int(task_manager_snapshot.get("active_lease_count", 0) or 0),
            "task_manager_admissible_directive_count": task_manager_admissible_count_before_admission,
            "task_manager_suppressed_duplicate_count": int(
                task_manager_snapshot.get("duplicate_suppression_count", 0) or 0
            ),
            "task_manager_mismatch_count": int(task_manager_snapshot.get("mismatch_count", 0) or 0),
            "task_manager_repair": task_manager_repair,
            "task_manager_repair_applied_count": int(
                task_manager_repair.get("task_manager_repair_applied_count", 0) or 0
            ),
            "task_manager_released_stale_lease_count": int(
                task_manager_repair.get("task_manager_released_stale_lease_count", 0) or 0
            ),
            "scheduler_phase_results": phase_results,
            "scheduler_phase_timeouts": phase_timeouts,
            "scheduler_phase_policy": normalized_phase_policy,
            "blocking_reasons": blocking_reasons,
            "scheduler": scheduler,
        }
    spawned: list[dict[str, Any]] = []
    suppressed: list[dict[str, Any]] = []
    if task_manager_cutover:
        if bounded_admission:
            task_manager_snapshot, task_leases = run_phase(
                "spawn_admission",
                lambda: acquire_task_manager_leases_from_cached_snapshot(
                    operator_root,
                    scheduler=scheduler,
                    limit=task_manager_capacity(scheduler),
                ),
            )
        else:
            task_manager_snapshot, task_leases = run_phase(
                "spawn_admission",
                lambda: acquire_task_manager_leases(
                    operator_root,
                    scheduler=scheduler,
                    limit=task_manager_capacity(scheduler),
                    inspect_containers=True,
                    runner=effective_runner,
                ),
            )
        directive_by_id = {
            str(directive.get("directive_id", "") or ""): directive
            for directive in _load_items(_directives_root(operator_root))
            if str(directive.get("directive_id", "") or "")
        }
        candidate_directives = [
            directive_by_id[str(lease.get("directive_id", "") or "")]
            for lease in task_leases
            if str(lease.get("directive_id", "") or "") in directive_by_id
        ]
        if pre_tick_spawn_blocked_by_review_ids:
            blocked_candidate_ids = {
                str(directive.get("directive_id", "") or "")
                for directive in candidate_directives
                if str(directive.get("directive_id", "") or "") in pre_tick_spawn_blocked_by_review_ids
            }
            if blocked_candidate_ids:
                candidate_directives = [
                    directive
                    for directive in candidate_directives
                    if str(directive.get("directive_id", "") or "") not in blocked_candidate_ids
                ]
                for directive_id in sorted(blocked_candidate_ids):
                    release_task_manager_lease(
                        operator_root,
                        directive_id=directive_id,
                        reason="pre_tick_pending_review_return_blocked_spawn",
                    )
                    suppressed.append(
                        {
                            "spawn_suppressed": True,
                            "directive_id": directive_id,
                            "reason": "pre_tick_pending_review_return_blocked_spawn",
                        }
                    )
    else:
        active_count = len(_active_children(operator_root))
        target = int(scheduler.get("target_concurrency", 1) or 1)
        capacity = max(0, target - active_count)
        candidate_directives = _queued_directives(operator_root)[:capacity]
        if pre_tick_spawn_blocked_by_review_ids:
            blocked_candidate_ids = {
                str(directive.get("directive_id", "") or "")
                for directive in candidate_directives
                if str(directive.get("directive_id", "") or "") in pre_tick_spawn_blocked_by_review_ids
            }
            candidate_directives = [
                directive
                for directive in candidate_directives
                if str(directive.get("directive_id", "") or "") not in blocked_candidate_ids
            ]
            for directive_id in sorted(blocked_candidate_ids):
                suppressed.append(
                    {
                        "spawn_suppressed": True,
                        "directive_id": directive_id,
                        "reason": "pre_tick_pending_review_return_blocked_spawn",
                    }
                )
    for directive in candidate_directives:
        spawn_result = _spawn_child_for_directive(
            operator_root,
            state_root=state_root,
            directive=directive,
            runner=runner,
            scheduler=scheduler,
        )
        if bool(spawn_result.get("spawn_suppressed", False)):
            suppressed.append(spawn_result)
            continue
        spawned.append(spawn_result)
    if bounded_admission and task_manager_cutover:
        cached_snapshot = load_task_manager_snapshot(operator_root)
        if cached_snapshot:
            now = _utc_now()
            spawned_by_directive = {
                str(child.get("directive_id", "") or ""): str(child.get("child_run_id", "") or "")
                for child in spawned
                if str(child.get("directive_id", "") or "") and str(child.get("child_run_id", "") or "")
            }
            suppressed_directive_ids = {
                str(item.get("directive_id", "") or "")
                for item in suppressed
                if str(item.get("directive_id", "") or "")
            }
            directive_tasks: list[dict[str, Any]] = []
            for task in list(cached_snapshot.get("directive_tasks", []) or []):
                if not isinstance(task, Mapping):
                    continue
                row = dict(task)
                directive_id = str(row.get("directive_id", "") or "")
                if directive_id in spawned_by_directive:
                    row["task_state"] = "running"
                    row["lease_state"] = "running"
                    row["active_child_run_id"] = spawned_by_directive[directive_id]
                    row["active_child_run_ids"] = [spawned_by_directive[directive_id]]
                    row["updated_at"] = now
                elif directive_id in suppressed_directive_ids and str(row.get("task_state", "") or "") == "leased":
                    row["task_state"] = "eligible"
                    row["lease_state"] = "released"
                    row["updated_at"] = now
                directive_tasks.append(row)
            cached_snapshot["directive_tasks"] = directive_tasks
            cached_snapshot["generated_at"] = now
            cached_snapshot["snapshot_refreshed_by"] = "bounded_admission_spawn_result"
            cached_snapshot["snapshot_freshness_state"] = "cached_bounded_admission"
            cached_snapshot["admissible_directives"] = [
                dict(task)
                for task in directive_tasks
                if str(task.get("task_state", "") or "") == "eligible"
            ]
            cached_snapshot["admissible_directive_count"] = len(cached_snapshot["admissible_directives"])
            cached_snapshot["active_lease_count"] = len(
                [
                    task
                    for task in directive_tasks
                    if str(task.get("task_state", "") or "") in {"leased", "running"}
                ]
            )
            cached_snapshot["active_child_count"] = len(
                [
                    task
                    for task in directive_tasks
                    if str(task.get("task_state", "") or "") in {"running", "leased"}
                    and str(task.get("active_child_run_id", "") or "").strip()
                ]
            )
            _write_json(Path(operator_root) / "conveyor" / "task_manager" / "snapshot_latest.json", cached_snapshot)
            persist_bounded_status_snapshot(
                operator_root,
                task_manager_snapshot=cached_snapshot,
                refreshed_by="bounded_admission_spawn_result",
            )
    if bounded_admission:
        refreshed_snapshot = load_task_manager_snapshot(operator_root)
        if refreshed_snapshot:
            task_manager_snapshot = refreshed_snapshot
            persist_bounded_status_snapshot(
                operator_root,
                task_manager_snapshot=task_manager_snapshot,
                refreshed_by="bounded_admission_spawn_result",
            )
    else:
        task_manager_snapshot = build_task_manager_snapshot(
            operator_root,
            scheduler=scheduler,
            inspect_containers=True,
            runner=effective_runner,
            persist=True,
        )
    return {
        "ok": True,
        "schema_name": "ConveyorSchedulerTick",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "spawned_count": len(spawned),
        "spawned_children": spawned,
        "suppressed_spawn_count": len(suppressed),
        "spawn_suppression_reasons": [
            str(item.get("spawn_suppression_reason", "") or "")
            for item in suppressed
            if str(item.get("spawn_suppression_reason", "") or "")
        ],
        "spawn_suppressions": suppressed,
        "stopped_children": [],
        "reconciliation": reconciliation,
        "kernel_evaluation": kernel_evaluation,
        "resident_support_candidate_ingestion": resident_support_candidate_ingestion,
        "support_candidate_ingested_count": int(
            resident_support_candidate_ingestion.get("support_candidate_ingested_count", 0) or 0
        ),
        "support_candidate_satisfied_count": int(
            resident_support_candidate_ingestion.get("support_candidate_satisfied_count", 0) or 0
        ),
        "support_checkout_refreshed_count": int(
            resident_support_candidate_ingestion.get("support_checkout_refreshed_count", 0) or 0
        ),
        "support_tick_deferred_count": int(
            resident_support_candidate_ingestion.get("support_tick_deferred_count", 0) or 0
        ),
        "active_support_continuation": active_support_continuation,
        "active_child_directive_repair_count": active_child_directive_repair_count,
        "stale_active_child_directive_cleanup_count": stale_active_child_directive_cleanup_count,
        "stale_spawn_reservation_cleanup_count": int(
            stale_spawn_reservation_cleanup.get("stale_spawn_reservation_count", 0) or 0
        ),
        "stale_spawn_reservations": list(stale_spawn_reservation_cleanup.get("records", []) or []),
        "directive_integrity_repair": directive_integrity_repair,
        "malformed_return_repaired_count": int(
            directive_integrity_repair.get("malformed_return_repaired_count", 0) or 0
        ),
        "task_manager_mode": str(task_manager_snapshot.get("task_manager_mode", "") or "shadow"),
        "task_manager_cutover_enabled": task_manager_cutover,
        "task_manager_state": task_manager_snapshot,
        "task_manager_active_lease_count": int(task_manager_snapshot.get("active_lease_count", 0) or 0),
        "task_manager_admissible_directive_count": task_manager_admissible_count_before_admission,
        "task_manager_suppressed_duplicate_count": int(
            task_manager_snapshot.get("duplicate_suppression_count", 0) or 0
        ),
        "task_manager_mismatch_count": int(task_manager_snapshot.get("mismatch_count", 0) or 0),
        "task_manager_repair": task_manager_repair,
        "task_manager_repair_applied_count": int(
            task_manager_repair.get("task_manager_repair_applied_count", 0) or 0
        ),
        "task_manager_released_stale_lease_count": int(
            task_manager_repair.get("task_manager_released_stale_lease_count", 0) or 0
        ),
        "scheduler_phase_results": phase_results,
        "scheduler_phase_timeouts": phase_timeouts,
        "scheduler_phase_policy": normalized_phase_policy,
        "scheduler_adaptation_state": scheduler_adaptation_state,
        "scheduler_adaptation_error_type": scheduler_adaptation_error_type,
        "scheduler_adaptation_error": scheduler_adaptation_error,
        "blocking_reasons": [],
        "scheduler": _load_scheduler(operator_root),
    }


def _stop_active_child_runs(
    operator_root: str | Path,
    *,
    runner: ConveyorChildRunner | None = None,
) -> list[dict[str, Any]]:
    scheduler = _load_scheduler(operator_root)
    effective_runner = runner or runner_from_scheduler(scheduler)
    stopped: list[dict[str, Any]] = []
    now = _utc_now()
    for child in _active_children(operator_root):
        child_id = str(child.get("child_run_id", "") or "")
        if not child_id:
            continue
        stop_result = effective_runner.stop_child_container(child)
        updated = dict(child)
        updated["state"] = "stopped" if bool(stop_result.get("ok", False)) else "blocked"
        updated["stop_requested"] = True
        updated["stop_result"] = dict(stop_result)
        updated["updated_at"] = now
        _write_json(_child_path(operator_root, child_id), updated)
        directive_id = str(updated.get("directive_id", "") or "")
        if directive_id:
            directive = _read_json(_directive_path(operator_root, directive_id))
            if directive:
                directive["state"] = "blocked"
                directive["updated_at"] = now
                _write_json(_directive_path(operator_root, directive_id), directive)
        _append_ledger(operator_root, "child_events", {"event": "emergency_stop_child", **updated})
        stopped.append(updated)
    return stopped


def cleanup_terminal_child_containers(
    operator_root: str | Path,
    *,
    runner: ConveyorChildRunner | None = None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    scheduler = _load_scheduler(operator_root)
    effective_runner = runner or runner_from_scheduler(scheduler)
    cleaned: list[dict[str, Any]] = []
    failed: list[dict[str, Any]] = []
    now = _utc_now()
    for child in _load_items(_children_root(operator_root)):
        child_id = str(child.get("child_run_id", "") or "")
        if not child_id:
            continue
        if str(child.get("state", "") or "") not in TERMINAL_CHILD_STATES:
            continue
        if str(child.get("container_cleanup_state", "") or "") in {"removed", "already_removed"}:
            continue
        if not str(child.get("container_id", "") or child.get("container_name", "")).strip():
            continue
        cleanup_result = effective_runner.remove_child_container(child)
        updated = dict(child)
        updated["container_cleanup_requested"] = True
        updated["container_cleanup_result"] = dict(cleanup_result)
        updated["container_cleanup_state"] = str(cleanup_result.get("state", "") or "remove_failed")
        updated["container_cleaned_at"] = now if bool(cleanup_result.get("ok", False)) else ""
        updated["updated_at"] = now
        _write_json(_child_path(operator_root, child_id), updated)
        event = "terminal_child_container_cleaned" if bool(cleanup_result.get("ok", False)) else "terminal_child_container_cleanup_failed"
        _append_ledger(operator_root, "child_events", {"event": event, **updated})
        if bool(cleanup_result.get("ok", False)):
            cleaned.append(updated)
        else:
            failed.append(updated)
    return {
        "ok": not failed,
        "schema_name": "ConveyorTerminalChildContainerCleanup",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "cleaned_container_count": len(cleaned),
        "failed_cleanup_count": len(failed),
        "cleaned_children": cleaned,
        "failed_children": failed,
    }


def _campaign_manifest_rows(operator_root: str | Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    root = _campaigns_root(operator_root)
    if not root.exists():
        return rows
    for manifest_path in sorted(root.glob("*/latest_manifest.json")):
        payload = _read_json(manifest_path)
        if payload:
            rows.append(payload)
    return rows


def _growth_receipt_health_summary(operator_root: str | Path) -> dict[str, Any]:
    rows = _read_growth_receipt_ledger(operator_root, limit=200)
    folded: dict[str, dict[str, Any]] = {}
    for row in rows:
        receipt_id = str(row.get("receipt_id", "") or row.get("dedupe_signature", "") or "")
        if not receipt_id:
            receipt_id = _record_id("growth-receipt-folded", row)
        folded[receipt_id] = dict(row)
    receipts = list(folded.values())[-50:]
    verified = [
        row
        for row in receipts
        if str(row.get("receipt_state", "") or "") in {
            "verified_delivery",
            "verified_canonical_effect",
            "later_consumed",
        }
    ]
    later_consumed = [
        row
        for row in receipts
        if bool(dict(row.get("later_consumption", {}) or {}).get("later_consumed", False))
        or str(row.get("receipt_state", "") or "") == "later_consumed"
    ]
    blockers: list[str] = []
    if receipts and len(verified) < len(receipts):
        blockers.append("receipt_delivery_not_verified")
    if receipts and not later_consumed:
        blockers.append("later_consumption_not_observed")
    return {
        "recent_growth_receipt_count": len(receipts),
        "verified_growth_receipt_count": len(verified),
        "later_consumed_growth_receipt_count": len(later_consumed),
        "latest_growth_receipt_state": str(receipts[-1].get("receipt_state", "") or "") if receipts else "",
        "strict_growth_blockers": blockers,
    }


def conveyor_lightweight_summary(operator_root: str | Path) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    scheduler = _load_scheduler(operator_root)
    directives = _load_items(_directives_root(operator_root))
    children = _load_items(_children_root(operator_root))
    returns = _load_items(_returns_root(operator_root))
    support_requests = _load_items(_support_requests_root(operator_root))
    active_children = []
    for child in children:
        if str(child.get("state", "") or "") in TERMINAL_CHILD_STATES:
            continue
        enriched = dict(child)
        latest_progress = _latest_child_progress(enriched)
        if latest_progress:
            enriched["latest_progress"] = latest_progress
            enriched["progress_state"] = str(latest_progress.get("progress_state", "") or "")
            enriched["latest_progress_at"] = str(latest_progress.get("generated_at", "") or "")
        enriched.update(_child_compute_status_fields(enriched, latest_progress))
        active_children.append(enriched)
    pending_returns = [
        packet for packet in returns if str(packet.get("review_state", "") or "") == "pending_operator_review"
    ]
    directive_ids = {
        str(directive.get("directive_id", "") or "")
        for directive in directives
        if str(directive.get("directive_id", "") or "")
    }
    stale_return_directive_count = len(
        [
            packet
            for packet in returns
            if str(packet.get("directive_id", "") or "")
            and str(packet.get("directive_id", "") or "") not in directive_ids
        ]
    )
    latest_return_at = ""
    clarification_needed_count = 0
    for packet in pending_returns:
        generated = str(packet.get("generated_at", "") or "")
        if generated > latest_return_at:
            latest_return_at = generated
        evaluation = dict(packet.get("kernel_evaluation", {}) or {})
        if str(evaluation.get("decision", "") or "") == "operator_clarification_required":
            clarification_needed_count += 1
        elif list(packet.get("requested_operator_clarifications", []) or []):
            clarification_needed_count += 1
    pending_support = [
        support
        for support in support_requests
        if str(support.get("support_state", "") or "") == "pending_operator_review"
    ]
    active_by_directive = {str(child.get("directive_id", "") or ""): child for child in active_children}
    pending_returns_by_directive: dict[str, int] = {}
    for packet in pending_returns:
        directive_id = str(packet.get("directive_id", "") or "")
        pending_returns_by_directive[directive_id] = pending_returns_by_directive.get(directive_id, 0) + 1
    pending_support_by_directive: dict[str, int] = {}
    for support in pending_support:
        directive_id = str(support.get("directive_id", "") or "")
        pending_support_by_directive[directive_id] = pending_support_by_directive.get(directive_id, 0) + 1
    refreshed_campaigns: list[dict[str, Any]] = []
    for directive in directives:
        directive_id = str(directive.get("directive_id", "") or "")
        if not directive_id:
            continue
        manifest_path = _campaign_manifest_path(operator_root, directive_id)
        if not manifest_path.exists():
            continue
        refreshed_campaigns.append(
            _write_campaign_manifest(
                operator_root,
                directive_id,
                active_child=active_by_directive.get(directive_id, {}),
                pending_return_count=pending_returns_by_directive.get(directive_id, 0),
                pending_support_count=pending_support_by_directive.get(directive_id, 0),
            )
        )
    if not refreshed_campaigns:
        refreshed_campaigns = _campaign_manifest_rows(operator_root)
    campaign_by_directive = {
        str(campaign.get("directive_id", "") or ""): dict(campaign)
        for campaign in refreshed_campaigns
        if str(campaign.get("directive_id", "") or "")
    }
    target_drift_records = [
        _resident_child_target_drift_record(
            child,
            campaign_by_directive.get(str(child.get("directive_id", "") or ""), {}),
        )
        for child in active_children
        if str(child.get("directive_id", "") or "") in campaign_by_directive
    ]
    target_drift_records = [record for record in target_drift_records if record["target_drift_detected"]]
    schema_followup_records = [
        _schema_resonance_followup_record(
            child,
            campaign_by_directive.get(str(child.get("directive_id", "") or ""), {}),
        )
        for child in active_children
        if str(child.get("directive_id", "") or "") in campaign_by_directive
    ]
    schema_followup_records = [
        record for record in schema_followup_records if record["schema_resonance_followup_required"]
    ]
    schema_followup_top_level_missing_count = len(
        [
            child
            for child in active_children
            if bool(child.get("schema_resonance_followup_required", False))
            and list(child.get("schema_followup_missing_top_level_fields", []) or child.get("missing_top_level_fields", []) or [])
        ]
    )
    schema_followup_contract_satisfied_count = len(
        [
            child
            for child in active_children
            if bool(child.get("schema_resonance_followup_required", False))
            and bool(child.get("schema_followup_contract_satisfied", False))
        ]
    )
    schema_followup_stall_count = len(
        [
            child
            for child in active_children
            if str(child.get("resident_worker_state", "") or "") == "schema_resonance_followup_stalled"
            or int(child.get("schema_followup_stall_count", 0) or 0) >= 2
        ]
    )
    persistent_schema_contract_missing_records = [
        {
            "child_run_id": str(child.get("child_run_id", "") or ""),
            "directive_id": str(child.get("directive_id", "") or ""),
            "target_artifact": str(
                dict(child.get("draft_delta_quality", {}) or {}).get(
                    "target_artifact",
                    child.get("latest_work_order_target_artifact", ""),
                )
                or ""
            ),
            "missing_top_level_fields": list(
                dict(child.get("draft_delta_quality", {}) or {}).get(
                    "persistent_schema_contract_missing_top_level_fields",
                    [],
                )
                or []
            ),
        }
        for child in active_children
        if bool(dict(child.get("draft_delta_quality", {}) or {}).get("persistent_schema_contract_required", False))
        and list(
            dict(child.get("draft_delta_quality", {}) or {}).get(
                "persistent_schema_contract_missing_top_level_fields",
                [],
            )
            or []
        )
    ]
    stale_missing_container_records = [
        {
            "child_run_id": str(child.get("child_run_id", "") or ""),
            "directive_id": str(child.get("directive_id", "") or ""),
            "blockers": list(child.get("missing_container_recovery_blockers", []) or []),
            "last_inspect_state": str(child.get("last_inspect_state", "") or ""),
            "container_missing_after_return_request": bool(
                child.get("container_missing_after_return_request", False)
            ),
        }
        for child in active_children
        if bool(child.get("missing_container_recovery_blocked", False))
    ]
    hardware_build_packet_records = [
        {
            "directive_id": str(campaign.get("directive_id", "") or ""),
            "readiness_state": str(campaign.get("readiness_state", "") or ""),
            "hardware_build_packet_ready": bool(
                dict(campaign.get("hardware_build_packet_assessment", {}) or {}).get(
                    "hardware_build_packet_ready",
                    False,
                )
            ),
            "failed_gates": list(
                dict(campaign.get("hardware_build_packet_assessment", {}) or {}).get("failed_gates", []) or []
            ),
            "next_unresolved_artifact": str(
                dict(campaign.get("hardware_build_packet_assessment", {}) or {}).get(
                    "next_unresolved_artifact",
                    "",
                )
                or ""
            ),
        }
        for campaign in refreshed_campaigns
        if bool(dict(campaign.get("hardware_build_packet_assessment", {}) or {}).get("required", False))
    ]
    return_campaign_hydration_mismatch_records: list[dict[str, Any]] = []
    for packet in pending_returns:
        directive_id = str(packet.get("directive_id", "") or "")
        campaign = campaign_by_directive.get(directive_id, {})
        if not campaign:
            continue
        evaluation = dict(packet.get("kernel_evaluation", {}) or {})
        missing_artifacts = list(evaluation.get("missing_artifacts", []) or packet.get("missing_artifacts", []) or [])
        try:
            artifact_presence = float(campaign.get("artifact_presence_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            artifact_presence = 0.0
        readiness_state = str(campaign.get("readiness_state", "") or campaign.get("status", "") or "")
        prototype_candidate = bool(
            artifact_presence >= 1.0
            or readiness_state in {"prototype_candidate_review", "prototype_ready_review", "build_ready_review"}
        )
        if missing_artifacts and prototype_candidate:
            return_campaign_hydration_mismatch_records.append(
                {
                    "return_packet_id": str(packet.get("return_packet_id", "") or ""),
                    "directive_id": directive_id,
                    "missing_artifacts": [str(item) for item in missing_artifacts],
                    "campaign_readiness_state": readiness_state,
                    "artifact_presence_score": artifact_presence,
                }
            )
    growth_receipt_health = _growth_receipt_health_summary(operator_root)
    task_manager_snapshot = build_task_manager_snapshot(
        operator_root,
        scheduler=scheduler,
        persist=False,
    )
    return {
        "ok": True,
        "schema_name": "ConveyorLightweightSummary",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "scheduler": scheduler,
        "directive_counts_by_state": _count_by_state(directives),
        "child_counts_by_state": _count_by_state(children),
        "return_counts_by_review_state": _count_by_state(returns, field="review_state"),
        "support_request_counts_by_state": _count_by_state(support_requests, field="support_state"),
        "stale_return_directive_count": stale_return_directive_count,
        "active_child_count": len(active_children),
        "pending_return_count": len(pending_returns),
        "pending_support_request_count": len(pending_support),
        "latest_return_at": latest_return_at,
        "clarification_needed_count": clarification_needed_count,
        "campaign_count": len(refreshed_campaigns),
        "campaigns": refreshed_campaigns,
        "target_drift_detected": bool(target_drift_records),
        "target_drift_detected_count": len(target_drift_records),
        "target_drift_repair_required": bool(target_drift_records),
        "target_drift_records": target_drift_records,
        "schema_resonance_followup_required": bool(schema_followup_records),
        "schema_resonance_followup_required_count": len(schema_followup_records),
        "schema_resonance_followup_records": schema_followup_records,
        "schema_followup_top_level_missing_count": schema_followup_top_level_missing_count,
        "schema_followup_contract_satisfied_count": schema_followup_contract_satisfied_count,
        "schema_followup_stall_count": schema_followup_stall_count,
        "persistent_schema_contract_missing_count": len(persistent_schema_contract_missing_records),
        "persistent_schema_contract_missing_records": persistent_schema_contract_missing_records,
        "stale_missing_container_child_count": len(stale_missing_container_records),
        "stale_missing_container_children": stale_missing_container_records,
        "hardware_build_packet_required_count": len(hardware_build_packet_records),
        "hardware_build_packet_ready_count": len(
            [item for item in hardware_build_packet_records if item["hardware_build_packet_ready"]]
        ),
        "hardware_build_packet_incomplete_count": len(
            [item for item in hardware_build_packet_records if not item["hardware_build_packet_ready"]]
        ),
        "hardware_build_packet_records": hardware_build_packet_records,
        "return_campaign_hydration_mismatch_count": len(return_campaign_hydration_mismatch_records),
        "return_campaign_hydration_mismatch_records": return_campaign_hydration_mismatch_records,
        "growth_receipt_health": growth_receipt_health,
        "recent_growth_receipt_count": int(growth_receipt_health.get("recent_growth_receipt_count", 0) or 0),
        "verified_growth_receipt_count": int(growth_receipt_health.get("verified_growth_receipt_count", 0) or 0),
        "later_consumed_growth_receipt_count": int(
            growth_receipt_health.get("later_consumed_growth_receipt_count", 0) or 0
        ),
        "task_manager_mode": str(task_manager_snapshot.get("task_manager_mode", "") or "shadow"),
        "task_manager_state": task_manager_snapshot,
        "task_manager_active_lease_count": int(task_manager_snapshot.get("active_lease_count", 0) or 0),
        "task_manager_admissible_directive_count": int(
            task_manager_snapshot.get("admissible_directive_count", 0) or 0
        ),
        "task_manager_suppressed_duplicate_count": int(
            task_manager_snapshot.get("duplicate_suppression_count", 0) or 0
        ),
        "task_manager_mismatch_count": int(task_manager_snapshot.get("mismatch_count", 0) or 0),
        "active_children": [
            {
                "child_run_id": str(child.get("child_run_id", "") or ""),
                "directive_id": str(child.get("directive_id", "") or ""),
                "state": str(child.get("state", "") or ""),
                "network_policy": str(child.get("network_policy", "") or ""),
                "latest_work_order_target_artifact": str(
                    child.get("latest_work_order_target_artifact", "")
                    or child.get("latest_target_artifact", "")
                    or ""
                ),
                "latest_progress_at": str(child.get("latest_progress_at", "") or ""),
                "latest_quality_target": str(child.get("latest_quality_target", "") or ""),
                "manifest_next_unresolved_gate_artifact": _manifest_next_unresolved_gate_artifact(
                    campaign_by_directive.get(str(child.get("directive_id", "") or ""), {})
                ),
                "target_drift_detected": _resident_child_target_drift_record(
                    child,
                    campaign_by_directive.get(str(child.get("directive_id", "") or ""), {}),
                )["target_drift_detected"],
                "schema_resonance_followup_required": _schema_resonance_followup_record(
                    child,
                    campaign_by_directive.get(str(child.get("directive_id", "") or ""), {}),
                )["schema_resonance_followup_required"],
                "schema_resonance_score": _schema_resonance_followup_record(
                    child,
                    campaign_by_directive.get(str(child.get("directive_id", "") or ""), {}),
                )["schema_resonance_score"],
                "missing_top_level_fields": _schema_resonance_followup_record(
                    child,
                    campaign_by_directive.get(str(child.get("directive_id", "") or ""), {}),
                )["missing_top_level_fields"],
                "schema_followup_top_level_fields_present": bool(
                    child.get("schema_followup_top_level_fields_present", False)
                ),
                "schema_followup_contract_satisfied": bool(
                    child.get("schema_followup_contract_satisfied", False)
                ),
                "schema_followup_missing_top_level_fields": list(
                    child.get("schema_followup_missing_top_level_fields", []) or []
                ),
                "persistent_schema_contract_required": bool(
                    dict(child.get("draft_delta_quality", {}) or {}).get(
                        "persistent_schema_contract_required",
                        child.get("persistent_schema_contract_required", False),
                    )
                ),
                "persistent_schema_contract_missing_top_level_fields": list(
                    dict(child.get("draft_delta_quality", {}) or {}).get(
                        "persistent_schema_contract_missing_top_level_fields",
                        [],
                    )
                    or []
                ),
                "schema_followup_stall_count": int(child.get("schema_followup_stall_count", 0) or 0),
                "last_quality_promotion_at": str(child.get("last_quality_promotion_at", "") or ""),
                "quality_no_progress_count": max(0, int(child.get("quality_no_progress_count", 0) or 0)),
                "productive_quiescence_eligible": bool(child.get("productive_quiescence_eligible", False)),
                "return_requested_after_clean_delta": bool(child.get("return_requested_after_clean_delta", False)),
                "missing_container_recovery_blocked": bool(child.get("missing_container_recovery_blocked", False)),
                "missing_container_recovery_blockers": list(
                    child.get("missing_container_recovery_blockers", []) or []
                ),
                "container_missing_after_return_request": bool(
                    child.get("container_missing_after_return_request", False)
                ),
                "followup_completion_reason": str(child.get("followup_completion_reason", "") or ""),
                "resident_work_order_duplicate_suppressed_count": int(
                    child.get("resident_work_order_duplicate_suppressed_count", 0) or 0
                ),
                **_child_compute_status_fields(child),
                "inbox_compaction_summary": dict(child.get("inbox_compaction_summary", {}) or {}),
                "latest_quality_retarget_reason": str(child.get("latest_quality_retarget_reason", "") or ""),
                "weakest_failed_artifact": str(
                    campaign_by_directive.get(str(child.get("directive_id", "") or ""), {}).get("weakest_failed_artifact", "")
                    or ""
                ),
            }
            for child in active_children
        ],
    }


def _terminal_prototype_ready_review_packet(packet: Mapping[str, Any]) -> bool:
    if str(packet.get("review_state", "") or "") != "pending_operator_review":
        return False
    evaluation = dict(packet.get("kernel_evaluation", {}) or {})
    if str(evaluation.get("decision", "") or "") != "operator_review_ready":
        return False
    if not bool(evaluation.get("prototype_ready_stop_condition", False)):
        return False
    if list(evaluation.get("missing_artifacts", []) or []) or list(evaluation.get("missing_evidence", []) or []):
        return False
    if list(evaluation.get("auto_reengagement_blockers", []) or []):
        return False
    if bool(evaluation.get("auto_reengagement_eligible", False)):
        return False
    if list(packet.get("requested_operator_clarifications", []) or []):
        return False
    if bool(packet.get("support_required_before_continue", False)):
        return False
    if str(packet.get("support_blocker_state", "") or "") == "pending_operator_review":
        return False
    return bool(dict(evaluation.get("campaign_state", {}) or {}).get("prototype_ready", False))


def conveyor_pending_return_evaluation_required(operator_root: str | Path) -> bool:
    initialize_conveyor_state(operator_root)
    pending_support = [
        item
        for item in _load_items(_support_requests_root(operator_root))
        if str(item.get("support_state", "") or "") == "pending_operator_review"
    ]
    if pending_support:
        return True
    pending_returns = [
        item
        for item in _load_items(_returns_root(operator_root))
        if str(item.get("review_state", "") or "") == "pending_operator_review"
    ]
    if not pending_returns:
        return False
    return not all(_terminal_prototype_ready_review_packet(packet) for packet in pending_returns)


def _return_packet_malformed_non_reviewable(packet: Mapping[str, Any]) -> bool:
    if str(packet.get("review_state", "") or "") != "pending_operator_review":
        return False
    risks = {str(item) for item in list(packet.get("risks", []) or [])}
    summary = " ".join(
        str(packet.get(field, "") or "")
        for field in (
            "outcome_summary",
            "summary",
            "title",
            "headline",
            "operator_note",
        )
    ).lower()
    recovery_signature = bool(
        "missing_child_return_packet" in risks
        or bool(packet.get("return_packet_recovered_by_parent", False))
        or bool(packet.get("recovered_from_progress_evidence", False))
        or "container disappeared" in summary
        or "without a valid return packet" in summary
    )
    if not recovery_signature:
        return False
    artifact_fields = (
        "artifacts",
        "returned_artifacts",
        "artifact_paths",
        "attached_artifacts",
        "recovered_workspace_artifacts",
    )
    has_artifacts_or_evidence = any(list(packet.get(field, []) or []) for field in artifact_fields)
    has_evaluation = bool(packet.get("kernel_evaluation")) or bool(packet.get("hardware_build_packet_assessment"))
    has_readiness = any(
        key in packet
        for key in (
            "hardware_build_packet_ready",
            "hardware_build_packet_ready_candidate",
            "technical_depth_contract_passed",
            "operator_feedback_obligation_passed",
        )
    )
    return not has_artifacts_or_evidence and not has_evaluation and not has_readiness


def assess_conveyor_directive_integrity(operator_root: str | Path) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    scheduler = _load_scheduler(operator_root)
    directives = _load_items(_directives_root(operator_root))
    children = _load_items(_children_root(operator_root))
    returns = _load_items(_returns_root(operator_root))
    active_children_by_directive: dict[str, list[str]] = {}
    for child in children:
        if str(child.get("state", "") or "") in TERMINAL_CHILD_STATES:
            continue
        directive_id = str(child.get("directive_id", "") or "")
        child_id = str(child.get("child_run_id", "") or "")
        if directive_id and child_id:
            active_children_by_directive.setdefault(directive_id, []).append(child_id)
    malformed_return_ids: list[str] = []
    stale_pending_return_ids: list[str] = []
    directive_by_id = {
        str(directive.get("directive_id", "") or ""): directive
        for directive in directives
        if str(directive.get("directive_id", "") or "")
    }
    for packet in returns:
        if str(packet.get("review_state", "") or "") != "pending_operator_review":
            continue
        packet_id = str(packet.get("return_packet_id", "") or "")
        if _return_packet_malformed_non_reviewable(packet):
            malformed_return_ids.append(packet_id)
        directive_id = str(packet.get("directive_id", "") or "")
        directive = directive_by_id.get(directive_id, {})
        if directive and str(directive.get("state", "") or "") != "returned_for_review":
            stale_pending_return_ids.append(packet_id)
    duplicate_directive_child_ids = {
        directive_id: child_ids
        for directive_id, child_ids in active_children_by_directive.items()
        if len(child_ids) > 1
    }
    stale_active_child_ids_by_directive: dict[str, list[str]] = {}
    for directive_id, child_ids in active_children_by_directive.items():
        directive = directive_by_id.get(directive_id, {})
        if not directive:
            continue
        if str(directive.get("state", "") or "") in {"queued", "requeued", "returned_for_review", "blocked_for_support"}:
            stale_active_child_ids_by_directive[directive_id] = list(child_ids)
    task_manager_snapshot = build_task_manager_snapshot(operator_root, persist=False)
    stale_spawn_lock_ids: list[str] = []
    spawn_root = _spawn_locks_root(operator_root)
    if spawn_root.exists():
        try:
            for lock_path in sorted(spawn_root.glob("*.lock")):
                owner = _read_json(lock_path / "owner.json")
                stamp = _parse_utc_time(
                    str(owner.get("created_at", "") or owner.get("updated_at", "") or "")
                )
                if stamp is None or (
                    datetime.now(timezone.utc) - stamp
                ).total_seconds() >= SPAWN_RESERVATION_STALE_SECONDS:
                    stale_spawn_lock_ids.append(lock_path.stem)
        except OSError:
            stale_spawn_lock_ids = []
    return {
        "schema_name": "ConveyorDirectiveIntegrityAssessment",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "directive_count": len(directives),
        "active_children_by_directive": active_children_by_directive,
        "duplicate_directive_child_ids": duplicate_directive_child_ids,
        "stale_active_child_ids_by_directive": stale_active_child_ids_by_directive,
        "malformed_pending_return_ids": [item for item in malformed_return_ids if item],
        "stale_pending_return_ids": [item for item in stale_pending_return_ids if item],
        "stale_spawn_lock_ids": stale_spawn_lock_ids,
        "task_manager_stale_lease_count": int(
            task_manager_snapshot.get("stale_lease_count", 0) or 0
        ),
        "task_manager_stale_leases": list(task_manager_snapshot.get("stale_leases", []) or []),
        "repair_needed": bool(
            malformed_return_ids
            or stale_pending_return_ids
            or duplicate_directive_child_ids
            or stale_active_child_ids_by_directive
            or stale_spawn_lock_ids
            or int(task_manager_snapshot.get("stale_lease_count", 0) or 0) > 0
        ),
        "scheduler": scheduler,
        "grants_execution_authority": False,
    }


def repair_conveyor_directive_integrity(
    operator_root: str | Path,
    *,
    runner: ConveyorChildRunner | None = None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    assessment = assess_conveyor_directive_integrity(operator_root)
    now = _utc_now()
    malformed_repaired: list[str] = []
    stale_repaired: list[str] = []
    plateau_repaired: list[str] = []
    plateau_directive_ids: set[str] = set()
    spawn_locks_repaired: list[str] = []
    child_stops: list[dict[str, Any]] = []
    live_child_preserved: list[dict[str, Any]] = []
    active_children_for_preservation: dict[str, list[dict[str, Any]]] = {}
    for child in _active_children(operator_root):
        directive_id = str(child.get("directive_id", "") or "").strip()
        child_id = str(child.get("child_run_id", "") or "").strip()
        if directive_id and child_id:
            active_children_for_preservation.setdefault(directive_id, []).append(dict(child))
    for packet in _load_items(_returns_root(operator_root)):
        return_packet_id = str(packet.get("return_packet_id", "") or "")
        if not return_packet_id:
            continue
        if str(packet.get("review_state", "") or "") != "pending_operator_review":
            continue
        if not str(packet.get("plateau_hard_stop_idempotency_key", "") or "").strip():
            continue
        if str(packet.get("plateau_requeue_reason", "") or "") != "second_no_delta_window_after_depth_support":
            continue
        packet["review_state"] = "requeued"
        packet["decision"] = "requeued"
        packet["return_repair_state"] = "requeued_by_directive_integrity_repair"
        packet["return_repair_reason"] = "non_reviewable_plateau_hard_stop_return"
        packet["reviewed_at"] = str(packet.get("reviewed_at", "") or now)
        packet["updated_at"] = now
        _write_json(_return_path(operator_root, return_packet_id), packet)
        _append_ledger(
            operator_root,
            "return_decisions",
            {
                "schema_name": "ConveyorReturnDecision",
                "schema_version": CONVEYOR_SCHEMA_VERSION,
                "return_packet_id": return_packet_id,
                "directive_id": str(packet.get("directive_id", "") or ""),
                "decision": "requeued",
                "decision_state": "requeued",
                "reason": "non_reviewable_plateau_hard_stop_return",
                "created_at": now,
                "grants_execution_authority": False,
            },
        )
        plateau_repaired.append(return_packet_id)
        directive_id = str(packet.get("directive_id", "") or "")
        if directive_id:
            plateau_directive_ids.add(directive_id)
    for directive in _load_items(_directives_root(operator_root)):
        if str(directive.get("state", "") or "") != "returned_for_review":
            continue
        return_packet_id = str(directive.get("latest_return_packet_id", "") or "")
        if not return_packet_id:
            continue
        packet = _read_json(_return_path(operator_root, return_packet_id))
        if not packet:
            continue
        if not str(packet.get("plateau_hard_stop_idempotency_key", "") or "").strip():
            continue
        if str(packet.get("plateau_requeue_reason", "") or "") != "second_no_delta_window_after_depth_support":
            continue
        if str(packet.get("review_state", "") or "") == "pending_operator_review":
            continue
        directive_id = str(directive.get("directive_id", "") or "")
        if directive_id:
            plateau_directive_ids.add(directive_id)
    plateau_directives_repaired: list[str] = []
    for directive_id in sorted(plateau_directive_ids):
        directive_path = _directive_path(operator_root, directive_id)
        directive = _read_json(directive_path)
        if not directive:
            continue
        if str(directive.get("state", "") or "") != "returned_for_review":
            continue
        directive["state"] = "requeued"
        directive["active_child_run_id"] = ""
        directive["updated_at"] = now
        if not str(directive.get("operator_feedback", "") or "").strip():
            target = str(dict(directive.get("metadata", {}) or {}).get("initial_work_order_target_artifact", "") or "")
            directive["operator_feedback"] = (
                f"Resident child plateaued after support; continue on {target or 'the target artifact'} "
                "with a concrete artifact delta before returning."
            )
        _write_json(directive_path, directive)
        plateau_directives_repaired.append(directive_id)
    candidate_return_ids = set(assessment.get("malformed_pending_return_ids", []) or [])
    candidate_return_ids.update(assessment.get("stale_pending_return_ids", []) or [])
    for return_packet_id in sorted(str(item) for item in candidate_return_ids if str(item)):
        packet_path = _return_path(operator_root, return_packet_id)
        packet = _read_json(packet_path)
        if str(packet.get("review_state", "") or "") != "pending_operator_review":
            continue
        malformed = _return_packet_malformed_non_reviewable(packet)
        directive = _read_json(_directive_path(operator_root, str(packet.get("directive_id", "") or "")))
        stale = bool(directive) and str(directive.get("state", "") or "") != "returned_for_review"
        directive_id = str(packet.get("directive_id", "") or "")
        packet_child_id = str(packet.get("child_run_id", "") or "")
        active_child_ids = {
            str(child.get("child_run_id", "") or "")
            for child in active_children_for_preservation.get(directive_id, [])
            if str(child.get("child_run_id", "") or "")
        }
        if (
            malformed
            and active_child_ids
            and packet_child_id not in active_child_ids
            and str(directive.get("state", "") or "") == "returned_for_review"
        ):
            continue
        if not malformed and not stale:
            continue
        packet["review_state"] = "requeued"
        packet["decision"] = "requeued"
        packet["non_reviewable_malformed_return"] = bool(malformed)
        packet["return_repair_state"] = "requeued_by_directive_integrity_repair"
        packet["return_repair_reason"] = (
            "non_reviewable_malformed_return" if malformed else "stale_pending_return_for_requeued_directive"
        )
        packet["updated_at"] = now
        _write_json(packet_path, packet)
        _append_ledger(
            operator_root,
            "return_decisions",
            {
                "schema_name": "ConveyorReturnDecision",
                "schema_version": CONVEYOR_SCHEMA_VERSION,
                "return_packet_id": return_packet_id,
                "directive_id": str(packet.get("directive_id", "") or ""),
                "decision": "requeued",
                "decision_state": "requeued",
                "reason": str(packet.get("return_repair_reason", "") or ""),
                "created_at": now,
                "grants_execution_authority": False,
            },
        )
        if malformed:
            malformed_repaired.append(return_packet_id)
        if stale:
            stale_repaired.append(return_packet_id)
    preserved_directive_ids: set[str] = set()
    for directive_id, child_rows in sorted(active_children_for_preservation.items()):
        directive = _read_json(_directive_path(operator_root, directive_id))
        if str(directive.get("state", "") or "") != "returned_for_review":
            continue
        active_sorted = sorted(
            child_rows,
            key=lambda row: str(
                row.get("updated_at", "")
                or row.get("generated_at", "")
                or row.get("created_at", "")
                or ""
            ),
            reverse=True,
        )
        active_child = active_sorted[0] if active_sorted else {}
        active_child_id = str(active_child.get("child_run_id", "") or "").strip()
        if not active_child_id:
            continue
        repaired_return_ids: list[str] = []
        for packet in _load_items(_returns_root(operator_root)):
            if str(packet.get("directive_id", "") or "") != directive_id:
                continue
            if str(packet.get("review_state", "") or "") not in {"pending_operator_review", "requeued"}:
                continue
            packet_child_id = str(packet.get("child_run_id", "") or "").strip()
            if packet_child_id == active_child_id:
                continue
            malformed = _return_packet_malformed_non_reviewable(packet) or bool(
                packet.get("non_reviewable_malformed_return", False)
            )
            if not malformed:
                continue
            packet["review_state"] = "requeued"
            packet["decision"] = "requeued"
            packet["non_reviewable_malformed_return"] = True
            packet["return_repair_state"] = "requeued_by_directive_integrity_repair"
            packet["return_repair_reason"] = "stale_empty_return_superseded_by_live_child"
            packet["superseded_by_active_child_run_id"] = active_child_id
            packet["superseded_reason"] = "active_resident_worker_continuation"
            packet["reviewed_at"] = now
            packet["updated_at"] = now
            return_packet_id = str(packet.get("return_packet_id", "") or "")
            _write_json(_return_path(operator_root, return_packet_id), packet)
            _append_ledger(
                operator_root,
                "return_decisions",
                {
                    "schema_name": "ConveyorReturnDecision",
                    "schema_version": CONVEYOR_SCHEMA_VERSION,
                    "return_packet_id": return_packet_id,
                    "directive_id": directive_id,
                    "decision": "requeued",
                    "decision_state": "requeued",
                    "reason": "stale_empty_return_superseded_by_live_child",
                    "created_at": now,
                    "superseded_by_active_child_run_id": active_child_id,
                    "grants_execution_authority": False,
                },
            )
            repaired_return_ids.append(return_packet_id)
        if not repaired_return_ids:
            continue
        directive["state"] = "running"
        directive["active_child_run_id"] = active_child_id
        directive["updated_at"] = now
        metadata = dict(directive.get("metadata", {}) or {})
        metadata["directive_integrity_live_child_preserved"] = True
        metadata["directive_integrity_preserved_child_run_id"] = active_child_id
        metadata["directive_integrity_repaired_return_ids"] = repaired_return_ids
        metadata["directive_integrity_repair_reason"] = "stale_empty_return_superseded_by_live_child"
        metadata["directive_integrity_repaired_at"] = now
        directive["metadata"] = metadata
        _write_json(_directive_path(operator_root, directive_id), directive)
        preserved_directive_ids.add(directive_id)
        live_child_preserved.append(
            {
                "directive_id": directive_id,
                "child_run_id": active_child_id,
                "return_packet_ids": repaired_return_ids,
                "repair_reason": "stale_empty_return_superseded_by_live_child",
            }
        )
    for directive_id in sorted(str(item) for item in assessment.get("stale_spawn_lock_ids", []) or [] if str(item)):
        lock_path = _directive_spawn_lock_path(operator_root, directive_id)
        try:
            if lock_path.exists():
                shutil.rmtree(lock_path)
                spawn_locks_repaired.append(directive_id)
        except OSError:
            continue
    scheduler = _load_scheduler(operator_root)
    effective_runner = runner or runner_from_scheduler(scheduler)
    active_children = {
        str(child.get("child_run_id", "") or ""): child
        for child in _active_children(operator_root)
        if str(child.get("child_run_id", "") or "")
    }
    children_to_stop: dict[str, str] = {}
    for directive_id, child_ids in dict(
        assessment.get("stale_active_child_ids_by_directive", {}) or {}
    ).items():
        if str(directive_id) in preserved_directive_ids:
            continue
        for child_id in list(child_ids or []):
            if child_id:
                children_to_stop[str(child_id)] = "stale_child_for_inactive_directive"
    for directive_id, child_ids in dict(
        assessment.get("duplicate_directive_child_ids", {}) or {}
    ).items():
        ids = [str(child_id) for child_id in list(child_ids or []) if str(child_id)]
        if len(ids) <= 1:
            continue
        directive = _read_json(_directive_path(operator_root, str(directive_id)))
        preferred = str(directive.get("active_child_run_id", "") or "")
        if preferred not in ids:
            inspect_results: dict[str, dict[str, Any]] = {}
            for child_id in ids:
                child = dict(active_children.get(child_id, {}) or {})
                if not child:
                    continue
                try:
                    inspect = effective_runner.inspect_child_container(child)
                except Exception as exc:
                    inspect = {
                        "ok": False,
                        "state": "inspect_failed",
                        "error_type": type(exc).__name__,
                    }
                inspect_results[child_id] = dict(inspect)

            def _live_container_score(child_id: str) -> int:
                inspect = inspect_results.get(child_id, {})
                state = str(inspect.get("state", "") or "").strip().lower()
                if bool(inspect.get("ok", False)) and state == "running":
                    return 4
                if bool(inspect.get("ok", False)) and state in {"created", "restarting", "paused"}:
                    return 3
                if bool(inspect.get("ok", False)):
                    return 2
                if state in {"running", "created", "restarting", "paused"}:
                    return 1
                return 0

            ids.sort(
                key=lambda child_id: str(
                    active_children.get(child_id, {}).get("updated_at", "")
                    or active_children.get(child_id, {}).get("generated_at", "")
                    or active_children.get(child_id, {}).get("created_at", "")
                    or ""
                ),
                reverse=True,
            )
            ids.sort(key=_live_container_score, reverse=True)
            preferred = ids[0]
        for child_id in ids:
            if child_id != preferred:
                children_to_stop[child_id] = "duplicate_active_child_for_directive"
    for child_id, reason in sorted(children_to_stop.items()):
        child = dict(active_children.get(child_id, {}) or {})
        if not child:
            continue
        try:
            stop_result = effective_runner.stop_child_container(child)
        except Exception as exc:
            stop_result = {"ok": False, "state": "stop_failed", "error_type": type(exc).__name__}
        child["state"] = "stopped" if bool(stop_result.get("ok", False)) else "stopped"
        child["stop_requested"] = True
        child["stop_result"] = dict(stop_result)
        child["directive_integrity_repair_reason"] = reason
        child["updated_at"] = now
        _write_json(_child_path(operator_root, child_id), child)
        release_task_manager_lease(
            operator_root,
            directive_id=str(child.get("directive_id", "") or ""),
            reason=reason,
            child_run_id=child_id,
        )
        child_stops.append(
            {
                "child_run_id": child_id,
                "directive_id": str(child.get("directive_id", "") or ""),
                "repair_reason": reason,
                "stop_result": dict(stop_result),
            }
        )
    task_repair = apply_task_manager_repairs(operator_root)
    snapshot = build_task_manager_snapshot(operator_root, persist=True)
    return {
        "ok": True,
        "schema_name": "ConveyorDirectiveIntegrityRepair",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": now,
        "malformed_return_repaired_count": len(malformed_repaired),
        "malformed_return_repaired_ids": malformed_repaired,
        "stale_pending_return_repaired_count": len(stale_repaired),
        "stale_pending_return_repaired_ids": stale_repaired,
        "plateau_return_repaired_count": len(plateau_repaired),
        "plateau_return_repaired_ids": plateau_repaired,
        "plateau_directive_repaired_count": len(plateau_directives_repaired),
        "plateau_directive_repaired_ids": plateau_directives_repaired,
        "stale_spawn_lock_repaired_count": len(spawn_locks_repaired),
        "stale_spawn_lock_repaired_ids": spawn_locks_repaired,
        "live_child_preserved_count": len(live_child_preserved),
        "directive_integrity_live_child_preserved": bool(live_child_preserved),
        "live_child_preserved": live_child_preserved,
        "stale_child_stop_count": len(child_stops),
        "stale_child_stops": child_stops,
        "task_manager_repair_applied_count": int(
            task_repair.get("task_manager_repair_applied_count", 0) or 0
        ),
        "task_manager_released_stale_lease_count": int(
            task_repair.get("task_manager_released_stale_lease_count", 0) or 0
        ),
        "task_manager_snapshot": snapshot,
        "grants_execution_authority": False,
    }


def conveyor_status(operator_root: str | Path) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    scheduler = _load_scheduler(operator_root)
    directives = _load_items(_directives_root(operator_root))
    directive_by_id = {
        str(directive.get("directive_id", "") or ""): directive
        for directive in directives
        if str(directive.get("directive_id", "") or "")
    }
    children = _load_items(_children_root(operator_root))
    title_by_directive = _directive_title_map(directives)
    active_by_directive = _active_child_ids_by_directive(children)
    returns: list[dict[str, Any]] = []
    for packet in _load_items(_returns_root(operator_root)):
        hydrated = dict(packet)
        if str(hydrated.get("review_state", "") or "") == "pending_operator_review":
            if not _terminal_prototype_ready_review_packet(hydrated):
                hydrated, changed = _hydrate_pending_return_workspace_artifacts(operator_root, hydrated)
                artifacts = {str(item) for item in list(hydrated.get("artifacts", []) or [])}
                evidence = {str(item) for item in list(hydrated.get("verification_evidence", []) or [])}
                missing_artifacts = sorted(BUILD_GRADE_ALL_REQUIRED_ARTIFACTS - artifacts)
                missing_evidence = sorted((BUILD_GRADE_REQUIRED_EVIDENCE | {BUILD_GRADE_STRUCTURED_EVIDENCE}) - evidence)
                refreshed_campaign_state = _campaign_depth_assessment(
                    hydrated,
                    missing_artifacts=missing_artifacts,
                    missing_evidence=missing_evidence,
                )
                existing_evaluation = dict(hydrated.get("kernel_evaluation", {}) or {})
                if existing_evaluation and dict(existing_evaluation.get("campaign_state", {}) or {}) != refreshed_campaign_state:
                    existing_evaluation["campaign_state"] = refreshed_campaign_state
                    existing_evaluation["missing_artifacts"] = missing_artifacts
                    existing_evaluation["missing_evidence"] = missing_evidence
                    hydrated["kernel_evaluation"] = existing_evaluation
                    changed = True
                support_fields = _support_blocker_packet_fields(
                    operator_root,
                    hydrated,
                    dict(hydrated.get("kernel_evaluation", {}) or {}),
                )
                if support_fields:
                    hydrated.update(support_fields)
                    changed = True
                else:
                    hydrated, cleared = _clear_stale_support_blocker_packet_fields(hydrated)
                    changed = changed or cleared
                if changed:
                    _write_json(_return_path(operator_root, str(hydrated.get("return_packet_id", "") or "")), hydrated)
        returns.append(hydrated)
    support_requests = _load_items(_support_requests_root(operator_root))
    returns, support_requests = _supersede_stale_pending_blockers_for_active_directives(
        operator_root,
        returns=returns,
        support_requests=support_requests,
        active_by_directive=active_by_directive,
    )
    returns, support_requests = _supersede_duplicate_pending_blockers(
        operator_root,
        returns=returns,
        support_requests=support_requests,
    )
    active_children: list[dict[str, Any]] = []
    for child in children:
        if str(child.get("state", "") or "") in TERMINAL_CHILD_STATES:
            continue
        enriched = dict(child)
        directive_id = str(enriched.get("directive_id", "") or "")
        if directive_id:
            enriched["directive_title"] = title_by_directive.get(directive_id, directive_id)
            directive = directive_by_id.get(directive_id)
            if directive:
                enriched["continuous_campaign"] = _continuous_campaign_state(
                    scheduler=scheduler,
                    directive=directive,
                )
        latest_progress = _latest_child_progress(enriched)
        if latest_progress:
            enriched["latest_progress"] = latest_progress
            enriched["progress_state"] = str(latest_progress.get("progress_state", "") or "")
            enriched["latest_progress_at"] = str(latest_progress.get("generated_at", "") or "")
        enriched.update(_child_compute_status_fields(enriched, latest_progress))
        enriched.update(_resident_wake_state(enriched))
        active_children.append(enriched)
    enriched_support_requests: list[dict[str, Any]] = []
    for request in support_requests:
        enriched = dict(request)
        directive_id = str(enriched.get("directive_id", "") or "")
        if directive_id:
            enriched["directive_title"] = title_by_directive.get(directive_id, directive_id)
            directive = directive_by_id.get(directive_id)
            if directive:
                enriched["continuous_campaign"] = _continuous_campaign_state(
                    scheduler=scheduler,
                    directive=directive,
                )
        enriched_support_requests.append(enriched)
    enriched_returns: list[dict[str, Any]] = []
    for packet in returns:
        enriched = dict(packet)
        directive_id = str(enriched.get("directive_id", "") or "")
        if directive_id:
            enriched["directive_title"] = title_by_directive.get(directive_id, directive_id)
            directive = directive_by_id.get(directive_id)
            if directive:
                enriched["continuous_campaign"] = _continuous_campaign_state(
                    scheduler=scheduler,
                    directive=directive,
                )
            else:
                enriched["stale_directive_reference"] = True
        enriched_returns.append(enriched)
    stale_return_directive_count = sum(
        1
        for packet in enriched_returns
        if str(packet.get("review_state", "") or "") == "pending_operator_review"
        and bool(packet.get("stale_directive_reference", False))
    )
    campaign_manifests: list[dict[str, Any]] = []
    campaign_manifest_by_directive: dict[str, dict[str, Any]] = {}
    pending_returns_by_directive: dict[str, int] = {}
    for packet in enriched_returns:
        if str(packet.get("review_state", "") or "") != "pending_operator_review":
            continue
        directive_id = str(packet.get("directive_id", "") or "")
        pending_returns_by_directive[directive_id] = pending_returns_by_directive.get(directive_id, 0) + 1
    pending_support_by_directive: dict[str, int] = {}
    for request in enriched_support_requests:
        if str(request.get("support_state", "") or "") != "pending_operator_review":
            continue
        directive_id = str(request.get("directive_id", "") or "")
        pending_support_by_directive[directive_id] = pending_support_by_directive.get(directive_id, 0) + 1
    active_child_by_directive = {
        str(child.get("directive_id", "") or ""): child
        for child in active_children
        if str(child.get("directive_id", "") or "")
    }
    for directive in directives:
        directive_id = str(directive.get("directive_id", "") or "")
        if not directive_id:
            continue
        manifest_path = _campaign_manifest_path(operator_root, directive_id)
        if manifest_path.exists():
            manifest = _write_campaign_manifest(
                operator_root,
                directive_id,
                active_child=active_child_by_directive.get(directive_id, {}),
                pending_return_count=pending_returns_by_directive.get(directive_id, 0),
                pending_support_count=pending_support_by_directive.get(directive_id, 0),
            )
            campaign_manifests.append(manifest)
            campaign_manifest_by_directive[directive_id] = manifest
    for child in active_children:
        directive_id = str(child.get("directive_id", "") or "")
        manifest = campaign_manifest_by_directive.get(directive_id, {})
        draft_delta_quality = dict(manifest.get("draft_delta_quality", {}) or {})
        if draft_delta_quality:
            child["draft_delta_quality"] = draft_delta_quality
            child["draft_plateau_count"] = int(draft_delta_quality.get("draft_plateau_count", 0) or 0)
            child["latest_draft_delta_gate_failures"] = list(
                draft_delta_quality.get("failed_gates", []) or []
            )
    directive_catalog = [
        {
            "directive_id": str(directive.get("directive_id", "") or ""),
            "directive_title": title_by_directive.get(str(directive.get("directive_id", "") or ""), ""),
            "state": str(directive.get("state", "") or ""),
            "campaign_manifest": campaign_manifest_by_directive.get(
                str(directive.get("directive_id", "") or ""),
                {},
            ),
            "continuous_campaign": _continuous_campaign_state(
                scheduler=scheduler,
                directive=directive,
            ),
        }
        for directive in directives
        if str(directive.get("directive_id", "") or "")
    ]
    continuous_campaign_directives = [
        dict(item.get("continuous_campaign", {}) or {}, directive_id=str(item.get("directive_id", "") or ""))
        for item in directive_catalog
    ]
    task_manager_snapshot = build_task_manager_snapshot(
        operator_root,
        scheduler=scheduler,
        persist=True,
    )
    return {
        "schema_name": CONVEYOR_SCHEMA_NAME,
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "scheduler": scheduler,
        "continuous_campaign": {
            "enabled": bool(scheduler.get("continuous_campaign_mode", False)),
            "policy": _continuous_campaign_policy(scheduler),
            "auto_continuing_count": sum(
                1
                for item in continuous_campaign_directives
                if str(item.get("latest_state", "") or "") == "auto_requeued"
            ),
            "cap_exhausted_count": sum(
                1
                for item in continuous_campaign_directives
                if str(item.get("latest_state", "") or "") == "cap_exhausted"
            ),
            "no_progress_escalated_count": sum(
                1
                for item in continuous_campaign_directives
                if str(item.get("latest_state", "") or "") == "no_progress_escalated"
            ),
            "directives": continuous_campaign_directives,
        },
        "directive_counts_by_state": _count_by_state(directives),
        "child_counts_by_state": _count_by_state(children),
        "return_counts_by_review_state": _count_by_state(enriched_returns, field="review_state"),
        "support_request_counts_by_state": _count_by_state(enriched_support_requests, field="support_state"),
        "stale_return_directive_count": stale_return_directive_count,
        "task_manager_mode": str(task_manager_snapshot.get("task_manager_mode", "") or "shadow"),
        "task_manager_state": task_manager_snapshot,
        "task_manager_active_lease_count": int(task_manager_snapshot.get("active_lease_count", 0) or 0),
        "task_manager_admissible_directive_count": int(
            task_manager_snapshot.get("admissible_directive_count", 0) or 0
        ),
        "task_manager_suppressed_duplicate_count": int(
            task_manager_snapshot.get("duplicate_suppression_count", 0) or 0
        ),
        "task_manager_mismatch_count": int(task_manager_snapshot.get("mismatch_count", 0) or 0),
        "active_children": active_children,
        "queued_directives": _queued_directives(operator_root),
        "directive_catalog": directive_catalog,
        "campaigns": campaign_manifests,
        "support_requests": enriched_support_requests,
        "returned_packets": [
            packet
            for packet in enriched_returns
            if str(packet.get("review_state", "") or "") == "pending_operator_review"
        ],
    }


def _memory_health_blocker(operator_root: str | Path) -> str:
    try:
        status = autonomy_status(operator_root)
    except Exception:
        return ""
    growth = dict(dict(status).get("autonomous_growth", {}) or {})
    pressure_values = {
        str(growth.get("memory_pressure_band", "") or "").lower(),
        str(growth.get("memory_smoothing_state", "") or "").lower(),
        str(growth.get("oom_guard_state", "") or "").lower(),
    }
    if pressure_values & {"oom", "out_of_memory", "critical", "exhausted"}:
        return "memory_health_unsafe"
    if bool(growth.get("memory_restart_recommended", False)) or bool(growth.get("service_recycle_recommended", False)):
        return "memory_health_unsafe"
    return ""


def conveyor_overnight_readiness(
    operator_root: str | Path,
    *,
    state_root: str | Path | None = None,
    required_directive_ids: Iterable[str] | None = None,
    target_hours: int = 10,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    status = conveyor_lightweight_summary(operator_root)
    scheduler = dict(status.get("scheduler", {}) or {})
    active_children = [
        dict(item)
        for item in list(status.get("active_children", []) or [])
        if str(dict(item).get("state", "") or "") not in TERMINAL_CHILD_STATES
    ]
    returned_packets = [dict(item) for item in _load_items(_returns_root(operator_root))]
    support_requests = [dict(item) for item in _load_items(_support_requests_root(operator_root))]
    directive_catalog = [dict(item) for item in _load_items(_directives_root(operator_root))]
    directive_state_by_id = {
        str(item.get("directive_id", "") or ""): str(item.get("state", "") or "")
        for item in directive_catalog
        if str(item.get("directive_id", "") or "")
    }
    required_ids = [str(item) for item in list(required_directive_ids or []) if str(item or "").strip()]
    if not required_ids:
        required_ids = [
            str(item.get("directive_id", "") or "")
            for item in directive_catalog
            if str(item.get("directive_id", "") or "")
            and str(item.get("state", "") or "") in {"running", "queued", "requeued", "returned_for_review"}
        ]
    required_ids = list(dict.fromkeys(required_ids))
    campaigns = [dict(item) for item in list(status.get("campaigns", []) or [])]
    campaign_by_directive = {str(item.get("directive_id", "") or ""): item for item in campaigns}
    active_work_required_ids = [
        directive_id
        for directive_id in required_ids
        if directive_state_by_id.get(directive_id, "") in {"running", "queued", "requeued"}
    ]
    expected_active = len(active_work_required_ids)
    active_directive_ids = {
        str(child.get("directive_id", "") or "")
        for child in active_children
        if str(child.get("directive_id", "") or "")
    }
    prototype_ready_review_packets = [
        packet
        for packet in returned_packets
        if str(packet.get("review_state", "") or "") == "pending_operator_review"
        and str(dict(packet.get("kernel_evaluation", {}) or {}).get("decision", "") or "") == "operator_review_ready"
        and bool(dict(packet.get("kernel_evaluation", {}) or {}).get("prototype_ready_stop_condition", False))
    ]
    prototype_ready_review_directive_ids = {
        str(packet.get("directive_id", "") or "")
        for packet in prototype_ready_review_packets
        if str(packet.get("directive_id", "") or "")
    }
    non_ready_pending_return_packets = [
        packet
        for packet in returned_packets
        if str(packet.get("review_state", "") or "") == "pending_operator_review"
        and str(packet.get("directive_id", "") or "") not in prototype_ready_review_directive_ids
    ]
    queued_or_running_without_child = [
        str(item.get("directive_id", "") or "")
        for item in directive_catalog
        if str(item.get("directive_id", "") or "") in set(required_ids)
        and str(item.get("state", "") or "") in {"queued", "requeued", "running"}
        and str(item.get("directive_id", "") or "") not in active_directive_ids
    ]
    inactive_required_ids = [
        directive_id for directive_id in active_work_required_ids if directive_id not in active_directive_ids
    ]
    inactive_work_is_prototype_ready_review = (
        bool(inactive_required_ids)
        and not queued_or_running_without_child
        and all(directive_id in prototype_ready_review_directive_ids for directive_id in inactive_required_ids)
    )
    quiescent_campaign_states = {
        "prototype_candidate_review",
        "prototype_ready_review",
        "build_ready_review",
        "hardware_build_packet_ready",
    }

    def _inactive_required_work_needs_resident(directive_id: str) -> bool:
        if directive_id in prototype_ready_review_directive_ids:
            return False
        campaign = dict(campaign_by_directive.get(directive_id, {}) or {})
        readiness_state = str(campaign.get("readiness_state", "") or campaign.get("status", "") or "")
        if readiness_state in quiescent_campaign_states:
            return False
        return True

    inactive_runnable_required_ids = [
        directive_id
        for directive_id in inactive_required_ids
        if _inactive_required_work_needs_resident(directive_id)
    ]
    active_required_ids = [
        directive_id for directive_id in active_work_required_ids if directive_id in active_directive_ids
    ]
    required_runnable_active_count = len(active_required_ids) + len(inactive_runnable_required_ids)
    blockers: list[str] = []
    warnings: list[str] = []
    recommended_actions: list[str] = []
    if _autonomy_emergency_stop_active(operator_root):
        blockers.append("emergency_stop_active")
        recommended_actions.append("Clear emergency stop only after confirming operator intent.")
    if not bool(scheduler.get("continuous_campaign_mode", False)):
        blockers.append("continuous_campaign_mode_disabled")
        recommended_actions.append("Enable continuous campaign mode for build-grade directives.")
    if str(scheduler.get("child_execution_mode", "") or "") != "resident_campaign":
        blockers.append("resident_campaign_mode_disabled")
        recommended_actions.append("Set child_execution_mode to resident_campaign.")
    if int(scheduler.get("target_concurrency", 0) or 0) < required_runnable_active_count:
        blockers.append("target_concurrency_below_required")
        recommended_actions.append(f"Raise target_concurrency to at least {required_runnable_active_count}.")
    if int(scheduler.get("max_concurrency", 0) or 0) < required_runnable_active_count:
        blockers.append("max_concurrency_below_required")
        recommended_actions.append(f"Raise max_concurrency to at least {required_runnable_active_count}.")
    if len(active_children) < required_runnable_active_count:
        blockers.append("active_children_below_required")
        recommended_actions.append("Resolve blockers and run a scheduler tick until required resident workers are active.")
    elif len(active_children) < expected_active:
        warnings.append("active_child_count_below_scheduler_target")
    stale_wake_children = [
        str(child.get("child_run_id", "") or "")
        for child in active_children
        if bool(child.get("wake_pending", False)) and bool(child.get("wake_stale", False))
    ]
    if stale_wake_children:
        warnings.append("resident_child_wake_pending_stale")
        recommended_actions.append("Run conveyor reconciliation so stale wake tokens can be acknowledged or fallback-restarted.")
    if int(status.get("stale_return_directive_count", 0) or 0) > 0:
        blockers.append("stale_return_directive_reference")
        recommended_actions.append("Resolve or archive orphaned return packets that reference missing directive records.")
    target_drift_records = [
        dict(item)
        for item in list(status.get("target_drift_records", []) or [])
        if dict(item).get("target_drift_detected", False)
    ]
    if target_drift_records:
        warnings.append("active_child_target_drift_detected")
        recommended_actions.append(
            "Run repair_active_resident_target_drift before the next resident cycle to retarget stale child work orders."
        )
    schema_followup_records = [
        dict(item)
        for item in list(status.get("schema_resonance_followup_records", []) or [])
        if dict(item).get("schema_resonance_followup_required", False)
    ]
    if schema_followup_records:
        warnings.append("schema_resonance_followup_required")
        recommended_actions.append(
            "Run repair_active_schema_resonance_followup so children echo missing evaluator keys as top-level artifact fields."
        )
    schema_followup_stall_count = int(status.get("schema_followup_stall_count", 0) or 0)
    schema_followup_top_level_missing_count = int(status.get("schema_followup_top_level_missing_count", 0) or 0)
    schema_followup_contract_satisfied_count = int(status.get("schema_followup_contract_satisfied_count", 0) or 0)
    persistent_schema_contract_missing_count = int(status.get("persistent_schema_contract_missing_count", 0) or 0)
    stale_missing_container_child_count = int(status.get("stale_missing_container_child_count", 0) or 0)
    hardware_build_packet_incomplete_count = int(status.get("hardware_build_packet_incomplete_count", 0) or 0)
    hardware_build_packet_records = [
        dict(item)
        for item in list(status.get("hardware_build_packet_records", []) or [])
        if isinstance(item, Mapping)
    ]
    return_campaign_hydration_mismatch_count = int(status.get("return_campaign_hydration_mismatch_count", 0) or 0)
    growth_receipt_health = dict(status.get("growth_receipt_health", {}) or {})
    if int(growth_receipt_health.get("recent_growth_receipt_count", 0) or 0) > 0 and int(
        growth_receipt_health.get("later_consumed_growth_receipt_count", 0) or 0
    ) == 0:
        warnings.append("growth_receipts_waiting_for_later_consumption")
    if schema_followup_stall_count > 0:
        warnings.append("schema_resonance_followup_stalled")
        recommended_actions.append(
            "Inspect child drafts for missing top-level schema-follow-up fields before allowing target-correct closure."
        )
    if persistent_schema_contract_missing_count > 0:
        warnings.append("persistent_schema_contract_missing")
        recommended_actions.append(
            "Keep the active target and require the persistent top-level schema contract before promotion."
        )
    if stale_missing_container_child_count > 0:
        warnings.append("stale_missing_container_child")
        recommended_actions.append(
            "Run reconciliation; recover missing child containers with final-return progress evidence or hold them for operator review."
        )
    if hardware_build_packet_incomplete_count > 0:
        warnings.append("hardware_build_packet_incomplete")
        recommended_actions.append(
            "Continue hardware directives on the next missing build-packet artifact until materialized fixtures, traces, BOM, manifest, risk controls, and return packet gates pass."
        )
    if return_campaign_hydration_mismatch_count > 0:
        warnings.append("return_campaign_hydration_mismatch")
        recommended_actions.append(
            "Review returned packet hydration before requeueing; campaign artifacts may be deeper than the return packet says."
        )
    non_denied_children = [
        str(child.get("child_run_id", "") or "")
        for child in active_children
        if str(child.get("network_policy", "") or "") != "deny_all"
    ]
    if non_denied_children:
        blockers.append("child_network_policy_not_denied")
        recommended_actions.append("Stop or restart child workers that are not using deny_all network policy.")
    support_gated_returns = [
        packet
        for packet in returned_packets
        if bool(packet.get("support_required_before_continue", False))
        or str(packet.get("support_blocker_state", "") or "") == "pending_operator_review"
    ]
    pending_support = [
        request for request in support_requests if str(request.get("support_state", "") or "") == "pending_operator_review"
    ]
    if support_gated_returns or pending_support:
        blockers.append("support_gated_returns_pending")
        recommended_actions.append("Auto-satisfy or approve routine synthesis support, then requeue before overnight.")
    shallow_campaigns = [
        item
        for item in campaigns
        if str(item.get("readiness_state", "") or "") == "artifact_complete_quality_shallow"
        or (
            float(item.get("artifact_presence_score", 0.0) or 0.0) >= 1.0
            and float(item.get("quality_depth_score", 0.0) or 0.0) < 0.75
        )
    ]
    if shallow_campaigns:
        blockers.append("campaign_quality_depth_shallow")
        recommended_actions.append("Continue quality-depth passes until artifact presence and quality depth both pass prototype thresholds.")
    memory_blocker = _memory_health_blocker(operator_root)
    if memory_blocker:
        blockers.append(memory_blocker)
        recommended_actions.append("Resolve memory/OOM health before starting an overnight run.")
    try:
        usage = shutil.disk_usage(str(operator_root))
        if usage.free < 5 * 1024 * 1024 * 1024:
            blockers.append("disk_headroom_low")
            recommended_actions.append("Free at least 5GB before leaving resident workers overnight.")
    except Exception:
        warnings.append("disk_headroom_unknown")
    active_by_directive = {str(child.get("directive_id", "") or ""): child for child in active_children}
    return_by_directive: dict[str, list[dict[str, Any]]] = {}
    for packet in returned_packets:
        return_by_directive.setdefault(str(packet.get("directive_id", "") or ""), []).append(packet)
    support_by_directive: dict[str, list[dict[str, Any]]] = {}
    for request in pending_support:
        support_by_directive.setdefault(str(request.get("directive_id", "") or ""), []).append(request)
    directive_statuses: list[dict[str, Any]] = []
    for directive in directive_catalog:
        directive_id = str(dict(directive).get("directive_id", "") or "")
        if required_ids and directive_id not in required_ids:
            continue
        child = active_by_directive.get(directive_id, {})
        continuous = dict(dict(directive).get("continuous_campaign", {}) or {})
        campaign = dict(campaign_by_directive.get(directive_id, {}) or {})
        directive_statuses.append(
            {
                "directive_id": directive_id,
                "directive_title": str(dict(directive).get("directive_title", "") or directive_id),
                "state": str(dict(directive).get("state", "") or ""),
                "active_child_run_id": str(child.get("child_run_id", "") or ""),
                "worker_active": bool(child),
                "network_policy": str(child.get("network_policy", "") or ""),
                "latest_target_artifact": str(
                    child.get("latest_work_order_target_artifact", "")
                    or child.get("latest_target_artifact", "")
                    or continuous.get("latest_target_artifact", "")
                    or ""
                ),
                "manifest_next_unresolved_gate_artifact": str(
                    child.get("manifest_next_unresolved_gate_artifact", "")
                    or campaign.get("next_unresolved_gate_artifact", "")
                    or ""
                ),
                "target_drift_detected": bool(child.get("target_drift_detected", False)),
                "schema_resonance_followup_required": bool(
                    child.get("schema_resonance_followup_required", False)
                ),
                "schema_resonance_score": float(child.get("schema_resonance_score", 1.0) or 0.0),
                "missing_top_level_fields": list(child.get("missing_top_level_fields", []) or []),
                "wake_pending": bool(child.get("wake_pending", False)),
                "latest_wake_request": dict(child.get("latest_wake_request", {}) or {}),
                "latest_wake_ack": dict(child.get("latest_wake_ack", {}) or {}),
                "wake_latency_seconds": child.get("wake_latency_seconds"),
                "wake_fallback_restart_count": int(child.get("wake_fallback_restart_count", 0) or 0),
                "continuous_campaign": continuous,
                "campaign_readiness_state": str(campaign.get("readiness_state", "") or ""),
                "hardware_build_packet_assessment": dict(
                    campaign.get("hardware_build_packet_assessment", {}) or {}
                ),
                "artifact_presence_score": float(campaign.get("artifact_presence_score", 0.0) or 0.0),
                "quality_depth_score": float(campaign.get("quality_depth_score", 0.0) or 0.0),
                "quality_failed_artifacts": list(campaign.get("quality_failed_artifacts", []) or []),
                "failed_quality_gates": list(campaign.get("failed_quality_gates", []) or []),
                "pending_return_count": len(return_by_directive.get(directive_id, [])),
                "prototype_ready_return_count": len(
                    [
                        packet
                        for packet in return_by_directive.get(directive_id, [])
                        if str(dict(packet.get("kernel_evaluation", {}) or {}).get("decision", "") or "")
                        == "operator_review_ready"
                        and bool(
                            dict(packet.get("kernel_evaluation", {}) or {}).get(
                                "prototype_ready_stop_condition", False
                            )
                        )
                    ]
                ),
                "pending_support_count": len(support_by_directive.get(directive_id, [])),
            }
        )
    if required_ids:
        found = {item["directive_id"] for item in directive_statuses}
        for directive_id in required_ids:
            if directive_id not in found:
                blockers.append("required_directive_missing")
                directive_statuses.append(
                    {
                        "directive_id": directive_id,
                        "directive_title": directive_id,
                        "state": "missing",
                        "worker_active": False,
                        "pending_return_count": 0,
                        "pending_support_count": 0,
                    }
                )
    blockers = list(dict.fromkeys(blockers))
    productive_quiescence_count = len(
        [
            child
            for child in active_children
            if bool(child.get("productive_quiescence_eligible", False))
            or bool(child.get("return_requested_after_clean_delta", False))
        ]
    )
    consumption_churn_warning_count = 0
    try:
        nine_d = _read_json(autonomy_root(operator_root) / "nine_d_capability_maturity_latest.json")
        churn = dict(nine_d.get("consumption_churn_assessment", {}) or {})
        consumption_churn_warning_count = int(churn.get("duplicate_strict_event_count", 0) or 0)
        if str(churn.get("state", "") or "") == "active":
            warnings.append("consumption_churn_without_closure")
    except Exception:
        consumption_churn_warning_count = 0
    return {
        "ok": True,
        "schema_name": "ConveyorOvernightReadiness",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "readiness_source": "fast_manifest_summary",
        "readiness_scan_limits": {
            "child_records": "metadata_only",
            "return_packets": len(returned_packets),
            "support_requests": len(support_requests),
            "campaign_manifests": len(campaigns),
            "inbox_messages_scanned": 0,
        },
        "target_hours": max(1, int(target_hours or 10)),
        "ready": not blockers,
        "blockers": blockers,
        "warnings": warnings,
        "recommended_actions": list(dict.fromkeys(recommended_actions)),
        "active_child_count": len(active_children),
        "expected_active_child_count": expected_active,
        "prototype_ready_review_count": len(prototype_ready_review_packets),
        "non_ready_pending_return_count": len(non_ready_pending_return_packets),
        "support_gated_return_count": len(support_gated_returns),
        "pending_support_request_count": len(pending_support),
        "productive_quiescence_count": productive_quiescence_count,
        "consumption_churn_warning_count": consumption_churn_warning_count,
        "target_drift_detected": bool(target_drift_records),
        "target_drift_detected_count": len(target_drift_records),
        "target_drift_repair_required": bool(target_drift_records),
        "target_drift_records": target_drift_records,
        "schema_resonance_followup_required": bool(schema_followup_records),
        "schema_resonance_followup_required_count": len(schema_followup_records),
        "schema_resonance_followup_records": schema_followup_records,
        "schema_followup_top_level_missing_count": schema_followup_top_level_missing_count,
        "schema_followup_contract_satisfied_count": schema_followup_contract_satisfied_count,
        "schema_followup_stall_count": schema_followup_stall_count,
        "persistent_schema_contract_missing_count": persistent_schema_contract_missing_count,
        "stale_missing_container_child_count": stale_missing_container_child_count,
        "stale_missing_container_children": list(status.get("stale_missing_container_children", []) or []),
        "hardware_build_packet_required_count": int(status.get("hardware_build_packet_required_count", 0) or 0),
        "hardware_build_packet_ready_count": int(status.get("hardware_build_packet_ready_count", 0) or 0),
        "hardware_build_packet_incomplete_count": hardware_build_packet_incomplete_count,
        "hardware_build_packet_records": hardware_build_packet_records,
        "return_campaign_hydration_mismatch_count": return_campaign_hydration_mismatch_count,
        "growth_receipt_health": growth_receipt_health,
        "recent_growth_receipt_count": int(growth_receipt_health.get("recent_growth_receipt_count", 0) or 0),
        "verified_growth_receipt_count": int(growth_receipt_health.get("verified_growth_receipt_count", 0) or 0),
        "later_consumed_growth_receipt_count": int(
            growth_receipt_health.get("later_consumed_growth_receipt_count", 0) or 0
        ),
        "continuous_campaign_enabled": bool(scheduler.get("continuous_campaign_mode", False)),
        "scheduler": scheduler,
        "directive_statuses": directive_statuses,
        "state_root_present": state_root is not None,
    }


def _load_child(operator_root: str | Path, child_run_id: str) -> dict[str, Any]:
    child = _read_json(_child_path(operator_root, child_run_id))
    if not child:
        raise ConveyorValidationError(f"child_run_id not found: {child_run_id}")
    return child


def _load_directive(operator_root: str | Path, directive_id: str) -> dict[str, Any]:
    directive = _read_json(_directive_path(operator_root, directive_id))
    if not directive:
        raise ConveyorValidationError(f"directive_id not found: {directive_id}")
    return directive


def _clarification_options_for_target(
    directive: Mapping[str, Any],
    target_artifact: str,
) -> list[dict[str, Any]]:
    directive_text = " ".join(
        [
            str(directive.get("directive_title", "") or ""),
            str(directive.get("directive_text", "") or ""),
        ]
    ).lower()
    target = str(target_artifact or "").strip()
    if "grin" in directive_text and target == "validation_fixtures.json":
        return [
            {
                "option_id": "synthetic_robotics_handoff_fixtures",
                "label": "Synthetic robotics handoff fixtures",
                "description": "Ask the child to produce offline robotics handoff scenarios with expected files, expected outputs, and pass/fail traces.",
            },
            {
                "option_id": "operator_customer_interaction_fixtures",
                "label": "Operator/customer interaction fixtures",
                "description": "Ask for role-specific interaction flows that separate operator actions, customer-facing behavior, and governance gates.",
            },
            {
                "option_id": "external_gateway_denial_fixtures",
                "label": "External gateway denial fixtures",
                "description": "Ask for explicit denial cases covering invasive, clinical, networked, or unsupported gateway capabilities.",
            },
            {
                "option_id": "real_world_test_exclusion_criteria",
                "label": "Real-world test exclusion criteria",
                "description": "Ask for no-go criteria that keep the prototype synthetic, non-clinical, and review-gated.",
            },
        ]
    return [
        {
            "option_id": "deepen_current_target",
            "label": "Deepen current target",
            "description": f"Ask the child to continue {target or 'the current artifact'} with measurable thresholds and evidence refs.",
        },
        {
            "option_id": "narrow_prototype_slice",
            "label": "Narrow prototype slice",
            "description": "Ask the child to reduce scope to the smallest reviewable prototype handoff.",
        },
        {
            "option_id": "hold_for_human_review",
            "label": "Hold for review",
            "description": "Keep the return parked until the operator provides specific direction.",
        },
    ]


def _normalize_requested_operator_clarifications(
    directive: Mapping[str, Any],
    requested: Iterable[Mapping[str, Any]] | None,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for item in list(requested or []):
        if not isinstance(item, Mapping):
            continue
        row = dict(item)
        target = str(row.get("target_artifact", "") or "")
        if not list(row.get("clarification_options", []) or []):
            row["clarification_options"] = _clarification_options_for_target(directive, target)
        rows.append(row)
    return rows


def record_child_return_packet(
    operator_root: str | Path,
    *,
    child_run_id: str,
    outcome_summary: str,
    artifacts: list[str],
    verification_evidence: list[str],
    risks: list[str],
    requested_follow_up: str = "",
    missing_capability_requests: list[Mapping[str, Any]] | None = None,
    artifact_hashes: Mapping[str, Any] | None = None,
    build_grade_scores: Mapping[str, Any] | None = None,
    claim_count: int = 0,
    novelty_count: int = 0,
    requested_operator_clarifications: list[Mapping[str, Any]] | None = None,
    result_state: str = "completed",
    extra_fields: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    child = _load_child(operator_root, child_run_id)
    summary = str(outcome_summary or "").strip()
    if not summary:
        raise ConveyorValidationError("outcome_summary is required")
    now = _utc_now()
    directive_id = str(child.get("directive_id", "") or "")
    directive = _load_directive(operator_root, directive_id)
    recovery_idempotency_key = ""
    if "missing_child_return_packet" in {str(item) for item in list(risks or [])} and not list(artifacts or []):
        recovery_idempotency_key = _record_id("return-recovery", child_run_id, "missing_child_return_packet")
        deterministic_packet_id = _record_id("return", child_run_id, recovery_idempotency_key)
        deterministic_packet = _read_json(_return_path(operator_root, deterministic_packet_id))
        if deterministic_packet:
            existing_packet = dict(deterministic_packet)
            existing_packet["return_recovery_idempotency_key"] = recovery_idempotency_key
            existing_packet["return_packet_recovery_deduplicated"] = True
            existing_packet["updated_at"] = _utc_now()
            _write_json(_return_path(operator_root, deterministic_packet_id), existing_packet)
            if str(child.get("state", "") or "") not in {"returned", "failed", "stopped"}:
                child["state"] = "failed"
                child["return_packet_id"] = deterministic_packet_id
                child["updated_at"] = existing_packet["updated_at"]
                _write_json(_child_path(operator_root, child_run_id), child)
            return existing_packet
        for existing in _load_items(_returns_root(operator_root)):
            if str(existing.get("child_run_id", "") or "") != str(child_run_id):
                continue
            existing_risks = {str(item) for item in list(existing.get("risks", []) or [])}
            existing_key = str(existing.get("return_recovery_idempotency_key", "") or "")
            if existing_key != recovery_idempotency_key and "missing_child_return_packet" not in existing_risks:
                continue
            existing_packet = dict(existing)
            existing_packet["return_recovery_idempotency_key"] = recovery_idempotency_key
            existing_packet["return_packet_recovery_deduplicated"] = True
            existing_packet["updated_at"] = _utc_now()
            packet_id = str(existing_packet.get("return_packet_id", "") or "")
            if packet_id:
                _write_json(_return_path(operator_root, packet_id), existing_packet)
            if str(child.get("state", "") or "") not in {"returned", "failed", "stopped"}:
                child["state"] = "failed"
                child["return_packet_id"] = packet_id
                child["updated_at"] = existing_packet["updated_at"]
                _write_json(_child_path(operator_root, child_run_id), child)
            return existing_packet
    return_packet_id = (
        _record_id("return", child_run_id, recovery_idempotency_key)
        if recovery_idempotency_key
        else _record_id("return", child_run_id, now)
    )
    failed = str(result_state or "").strip() == "failed"
    packet = {
        "schema_name": RETURN_PACKET_SCHEMA_NAME,
        "schema_version": RETURN_PACKET_SCHEMA_VERSION,
        "return_packet_id": return_packet_id,
        "child_run_id": child_run_id,
        "directive_id": directive_id,
        "generated_at": now,
        "outcome_summary": summary,
        "artifacts": [str(item) for item in list(artifacts or [])],
        "verification_evidence": [str(item) for item in list(verification_evidence or [])],
        "risks": [str(item) for item in list(risks or [])],
        "resource_runtime_summary": {
            "spawn_mode": str(child.get("spawn_mode", "")),
            "network_policy": str(child.get("network_policy", "")),
            "workspace_root": str(child.get("workspace_root", "")),
        },
        "requested_follow_up": str(requested_follow_up or ""),
        "missing_capability_requests": [dict(item) for item in list(missing_capability_requests or [])],
        "artifact_hashes": {str(key): str(value) for key, value in dict(artifact_hashes or {}).items()},
        "build_grade_scores": dict(build_grade_scores or {}),
        "claim_count": int(claim_count or 0),
        "novelty_count": int(novelty_count or 0),
        "requested_operator_clarifications": _normalize_requested_operator_clarifications(
            directive,
            requested_operator_clarifications,
        ),
        "review_state": "pending_operator_review",
        "decision_options": list(RETURN_DECISIONS),
    }
    if extra_fields:
        packet.update(dict(extra_fields))
    if recovery_idempotency_key:
        packet["return_recovery_idempotency_key"] = recovery_idempotency_key
    if failed and {"resident_worker_stalled", "docker_mount_fault"}.intersection(set(packet["risks"])) and not packet["artifacts"]:
        packet, _attached = _attach_latest_child_workspace_artifacts(operator_root, packet, child=child)
    packet["return_packet_path"] = str(_return_path(operator_root, return_packet_id))
    _write_json(_return_path(operator_root, return_packet_id), packet)
    child["state"] = "failed" if failed else "returned"
    child["return_packet_id"] = return_packet_id
    child["updated_at"] = now
    _write_json(_child_path(operator_root, child_run_id), child)
    directive["state"] = "returned_for_review"
    directive["active_child_run_id"] = ""
    directive["latest_return_packet_id"] = return_packet_id
    directive["updated_at"] = now
    _write_json(_directive_path(operator_root, directive_id), directive)
    release_task_manager_lease(
        operator_root,
        directive_id=directive_id,
        reason="child_return_recorded",
        child_run_id=child_run_id,
    )
    _append_ledger(operator_root, "return_events", {"event": "packet_recorded", **packet})
    return packet


def reconcile_child_runs(
    operator_root: str | Path,
    *,
    state_root: str | Path | None = None,
    runner: ConveyorChildRunner | None = None,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    scheduler = _load_scheduler(operator_root)
    effective_runner = runner or runner_from_scheduler(scheduler)
    inspected = 0
    collected = 0
    failed = 0
    recovered_missing_container = 0
    requeued_missing_container = 0
    stale_missing_container = 0
    resident_productive_finalized = 0
    resident_no_first_checkpoint_finalized = 0
    rows: list[dict[str, Any]] = []
    stale_missing_container_children: list[dict[str, Any]] = []
    for child in _active_children(operator_root):
        child_id = str(child.get("child_run_id", "") or "")
        if not child_id:
            continue
        inspected += 1
        state = effective_runner.inspect_child_container(child)
        state_name = str(state.get("state", "") or "")
        if state_name != "exited":
            updated = dict(child)
            updated["last_inspect_state"] = state_name
            updated["last_inspect_result"] = dict(state)
            latest_progress = _latest_child_progress(updated)
            if latest_progress:
                updated["latest_progress"] = latest_progress
            missing_container = _child_inspect_indicates_missing_container(state)
            if missing_container and not _child_inspect_indicates_mount_fault(state, updated):
                recovery = _missing_container_recovery_evidence(updated, latest_progress)
                final_return_requested = _child_requested_final_return(updated)
                blockers = [
                    str(item)
                    for item in list(recovery.get("blockers", []) or [])
                    if str(item).strip()
                ]
                if not final_return_requested:
                    _append_unique(blockers, "final_return_not_requested")
                if bool(recovery.get("recoverable", False)) and final_return_requested:
                    evidence = [
                        "resident_progress_recovered_after_missing_container",
                        "missing_container_after_return_request",
                    ]
                    if bool(recovery.get("progress_has_delta", False)):
                        _append_unique(evidence, "resident_progress_meaningful_delta")
                    if bool(recovery.get("workspace_has_artifacts", False)):
                        _append_unique(evidence, "child_workspace_artifacts_present")
                    packet = record_child_return_packet(
                        operator_root,
                        child_run_id=child_id,
                        outcome_summary=(
                            "Child container disappeared after a final-return request; Novali recovered "
                            "resident progress and workspace evidence for review."
                        ),
                        artifacts=[],
                        verification_evidence=evidence,
                        risks=["missing_child_return_packet"],
                        requested_follow_up="kernel_recover_missing_container_from_progress_evidence",
                        result_state="failed",
                        extra_fields={
                            "container_missing_after_return_request": True,
                            "recovered_from_progress_evidence": True,
                            "last_inspect_result": dict(state),
                            "latest_progress_ref": dict(recovery.get("latest_progress_ref", {}) or {}),
                            "recovered_target_artifact": str(recovery.get("target_artifact", "") or ""),
                            "recovered_work_order_id": str(recovery.get("work_order_id", "") or ""),
                            "recovered_workspace_artifacts": list(recovery.get("workspace_artifacts", []) or []),
                            "recovery_artifact_delta_count": int(recovery.get("artifact_delta_count", 0) or 0),
                            "recovery_materialized_expected_files": list(
                                recovery.get("materialized_expected_files", []) or []
                            ),
                        },
                    )
                    attached_packet, attached = _attach_latest_child_workspace_artifacts(
                        operator_root,
                        packet,
                        child=updated,
                    )
                    if attached:
                        attached_packet["container_missing_after_return_request"] = True
                        attached_packet["recovered_from_progress_evidence"] = True
                        attached_packet["last_inspect_result"] = dict(state)
                        attached_packet["latest_progress_ref"] = dict(recovery.get("latest_progress_ref", {}) or {})
                        attached_packet["recovered_target_artifact"] = str(recovery.get("target_artifact", "") or "")
                        attached_packet["recovered_work_order_id"] = str(recovery.get("work_order_id", "") or "")
                        attached_packet["updated_at"] = _utc_now()
                        _write_json(_return_path(operator_root, str(packet.get("return_packet_id", "") or "")), attached_packet)
                        packet = attached_packet
                    recovered_missing_container += 1
                    failed += 1
                    rows.append(packet)
                    continue
                if bool(recovery.get("recoverable", False)) and not final_return_requested:
                    lifecycle = _classify_terminal_child_without_return(
                        updated,
                        inspect_state=state,
                        latest_progress=latest_progress,
                        recovery=recovery,
                    )
                    if str(lifecycle.get("child_lifecycle_classification", "") or "") in {
                        "intentional_stop",
                        "productive_pass_completed_not_review_ready",
                        "blocked_pass_completed_not_review_ready",
                    }:
                        updated = _record_terminal_child_without_review_return(
                            operator_root,
                            child=updated,
                            lifecycle=lifecycle,
                            recovery=recovery,
                            inspect_state=state,
                        )
                    else:
                        updated = _requeue_missing_container_child_without_return(
                            operator_root,
                            child=updated,
                            recovery=recovery,
                            inspect_state=state,
                        )
                    requeued_missing_container += 1
                    failed += 1
                    rows.append(updated)
                    continue
                updated["missing_container_recovery_blocked"] = True
                updated["missing_container_recovery_blockers"] = blockers
                updated["missing_container_after_return_request"] = final_return_requested
                updated["container_missing_after_return_request"] = bool(final_return_requested)
                updated["missing_container_last_seen_at"] = _utc_now()
                updated["updated_at"] = updated["missing_container_last_seen_at"]
                _write_json(_child_path(operator_root, child_id), updated)
                stale_missing_container += 1
                stale_missing_container_children.append(
                    {
                        "child_run_id": child_id,
                        "directive_id": str(updated.get("directive_id", "") or ""),
                        "blockers": blockers,
                        "last_inspect_state": state_name,
                        "last_inspect_result": dict(state),
                    }
                )
                rows.append(updated)
                continue
            wake_state = _resident_wake_state(updated)
            fallback_child = None
            if str(updated.get("child_execution_mode", "") or "") == "resident_campaign":
                fallback_child = _fallback_restart_stale_wake_child(
                    operator_root,
                    state_root=state_root,
                    child=updated,
                    state=state,
                    wake_state=wake_state,
                    runner=effective_runner,
                    scheduler=scheduler,
                )
            if fallback_child is not None:
                rows.append(fallback_child)
                continue
            if latest_progress:
                if str(updated.get("child_execution_mode", "") or "") == "resident_campaign":
                    finalized_child = _finalize_stale_resident_productive_pass(
                        operator_root,
                        child=updated,
                        latest_progress=latest_progress,
                        inspect_state=state,
                        runner=effective_runner,
                    )
                    if finalized_child is not None:
                        resident_productive_finalized += 1
                        requeued_missing_container += 1
                        rows.append(finalized_child)
                        continue
                    if child_id:
                        updated = dict(_read_json(_child_path(operator_root, child_id)) or updated)
                    updated, resident_packet = _update_resident_child_progress_state(
                        operator_root,
                        state_root=state_root,
                        child=updated,
                        latest_progress=latest_progress,
                        runner=effective_runner,
                    )
                    if resident_packet is not None:
                        collected += 1
                        rows.append(resident_packet)
                        continue
                    finalized_child = _finalize_stale_resident_productive_pass(
                        operator_root,
                        child=updated,
                        latest_progress=latest_progress,
                        inspect_state=state,
                        runner=effective_runner,
                    )
                    if finalized_child is not None:
                        resident_productive_finalized += 1
                        requeued_missing_container += 1
                        rows.append(finalized_child)
                        continue
                    if child_id:
                        updated = dict(_read_json(_child_path(operator_root, child_id)) or updated)
                else:
                    updated["latest_progress"] = latest_progress
                    updated["progress_state"] = str(latest_progress.get("progress_state", "") or "")
                    updated["latest_progress_at"] = str(latest_progress.get("generated_at", "") or "")
            elif str(updated.get("child_execution_mode", "") or "") == "resident_campaign":
                finalized_child = _finalize_resident_no_first_checkpoint(
                    operator_root,
                    child=updated,
                    inspect_state=state,
                    runner=effective_runner,
                )
                if finalized_child is not None:
                    resident_no_first_checkpoint_finalized += 1
                    requeued_missing_container += 1
                    failed += 1
                    rows.append(finalized_child)
                    continue
                if child_id:
                    updated = dict(_read_json(_child_path(operator_root, child_id)) or updated)
            updated["updated_at"] = _utc_now()
            _write_json(_child_path(operator_root, child_id), updated)
            rows.append(updated)
            continue
        payload = effective_runner.collect_return_packet(child)
        if payload:
            packet = record_child_return_packet(
                operator_root,
                child_run_id=child_id,
                outcome_summary=str(payload.get("outcome_summary", "") or "Child returned a packet."),
                artifacts=[str(item) for item in list(payload.get("artifacts", []) or [])],
                verification_evidence=[
                    str(item) for item in list(payload.get("verification_evidence", []) or [])
                ],
                risks=[str(item) for item in list(payload.get("risks", []) or [])],
                requested_follow_up=str(payload.get("requested_follow_up", "") or ""),
                missing_capability_requests=[
                    dict(item)
                    for item in list(payload.get("missing_capability_requests", []) or [])
                    if isinstance(item, Mapping)
                ],
                artifact_hashes=dict(payload.get("artifact_hashes", {}) or {}),
                build_grade_scores=dict(payload.get("build_grade_scores", {}) or {}),
                claim_count=int(payload.get("claim_count", 0) or 0),
                novelty_count=int(payload.get("novelty_count", 0) or 0),
                requested_operator_clarifications=[
                    dict(item)
                    for item in list(payload.get("requested_operator_clarifications", []) or [])
                    if isinstance(item, Mapping)
                ],
            )
            collected += 1
            rows.append(packet)
        else:
            recovered_packet = _recover_quiescent_resident_return_from_campaign_draft(operator_root, child)
            if recovered_packet is not None:
                collected += 1
                rows.append(recovered_packet)
                continue
            mount_fault = _child_inspect_indicates_mount_fault(state, child)
            if mount_fault:
                latest_progress = _latest_child_progress(child)
                evidence = ["child_container_exit_code_mount_fault"]
                if latest_progress:
                    evidence.append("resident_progress_mount_fault_checkpoint")
                packet = record_child_return_packet(
                    operator_root,
                    child_run_id=child_id,
                    outcome_summary=(
                        "Child container stopped after a Docker bind-mount I/O fault before it could "
                        "write a valid return packet."
                    ),
                    artifacts=[],
                    verification_evidence=evidence,
                    risks=["docker_mount_fault", "infrastructure_fault"],
                    requested_follow_up="recover_docker_mount_and_requeue",
                    result_state="failed",
                    requested_operator_clarifications=[
                        {
                            "question": (
                                "Recover Docker bind mounts, then continue this directive from the latest "
                                "campaign baseline."
                            ),
                            "blocked_gate": "docker_mount_fault",
                            "target_artifact": str(
                                latest_progress.get("target_artifact", "") if isinstance(latest_progress, Mapping) else ""
                            ),
                        }
                    ],
                    extra_fields={
                        "infrastructure_fault": True,
                        "failed_gates": ["docker_mount_fault"],
                        "blocked_requirements": ["docker_bind_mount_io_recovery"],
                        "support_required_before_continue": False,
                        "next_required_operator_action": "recover_docker_mount_and_requeue",
                        "container_exit_code": int(state.get("exit_code", MOUNT_FAULT_EXIT_CODE) or MOUNT_FAULT_EXIT_CODE),
                    },
                )
                failed += 1
                rows.append(packet)
                continue
            latest_progress = _latest_child_progress(child)
            recovery = _missing_container_recovery_evidence(child, latest_progress)
            lifecycle = _classify_terminal_child_without_return(
                child,
                inspect_state=state,
                latest_progress=latest_progress,
                recovery=recovery,
            )
            if str(lifecycle.get("child_lifecycle_classification", "") or "") in {
                "intentional_stop",
                "productive_pass_completed_not_review_ready",
                "blocked_pass_completed_not_review_ready",
            }:
                updated_child = _record_terminal_child_without_review_return(
                    operator_root,
                    child=child,
                    lifecycle=lifecycle,
                    recovery=recovery,
                    inspect_state=state,
                )
                if str(lifecycle.get("child_lifecycle_classification", "") or "") == "productive_pass_completed_not_review_ready":
                    requeued_missing_container += 1
                stale_missing_container_children.append(dict(lifecycle))
                rows.append(updated_child)
                continue
            packet = record_child_return_packet(
                operator_root,
                child_run_id=child_id,
                outcome_summary="Child container exited without a valid return packet.",
                artifacts=[],
                verification_evidence=[],
                risks=["missing_child_return_packet"],
                requested_follow_up="operator_review_failed_child",
                result_state="failed",
            )
            failed += 1
            rows.append(packet)
    lifecycle_backfill = _backfill_terminal_child_lifecycle_assessments(operator_root)
    backfill_rows = [
        dict(row)
        for row in list(lifecycle_backfill.get("records", []) or [])
        if isinstance(row, Mapping)
    ]
    rows.extend(backfill_rows)
    cleanup = cleanup_terminal_child_containers(operator_root, runner=effective_runner)
    return {
        "ok": True,
        "schema_name": "ConveyorChildReconciliation",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "inspected_child_count": inspected,
        "collected_return_count": collected,
        "failed_return_count": failed,
        "recovered_missing_container_return_count": recovered_missing_container,
        "requeued_missing_container_child_count": requeued_missing_container,
        "productive_pass_requeued_count": sum(
            1
            for row in rows
            if isinstance(row, Mapping)
            and str(row.get("child_lifecycle_classification", "") or "") == "productive_pass_completed_not_review_ready"
        ),
        "resident_productive_finalized_count": resident_productive_finalized,
        "resident_no_first_checkpoint_finalized_count": resident_no_first_checkpoint_finalized,
        "productive_pass_backfill_count": int(lifecycle_backfill.get("productive_pass_backfill_count", 0) or 0),
        "blocked_pass_requeued_count": sum(
            1
            for row in rows
            if isinstance(row, Mapping)
            and str(row.get("child_lifecycle_classification", "") or "") == "blocked_pass_completed_not_review_ready"
        ),
        "blocked_pass_backfill_count": int(lifecycle_backfill.get("blocked_pass_backfill_count", 0) or 0),
        "terminal_child_lifecycle_backfill_count": int(
            lifecycle_backfill.get("terminal_child_lifecycle_backfill_count", 0) or 0
        ),
        "stale_missing_container_child_count": stale_missing_container,
        "stale_missing_container_children": stale_missing_container_children,
        "cleaned_container_count": int(cleanup.get("cleaned_container_count", 0) or 0),
        "failed_container_cleanup_count": int(cleanup.get("failed_cleanup_count", 0) or 0),
        "container_cleanup": cleanup,
        "records": rows,
    }


def _decide_return(
    operator_root: str | Path,
    *,
    return_packet_id: str,
    decision_state: str,
    operator_note: str = "",
    feedback: str = "",
) -> dict[str, Any]:
    if decision_state not in {"accepted", "requeued", "rejected", "split"}:
        raise ConveyorValidationError(f"unsupported decision_state: {decision_state}")
    packet = _read_json(_return_path(operator_root, return_packet_id))
    if not packet:
        raise ConveyorValidationError(f"return_packet_id not found: {return_packet_id}")
    now = _utc_now()
    packet["review_state"] = decision_state
    packet["operator_note"] = str(operator_note or "")
    packet["operator_feedback"] = str(feedback or "")
    packet["reviewed_at"] = now
    _write_json(_return_path(operator_root, return_packet_id), packet)
    directive = _load_directive(operator_root, str(packet.get("directive_id", "") or ""))
    directive["state"] = decision_state
    directive["active_child_run_id"] = ""
    directive["updated_at"] = now
    if decision_state == "requeued":
        directive["state"] = "requeued"
        directive["operator_feedback"] = str(feedback or operator_note or "")
        directive["requeue_count"] = int(directive.get("requeue_count", 0) or 0) + 1
    _write_json(_directive_path(operator_root, str(directive.get("directive_id", ""))), directive)
    decision = {
        "schema_name": "ConveyorReturnDecision",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": now,
        "return_packet_id": return_packet_id,
        "directive_id": str(directive.get("directive_id", "")),
        "decision_state": decision_state,
        "operator_note": str(operator_note or ""),
        "operator_feedback": str(feedback or ""),
    }
    _append_ledger(operator_root, "return_decisions", decision)
    return decision


def _kernel_depth_feedback(
    *,
    directive: Mapping[str, Any],
    packet: Mapping[str, Any],
    missing_artifacts: list[str],
    missing_evidence: list[str],
    campaign_state: Mapping[str, Any] | None = None,
) -> str:
    support_requests = list(packet.get("missing_capability_requests", []) or [])
    title = str(directive.get("directive_id", "") or "this directive")
    campaign = dict(campaign_state or {})
    missing_gates = [
        str(item)
        for item in list(campaign.get("missing_build_readiness_gates", []) or [])
        if str(item)
    ]
    readiness_level = str(campaign.get("readiness_level", "") or "").strip()
    return " ".join(
        [
            f"Kernel evaluation found that {title} needs additional depth before final operator review.",
            "Continue from the previous return packet and artifacts instead of restarting.",
            "Expand the scaffold into full technical documentation with subsystem requirements, architecture, interfaces, dependencies, validation strategy, implementation readiness, risks, safety and governance gates, and concrete follow-up questions.",
            "Keep high-risk biomedical, clinical, security, or unsafe procedural details at architecture/review level until trusted knowledge packs and operator approval are available.",
            f"Current campaign readiness level: {readiness_level}." if readiness_level else "",
            (
                f"Missing build-readiness gates: {', '.join(missing_gates)}."
                if missing_gates
                else "All build-readiness gates were satisfied."
            ),
            (
                f"Missing artifacts: {', '.join(missing_artifacts)}."
                if missing_artifacts
                else "Required build-grade artifacts were present."
            ),
            (
                f"Missing evidence: {', '.join(missing_evidence)}."
                if missing_evidence
                else "Required build-grade evidence was present."
            ),
            (
                f"Resolve or restate {len(support_requests)} kernel knowledge/skill support request(s) in the next packet."
                if support_requests
                else "Request kernel knowledge or skill checkout only for concrete gaps."
            ),
        ]
    )


def _failed_return_recovery_target_artifact(
    *,
    campaign_state: Mapping[str, Any],
    campaign_manifest: Mapping[str, Any],
    micro_adjustment: Mapping[str, Any],
    next_unresolved_gate_artifact: str,
) -> str:
    micro_target = str(micro_adjustment.get("target_artifact", "") or "").strip()
    if micro_target in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER and micro_target != "technical_documentation.md":
        return micro_target
    for source in (campaign_manifest, campaign_state):
        hardware = dict(source.get("hardware_build_packet_assessment", {}) or {})
        hardware_next = str(hardware.get("next_unresolved_artifact", "") or "").strip()
        if hardware_next in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER and hardware_next != "technical_documentation.md":
            return hardware_next
    for source in (campaign_manifest, campaign_state):
        hardware = dict(source.get("hardware_build_packet_assessment", {}) or {})
        hardware_next = str(hardware.get("next_unresolved_artifact", "") or "").strip()
        hardware_failed = {str(item) for item in list(hardware.get("failed_gates", []) or [])}
        if (
            hardware_next == "risk_controls.json"
            or "missing_hardware_fmea_controls" in hardware_failed
        ):
            return "risk_controls.json"
    next_target = str(next_unresolved_gate_artifact or "").strip()
    if next_target in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER and next_target != "technical_documentation.md":
        return next_target
    draft_delta = dict(campaign_manifest.get("draft_delta_quality", {}) or campaign_state.get("draft_delta_quality", {}) or {})
    draft_target = str(draft_delta.get("target_artifact", "") or "").strip()
    if draft_target in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER and draft_target != "technical_documentation.md":
        return draft_target
    return ""


def _failed_return_recovery_evidence(
    *,
    directive_id: str,
    target_artifact: str,
    child_record: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
    campaign_manifest: Mapping[str, Any],
) -> dict[str, Any]:
    child_directive_id = str(child_record.get("directive_id", "") or "")
    same_child_directive = bool(child_record) and child_directive_id == str(directive_id or "")
    target = str(target_artifact or "").strip()
    progress_target = str(latest_progress.get("target_artifact", "") or "").strip()
    progress_same_target = bool(progress_target and target and progress_target == target)
    progress_same_directive = str(latest_progress.get("directive_id", "") or directive_id) == str(directive_id or "")
    try:
        artifact_delta_count = int(latest_progress.get("artifact_delta_count", 0) or 0)
    except (TypeError, ValueError):
        artifact_delta_count = 0
    materialized_files = [
        str(item)
        for item in list(latest_progress.get("materialized_expected_files", []) or [])
        if str(item).strip()
    ]
    progress_changed_behavior = bool(
        latest_progress
        and same_child_directive
        and progress_same_directive
        and progress_same_target
        and (
            bool(latest_progress.get("meaningful_delta", False))
            or artifact_delta_count > 0
            or materialized_files
            or bool(latest_progress.get("hardware_build_packet_contract_applied", False))
        )
    )
    draft_delta = dict(campaign_manifest.get("draft_delta_quality", {}) or {})
    draft_target = str(draft_delta.get("target_artifact", "") or "").strip()
    draft_changed_behavior = bool(
        target
        and draft_target == target
        and (
            bool(draft_delta.get("draft_changed_from_canonical", False))
            or bool(draft_delta.get("draft_changed_since_last_review", False))
            or str(draft_delta.get("draft_hash", "") or "").strip()
        )
    )
    references = []
    if progress_changed_behavior:
        references.append("latest_resident_progress")
    if draft_changed_behavior:
        references.append("draft_delta_quality")
    return {
        "has_evidence": bool(progress_changed_behavior or draft_changed_behavior),
        "progress_changed_behavior": progress_changed_behavior,
        "draft_changed_behavior": draft_changed_behavior,
        "evidence_refs": references,
        "progress_target_artifact": progress_target,
        "draft_target_artifact": draft_target,
        "work_order_id": str(latest_progress.get("work_order_id", "") or ""),
        "artifact_delta_count": artifact_delta_count,
        "materialized_expected_files": materialized_files,
    }


def _artifact_rows_for_target(payload: Mapping[str, Any], target_artifact: str) -> list[dict[str, Any]]:
    target = str(target_artifact or "")
    row_keys = tuple(
        dict(FULL_DIVE_HARDWARE_REQUIRED_FIELDS.get(target, {}) or {}).get("row_keys", ())
        or ("rows", "items", "interfaces", "fixtures", "controls", "risks")
    )
    rows: list[dict[str, Any]] = []
    for key in row_keys:
        value = payload.get(key)
        if isinstance(value, list):
            rows.extend(dict(item) for item in value if isinstance(item, Mapping))
    if not rows and isinstance(payload.get("rows"), list):
        rows.extend(dict(item) for item in list(payload.get("rows", []) or []) if isinstance(item, Mapping))
    return rows


def _row_field_present(row: Mapping[str, Any], field: str) -> bool:
    normalized = normalize_support_field_name(field)
    aliases = {
        normalized,
        str(field or "").strip(),
    }
    if normalized == "latency_budget":
        aliases.update({"latency", "latency_budget_ms"})
    if normalized == "electrical_isolation":
        aliases.update({"isolation"})
    if normalized == "validation_hooks":
        aliases.update({"validation_hook", "validation_hooks"})
    if normalized == "device_capability_manifest_ref":
        aliases.update({"device_manifest_ref", "device_capability_manifest", "manifest_ref"})
    if normalized == "validation_fixture_ref":
        aliases.update({"fixture_ref", "fixture_refs", "validation_fixture_refs"})
    if normalized == "linked_risk_control_ref":
        aliases.update({"risk_ref", "risk_refs", "linked_risk_control_refs"})
    if normalized == "bom_ref":
        aliases.update({"bom_refs", "bill_of_materials_ref", "linked_bom_refs"})
    for key, value in row.items():
        key_normalized = normalize_support_field_name(key)
        if key_normalized not in {normalize_support_field_name(alias) for alias in aliases}:
            continue
        if isinstance(value, (list, tuple, set, dict)):
            if value:
                return True
        elif str(value or "").strip():
            return True
    return False


def _full_dive_interface_required_fields_for_partial_closure() -> list[str]:
    contract = dict(FULL_DIVE_HARDWARE_REQUIRED_FIELDS.get("interface_specifications.json", {}) or {})
    fields = _support_field_coverage_list(contract.get("required_fields", []))
    for field in (
        "bom_ref",
        "validation_fixture_ref",
        "linked_risk_control_ref",
    ):
        if field not in fields:
            fields.append(field)
    return fields


def _remaining_linked_artifacts_from_hardware_assessment(
    assessment: Mapping[str, Any],
    *,
    closed_artifact: str,
) -> list[str]:
    gaps = dict(assessment.get("field_gaps_by_artifact", {}) or {})
    failed = [str(item) for item in list(assessment.get("failed_artifacts", []) or []) if str(item).strip()]
    failed.extend(str(key) for key, value in gaps.items() if key and value)
    missing_docs = [
        str(item)
        for item in list(assessment.get("missing_required_hardware_artifacts", []) or [])
        if str(item).strip()
    ]
    failed.extend(missing_docs)
    ordered: list[str] = []
    for artifact in list(FULL_DIVE_LINKED_ARTIFACT_RETARGET_ORDER) + list(BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER):
        if artifact == closed_artifact:
            continue
        if artifact in set(failed) and artifact not in ordered:
            ordered.append(artifact)
    return ordered


def _assess_target_artifact_partial_closure(
    operator_root: str | Path,
    *,
    directive_id: str,
    target_artifact: str,
    hardware_assessment: Mapping[str, Any],
    latest_progress: Mapping[str, Any],
) -> dict[str, Any]:
    if target_artifact != "interface_specifications.json":
        return {}
    if not bool(hardware_assessment.get("required", False)):
        return {}
    if bool(hardware_assessment.get("hardware_build_packet_ready", False)):
        return {}
    draft_path = _campaign_root(operator_root, directive_id) / "drafts" / target_artifact
    artifact = _read_json(draft_path)
    if not artifact:
        return {}
    rows = _artifact_rows_for_target(artifact, target_artifact)
    if not rows:
        return {}
    required_fields = _full_dive_interface_required_fields_for_partial_closure()
    closed_fields = [
        field
        for field in required_fields
        if any(_row_field_present(row, field) for row in rows)
    ]
    missing_fields = [field for field in required_fields if field not in set(closed_fields)]
    if missing_fields:
        return {}
    row_resolution = str(latest_progress.get("support_target_row_resolution_state", "") or "")
    resolved_rows = [
        str(item)
        for item in list(latest_progress.get("support_resolved_target_row_ids", []) or [])
        if str(item).strip()
    ]
    remaining_artifacts = _remaining_linked_artifacts_from_hardware_assessment(
        hardware_assessment,
        closed_artifact=target_artifact,
    )
    if not remaining_artifacts:
        return {}
    evidence = {
        "schema_name": "TargetArtifactClosureEvidence",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "directive_id": directive_id,
        "target_artifact": target_artifact,
        "target_artifact_closure_state": "partial_closed_linked_artifacts_remaining",
        "closed_target_artifact": target_artifact,
        "closed_fields": closed_fields,
        "remaining_linked_artifact_gaps": remaining_artifacts,
        "remaining_artifacts": remaining_artifacts,
        "next_linked_artifact_target": remaining_artifacts[0],
        "partial_target_correct_closure": True,
        "hardware_build_packet_ready": False,
        "support_target_row_resolution_state": row_resolution or ("resolved" if resolved_rows else "artifact_fields_complete"),
        "support_resolved_target_row_ids": resolved_rows,
        "grants_execution_authority": False,
    }
    evidence["target_artifact_closure_evidence_id"] = _record_id(
        "target-artifact-closure",
        directive_id,
        target_artifact,
        ",".join(closed_fields),
        ",".join(remaining_artifacts),
    )
    latest_path = _conveyor_root(operator_root) / "target_artifact_closure_evidence_latest.json"
    latest = _read_json(latest_path)
    if str(latest.get("target_artifact_closure_evidence_id", "") or "") != str(
        evidence["target_artifact_closure_evidence_id"]
    ):
        _append_ledger(operator_root, "target_artifact_closure_evidence", evidence)
        _write_json(latest_path, evidence)
    return evidence


def _retarget_initial_work_order_after_partial_closure(
    operator_root: str | Path,
    *,
    directive: Mapping[str, Any],
    target_artifact: str,
) -> tuple[dict[str, Any], str, dict[str, Any]]:
    directive_id = str(directive.get("directive_id", "") or "").strip()
    target = str(target_artifact or "").strip()
    if not directive_id or target != "interface_specifications.json":
        return dict(directive), target, {}
    hardware_assessment = _assess_hardware_build_packet(
        operator_root,
        directive_id,
        directive=directive,
        require_return_packet=False,
    )
    closure = _assess_target_artifact_partial_closure(
        operator_root,
        directive_id=directive_id,
        target_artifact=target,
        hardware_assessment=hardware_assessment,
        latest_progress={},
    )
    next_target = str(closure.get("next_linked_artifact_target", "") or "").strip()
    if next_target not in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER or next_target == target:
        return dict(directive), target, closure

    updated = dict(_read_json(_directive_path(operator_root, directive_id)) or directive)
    metadata = dict(updated.get("metadata", {}) or {})
    previous_context = str(metadata.get("initial_work_order_context", "") or "").strip()
    metadata["initial_work_order_target_artifact"] = next_target
    metadata["continuous_campaign_latest_target_artifact"] = next_target
    metadata["support_blocker_target_artifact"] = next_target
    metadata["initial_work_order_capability"] = "directive_build_grade_synthesis_pack"
    metadata["initial_work_order_retargeted_from_artifact"] = target
    metadata["initial_work_order_retarget_reason"] = "partial_target_correct_closure"
    metadata["support_retargeted_from_artifact"] = target
    metadata["support_retargeted_to_artifact"] = next_target
    metadata["support_retarget_reason"] = "partial_target_correct_closure"
    metadata["current_support_request_repaired"] = True
    metadata["partial_target_correct_closure"] = True
    metadata["closed_target_artifact"] = target
    metadata["next_linked_artifact_target"] = next_target
    metadata["remaining_linked_artifact_gaps"] = list(closure.get("remaining_linked_artifact_gaps", []) or [])
    metadata["target_artifact_closure_evidence_id"] = str(
        closure.get("target_artifact_closure_evidence_id", "") or ""
    )
    if not previous_context or target in previous_context:
        metadata["initial_work_order_context"] = _campaign_artifact_guidance(
            next_target,
            fallback=(
                f"{target} has enough review-only field closure for this layer. Continue on "
                f"{next_target} and close the linked BOM, risk, fixture, safety, research, or regulatory gaps "
                "that still block build-review readiness."
            ),
            directive=updated,
            failed_gates=list(hardware_assessment.get("failed_gates", []) or []),
        )
    updated["metadata"] = metadata
    updated["updated_at"] = _utc_now()
    _write_json(_directive_path(operator_root, directive_id), updated)

    manifest_path = _campaign_manifest_path(operator_root, directive_id)
    manifest = _read_json(manifest_path)
    if isinstance(manifest, Mapping):
        manifest_update = dict(manifest)
        manifest_update["partial_target_correct_closure"] = True
        manifest_update["target_artifact_closure_state"] = str(
            closure.get("target_artifact_closure_state", "") or ""
        )
        manifest_update["closed_target_artifact"] = target
        manifest_update["next_unresolved_gate_artifact"] = next_target
        manifest_update["weakest_failed_artifact"] = next_target
        manifest_update["next_linked_artifact_target"] = next_target
        manifest_update["remaining_linked_artifact_gaps"] = list(
            closure.get("remaining_linked_artifact_gaps", []) or []
        )
        schema_resonance = dict(manifest_update.get("schema_resonance", {}) or {})
        schema_resonance["target_artifact"] = next_target
        schema_resonance["target_retargeted_from_artifact"] = target
        schema_resonance["target_retarget_reason"] = "partial_target_correct_closure"
        manifest_update["schema_resonance"] = schema_resonance
        prototype_cluster = dict(manifest_update.get("prototype_cluster_closure", {}) or {})
        prototype_cluster["next_unresolved_artifact"] = next_target
        prototype_cluster["target_retargeted_from_artifact"] = target
        prototype_cluster["target_retarget_reason"] = "partial_target_correct_closure"
        manifest_update["prototype_cluster_closure"] = prototype_cluster
        manifest_update["target_artifact_closure_evidence_id"] = str(
            closure.get("target_artifact_closure_evidence_id", "") or ""
        )
        manifest_update["updated_at"] = updated["updated_at"]
        _write_json(manifest_path, manifest_update)

    _append_ledger(
        operator_root,
        "continuous_campaign_events",
        {
            "event": "partial_target_closure_retarget",
            "generated_at": updated["updated_at"],
            "directive_id": directive_id,
            "closed_target_artifact": target,
            "target_artifact": next_target,
            "next_linked_artifact_target": next_target,
            "target_artifact_closure_evidence_id": str(
                closure.get("target_artifact_closure_evidence_id", "") or ""
            ),
            "grants_execution_authority": False,
        },
    )
    return updated, next_target, closure


def _evaluate_return_packet_depth(
    operator_root: str | Path,
    packet: Mapping[str, Any],
    *,
    state_root: str | Path | None = None,
    max_kernel_requeues: int,
) -> dict[str, Any]:
    directive_id = str(packet.get("directive_id", "") or "")
    try:
        directive = _load_directive(operator_root, directive_id)
    except ConveyorValidationError as exc:
        return {
            "schema_name": "ConveyorKernelReturnEvaluation",
            "schema_version": CONVEYOR_SCHEMA_VERSION,
            "generated_at": _utc_now(),
            "directive_id": directive_id,
            "return_packet_id": str(packet.get("return_packet_id", "") or ""),
            "decision": "operator_review_required",
            "reasons": ["stale_directive_reference"],
            "missing_artifacts": [],
            "missing_evidence": [],
            "requested_operator_clarifications": [
                {
                    "clarification_id": _record_id(
                        "clarification",
                        str(packet.get("return_packet_id", "") or ""),
                        "stale_directive_reference",
                    ),
                    "blocked_gate": "stale_directive_reference",
                    "question": (
                        "This return packet references a directive record that is no longer available. "
                        "Should Novali restore, reject, or archive this orphaned return?"
                    ),
                }
            ],
            "support_request_ids": [],
            "campaign_state": {
                "readiness_level": "orphaned_return",
                "stale_directive_reference": True,
                "message": str(exc),
            },
            "feedback": "Resolve the stale directive reference before continuing this return packet.",
            "stale_directive_reference": True,
            "orphaned_return": True,
        }
    artifacts = {str(item) for item in list(packet.get("artifacts", []) or [])}
    evidence = {str(item) for item in list(packet.get("verification_evidence", []) or [])}
    risks = {str(item) for item in list(packet.get("risks", []) or [])}
    missing_artifacts = sorted(BUILD_GRADE_ALL_REQUIRED_ARTIFACTS - artifacts)
    missing_evidence = sorted((BUILD_GRADE_REQUIRED_EVIDENCE | {BUILD_GRADE_STRUCTURED_EVIDENCE}) - evidence)
    campaign_state = _campaign_depth_assessment(
        packet,
        missing_artifacts=missing_artifacts,
        missing_evidence=missing_evidence,
    )
    campaign_manifest = _read_json(_campaign_manifest_path(operator_root, directive_id)) if directive_id else {}
    draft_delta_quality = dict(campaign_manifest.get("draft_delta_quality", {}) or {})
    prototype_cluster_closure = _assess_prototype_cluster_closure(directive, campaign_manifest or campaign_state)
    next_unresolved_gate_artifact = str(
        prototype_cluster_closure.get("next_unresolved_artifact", "")
        or _weakest_failed_artifact_from_manifest(campaign_manifest)
        or _weakest_failed_artifact_from_manifest(campaign_state)
        or ""
    )
    child_record = _read_json(_child_path(operator_root, str(packet.get("child_run_id", "") or "")))
    latest_progress = _latest_child_progress(child_record) if child_record else {}
    selected_hardware_assessment = _assess_hardware_build_packet(
        operator_root,
        directive_id,
        directive=directive,
        active_child=child_record,
        packet=packet,
    )
    selected_hardware_assessment = _prefer_richer_hardware_assessment(
        selected_hardware_assessment,
        dict(campaign_manifest.get("hardware_build_packet_assessment", {}) or {}),
    )
    if bool(selected_hardware_assessment.get("required", False)):
        campaign_state = dict(campaign_state)
        campaign_state["hardware_build_packet_assessment"] = dict(selected_hardware_assessment)
        if not bool(selected_hardware_assessment.get("hardware_build_packet_ready", False)):
            campaign_state["prototype_ready"] = False
            hardware_next = str(selected_hardware_assessment.get("next_unresolved_artifact", "") or "").strip()
            if hardware_next:
                campaign_state["next_unresolved_gate_artifact"] = hardware_next
            missing_gates = list(campaign_state.get("missing_build_readiness_gates", []) or [])
            for gate in list(selected_hardware_assessment.get("failed_gates", []) or []):
                _append_unique(missing_gates, str(gate))
            campaign_state["missing_build_readiness_gates"] = missing_gates
    latest_progress_target = str(latest_progress.get("target_artifact", "") or "").strip()
    latest_progress_closed_gates = [
        str(item)
        for item in list(latest_progress.get("closed_failed_gates", []) or [])
        if str(item).strip()
    ]
    latest_progress_remaining_gates = [
        str(item)
        for item in list(latest_progress.get("remaining_failed_gates", []) or latest_progress.get("unchanged_failed_gates", []) or [])
        if str(item).strip()
    ]
    latest_progress_gate_closure_consumed = bool(
        latest_progress_target
        and latest_progress_closed_gates
        and not latest_progress_remaining_gates
    )
    if latest_progress_gate_closure_consumed and not next_unresolved_gate_artifact:
        for artifact in _directive_gate_target_priority(directive):
            if artifact != latest_progress_target and artifact in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER:
                next_unresolved_gate_artifact = artifact
                break
    draft_delta_quality_gate_failures = [
        str(item)
        for item in list(draft_delta_quality.get("failed_gates", []) or [])
        if str(item).strip()
    ]
    followup_required = bool(
        str(draft_delta_quality.get("target_artifact", "") or "").strip()
        and (
            str(draft_delta_quality.get("draft_hash", "") or "").strip()
            or draft_delta_quality_gate_failures
        )
    )
    new_depth_since_last_review = bool(
        draft_delta_quality.get("draft_changed_from_canonical", False)
        and draft_delta_quality.get("draft_changed_since_last_review", False)
        and not draft_delta_quality_gate_failures
    )
    operator_followup_delta_satisfied = bool(
        not followup_required or bool(draft_delta_quality.get("operator_followup_delta_satisfied", False))
    )
    if draft_delta_quality:
        campaign_state = dict(campaign_state)
        campaign_state["draft_delta_quality"] = draft_delta_quality
    if prototype_cluster_closure:
        campaign_state = dict(campaign_state)
        campaign_state["prototype_cluster_closure"] = prototype_cluster_closure
        if next_unresolved_gate_artifact:
            campaign_state["next_unresolved_gate_artifact"] = next_unresolved_gate_artifact
    if bool(selected_hardware_assessment.get("required", False)):
        hardware_next = str(selected_hardware_assessment.get("next_unresolved_artifact", "") or "").strip()
        if not bool(selected_hardware_assessment.get("hardware_build_packet_ready", False)) and hardware_next:
            next_unresolved_gate_artifact = hardware_next
            campaign_state["next_unresolved_gate_artifact"] = hardware_next
        elif bool(selected_hardware_assessment.get("hardware_build_packet_ready", False)) and next_unresolved_gate_artifact == hardware_next:
            next_unresolved_gate_artifact = ""
            campaign_state.pop("next_unresolved_gate_artifact", None)
    partial_target_closure = _assess_target_artifact_partial_closure(
        operator_root,
        directive_id=directive_id,
        target_artifact=next_unresolved_gate_artifact or latest_progress_target,
        hardware_assessment=selected_hardware_assessment,
        latest_progress=latest_progress,
    )
    if partial_target_closure:
        campaign_state = dict(campaign_state)
        next_linked_artifact = str(partial_target_closure.get("next_linked_artifact_target", "") or "")
        if next_linked_artifact:
            next_unresolved_gate_artifact = next_linked_artifact
            campaign_state["next_unresolved_gate_artifact"] = next_linked_artifact
        campaign_state["partial_target_correct_closure"] = True
        campaign_state["target_artifact_closure_state"] = str(
            partial_target_closure.get("target_artifact_closure_state", "") or ""
        )
        campaign_state["closed_target_artifact"] = str(
            partial_target_closure.get("closed_target_artifact", "") or ""
        )
        campaign_state["next_linked_artifact_target"] = next_linked_artifact
        campaign_state["remaining_linked_artifact_gaps"] = list(
            partial_target_closure.get("remaining_linked_artifact_gaps", []) or []
        )
        campaign_state["target_artifact_closure_evidence_id"] = str(
            partial_target_closure.get("target_artifact_closure_evidence_id", "") or ""
        )
    micro_adjustment = _campaign_micro_adjustment_requirement(
        operator_root,
        directive=directive,
        packet=packet,
        campaign_manifest=campaign_manifest,
    )
    micro_adjustment_required = bool(micro_adjustment.get("required", False))
    if micro_adjustment_required:
        campaign_state = dict(campaign_state)
        campaign_state["micro_adjustment_required"] = True
        campaign_state["micro_adjustment"] = dict(micro_adjustment)
        micro_target = str(micro_adjustment.get("target_artifact", "") or "").strip()
        closed_target = str(
            dict(campaign_state.get("target_artifact_closure_state", {}) or {}).get("closed_target_artifact", "")
            if isinstance(campaign_state.get("target_artifact_closure_state", {}), Mapping)
            else campaign_state.get("closed_target_artifact", "")
            or ""
        )
        partial_next = str(campaign_state.get("next_linked_artifact_target", "") or "")
        if micro_target and bool(campaign_state.get("partial_target_correct_closure", False)) and micro_target == closed_target and partial_next:
            next_unresolved_gate_artifact = partial_next
            campaign_state["next_unresolved_gate_artifact"] = partial_next
            campaign_state["micro_adjustment_superseded_by_partial_target_closure"] = True
        elif micro_target:
            next_unresolved_gate_artifact = micro_target
            campaign_state["next_unresolved_gate_artifact"] = micro_target
    requeue_count = int(directive.get("requeue_count", 0) or 0)
    child_support_requests = [
        dict(item)
        for item in list(packet.get("missing_capability_requests", []) or [])
        if isinstance(item, Mapping)
    ]
    support_requests = [
        _support_request_from_child_request(
            operator_root,
            state_root=state_root,
            directive=directive,
            packet=packet,
            child_request=item,
        )
        for item in child_support_requests
    ]
    for related_support in _related_support_requests_for_packet(
        operator_root,
        packet,
        capability="directive_build_grade_synthesis_pack",
    ):
        if not any(
            str(item.get("support_request_id", "") or "") == str(related_support.get("support_request_id", "") or "")
            for item in support_requests
        ):
            support_requests.append(related_support)
    unresolved_support_requests = [
        item
        for item in support_requests
        if str(item.get("support_state", "") or "") == "pending_operator_review"
    ]
    satisfied_support_requests = [
        item for item in support_requests if str(item.get("support_state", "") or "") == "satisfied"
    ]
    metadata = dict(directive.get("metadata", {}) or {})
    build_grade_assessment = dict(
        dict(campaign_state.get("build_grade_artifact_assessment", {}) or {})
    )
    structured_reasons: list[str] = []
    if bool(build_grade_assessment.get("generic_template_content", False)):
        structured_reasons.append("generic_template_content")
    if missing_artifacts:
        structured_reasons.append("missing_required_artifact")
    if int(build_grade_assessment.get("unsupported_claim_count", 0) or 0) > 0:
        structured_reasons.append("insufficient_claim_evidence")
        structured_reasons.append("synthesis_pack_required")
    if int(build_grade_assessment.get("novelty_count", 0) or 0) < 2 and not missing_artifacts:
        structured_reasons.append("no_meaningful_novelty")
    high_risk_needs_clarification = int(build_grade_assessment.get("high_risk_claim_count", 0) or 0) > 0
    unresolved_operator_clarifications = [
        dict(item)
        for item in list(packet.get("requested_operator_clarifications", []) or [])
        if isinstance(item, Mapping) and not bool(item.get("resolved", False))
    ]
    if high_risk_needs_clarification:
        unresolved_operator_clarifications.append(
            {
                "clarification_id": _record_id(
                    "clarification",
                    str(packet.get("return_packet_id", "") or ""),
                    "safety_review_required",
                ),
                "blocked_gate": "safety_review_required",
                "question": (
                    "May Novali continue treating high-risk claims as architecture/prototype-planning "
                    "material, or should the directive be narrowed before the next conveyor pass?"
                ),
                "proposed_options": [
                    "Continue with non-invasive simulation/tabletop prototype planning only.",
                    "Narrow or split the high-risk subsystem before further depth work.",
                    "Reject this path for now.",
                ],
            }
        )
    if "synthesis_pack_required" in structured_reasons:
        support_requests.append(
            _support_request_from_child_request(
                operator_root,
                state_root=state_root,
                directive=directive,
                packet=packet,
                child_request={
                    "request_type": "knowledge_checkout",
                    "capability": "directive_build_grade_synthesis_pack",
                    "reason": "Build-grade claim evidence is missing or unsupported.",
                    "kernel_channel": "kernel_return_evaluation",
                },
            )
        )
        unresolved_support_requests = [
            item
            for item in support_requests
            if str(item.get("support_state", "") or "") == "pending_operator_review"
        ]
        satisfied_support_requests = [
            item for item in support_requests if str(item.get("support_state", "") or "") == "satisfied"
        ]
    support_assisted_requeue_count = int(metadata.get("support_assisted_requeue_count", 0) or 0)
    support_assisted_requeue_available = bool(satisfied_support_requests) and support_assisted_requeue_count < 1
    overnight_enabled, overnight_target, overnight_completed = _overnight_incubation_budget(metadata)
    overnight_incubation_candidate_ready = bool(campaign_state.get("prototype_ready", False))
    overnight_incubation_available = (
        overnight_enabled
        and overnight_target > 0
        and overnight_completed < overnight_target
        and overnight_incubation_candidate_ready
    )
    expects_build_grade = _directive_expects_build_grade_documentation(directive)
    build_grade_assessment = dict(campaign_state.get("build_grade_artifact_assessment", {}) or {})
    handoff_assessment = dict(campaign_state.get("build_grade_handoff_assessment", {}) or {})
    campaign_prototype_ready = bool(campaign_state.get("prototype_ready", False)) and bool(
        prototype_cluster_closure.get("cluster_closed", True)
    )
    failed_or_missing_return = bool("missing_child_return_packet" in risks or "runtime_failure" in risks)
    stale_depth_clarification_gates = {
        "resident_artifact_delta_after_support",
        "resident_worker_stalled",
        "quality_depth_target_selection",
    }
    blocking_operator_clarifications: list[dict[str, Any]] = []
    superseded_operator_clarifications: list[dict[str, Any]] = []
    superseded_stale_clarifications: list[dict[str, Any]] = []
    for clarification in unresolved_operator_clarifications:
        blocked_gate = str(
            clarification.get("blocked_gate", "")
            or clarification.get("blocked_requirement", "")
            or ""
        )
        clarification_target = str(clarification.get("target_artifact", "") or "").strip()
        stale_after_progress_closure = bool(
            latest_progress_gate_closure_consumed
            and clarification_target
            and clarification_target == latest_progress_target
            and blocked_gate in stale_depth_clarification_gates
        )
        if (
            campaign_prototype_ready
            and not missing_artifacts
            and not missing_evidence
            and not unresolved_support_requests
            and blocked_gate in stale_depth_clarification_gates
        ):
            superseded_operator_clarifications.append(dict(clarification))
        elif stale_after_progress_closure:
            superseded = dict(clarification)
            superseded["superseded_reason"] = "latest_progress_closed_requested_gates"
            superseded["closed_failed_gates"] = list(latest_progress_closed_gates)
            superseded_stale_clarifications.append(superseded)
            superseded_operator_clarifications.append(superseded)
        else:
            blocking_operator_clarifications.append(dict(clarification))
    prototype_ready_gate_failures: list[str] = []
    if missing_artifacts:
        _append_unique(prototype_ready_gate_failures, "missing_build_grade_artifacts")
    if missing_evidence:
        _append_unique(prototype_ready_gate_failures, "missing_build_grade_evidence")
    if not campaign_prototype_ready:
        _append_unique(prototype_ready_gate_failures, "prototype_not_ready")
        if list(campaign_state.get("missing_build_readiness_gates", []) or []):
            _append_unique(prototype_ready_gate_failures, "missing_build_readiness_gates")
        if bool(build_grade_assessment.get("generic_template_content", False)):
            _append_unique(prototype_ready_gate_failures, "generic_template_content")
        if bool(handoff_assessment.get("handoff_present", False)) and not bool(
            handoff_assessment.get("handoff_ready", False)
        ):
            _append_unique(prototype_ready_gate_failures, "incomplete_implementation_handoff")
    for reason in structured_reasons:
        _append_unique(prototype_ready_gate_failures, reason)
    if next_unresolved_gate_artifact:
        _append_unique(prototype_ready_gate_failures, "prototype_cluster_not_closed")
    if followup_required and not operator_followup_delta_satisfied:
        _append_unique(prototype_ready_gate_failures, "operator_followup_delta_not_satisfied")
        for reason in draft_delta_quality_gate_failures:
            _append_unique(prototype_ready_gate_failures, reason)
    if micro_adjustment_required:
        _append_unique(prototype_ready_gate_failures, "micro_adjustment_required")
        for reason in list(micro_adjustment.get("reasons", []) or []):
            _append_unique(prototype_ready_gate_failures, str(reason))

    failed_return_recovery_target = _failed_return_recovery_target_artifact(
        campaign_state=campaign_state,
        campaign_manifest=campaign_manifest,
        micro_adjustment=micro_adjustment if micro_adjustment_required else {},
        next_unresolved_gate_artifact=next_unresolved_gate_artifact,
    )
    failed_return_recovery_evidence = _failed_return_recovery_evidence(
        directive_id=directive_id,
        target_artifact=failed_return_recovery_target,
        child_record=child_record,
        latest_progress=latest_progress,
        campaign_manifest=campaign_manifest,
    )
    if not bool(failed_return_recovery_evidence.get("has_evidence", False)):
        recovery_candidates = [
            str(latest_progress.get("target_artifact", "") or "").strip(),
            str(micro_adjustment.get("target_artifact", "") or "").strip() if micro_adjustment_required else "",
            str(dict(campaign_manifest.get("draft_delta_quality", {}) or {}).get("target_artifact", "") or "").strip(),
            str(dict(campaign_state.get("draft_delta_quality", {}) or {}).get("target_artifact", "") or "").strip(),
        ]
        for candidate in recovery_candidates:
            if (
                not candidate
                or candidate == failed_return_recovery_target
                or candidate == "technical_documentation.md"
                or candidate not in BUILD_GRADE_REVIEWABLE_ARTIFACT_ORDER
            ):
                continue
            candidate_evidence = _failed_return_recovery_evidence(
                directive_id=directive_id,
                target_artifact=candidate,
                child_record=child_record,
                latest_progress=latest_progress,
                campaign_manifest=campaign_manifest,
            )
            if bool(candidate_evidence.get("has_evidence", False)):
                failed_return_recovery_target = candidate
                failed_return_recovery_evidence = candidate_evidence
                break
    recovery_pre_blockers: list[str] = []
    if not failed_or_missing_return:
        recovery_pre_blockers.append("return_packet_not_failed_or_missing")
    if "docker_mount_fault" in risks or bool(packet.get("infrastructure_fault", False)):
        recovery_pre_blockers.append("docker_mount_fault")
    if not expects_build_grade:
        recovery_pre_blockers.append("directive_does_not_require_build_grade_documentation")
    if not failed_return_recovery_target:
        recovery_pre_blockers.append("missing_recovery_target_artifact")
    if not bool(failed_return_recovery_evidence.get("has_evidence", False)):
        recovery_pre_blockers.append("missing_progress_or_draft_delta_evidence")
    if _failed_return_recovery_used_for_target(metadata, failed_return_recovery_target):
        recovery_pre_blockers.append("failed_return_auto_requeue_cap_reached")
    if unresolved_support_requests:
        recovery_pre_blockers.append("kernel_support_request_pending")
    if high_risk_needs_clarification:
        recovery_pre_blockers.append("safety_review_required")
    if blocking_operator_clarifications:
        recovery_pre_blockers.append("operator_clarification_required")
    if _autonomy_emergency_stop_active(operator_root):
        recovery_pre_blockers.append("emergency_stop_active")
    failed_return_recovery = {
        "eligible": bool(failed_or_missing_return and not recovery_pre_blockers),
        "reason": (
            "failed_return_recovered_from_progress_evidence"
            if failed_or_missing_return and not recovery_pre_blockers
            else ""
        ),
        "target_artifact": failed_return_recovery_target,
        "blockers": list(dict.fromkeys(recovery_pre_blockers)),
        "evidence": failed_return_recovery_evidence,
        "return_risks": sorted(risks),
        "bounded_auto_requeue_limit": 1,
    }

    auto_reengagement_blockers: list[str] = []
    if failed_or_missing_return and not bool(failed_return_recovery.get("eligible", False)):
        _append_unique(auto_reengagement_blockers, "child_failed_or_return_packet_missing")
        if "failed_return_auto_requeue_cap_reached" in recovery_pre_blockers:
            _append_unique(auto_reengagement_blockers, "failed_return_auto_requeue_cap_reached")
        if "missing_progress_or_draft_delta_evidence" in recovery_pre_blockers:
            _append_unique(auto_reengagement_blockers, "missing_progress_or_draft_delta_evidence")
    if "docker_mount_fault" in risks or bool(packet.get("infrastructure_fault", False)):
        _append_unique(auto_reengagement_blockers, "docker_mount_fault")
    if unresolved_support_requests:
        _append_unique(auto_reengagement_blockers, "kernel_support_request_pending")
    if high_risk_needs_clarification:
        _append_unique(auto_reengagement_blockers, "safety_review_required")
    if blocking_operator_clarifications:
        _append_unique(auto_reengagement_blockers, "operator_clarification_required")
    if _autonomy_emergency_stop_active(operator_root):
        _append_unique(auto_reengagement_blockers, "emergency_stop_active")
    if not expects_build_grade:
        _append_unique(auto_reengagement_blockers, "directive_does_not_require_build_grade_documentation")
    if not campaign_prototype_ready and requeue_count >= max_kernel_requeues and not micro_adjustment_required:
        _append_unique(auto_reengagement_blockers, "kernel_requeue_cap_reached")

    prototype_ready_stop_condition = (
        expects_build_grade
        and campaign_prototype_ready
        and not missing_artifacts
        and not missing_evidence
        and (not followup_required or operator_followup_delta_satisfied)
        and not micro_adjustment_required
        and not auto_reengagement_blockers
    )
    auto_reengagement_eligible = (
        expects_build_grade
        and not prototype_ready_stop_condition
        and not auto_reengagement_blockers
        and bool(prototype_ready_gate_failures)
    )

    if bool(failed_return_recovery.get("eligible", False)):
        decision = "continue_campaign"
        reasons = ["failed_return_recovered_from_progress_evidence"]
    elif failed_or_missing_return:
        decision = "operator_review_required"
        reasons = ["child_failed_or_return_packet_missing"]
    elif not expects_build_grade:
        decision = "operator_review_ready"
        reasons = ["directive_does_not_require_build_grade_documentation"]
    elif prototype_ready_stop_condition:
        decision = "operator_review_ready"
        reasons = ["prototype_ready_human_review"]
    elif "insufficient_claim_evidence" in structured_reasons or high_risk_needs_clarification:
        decision = "operator_clarification_required"
        reasons = [
            *structured_reasons,
            *(["operator_clarification_required", "safety_review_required"] if high_risk_needs_clarification else []),
        ]
    elif unresolved_support_requests:
        decision = "operator_review_required"
        reasons = ["kernel_support_request_pending"]
    elif blocking_operator_clarifications:
        decision = "operator_review_required"
        reasons = ["operator_clarification_required"]
    elif micro_adjustment_required:
        decision = "continue_campaign"
        reasons = list(micro_adjustment.get("reasons", []) or ["micro_adjustment_required"])
    elif "generic_template_content" in structured_reasons and requeue_count >= max_kernel_requeues:
        decision = "operator_review_required"
        reasons = [*structured_reasons, "kernel_requeue_cap_reached"]
    elif not campaign_prototype_ready and requeue_count >= max_kernel_requeues:
        decision = "operator_review_required"
        reasons = ["prototype_not_ready", "kernel_requeue_cap_reached"]
    elif auto_reengagement_eligible and "resident_worker_stalled" in risks:
        decision = "continue_campaign"
        reasons = ["prototype_not_ready", *prototype_ready_gate_failures]
    elif "generic_template_content" in structured_reasons:
        decision = "requeue_for_depth"
        reasons = [*structured_reasons]
    elif not campaign_prototype_ready and not (missing_artifacts or missing_evidence):
        decision = "continue_campaign"
        reasons = ["missing_build_readiness_gates", *structured_reasons]
    elif overnight_incubation_available:
        decision = "continue_campaign"
        reasons = ["overnight_incubation_depth_pass"]
    elif support_assisted_requeue_available:
        decision = "requeue_for_depth"
        reasons = [
            "kernel_support_request_satisfied",
            *(["missing_build_grade_artifacts"] if missing_artifacts else []),
            *(["missing_build_grade_evidence"] if missing_evidence else []),
        ]
    elif missing_artifacts or missing_evidence:
        if requeue_count >= max_kernel_requeues:
            decision = "operator_review_required"
            reasons = ["kernel_requeue_cap_reached"]
        else:
            decision = "requeue_for_depth"
            reasons = [
                *structured_reasons,
                *(["missing_build_grade_artifacts"] if missing_artifacts else []),
                *(["missing_build_grade_evidence"] if missing_evidence else []),
            ]
    else:
        decision = "operator_review_ready"
        reasons = ["build_grade_documentation_ready"]
    reasons = list(dict.fromkeys([str(reason) for reason in reasons if str(reason or "").strip()]))
    if prototype_ready_stop_condition:
        feedback = (
            "Kernel evaluation found prototype-ready documentation and handoff artifacts complete for "
            f"{str(directive.get('directive_id', '') or '')}. Stop conveyor re-engagement and hold for "
            "human review; this does not grant acceptance or execution authority."
        )
    elif micro_adjustment_required:
        feedback = str(micro_adjustment.get("feedback", "") or "").strip() or _kernel_depth_feedback(
            directive=directive,
            packet=packet,
            missing_artifacts=missing_artifacts,
            missing_evidence=missing_evidence,
            campaign_state=campaign_state,
        )
    else:
        feedback = _kernel_depth_feedback(
            directive=directive,
            packet=packet,
            missing_artifacts=missing_artifacts,
            missing_evidence=missing_evidence,
            campaign_state=campaign_state,
        )
    return {
        "schema_name": "ConveyorKernelReturnEvaluation",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "return_packet_id": str(packet.get("return_packet_id", "") or ""),
        "directive_id": str(directive.get("directive_id", "") or ""),
        "decision": decision,
        "reasons": reasons,
        "prototype_ready_stop_condition": prototype_ready_stop_condition,
        "auto_reengagement_eligible": auto_reengagement_eligible,
        "auto_reengagement_blockers": auto_reengagement_blockers,
        "prototype_ready_gate_failures": prototype_ready_gate_failures,
        "latest_progress_gate_closure_consumed": latest_progress_gate_closure_consumed,
        "superseded_stale_clarifications": superseded_stale_clarifications,
        "next_unresolved_gate_artifact": next_unresolved_gate_artifact,
        "partial_target_correct_closure": bool(campaign_state.get("partial_target_correct_closure", False)),
        "target_artifact_closure_state": str(campaign_state.get("target_artifact_closure_state", "") or ""),
        "closed_target_artifact": str(campaign_state.get("closed_target_artifact", "") or ""),
        "next_linked_artifact_target": str(campaign_state.get("next_linked_artifact_target", "") or ""),
        "remaining_linked_artifact_gaps": list(
            campaign_state.get("remaining_linked_artifact_gaps", []) or []
        ),
        "prototype_cluster_closure": prototype_cluster_closure,
        "new_depth_since_last_review": new_depth_since_last_review,
        "operator_followup_delta_satisfied": operator_followup_delta_satisfied,
        "draft_delta_quality_gate_failures": draft_delta_quality_gate_failures,
        "failed_return_recovery": failed_return_recovery,
        "micro_adjustment_required": micro_adjustment_required,
        "micro_adjustment": dict(micro_adjustment) if micro_adjustment_required else {},
        "missing_artifacts": missing_artifacts,
        "missing_evidence": missing_evidence,
        "campaign_state": campaign_state,
        "support_request_count": len(support_requests),
        "support_satisfied_count": len(satisfied_support_requests),
        "support_unresolved_count": len(unresolved_support_requests),
        "support_request_ids": [str(item.get("support_request_id", "") or "") for item in support_requests],
        "requested_operator_clarifications": blocking_operator_clarifications,
        "superseded_operator_clarifications": superseded_operator_clarifications,
        "support_assisted_requeue_available": support_assisted_requeue_available,
        "overnight_incubation_enabled": overnight_enabled,
        "overnight_incubation_target_passes": overnight_target,
        "overnight_incubation_completed_passes": overnight_completed,
        "overnight_incubation_available": overnight_incubation_available,
        "requeue_count": requeue_count,
        "max_kernel_requeues": max_kernel_requeues,
        "feedback": feedback,
    }


def _mark_support_assisted_requeue_consumed(
    operator_root: str | Path,
    directive_id: str,
) -> None:
    try:
        directive = _load_directive(operator_root, directive_id)
    except ConveyorValidationError:
        _append_ledger(
            operator_root,
            "continuous_campaign_events",
            {
                "event": "failed_return_recovery_reset_skipped_missing_directive",
                "generated_at": _utc_now(),
                "directive_id": str(directive_id or ""),
                "return_packet_id": str(return_packet_id or ""),
                "target_artifact": str(target_artifact or ""),
            },
        )
        return
    if not directive:
        return
    metadata = dict(directive.get("metadata", {}) or {})
    metadata["support_assisted_requeue_count"] = int(metadata.get("support_assisted_requeue_count", 0) or 0) + 1
    directive["metadata"] = metadata
    directive["updated_at"] = _utc_now()
    _write_json(_directive_path(operator_root, directive_id), directive)


def _failed_return_recovery_registry(metadata: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    raw = metadata.get("failed_return_auto_requeue_recovery", {})
    if not isinstance(raw, Mapping):
        return {}
    registry: dict[str, dict[str, Any]] = {}
    for key, value in raw.items():
        target = str(key or "").strip()
        if not target:
            continue
        registry[target] = dict(value) if isinstance(value, Mapping) else {"count": int(value or 0)}
    return registry


def _failed_return_recovery_used_for_target(metadata: Mapping[str, Any], target_artifact: str) -> bool:
    target = str(target_artifact or "").strip()
    if not target:
        return False
    record = _failed_return_recovery_registry(metadata).get(target, {})
    try:
        count = int(record.get("count", 0) or 0)
    except (TypeError, ValueError):
        count = 0
    return count >= 1


def _record_failed_return_auto_requeue_recovery(
    operator_root: str | Path,
    directive_id: str,
    *,
    target_artifact: str,
    return_packet_id: str,
    child_run_id: str = "",
    work_order_id: str = "",
    reason: str = "failed_return_recovered_from_progress_evidence",
) -> None:
    try:
        directive = _load_directive(operator_root, directive_id)
    except ConveyorValidationError:
        _append_ledger(
            operator_root,
            "continuous_campaign_events",
            {
                "event": "failed_return_recovery_record_skipped_missing_directive",
                "generated_at": _utc_now(),
                "directive_id": str(directive_id or ""),
                "return_packet_id": str(return_packet_id or ""),
                "target_artifact": str(target_artifact or ""),
            },
        )
        return
    if not directive:
        return
    metadata = dict(directive.get("metadata", {}) or {})
    registry = _failed_return_recovery_registry(metadata)
    target = str(target_artifact or "").strip()
    if not target:
        return
    previous = dict(registry.get(target, {}) or {})
    try:
        previous_count = int(previous.get("count", 0) or 0)
    except (TypeError, ValueError):
        previous_count = 0
    now = _utc_now()
    registry[target] = {
        **previous,
        "count": max(1, previous_count + 1),
        "target_artifact": target,
        "latest_return_packet_id": str(return_packet_id or ""),
        "latest_child_run_id": str(child_run_id or ""),
        "latest_work_order_id": str(work_order_id or ""),
        "latest_reason": reason,
        "latest_recovered_at": now,
        "valid_return_packet_observed_after_recovery": False,
    }
    metadata["failed_return_auto_requeue_recovery"] = registry
    directive["metadata"] = metadata
    directive["updated_at"] = now
    _write_json(_directive_path(operator_root, directive_id), directive)
    _append_ledger(
        operator_root,
        "continuous_campaign_events",
        {
            "event": "failed_return_auto_requeue_recovery_used",
            "generated_at": now,
            "directive_id": directive_id,
            "return_packet_id": str(return_packet_id or ""),
            "child_run_id": str(child_run_id or ""),
            "work_order_id": str(work_order_id or ""),
            "target_artifact": target,
            "reason": reason,
        },
    )


def _reset_failed_return_auto_requeue_recovery_after_valid_return(
    operator_root: str | Path,
    directive_id: str,
    *,
    target_artifact: str = "",
    return_packet_id: str = "",
) -> None:
    directive = _read_json(_directive_path(operator_root, directive_id))
    if not directive:
        return
    metadata = dict(directive.get("metadata", {}) or {})
    registry = _failed_return_recovery_registry(metadata)
    if not registry:
        return
    target = str(target_artifact or "").strip()
    if target:
        registry.pop(target, None)
    else:
        registry = {}
    metadata["failed_return_auto_requeue_recovery"] = registry
    metadata["failed_return_auto_requeue_recovery_reset_at"] = _utc_now()
    metadata["failed_return_auto_requeue_recovery_reset_return_packet_id"] = str(return_packet_id or "")
    directive["metadata"] = metadata
    directive["updated_at"] = metadata["failed_return_auto_requeue_recovery_reset_at"]
    _write_json(_directive_path(operator_root, directive_id), directive)


def _overnight_incubation_budget(metadata: Mapping[str, Any]) -> tuple[bool, int, int]:
    enabled = bool(metadata.get("overnight_incubation_enabled", False))
    try:
        target = max(0, min(int(metadata.get("overnight_incubation_target_passes", 0) or 0), 12))
    except (TypeError, ValueError):
        target = 0
    try:
        completed = max(0, int(metadata.get("overnight_incubation_completed_passes", 0) or 0))
    except (TypeError, ValueError):
        completed = 0
    return enabled, target, completed


def _mark_overnight_incubation_pass_consumed(
    operator_root: str | Path,
    directive_id: str,
) -> None:
    directive = _load_directive(operator_root, directive_id)
    if not directive:
        return
    metadata = dict(directive.get("metadata", {}) or {})
    enabled, target, completed = _overnight_incubation_budget(metadata)
    if not enabled or target <= 0:
        return
    metadata["overnight_incubation_completed_passes"] = min(target, completed + 1)
    directive["metadata"] = metadata
    directive["updated_at"] = _utc_now()
    _write_json(_directive_path(operator_root, directive_id), directive)


def _persist_directive_campaign_state(
    operator_root: str | Path,
    directive_id: str,
    campaign_state: Mapping[str, Any],
) -> None:
    try:
        directive = _load_directive(operator_root, directive_id)
    except ConveyorValidationError:
        _append_ledger(
            operator_root,
            "directive_events",
            {
                "event": "campaign_state_persist_skipped_missing_directive",
                "directive_id": str(directive_id or ""),
                "created_at": _utc_now(),
            },
        )
        return
    if not directive:
        return
    state = dict(campaign_state)
    state["updated_at"] = _utc_now()
    state["campaign_goal"] = "drive_directive_to_real_world_prototype_readiness"
    directive["campaign_state"] = state
    directive["campaign_readiness_level"] = str(state.get("readiness_level", "") or "")
    directive["updated_at"] = state["updated_at"]
    _write_json(_directive_path(operator_root, directive_id), directive)


def evaluate_pending_child_returns(
    operator_root: str | Path,
    *,
    state_root: str | Path | None = None,
    max_kernel_requeues: int = 2,
    allow_continuous_support: bool = True,
) -> dict[str, Any]:
    initialize_conveyor_state(operator_root)
    rows: list[dict[str, Any]] = []
    requeued_count = 0
    continued_campaign_count = 0
    continuous_auto_requeued_count = 0
    continuous_auto_support_approved_count = 0
    continuous_escalated_count = 0
    continuous_support_skipped_count = 0
    stale_return_directive_count = 0
    ready_count = 0
    held_count = 0
    for packet in _load_items(_returns_root(operator_root)):
        if str(packet.get("review_state", "") or "") != "pending_operator_review":
            continue
        return_packet_id = str(packet.get("return_packet_id", "") or "")
        if not return_packet_id:
            continue
        directive_for_packet = _read_json(
            _directive_path(operator_root, str(packet.get("directive_id", "") or ""))
        )
        active_child_id = str(directive_for_packet.get("active_child_run_id", "") or "") if directive_for_packet else ""
        packet_child_id = str(packet.get("child_run_id", "") or "")
        if (
            active_child_id
            and packet_child_id
            and packet_child_id != active_child_id
            and str(directive_for_packet.get("state", "") or "") == "running"
        ):
            repaired_packet = dict(packet)
            repaired_packet["review_state"] = "requeued"
            repaired_packet["operator_note"] = str(
                repaired_packet.get("operator_note", "") or "superseded_by_active_child"
            )
            repaired_packet["superseded_by_active_child_run_id"] = active_child_id
            repaired_packet["superseded_reason"] = "active_resident_worker_continuation"
            repaired_packet["reviewed_at"] = str(repaired_packet.get("reviewed_at", "") or _utc_now())
            repaired_packet["updated_at"] = _utc_now()
            _write_json(_return_path(operator_root, return_packet_id), repaired_packet)
            continue
        latest_decision = _latest_return_decision(operator_root, return_packet_id)
        latest_decision_state = str(latest_decision.get("decision_state", "") or "")
        if latest_decision_state in {"accepted", "requeued", "rejected", "split"}:
            repaired_packet = dict(packet)
            repaired_packet["review_state"] = latest_decision_state
            repaired_packet["operator_note"] = str(latest_decision.get("operator_note", "") or "")
            repaired_packet["operator_feedback"] = str(latest_decision.get("operator_feedback", "") or "")
            repaired_packet["reviewed_at"] = str(latest_decision.get("generated_at", "") or _utc_now())
            repaired_packet["updated_at"] = _utc_now()
            _write_json(_return_path(operator_root, return_packet_id), repaired_packet)
            continue
        directive_metadata = dict(directive_for_packet.get("metadata", {}) or {}) if directive_for_packet else {}
        if (
            str(directive_metadata.get("continuous_campaign_latest_state", "") or "") == "auto_requeued"
            and str(directive_metadata.get("continuous_campaign_latest_return_packet_id", "") or "") == return_packet_id
        ):
            repaired_packet = dict(packet)
            repaired_packet["review_state"] = "requeued"
            repaired_packet["operator_note"] = str(
                repaired_packet.get("operator_note", "") or "continuous_campaign_auto_continue"
            )
            repaired_packet["reviewed_at"] = str(
                repaired_packet.get("reviewed_at", "")
                or directive_metadata.get("continuous_campaign_latest_updated_at", "")
                or _utc_now()
            )
            repaired_packet["updated_at"] = _utc_now()
            _write_json(_return_path(operator_root, return_packet_id), repaired_packet)
            continue
        packet, hydrated = _hydrate_pending_return_workspace_artifacts(operator_root, packet)
        if hydrated:
            _write_json(_return_path(operator_root, return_packet_id), packet)
        packet, compiled = _compile_handoff_documentation_if_needed(operator_root, packet)
        if compiled:
            packet, _rehydrated = _attach_latest_campaign_canonical_artifacts(operator_root, packet)
            _write_json(_return_path(operator_root, return_packet_id), packet)
        evaluation = _evaluate_return_packet_depth(
            operator_root,
            packet,
            state_root=state_root,
            max_kernel_requeues=max(1, int(max_kernel_requeues or 1)),
        )
        updated_packet = dict(packet)
        updated_packet["kernel_evaluation"] = evaluation
        support_fields = _support_blocker_packet_fields(operator_root, updated_packet, evaluation)
        if support_fields:
            updated_packet.update(support_fields)
        else:
            updated_packet, _cleared = _clear_stale_support_blocker_packet_fields(updated_packet)
        if list(evaluation.get("requested_operator_clarifications", []) or []):
            updated_packet["requested_operator_clarifications"] = [
                dict(item)
                for item in list(evaluation.get("requested_operator_clarifications", []) or [])
                if isinstance(item, Mapping)
            ]
        elif "requested_operator_clarifications" in updated_packet:
            updated_packet["requested_operator_clarifications"] = []
        _write_json(_return_path(operator_root, return_packet_id), updated_packet)
        directive_id = str(evaluation.get("directive_id", "") or "")
        if bool(evaluation.get("stale_directive_reference", False)):
            stale_return_directive_count += 1
        else:
            _persist_directive_campaign_state(
                operator_root,
                directive_id,
                dict(evaluation.get("campaign_state", {}) or {}),
            )
        updated_risks = {str(item) for item in list(updated_packet.get("risks", []) or [])}
        if (
            directive_id
            and not bool(evaluation.get("stale_directive_reference", False))
            and not {"missing_child_return_packet", "runtime_failure"}.intersection(updated_risks)
            and str(updated_packet.get("child_run_id", "") or "").strip()
            and (list(updated_packet.get("artifacts", []) or []) or list(updated_packet.get("verification_evidence", []) or []))
        ):
            reset_target = str(
                evaluation.get("next_unresolved_gate_artifact", "")
                or dict(evaluation.get("campaign_state", {}) or {}).get("next_unresolved_gate_artifact", "")
                or ""
            ).strip()
            if not reset_target:
                directive_for_reset = _read_json(_directive_path(operator_root, directive_id))
                reset_target = _auto_reengagement_target_artifact(
                    operator_root,
                    directive=directive_for_reset,
                    packet=updated_packet,
                    evaluation=evaluation,
                ) if directive_for_reset else ""
            _reset_failed_return_auto_requeue_recovery_after_valid_return(
                operator_root,
                directive_id,
                target_artifact=reset_target,
                return_packet_id=return_packet_id,
            )
        if (
            evaluation["decision"] == "operator_review_required"
            and "kernel_support_request_pending" in list(evaluation.get("reasons", []) or [])
        ):
            if not allow_continuous_support:
                evaluation = dict(evaluation)
                evaluation["continuous_support_skipped"] = True
                evaluation["continuous_support_skip_reason"] = "scheduler_return_evaluation_support_continuation_deferred"
                updated_packet["kernel_evaluation"] = evaluation
                updated_packet["continuous_support_skipped"] = True
                updated_packet["continuous_support_skip_reason"] = "scheduler_return_evaluation_support_continuation_deferred"
                _write_json(_return_path(operator_root, return_packet_id), updated_packet)
                rows.append({"evaluation": evaluation})
                held_count += 1
                continuous_support_skipped_count += 1
                continue
            continuous_attempt = _attempt_continuous_campaign_continuation(
                operator_root,
                state_root=state_root,
                packet=updated_packet,
                evaluation=evaluation,
            )
            evaluation = dict(evaluation)
            evaluation["continuous_campaign"] = continuous_attempt
            updated_packet["kernel_evaluation"] = evaluation
            if bool(continuous_attempt.get("auto_requeued", False)):
                rows.append(
                    {
                        "evaluation": evaluation,
                        "continuous_campaign": continuous_attempt,
                        "decision": dict(continuous_attempt.get("decision", {}) or {}),
                    }
                )
                requeued_count += 1
                continuous_auto_requeued_count += 1
                continuous_auto_support_approved_count += int(
                    continuous_attempt.get("auto_support_approved_count", 0) or 0
                )
                continue
            if str(continuous_attempt.get("state", "") or "") in {
                "cap_exhausted",
                "no_progress_escalated",
                "support_failed",
                "blocked",
            }:
                continuous_escalated_count += 1
            _write_json(_return_path(operator_root, return_packet_id), updated_packet)
        if evaluation["decision"] in {"requeue_for_depth", "continue_campaign"}:
            directive_for_requeue = _read_json(_directive_path(operator_root, directive_id)) if directive_id else {}
            if directive_id and not directive_for_requeue:
                stale_return_directive_count += 1
                updated_packet["kernel_evaluation"] = {
                    **dict(evaluation),
                    "stale_directive_reference": True,
                    "reasons": list(
                        dict.fromkeys(
                            [
                                *list(evaluation.get("reasons", []) or []),
                                "stale_directive_reference",
                            ]
                        )
                    ),
                }
                _write_json(_return_path(operator_root, return_packet_id), updated_packet)
                continue
            target_artifact = _auto_reengagement_target_artifact(
                operator_root,
                directive=directive_for_requeue,
                packet=updated_packet,
                evaluation=evaluation,
            )
            try:
                decision = _decide_return(
                    operator_root,
                    return_packet_id=return_packet_id,
                    decision_state="requeued",
                    operator_note=(
                        "kernel_campaign_continuation"
                        if evaluation["decision"] == "continue_campaign"
                        else "kernel_depth_evaluation"
                    ),
                    feedback=str(evaluation.get("feedback", "") or ""),
                )
            except ConveyorValidationError as exc:
                if "directive_id not found" not in str(exc):
                    raise
                stale_return_directive_count += 1
                stale_evaluation = {
                    **dict(evaluation),
                    "stale_directive_reference": True,
                    "reasons": list(
                        dict.fromkeys(
                            [
                                *list(evaluation.get("reasons", []) or []),
                                "stale_directive_reference",
                            ]
                        )
                    ),
                }
                updated_packet["kernel_evaluation"] = stale_evaluation
                _write_json(_return_path(operator_root, return_packet_id), updated_packet)
                rows.append(
                    {
                        "evaluation": stale_evaluation,
                        "decision": {
                            "decision_state": "stale_directive_reference",
                            "return_packet_id": return_packet_id,
                            "directive_id": directive_id,
                        },
                    }
                )
                continue
            if directive_for_requeue and target_artifact:
                _set_continuous_campaign_metadata(
                    operator_root,
                    directive_for_requeue,
                    state="auto_requeued",
                    action=(
                        "kernel_campaign_continuation"
                        if evaluation["decision"] == "continue_campaign"
                        else "kernel_depth_evaluation"
                    ),
                    reason="auto_reengagement_depth_target",
                    return_packet_id=return_packet_id,
                    no_progress_count=0,
                    target_artifact=target_artifact,
                    feedback=str(evaluation.get("feedback", "") or ""),
                )
                if bool(dict(evaluation.get("failed_return_recovery", {}) or {}).get("eligible", False)):
                    _record_failed_return_auto_requeue_recovery(
                        operator_root,
                        directive_id,
                        target_artifact=target_artifact,
                        return_packet_id=return_packet_id,
                        child_run_id=str(updated_packet.get("child_run_id", "") or ""),
                        work_order_id=str(
                            dict(dict(evaluation.get("failed_return_recovery", {}) or {}).get("evidence", {}) or {}).get(
                                "work_order_id",
                                "",
                            )
                            or ""
                        ),
                    )
                    decided_packet = _read_json(_return_path(operator_root, return_packet_id)) or updated_packet
                    decided_packet["failed_return_auto_requeue_recovery"] = {
                        "used": True,
                        "target_artifact": target_artifact,
                        "reason": "failed_return_recovered_from_progress_evidence",
                        "bounded_auto_requeue_limit": 1,
                    }
                    decided_packet["updated_at"] = _utc_now()
                    _write_json(_return_path(operator_root, return_packet_id), decided_packet)
                    child_id = str(updated_packet.get("child_run_id", "") or "")
                    child_record = _read_json(_child_path(operator_root, child_id)) if child_id else {}
                    if child_record:
                        latest_progress = _latest_child_progress(child_record)
                        work_order = _append_resident_work_order(
                            operator_root,
                            state_root=state_root,
                            child=child_record,
                            latest_progress=latest_progress,
                            target_artifact=target_artifact,
                            reason=str(evaluation.get("feedback", "") or ""),
                        )
                        child_record["latest_work_order_id"] = str(work_order.get("work_order_id", "") or "")
                        child_record["latest_work_order_target_artifact"] = str(
                            work_order.get("target_artifact", "") or ""
                        )
                        child_record["latest_work_order_at"] = str(work_order.get("generated_at", "") or "")
                        child_record["latest_work_order"] = dict(work_order)
                        child_record["resident_worker_state"] = "failed_return_recovery_work_order_injected"
                        _write_json(_child_path(operator_root, child_id), child_record)
                evaluation = dict(evaluation)
                intent_continuity = {
                    "source_return_packet_id": return_packet_id,
                    "intended_target_artifact": target_artifact,
                    "spawned_target_artifact": "",
                    "inbox_work_order_present": False,
                    "role_adapter_ref_present": False,
                    "requirement_contract_present": False,
                    "preserved": False,
                    "pending_next_spawn": True,
                    "failed_gates": [],
                }
                evaluation["intent_continuity"] = intent_continuity
                decided_packet = _read_json(_return_path(operator_root, return_packet_id))
                updated_packet = dict(decided_packet or updated_packet)
                updated_packet["kernel_evaluation"] = evaluation
                _write_json(_return_path(operator_root, return_packet_id), updated_packet)
            if bool(evaluation.get("support_assisted_requeue_available", False)):
                _mark_support_assisted_requeue_consumed(
                    operator_root,
                    directive_id,
                )
            if "overnight_incubation_depth_pass" in list(evaluation.get("reasons", []) or []):
                _mark_overnight_incubation_pass_consumed(
                    operator_root,
                    directive_id,
                )
            rows.append({"evaluation": evaluation, "decision": decision})
            requeued_count += 1
            if evaluation["decision"] == "continue_campaign":
                continued_campaign_count += 1
        elif evaluation["decision"] == "operator_review_ready":
            rows.append({"evaluation": evaluation})
            ready_count += 1
        else:
            rows.append({"evaluation": evaluation})
            held_count += 1
    result = {
        "ok": True,
        "schema_name": "ConveyorKernelReturnEvaluationBatch",
        "schema_version": CONVEYOR_SCHEMA_VERSION,
        "generated_at": _utc_now(),
        "evaluated_count": len(rows),
        "requeued_count": requeued_count,
        "continued_campaign_count": continued_campaign_count,
        "continuous_auto_requeued_count": continuous_auto_requeued_count,
        "continuous_auto_support_approved_count": continuous_auto_support_approved_count,
        "continuous_escalated_count": continuous_escalated_count,
        "continuous_support_skipped": continuous_support_skipped_count > 0,
        "continuous_support_skipped_count": continuous_support_skipped_count,
        "stale_return_directive_count": stale_return_directive_count,
        "ready_for_review_count": ready_count,
        "held_for_operator_count": held_count,
        "support_request_count": sum(
            int(row.get("evaluation", {}).get("support_request_count", 0) or 0)
            for row in rows
        ),
        "support_satisfied_count": sum(
            int(row.get("evaluation", {}).get("support_satisfied_count", 0) or 0)
            for row in rows
        ),
        "support_unresolved_count": sum(
            int(row.get("evaluation", {}).get("support_unresolved_count", 0) or 0)
            for row in rows
        ),
        "records": rows,
    }
    if rows:
        _append_ledger(operator_root, "return_evaluations", result)
    return result


def accept_child_return(
    operator_root: str | Path,
    *,
    return_packet_id: str,
    operator_note: str = "",
) -> dict[str, Any]:
    return _decide_return(
        operator_root,
        return_packet_id=return_packet_id,
        decision_state="accepted",
        operator_note=operator_note,
    )


def _commercial_bom_requeue_requested_row_ids(
    operator_root: str | Path,
    *,
    directive_id: str,
) -> list[str]:
    row_ids: list[str] = []
    for artifact_root in ("drafts", "canonical"):
        payload = _read_json(
            _campaign_root(operator_root, directive_id)
            / artifact_root
            / "bill_of_materials.json"
        )
        for row in _artifact_rows_for_target(payload, "bill_of_materials.json"):
            row_id = str(
                row.get("requested_row_id", "")
                or row.get("closes_requested_row_id", "")
                or row.get("design_artifact_row_id", "")
                or row.get("item_id", "")
                or row.get("component_id", "")
                or row.get("row_id", "")
                or row.get("target_role", "")
                or ""
            ).strip()
            if row_id and row_id not in row_ids:
                row_ids.append(row_id)
    if row_ids:
        return row_ids
    return ["bill_of_materials.json#source_backed_commercial_rows"]


def _mark_commercial_bom_requeue_blocker(
    operator_root: str | Path,
    *,
    directive: Mapping[str, Any],
    metadata: dict[str, Any],
    target_artifact: str,
) -> dict[str, Any]:
    if str(target_artifact or "").strip() != "bill_of_materials.json":
        return metadata
    directive_id = str(directive.get("directive_id", "") or "").strip()
    requested_row_ids = _commercial_bom_requeue_requested_row_ids(
        operator_root,
        directive_id=directive_id,
    )
    required_fields = [
        str(field)
        for field in list(
            dict(FULL_DIVE_HARDWARE_REQUIRED_FIELDS.get("bill_of_materials.json", {}) or {}).get(
                "required_fields",
                (),
            )
        )
        if str(field).strip()
    ]
    metadata["operator_requeue_explicit_target_artifact"] = "bill_of_materials.json"
    metadata["support_blocker_target_artifact"] = "bill_of_materials.json"
    metadata["continuous_campaign_latest_target_artifact"] = "bill_of_materials.json"
    metadata["commercial_source_acquisition_required"] = True
    metadata["source_backed_rows_required"] = True
    metadata["design_brief_diagnostic_only"] = True
    metadata["uncovered_requested_row_ids"] = requested_row_ids
    metadata["uncovered_commercial_requested_row_ids"] = requested_row_ids
    metadata["field_lane_uncovered_fields"] = required_fields
    metadata["support_provider_quality_blocker"] = True
    metadata["support_admission_state"] = "commercial_source_acquisition_required"
    metadata["support_admission_blocker_reason"] = "source_backed_rows_required"
    metadata["next_support_recovery_action"] = "provider_field_lane_acquisition"
    return metadata


def requeue_child_return(
    operator_root: str | Path,
    *,
    return_packet_id: str,
    feedback: str,
    operator_note: str = "",
    state_root: str | Path | None = None,
    approve_support_before_requeue: bool = False,
) -> dict[str, Any]:
    packet = _read_json(_return_path(operator_root, return_packet_id))
    support_approval_results: list[dict[str, Any]] = []
    effective_feedback = str(feedback or operator_note or "").strip()
    target_artifact = ""
    if approve_support_before_requeue and packet:
        target_artifact = _support_blocker_target_artifact(
            packet,
            _related_support_requests_for_packet(operator_root, packet),
        )
        if target_artifact == "interface_specifications.json":
            interface_guidance = (
                " For interface_specifications.json, produce typed contracts, boundary conditions, "
                "inputs/outputs, validation fixtures, failure modes, safety/governance boundaries, "
                "and prototype integration assumptions."
            )
            if "typed contracts" not in effective_feedback.lower():
                effective_feedback = f"{effective_feedback}{interface_guidance}".strip()
        ok, support_approval_results, blocker = _approve_related_support_requests_before_requeue(
            operator_root,
            packet=packet,
            state_root=state_root,
        )
        if not ok:
            packet_payload = _read_json(_return_path(operator_root, return_packet_id)) or packet
            support_fields = _support_blocker_packet_fields(operator_root, packet_payload)
            if support_fields:
                packet_payload.update(support_fields)
                packet_payload["updated_at"] = _utc_now()
                _write_json(_return_path(operator_root, return_packet_id), packet_payload)
            return {
                "ok": False,
                "schema_name": "ConveyorReturnDecision",
                "schema_version": CONVEYOR_SCHEMA_VERSION,
                "generated_at": _utc_now(),
                "decision_state": "support_required_before_requeue",
                "return_packet_id": return_packet_id,
                "message": blocker,
                "support_approval_count": len(support_approval_results),
                "support_approval_results": support_approval_results,
            }
    if packet:
        directive_id = str(packet.get("directive_id", "") or "")
        directive = _load_directive(operator_root, directive_id)
        target_artifact = _operator_requeue_target_artifact(
            operator_root,
            directive=directive,
            packet=packet,
            feedback=effective_feedback,
            previous_target=target_artifact,
        )
        manifest = _read_json(_campaign_manifest_path(operator_root, directive_id))
        target_quality = dict(dict(manifest.get("canonical_artifacts", {}) or {}).get(target_artifact, {}) or {})
        effective_feedback = _campaign_artifact_guidance(
            target_artifact,
            fallback=effective_feedback,
            directive=directive,
            failed_gates=list(target_quality.get("failed_quality_gates", []) or []),
        )
    decision = _decide_return(
        operator_root,
        return_packet_id=return_packet_id,
        decision_state="requeued",
        operator_note=operator_note,
        feedback=effective_feedback,
    )
    if packet:
        directive_id = str(packet.get("directive_id", "") or "")
        directive = _load_directive(operator_root, directive_id)
        if directive and target_artifact:
            metadata = dict(directive.get("metadata", {}) or {})
            metadata["initial_work_order_target_artifact"] = target_artifact
            metadata["initial_work_order_context"] = effective_feedback
            metadata["initial_work_order_source_return_packet_id"] = return_packet_id
            metadata["initial_work_order_capability"] = "directive_build_grade_synthesis_pack"
            metadata = _mark_commercial_bom_requeue_blocker(
                operator_root,
                directive=directive,
                metadata=metadata,
                target_artifact=target_artifact,
            )
            directive["metadata"] = metadata
            directive["updated_at"] = _utc_now()
            _write_json(_directive_path(operator_root, directive_id), directive)
    if approve_support_before_requeue and packet:
        directive_id = str(packet.get("directive_id", "") or "")
        directive = _load_directive(operator_root, directive_id)
        directive = _mark_campaign_artifact_attempt(
            operator_root,
            directive,
            artifact=target_artifact or "interface_specifications.json",
            return_packet_id=return_packet_id,
            reason="operator_support_assisted_requeue",
        )
        metadata = dict(directive.get("metadata", {}) or {})
        metadata["initial_work_order_target_artifact"] = target_artifact or "interface_specifications.json"
        metadata["initial_work_order_context"] = effective_feedback
        metadata["initial_work_order_source_return_packet_id"] = return_packet_id
        metadata["initial_work_order_capability"] = "directive_build_grade_synthesis_pack"
        metadata = _mark_commercial_bom_requeue_blocker(
            operator_root,
            directive=directive,
            metadata=metadata,
            target_artifact=target_artifact,
        )
        directive["metadata"] = metadata
        directive["updated_at"] = _utc_now()
        _write_json(_directive_path(operator_root, directive_id), directive)
    packet = _read_json(_return_path(operator_root, return_packet_id))
    if packet:
        resolved = _resolve_return_operator_feedback(
            operator_root,
            packet=packet,
            feedback=effective_feedback,
            operator_note=operator_note,
            resolution_source="operator_deeper_pass_direction",
        )
        packet = _read_json(_return_path(operator_root, return_packet_id)) or packet
        if approve_support_before_requeue:
            support_cleanup = [
                dict(result.get("support_request", {}) or {"support_request_id": result.get("support_request_id", "")})
                for result in support_approval_results
                if bool(result.get("ok", False))
            ]
        else:
            support_cleanup = _cleanup_related_support_requests_for_requeue(
                operator_root,
                packet=packet,
                state_root=state_root,
                feedback=effective_feedback,
                operator_note=operator_note,
            )
        sibling_return_cleanup = _supersede_sibling_pending_returns_for_requeue(
            operator_root,
            packet=packet,
            feedback=effective_feedback,
        )
    else:
        resolved = []
        support_cleanup = []
        sibling_return_cleanup = []
    decision["resolved_clarification_count"] = len(resolved)
    decision["support_cleanup_count"] = len(support_cleanup)
    decision["sibling_return_cleanup_count"] = len(sibling_return_cleanup)
    decision["sibling_return_cleanup_packet_ids"] = [
        str(item.get("return_packet_id", "") or "") for item in sibling_return_cleanup
    ]
    decision["support_cleanup_request_ids"] = [
        str(item.get("support_request_id", "") or "") for item in support_cleanup
    ]
    decision["support_cleanup_states"] = [
        str(item.get("support_state", "") or "") for item in support_cleanup
    ]
    decision["support_approval_count"] = len(support_approval_results)
    decision["support_approval_results"] = support_approval_results
    if packet:
        _reset_continuous_campaign_context(
            operator_root,
            str(packet.get("directive_id", "") or ""),
            reason="operator_feedback_requeue",
            action="operator_requeue",
            return_packet_id=return_packet_id,
            feedback=effective_feedback,
            target_artifact=target_artifact,
        )
    return decision


def clarify_child_return(
    operator_root: str | Path,
    *,
    return_packet_id: str,
    feedback: str,
    clarifications: Iterable[Mapping[str, Any]] | None = None,
    operator_note: str = "",
) -> dict[str, Any]:
    decision = _decide_return(
        operator_root,
        return_packet_id=return_packet_id,
        decision_state="requeued",
        operator_note=operator_note,
        feedback=feedback,
    )
    packet = _read_json(_return_path(operator_root, return_packet_id))
    if not packet:
        raise ConveyorValidationError(f"return_packet_id not found: {return_packet_id}")
    directive_id = str(packet.get("directive_id", "") or "")
    directive = _load_directive(operator_root, directive_id)
    requested = [
        dict(item)
        for item in list(packet.get("requested_operator_clarifications", []) or [])
        if isinstance(item, Mapping)
    ]
    requested_by_id = {
        str(item.get("clarification_id", "") or ""): item
        for item in requested
        if str(item.get("clarification_id", "") or "")
    }
    answer_payloads = [
        dict(item)
        for item in list(clarifications or [])
        if isinstance(item, Mapping)
    ]
    if not answer_payloads and str(feedback or "").strip():
        source = requested[0] if requested else {}
        answer_payloads = [
            {
                "clarification_id": str(source.get("clarification_id", "") or f"clarification-{uuid.uuid4().hex[:10]}"),
                "answer": str(feedback or "").strip(),
            }
        ]
    now = _utc_now()
    resolved_records: list[dict[str, Any]] = []
    for index, answer in enumerate(answer_payloads):
        clarification_id = str(answer.get("clarification_id", "") or "").strip()
        source = requested_by_id.get(clarification_id)
        if source is None and index < len(requested):
            source = requested[index]
            clarification_id = clarification_id or str(source.get("clarification_id", "") or "")
        if not clarification_id:
            clarification_id = f"clarification-{uuid.uuid4().hex[:10]}"
        source = dict(source or {})
        resolved_records.append(
            {
                "clarification_id": clarification_id,
                "question": str(answer.get("question", "") or source.get("question", "") or ""),
                "answer": str(answer.get("answer", "") or answer.get("operator_answer", "") or feedback or "").strip(),
                "blocked_gate": str(
                    answer.get("blocked_gate", "")
                    or source.get("blocked_gate", "")
                    or source.get("blocked_requirement", "")
                    or "operator_clarification_required"
                ),
                "proposed_options": [
                    dict(item) if isinstance(item, Mapping) else str(item)
                    for item in list(answer.get("proposed_options", source.get("proposed_options", [])) or [])
                ],
                "resolved": True,
                "return_packet_id": return_packet_id,
                "operator_feedback": str(feedback or operator_note or "").strip(),
                "answered_at": now,
            }
        )
    existing = [
        dict(item)
        for item in list(directive.get("operator_clarifications", []) or [])
        if isinstance(item, Mapping)
    ]
    by_id = {
        str(item.get("clarification_id", "") or f"clarification-{uuid.uuid4().hex[:10]}"): item
        for item in existing
    }
    for record in resolved_records:
        by_id[str(record["clarification_id"])] = record
    target_artifact = _operator_requeue_target_artifact(
        operator_root,
        directive=directive,
        packet=packet,
        feedback=str(feedback or operator_note or "").strip(),
    )
    manifest = _read_json(_campaign_manifest_path(operator_root, directive_id))
    target_quality = dict(dict(manifest.get("canonical_artifacts", {}) or {}).get(target_artifact, {}) or {})
    effective_feedback = _campaign_artifact_guidance(
        target_artifact,
        fallback=str(feedback or operator_note or "").strip(),
        directive=directive,
        failed_gates=list(target_quality.get("failed_quality_gates", []) or []),
    )
    directive["operator_clarifications"] = list(by_id.values())
    directive["operator_feedback"] = effective_feedback
    directive["state"] = "requeued"
    directive["active_child_run_id"] = ""
    directive["updated_at"] = now
    _write_json(_directive_path(operator_root, directive_id), directive)
    packet["operator_clarifications_resolved"] = resolved_records
    packet["operator_feedback"] = effective_feedback
    packet["review_state"] = "requeued"
    packet["reviewed_at"] = now
    _write_json(_return_path(operator_root, return_packet_id), packet)
    decision["operator_clarifications"] = resolved_records
    decision["clarification_count"] = len(resolved_records)
    _append_ledger(
        operator_root,
        "directive_events",
        {
            "event": "clarification_requeued",
            "generated_at": now,
            "directive_id": directive_id,
            "return_packet_id": return_packet_id,
            "clarification_count": len(resolved_records),
        },
    )
    _reset_continuous_campaign_context(
        operator_root,
        directive_id,
        reason="operator_clarification_requeue",
        action="operator_clarify_requeue",
        return_packet_id=return_packet_id,
        feedback=effective_feedback,
        target_artifact=target_artifact,
    )
    return decision


