def apply_directive_feedback(
    operator_root: str | Path,
    *,
    directive_id: str,
    feedback: str,
) -> dict[str, Any]:
    directive = _load_directive(operator_root, directive_id)
    now = _utc_now()
    target_artifact = _operator_requeue_target_artifact(
        operator_root,
        directive=directive,
        feedback=str(feedback or ""),
    )
    manifest = _read_json(_campaign_manifest_path(operator_root, directive_id))
    target_quality = dict(dict(manifest.get("canonical_artifacts", {}) or {}).get(target_artifact, {}) or {})
    effective_feedback = _campaign_artifact_guidance(
        target_artifact,
        fallback=str(feedback or ""),
        directive=directive,
        failed_gates=list(target_quality.get("failed_quality_gates", []) or []),
    )
    directive["state"] = "requeued"
    directive["operator_feedback"] = effective_feedback
    directive["active_child_run_id"] = ""
    directive["requeue_count"] = int(directive.get("requeue_count", 0) or 0) + 1
    directive["updated_at"] = now
    _write_json(_directive_path(operator_root, directive_id), directive)
    _append_ledger(
        operator_root,
        "directive_events",
        {"event": "feedback_requeued", "generated_at": now, "directive_id": directive_id},
    )
    return _reset_continuous_campaign_context(
        operator_root,
        directive,
        reason="operator_directive_feedback",
        action="directive_feedback_requeue",
        feedback=effective_feedback,
        target_artifact=target_artifact,
    ) or directive


def control_child_run(
    operator_root: str | Path,
    *,
    child_run_id: str,
    action: str,
    runner: ConveyorChildRunner | None = None,
) -> dict[str, Any]:
    child = _load_child(operator_root, child_run_id)
    normalized = str(action or "").strip().lower()
    if normalized not in {"pause", "stop"}:
        raise ConveyorValidationError("action must be pause or stop")
    now = _utc_now()
    if normalized == "stop":
        effective_runner = runner or runner_from_scheduler(_load_scheduler(operator_root))
        stop_result = effective_runner.stop_child_container(child)
        child["stop_result"] = dict(stop_result)
        child["state"] = "stopped" if bool(stop_result.get("ok", False)) else "blocked"
    else:
        child["state"] = "paused"
    child[f"{normalized}_requested"] = True
    child["updated_at"] = now
    _write_json(_child_path(operator_root, child_run_id), child)
    directive_id = str(child.get("directive_id", "") or "").strip()
    if normalized == "stop" and directive_id:
        directive = _read_json(_directive_path(operator_root, directive_id))
        if directive and str(directive.get("active_child_run_id", "") or "") == child_run_id:
            directive["active_child_run_id"] = ""
            directive["state"] = "blocked"
            directive["blocked_reason"] = "active_child_stopped"
            directive["updated_at"] = now
            _write_json(_directive_path(operator_root, directive_id), directive)
    _append_ledger(operator_root, "child_events", {"event": normalized, **child})
    return child


def _write_conveyor_worker_result(result_path: str | Path, payload: Mapping[str, Any]) -> None:
    result = Path(result_path)
    result.parent.mkdir(parents=True, exist_ok=True)
    temp_path = result.with_name(f".{result.name}.{uuid.uuid4().hex}.tmp")
    try:
        temp_path.write_text(json.dumps(dict(payload), indent=2, sort_keys=True) + "\n", encoding="utf-8")
        temp_path.replace(result)
    finally:
        try:
            if temp_path.exists():
                temp_path.unlink()
        except OSError:
            pass


def _conveyor_worker_main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="python -m operator_shell.conveyor")
    parser.add_argument(
        "command",
        choices=("scheduler-pending-return-evaluation", "support-request-auto-approval"),
    )
    parser.add_argument("--operator-root", required=True)
    parser.add_argument("--state-root", required=True)
    parser.add_argument("--result-path", required=True)
    parser.add_argument("--support-request-id", default="")
    args = parser.parse_args(argv)
    try:
        if args.command == "scheduler-pending-return-evaluation":
            result = evaluate_pending_child_returns(
                args.operator_root,
                state_root=args.state_root,
                allow_continuous_support=False,
            )
        elif args.command == "support-request-auto-approval":
            if not str(args.support_request_id or "").strip():
                raise ConveyorValidationError("--support-request-id is required")
            result = approve_conveyor_support_request(
                args.operator_root,
                state_root=args.state_root,
                support_request_id=args.support_request_id,
            )
        else:  # pragma: no cover - argparse choices keep this unreachable.
            raise ConveyorValidationError(f"unknown conveyor worker command: {args.command}")
        _write_conveyor_worker_result(args.result_path, {"ok": True, "result": result})
        return 0
    except Exception as exc:  # pragma: no cover - defensive worker envelope.
        _write_conveyor_worker_result(
            args.result_path,
            {"ok": False, "error_type": type(exc).__name__, "error": str(exc)},
        )
        return 1


if __name__ == "__main__":  # pragma: no cover - exercised through subprocess workers.
    raise SystemExit(_conveyor_worker_main())
